INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-26393','春日飡霞阁','施肩吾','quantangshi','','卷27','洒水初晴物候新，飡霞阁上最宜春。
山花四面风吹入，为我铺牀作锦茵。','',''),('quantangshi-26394','喜友再相逢','施肩吾','quantangshi','','卷27','三十年前与君别，可怜容色夺花红。
谁知日月相催促，此度见君成老翁。','',''),('quantangshi-26395','候仙词','施肩吾','quantangshi','','卷27','西归公子何时降，南岳先生早晚来。
巡历世间犹未遍，乞求鸾鹤且裴回。','',''),('quantangshi-26396','修仙词','施肩吾','quantangshi','','卷27','丹田自种留年药，玄谷长生续命芝。
世上漫忙兼漫走，不知求己更求谁。','',''),('quantangshi-26397','夏日题方师院','施肩吾','quantangshi','','卷27','火天无处买清风，闷发时来入梵宫。
只向方师小廊下，回看门外是樊笼。','',''),('quantangshi-26398','春游乐','施肩吾','quantangshi','','卷27','一年三百六十日，赏心那似春中物。
草迷曲坞花满园，东家少年西家出。','',''),('quantangshi-26399','仙客归乡词二首 一','施肩吾','quantangshi','','卷27','六合八荒游未半，子孙零落暂归来。
井边不认捎云树，多是门人在后栽。','',''),('quantangshi-26400','仙客归乡词二首 二','施肩吾','quantangshi','','卷27','洞中日月洞中仙，不算离家是几年。
出郭始知人代变，又须抛却古时钱。','',''),('quantangshi-26401','云州饮席','施肩吾','quantangshi','','卷27','酒肠虽满少欢情，身在云州望帝城。
巡次合当谁令改，先须为我打还京。','',''),('quantangshi-26402','戏赠李主簿','施肩吾','quantangshi','','卷27','官罢江南客恨遥，二年空被酒中消。
不知暗数春游处，偏忆扬州第几桥。','',''),('quantangshi-26403','春词','施肩吾','quantangshi','','卷27','黄鸟啼多春日高，红芳开尽井边桃。
美人手暖裁衣易，片片轻云落剪刀。','',''),('quantangshi-26404','题景上人山门','施肩吾','quantangshi','','卷27','水有青莲沙有金，老僧于此独观心。
愁人欲寄中峰宿，只恐白猨啼夜深。','',''),('quantangshi-26405','妓人残妆词','施肩吾','quantangshi','','卷27','云髻已收金凤皇，巧匀轻黛约残妆。
不知昨夜新歌响，犹在谁家绕画梁。','',''),('quantangshi-26406','临水亭','施肩吾','quantangshi','','卷27','只怪素亭黏黛色，溪烟为我染莓苔。
欲知源上春风起，看取桃花逐水来。','',''),('quantangshi-26407','听范玄长吟','施肩吾','quantangshi','','卷27','声声扣出碧琅玕，能使秋猨欲呌难。
诗兴未穷心更远，手垂青拂向云看。','',''),('quantangshi-26408','观叶生画花','施肩吾','quantangshi','','卷27','心窍玲珑貌亦奇，荣枯只在手中移。
今朝故向霜天里，点破繁花四五枝。','',''),('quantangshi-26409','洗丹沙词','施肩吾','quantangshi','','卷27','千淘万洗紫光攒，夜火荧荧照玉盘。
恐是麻姑残米粒，不曾将与世人看。','',''),('quantangshi-26410','长安春夜吟','施肩吾','quantangshi','','卷27','露盘滴时河汉微，美人灯下裁春衣。
蟾蜍东去鹊南飞，芸香省中郎不归。','',''),('quantangshi-26411','自述','施肩吾','quantangshi','','卷27','箧贮灵砂日日看，欲成仙法脱身难。
不知谁向交州去，为谢罗浮葛长官。','',''),('quantangshi-26412','少年行','施肩吾','quantangshi','','卷27','醉骑白马走空衢，恶少皆称电不如。
五凤街头新勒辔，半垂衫袖揖金吾。','',''),('quantangshi-26413','越中遇寒食','施肩吾','quantangshi','','卷27','去岁清明霅溪口，今朝寒食镜湖西。
信知天地心不易，还有子规依旧啼。','',''),('quantangshi-26414','赠采药叟','施肩吾','quantangshi','','卷27','老去唯将药裹行，无家无累一身轻。
却教年少取书卷，小字灯前鬬眼明。','',''),('quantangshi-26415','清夜忆仙宫子','施肩吾','quantangshi','','卷27','夜静门深紫洞烟，孤行独坐忆神仙。
三清宫里月如昼，十二宫楼何处眠。','',''),('quantangshi-26416','江南怨','施肩吾','quantangshi','','卷27','愁见桥边荇叶新，兰舟枕水楫生尘。
从来不是无莲采，十顷莲塘卖与人。','',''),('quantangshi-26417','送绝尘子归旧隐二首 一','施肩吾','quantangshi','','卷27','云水千重绕洞门，独归何处是桃源？仙方不用随身去，留与人间老子孙。','',''),('quantangshi-26418','送绝尘子归旧隐二首 二','施肩吾','quantangshi','','卷27','班藤为杖草为衣，万壑千峰独自归。
纵令相忆谁相报，桂树岩边人信稀。','',''),('quantangshi-26419','送裴秀才归淮南','施肩吾','quantangshi','','卷27','怪来频起咏刀头，枫叶枝边一夕秋。
又向江南别才子，却将风景过扬州。','',''),('quantangshi-26420','钱塘渡口','施肩吾','quantangshi','','卷27','天堑茫茫连沃焦，秦皇何事不安桥。
钱塘渡口无钱纳，已失西兴两信潮。','',''),('quantangshi-26421','春日宴徐君池亭','施肩吾','quantangshi','','卷27','暂凭春酒换愁颜，今日应须醉始还。
池上有门君莫掩，从教野客见青山。','',''),('quantangshi-26422','山中送友人','施肩吾','quantangshi','','卷27','欲折杨枝别恨生，一重枝上一啼莺。
乱山重叠云相掩，君向乱山何处行。','',''),('quantangshi-26423','寄王少府','施肩吾','quantangshi','','卷27','采松仙子徒销日，吃菜山僧枉过生。
多谢蓝田王少府，人间诗酒最关情。','',''),('quantangshi-26424','赠女道士郑玉华二首 一','施肩吾','quantangshi','','卷27','玄发新簪碧藕花，欲添肌雪饵红砂。
世间风景那堪恋，长笑刘郎漫忆家。','',''),('quantangshi-26425','赠女道士郑玉华二首 二','施肩吾','quantangshi','','卷27','明镜湖中休采莲，却师阿母学神仙。
朱丝误落青囊里，犹是箜篌第几弦。','',''),('quantangshi-26426','寄西台李侍御','施肩吾','quantangshi','','卷27','二千余里采琼瓌，到处伤心瓦砾堆。
唯有绣衣周柱史，独将珠玉挂西台。','',''),('quantangshi-26427','赠凌仙姥','施肩吾','quantangshi','','卷27','阿母从天降几时，前朝惟有汉皇知。
仙桃不啻三回熟，饱见东方一小儿。','',''),('quantangshi-26428','晚春送王秀才游剡川','施肩吾','quantangshi','','卷27','越山花去剡藤新，才子风光不厌春。
第一莫寻溪上路，可怜仙女爱迷人。','',''),('quantangshi-26429','冯上人院','施肩吾','quantangshi','','卷27','扰扰凡情逐水流，世间多喜复多忧。
一回行到冯公院，便欲令人百事休。','',''),('quantangshi-26430','金吾词','施肩吾','quantangshi','','卷27','行拥朱轮锦幨儿，望仙门外叱金羁。
染须偷嫩无人觉，唯有平康小妇知。','',''),('quantangshi-26431','观舞女','施肩吾','quantangshi','','卷27','缠红结紫畏风吹，袅娜初回弱柳枝。
买笑未知谁是主，万人心逐一人移。','',''),('quantangshi-26432','鄠县村居','施肩吾','quantangshi','','卷27','欲住村西日日慵，上山无水引高踪。
谁能求得秦皇术，为我先驱紫阁峰。','',''),('quantangshi-26433','酬周秀才','施肩吾','quantangshi','','卷27','三展蜀牋皆郢曲，我心珍重甚琼瑶。
应缘水府龙神睡，偷得蛟人五色绡。','',''),('quantangshi-26434','旅次文水县喜遇李少府','施肩吾','quantangshi','','卷27','为君三日废行程，一县官人是酒朋。
共忆襄阳同醉处，尚书坐上纳银觥。','',''),('quantangshi-26435','夏雨后题青荷兰若','施肩吾','quantangshi','','卷27','僧舍清凉竹树新，初经一雨洗诸尘。
微风忽起吹莲叶，青玉盘中泻水银。','',''),('quantangshi-26436','途中逢少女','施肩吾','quantangshi','','卷27','身倚西门笑向东，牡丹初折一枝红。
市头日卖千般镜，知落谁家新匣中。','',''),('quantangshi-26437','山中翫白鹿','施肩吾','quantangshi','','卷27','绕洞寻花日易销，人间无路得相招。
呦呦白鹿毛如雪，踏我桃花过石桥。','',''),('quantangshi-26438','山居乐','施肩吾','quantangshi','','卷27','鸾鹤每于松下见，笙歌常向坐中闻。
手持十节龙头杖，不指虚空即指云。','',''),('quantangshi-26439','襄阳曲','施肩吾','quantangshi','','卷27','大堤女儿郎莫寻，三三五五结同心。
清晨对镜理容色，意欲取郎千万金。','',''),('quantangshi-26440','望夫词二首 一','施肩吾','quantangshi','','卷27','看看北雁又南飞，薄幸征夫久不归。
蟢子到头无信处，凡经几度上人衣。','',''),('quantangshi-26441','望夫词二首 二','施肩吾','quantangshi','','卷27','何事经年断书信，愁闻远客说风波。
西家还有望夫伴，一种泪痕儿最多。','',''),('quantangshi-26442','少妇游春词','施肩吾','quantangshi','','卷27','簇锦攒花鬬胜游，万人行处最风流。
无端自向春园里，笑摘青梅呌阿侯。','',''),('quantangshi-26443','折柳枝','施肩吾','quantangshi','','卷27','伤见路边杨柳春，一重折尽一重新。
今年还折去年处，不送去年离别人。','',''),('quantangshi-26444','归将吟','施肩吾','quantangshi','','卷27','百战放归成老翁，余生得出死人中。
今朝授敕三回舞，两赐青娥又拜公。','',''),('quantangshi-26445','惜花词','施肩吾','quantangshi','','卷27','千树繁红遶碧泉，正宜尊酒对芳年。
明朝欲饮还来此，只怕春风却在前。','',''),('quantangshi-26446','抛缠头词','施肩吾','quantangshi','','卷27','翠娥初罢绕梁词，又见双鬟对舞时。
一抱红罗分不足，参差裂破凤皇儿。','',''),('quantangshi-26447','望骑马郎','施肩吾','quantangshi','','卷27','碧蹄新压步初成，玉色郎君弄影行。
