路逢邻妇遥相问，小小如今学养蚕。','',''),('quantangshi-26449','春日钱塘杂兴二首 二','施肩吾','quantangshi','','卷27','西邻年少问东邻，柳岸花堤几处新。
昨夜雨多春水阔，隔江桃叶唤何人。','',''),('quantangshi-26450','翫手植松','施肩吾','quantangshi','','卷27','却思毫末栽松处，青翠才将众草分。
今日散材遮不得，看看气色欲凌云。','',''),('quantangshi-26451','夜笛词','施肩吾','quantangshi','','卷27','皎洁西楼月未斜，笛声寥亮入东家。
却令灯下裁衣妇，误翦同心一半花。','',''),('quantangshi-26452','赠郑伦吹凤管','施肩吾','quantangshi','','卷27','喃喃解语凤皇儿，曾听棃园竹里吹。
谁谓五陵年少子，还将此曲暗相随。','',''),('quantangshi-26453','蜀茗词','施肩吾','quantangshi','','卷27','越椀初盛蜀茗新，薄烟轻处搅来匀。
山僧问我将何比，欲道琼浆却畏嗔。','',''),('quantangshi-26454','春霁','施肩吾','quantangshi','','卷27','煎茶水里花千片，候客亭中酒一樽。
独对春光还寂寞，罗浮道士忽敲门。','',''),('quantangshi-26455','讽山云','施肩吾','quantangshi','','卷27','闲云生叶不生根，常被重重蔽石门。
赖有风帘能埽荡，满山晴日照干坤。','',''),('quantangshi-26456','日晚归山词','施肩吾','quantangshi','','卷27','虎迹新逢雨后泥，无人家处洞边溪。
独行归客晚山里，赖有鹧鸪临路岐。','',''),('quantangshi-26457','翫花词','施肩吾','quantangshi','','卷27','今朝造化使春风，开拆西施面上红。
竟日眼前犹不足，数株舁入寸心中。','',''),('quantangshi-26458','长安早春','施肩吾','quantangshi','','卷27','报花消息是春风，未见先教何处红。
想得芳园十余日，万家身在画屏中。','',''),('quantangshi-26459','再酬李先辈','施肩吾','quantangshi','','卷27','清辞再发郢人家，字字新移锦上花。
能使龙宫买绡女，低回不敢织轻霞。','',''),('quantangshi-26460','寄隐者','施肩吾','quantangshi','','卷27','路绝空林无处问，幽奇山水不知名。
松门拾得一片屐，知是高人向此行。','',''),('quantangshi-26461','寄四明山子','施肩吾','quantangshi','','卷27','高栖只在千峰里，尘世望君那得知。
长忆去年风雨夜，向君窗下听猨时。','',''),('quantangshi-26462','观美人','施肩吾','quantangshi','','卷27','漆点双眸鬓绕蝉，长留白雪占胸前。
爱将红袖遮娇笑，往往偷开水上莲。','',''),('quantangshi-26463','收妆词','施肩吾','quantangshi','','卷27','斜月胧胧照半牀，茕茕孤妾嬾收妆。
灯前再览青铜镜，枉插金钗十二行。','',''),('quantangshi-26464','仙女词','施肩吾','quantangshi','','卷27','仙女羣中名最高，曾看王母种仙桃。
手题金简非凡笔，道是天边玉兔毛。','',''),('quantangshi-26465','仙翁词','施肩吾','quantangshi','','卷27','世间无远可为游，六合朝行夕已周。
坛上夜深风雨静，小仙乘月系苍虬。','',''),('quantangshi-26466','遇李山人','施肩吾','quantangshi','','卷27','游山游水几千重，二十年中一度逢。
别易会难君且住，莫交青竹化为龙。','',''),('quantangshi-26467','同张炼师溪行','施肩吾','quantangshi','','卷27','青溪道士紫霞巾，洞里仙家旧是邻。
