归去不论无旧识，子孙今亦是他人。','',''),('quantangshi-26469','桃源词二首 二','施肩吾','quantangshi','','卷27','秦世老翁归汉世，还同白鹤返辽城。
纵令记得山川路，莫问当时州县名。','',''),('quantangshi-26470','送道友游山','施肩吾','quantangshi','','卷27','欲驻如今未老形，万重山上九芝清。
君今若问采芝路，踏水踏云攀杳冥。','',''),('quantangshi-26471','赠王屋刘道士','施肩吾','quantangshi','','卷27','小有洞中长住客，大罗天下后来仙。
