如花年少一女子，身骑白鹤游青天。','',''),('quantangshi-26473','秋吟献李舍人','施肩吾','quantangshi','','卷27','肠结愁根酒不消，新惊白发长愁苗。
主司傥许题名姓，笔下看成度海桥。','',''),('quantangshi-26474','山中喜静和子见访','施肩吾','quantangshi','','卷27','绝壁深溪无四邻，每逢猨鹤即相亲。
小奴惊出垂藤下，山犬今朝吠一人。','',''),('quantangshi-26475','春日题罗处士山舍','施肩吾','quantangshi','','卷27','乱叠千峰掩翠微，高人爱此自忘机。
春风若埽阶前地，便是山花带锦飞。','',''),('quantangshi-26476','访松岭徐炼师','施肩吾','quantangshi','','卷27','千仞峰头一谪仙，何时种玉已成田？开经犹在松阴里，读到南华第几篇。','',''),('quantangshi-26477','江南织绫词','施肩吾','quantangshi','','卷27','卿卿买得越人丝，贪弄金梭嬾画眉。
女伴能来看新𥷨，鸳鸯正欲上花枝。','',''),('quantangshi-26478','宿兰若','施肩吾','quantangshi','','卷27','听钟投宿入孤烟，岩下病僧犹坐禅。
独夜客心何处是，秋云影里一灯然。','',''),('quantangshi-26479','题禅僧院','施肩吾','quantangshi','','卷27','栖禅枝畔数花新，飞作琉璃池上尘。
谷鸟自啼猨自呌，不能愁得定中人。','',''),('quantangshi-26480','送绝粒僧','施肩吾','quantangshi','','卷27','碧洞青萝不畏深，免将饥渴累禅心。
若期野客来相访，一室无烟何处寻。','',''),('quantangshi-26481','早春游曲江','施肩吾','quantangshi','','卷27','芳处亦将枯槁同，应缘遭化未施功。
羲和若拟动炉鞴，先铸曲江千树红。','',''),('quantangshi-26482','佳人览镜','施肩吾','quantangshi','','卷27','每坐台前见玉容，今朝不与昨朝同。
良人一夜出门宿，减却桃花一半红。','',''),('quantangshi-26483','遇王山人','施肩吾','quantangshi','','卷27','每欲寻君千万峰，岂知人世也相逢。
一瓢遗却在何处，应挂天台最老松。','',''),('quantangshi-26484','遇醉道士','施肩吾','quantangshi','','卷27','霞帔寻常带酒眠，路傍疑是酒中仙。
醉来不住人家宿，多向远山松月边。','',''),('quantangshi-26485','送人归台州','施肩吾','quantangshi','','卷27','莫驱归骑且徘徊，更遣离情四五杯。
醉后不忧迷客路，遥看瀑布识天台。','',''),('quantangshi-26486','赠施仙姑','施肩吾','quantangshi','','卷27','缥缈吾家一女仙，冰容虽小不知年。
有时频夜看明月，心在嫦娥几案边。','',''),('quantangshi-26487','山院观花','施肩吾','quantangshi','','卷27','初来唯见空树枝，今朝满院花如雪。
门前为报诸少年，明日来迟不堪折。','',''),('quantangshi-26488','经桃花夫人庙','施肩吾','quantangshi','','卷27','谁能枉驾入荒榛，随例形相土木身。
不及连山种桃树，花开犹得识夫人。','',''),('quantangshi-26489','代农叟吟','施肩吾','quantangshi','','卷27','且将一笑悦丰年，渐老那能日日眠。
引客特来山地上，坐看秋水落红莲。','',''),('quantangshi-26490','下第春游','施肩吾','quantangshi','','卷27','羁情含蘖复含辛，泪眼看花只似尘。
天遣春风领春色，不教分付与愁人。','',''),('quantangshi-26491','送僧游越','施肩吾','quantangshi','','卷27','麻衣年少雪为颜，却笑孤云未是闲。
此去若逢花柳月，栖禅莫向苎萝山。','',''),('quantangshi-26492','遇越州贺仲宣','施肩吾','quantangshi','','卷27','君在镜湖西畔住，四明山下莫经春。
门前几个采莲女，欲泊莲舟无主人。','',''),('quantangshi-26493','江南积雨叹','施肩吾','quantangshi','','卷27','人厌为霖水毁溪，牀边生菌路成泥。
雨师一日三回到，栋里闲云岂得栖。','',''),('quantangshi-26494','云中道上作','施肩吾','quantangshi','','卷27','羊马羣中觅人道，雁门关外绝人家。
昔时闻有云中郡，今日无云空见沙。','',''),('quantangshi-26495','同诸隐者夜登四明山','施肩吾','quantangshi','','卷27','半夜寻幽上四明，手攀松桂触云行。
相呼已到无人境，何处玉箫吹一声。','',''),('quantangshi-26496','戏郑申府','施肩吾','quantangshi','','卷27','年少郑郎那解愁，春来闲卧酒家楼。
胡姬若拟邀他宿，挂却金鞭系紫骝。','',''),('quantangshi-26497','宿干越亭','施肩吾','quantangshi','','卷27','琵琶洲上人行绝，干越亭中客思多。
月满秋江山冷落，不知谁问夜如何。','',''),('quantangshi-26498','少女词二首 一','施肩吾','quantangshi','','卷27','娇羞不肯点新黄，踏过金钿出绣牀。
信物无端寄谁去，等闲裁破锦鸳鸯。','',''),('quantangshi-26499','少女词二首 二','施肩吾','quantangshi','','卷27','同心带里脱金钱，买取头花翠羽连。
手执木兰犹未惯，今朝初上采菱船。','',''),('quantangshi-26500','冬词','施肩吾','quantangshi','','卷27','锦绣堆中卧初起，芙蓉面上粉犹残。
台前也欲梳云髻，只怕盘龙手捻难。','',''),('quantangshi-26501','昭君怨','施肩吾','quantangshi','','卷27','马上徒劳别恨深，总缘如玉不输金。
已知贱妾无归日，空荷君王有悔心。','',''),('quantangshi-26502','赠仙子','施肩吾','quantangshi','','卷27','欲令雪貌带红芳，更取金瓶泻玉浆。
凤管鹤声来未足，嬾眠秋月忆萧郎。','',''),('quantangshi-26503','越溪怀古','施肩吾','quantangshi','','卷27','忆昔西施人未求，浣纱曾向此溪头。
一朝得侍君王侧，不见玉颜空水流。','',''),('quantangshi-26504','秋夜山中赠别友人','施肩吾','quantangshi','','卷27','何处邀君话别情，寒山木落月华清。
莫愁今夜无诗思，已听秋猨第一声。','',''),('quantangshi-26505','大堤新咏','施肩吾','quantangshi','','卷27','行路少年知不知，襄阳全欠旧来时。
宜城贾客载钱出，始觉大堤无女儿。','',''),('quantangshi-26506','宿四明山','施肩吾','quantangshi','','卷27','黎洲老人命余宿，杳然高顶浮云平。
下视不知几千仞，欲晓不晓天鸡声。','',''),('quantangshi-26507','禁中新柳','施肩吾','quantangshi','','卷27','万条金线带春烟，深染青丝不直钱。
又免生当离别地，宫鵶啼处禁门前。','',''),('quantangshi-26508','酬张明府','施肩吾','quantangshi','','卷27','潘令新诗忽寄来，分明绣段对花开。
此时欲醉红楼里，正被歌人劝一杯。','',''),('quantangshi-26509','安吉天宁寺闻磬','施肩吾','quantangshi','','卷27','玉磬敲时清夜分，老龙吟断碧天云。
隣房逢见广州客，曾向罗浮山里闻。','',''),('quantangshi-26510','句','施肩吾','quantangshi','','卷27','年来如抛梭，不老应不得。
花眼绽红斟酒看，药心抽绿带烟锄。
颠狂楚客歌成雪，媚赖吴娘笑是盐。
荷翻紫盖摇波面，蒲莹青刀插水湄。
烟黏薜荔龙须软，雨压芭蕉凤翅垂。
茶为涤烦子，酒为忘忧君。
锄药顾老叟，焚香呼小青。
遗却白鸡呼喌喌。
五通本是佛家奴，身着青衣一足无。
天边有仙药，为我补三关。
世人谁不爱年长，所欲皆非保命方。
但看日及花，惟是朝可怜。
池塘已长鸡头叶，篱落初开狗脊花。
出路船为脚，供官本是奴。
一言感着热铁心，为人剑下偷青娥。
青鬓丈人不识愁。','',''),('quantangshi-26511','不赴拾遗召','費冠卿','quantangshi','','卷27','君亲同是先王道，何如骨肉一处老。
也知臣子合佐时，自古荣华谁可保。','',''),('quantangshi-26512','闲居即事','費冠卿','quantangshi','','卷27','生计唯将三尺僮，学他贤者隐墙东。
照眠夜后多因月，扫地春来祗藉风。
几处红旗驱战士，一园青草伴衰翁。
子房仙去孔明死，更有何人解指踪。','',''),('quantangshi-26513','酬范中丞见','費冠卿','quantangshi','','卷27','花宫柳陌正从行，紫袂金鞍问姓名。
战国方须礼干木，康时何必重侯嬴。
捧将束帛山僮喜，传示银钩邑客惊。
直为云泥相去远，一言知己杀身轻。','',''),('quantangshi-26514','秋日与冷然上人寺庄观稼','費冠卿','quantangshi','','卷27','世人从扰扰，独自爱身闲。
美景当新霁，随僧过远山。
村桥出秋稼，空翠落澄湾。
唯有中林犬，犹应望我还。','',''),('quantangshi-26515','题中峰','費冠卿','quantangshi','','卷27','中峰高拄泬寥天，上有茅庵与石泉。
晴景猎人曾望见，青蓝色里一僧禅。','',''),('quantangshi-26516','蒙召拜拾遗书情二首 一','費冠卿','quantangshi','','卷27','拾遗帝侧知难得，官紧才微恐不胜。
好是中朝绝亲友，九华山下诏来征。','',''),('quantangshi-26517','蒙召拜拾遗书情二首 二','費冠卿','quantangshi','','卷27','三千里外一微臣，二十年来任运身。
今日忽蒙天子召，自慙惊动国中人。','',''),('quantangshi-26518','挂树藤','費冠卿','quantangshi','','卷27','本为独立难，寄彼高树枝。
蔓衍数条远，溟蒙千朵垂。
向日助成阴，当风藉持危。
谁言柔可屈，坐见蟠蛟螭。','',''),('quantangshi-26519','枕流石','費冠卿','quantangshi','','卷27','不为幽岸隐，古色涵空出。
愿以清泚流，鉴此坚贞质。
傍临玉光润，时泻苔花密。
往往惊游鳞，尚疑垂钓日。','',''),('quantangshi-26520','久居京师感怀诗','費冠卿','quantangshi','','卷27','茕独不为苦，求名始辛酸。
上国无交亲，请谒多少难。
九月风到面，羞汗成冰片。
求名俟公道，名与公道远。
力尽得一名，他喜我且轻。
家书十年绝，归去知谁荣。
马嘶渭桥柳，特地起秋声。','',''),('quantangshi-26521','答萧建','費冠卿','quantangshi','','卷27','自地上青峰，悬崖一万重。
践危频侧足，登堑半齐胸。
飞狖啼攀桂，游人喘倚松。
入林寒㾕㾕，近瀑雨蒙蒙。
径滑石棱上，寺开山掌中。
幡花扑净地，台殿印晴空。
胜境层层别，高僧院院逢。
泉鱼候洗钵，老玃戏撞钟。
外户凭云掩，中厨课水舂。
搜泥时和麪，拾橡半添穜。
渡壑缘槎险，持灯入洞穷。
夹天开壁峭，透石蹙波雄。
涧蔼清无土，潭深碧有龙。
畲田一片净，谷树万株浓。
野客登临惯，山房幽寂同。
寒炉树根火，夏牖竹稍风。
边鄙筹贤相，黔黎托圣躬。
君能弃名利，岁[晏]一相从。','',''),('quantangshi-26522','代书问费征君九华亭','蕭建','quantangshi','','卷27','见说九华峰上寺，日宫犹在下方开。
其中幽境客难到，请为诗中图画来。','',''),('quantangshi-26523','献主文','劉虛白','quantangshi','','卷27','二十年前此夜中，一般灯烛一般风。
不知岁月能多少，犹着麻衣待至公。','',''),('quantangshi-26524','句','劉虛白','quantangshi','','卷27','知道醉乡无户税，任他荒却下丹田。','',''),('quantangshi-26525','山出云','張復','quantangshi','','卷27','山静云初吐，霏微触石新。
无心离碧岫，有叶占青春。
散类如虹气，轻同不让尘。
凌空还似翼，映涧欲成鳞。
异起临汾鼎，疑随出峡神。
为霖终济旱，非独降贤人。','',''),('quantangshi-26526','山出云','張勝之','quantangshi','','卷27','片云初出岫，孤迥色难亲。
盖小辞山近，根轻触石新。
飘颻经绿野，明丽照晴春。
拂树疑舒叶，临流似结鳞。
从龙方有感，捧日岂无因。
看取为霖去，恩霑雨露均。','',''),('quantangshi-26527','送狄尚书镇太原','姚合','quantangshi','','卷27','授钺儒生贵，倾朝赴饯筵。
麾幢官在省，礼乐将临边。
代马龙相杂，汾河海暗连。
远戎移帐幕，高鸟避旌旃。
天下屯兵处，皇威破虏年。
防秋嫌垒近，入塞必身先。
中外恩重叠，科名岁接连。
散材无所用，老向琐闱眠。','',''),('quantangshi-26528','送杨尚书祭西岳','姚合','quantangshi','','卷27','报功严祀典，宠诏下明庭。
酒气飘林岭，香烟入杳冥。
乐清三奏备，词直百神听。
衣拂云霞湿，诗通水石灵。
何因逐驺骑，暂得到岩扃。','',''),('quantangshi-26529','送李侍御过夏州','姚合','quantangshi','','卷27','酬恩不顾名，走马觉身轻。
迢递河边路，苍茫塞上城。
沙寒无宿雁，虏近少闲兵。
饮罢挥鞭去，旁人意气生。','',''),('quantangshi-26530','送李起居赴池州','姚合','quantangshi','','卷27','天子念疲民，分忧辍侍臣。
红旗高起焰，绿野静无尘。
阙下亲知别，江南惠化新。
朝昏即千里，且愿话逡巡。','',''),('quantangshi-26531','送刘詹事赴寿州','姚合','quantangshi','','卷27','殷勤莫遽起，四坐悉同袍。
世上诗难得，林中酒更高。
隋堤傍杨柳，楚驿在波涛。
别后书频寄，无辞费笔毫。','',''),('quantangshi-26532','送裴大夫赴亳州','姚合','quantangshi','','卷27','杭人遮道路，垂泣浙江前。
谯国迎舟舰，行歌汴水边。
周旋君量远，交代我才偏。
寒日严旌戟，晴风出管弦。
一杯诚淡薄，四坐愿留连。
异政承殊泽，应为天下先。','',''),('quantangshi-26533','送徐州韦仅行军','姚合','quantangshi','','卷27','饯幕俨征轩，行军归大藩。
山程度函谷，水驿到夷门。
晓日诗情远，春风酒色浑。
逡巡何足贵，所贵尽残罇。','',''),('quantangshi-26534','送刘禹锡郎中赴苏州 一','姚合','quantangshi','','卷27','三十年来天下名，衔恩东守阖闾城。
初经咸谷眠山驿，渐入梁园问水程。
霁日满江寒浪静，春风遶郭白苹生。
虎丘野寺吴中少，谁伴吟诗月里行。','',''),('quantangshi-26535','送刘禹锡郎中赴苏州 二','姚合','quantangshi','','卷27','州城全是故吴宫，香径难寻古藓中。
云水计程千里远，轩车送别九衢空。
鹤声高下听无尽，潮色朝昏望不同。
太守吟诗人自理，小斋闲卧白苹风。','',''),('quantangshi-26536','送贾謩赴共城营田','姚合','quantangshi','','卷27','上国羞长选，戎装贵所从。
山田依法种，兵食及时供。
水气诗书软，岚烟笔砚浓。
几时无事扰，相见得从容。','',''),('quantangshi-26537','送裴宰君','姚合','quantangshi','','卷27','见说为官处，烟霞思不穷。
夜猿啼户外，瀑水落厨中。
名药人难识，仙山路易通。
还应施静化，谁复与君同。','',''),('quantangshi-26538','送顾非熊下第归越','姚合','quantangshi','','卷27','失意寻归路，亲知不复过。
家山去城远，日月在船多。
楚塞数逢雁，浙江长有波。
秋风别乡老，还听鹿鸣歌。','',''),('quantangshi-26539','送雍陶游蜀','姚合','quantangshi','','卷27','春色三千里，愁人意未开。
木梢穿栈出，雨势隔江来。
荒馆因花宿，深山羡客回。
相如何物在，应只有琴台。','',''),('quantangshi-26540','送崔约下第归扬州','姚合','quantangshi','','卷27','满座诗人吟送酒，离城此会亦应稀。
春风下第时称屈，秋卷呈亲自束归。
日晚山花当马落，天阴水鸟傍船飞。
江边道路多苔藓，尘土无由得上衣。','',''),('quantangshi-26541','送李廓侍御赴西川行营','姚合','quantangshi','','卷27','不道弓箭字，罢官唯醉眠。
何人荐筹策，走马逐旌旃。
阵变孤虚外，功成语笑前。
从今巂州路，无复有烽烟。','',''),('quantangshi-26542','送杨尚书赴东川','姚合','quantangshi','','卷27','郤縠诗书将，衔恩赴梓州。
遶身垂印绶，护马执戈矛。
劒阁和铭峭，巴江带字流。
从来皆惜别，此别复何愁。','',''),('quantangshi-26543','送邢郎中赴太原','姚合','quantangshi','','卷27','上将得良策，恩威作长城。
如今并州北，不见有胡兵。
晋野雨初足，汾河波亦清。
所从古无比，意气送君行。','',''),('quantangshi-26544','送裴中丞赴华州','姚合','quantangshi','','卷27','我梦何曾应，看君渡浐川。
自无仙掌分，非是圣心偏。
径草多生药，庭花半落泉。
人间有此郡，况在凤城边。','',''),('quantangshi-26545','送徐员外赴河中从事','姚合','quantangshi','','卷27','赤府从军美，儒衣结束轻。
凉飙下山寺，晓浪满关城。
闲坐饶诗景，高眠长道情。
将军不战术，计日立功名。','',''),('quantangshi-26546','送殷尧藩侍御赴同州','姚合','quantangshi','','卷27','吟诗掷酒船，仙掌白楼前。
从事关中贵，主人天下贤。
此生无了日，终岁踏离筵。
何计因归去，深山恣意眠。','',''),('quantangshi-26547','送崔中丞赴郑州','姚合','quantangshi','','卷27','仆射陂前郡，清高越四隣。
丹霄凤诏下，太守虎符新。
雾湿关城月，花香驿路尘。
连枝相庭树，岁岁一家春。','',''),('quantangshi-26548','送丁端公赴河阴','姚合','quantangshi','','卷27','炎天木叶焦，晓夕绝凉飙。
念子独归县，何人不在朝。
市连风浪动，帆彻海门遥。
饮尽樽中酒，同年同寂寥。','',''),('quantangshi-26549','送郑尚书赴兴元','姚合','quantangshi','','卷27','儒有登坛贵，何人得此功。
红旗烧密雪，白马踏长风。
斧钺来天上，诗书理汉中。
方知百胜略，应不在弯弓。','',''),('quantangshi-26550','送田使君赴蔡州','姚合','quantangshi','','卷27','长年离别情，百盏酒须倾。
诗外应无思，人间半是行。
路遥嘶白马，林断出红旌。
功业今应立，淮西有劲兵。','',''),('quantangshi-26551','送无可上人游边','姚合','quantangshi','','卷27','一钵与三衣，经行远近随。
出家还养母，持律复能诗。
春雪离京厚，晨钟近塞迟。
亦知莲府客，夜坐喜同师。','',''),('quantangshi-26552','送僧 一','姚合','quantangshi','','卷27','人间扰扰唯闲事，自见高人只有诗。
寂寞嵩峰云外寺，常多梦里过斋时。','',''),('quantangshi-26553','送僧 二','姚合','quantangshi','','卷27','城中听得新经论，却过关东说向人。
旧国门徒终日望，见时应是见真身。','',''),('quantangshi-26554','送宋慎言','姚合','quantangshi','','卷27','童穉便知闻，如今祗有君。
百篇诗尽和，一盏酒须分。
驿路多连水，州城半在云。
离情同落叶，向晚更纷纷。','',''),('quantangshi-26555','送家兄赴任昭义','姚合','quantangshi','','卷27','早得白眉名，之官濠上城。
别离浮世事，迢遰长年情。
广陌垂花影，遥林起雨声。
出关春草长，过汴夏云生。
黠吏先潜去，疲人相次迎。
宴余和酒拜，魂梦共东行。','',''),('quantangshi-26556','送崔玄亮赴果州冬夜宴韩卿宅','姚合','quantangshi','','卷27','兰烛照重茵，飞杯复几分。
主人寒不寐，上客晓离羣。
骑吏缘青壁，旌旗度白云。
劒铭生藓色，巴字叠冰文。
华省思仙侣，疲民爱使君。
泠泠唯自适，郡邸有谁闻。','',''),('quantangshi-26557','送喻凫校书归毗陵','姚合','quantangshi','','卷27','主人庭叶黑，诗稿更谁书。
阙下科名出，乡中赋籍除。
山春烟树众，江远晚帆疎。
吾亦家吴者，无因到弊庐。','',''),('quantangshi-26558','送董正字武归常州觐亲','姚合','quantangshi','','卷27','路岐知不尽，离别自无穷。
行客心方切，主人罇未空。
楚樯收月下，江树在潮中。
人各还家去，还家庆不同。','',''),('quantangshi-26559','送萧正字往蔡州贺裴相淮西平','姚合','quantangshi','','卷27','相府旌旄重，还邀上客行。
今朝郭门路，初彻蔡州城。
从马唯提酒，防身不要兵。
从来皆作使，君去是时平。','',''),('quantangshi-26560','送进士田卓入华山','姚合','quantangshi','','卷27','何物随身去，六经与一琴。
辞家计已久，入谷住应深。
偶坐僧同石，闲书叶满林。
业成须谒帝，无贮白云心。','',''),('quantangshi-26561','送右司薛员外赴处州','姚合','quantangshi','','卷27','怀中天子书，腰下使君鱼。
瀑布和云落，仙都与世疎。
远程兼水陆，半岁在舟车。
相送难相别，南风入夏初。','',''),('quantangshi-26562','送王建秘书往渭南庄','姚合','quantangshi','','卷27','白须芸阁吏，羸马月中行。
庄僻难寻路，官闲易出城。
看山多失饭，过寺故题名。
秋日田家作，唯添集卷成。','',''),('quantangshi-26563','送殷尧藩侍御游山南','姚合','quantangshi','','卷27','诗境西南好，秋深昼夜蛩。
人家连水影，驿路在山峰。
谷静云生石，天寒雪覆松。
我为公府系，不得此相从。','',''),('quantangshi-26564','送李植侍御','姚合','quantangshi','','卷27','圣代无邪触，空林獬豸归。
谁知陇山鸟，长绕玉楼飞。
风雨依山急，云泉入郭微。
无同昔年别，别后寄书稀。','',''),('quantangshi-26565','送王澹','姚合','quantangshi','','卷27','常省为官处，门前数树松。
寻山屐费齿，书石笔无锋。
果熟猿偷乱，花繁鸟语重。
今来为客去，惜取最高峰。','',''),('quantangshi-26566','送崔之仁','姚合','quantangshi','','卷27','欲出还成住，前程甚谪迁。
佯眠随客醉，愁坐似僧禅。
旧国归何处，春山买欠钱。
几时无一事，长在故人边。','',''),('quantangshi-26567','送孙山人','姚合','quantangshi','','卷27','山翁来帝里，不肯住多时。
尘土衣裳重，腥膻仆隶饥。
林中愁不到，城外老应迟。
喧寂一为别，相逢未有期。','',''),('quantangshi-26568','送费骧','姚合','quantangshi','','卷27','兄寒弟亦饥，力学少闲时。
何路免为客，无门卖得诗。
几人携酒送，独我入山迟。
少小同居止，今朝始别离。','',''),('quantangshi-26569','送河中杨少府宴崔驸马宅','姚合','quantangshi','','卷27','凤凰楼下醉醺醺，晚出东门蝉渐闻。
不使乡人治驿路，却将家累宿山云。
闲时采药随僧去，每月请钱共客分。
县吏若非三载满，自知无计更寻君。','',''),('quantangshi-26570','送文着上人游越','姚合','quantangshi','','卷27','水石随缘岂计程，东吴相遇别西京。
夜禅月下袈裟湿，晓上山巅锡杖鸣。
念我为官应易老，羡师依佛学无生。
越中多有前朝寺，处处铁钟石磬声。','',''),('quantangshi-26571','送无可上人游越','姚合','quantangshi','','卷27','清晨相访立门前，麻履方袍一少年。
嬾读经文求作佛，愿攻诗句觅升仙。
芳春山影花连寺，独夜潮声月满船。
今日送行偏惜别，共师文字有因缘。','',''),('quantangshi-26572','送洛阳张员外','姚合','quantangshi','','卷27','饯客未归城，东来驺骑迎。
千山嵩岳峭，百县洛阳清。
朔雁和云度，川风吹雨晴。
藓庭公事暇，应祗独吟行。','',''),('quantangshi-26573','送少府田中丞入西藩','姚合','quantangshi','','卷27','萧关路绝久，石堠亦为尘。
护塞空兵帐，和戎在使臣。
风沙去国远，雨雪换衣频。
若问凉州事，凉州多汉人。','',''),('quantangshi-26574','送王龟处士','姚合','quantangshi','','卷27','送客客为谁，朱门处士稀。
唯修曾子行，不着老莱衣。
古寺随僧饭，空林共鸟归。
壶中驻年药，烧得献庭闱。','',''),('quantangshi-26575','送崔郎中赴常州','姚合','quantangshi','','卷27','贵是鸰原在紫微，荣逢知己领黄扉。
人间盛事今全得，江上政声复欲归。
风起满城山果落，雨余穿宅水禽飞。
昔年尝作毗陵客，石峭泉清天下稀。','',''),('quantangshi-26576','送林使君赴邵州','姚合','quantangshi','','卷27','诏书飞下五云间，才子分符不等闲。
驿路算程多是水，州图管地少于山。
江头斑竹寻应遍，洞里丹砂自采还。
清净化人人自理，终朝无事更相关。','',''),('quantangshi-26577','送别友人','姚合','quantangshi','','卷27','独向山中觅紫芝，山人勾引住多时。
摘花浸酒春愁尽，烧竹煎茶夜卧迟。
泉落林梢多碎滴，松生石底足旁枝。
明朝却欲归城市，问我来期总不知。','',''),('quantangshi-26578','送李琮归灵州觐省','姚合','quantangshi','','卷27','饯席离人起，贪程醉不眠。
风沙移道路，仆马识山川。
塞树花开小，关城雪下偏。
胡尘今已尽，应便促朝天。','',''),('quantangshi-26579','送任畹评事赴沂海','姚合','quantangshi','','卷27','掷笔不作尉，戎衣从嫖姚。
严冬入都门，仆马气益豪。
沂州右镇雄，士勇旌旗高。
洛东无忧虞，半夜开虎牢。
丈夫贵功勋，不贵爵禄饶。
仰眠作书生，衣食何由销。
任生非常才，临事胆不摇。
必当展长画，逆波斩鲸鳌。
九陌尘土黑，话别立远郊。
孟坚勒燕然，岂独在汉朝。','',''),('quantangshi-26580','送李余及第归蜀','姚合','quantangshi','','卷27','蜀山高岧嶤，蜀客无平才。
日饮锦江水，文章盈其怀。
十年作贡宾，九年多邅回。
春来登高科，升天得梯阶。
手持冬集书，还家献庭闱。
人生此为荣，得如君者稀。
李白蜀道难，羞为无成归。
子今称意行，所历安觉危。
与子久相从，今朝忽乖离。
风飘海中船，会合难自期。
长安米价高，伊我常渴饥。
临岐歌送子，无声但陈词。
义交外不亲，利交内相违。
勉子慎其道，急若食与衣。
苦爇道路赤，行人念前驰。
一杯不可轻，远别方自兹。','',''),('quantangshi-26581','送饶州张使君','姚合','quantangshi','','卷27','鄱阳胜事闻难比，千里连连是稻畦。
山寺去时通水路，郡图开处是诗题。
化行应免农人困，庭静惟多野鹤栖。
饮罢春明门外别，萧条驿路夕阳低。','',''),('quantangshi-26582','送张宗原','姚合','quantangshi','','卷27','东门送客道，春色如死灰。
一客失意行，十客颜色低。
住者既无家，去者又非归。
穷愁一成疾，百药不可治。
子贤我且愚，命分不合齐。
谁开蹇踬门，日日同游栖。
子行何所之，切切食与衣。
谁能买仁义，令子无寒饥。
野田不生草，四向生路岐。
士人甚商贾，终日须东西。
鸿雁春北去，秋风复南飞。
勉君向前路，无失相见期。','',''),('quantangshi-26583','送王求','姚合','quantangshi','','卷27','士有经世筹，自无活身策。
求食道路间，劳困甚徒役。
我身与子同，日被饥寒迫。
侧望卿相门，难入坚如石。
为农昧耕耘，作商迷贸易。
空把书卷行，投人买罪责。
六月南风多，苦旱土色赤。
坐家心尚焦，况乃远作客。
羸马出郭门，饯饮晓连夕。
愿君似醉肠，莫谩生忧戚。','',''),('quantangshi-26584','送朱庆余及第后归越','姚合','quantangshi','','卷27','劝君缓上车，乡里有吾庐。
未得同归去，空令相见疎。
山晴栖鹤起，天晓落潮初。
此庆将谁比，献亲冬集书。','',''),('quantangshi-26585','送朱庆余越州归觐','姚合','quantangshi','','卷27','乡书落姓名，太守拜亲荣。
访我波涛郡，还家雾雨城。
海山窗外近，镜水世间清。
何计随君去，邻墙过此生。','',''),('quantangshi-26586','送任尊师归蜀觐亲','姚合','quantangshi','','卷27','白云修道者，归去春风前。
玉简通仙籍，金丹驻母年。
锦文江一色，酒气雨相连。
众说君平死，真师易义全。','',''),('quantangshi-26587','送友人游蜀','姚合','quantangshi','','卷27','送君一壶酒，相别野庭边。
马上过秋色，舟中到锦川。
峡猿啼夜雨，蜀鸟噪晨烟。
莫便不回首，风光促几年。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-26588','送杜立归蜀','姚合','quantangshi','','卷27','迢递三千里，西南是去程。
杜陵家已尽，蜀国客重行。
雪照巴江色，风吹栈阁声。
马嘶山稍暖，人语店初明。
旅梦心多感，孤吟气不平。
谁为李白后，为访锦官城。','',''),('quantangshi-26589','送韩湘赴江西从事','姚合','quantangshi','','卷27','年少登科客，从军诏命新。
行装有兵器，祖席尽诗人。
细雨湘城暮，微风楚水春。
浔阳应足雁，梦泽岂无尘。
猿叫来山顶，潮痕在树身。
从容多暇日，佳句寄须频。','',''),('quantangshi-26590','送潘传秀才归宣州','姚合','quantangshi','','卷27','李白坟三尺，嵯峨万古名。
因君还故里，为我吊先生。
晴日移虹影，空山出鹤声。
老郎闲未得，无计此中行。','',''),('quantangshi-26591','送僧默然','姚合','quantangshi','','卷27','出家侍母前，至孝自通禅。
伏日江头别，秋风樯下眠。
鸟声猿更促，石色树相连。
此路多如此，师行亦有缘。','',''),('quantangshi-26592','送陟遐上人游天台','姚合','quantangshi','','卷27','万叠赤城路，终年游客稀。
朝来送师去，自觉有家非。
石净山光远，云深海色微。
此诗成亦鄙，为我写岩扉。','',''),('quantangshi-26593','送盛秀才赴举','姚合','quantangshi','','卷27','重重吴越浙江潮，刺史何门始得消。
五字州人唯有此，四邻风景合相饶。
橘村篱落香潜度，竹寺虚空翠自飘。
君去九衢须说我，病成疎嬾嬾趋朝。','',''),('quantangshi-26594','送僧贞实归杭州天竺','姚合','quantangshi','','卷27','石桥寺里最清凉，闻说茆庵寄上方。
林外猿声连院磬，月中潮色到禅牀。
他生念我身何在，此世唯师性亦忘。
九陌相逢千里别，青山重叠树苍苍。','',''),('quantangshi-26595','送卢二弟茂才罢举游洛谒新相','姚合','quantangshi','','卷27','踏碎作赋笔，驱车出上京。
离筵俯岐路，四坐半公卿。
守命贫难掷，忧身梦数惊。
今朝赴知己，休咏苦辛行。','',''),('quantangshi-26596','送任畹及第归蜀中觐亲','姚合','quantangshi','','卷27','子规啼欲死，君听固无愁。
阙下声名出，乡中意气游。
东川横劒阁，南斗近刀州。
神圣题前字，千人看不休。','',''),('quantangshi-26597','送杜观罢举东游','姚合','quantangshi','','卷27','秋风离九陌，心事岂云安。
曾是求名苦，当知此去难。
辛勤程自远，寂寞夜多寒。
诗句无人识，应须把劒看。','',''),('quantangshi-26598','送狄兼謩下第归故山','姚合','quantangshi','','卷27','慈恩塔上名，昨日败垂成。
赁舍应无直，居山岂钓声。
半年犹小隐，数日得闲行。
映竹窥猿剧，寻云探鹤情。
爱花高酒户，煮药污茶铛。
莫便多时住，烟霄路在城。','',''),('quantangshi-26599','送源中丞赴新罗','姚合','quantangshi','','卷27','赤墀赐对使殊方，官重霜台紫绶光。
玉节在船清海怪，金函开诏拜夷王。
云晴渐觉山川异，风便那知道路长。
谁得似君将雨露，海东万里洒扶桑。','',''),('quantangshi-26600','送陈倜赴江陵从事','姚合','quantangshi','','卷27','荆州胜事众皆闻，幕下今朝又得君。
才子何须藉科第，男儿终久要功勋。
江村竹树多于草，山路尘埃半是云。
新什定知饶景思，不应一向赋从军。','',''),('quantangshi-26601','送张郎中副使赴泽潞','姚合','quantangshi','','卷27','晓陌事戎装，风流粉署郎。
机筹通变化，除拜出寻常。
地冷饶霜气，山高碍雁行。
应无离别恨，车马自生光。','',''),('quantangshi-26602','送陆畅侍御归扬州','姚合','quantangshi','','卷27','故园偏接近，霅水洞庭边。
归去知何日，相逢各长年。
山川南北路，风雪别离天。
楚色穷冬烧，淮声独夜船。
从军丞相府，谈笑酒杯前。','',''),('quantangshi-26603','送韦瑶校书赴越','姚合','quantangshi','','卷27','寄家临禹穴，乘传出秦关。
霜落橘满地，潮来帆近山。
相门宾益贵，水国事多闲。
晨省高堂后，余欢杯酒间。','',''),('quantangshi-26604','送雍陶及第归觐','姚合','quantangshi','','卷27','献亲冬集书，比橘复何如。
此去关山远，相思笑语疎。
路寻丹壑断，人近白云居。
幽石题名处，凭君亦记余。','',''),('quantangshi-26605','送李秀才赴举','姚合','quantangshi','','卷27','罗刹楼头醉，送君西入京。
秦吴无限地，山水半分程。
海上烟霞湿，关中日月明。
登科旧乡里，当为改嘉名。','',''),('quantangshi-26606','送李传秀才归宣州','姚合','quantangshi','','卷27','谢守青山宅，山孤宅亦平。
池塘无复见，春草野中生。
常日登楼望，今朝送客行。
殷勤拂石壁，为我一书名。','',''),('quantangshi-26607','送元绪上人游商山','姚合','quantangshi','','卷27','万法空门里，师修历几生。
过来心已悟，未到行弥精。
溪寂钟还度，林昏锡独鸣。
朝簪抽未得，此别岂忘情。','',''),('quantangshi-26608','送僧栖真归杭州天竺寺','姚合','quantangshi','','卷27','吏事日纷然，无因到佛前。
劳师相借问，知我亦通禅。
古寺杉松出，残阳钟磬连。
草庵盘石上，归此是因缘。','',''),('quantangshi-26609','送敬法师归福州','姚合','quantangshi','','卷27','结得随缘伴，蝉鸣方出关。
新经译旧寺，故国与谁还。
斋为无钟早，心因罢讲闲。','',''),('quantangshi-26610','送清敬闍黎归浙西','姚合','quantangshi','','卷27','大地无生理，吴中岂是归。
自翻贝叶偈，人施福田衣。
夏尽滩声出，潮来日色微。
郡斋师去后，寂寞夜吟稀。','',''),('quantangshi-26611','送贾岛及钟浑','姚合','quantangshi','','卷27','日日攻诗亦自彊，年年供应在名场。
春风驿路归何处，紫阁山边是草堂。','',''),('quantangshi-26612','送僧游边','姚合','quantangshi','','卷27','师向边头去，边人业障轻。
腥膻斋自洁，部落讲还成。
传教多离寺，随缘不计程。
三千世界内，何处是无生。','',''),('quantangshi-26613','送澄江上人赴兴元郑尚书招','姚合','quantangshi','','卷27','师经非纸上，师佛在心中。
觉路何曾异，行人自不同。
水云晴亦雨，山木夜多风。
闻结西方社，尚书待远公。','',''),('quantangshi-26614','送马戴下第客游','姚合','quantangshi','','卷27','昨来送君处，亦是九衢中。
此日殷勤别，前时寂寞同。
鸟啼寒食雨，花落暮春风。
向晚离人起，筵收罇未空。','',''),('quantangshi-26615','送薛二十三郎中赴婺州','姚合','quantangshi','','卷27','我住浙江西，君去浙江东。
日日心来往，不畏浙江风。','',''),('quantangshi-26616','送独孤焕评事赴丰州','姚合','quantangshi','','卷27','东门携酒送廷评，结束从军塞上行。
深碛路移唯马觉，断蓬风起与雕平。
烟生远戍侵云色，冰叠黄河长雪声。
须凿燕然山上石，登科记里是闲名。','',''),('quantangshi-26617','送张齐物主簿赴内乡','姚合','quantangshi','','卷27','几年山下事仙翁，名在长生箓籍中。
烧得药成须寄我，曾为主簿与君同。','',''),('quantangshi-26618','送王嗣之典仪城','姚合','quantangshi','','卷27','日日思朝位，偷闲城外行。
唯求采药者，不道在官名。
好异嫌山浅，寻幽喜迳生。
病来文字拙，不要把归城。','',''),('quantangshi-26619','别贾岛','姚合','quantangshi','','卷27','嬾作住山人，贫家日赁身。
书多笔渐重，睡少枕长新。
野客狂无过，诗仙瘦始真。
秋风千里去，谁与我相亲。','',''),('quantangshi-26620','别李余','姚合','quantangshi','','卷27','病童随瘦马，难算往来程。
野寺僧相送，河桥酒滞行。
足愁无道性，久客会人情。
何计羁穷尽，同居不出城。','',''),('quantangshi-26621','别胡逸','姚合','quantangshi','','卷27','记得春闱同席试，逡巡何啻十年余。
今日相逢又相送，予乘五马子单车。','',''),('quantangshi-26622','惜别','姚合','quantangshi','','卷27','酒阑歌罢更迟留，携手思量凭翠楼。
桃李容华犹叹月，风流才器亦悲秋。
光阴不觉朝昏过，岐路无穷早晚休。
似把剪刀裁别恨，两人分得一般愁。','',''),('quantangshi-26623','欲别','姚合','quantangshi','','卷27','山川重叠远茫茫，欲别先忧别恨长。
红芍药花虽共醉，绿蘼芜影又分将。
鸳鸯有路高低去，鸿雁南飞一两行。
惆怅与君烟景迥，不知何日到潇湘。','',''),('quantangshi-26624','别杭州','姚合','quantangshi','','卷27','醉与江涛别，江涛惜我游。
他年婚嫁了，终老此江头。','',''),('quantangshi-26625','寄贾岛','姚合','quantangshi','','卷27','漫向城中住，儿童不识钱。
瓮头寒绝酒，竈额晓无烟。
狂发吟如哭，愁来坐似禅。
新诗有几首，旋被世人传。','',''),('quantangshi-26626','寄王度居士','姚合','quantangshi','','卷27','顦顇王居士，颠狂不称时。
天公与贫病，时辈复轻欺。
茅屋随年借，盘飡逐日移。
弃嫌官似梦，珍重酒如师。
无竹栽芦看，思山叠石为。
静窗留客话，古寺觅僧棊。
瘦马寒来死，羸童饿得痴。
唯应寻阮籍，心事远相知。','',''),('quantangshi-26627','寄杨茂卿校书','姚合','quantangshi','','卷27','去年别君时，同宿黎阳城。
黄河冻欲合，船入冰罅行。
君为使滑州，我来西入京。
丈夫不泣别，旁人叹无情。
到京就省试，落籍先有名。
慙辱乡荐书，忽欲自受刑。
还家岂无路，羞为路人轻。
决心住城中，百败望一成。
腐草众所弃，犹能化为萤。
岂我愚暗身，终久不发明。
所悲道路长，亲爱难合并。
还如舟与车，奔走各异程。
耳目甚短狭，背面若聋盲。
安得学白日，远见君仪形。','',''),('quantangshi-26628','寄杜师义','姚合','quantangshi','','卷27','出处难相见，同城似异乡。
点兵寻户籍，烧药试仙方。
事校千般别，心还一种忙。
黄金如化得，相寄亦何妨。','',''),('quantangshi-26629','寄陆浑县尉李景先','姚合','quantangshi','','卷27','微俸还同请，唯君独自闲。
地偏无驿路，药贱管仙山。
月色生松里，泉声在石间。
吟诗复饮酒，何事更相关。','',''),('quantangshi-26630','寄酬卢侍御','姚合','quantangshi','','卷27','诗新得意恣狂疎，挥手终朝力有余。
今到诗家浑手战，欲题名字倩人书。','',''),('quantangshi-26631','寄主客张郎中','姚合','quantangshi','','卷27','年长方慕道，金丹事参差。
故园归未得，秋风思难持。
蹇拙公府弃，朴静高人知。
以我齐杖屦，昏旭讵相离。
吟诗红叶寺，对酒黄菊篱。
所赏未及毕，后游良有期。
粲粲华省步，屑屑旅客姿。
未同山中去，固当殊路岐。','',''),('quantangshi-26632','寄鄠县尉李廓少府','姚合','quantangshi','','卷27','岁满休为吏，吟诗着白衣。
爱山闲卧久，在世此心稀。
听鹤向风立，捕鱼乘月归。
比君才不及，谬得侍彤闱。','',''),('quantangshi-26633','寄紫阁隐者','姚合','quantangshi','','卷27','自闻憔客说，无计得相寻。
几世传高卧，全家在一林。
养情书览苦，采药路多深。
愿得为邻里，谁能说此心。','',''),('quantangshi-26634','寄国子杨巨源祭酒','姚合','quantangshi','','卷27','日日新诗出，城中写不禁。
清高疑对竹，闲雅胜闻琴。
门户饶秋景，儿童解冷吟。
云山今作主，还借外人寻。','',''),('quantangshi-26635','寄永乐长官殷尧藩','姚合','quantangshi','','卷27','故人为吏隐，高卧簿书间。
遶院唯栽药，逢僧只说山。
此宵欢不接，穷岁信空还。
何计相寻去，严风雪满关。','',''),('quantangshi-26636','冬夜书事寄两省阁老','姚合','quantangshi','','卷27','天寒渐觉雁声疎，新月微微玉漏初。
海峤只宜今日去，故乡已过十年余。
发稀岂易胜玄冕，眼暗应难写谏书。
阁下羣公尽高思，谁能携酒访贫居。','',''),('quantangshi-26637','寄灵一律师','姚合','quantangshi','','卷27','梵书钞律千余纸，净院焚香独受持。
童子病来烟火绝，清泉漱口过斋时。','',''),('quantangshi-26638','郡中书事寄默然上人','姚合','quantangshi','','卷27','郡中饶野兴，过客亦淹留。
看月江楼晓，寻山石径秋。
意归何处老，谁免此生愁。
长爱东林子，安禅百事休。','',''),('quantangshi-26639','寄张徯','姚合','quantangshi','','卷27','幽处寻书坐，朝朝闭竹扉。
山僧封茗寄，野客乞诗归。
秋卷多唯好，时名屈更肥。
明年取前字，杯酒赛春辉。','',''),('quantangshi-26640','寄李频','姚合','quantangshi','','卷27','闭门常不出，惟觉长庭莎。
朋友来看少，诗书卧读多。
命随才共薄，愁与醉相和。
珍重君名字，新登甲乙科。','',''),('quantangshi-26641','寄李羣玉','姚合','quantangshi','','卷27','九衢名与利，无计扰闲人。
道远期轻世，才高贵重身。
石脂稀胜乳，玉粉细于尘。
骨换肌肤腻，心灵气色真。
嵩山高到日，洛水暖如春。
居住应安稳，黄金几竈新。','',''),('quantangshi-26642','病中书事寄友人','姚合','quantangshi','','卷27','终日自缠绕，此身无适缘。
万愁生雨夜，百病凑衰年。
多睡憎明屋，慵行待暖天。
疮头梳有虱，风耳乱无蝉。
换白方多错，回金法不全。
家贫何所怨，将在老僧边。','',''),('quantangshi-26643','九日寄钱可复','姚合','quantangshi','','卷27','数杯黄菊酒，千里白云天。
上国名方振，戎州病未痊。
静愁惟忆醉，闲走不胜眠。
惆怅东门别，相逢知几年。','',''),('quantangshi-26644','春日早朝寄刘起居','姚合','quantangshi','','卷27','九衢寒雾歛，双阙曙光分。
彩杖迎春日，香烟接瑞云。
佩声清漏间，天语侍臣闻。
莫笑冯唐老，还来谒圣君。','',''),('quantangshi-26645','秋日寄李支使','姚合','quantangshi','','卷27','秋思朝来起，侵人暑稍微。
晓眠离北户，午饭尚生衣。
山静云初白，枝高果渐稀。
闻君家海上，莫与燕同归。','',''),('quantangshi-26646','寄汴州令狐楚相公','姚合','quantangshi','','卷27','汴水从今不复浑，秋风鼙鼓动城根。
梁园台馆关东少，相府旌旗天下尊。
诗好四方谁敢和，政成三郡自无冤。
几时诏下归丹阙，还领千官入合门。','',''),('quantangshi-26647','寄东都分司白宾客','姚合','quantangshi','','卷27','阙下高眠过十旬，南宫印绶乞离身。
诗中得意应千首，海内嫌官只一人。
宾客分司真是隐，山泉遶宅岂辞贫。
竹斋晚起多无事，唯到龙门寺里频。','',''),('quantangshi-26648','寄裴起居','姚合','quantangshi','','卷27','千官晓立炉烟里，立近丹墀是起居。
彩笔专书皇帝语，书成几卷太平书。','',''),('quantangshi-26649','寄狄拾遗时为魏州从事','姚合','quantangshi','','卷27','少在兵马间，长还系戎职。
鸡飞不得远，岂要生羽翼。
三年城中游，与君最相识。
应知我中肠，不苟念衣食。
主人树勋名，欲灭天下贼。
愚虽乏智谋，愿陈一夫力。
人生须气健，饥冻缚不得。
睡当一席宽，觉乃千里窄。
古人不惧死，所惧死无益。
至交不可合，一合难离坼。
君尝相劝勉，苦语毒胸臆。
百年心知同，谁限河南北。','',''),('quantangshi-26650','金州书事寄山中旧友','姚合','quantangshi','','卷27','安康虽好郡，刺史是憨翁。
买酒终朝饮，吟诗一室空。
自知为政拙，众亦觉心公。
亲事星河在，忧人骨肉同。
簿书岚色里，鼓角水声中。
井邑神州接，帆樯海路通。
野亭晴带雾，竹寺夏多风。
溉稻长洲白，烧林远岫红。
旧山期已失，芳草思何穷。
林下无相笑，男儿五马雄。','',''),('quantangshi-26651','寄紫阁无名头陀','姚合','quantangshi','','卷27','峭行得如如，谁分圣与愚。
不眠知梦妄，无号免人呼。
山海禅皆遍，华夷佛岂殊。
何因接师话，清净在斯须。','',''),('quantangshi-26652','寄郁上人','姚合','quantangshi','','卷27','此生修道浅，愁见未来身。
谁为传真谛，唯应是上人。
自悲年已长，渐觉事难亲。
不向禅门去，他门无了因。','',''),('quantangshi-26653','寄孙路秀才','姚合','quantangshi','','卷27','幽居邻里少，江际复山阿。
潮去蝉声出，天晴鹤语多。
老人能步蹇，才子奈贫何。
曾见春官语，年来虚甲科。','',''),('quantangshi-26654','寄安陆友人','姚合','quantangshi','','卷27','别路在春色，故人云梦中。
鸟啼三月雨，蝶舞百花风。
烟束远山碧，霞欹落照红。
想君登此兴，回首念飘蓬。','',''),('quantangshi-26655','寄马戴','姚合','quantangshi','','卷27','天府鹿鸣客，幽山秋未归。
我知方甚爱，众说以为非。
隔屋闻泉细，和云见鹤微。
新诗此处得，清峭比应稀。','',''),('quantangshi-26656','寄贾岛时任普州司仓','姚合','quantangshi','','卷27','长沙事可悲，普掾罪谁知。
千载人空尽，一家冤不移。
吟寒应齿落，才峭自名垂。
地远山重叠，难传相忆词。','',''),('quantangshi-26657','寄杨工部闻毗陵舍弟自罨溪入茶山','姚合','quantangshi','','卷27','采茶溪路好，花影半浮沈。
画舸僧同上，春山客共寻。
芳新生石际，幽嫩在山阴。
色是春光染，香惊日气侵。
试尝应酒醒，封进定恩深。
芳贻千里外，怡怡太府吟。','',''),('quantangshi-26658','寄陕州王司马','姚合','quantangshi','','卷27','家寄秦城非本心，偶然头上有朝簪。
自当台直无因醉，一别诗宗更嬾吟。
世事每将愁见扰，年光唯与老相侵。
欲知居处堪长久，须向山中学煮金。','',''),('quantangshi-26659','寄贾岛','姚合','quantangshi','','卷27','寂寞荒原下，南山祗隔篱。
家贫唯我并，诗好复谁知。
草色无穷处，虫声少尽时。
朝昏鼓不到，闲卧益相宜。','',''),('quantangshi-26660','寄崔之仁山人','姚合','quantangshi','','卷27','百门坡上住，石屋两三间。
日月难教老，妻儿乞与闲。
仙经拣客问，药债煮金还。
何计能相访，终身得在山。','',''),('quantangshi-26661','寄嵩岳程光范','姚合','quantangshi','','卷27','相别何容易，相逢便岁年。
客来嫌路远，谁得到君边。
岳色鸟啼里，钟声竹影前。
只应访支遁，时得话诗篇。','',''),('quantangshi-26662','洛下夜会寄贾岛','姚合','quantangshi','','卷27','洛下攻诗客，相逢祗是吟。
夜觞欢稍静，寒屋坐多深。
乌府偶为吏，沧江长在心。
忆君难就寝，烛灭复星沈。','',''),('quantangshi-26663','寄华州李中丞','姚合','quantangshi','','卷27','毛女峰前郡，烟霞气转清。
庭分灵掌影，窗度瀑泉声。
藓迳人稀到，松斋药自生。
常飡亦芝术，闲客是公卿。
看水逢仙鹤，登楼见帝城。
养生非酒病，难隐是诗名。
省署尝连步，江臯欲独耕。
偶题无六义，聊以达微诚。','',''),('quantangshi-26664','病中辱谏议惠甘菊药苗因以诗赠','姚合','quantangshi','','卷27','萧萧一亩宫，种菊十余丛。
采摘和芳露，封题寄病翁。
熟宜茶鼎里，飡称石瓯中。
香洁将何比，从来味不同。','',''),('quantangshi-26665','舟行书事寄杭州崔员外','姚合','quantangshi','','卷27','张颐任酒浇，开眼信花烧。
旧国归何滞，新知别又遥。
夜行篙触石，晚泊缆依桥。
若未重相见，无门解寂寥。','',''),('quantangshi-26666','寄元绪上人','姚合','quantangshi','','卷27','石窗紫藓墙，此世此清凉。
研露题诗洁，消冰煮茗香。
闲云春影薄，孤磬夜声长。
何计休为吏，从师老草堂。','',''),('quantangshi-26667','寄白阁默然','姚合','quantangshi','','卷27','白阁峰头雪，城中望亦寒。
高僧多默坐，清夜到明看。
世上无诸苦，林间只一飡。
尝闻南北教，所得比师难。','',''),('quantangshi-26668','夏日书事寄丘亢处士','姚合','quantangshi','','卷27','暑天难可度，岂复更持觞。
树里鸣蝉咽，宫中午漏长。
病夫心益躁，静者室应凉。
几欲相寻去，红尘满路旁。','',''),('quantangshi-26669','秋中寄崔道士','姚合','quantangshi','','卷27','贫居雀喧噪，况乃静巷陌。
夜眠睡不成，空庭闻露滴。
旁有一杯酒，欢然如对客。
月光久逾明，照得笔墨白。
平生志舒豁，难可似兹夕。
四肢得自便，虽劳不为役。
故人山中住，善治活身策。
五谷口不尝，比僧更闲寂。
我今暂得安，自谓脱幽戚。
君身长逍遥，日月争老得。','',''),('quantangshi-26670','寄华州崔中丞','姚合','quantangshi','','卷27','莲华峰下郡，仙洞亦难胜。
闾里苍苔水，虚空瀑布冰。
酒香和药熟，山峭过云登。
清净黎人泰，唯忧急诏征。','',''),('quantangshi-26671','秋日书事寄祕书窦少监','姚合','quantangshi','','卷27','秋气日骚骚，星星双鬓毛。
凉天吟自远，清夜梦还高。
林下期同去，人间共是劳。
头巾何所直，且漉瓮头糟。','',''),('quantangshi-26672','友人南游不回因寄','姚合','quantangshi','','卷27','相思春树绿，千里亦依依。
鄠杜月频满，潇湘人不归。
桂花风畔落，烟草蝶双飞。
一别无消息，水南车迹稀。','',''),('quantangshi-26673','早春山居寄城中知己','姚合','quantangshi','','卷27','阳和潜发荡寒阴，便使川原景象深。
入户风泉声沥沥，当轩云岫影沈沈。
残云带雨轻飘雪，嫩柳含烟小绽金。
虽有眼前诗酒兴，邀游争得称闲心。','',''),('quantangshi-26674','辞白宾客归后寄','姚合','quantangshi','','卷27','千骑红旗不可攀，水头独立暮方还。
家人怪我浑如病，尊酒休倾笔砚间。','',''),('quantangshi-26675','寄右史李定言','姚合','quantangshi','','卷27','才归龙尾含鸡舌，更立螭头运兔毫。
阊阖欲开金漏尽，冕旒初坐御香高。','',''),('quantangshi-26676','寄绛州李使君','姚合','quantangshi','','卷27','独施清静化，千里管横汾。
黎庶应深感，朝庭亦细闻。
心期在黄老，家事是功勋。
物外须仙侣，人间要使君。
花多匀地落，山近满厅云。
戎客无因去，西看白日曛。','',''),('quantangshi-26677','寄送卢拱秘书游魏州','姚合','quantangshi','','卷27','太行山下路，荆棘昨来平。
一自开元后，今逢上客行。
地形吞北虏，人事接东京。
埽洒氛埃静，游从气概生。
蓟门春不艳，淇水暖还清。
看野风情远，寻花酒病成。
官闲身自在，诗逸语纵横。
车马回应晚，烟光满去程。','',''),('quantangshi-26678','秋晚夜坐寄院中诸曹长','姚合','quantangshi','','卷27','腰间垂印囊，白发未归乡。
还往应相责，朝昏亦自伤。
穷愁山影峭，独夜漏声长。
寂寞难成寐，寒灯侵晓光。','',''),('quantangshi-26679','书怀寄友人','姚合','quantangshi','','卷27','精心奉北宗，微宦在南宫。
举世劳为适，开门事不穷。
年来复几日，蝉去又鸣鸿。
衰疾谁人问，闲情与酒通。
四邻寒稍静，九陌夜方空。
知老何山是，思归愚谷中。','',''),('quantangshi-26680','寄无可上人','姚合','quantangshi','','卷27','十二门中寺，诗僧寺独幽。
多年松色别，后夜磬声秋。
见世虑皆尽，来生事更修。
终须执瓶钵，相逐入牛头。','',''),('quantangshi-26681','寄晖上人','姚合','quantangshi','','卷27','日出月复没，悠悠昏与明。
修持经几劫，清净到今生。
林下知无相，人间苦是情。
终期逐师去，不拟老尘缨。','',''),('quantangshi-26682','寄李干','姚合','quantangshi','','卷27','寻常自怪诗无味，虽被人吟不喜闻。
见说与君同一格，数篇到火却休焚。','',''),('quantangshi-26683','寄贾岛浪仙','姚合','quantangshi','','卷27','悄悄掩门扉，穷窘自维絷。
世途已昧履，生计复乖缉。
疎我非常性，端峭尔孤立。
往还纵云久，贫蹇岂自习。
所居率荒野，宁似在京邑。
院落夕弥空，虫声雁相及。
衣巾半僧施，蔬药常自拾。
凛凛寝席单，翳翳竈烟湿。
颓篱里人度，败壁邻灯入。
晓思已暂舒，暮愁还更集。
风凄林叶萎，苔糁行径涩。
海峤誓同归，橡栗充朝给。','',''),('quantangshi-26684','寄九华费冠卿','姚合','quantangshi','','卷27','逍遥[罾]缴外，高鸟与潜鱼。
阙下无朝籍，林间有诏书。
夜眠青玉洞，晓饭白云蔬。
四海人空老，九华君独居。
此心谁复识，日与世情疎。','',''),('quantangshi-26685','寄不疑上人','姚合','quantangshi','','卷27','是法修行遍，方栖不二门。
随缘嫌寺着，见性觉经繁。
所叹身将老，始闻师一言。
尘沙千万劫，劫尽佛长存。','',''),('quantangshi-26686','寄主客刘郎中','姚合','quantangshi','','卷27','汉朝共许贾生贤，迁谪还应是宿缘。
仰德多时方会面，拜兄何暇更论年。
嵩山晴色来城里，洛水寒光出岸边。
清景早朝吟丽思，题诗应费益州牋。','',''),('quantangshi-26687','寄周十七起居','姚合','quantangshi','','卷27','冬冬九陌鼓声齐，百辟朝天马乱嘶。
月照浓霜寒更远，风吹红烛举还低。
官清立在金炉北，仗下归眠玉殿西。
莫笑老人多独出，晴山荒景觅诗题。','',''),('quantangshi-26688','秋夜寄默然上人','姚合','quantangshi','','卷27','霜月静幽居，闲吟梦觉初。
秋深夜迢遰，年长意萧疎。
海上归难遂，人间事尽虚。
赖师方便语，渐得识真如。','',''),('quantangshi-26689','寄王玄伯','姚合','quantangshi','','卷27','夜归晓出满衣尘，转觉才名带累身。
莫觅旧来终日醉，世间杯酒属闲人。','',''),('quantangshi-26690','寄山中友人','姚合','quantangshi','','卷27','昨秋今复春，役役是非身。
海上无归路，城中作老人。
流年何处在，白日每朝新。
闻有长生术，将求未有因。','',''),('quantangshi-26691','寄陕府内兄郭冏端公','姚合','quantangshi','','卷27','蹇钝无大计，酷嗜进士名。
为文性不高，三年住西京。
相府执文柄，念其心专精。
薄艺不退辱，特列为门生。
事出自非意，喜常少于惊。
春牓四散飞，数日徧八纮。
眼始见花发，耳得闻鸟鸣。
免同去年春，兀兀聋与盲。
家寄河朔间，道路出陕城。
暌违逾十年，一会豁素诚。
同游山水穷，狂饮飞大觥。
起坐不相离，有若亲弟兄。
中外无亲疎，所算在其情。
久客贵优饶，一醉旧疾平。
家远归思切，风雨甚亦行。
到兹恋仁贤，淹滞一月程。
新诗忽见示，气逸言纵横。
缠緜意千里，骚雅文发明。
永昼吟不休，咽喉干无声。
羁贫重金玉，今日金玉轻。','',''),('quantangshi-26692','寄题蔡州蒋亭兼简田使君','姚合','quantangshi','','卷27','几岁乱军里，蒋亭名不销。
无人知旧径，有药长新苗。
树宿山禽静，池通野水遥。
何因同此醉，永望思萧条。','',''),('quantangshi-26693','山居寄友人','姚合','quantangshi','','卷27','独在山阿里，朝朝遂性情。
晓泉和雨落，秋草上堦生。
因客始沽酒，借书方到城。
诗情聊自遣，不是趁声名。','',''),('quantangshi-26694','寄崔之仁山人','姚合','quantangshi','','卷27','不得之仁消息久，秋来体色复何如。
苦将杯酒判身病，狂作文章信手书。
官职卑微从客笑，性灵闲野向钱疎。
几时身计浑无事，拣取深山一处居。','',''),('quantangshi-26695','寄主客刘员外','姚合','quantangshi','','卷27','蝉稀虫唧唧，露重思悠悠。
静者多便夜，豪家不见秋。
同归方欲就，微恙几时瘳。
今日沧江上，何人理钓舟。','',''),('quantangshi-26696','山中寄友人','姚合','quantangshi','','卷27','路岐何渺邈，在客易蹉跎。
却是去家远，因循住日多。
几看春草绿，又见塞鸿过。
未有进身处，忍教抛薜萝。','',''),('quantangshi-26697','寄友人','姚合','quantangshi','','卷27','日暮掩重扉，抽簪复解衣。
漏声林下静，萤色月中微。
秋霁露华结，夜深人语稀。
殷勤故山路，谁与我同归。','',''),('quantangshi-26698','寄李余卧疾','姚合','quantangshi','','卷27','穷节弥惨栗，我讵自云乐。
伊人婴疾恙，所对唯苦药。
寂寞行稍稀，清羸飡自薄。
幽斋外浮事，梦寐亦简略。
雪户掩复明，风帘卷还落。
方持数杯酒，勉子同斟酌。','',''),('quantangshi-26699','寄白石师','姚合','quantangshi','','卷27','白石师何在，师禅白石中。
无情云可比，不食鸟难同。
屦下苍苔雪，龛前瀑布风。
相寻未有计，只是礼虚空。','',''),('quantangshi-26700','寄贾岛','姚合','quantangshi','','卷27','疎拙祗如此，此身谁与同。
高情向酒上，无事在山中。
渐老病难理，久贫吟益空。
赖君时访宿，不避北斋风。','',''),('quantangshi-26701','寄默然上人','姚合','quantangshi','','卷27','晨飡夜复眠，日与月相连。
天下谁无病，人间乐是禅。
几生通佛性，一室但香烟。
结得无为社，还应有宿缘。','',''),('quantangshi-26702','寄不出院僧','姚合','quantangshi','','卷27','不行门外地，斋戒得清真。
长食施来饭，深居锁定身。
朝昏常傍佛，起坐省逢人。
非独心常净，衣无一点尘。','',''),('quantangshi-26703','万年县中雨夜会宿寄皇甫甸','姚合','quantangshi','','卷27','县斋还寂寞，夕雨洗苍苔。
清气灯微润，寒声竹共来。
虫移上阶近，客起到门回。
想得吟诗处，唯应对酒杯。','',''),('quantangshi-26704','寄旧山隐者','姚合','quantangshi','','卷27','别君须臾间，历日两度新。
念彼白日长，复值人事并。
未改当时居，心事如野云。
朝朝恣行坐，百事都不闻。
奈何道未尽，出山最艰辛。
奔走衢路间，四枝不属身。
名在进士场，笔毫争等伦。
我性本朴直，词理安得文。
纵然自称心，又不合众人。
以此名字低，不如风中尘。
昨逢卖药客，云是居山邻。
说君忆我心，顦顇其形神。
昔是同枝鸟，今作万里分。
万里亦未遥，喧静终难羣。','',''),('quantangshi-26705','新居秋夕寄李廓','姚合','quantangshi','','卷27','羁滞多共趣，屡屡同室眠。
稍暇更访诣，宁唯候招延。
愧君备蔬药，识我性所便。
罢吏童仆去，洒扫或自专。
古巷人易息，疎迥自江边。
幸当中秋夕，复此无云天。
月华更漏清，露叶光彩鲜。
四邻亦悄悄，中怀益缠绵。
兹境罕能致，居闲得弥偏。
数杯罢复饮，共想山中年。','',''),('quantangshi-26706','赠卢大夫将军','姚合','quantangshi','','卷27','将军身在城，讵得虏尘清。
酿酒邀闲客，吟诗直禁营。
苍鹰春不下，战马夜空鸣。
碣石应无业，皇州独有名。
上山嫌䯗重，拔劒叹衣生。
公议今如此，登坛到即行。','',''),('quantangshi-26707','赠供奉僧次融','姚合','quantangshi','','卷27','会解如来意，僧家独有君。
开经对天子，骑马过声闻。
本寺远于日，新诗高似云。
热时吟一句，凉冷胜秋分。','',''),('quantangshi-26708','赠王尊师','姚合','quantangshi','','卷27','先生自说瀛洲路，多在青松白石间。
海岸夜中常见日，仙宫深处却无山。
犬随鹤去游诸洞，龙作人来问大还。
今日偶闻尘外事，朝簪未掷复何颜。','',''),('quantangshi-26709','赠常州院僧','姚合','quantangshi','','卷27','一住毗陵寺，师应祗信缘。
院贫人施食，窗静鸟窥禅。
古磬声难尽，秋灯色更鲜。
仍闻开讲日，湖上少鱼船。','',''),('quantangshi-26710','赠卢沙弥小师','姚合','quantangshi','','卷27','怕见世间事，削头披佛衣。
年小未受戒，会解如老师。
天与出家肠，一食斋不饥。
麻履踏雪路，与马不肯骑。
嫌我身腥膻，似我见戎夷。
彼此见会异，对面成别离。
我师文宣王，立教垂书诗。
但全仁义心，自然便慈悲。
两教大体同，无处辨是非。
莫以衣服别，到头不相知。','',''),('quantangshi-26711','赠张籍太祝','姚合','quantangshi','','卷27','绝妙江南曲，凄凉怨女诗。
古风无手敌，新语是人知。
飞动应由格，功夫过却奇。
麟台添集卷，乐府换歌词。
李白应先拜，刘祯必自疑。
贫须君子救，病合国家医。
野客开山借，邻僧与米炊。
甘贫辞聘币，依选受官资。
多见愁连晓，稀闻债尽时。
圣朝文物盛，太祝独低眉。','',''),('quantangshi-26712','赠丘郎中','姚合','quantangshi','','卷27','绕篱栽杏种黄精，晓侍罏烟暮出城。
万事将身求总易，学君难得是长生。','',''),('quantangshi-26713','赠王建司马','姚合','quantangshi','','卷27','久向空门隐，交亲亦不知。
文高轻古意，官冷似前资。
老觉僧斋健，贫还酒债迟。
仙方小字写，行坐把相随。','',''),('quantangshi-26714','赠任士曹','姚合','quantangshi','','卷27','宪皇十一祀，共得春闱书。
道直淹曹掾，命通侍玉除。
浮生年月促，九陌笑言疎。
何计同归去，沧江有弊庐。','',''),('quantangshi-26715','赠刘[叉]','姚合','quantangshi','','卷27','自君离海上，垂钓更何人。
独宿空堂雨，闲行九陌尘。
避时曾变姓，救难似嫌身。
何处相期宿，咸阳酒市春。','',''),('quantangshi-26716','赠僧绍明','姚合','quantangshi','','卷27','西方清净路，此路出何门。
见说师知处，从来佛不言。
今生多病恼，自晓至黄昏。
唯寐方无事，那堪梦亦喧。','',''),('quantangshi-26717','赠张质山人','姚合','quantangshi','','卷27','先生居处僻，荆棘与墙齐。
酒好宁论价，诗狂不着题。
烧成度世药，踏尽上山梯。
嬾听闲人语，争如谷鸟啼。','',''),('quantangshi-26718','赠少室山麻襦僧','姚合','quantangshi','','卷27','秖辫麻为衲，此中经几春。
庵前多猛兽，径小绝行人。
泉近濆瓶履，山深少垢尘。
想师正法指，喻我独迷津。','',''),('quantangshi-26719','赠王山人','姚合','quantangshi','','卷27','贤哲论独诞，吾宗次定今。
诗吟天地广，觉印果因深。
教演归恭敬，名标中外钦。
既能施六度，了悟达双林。','',''),('quantangshi-26720','赠终南山傅山人','姚合','quantangshi','','卷27','七十未成事，终南苍鬓翁。
老来诗兴苦，贫去酒肠空。
蟠蛰身仍病，鹏抟力未通。
已无烧药本，唯有着书功。
白马时何晚，青龙岁欲终。
生涯枯叶下，家口乱云中。
潭静鱼惊水，天晴鹤唳风。
悲君还姓傅，独不梦高宗。','',''),('quantangshi-26721','使两浙赠罗隐','姚合','quantangshi','','卷27','平日时风好涕流，谗书虽盛一名休。
寰区叹屈瞻天问，夷貊闻诗过海求。
向夕便思青琐拜，近年寻伴赤松游。
何当世祖从人望，早以公台命卓侯。','',''),('quantangshi-26722','闲居遣怀十首 一','姚合','quantangshi','','卷27','身外无徭役，开门百事闲。
倚松听唳鹤，策杖望秋山。
萍任连池绿，苔从匝地斑。
料无车马客，何必扫柴关。','',''),('quantangshi-26723','闲居遣怀十首 二','姚合','quantangshi','','卷27','闲卧销长日，亲朋笑我疎。
诗篇随分有，人事度年无。
情性僻难改，愁怀酒为除。
谁能思此计，空备满牀书。','',''),('quantangshi-26724','闲居遣怀十首 三','姚合','quantangshi','','卷27','白日逍遥过，看山复遶池。
展书寻古事，翻卷改新诗。
赊酒风前酌，留僧竹里棊。
同人笑相问，羡我足闲时。','',''),('quantangshi-26725','闲居遣怀十首 四','姚合','quantangshi','','卷27','好景时牵目，茅斋兴有余。
远山经雨后，庭树得秋初。
道侣怜栽药，高人笑养鱼。
优游随本性，甘被弃慵疎。','',''),('quantangshi-26726','闲居遣怀十首 五','姚合','quantangshi','','卷27','永日厨烟绝，何曾暂废吟。
闲时随思缉，小酒恣情斟。
看月嫌松密，垂纶爱水深。
世间多少事，无事可关心。','',''),('quantangshi-26727','闲居遣怀十首 六','姚合','quantangshi','','卷27','一生能几日，愁恨也无端。
遇酒酕醄饮，逢花烂熳看。
青云非失路，白发未相干。
以此多携解，将心但自宽。','',''),('quantangshi-26728','闲居遣怀十首 七','姚合','quantangshi','','卷27','万事徒纷扰，难关枕上身。
朗吟销白日，沈醉度青春。
演步怜山近，闲眠厌客频。
市朝曾不到，长免满衣尘。','',''),('quantangshi-26729','闲居遣怀十首 八','姚合','quantangshi','','卷27','野性多疎惰，幽栖更称情。
独行看影笑，闲坐弄琴声。
嬾拜腰肢硬，慵趋礼乐生。
业文随日遣，不是为求名。','',''),('quantangshi-26730','闲居遣怀十首 九','姚合','quantangshi','','卷27','生计甘寥落，高名愧自由。
惯无身外事，不信世间愁。
好酒盈杯酌，闲诗任笔酬。
凉风从入户，云水更宜秋。','',''),('quantangshi-26731','闲居遣怀十首 十','姚合','quantangshi','','卷27','拙直难和洽，从人笑掩关。
不能行户外，宁解走尘间。
被酒长酣思，无愁可上颜。
何言归去事，着处是青山。','',''),('quantangshi-26732','武功县中作三十首 一','姚合','quantangshi','','卷27','县去帝城远，为官与隐齐。
马随山鹿放，鸡杂野禽栖。
遶舍惟藤架，侵堦是药畦。
更师嵇叔夜，不拟作书题。','',''),('quantangshi-26733','武功县中作三十首 二','姚合','quantangshi','','卷27','方拙天然性，为官是事疎。
惟寻向山路，不寄入城书。
因病多收药，缘飡学钓鱼。
养身成好事，此外更空虚。','',''),('quantangshi-26734','武功县中作三十首 三','姚合','quantangshi','','卷27','微官如马足，祗是在泥尘。
到处贫随我，终年老趁人。
簿书销眼力，杯酒耗心神。
早作归休计，深居养此身。','',''),('quantangshi-26735','武功县中作三十首 四','姚合','quantangshi','','卷27','簿书多不会，薄俸亦难销。
醉卧慵开眼，闲行嬾系腰。
移花兼蝶至，买石得云饶。
且自心中乐，从他笑寂寥。','',''),('quantangshi-26736','武功县中作三十首 五','姚合','quantangshi','','卷27','晓钟惊睡觉，事事便相关。
小市柴薪贵，贫家砧杵闲。
读书多旋忘，赊酒数空还。
长羡刘伶辈，高眠出世间。','',''),('quantangshi-26737','武功县中作三十首 六','姚合','quantangshi','','卷27','性疎常爱卧，亲故笑悠悠。
纵出多携枕，因衙始裹头。
上山方觉老，过寺暂忘愁。
三考千余日，低腰不拟休。','',''),('quantangshi-26738','武功县中作三十首 七','姚合','quantangshi','','卷27','客至皆相笑，诗书满卧牀。
爱闲求病假，因醉弃官方。
鬓发寒唯短，衣衫瘦渐长。
自嫌多检束，不似旧来狂。','',''),('quantangshi-26739','武功县中作三十首 八','姚合','quantangshi','','卷27','一日看除目，终年损道心。
山亦冲雪上，诗好带风吟。
野客嫌知印，家人笑买琴。
只应随分过，已是错弥深。','',''),('quantangshi-26740','武功县中作三十首 九','姚合','quantangshi','','卷27','邻里皆相爱，门开数见过。
秋凉送客远，夜静咏诗多。
就架题书目，寻栏记药窠。
到官无别事，种得满庭莎。','',''),('quantangshi-26741','武功县中作三十首 十','姚合','quantangshi','','卷27','穷达天应与，人间事莫论。
微官长似客，远县岂胜村。
竟日多无食，连宵不闭门。
斋心调笔砚，唯写五千言。','',''),('quantangshi-26742','武功县中作三十首 十一','姚合','quantangshi','','卷27','县僻仍牢落，游人到便回。
路当边地去，村入郭门来。
酒户愁偏长，诗情病不开。
可曾衙小吏，恐谓踏青苔。','',''),('quantangshi-26743','武功县中作三十首 十二','姚合','quantangshi','','卷27','自下青山路，三年着绿衣。
官卑食肉僭，才短事人非。
野客教长醉，高僧劝早归。
不知何计是，免与本心违。','',''),('quantangshi-26744','武功县中作三十首 十三','姚合','quantangshi','','卷27','日出方能起，庭前看种莎。
吏来山鸟散，酒熟野人过。
岐路荒城少，烟霞远岫多。
同官数相引，下马上西[坡]。','',''),('quantangshi-26745','武功县中作三十首 十四','姚合','quantangshi','','卷27','作吏荒城里，穷愁欲不胜。
病多唯识药，年老渐亲僧。
梦觉空堂月，诗成满砚冰。
故人多得路，寂寞不相称。','',''),('quantangshi-26746','武功县中作三十首 十五','姚合','quantangshi','','卷27','谁念东山客，栖栖守印牀。
何年得事尽，终日逐人忙。
醉卧谁知呌，闲书不着行。
人间长检束，与此岂相当。','',''),('quantangshi-26747','武功县中作三十首 十六','姚合','quantangshi','','卷27','朝朝眉不展，多病怕逢迎。
引水远通涧，垒山高过城。
秋灯照树色，寒雨落池声。
好是吟诗夜，披衣坐到明。','',''),('quantangshi-26748','武功县中作三十首 十七','姚合','quantangshi','','卷27','簿籍谁能问，风寒趁早眠。
每旬常乞假，隔月探支钱。
还往嫌诗僻，亲情怪酒颠。
谋身须上计，终久是归田。','',''),('quantangshi-26749','武功县中作三十首 十八','姚合','quantangshi','','卷27','闭门风雨里，落叶与堦齐。
野客嫌杯小，山翁喜枕低。
听琴知道性，寻药得诗题。
谁更能骑马，闲行祗杖藜。','',''),('quantangshi-26750','武功县中作三十首 十九','姚合','quantangshi','','卷27','腥膻都不食，稍稍觉神清。
夜犬因风吠，邻鸡带雨鸣。
守官常卧病，学道别称名。
小有洞中路，谁能引我行。','',''),('quantangshi-26751','武功县中作三十首 二十','姚合','quantangshi','','卷27','宦名浑不计，酒熟且开封。
晴月销灯色，寒天挫笔锋。
惊禽时并起，闲客数相逢。
旧国萧条思，青山隔几重。','',''),('quantangshi-26752','武功县中作三十首 二十一','姚合','quantangshi','','卷27','假日多无事，谁知我独忙。
移山入县宅，种竹上城墙。
惊蝶遗花蘂，游蜂带蜜香。
唯愁明早出，端坐吏人旁。','',''),('quantangshi-26753','武功县中作三十首 二十二','姚合','quantangshi','','卷27','门外青山路，因循自不归。
养生宜县僻，说品喜官微。
净爱山僧饭，闲披野客衣。
谁怜幽谷鸟，不解入城飞。','',''),('quantangshi-26754','武功县中作三十首 二十三','姚合','quantangshi','','卷27','一官无限日，愁闷欲何如。
扫舍惊巢燕，寻方落壁鱼。
从僧乞净水，凭客报闲书。
白发谁能镊，年来四十余。','',''),('quantangshi-26755','武功县中作三十首 二十四','姚合','quantangshi','','卷27','朝朝门不闭，长似在山时。
宾客抽书读，儿童斫竹骑。
久贫还易老，多病嬾能医。
道友应相怪，休官日已迟。','',''),('quantangshi-26756','武功县中作三十首 二十五','姚合','quantangshi','','卷27','戚戚常无思，循资格上官。
闲人得事晚，常骨觅仙难。
醉卧疑身病，贫居觉道宽。
新诗久不写，自算少人看。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-26757','武功县中作三十首 二十六','姚合','quantangshi','','卷27','漫作容身计，今知拙有余。
青衫迎驿使，白发忆山居。
道友怜蔬食，吏人嫌草书。
须为长久事，归去自耕锄。','',''),('quantangshi-26758','武功县中作三十首 二十七','姚合','quantangshi','','卷27','主印三年坐，山居百事休。
焚香开敕库，踏月上城楼。
饮酒多成病，吟诗易长愁。
殷勤问渔者，暂借手中钩。','',''),('quantangshi-26759','武功县中作三十首 二十八','姚合','quantangshi','','卷27','长忆青山下，深居遂性情。
垒堦溪石净，烧竹竈烟轻。
点笔图云势，弹琴学鸟声。
今朝知县印，梦里百忧生。','',''),('quantangshi-26760','武功县中作三十首 二十九','姚合','quantangshi','','卷27','自知狂僻性，吏事固相疎。
祗是看山立，无嫌出县居。
印朱霑墨砚，户籍杂经书。
月俸寻常请，无妨乏斗储。','',''),('quantangshi-26761','武功县中作三十首 三十','姚合','quantangshi','','卷27','作吏无能事，为文旧致功。
诗标八病外，心落百忧中。
拜别登朝客，归依炼药翁。
不知还往内，谁与此心同。','',''),('quantangshi-26762','罢武功县将入城 一','姚合','quantangshi','','卷27','乍抛衫笏觉身轻，依旧还称学道名。
欲泥山僧分屋住，羞从野老借牛耕。
妻儿尽怕为逋客，亲故相邀遣到城。
无奈同官珍重意，几回临路却休行。','',''),('quantangshi-26763','罢武功县将入城 二','姚合','quantangshi','','卷27','青衫脱下便狂歌，种薤栽莎斸古坡。
野客相逢添酒病，春山暂上着诗魔。
亦知官罢贫还甚，且喜闲来睡得多。
欲与九衢亲故别，明朝拄杖始经过。','',''),('quantangshi-26764','秋日闲居二首 一','姚合','quantangshi','','卷27','九陌宅重重，何门怜此翁。
荒庭唯菊茂，幽径与山通。
落叶带衣上，闲云来酒中。
此心谁得见，林下鹿应同。','',''),('quantangshi-26765','秋日闲居二首 二','姚合','quantangshi','','卷27','先忆花时节，家山听更归。
爱诗看古集，忆酒典寒衣。
睡少身还健，愁多食不肥。
自怜疎嬾性，无事出门稀。','',''),('quantangshi-26766','闲居晚夏','姚合','quantangshi','','卷27','闲居无事扰，旧病亦多痊。
选字诗中老，看山屋外眠。
片霞侵落日，繁叶咽鸣蝉。
对此心还乐，谁知乏酒钱。','',''),('quantangshi-26767','闲居','姚合','quantangshi','','卷27','不自识疎鄙，终年住在城。
过门无马迹，满宅是蝉声。
带病吟虽苦，休官梦已清。
何当学禅观，依止古先生。','',''),('quantangshi-26768','街西居三首 一','姚合','quantangshi','','卷27','受得山野性，住城多事违。
青山在宅南，回首东西稀。
浅浅一井泉，数家同汲之。
独我恶水浊，凿井庭之陲。
自凿还自饮，亦为众所非。
吁嗟世间事，洁身诚难为。','',''),('quantangshi-26769','街西居三首 二','姚合','quantangshi','','卷27','日出穷巷喜，温然胜重衣。
重衣岂不暖，所暖人不齐。
兀兀复行行，不离阶与墀。','',''),('quantangshi-26770','街西居三首 三','姚合','quantangshi','','卷27','丈夫非马蹄，安得知路岐。
穷贱飱茹薄，兴与养性宜。
乃知长生术，豪贵难得之。','',''),('quantangshi-26771','闲居遣兴','姚合','quantangshi','','卷27','终年城里住，门户似山林。
客怪身名晚，妻嫌酒病深。
写方多识药，失谱废弹琴。
文字非经济，空虚用破心。','',''),('quantangshi-26772','庄居即事','姚合','quantangshi','','卷27','休看小字大书名，向日持经眼却明。
时过无心求富贵，身闲不梦见公卿。
因寻岳寺荤辛断，自到王城礼数生。
斜月照牀新睡觉，西风半夜鹤来声。','',''),('quantangshi-26773','亲仁里居','姚合','quantangshi','','卷27','三年赁舍亲仁里，寂寞何曾似在城。
饮酒自缘防冷病，寻人多是为闲行。
轩车无路通门巷，亲友因诗道姓名。
自别青山归未得，羡君长听石泉声。','',''),('quantangshi-26774','庄居野行','姚合','quantangshi','','卷27','客行野田间，此屋皆闭户。
借问屋中人，尽去作商贾。
官家不税商，税农服作苦。
居人尽东西，道路侵壠亩。
采玉上山颠，探珠入水府。
边兵索衣食，此物同泥土。
古来一人耕，三人食犹饥。
如今千万家，无一把锄犂。
我仓常空虚，我田生蒺藜。
上天不雨粟，何由活烝黎。','',''),('quantangshi-26775','春日闲居','姚合','quantangshi','','卷27','居止日萧条，庭前唯药苗。
身闲眠自久，眼荖视还遥。
檐燕酬莺语，邻花杂絮飘。
客来无酒饮，搔首掷空瓢。','',''),('quantangshi-26776','独居','姚合','quantangshi','','卷27','深闭柴门长不出，功夫自课少闲时。
翻音免问他人字，覆局何劳对手棊。
生计如云无定所，穷愁似影每相随。
到头归向青山是，尘路茫茫欲告谁。','',''),('quantangshi-26777','早春闲居','姚合','quantangshi','','卷27','寂寞日何为，闲居春色迟。
惊风起庭雪，寒雨长檐澌。
强饮樽中酒，嘲山世外诗。
此生仍且在，难与老相离。','',''),('quantangshi-26778','原上新居','姚合','quantangshi','','卷27','秋来梨果熟，行哭小儿饥。
邻富鸡长往，庄贫客渐稀。
借牛耕地晚，卖树纳钱迟。
墙下当官道，依前夹竹篱。','',''),('quantangshi-26779','将归山','姚合','quantangshi','','卷27','野人惯去山中住，自到城来闷不胜。
宫树蝉声多却乐，侯门月色少于灯。
饥来唯拟重餐药，归去还应只别僧。
闻道旧溪茆屋畔，春风新上数枝藤。','',''),('quantangshi-26780','山中述怀','姚合','quantangshi','','卷27','为客久未归，寒山独掩扉。
晓来山鸟散，雨过杏花稀。
天远云空积，溪深水自微。
此情对春色，尽醉欲忘机。','',''),('quantangshi-26781','偶然书怀','姚合','quantangshi','','卷27','十年通籍入金门，自愧名微枉搢绅。
炼得丹砂疑不食，从兹白发日相亲。
家山迢遰归无路，杯酒稀疎病到身。
汉有冯唐唐有我，老为郎吏更何人。','',''),('quantangshi-26782','客舍有怀','姚合','quantangshi','','卷27','旅人无事喜，终日思悠悠。
逢酒嫌杯浅，寻书怕字稠。
贫来许钱圣，梦觉见身愁。
寂寞中林下，饥鹰望到秋。','',''),('quantangshi-26783','及第后夜中书事','姚合','quantangshi','','卷27','夜睡常惊起，春光属野夫。
新衔添一字，旧友逊前途。
喜过还疑梦，狂来不似儒。
爱花持烛看，忆酒犯街沽。
天上名应定，人间盛更无。
报恩丞相合，何啻杀微躯。','',''),('quantangshi-26784','偶题','姚合','quantangshi','','卷27','年年九陌看春还，旧隐空劳梦寐间。
迟日逍遥芸草长，圣朝清净谏臣闲。
偶逢游客同倾酒，自有前驺耻见山。
道侣书来相责诮，朝朝欲报作何颜。','',''),('quantangshi-26785','感时','姚合','quantangshi','','卷27','忆昔未出身，索寞无精神。
逢人话天命，自贱如埃尘。
君今才出身，飒爽鞍马春。
逢人话天命，自重如千钧。
信涉名利道，举动皆丧真。
君今自世情，何况天下人。','',''),('quantangshi-26786','忆山','姚合','quantangshi','','卷27','闲处无人到，乖疎称野情。
日高搔首起，林下散衣行。
泉引窗前过，云看石罅生。
别来愁欲老，虚负出山名。','',''),('quantangshi-26787','客游旅怀','姚合','quantangshi','','卷27','客行无定止，终日路岐间。
马为赊来贵，僮缘借得顽。
诗书愁触雨，店舍喜逢山。
旧业嵩阳下，三年未得还。','',''),('quantangshi-26788','迎春','姚合','quantangshi','','卷27','半年留醉待花开，晓去迎春夜始回。
风暖慢行寻曲水，天晴远望立高台。
亦知无处将诗请，唯得终朝把酒催。
今日柳条全弄色，游人相伴看春来。','',''),('quantangshi-26789','游春十二首 一','姚合','quantangshi','','卷27','正月一日后，寻春更不眠。
自知还近僻，众说过于颠。
看水宁依路，登山欲到天。
悠悠芳思起，多是晚风前。','',''),('quantangshi-26790','游春十二首 二','姚合','quantangshi','','卷27','官卑长少事，县僻又无城。
未晓冲寒起，迎春忍病行。
树枝风掉软，菜甲土浮轻。
好个林间鹊，今朝足喜声。','',''),('quantangshi-26791','游春十二首 三','姚合','quantangshi','','卷27','诗酒相牵引，朝朝思不穷。
苔痕雪水里，春色竹烟中。
迎雨缘池草，摧花倚树风。
书非名利事，爱此少人同。','',''),('quantangshi-26792','游春十二首 四','姚合','quantangshi','','卷27','尘中主印吏，谁遣有高情。
趁暖檐前坐，寻芳树底行。
土融凝墅色，冰败满池声。
渐觉春相泥，朝来睡不轻。','',''),('quantangshi-26793','游春十二首 五','姚合','quantangshi','','卷27','疎顽无异事，随例但添年。
旧历藏深箧，新衣薄絮绵。
暖风浑酒色，晴日畅琴弦。
同伴无辞困，游春贵在先。','',''),('quantangshi-26794','游春十二首 六','姚合','quantangshi','','卷27','看春长不足，岂更觉身劳。
寺里花枝净，山中水色高。
嫩云轻似絮，新草细如毛。
并起诗人思，还应费笔毫。','',''),('quantangshi-26795','游春十二首 七','姚合','quantangshi','','卷27','悠悠小县吏，顦顇入新年。
远思遭诗恼，闲情被酒牵。
恋花林下饮，爱草野中眠。
疎嬾今成性，谁人肯更怜。','',''),('quantangshi-26796','游春十二首 八','姚合','quantangshi','','卷27','处处春光遍，游人亦不稀。
向阳倾冷酒，看影试新衣。
嫩树行移长，幽禽语旋飞。
同来皆去尽，冲夜独吟归。','',''),('quantangshi-26797','游春十二首 九','姚合','quantangshi','','卷27','朝朝看春色，春色似相怜。
酒醒莺啼里，诗成蝶舞前。
摘花盈手露，折竹满庭烟。
亲故多相笑，疎狂似少年。','',''),('quantangshi-26798','游春十二首 十','姚合','quantangshi','','卷27','卑官还不恶，行止得逍遥。
晴野花侵路，春陂水上桥。
尘埃生暖色，药草长新苗。
看却烟光散，狂风处处飘。','',''),('quantangshi-26799','游春十二首 十一','姚合','quantangshi','','卷27','身被春光引，经时更不归。
嚼花香满口，书竹粉黏衣。
弄日莺狂语，迎风蝶倒飞。
自知疎嬾性，得事亦应稀。','',''),('quantangshi-26800','游春十二首 十二','姚合','quantangshi','','卷27','晓脱青衫出，闲行气味长。
一瓶春酒色，数顷野花香。
朝客闻应羡，山僧见亦狂。
不将僮仆去，恐为损风光。','',''),('quantangshi-26801','赏春','姚合','quantangshi','','卷27','闲人祗是爱春光，迎得春来喜欲狂。
买酒怕迟教走马，看花嫌远自移牀。
娇莺语足方离树，戏蝶飞高始过墙。
颠倒醉眠三数日，人间百事不思量。','',''),('quantangshi-26802','春日即事','姚合','quantangshi','','卷27','春来眠不得，谁复念生涯。
夜听四邻乐，朝寻九陌花。
轻烟浮草色，微雨濯年华。
乞假非关病，朝衣在酒家。','',''),('quantangshi-26803','春日江次','姚合','quantangshi','','卷27','野步出茆斋，闲行坐石台。
久悲乡路远，犹喜杏花开。
鸥鹭皆飞去，帆樯何处来？
因凝千里目，落日尚徘徊。','',''),('quantangshi-26804','扬州春词三首 一','姚合','quantangshi','','卷27','广陵寒食天，无雾复无烟。
暖日凝花柳，春风散管弦。
园林多是宅，车马少于船。
莫唤游人住，游人困不眠。','',''),('quantangshi-26805','扬州春词三首 二','姚合','quantangshi','','卷27','满郭是春光，街衢土亦香。
竹风轻履舃，花露腻衣裳。
谷鸟鸣还艳，山夫到更狂。
可怜游赏地，炀帝国倾亡。','',''),('quantangshi-26806','扬州春词三首 三','姚合','quantangshi','','卷27','江北烟光里，淮南胜事多。
市鄽持烛入，邻里漾船过。
有地惟栽竹，无家不养鹅。
春风荡城郭，满耳是笙歌。','',''),('quantangshi-26807','寒食二首 一','姚合','quantangshi','','卷27','今朝一百五，出户雨初晴。
舞爱双飞蝶，歌闻百啭莺。
江深青草岸，花满白云城。
为政多孱懦，应无酷吏名。','',''),('quantangshi-26808','寒食二首 二','姚合','quantangshi','','卷27','出城烟火少，况复是今朝。
闲坐将谁语，临觞只自谣。
堦前春藓徧，衣上落花飘。
伎乐州人戏，使君心寂寥。','',''),('quantangshi-26809','暮春书事','姚合','quantangshi','','卷27','穷巷少芳菲，苍苔一径微。
酒醒闻客别，年长送春归。
宿愿眠云峤，浮名系锁闱。
未因丞相庇，难得脱朝衣。','',''),('quantangshi-26810','春晚雨中','姚合','quantangshi','','卷27','寂寂春将老，闲人强自欢。
迎风莺语涩，带雨蝶飞难。
傍砌木初长，眠花景渐阑。
临轩平目望，情思若为宽。','',''),('quantangshi-26811','送春','姚合','quantangshi','','卷27','昨迎今复送，来晚去逡巡。
芳尽空繁树，愁多独病身。
静思倾酒嬾，闲望上楼频。
为向春风道，明年早报春。','',''),('quantangshi-26812','别春','姚合','quantangshi','','卷27','留春不得被春欺，春若无情遣泥谁。
寂寞自疑生冷病，凄凉还似别亲知。
随风未辨归何处，浇酒唯求住少时。
一去近当三百日，从朝至夜是相思。','',''),('quantangshi-26813','夏夜','姚合','quantangshi','','卷27','闲斋深夜静，独坐又闲行。
密树月笼影，疎篱水隔声。
断猨时叫谷，栖鸟每摇柽。
寂寞求名士，谁知此夕情。','',''),('quantangshi-26814','秋日有怀','姚合','quantangshi','','卷27','秋来不复眠，但觉思悠然。
菊色欲经露，虫声渐替蝉。
诗情生酒里，心事在山边。
旧里无因到，西风又一年。','',''),('quantangshi-26815','秋夕遣怀','姚合','quantangshi','','卷27','昨宵白露下，秋气满山城。
风劲衣巾脆，窗虚笔墨轻。
临书爱真迹，避酒怕狂名。
祗拟随麋鹿，悠悠过一生。','',''),('quantangshi-26816','秋中夜坐','姚合','quantangshi','','卷27','疎散永无事，不眠常夜分。
月中松露滴，风引鹤同闻。','',''),('quantangshi-26817','同卫尉崔少卿九月六日饮','姚合','quantangshi','','卷27','酒熟菊还芳，花飘盏亦香。
与君先一醉，举世待重阳。
风色初晴利，虫声向晚长。
此时如不饮，心事亦应伤。','',''),('quantangshi-26818','九日忆砚山旧居','姚合','quantangshi','','卷27','帝里闲人少，谁同把酒杯。
砚山篱下菊，今日几枝开。
晓角惊眠起，秋风引病来。
长年归思切，更值雁声催。','',''),('quantangshi-26819','秋晚江次','姚合','quantangshi','','卷27','萧萧晚景寒，独立望江壖。
沙渚几行雁，风湾一只船。
落霞澄返照，孤屿隔微烟。
极目思无尽，乡心到眼前。','',''),('quantangshi-26820','除夜二首 一','姚合','quantangshi','','卷27','衰残归未遂，寂寞此宵情。
旧国当千里，新年隔数更。
寒犹近北峭，风渐向东生。
谁见长安陌，晨钟度火城。','',''),('quantangshi-26821','除夜二首 二','姚合','quantangshi','','卷27','殷勤惜此夜，此夜在逡巡。
烛尽年还别，鸡鸣老更新。
傩声方去疫，酒色已迎春。
明日持杯处，谁为最后人。','',''),('quantangshi-26822','晦日送穷三首 一','姚合','quantangshi','','卷27','年年到此日，沥酒拜街中。
万户千门看，无人不送穷。','',''),('quantangshi-26823','晦日送穷三首 二','姚合','quantangshi','','卷27','送穷穷不去，相泥欲何为。
今日官家宅，淹留又几时。','',''),('quantangshi-26824','晦日送穷三首 三','姚合','quantangshi','','卷27','古人皆恨别，此别恨消魂。
只是空相送，年年不出门。','',''),('quantangshi-26825','咏云','姚合','quantangshi','','卷27','霭霭纷纷不可穷，戛笙歌处尽随龙。
来依银汉一千里，归傍巫山十二峰。
呈瑞每闻开丽色，避风仍见挂乔松。
怜君翠染双蝉鬓，镜里朝朝近玉容。','',''),('quantangshi-26826','咏雪','姚合','quantangshi','','卷27','愁云残腊下阳台，混却干坤六出开。
与月交光呈瑞色，共花争艳傍寒梅。
飞随郢客歌声远，散逐宫娥舞袖回。
其那知音不相见，剡溪乘兴为君来。','',''),('quantangshi-26827','郡中对雪','姚合','quantangshi','','卷27','霏微着草树，渐布与阶平。
远近如空色，飘扬无落声。
飞鸦疑翅重，去马觉蹄轻。
遥想故山下，樵夫应滞行。','',''),('quantangshi-26828','对月','姚合','quantangshi','','卷27','银轮玉兔向东流，莹净三更正好游。
一片黑云何处起，皂罗笼却水精球。','',''),('quantangshi-26829','八月十五夜看月','姚合','quantangshi','','卷27','亭亭千万里，三五复秋中。
此夕光应绝，常时思不同。
九霄微有露，四海静无风。
惆怅逡巡别，谁能看碧空。','',''),('quantangshi-26830','赋月华临静夜','姚合','quantangshi','','卷27','长空埃𡏖灭，皎皎月华临。
色正秋将半，光鲜夜自深。
九霄晴更彻，四野气难侵。
静照遥山出，孤明列宿沈。
高人应不寐，惊鹊复何心。','',''),('quantangshi-26831','酬任畴协律夏中苦雨见寄','姚合','quantangshi','','卷27','银汉波澜溢，经旬雨未休。
细听宜隔牖，远望忆高楼。
风急飘还断，云低落更稠。
走童惊掣电，饥鸟啄浮沤。
丝网张空际，蛛绳续瓦沟。
青蛙多入户，潢潦欲胜舟。
雷怒疑山破，池浑似土流。
灰人漫禳厌，水马恣沈浮。
广陌应翻浪，贫居恐作湫。
阳精藏不耀，阴气盛难收。
远色重林暮，繁声四壁秋。
望晴思见日，防冷欲披裘。
枕润眠还嬾，车羸出转忧。
散空烟漠漠，迸溜竹修修。
树暗蝉吟咽，巢倾燕语愁。
琴书凉簟净，灯烛夜窗幽。
天下那能向，龙边岂易求。
湿烟凝竈额，荒草覆墙头。
酒思凄方罢，诗情耿始抽。
下牀先仗屐，汲井恐飘瓯。
危坐徒相忆，佳期未有由。
劳君寄新什，终日不能酬。','',''),('quantangshi-26832','和座主相公雨中作','姚合','quantangshi','','卷27','清气润华屋，东风吹雨匀。
花低惊艳重，竹净觉声真。
山际凝如雾，云中散似尘。
萧萧下碧落，点点救生民。
缓洒雷霆细，微霑瓦砾新。
诗成难继和，造化笔通神。','',''),('quantangshi-26833','恶神行雨','姚合','quantangshi','','卷27','凶神扇𥳽恶神行，汹涌挨排白雾生。
风击水凹波扑凸，雨漴山口地嵌坑。
龙喷黑气翻腾滚，鬼掣红光劈划揁。
哮吼忽雷声揭石，满天啾唧闹轰轰。','',''),('quantangshi-26834','苦雨','姚合','quantangshi','','卷27','江昏山半晴，南阻绝人行。
葭菼连云色，松杉共雨声。
早秋仍燕舞，深夜更鼍鸣。
为报迷津客，讹言未可轻。','',''),('quantangshi-26835','题凤翔西郭新亭','姚合','quantangshi','','卷27','西郭尘埃外，新亭制度奇。
地形当要处，人力是闲时。
结构方殊绝，高低更合宜。
栋梁清俸买，松竹远山移。
佛寺幽难敌，仙家景可追。
良工慙巧尽，上客恨逢迟。
两面寒波涨，当前软柳垂。
清虚宜月入，凉冷胜风吹。
宴赏军容静，登临妓乐随。
鱼龙听弦管，凫鹤识旌旗。
泛鷁春流阔，飞觞白日欹。
闲花长在户，嫩藓乍缘墀。
永望情无极，频来困不辞。
云峰晴转翠，烟树晓逾滋。
向野惟贪静，临空遽觉危。
行人如不到，游乐更何为。','',''),('quantangshi-26836','题金州西园九首 江榭','姚合','quantangshi','','卷27','亭亭白云榭，下有清江流。
见江不得亲，不如波上鸥。
有榭江可见，无榭无双眸。','',''),('quantangshi-26837','题金州西园九首 药堂','姚合','quantangshi','','卷27','僮仆不到阈，双扉常自关。
四壁画远水，堂前耸秋山。
时闻有仙鼠，窃药檐隙间。','',''),('quantangshi-26838','题金州西园九首 草阁','姚合','quantangshi','','卷27','编草覆柏椽，轩扉皆竹织。
合成似僧居，学僧居未得。
有时公府劳，还复来此息。','',''),('quantangshi-26839','题金州西园九首 松坛','姚合','quantangshi','','卷27','盘盘松上盖，下覆青石坛。
月中零露垂，日出露尚漙。
山翁称绝境，海桥无所观。','',''),('quantangshi-26840','题金州西园九首 葼径','姚合','quantangshi','','卷27','药院径亦高，往来踏葼影。
方当繁暑日，草屩微微冷。
爱此不能行，折薪坐煎茗。','',''),('quantangshi-26841','题金州西园九首 垣竹','姚合','quantangshi','','卷27','种竹爱庭际，亦以资玩赏。
穷秋雨萧条，但见墙垣长。
宣尼高数仞，固应非土壤。','',''),('quantangshi-26842','题金州西园九首 石庭','姚合','quantangshi','','卷27','布石满山庭，磷磷洁还清。
幽人常履此，月下屐齿鸣。
药草枝叶动，似向山中生。','',''),('quantangshi-26843','题金州西园九首 莓苔','姚合','quantangshi','','卷27','茅堂阶岂高，数寸是苔藓。
只恐秋雨中，窗户亦不溅。
眼前无此物，我情何由遣。','',''),('quantangshi-26844','题金州西园九首 芭蕉屏','姚合','quantangshi','','卷27','芭蕉丛丛生，月照参差影。
数叶大如墙，作我门之屏。
稍稍闻见稀，耳目得安静。','',''),('quantangshi-26845','杏溪十首 杏溪','姚合','quantangshi','','卷27','桃花四散飞，桃子压枝垂。
寂寂青阴里，幽人举步迟。
殷勤念此径，我去复来谁。','',''),('quantangshi-26846','杏溪十首 莲塘','姚合','quantangshi','','卷27','方塘菡萏高，繁艳相照耀。
幽人夜眠起，忽疑野中烧。
晓寻不知休，白石岸亦峭。','',''),('quantangshi-26847','杏溪十首 架水藤','姚合','quantangshi','','卷27','蒙蒙紫花藤，下复清溪水。
若遣随波流，不如风飘起。
风飘或近堤，随波千万里。','',''),('quantangshi-26848','杏溪十首 石潭','姚合','quantangshi','','卷27','晓向潭上行，夕就潭边宿。
清冷无波澜，潎潎鱼相逐。
钓翁坐不起，见我往来熟。','',''),('quantangshi-26849','杏溪十首 溪路','姚合','quantangshi','','卷27','此路何潇洒，永无公卿迹。
日日多往来，藜杖与桑屐。
路边何所有，磊磊青渌石。','',''),('quantangshi-26850','杏溪十首 望江峰','姚合','quantangshi','','卷27','念昔有此峰，在彼江陵先。
举世未能知，愚亦望同贤。
我来心益闷，欲上天公牋。','',''),('quantangshi-26851','杏溪十首 杏水','姚合','quantangshi','','卷27','不与江水接，自出林中央。
穿花复远水，一山闻杏香。
我来持茗瓯，日屡此来尝。','',''),('quantangshi-26852','杏溪十首 渚上竹','姚合','quantangshi','','卷27','叶叶新春筠，下复清浅流。
微风屡此来，决决复修修。
诗人月下吟，月堕吟不休。','',''),('quantangshi-26853','杏溪十首 枫林堰','姚合','quantangshi','','卷27','森森枫树林，护此石门堰。
杏堤数里余，枫影覆亦徧。
鸬鷀与钓童，质异同所愿。','',''),('quantangshi-26854','杏溪十首 石濑','姚合','quantangshi','','卷27','散漫复潺湲，半砂半和石。
清风波亦无，历历鱼可搦。
我来亦屡久，归路常日夕。','',''),('quantangshi-26855','陕下厉玄侍御宅五题 濯缨溪','姚合','quantangshi','','卷27','旧山宁要去，此有濯缨泉。
晓景松枝覆，秋光月色连。
行寻屐齿尽，坐对角巾偏。
寂寂幽栖处，无妨请俸钱。','',''),('quantangshi-26856','陕下厉玄侍御宅五题 垂钓亭','姚合','quantangshi','','卷27','由钓起茅亭，柴扉复竹楹。
波清见丝影，坐久识鱼情。
白鸟依窗宿，青蒲傍砌生。
欲同渔父舍，须自减逢迎。','',''),('quantangshi-26857','陕下厉玄侍御宅五题 吟诗岛','姚合','quantangshi','','卷27','幽岛藓层层，诗人日日登。
坐危石是榻，吟冷唾成冰。
静对唯秋水，同来但老僧。
竹枝题字处，小篆复谁能。','',''),('quantangshi-26858','陕下厉玄侍御宅五题 竹里径','姚合','quantangshi','','卷27','微径婵娟里，唯闻静者知。
迹深苔长处，步狭笋生时。
高是连幽树，穷应到曲池。
纱巾灵寿杖，行乐复相宜。','',''),('quantangshi-26859','陕下厉玄侍御宅五题 泛觞泉','姚合','quantangshi','','卷27','不上酒家楼，池边日献酬。
杯来转巴字，客坐遶方流。
酹滴苔纹断，泉连石岸秋。
若能山下置，岁晚愿同游。','',''),('quantangshi-26860','题僧院引泉','姚合','quantangshi','','卷27','泉眼高千尺，山僧取得归。
架空横竹引，凿石透渠飞。
洗药溪流浊，浇花雨力微。
朝昏长遶看，护惜似持衣。','',''),('quantangshi-26861','题家园新池','姚合','quantangshi','','卷27','数日自穿池，引泉来近陂。
寻渠通咽处，遶岸待清时。
深好求鱼养，闲堪与鹤期。
幽声听难尽，入夜睡常迟。','',''),('quantangshi-26862','咏盆池','姚合','quantangshi','','卷27','浮萍重叠水团圆，客遶千遭屐齿痕。
莫惊池里寻常满，一井清泉是上源。','',''),('quantangshi-26863','买太湖石','姚合','quantangshi','','卷27','我尝游太湖，爱石青嵯峨。
波澜取不得，自后长咨嗟。
奇哉卖石翁，不傍豪贵家。
负石听苦吟，虽贫亦来过。
贵我辨识精，取价复不多。
比之昔所见，珍怪颇更加。
背面淙注痕，孔隙若琢磨。
水称至柔物，湖乃生壮波。
或云此天生，嵌空亦非他。
气质偶不合，如地生江河。
置之书房前，晓雾常纷罗。
碧光入四邻，墙壁难蔽遮。
客来谓我宅，忽若岩之阿。','',''),('quantangshi-26864','天竺寺殿前立石','姚合','quantangshi','','卷27','补天残片女娲抛，扑落禅门压地坳。
霹雳划深龙旧攫，屈盘痕浅虎新抓。
苔黏月眼风挑剔，尘结云头雨磕敲。
秋至莫言长矻立，春来自有薜萝交。','',''),('quantangshi-26865','杭州观潮','姚合','quantangshi','','卷27','楼有章亭号，涛来自古今。
势连苍海阔，色比白云深。
怒雪驱寒气，狂雷散大音。
浪高风更起，波急石难沈。
鸟惧多遥过，龙惊不敢吟。
坳如开玉穴，危似走琼岑。
但褫千人魄，那知伍相心。
岸摧连古道，洲涨碚丛林。
跳沫山皆湿，当江日半阴。
天然与禹凿，此理遣谁寻。','',''),('quantangshi-26866','题李频新居','姚合','quantangshi','','卷27','赁居求贱处，深僻任人嫌。
盖地花如绣，当门竹胜帘。
劝僧尝药酒，教仆辨书签。
庭际山宜小，休令着石添。','',''),('quantangshi-26867','寄题纵上人院','姚合','quantangshi','','卷27','营营是与非，前乐后还悲。
今世已如此，他生愿似师。
禅房空旦暮，画壁半陈隋。
遶径苍苔迹，幽人来是谁。','',''),('quantangshi-26868','题山寺','姚合','quantangshi','','卷27','千重山崦里，楼阁影参差。
未暇寻僧院，先看置寺碑。
竹深行渐暗，石稳坐多时。
古塔虫蛇善，阴廊鸟雀痴。
云开上界近，泉落下方迟。
为爱青桐叶，因题满树诗。','',''),('quantangshi-26869','题贞女祠','姚合','quantangshi','','卷27','此女骨为土，贞名不可移。
精灵閟何处，苹藻奠空祠。
水石生异状，杉松无病枝。
我来方谢雨，延滞失归期。','',''),('quantangshi-26870','题刑部马员外修行里南街新居','姚合','quantangshi','','卷27','帝里谁无宅，青山秖属君。
闲窗连竹色，幽砌上苔文。
远近高低树，东西南北云。
朝朝常独见，免被四邻分。','',''),('quantangshi-26871','题郭侍郎亲仁里幽居','姚合','quantangshi','','卷27','入门尘外思，苔径药苗间。
洞里应生玉，庭前自有山。
帝城唯此静，朝客更谁闲。
野鹤松中语，时时去复还。','',''),('quantangshi-26872','题宣义池亭','姚合','quantangshi','','卷27','春入池亭好，风光暖更鲜。
寻芳行不困，逐胜坐还迁。
细草乱如发，幽禽鸣似弦。
苔文翻古篆，石色学秋天。
花落能漂酒，萍开解避船。
暂来还愈疾，久住合成仙。
迸笋搘堦起，垂藤压树偏。
此生应借看，自计买无钱。','',''),('quantangshi-26873','题薛十二池亭','姚合','quantangshi','','卷27','每日树边消一日，遶池行过又须行。
异花多是非时有，好竹皆当要处生。
斜立小桥看岛势，远移幽石作泉声。
浮萍着岸风吹歇，水面无尘晚更清。','',''),('quantangshi-26874','题大理崔少卿驸马林亭','姚合','quantangshi','','卷27','每来归意懒，都尉似山人。
台榭栖双鹭，松篁隔四邻。
迸泉清胜雨，深洞暖如春。
更看题诗处，前轩粉壁新。','',''),('quantangshi-26875','题杭州南亭','姚合','quantangshi','','卷27','旧隐即云林，思归日日深。
如今来此地，无复有前心。
古石生灵草，长松栖异禽。
暮潮檐下过，溅浪湿衣襟。','',''),('quantangshi-26876','题郑驸马林亭','姚合','quantangshi','','卷27','东园连宅起，胜事与心期。
幽洞自生药，新篁迸入池。
密林行不尽，芳草坐难移。
石翠疑无质，莺歌似有词。
莎台高出树，藓壁净题诗。
我独多来赏，九衢人不知。','',''),('quantangshi-26877','题厉玄侍御所居','姚合','quantangshi','','卷27','幽栖一亩宫，清峭似山峰。
邻里不通径，俸钱唯买松。
野人时寄宿，谷鸟自相逢。
朝路牀前是，谁知晓起慵。','',''),('quantangshi-26878','题田将军宅','姚合','quantangshi','','卷27','焚香书院最风流，莎草缘墙绿藓秋。
近砌别穿浇药井，临街新起看山楼。
栖禽恋竹明犹在，闲客观花夜未休。
好是暗移城里宅，清凉浑得似江头。','',''),('quantangshi-26879','题崔驸马宅','姚合','quantangshi','','卷27','心在林泉身在城，凤凰楼下得闲名。
洞中见凿寻仙路，月里犹烧煮药铛。
数树异花皆敕赐，并竿修竹自天生。
诗人多说离君宅，不得青苔地上行。','',''),('quantangshi-26880','题河上亭','姚合','quantangshi','','卷27','亭亭河上亭，鱼踯水禽鸣。
九曲何时尽，千峰今日清。
晨光秋更远，暑气夏常轻。
杯里移樯影，琴中有浪声。
岸莎连砌静，渔火入窗明。
来此多沈醉，神高无宿酲。','',''),('quantangshi-26881','题长安薛员外水阁','姚合','quantangshi','','卷27','亭亭新阁成，风景益鲜明。
石尽太湖色，水多湘渚声。
翠筠和粉长，零露逐荷倾。
时倚高窗望，幽寻小径行。
林疎看鸟语，池近识鱼情。
政暇招闲客，唯将酒送迎。','',''),('quantangshi-26882','题梁国公主池亭','姚合','quantangshi','','卷27','平阳池馆枕秦川，门鏁南山一带烟。
素柰花开西子面，绿榆枝种沈郎钱。
装帘玳瑁随风落，庭岸䴔䴖趁暖眠。
寂寞空余歌舞地，玉箫惊起凤归天。','',''),('quantangshi-26883','寄题尉迟少卿郊居','姚合','quantangshi','','卷27','卿仕在关东，林居思不穷。
朝衣挂壁上，廐马放田中。
隅坐唯禅子，随行只药童。
砌莎留宿露，庭竹出清风。
浓翠生苔点，辛香发桂丛。
莲池伊水入，石径远山通。
愚者心还静，高人迹自同。
无能相近住，终日羡邻翁。','',''),('quantangshi-26884','题永城驿','姚合','quantangshi','','卷27','秋赋春还计尽违，自知身是拙求知。
惟思旷海无休日，却喜孤舟似去时。
连浦一程兼汴宋，夹堤千柳杂唐隋。
从来此恨皆前达，敢负吾君作楚词。','',''),('quantangshi-26885','过张邯郸庄','姚合','quantangshi','','卷27','客行长似病，烦热束四肢。
到君读书堂，忽若逢良医。
堂前水交流，堂下树交枝。
两门延风凉，洗我昏浊肌。
与子还往熟，坐卧恣所宜。
时时相献酬，文字当酒巵。
野饭具藜藿，永日亦不饥。
苟飡非其所，鲙炙为蒺藜。
时清士人闲，耕作唯文词。
岂独乡里荐，当取四海知。','',''),('quantangshi-26886','过杨处士幽居','姚合','quantangshi','','卷27','引水穿风竹，幽声胜远溪。
裁衣延野客，翦翅养山鸡。
酒熟听琴酌，诗成削树题。
惟愁春气暖，松下雪和泥。','',''),('quantangshi-26887','过李处士山居','姚合','quantangshi','','卷27','闲居昼掩扉，门柳荫蔬畦。
因病方收药，寻僧始度溪。
少逢人到户，时有燕衔泥。
萧洒身无事，名高孰与齐。','',''),('quantangshi-26888','过无可僧院','姚合','quantangshi','','卷27','忆师眠复起，永夜思迢迢。
月下门方掩，林中寺更遥。
钟声空下界，池色在清宵。
终拟修禅观，窗间卷欲烧。','',''),('quantangshi-26889','过稠上人院','姚合','quantangshi','','卷27','清羸一饭师，闲院亦披衣。
应诏常翻译，修心出是非。
雪中疎磬度，林际晚风归。
蔬食常来此，人间护净稀。','',''),('quantangshi-26890','过不疑上人院','姚合','quantangshi','','卷27','九经通大义，内典自应精。
帘冷连松影，苔深减覆声。
相逢幸此日，相失恐来生。
觉路何门去，师须引我行。','',''),('quantangshi-26891','过昙花宝上人院','姚合','quantangshi','','卷27','九陌最幽寺，吾师院复深。
烟霜同覆屋，松竹杂成林。
鸟语境弥寂，客来机自沈。
早知能到此，应不戴朝簪。','',''),('quantangshi-26892','过杜氏江亭','姚合','quantangshi','','卷27','上国千余里，逢春且胜游。
暂闻新鸟戏，似解旅人愁。
野色吞山尽，江烟衬水流。
村醪须一醉，无恨滞行舟。','',''),('quantangshi-26893','过张云峰院宿','姚合','quantangshi','','卷27','不吃胡麻饭，杯中自得仙。
隔篱招好客，扫室置芳筵。
家酝香醪嫩，时新异果鲜。
夜深唯畏晓，坐稳岂思眠。
棊罢嫌无敌，诗成贵在前。
明朝题壁上，谁得众人传。','',''),('quantangshi-26894','过钦上人院','姚合','quantangshi','','卷27','有相无相身，唯师说始真。
修篁半庭影，清磬几僧邻。
古壁丹青落，虚檐鸟雀驯。
伊余求了义，羸马往来频。','',''),('quantangshi-26895','过无可上人院','姚合','quantangshi','','卷27','寥寥听不尽，孤磬与疎钟。
烦恼师长别，清凉我暂逢。
蚁行经古藓，鹤毳落深松。
自想归时路，尘埃复几重。','',''),('quantangshi-26896','过城南僧院','姚合','quantangshi','','卷27','寺对远山起，幽居仍是师。
斜阳通暗隙，残雪落疎篱。
松静鹤栖定，廊虚钟尽迟。
朝朝趋府吏，来此是相宜。','',''),('quantangshi-26897','过灵泉寺','姚合','quantangshi','','卷27','偶寻灵迹去，幽径入氲氛。
转壑惊飞鸟，穿山踏乱云。
水从岩下落，溪向寺前分。
释子游何处，空堂日渐曛。','',''),('quantangshi-26898','过天津桥晴望','姚合','quantangshi','','卷27','闲立津桥上，寒光动远林。
皇宫对嵩顶，清洛贯城心。
雪路初晴出，人家向晚深。
自从王在镐，天宝至如今。','',''),('quantangshi-26899','春日游慈恩寺','姚合','quantangshi','','卷27','年长归何处，青山未有家。
赏春无酒饮，多看寺中花。','',''),('quantangshi-26900','游天台上方','姚合','quantangshi','','卷27','晓上上方高处立，路人羡我此时身。
白云向我头上过，我更羡他云路人。','',''),('quantangshi-26901','游终南山','姚合','quantangshi','','卷27','策杖度溪桥，云深步数劳。
青猿吟岭际，白鹤坐松梢。
天外浮烟远，山根野水交。
自缘名利系，好此结蓬茆。','',''),('quantangshi-26902','游杏溪兰若','姚合','quantangshi','','卷27','踏得度溪湾，晨游暮不还。
月明松影路，春满杏花山。
戏狖跳林末，高僧住石间。
未肯离腰组，来此复何颜。','',''),('quantangshi-26903','游谢公亭','姚合','quantangshi','','卷27','行行方避梦，又到谢亭来。
举世皆如此，伊余何处回？
竹鲜多透石，泉洁亦无苔。
坐与僧同语，谁能顾酒杯。','',''),('quantangshi-26904','游阳河岸','姚合','quantangshi','','卷27','终日游山困，今朝始傍河。
寻芳愁路尽，逢景畏人多。
鸟语催沽酒，鱼来似听歌。
醉时眠石上，肢体自婆娑。','',''),('quantangshi-26905','游河桥晓望','姚合','quantangshi','','卷27','闲上津桥立，天涯一望间。
秋风波上岸，旭日气连山。
偶圣今方变，朝宗岂复还。
昆仑在蕃界，作将亦何颜。','',''),('quantangshi-26906','秋夜月中登天坛','姚合','quantangshi','','卷27','秋蟾流异彩，斋洁上坛行。
天近星辰大，山深世界清。
仙飙石上起，海日夜中明。
何计长来此，闲眠过一生。','',''),('quantangshi-26907','游昊天玄都观','姚合','quantangshi','','卷27','性同相见易，紫府共闲行。
阴径红桃落，秋坛白石生。
藓文连竹色，鹤语应松声。
风定药香细，树声泉气清。
垂檐灵草影，遶壁古山名。
围外坊无禁，归时踏月明。','',''),('quantangshi-26908','同裴起居厉侍御放朝游曲江','姚合','quantangshi','','卷27','暑月放朝频，青槐路绝尘。
雨晴江色出，风动草香新。
独立分幽岛，同行得静人。
此欢宜稍滞，此去与谁亲。','',''),('quantangshi-26909','晓望华清宫','姚合','quantangshi','','卷27','晓看楼殿更鲜明，遥隔朱栏见鹿行。
武帝自知身不死，教修玉殿号长生。','',''),('quantangshi-26910','夏日登楼晚望','姚合','quantangshi','','卷27','避暑高楼上，平芜望不穷。
鸟穿山色去，人歇树阴中。
数带长河水，千条弱柳风。
暗思多少事，懒话与芝翁。','',''),('quantangshi-26911','霁后登楼','姚合','quantangshi','','卷27','高楼初霁后，远望思无穷。
雨洗青山净，春蒸大野融。
碧池舒暖景，若柳嚲和风。
为有登临兴，独吟落照中。','',''),('quantangshi-26912','早夏郡楼宴集','姚合','quantangshi','','卷27','官散有闲情，登楼步稍轻。
窗云带雨气，林鸟杂人声。
晓日襟前度，微风酒上生。
城中会难得，扫壁各书名。','',''),('quantangshi-26913','夜宴太仆田卿宅','姚合','quantangshi','','卷27','故人九寺长，邀我此同欢。
永夜开筵静，中年饮酒难。
微风侵烛影，叠漏过林端。
腊后分朝日，天明几刻残。','',''),('quantangshi-26914','春日同会卫尉崔少卿宅','姚合','quantangshi','','卷27','诗家会诗客，池阁晓初晴。
鸟尽山中语，琴多谱外声。
映花相劝酒，入洞各题名。
疎野常如此，谁人信在城。','',''),('quantangshi-26915','军城夜会','姚合','quantangshi','','卷27','军城夜禁乐，饮酒每题诗。
坐稳吟难尽，寒多醉较迟。
远钟惊漏压，微月被灯欺。
此会诚堪惜，天明是别离。','',''),('quantangshi-26916','晦日宴刘值录事宅','姚合','quantangshi','','卷27','花落莺飞深院静，满堂宾客尽诗人。
城中杯酒家家有，唯是君家酒送春。','',''),('quantangshi-26917','宴光禄田卿宅','姚合','quantangshi','','卷27','竹里开华馆，珍羞次第尝。
春风酒影动，晴日乐声长。
久坐难辞醉，衰年亦暂狂。
殷勤还继烛，永夕梦相妨。','',''),('quantangshi-26918','会将作崔监东园','姚合','quantangshi','','卷27','墙北走红尘，墙东接白云。
山光衣上见，药气酒中闻。
此会诚堪惜，穷秋日又曛。
人间唯有醉，醉后复何云。','',''),('quantangshi-26919','同诸公会太府韩卿宅','姚合','quantangshi','','卷27','九寺名卿才思雄，邀欢笔下与杯中。
六街鼓绝尘埃息，四座筵开语笑同。
焰焰兰缸明狭室，丁丁玉漏发深宫。
即听鸡唱天门晓，吏事相牵西复东。','',''),('quantangshi-26920','乞酒','姚合','quantangshi','','卷27','闻君有美酒，与我正相宜。
溢瓮清如水，黏杯半似脂。
岂唯消旧病，且要引新诗。
况此便便腹，无非是满巵。','',''),('quantangshi-26921','寄卫拾遗乞酒','姚合','quantangshi','','卷27','老人罢巵酒，不醉已经年。
自饮君家酒，一杯三日眠。
味轻花上露，色似洞中泉。
莫厌时时寄，须知法未传。','',''),('quantangshi-26922','乞新茶','姚合','quantangshi','','卷27','嫩绿微黄碧涧春，采时闻道断荤辛。
不将钱买将诗乞，借问山翁有几人。','',''),('quantangshi-26923','西掖寓直春晓闻残漏','姚合','quantangshi','','卷27','直庐仙掖近，春气曙犹寒。
隐隐银河在，丁丁玉漏残。
微风飘更切，万籁杂应难。
凤阁明初启，鸡人唱渐阑。
静宜来禁里，清是下云端。
我识朝天路，从容自整冠。','',''),('quantangshi-26924','杭州郡斋南亭','姚合','quantangshi','','卷27','符印悬腰下，东山不得归。
独行南北近，渐老往还稀。
迸笋侵窗长，惊蝉出树飞。
田田池上叶，长是使君衣。','',''),('quantangshi-26925','郡中西园','姚合','quantangshi','','卷27','西园春欲尽，芳草径难分。
静语唯幽鸟，闲眠独使君。
密林生雨气，古石带潮文。
虽去清秋远，朝朝见白云。','',''),('quantangshi-26926','杭州官舍偶书','姚合','quantangshi','','卷27','钱塘刺史谩题诗，贫褊无恩懦少威。
春尽酒杯花影在，潮回画槛水声微。
闲吟山际邀僧上，暮入林中看鹤归。
无术理人人自理，朝朝渐觉簿书稀。','',''),('quantangshi-26927','省直书事','姚合','quantangshi','','卷27','默默沧江老，官分右掖荣。
立朝班近殿，奏直上知名。
晓雾和香气，晴楼下乐声。
蜀牋金屑腻，月兔笔毫精。
禁树霏烟覆，宫墙瑞草生。
露盘秋更出，玉漏昼还清。
碧藓无尘染，寒蝉似鸟鸣。
竹深云自宿，天近日先明。
孱懦难封诏，疎愚但掷觥。
素飡终日足，宁免众人轻。','',''),('quantangshi-26928','杭州官舍即事','姚合','quantangshi','','卷27','临江府署清，闲卧复闲行。
苔藓疎尘色，梧桐出雨声。
渐除身外事，暗作道家名。
更喜仙山近，庭前药自生。','',''),('quantangshi-26929','假日书事呈院中司徒','姚合','quantangshi','','卷27','十日公府静，巾栉起清晨。
寒蝉近衰柳，古木似高人。
学佛宁忧老，为儒自喜贫。
海山归未得，芝术梦中春。','',''),('quantangshi-26930','书县丞旧厅','姚合','quantangshi','','卷27','宫殿半山上，人家向下居。
古厅眠易魇，老吏语多虚。
雨水浇荒竹，溪沙拥废渠。
圣朝收外府，皆是九天除。','',''),('quantangshi-26931','县中秋宿','姚合','quantangshi','','卷27','鼓绝门方掩，萧条作吏心。
露垂庭际草，萤照竹间禽。
棊罢嫌无月，眠迟听尽砧。
还知未离此，时复更相寻。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-26932','夏夜宿江驿','姚合','quantangshi','','卷27','竹屋临江岸，清宵兴自长。
夜深倾北斗，叶落映横塘。
渚闹渔歌响，风和角糉香。
却愁南去棹，早晚到潇湘。','',''),('quantangshi-26933','陕城即事','姚合','quantangshi','','卷27','左右分京阙，黄河与宅连。
何功来此地，窃位已经年。
天下才弥小，关中镇最先。
陇山望可见，惆怅是穷边。','',''),('quantangshi-26934','和东都令狐留守相公','姚合','quantangshi','','卷27','除官东守洛阳宫，恩比藩方任更雄。
拜表出时传七刻，排班衙日有三公。
旌旗严重临关外，庭宇清深接禁中。
三十六峰诗酒思，朝朝闲望与谁同。','',''),('quantangshi-26935','和高谏议蒙兼宾客时入翰苑','姚合','quantangshi','','卷27','兼秩恩归第一流，时寻仙路向瀛洲。
钟声迢递银河晓，林色葱笼玉露秋。
紫殿讲筵邻御座，青宫宾榻入龙楼。
从来共结归山侣，今日多应独自休。','',''),('quantangshi-26936','和卢给事酬裴员外','姚合','quantangshi','','卷27','南山雪色彻皇州，钟鼓声交晓气浮。
鸳鹭簪裾上龙尾，蓬莱宫殿压鳌头。
夕郎夜直吟仙掖，天乐和声下禁楼。
赠答诗成才思敌，病夫欲和几朝愁。','',''),('quantangshi-26937','和裴结端公早朝','姚合','quantangshi','','卷27','鱼钥千门启，鸡人唱晓传。
冕旒临玉殿，丞相入炉烟。
列位同居左，分行忝在前。
仰闻天语近，俯拜佩声连。
彩杖祥光动，彤庭霁色鲜。
威仪谁可纪，柱史有新篇。','',''),('quantangshi-26938','和门下李相饯西蜀相公','姚合','quantangshi','','卷27','圣朝同舜日，作相有夔龙。
理化知无外，烝黎尽可封。
燮和皆达识，出入并登庸。
武骑增余勇，儒冠贵所从。
赠诗全六义，出镇越千峰。
连日陈天乐，芳筵叠酒钟。
乌台情已洽，凤阁分弥浓。
栈转旌摇水，崖高马蹋松。
恩深施远俗，化美见前踪。
江晓流巴字，山晴耸剑峰。
双油拥上宰，四海羡临邛。
先路声华远，离京诏旨重。
岁除今向尽，春色即相逢。
嫩叶抽頳蘂，新苔长翠茸。
冰销鱼潎潎，林暖鸟噰噰。
泉落闻难尽，花开看不供。
青城方眷恋，黄阁竟从容。
计日归台席，还听长乐钟。','',''),('quantangshi-26939','和座主相公西亭秋日即事','姚合','quantangshi','','卷27','西亭秋望好，宁要更垂帘。
夫子墙还峻，酇侯宅过谦。
微风红叶下，新雨绿苔黏。
窗外松初长，栏中药旋添。
海图装玉轴，书目记牙签。
竹色晴连地，山光远入檐。
酒浓杯稍重，诗冷语多尖。
属和才虽浅，题高免客嫌。','',''),('quantangshi-26940','和祕书崔少监春日游青龙寺僧院','姚合','quantangshi','','卷27','官清书府足闲时，晓起攀花折柳枝。
九陌城中寻不尽，千峰寺里看相宜。
高人酒味多和药，自古风光只属诗。
见说往来多静者，未知前日更逢谁。','',''),('quantangshi-26941','和李绅助教不赴看花','姚合','quantangshi','','卷27','笑辞聘礼深坊住，门馆长闲似退居。
太学官资清品秩，高人公事说经书。
年华未是登朝晚，春色何因向酒疎。
且看牡丹吟丽句，不知此外复何如。','',''),('quantangshi-26942','和李十二舍人冬至日','姚合','quantangshi','','卷27','献寿人皆庆，南山复北堂。
从今千万日，此日又初长。','',''),('quantangshi-26943','和裴令公新成绿野堂即事','姚合','quantangshi','','卷27','结构立嘉名，轩窗四面明。
丘墙高莫比，萧宅僻还清。
池际龟潜戏，庭前药旋生。
树深檐稍邃，石峭径难平。
道旷襟情远，神闲视听精。
古今功独出，大小隐俱成。
曙雨新苔色，秋风长桂声。
携诗就竹写，取酒对花倾。
古寺招僧饭，方塘看鹤行。
人间无此贵，半仗暮归城。','',''),('quantangshi-26944','和厉玄侍御题户部李相公庐山西林草堂','姚合','quantangshi','','卷27','茅屋临江起，登庸复应期。
遥知归去日，自致太平时。
幽药禅僧护，高窗宿鸟窥。
行人尽歌咏，唯子独能诗。','',''),('quantangshi-26945','和郑相演杨尚书蜀中唱和诗','姚合','quantangshi','','卷27','天福坤维厚，忠贤拥节旄。
江同渭滨远，山似傅岩高。
元气符才格，文星照笔毫。
五言全丽则，六义出风骚。
圣日麻双下，洪炉柄共操。
宠荣连雨露，先后比萧曹。
唱绝时难和，吟多客讵劳。
四方虽纸贵，谁怕费钱刀。','',''),('quantangshi-26946','和户部侍郎省中晚归','姚合','quantangshi','','卷27','寒日南宫晚，闲吟半醉归。
位高行路静，诗好和人稀。
古树苔文匝，遥峰雪色微。
宁知逢彩笔，寂寞有光辉。','',''),('quantangshi-26947','和元八郎中秋居','姚合','quantangshi','','卷27','圣代无为化，郎中似散仙。
晚眠随客醉，夜坐学僧禅。
酒用林花酿，茶将野水煎。
人生知此味，独恨少因缘。','',''),('quantangshi-26948','和李十二舍人裴四二舍人两阁老酬白少傅见寄','姚合','quantangshi','','卷27','罢草王言星岁久，嵩高山色日相亲。
萧条雨夜吟连晓，撩乱花时看尽春。
此世逍遥应独得，古来闲散有谁邻。
林中长老呼居士，天下书生仰达人。
酒挈数瓶杯亦阔，诗成千首语皆新。
纶闱竝命诚宜贺，不念衰年寄上频。','',''),('quantangshi-26949','和刘禹锡主客冬初拜表怀上都故人','姚合','quantangshi','','卷27','九陌喧喧骑吏催，百官拜表禁城开。
林疎晓日明红叶，尘静寒霜覆绿苔。
玉佩声微班始定，金函光动按初来。
此时共想朝天客，谢食方从阁里回。','',''),('quantangshi-26950','和太仆田卿酬殷尧藩侍御见寄','姚合','quantangshi','','卷27','往还知分熟，酬赠思同新。
嗜饮殷偏逸，闲吟卿亦贫。
古苔寒更翠，修竹静无邻。
促席灯浮酒，听鸿霜满身。
浅才唯是我，高论更何人。
携手宜相访，穷行少路尘。','',''),('quantangshi-26951','和膳部李郎中秋夕','姚合','quantangshi','','卷27','淅淅复修修，凉风似水流。
此生难免老，举世大同愁。
萤影明苔藓，鸿声傍斗牛。
犹分省署直，何日是归休。','',''),('quantangshi-26952','和前吏部韩侍郎夜泛南溪','姚合','quantangshi','','卷27','辞得官来疾渐平，世间难有此高情。
新秋月满南溪里，引客乘船处处行。','',''),('quantangshi-26953','和王郎中题华州李中丞厅','姚合','quantangshi','','卷27','莲华峰下郡斋前，遶砌穿池贮瀑泉。
君到亦应闲不得，主人草圣复诗仙。','',''),('quantangshi-26954','和厉玄侍御无可上人会宿见寄','姚合','quantangshi','','卷27','九衢难会宿，况复是寒天。
朝客清贫老，林僧默悟禅。
眠迟消漏水，吟苦堕寒涎。
异日来寻我，沧江有钓船。','',''),('quantangshi-26955','和令狐六员外直夜即事寄上相公','姚合','quantangshi','','卷27','霜台同处轩窗接，粉署先登语笑疎。
皓月满帘听玉漏，紫泥盈手发天书。
吟诗清美招闲客，对酒逍遥卧直庐。
荣贵人间难有比，相公离此十年余。','',''),('quantangshi-26956','答孟侍御早朝见寄','姚合','quantangshi','','卷27','河倾月向西，九陌鼓声齐。
尘静霜华远，烟生曙色低。
禁门人已度，宫树鸟犹栖。
疎懒劳相问，登山有旧梯。','',''),('quantangshi-26957','和友人新居园上','姚合','quantangshi','','卷27','新居多野思，不似在京城。
墙上云相压，庭前竹乱生。
寻师望药力，依谱上琴声。
好是中秋夜，无尘有月明。','',''),('quantangshi-26958','和裴令公游南庄忆白二十韦七二宾客','姚合','quantangshi','','卷27','四郊初雨歇，高树滴犹残。
池满红莲湿，云收绿野宽。
花开半山晓，竹动数村寒。
鬬雀翻衣袂，惊鱼触钓竿。
罇前多野客，膝下尽郎官。
斸石通泉脉，移松出药栏。
关东分务重，天下似公难。
半醉思韦白，题诗染彩翰。','',''),('quantangshi-26959','和李舍人秋日卧疾言怀','姚合','quantangshi','','卷27','闲卧襟情远，西风菊渐芳。
虚窗通晓景，珍簟卷秋光。
果坠青莎径，尘离绿藓墙。
药匳开静室，书阁出丛篁。
对酒吟难尽，思山梦稍长。
王言生彩笔，朝服惹炉香。
松影幽连砌，虫声冷到牀。
诗成谁敢和，清思若怀霜。','',''),('quantangshi-26960','和李十二舍人直日放朝对雪','姚合','quantangshi','','卷27','今朝街鼓何人听，朝客开门对雪眠。
岂比直庐丹禁里，九重天近色弥鲜。','',''),('quantangshi-26961','答李频秀才','姚合','quantangshi','','卷27','一年离九陌，壁上挂朝袍。
物外诗情远，人间酒味高。
思归知病长，失寝觉神劳。
衰老无多思，因君把笔毫。','',''),('quantangshi-26962','答胡遇','姚合','quantangshi','','卷27','一会一分离，贫游少定期。
酒多为客稳，米贵入城迟。
晴日偷将睡，秋山乞与诗。
纵然眉得展，不似见君时。','',''),('quantangshi-26963','答友人招游','姚合','quantangshi','','卷27','不来知尽怪，失意懒春游。
闻鸟宁惊梦，看花怕引愁。
赌棋招敌手，沽酒自扶头。
何似华筵上，推辞候到筹。','',''),('quantangshi-26964','答窦知言','姚合','quantangshi','','卷27','冬日易惨恶，暴风拔山根。
尘沙落黄河，浊波如地翻。
飞鸟皆束翼，居人不开门。
独我赴省期，冒此驰毂辕。
陕城城西边，逢子亦且奔。
所趋事一心，相见如弟昆。
我惨得子舒，我寒得子温。
同行十日程，僮仆性亦敦。
到京人事多，日无闲精魂。
念子珍重我，吐辞发蒙昏。
反复千万意，一百六十言。
格高思清冷，山低济浑浑。
尝闻朋友惠，赠言始为恩。
金玉日消费，好句长存存。
倒篚别收贮，不与俗士论。
每当清夜吟，使我如哀猿。','',''),('quantangshi-26965','酬田就','姚合','quantangshi','','卷27','闲居多僻静，犹恐道相违。
只是夜深坐，那堪春未归。
嫩苔黏野色，香絮扑人衣。
纵有野僧到，终朝不话非。','',''),('quantangshi-26966','酬礼部李员外见寄','姚合','quantangshi','','卷27','本求仙郡是闲居，岂向郎官更有书。
溪石谁思玉匠爱，烟鸿愿与弋人疎。
自来江上眠方稳，旧在城中病悉除。
唯见君诗难便舍，寒宵吟到晓更初。','',''),('quantangshi-26967','酬令狐郎中见寄','姚合','quantangshi','','卷27','昨是儿童今是翁，人间日月急如风。
常闻欲向沧江去，除我无人与子同。','',''),('quantangshi-26968','酬李廓精舍南台望月见寄','姚合','quantangshi','','卷27','看月空门里，诗家境有余。
露寒僧梵出，林静鸟巢疎。
远色当秋半，清光胜夜初。
独无台上思，寂寞守吾庐。','',''),('quantangshi-26969','酬光禄田卿末伏见寄','姚合','quantangshi','','卷27','下伏秋期近，还知扇渐疎。
惊飙坠邻果，暴雨落江鱼。
贵寺虽同秩，闲曹只管书。
朝朝廊下食，相庇在肴葅。','',''),('quantangshi-26970','酬薛奉礼见赠之作','姚合','quantangshi','','卷27','栖栖沧海一耕人，诏遣江边作使君。
山顶雨余青到地，涛头风起白连云。
诗成客见书墙和，药熟僧来就鼎分。
珍重来章相借分，芳名未识已曾闻。','',''),('quantangshi-26971','酬卢汀谏议','姚合','quantangshi','','卷27','粟如流水帛如山，依念仓边语笑间。
篇什纵横文案少，亲朋撩乱吏人闲。
杯觞引满从衣湿，墙壁书多任手顽。
遥贺来年二三月，彩衣先辈过春关。','',''),('quantangshi-26972','酬万年张郎中见寄','姚合','quantangshi','','卷27','贡籍常同府，周行今一时。
谏曹诚已忝，京邑岂相宜。
黑发年来尽，沧江归去迟。
何时得携手，林下静吟诗。','',''),('quantangshi-26973','酬光禄田卿六韵见寄','姚合','quantangshi','','卷27','以病辞朝谒，迂疎种药翁。
心弥念鱼鸟，诏遣理兵戎。
遶户旌旗影，吹人鼓角风。
雪晴嵩岳顶，树老陕城宫。
莅职才微薄，归山路未通。
名卿诗句峭，诮我在关东。','',''),('quantangshi-26974','酬杨汝士尚书喜人移居','姚合','quantangshi','','卷27','未得沧江外，衰残读药书。
圣朝优上秩，仁里许闲居。
树对枝相接，泉同井不疎。
酬章深自鄙，欲寄复踌蹰。','',''),('quantangshi-26975','酬田卿书斋即事见寄','姚合','quantangshi','','卷27','幽斋琴思静，晚下紫宸朝。
旧隐同溪远，周行隔品遥。
深槐蝉唧唧，疎竹雨萧萧。
不是相寻懒，烦君举酒瓢。','',''),('quantangshi-26976','酬张籍司业见寄','姚合','quantangshi','','卷27','日日在心中，青山青桂丛。
高人多爱静，归路亦应同。
罢吏方无病，因僧得解空。
新诗劳见问，吟对竹林风。','',''),('quantangshi-26977','谢汾州田大夫寄茸毡[葡]萄','姚合','quantangshi','','卷27','筐封紫[葡]萄，筒卷白茸毛。
卧暖身应健，含消齿免劳。
衾衣疎不称，梨栗鄙难高。
晓起题诗报，寒澌满笔毫。','',''),('quantangshi-26978','牧杭州谢李太尉德裕','姚合','quantangshi','','卷27','皇恩特许拜杭坛，欲谢旌旄去就难。
偷拟白头瞻画戟，四神俱散发毛寒。','',''),('quantangshi-26979','杏园宴上谢座主','姚合','quantangshi','','卷27','得陪桃李植芳丛，别感生成太昊功。
今日无言春雨后，似含冷涕谢东风。','',''),('quantangshi-26980','谢韬光上人','姚合','quantangshi','','卷27','上方清净无因住，唯愿他生得住持。
只恐无生复无我，不知何处更逢师。','',''),('quantangshi-26981','谢秦校书与无可上人见访','姚合','quantangshi','','卷27','道同无宿约，三伏自从容。
窗豁山侵座，扇摇风下松。
客吟多遶竹，僧饭只凭钟。
向晚分归路，莓苔行迹重。','',''),('quantangshi-26982','喜胡遇至','姚合','quantangshi','','卷27','穷居稀出入，门户满尘埃。
病少闲人问，贫唯密友来。
茅斋从埽破，药酒遣生开。
多事经时别，还愁不宿回。
就林烧嫩笋，遶树拣香梅。
相对题新什，迟成举罚杯。','',''),('quantangshi-26983','喜贾岛至','姚合','quantangshi','','卷27','布囊悬蹇驴，千里到贫居。
饮酒谁堪伴，留诗自与书。
爱眠知不醉，省语似相疎。
军吏衣裳窄，还应暗笑余。','',''),('quantangshi-26984','喜喻凫至','姚合','quantangshi','','卷27','欲出心还懒，闲吟遶寝牀。
道书虫食尽，酒律客偷将。
愁至为多病，贫来减得狂。
见君何所似，如热得清凉。','',''),('quantangshi-26985','喜雍陶秋夜访宿','姚合','quantangshi','','卷27','晓立侍炉烟，夜归蓬荜眠。
露华明菊上，萤影灭灯前。
清漏和砧叠，栖禽与叶连。
高人来此宿，为似在山颠。','',''),('quantangshi-26986','喜贾岛雨中访宿','姚合','quantangshi','','卷27','雨里难逢客，闲吟不复眠。
虫声秋并起，林色夜相连。
爱酒此生里，趋朝未老前。
终须携手去，沧海棹鱼船。','',''),('quantangshi-26987','喜马戴冬夜见过期无可上人不至 一','姚合','quantangshi','','卷27','客来初夜里，药酒自开封。
老渐多归思，贫惟长病容。
苦寒灯焰细，近晓鼓声重。
僧可还相舍，深居闭古松。','',''),('quantangshi-26988','喜马戴冬夜见过期无可上人不至 二','姚合','quantangshi','','卷27','内殿臣相命，开罇话旧时。
夜钟催鸟绝，积雪阻僧期。
林静寒声远，天阴曙色迟。
今宵复何夕，鸣佩坐相随。','',''),('quantangshi-26989','访僧法通不遇','姚合','quantangshi','','卷27','访师师不遇，礼佛佛无言。
依旧将烦恼，黄昏入宅门。','',''),('quantangshi-26990','夜期友生不至','姚合','quantangshi','','卷27','忍寒停酒待君来，酒作凌凘火作灰。
半夜出门重立望，月明先自下高台。','',''),('quantangshi-26991','寻僧不遇','姚合','quantangshi','','卷27','入门愁自散，不假见僧翁。
花落煎茶水，松生醒酒风。
拂牀寻古画，拔刺看新丛。
别有游人见，多疑住此中。','',''),('quantangshi-26992','过友人山庄','姚合','quantangshi','','卷27','蕙带缠腰复野蔬，一庄水竹数房书。
举头忽见南山雪，便说休官相近居。','',''),('quantangshi-26993','奉和前司封苏郎中喜严常侍萧给事见访惊斑鬓之什','姚合','quantangshi','','卷27','遶鬓沧浪有几茎，珥貂相问夕郎惊。
祗应为酒微微变，不是因年渐渐生。
东观诗成号良史，中台官罢揖高名。
即提彩笔裁天诏，谁得吟诗自在行。','',''),('quantangshi-26994','奉和门下相公雨中寄裴给事','姚合','quantangshi','','卷27','晓起闲看雨，垂檐自滴堦。
风清想林壑，云湿似江淮。
石信浮沤重，泥从积藓埋。
气消浓酒力，心助独吟怀。
飒飒通琴韵，萧萧静竹斋。
彩毫无限思，念与夕郎乖。','',''),('quantangshi-26995','答韩湘','姚合','quantangshi','','卷27','疎散无世用，为文乏天格。
把笔日不休，忽忽有所得。
所得良自慰，不求他人识。
子独访我来，致诗过相饰。
君子无浮言，此诗应亦直。
但虑忧我深，鉴亦随之惑。
子在名场中，屡战还屡北。
我无数子明，端坐空叹息。
昨闻过春关，名系吏部籍。
三十登高科，前涂浩难测。
诗人多峭冷，如水在胸臆。
岂随寻常人，五藏为酒食。
期来作酬章，危坐吟到夕。
难为间其辞，益贵我纸墨。','',''),('quantangshi-26996','奉和四松','姚合','quantangshi','','卷27','四松相对植，苍翠映中台。
擢干凌空去，移根斸石开。
阴阳气潜煦，造化手亲栽。
日月滋佳色，烟霄长异材。
清音胜在涧，寒影徧生苔。
静遶霜霑履，闲看酒满杯。
同荣朱户际，永日白云隈。
密叶闻风度，高枝见鹤来。
赏心难可尽，丽什妙难裁。
此地无因到，循环几百回。','',''),('quantangshi-26997','和李补阙曲江看莲花','姚合','quantangshi','','卷27','露荷迎曙发，灼灼复田田。
乍见神应骇，频来眼尚颠。
光凝珠有蒂，焰起火无烟。
粉腻黄丝蘂，心重碧玉钱。
日浮秋转丽，雨洒晚弥鲜。
醉艳酣千朵，愁红思一川。
绿茎扶萼正，翠菂满房圆。
淡晕还殊众，繁英得自然。
高名犹不厌，上客去争先。
景逸倾芳酒，怀浓习彩牋。
海霞宁有态，蜀锦不成妍。
客至应消病，僧来欲破禅。
晓多临水立，夜只傍堤眠。
金似明沙渚，灯疑宿浦船。
风惊丛乍密，鱼戏影微偏。
穠彩烧晴雾，殷姿缬碧泉。
画工投粉笔，宫女弃花钿。
鸟恋惊难起，蜂偷困不前。
遶行香烂熳，折赠意缠绵。
谁计江南曲，风流合管弦。','',''),('quantangshi-26998','和王郎中召看牡丹','姚合','quantangshi','','卷27','葩叠萼相重，烧栏复照空。
妍姿朝景里，醉艳晚烟中。
乍怪霞临砌，还疑烛出笼。
遶行惊地赤，移坐觉衣红。
殷丽开繁朵，香浓发几丛。
裁绡样岂似，染茜色宁同。
嫩畏人看损，鲜愁日炙融。
婵娟涵宿露，烂熳抵春风。
纵赏襟情合，闲吟景思通。
客来归尽懒，莺恋语无穷。
万物珍那比，千金买不充。
如今难更有，纵有在仙宫。','',''),('quantangshi-26999','咏南池嘉莲','姚合','quantangshi','','卷27','芙蓉池里叶田田，一本双花出碧泉。
浓淡共妍香各散，东西分艳蔕相连。
自知政术无他异，纵是祯祥亦偶然。
四野人闻皆尽喜，争来入郭看嘉莲。','',''),('quantangshi-27000','种苇','姚合','quantangshi','','卷27','欲种数茎苇，出门来往频。
近陂收本土，选地问幽人。
静看唯思长，初移未觉匀。
坐中寻竹客，将去更逡巡。','',''),('quantangshi-27001','采松花','姚合','quantangshi','','卷27','拟服松花无处学，嵩阳道士忽相教。
今朝试上高枝采，不觉倾翻仙鹤巢。','',''),('quantangshi-27002','咏新菊','姚合','quantangshi','','卷27','黄金色未足，摘取且尝新。
若待重阳日，何曾异众人。','',''),('quantangshi-27003','杨柳枝词五首 一','姚合','quantangshi','','卷27','黄金丝挂粉墙头，动似颠狂静似愁。
游客见时心自醉，无因得见谢家楼。','',''),('quantangshi-27004','杨柳枝词五首 二','姚合','quantangshi','','卷27','叶叶如眉翠色浓，黄莺偏恋语从容。
桥边陌上无人识，雨湿烟和思万重。','',''),('quantangshi-27005','杨柳枝词五首 三','姚合','quantangshi','','卷27','江上东西离别饶，旧条折尽折新条。
亦知春色人将去，犹胜狂风取次飘。','',''),('quantangshi-27006','杨柳枝词五首 四','姚合','quantangshi','','卷27','二月杨花触处飞，悠悠漠漠自东西。
谢家咏雪徒相比，吹落庭前便作泥。','',''),('quantangshi-27007','杨柳枝词五首 五','姚合','quantangshi','','卷27','江亭杨柳折还垂，月照深黄几树丝。
见说隋堤枯已尽，年年行客怪春迟。','',''),('quantangshi-27008','郡中冬夜闻蛩','姚合','quantangshi','','卷27','秋蛩声尚在，切切起苍苔。
久是忘情者，今还有事来。
微霜风稍静，圆月雾初开。
此思谁能遣，应须执酒杯。','',''),('quantangshi-27009','闻新蝉寄李余','姚合','quantangshi','','卷27','往年六月蝉应到，每到闻时骨欲惊。
今日槐花还似发，却愁听尽更无声。','',''),('quantangshi-27010','闻蝉寄贾岛','姚合','quantangshi','','卷27','秋来吟更苦，半咽半随风。
禅客心应乱，愁人耳愿聋。
雨晴烟树里，日晚古城中。
远思应难尽，谁当与我同。','',''),('quantangshi-27011','题鹤雏','姚合','quantangshi','','卷27','羽毛生未齐，嶛峭丑于鸡。
夜夜穿笼出，捣衣砧上栖。','',''),('quantangshi-27012','咏莺','姚合','quantangshi','','卷27','春来深谷雪方消，莺别寒林傍翠条。
到处为怜烟景好，隔帘多爱语声娇。
不同蜀魄啼残月，唯逐天鸡啭诘朝。
少妇听时思旧曲，玉楼从此动云韶。','',''),('quantangshi-27013','老马','姚合','quantangshi','','卷27','卧来扶不起，唯向主人嘶。
惆怅东郊道，秋来雨作泥。','',''),('quantangshi-27014','咏镜','姚合','quantangshi','','卷27','铸为明镜绝尘埃，翡翠窗前挂玉台。
绣带共寻龙口出，菱花争向匣中开。
孤光常见鸾踪在，分处还因鹊影回。
好是照身宜谢女，嫦娥飞向玉宫来。','',''),('quantangshi-27015','咏破屏风','姚合','quantangshi','','卷27','时人嫌古画，倚壁不曾收。
露滴胶山断，风吹绢海秋。
残云飞屋里，片水落牀头。
尚胜凡花鸟，君能补缀不。','',''),('quantangshi-27016','古碑','姚合','quantangshi','','卷28','荒田一片石，文字满青苔。
不是逢闲客，何人肯读来。','',''),('quantangshi-27017','拾得古砚','姚合','quantangshi','','卷28','僻性爱古物，终岁求不获。
昨朝得古砚，黄河滩之侧。
念此黄河中，应有昔人宅。
宅亦作流水，斯砚未变易。
波澜所激触，背面生罅隙。
质状朴且丑，今人作不得。
捧持且惊叹，不敢施笔墨。
或恐先圣人，尝用修六籍。
置之洁净室，一日三磨拭。
大喜豪贵嫌，久长得保惜。','',''),('quantangshi-27018','裴大夫见过','姚合','quantangshi','','卷28','湖南谯国尽英髦，心事相期节义高。
解下佩刀无所惜，新闻天子付三刀。','',''),('quantangshi-27019','谢韬光上人赠百龄藤杖','姚合','quantangshi','','卷28','衰病近来行少力，光公乞我百龄藤。
闲来杖此向何处，过水缘山只访僧。','',''),('quantangshi-27020','咏贵游','姚合','quantangshi','','卷28','贵游多爱向深春，到处香凝数里尘。
红杏花开连锦障，绿杨阴合拂朱轮。
凤凰尊畔飞金盏，丝竹声中醉玉人。
日暮垂鞭共归去，西园宾客附龙鳞。','',''),('quantangshi-27021','穷边词二首 一','姚合','quantangshi','','卷28','将军作镇古汧洲，水腻山春节气柔。
清夜满城丝管散，行人不信是边头。','',''),('quantangshi-27022','穷边词二首 二','姚合','quantangshi','','卷28','箭利弓调四镇兵，蕃人不敢近东行。
沿边千里浑无事，唯见平安火入城。','',''),('quantangshi-27023','剑器词三首 一','姚合','quantangshi','','卷28','圣朝能用将，破敌速如神。
掉剑龙缠臂，开旗火满身。
积尸川没岸，流血野无尘。
今日当场舞，应知是战人。','',''),('quantangshi-27024','剑器词三首 二','姚合','quantangshi','','卷28','昼渡黄河水，将军险用师。
雪光偏着甲，风力不禁旗。
阵变龙蛇活，军雄鼓角知。
今朝重起舞，记得战酣时。','',''),('quantangshi-27025','剑器词三首 三','姚合','quantangshi','','卷28','破虏行千里，三军意气麤。
展旗遮日黑，驱马饮河枯。
邻境求兵略，皇恩索阵图。
元和太平乐，自古恐应无。','',''),('quantangshi-27026','从军乐二首 一','姚合','quantangshi','','卷28','每日寻兵籍，经年别酒徒。
眼疼长不校，肺病且还无。
僮仆惊衣窄，亲情觉语麤。
几时得归去，依旧作山夫。','',''),('quantangshi-27027','从军乐二首 二','姚合','quantangshi','','卷28','朝朝十指痛，唯署点兵符。
贫贱依前在，颠狂一半无。
身慙山友弃，胆赖酒杯扶。
谁道从军乐，年来镊白须。','',''),('quantangshi-27028','敬宗皇帝挽词三首 一','姚合','quantangshi','','卷28','从谏停东幸，垂衣宝历昌。
汉昭登位少，周代卜年长。
彩仗三清路，麻衣万国丧。
玄宫今一闭，终古柏苍苍。','',''),('quantangshi-27029','敬宗皇帝挽词三首 二','姚合','quantangshi','','卷28','晚色启重扉，旌旗路渐移。
荆山鼎成日，湘浦竹斑时。
臣子终身感，山园七月期。
金茎看尚在，承露复何为。','',''),('quantangshi-27030','敬宗皇帝挽词三首 三','姚合','quantangshi','','卷28','紫陌起仙飙，川原共寂寥。
灵輴万国护，仪殿百神朝。
漏滴秋风路，笳吟灞水桥。
微臣空感咽，踊绝觉天遥。','',''),('quantangshi-27031','文宗皇帝挽词三首 一','姚合','quantangshi','','卷28','垂拱开成化，愔愔雅乐全。
千官方就日，四海忽无天。
尧舜非传子，殷周但卜年。
圣功青史外，刊石在陵前。','',''),('quantangshi-27032','文宗皇帝挽词三首 二','姚合','quantangshi','','卷28','代以无为理，车书万国同。
继兄还付弟，授圣悉推公。
云雾疑无日，笳箫别起风。
金茎难复见，寒露落空中。','',''),('quantangshi-27033','文宗皇帝挽词三首 三','姚合','quantangshi','','卷28','龙归攀不得，髯在侍臣边。
彻奠新阡起，登山吉从全。
关河佳气散，夷夏哭声连。
寂寞玄宫闭，朝昏千万年。','',''),('quantangshi-27034','庄恪太子挽词二首 一','姚合','quantangshi','','卷28','晓漏启严城，宫臣缟素行。
灵仪先卤簿，新諡在铭旌。
云晦郊原色，风连霰雪声。
凄凉望苑路，春草即应生。','',''),('quantangshi-27035','庄恪太子挽词二首 二','姚合','quantangshi','','卷28','寒日春宫闭，玄堂渭水滨。
华夷牋乍绝，凶吉礼空新。
薤露歌连哭，泉扉夜作晨。
吹笙今一去，千古在逡巡。','',''),('quantangshi-27036','哭费拾遗征君','姚合','quantangshi','','卷28','服儒师道旨，粝食卧中林。
谁识先生事，无身是本心。
空山流水远，故国白云深。
日夕谁来哭，唯应猨鸟吟。','',''),('quantangshi-27037','哭砚山孙道士','姚合','quantangshi','','卷28','修短皆由命，暗怀师出尘。
岂知修道者，难免不亡身。
永祕黄庭诀，高悬漉酒巾。
可怜白犬子，闲吠远行人。','',''),('quantangshi-27038','哭贾岛二首 一','姚合','quantangshi','','卷28','白日西边没，沧波东去流。
名虽千古在，身已一生休。
岂料文章远，那知瑞草秋。
曾闻有书剑，应是别人收。','',''),('quantangshi-27039','哭贾岛二首 二','姚合','quantangshi','','卷28','杳杳黄泉下，嗟君向此行。
有名传后世，无子过今生。
新墓松三尺，空堦月二更。
从今旧诗卷，人觅写应争。','',''),('quantangshi-27040','杨给事师臯哭亡爱姬英英窃闻诗人多赋因而继和','姚合','quantangshi','','卷28','真珠为土玉为尘，未识遥闻鼻亦辛。
天上还应收至宝，世间难得是佳人。
朱丝自断虚银烛，红粉潜销冷绣裀。
见说忘情唯有酒，夕阳对酒更伤神。','',''),('quantangshi-27041','喜览泾州卢侍御诗卷','姚合','quantangshi','','卷28','新诗十九首，丽格出青冥。
得处神应骇，成时力尽停。
正愁闻更喜，沈醉见还醒。
自是天才健，非关笔砚灵。','',''),('quantangshi-27042','喜览裴中丞诗卷','姚合','quantangshi','','卷28','新诗盈道路，清韵似敲金。
调格江山峻，功夫日月深。
蜀牋方入写，越客始消吟。
后辈难知处，朝朝枉用心。','',''),('quantangshi-27043','心怀霜','姚合','quantangshi','','卷28','欲识为诗苦，秋霜若在心。
神清方耿耿，气肃觉沈沈。
皓素中方委，严凝得更深。
依稀轻夕渚，仿髴在寒林。
思劲凄孤韵，声酸激冷吟。
还如饮冰士，励节望知音。','',''),('quantangshi-27044','听僧云端讲经','姚合','quantangshi','','卷28','无生深旨诚难解，唯是师言得正真。
远近迟斋来谛听，酒坊鱼市尽无人。','',''),('quantangshi-27045','腊日猎','姚合','quantangshi','','卷28','健夫结束执旌旗，晓度长江自合围。
野外狐狸搜得尽，天边鸿雁射来稀。
苍鹰落日饥唯急，白马平川走似飞。
蜡节畋游非为己，莫惊刺史夜深归。','',''),('quantangshi-27046','闻魏州破贼','姚合','quantangshi','','卷28','生灵苏息到元和，上将功成自执戈。
烟雾扫开尊北岳，蛟龙斩断净南河。
旗回海眼军容壮，兵合天心杀气多。
从此四方无一事，朝朝雨露是恩波。','',''),('quantangshi-27047','下第','姚合','quantangshi','','卷28','枉为乡里举，射鹄艺浑疎。
归路羞人问，春城赁舍居。
闭门辞杂客，开箧读生书。
以此投知己，还因胜自余。','',''),('quantangshi-27048','得舍弟书','姚合','quantangshi','','卷28','亲戚多离散，三年独在城。
贫居深稳卧，晚学爱闲名。
小弟有书至，异乡无地行。','',''),('quantangshi-27049','病僧','姚合','quantangshi','','卷28','三年病不出，苔藓满藤鞋。
倚壁看经坐，闻钟吃药斋。
茶烟熏杀竹，檐雨滴穿堦。
无暇频相访，秋风寂寞怀。','',''),('quantangshi-27050','成名后留别从兄','姚合','quantangshi','','卷28','一辞山舍废躬耕，无事悠悠住帝城。
为客衣裳多不稳，和人诗句固难精。
几年秋赋唯知病，昨日春闱偶有名。
却出关东悲复喜，归寻弟妹别仁兄。','',''),('quantangshi-27051','佛舍见胡子有嘲','姚合','quantangshi','','卷28','明明复夜夜，胡子即成翁。
唯是真知性，不来生灭中。','',''),('quantangshi-27052','白鼻騧','姚合','quantangshi','','卷28','为底胡姬酒，长来白鼻騧。
摘莲抛水上，郎意在浮花。','',''),('quantangshi-27053','崔少卿鹤','姚合','quantangshi','','卷28','入门石径半高低，闲处无非是药畦。
致得仙禽无去意，花间舞罢洞中栖。','',''),('quantangshi-27054','新昌里','姚合','quantangshi','','卷28','旧客常乐坊，井泉浊而咸。
新屋新昌里，井泉清而甘。
僮仆惯苦饮，食美翻憎嫌。
朝朝忍饥行，戚戚如难堪。
中下无正性，所习便淫耽。
一染不可变，甚于茜与蓝。
近贫日益廉，近富日益贪。
以此当自警，慎勿信邪谗。','',''),('quantangshi-27055','塞下曲','姚合','quantangshi','','卷28','碛露黄云下，凝寒鼓不鸣。
战须移死地，军讳杀降兵。
印马秋遮虏，蒸沙夜筑城。
旧乡归不得，都尉负功名。','',''),('quantangshi-27056','从军行','姚合','quantangshi','','卷28','滥得进士名，才用苦不长。
性癖艺亦独，十年作诗章。
六义虽粗成，名字犹未扬。
将军俯招引，遣脱儒衣裳。
常恐虚受恩，不惯把刀枪。
又无远筹略，坐使虏灭亡。
昨来发兵师，各各赴战场。
顾我同老弱，不得随戎行。
丈夫生世间，职分贵所当。
从军不出门，岂异病在牀。
谁不恋其家，其家无风霜。
鹰鹘念搏击，岂贵食满肠。','',''),('quantangshi-27057','杏园','姚合','quantangshi','','卷28','江头数顷杏花开，车马争先尽此来。
欲待无人连夜看，黄昏树树满尘埃。','',''),('quantangshi-27058','闲居','姚合','quantangshi','','卷28','日日门长闭，隣家亦懒过。
头风春饮苦，眼晕夜书多。
幽鸟偏栖竹，凡人笑种莎。
近来难得酒，无计奈愁何。','',''),('quantangshi-27059','句','姚合','quantangshi','','卷28','天遥来雁小，江阔去帆孤。
南陌游人回首去，东林道者杖藜归。
萄藤洞庭头，引叶漾盈摇。
皎洁钩高挂，玲珑影落寮。
阴烟压幽屋，蒙密梦冥苗。
清秋青且翠，冬到冻都凋。','',''),('quantangshi-27060','留辞杭州姚合郎中','周賀','quantangshi','','卷28','波涛千里隔，抱疾亦相寻。
会宿逢高士，辞归值积霖。
丛桑山店迥，孤烛海船深。
尚有重来约，知无省阁心。','',''),('quantangshi-27061','酬吴之问见赠','周賀','quantangshi','','卷28','已当鸣雁夜，多事不同居。
故疾离城晚，秋霖见月疎。
趂风开静户，带叶卷残书。
荡桨期南去，荒园久废锄。','',''),('quantangshi-27062','送分定归灵夏','周賀','quantangshi','','卷28','南游多老病，见说讲经稀。
塞寺几僧在，关城空自归。
带河衰草断，映日旱沙飞。
却到禅斋后，边军识衲衣。','',''),('quantangshi-27063','与崔弇话别','周賀','quantangshi','','卷28','归思缘平泽，幽斋夜话迟。
人寻冯翊去，草向建康衰。
雨雪生中路，干戈阻后期。
几年方见面，应是镊苍髭。','',''),('quantangshi-27064','题何氏池亭','周賀','quantangshi','','卷28','信是虚闲地，亭高亦有苔。
绕池逢石坐，穿竹引山回。
果落纤萍散，龟行细草开。
主人偏好事，终不厌频来。','',''),('quantangshi-27065','送表兄东南游','周賀','quantangshi','','卷28','山水叠层层，吾兄涉又登。
挂帆春背雁，寻磬夜逢僧。
雪溜悬衡岳，江云盖秣陵。
评文永不忘，此说是中兴。','',''),('quantangshi-27066','送康绍归建业','周賀','quantangshi','','卷28','南朝秋色满，君去意如何。
帝业空城在，民田坏冢多。
月圆台独上，栗绽寺频过。
篱下西江阔，相思见白波。','',''),('quantangshi-27067','再过王辂原居纳凉','周賀','quantangshi','','卷28','夏天多忆此，早晚得秋分。
旧月来还见，新蝉坐忽闻。
扇风调病叶，沟水隔残云。
别有微凉处，从容不似君。','',''),('quantangshi-27068','送耿山人归湖南','周賀','quantangshi','','卷28','南行随越僧，别业几池菱。
两鬓已垂白，五湖归挂罾。
夜涛鸣栅鏁，寒苇露船灯。
去此应无事，却来知不能。','',''),('quantangshi-27069','送省己上人归太原','周賀','quantangshi','','卷28','惜别听边漏，窗灯落烬重。
寒僧回绝塞，夕雪下穷冬。
出定闻残角，休兵见坏锋。
何年更来此，老却倚堦松。','',''),('quantangshi-27070','宿甄山南溪昼公院','周賀','quantangshi','','卷28','从作两河客，别离经半年。
却来峰顶宿，知废甄南禅。
余雾沈斜月，孤灯照落泉。
何当闲事尽，相伴老溪边。','',''),('quantangshi-27071','相次寻举客寄住人','周賀','quantangshi','','卷28','停桡因旧识，白发向波涛。
以我往来倦，知君耕稼劳。
渚田临舍尽，坂路出檐高。
游者还南去，终期伴尔曹。','',''),('quantangshi-27072','出关寄贾岛','周賀','quantangshi','','卷28','旧乡无子孙，谁共老青门。
迢递早秋路，别离深夜村。
伊流偕行客，岳响答啼猿。
去后期招隐，何当复此言。','',''),('quantangshi-27073','暮冬长安旅舍','周賀','quantangshi','','卷28','湖外谁相识，思归日日频。
遍寻新住客，少见故乡人。
失计空知命，劳生耻为身。
惟看洞庭树，即是旧山春。','',''),('quantangshi-27074','赠胡僧','周賀','quantangshi','','卷28','瘦形无血色，草履着行穿。
闲话似持咒，不眠同坐禅。
背经来汉地，袒膊过冬天。
情性人难会，游方应信缘。','',''),('quantangshi-27075','赠李主簿','周賀','quantangshi','','卷28','税时兼主印，每日得闲稀。
对酒妨料吏，为官亦典衣。
案迟吟坐待，宅近步行归。
见说论诗道，应愁判是非。','',''),('quantangshi-27076','同朱庆余宿翊西上人房','周賀','quantangshi','','卷28','溪僧还共谒，相与坐寒天。
屋雪凌高烛，山茶称远泉。
夜清更彻寺，空阔雁冲烟。
莫怪多时话，重来又隔年。','',''),('quantangshi-27077','寄姚合郎中','周賀','quantangshi','','卷28','转刺名山郡，连年别省曹。
分题得客少，着价买书高。
晚柳蝉和角，寒城烛照涛。
鄱溪卧疾久，未获后乘骚。','',''),('quantangshi-27078','休粮僧','周賀','quantangshi','','卷28','一斋难过日，况是更休粮。
养力时行道，闻钟不上堂。
惟留温药火，未写化金方。
旧有山厨在，从僧请作房。','',''),('quantangshi-27079','怀西峰隐者','周賀','quantangshi','','卷28','灌木藏岑色，天寒望即愁。
高斋何日去，远瀑入城流。
腊近溪书绝，灯残夜雪稠。
迩来相忆处，枕上苦吟休。','',''),('quantangshi-27080','赠栢岩禅师','周賀','quantangshi','','卷28','野寺绝依念，灵山会遍行。
老来披衲重，病后读经生。
乞食嫌村远，寻溪爱路平。
多年栢岩住，不记栢岩名。','',''),('quantangshi-27081','旅怀','周賀','quantangshi','','卷28','不觉月又尽，未归还到春。
雪通庐岳梦，树匝草堂身。
泽雁和寒露，江槎带远薪。
何年自此去，旧国复为隣。','',''),('quantangshi-27082','缑氏韦明府厅','周賀','quantangshi','','卷28','贵邑清风满，谁同上宰心。
杉松出郭外，雨电下嵩阴。
度雁方离垒，来僧始别岑。
西池月才迥，会接一宵吟。','',''),('quantangshi-27083','送朱庆余','周賀','quantangshi','','卷28','野客行无定，全家在浦东。
寄眠僧阁静，赠别橐金空。
旧里千山隔，归舟百计同。
药资如有分，相约老吴中。','',''),('quantangshi-27084','宿开元寺楼','周賀','quantangshi','','卷28','西峰残日落，谁见寂寥心。
孤枕客眠久，两廊僧话深。
寒扉关雨气，风叶隐钟音。
此爱东楼望，仍期别夜寻。','',''),('quantangshi-27085','送僧还南岳','周賀','quantangshi','','卷28','辞僧下水栅，因梦岳钟声。
远路独归寺，几时重到城。
风高寒叶落，雨绝夜堂清。
自说深居后，隣州亦不行。','',''),('quantangshi-27086','秋思','周賀','quantangshi','','卷28','杨柳已秋思，楚田仍刈禾。
归心病起切，败叶夜来多。
细雨城蝉噪，残阳峤客过。
旧山余业在，杳隔洞庭波。','',''),('quantangshi-27087','旅情','周賀','quantangshi','','卷28','黄叶下堦频，徐徐起病身。
残秋萤出尽，独夜雁来新。
别业去千里，旧乡空四隣。
孤舟寻几度，又识岳阳人。','',''),('quantangshi-27088','送灵应禅师','周賀','quantangshi','','卷28','寒天仍远去，离寺雪霏霏。
古迹曾重到，生涯不暂归。
坐禅山店暝，补衲夜灯微。
巡礼何时住，相逢的是稀。','',''),('quantangshi-27089','送陆判官防秋','周賀','quantangshi','','卷28','匹马无穷地，三年逐大军。
筭程淮邑远，起帐夕阳曛。
瀑浪行时漱，边笳语次闻。
要传书札去，应到碛东云。','',''),('quantangshi-27090','山居秋思','周賀','quantangshi','','卷28','一从云水住，曾不下西岑。
落木孤猨在，秋庭积雾深。
泉流通井脉，虫响出墙阴。
夜静溪声彻，寒灯尚独吟。','',''),('quantangshi-27091','赠皎然上人','周賀','quantangshi','','卷28','竹庭瓶水新，深称北窗人。
讲罢见黄叶，诗成寻旧隣。
锡阴迷坐石，池影露斋身。
苦作南行约，劳生始问津。','',''),('quantangshi-27092','春日山居寄友人','周賀','quantangshi','','卷28','春居无俗喧，时立涧前村。
路远少来客，山深多过猨。
带岩松色老，临水杏花繁。
除忆文流外，何人更可言。','',''),('quantangshi-27093','留别南徐故人','周賀','quantangshi','','卷28','三年蒙见待，此夕是前程。
未断却来约，且伸临去情。
潮[回]滩鸟下，月上客船明。
他日南徐道，缘君又重行。','',''),('quantangshi-27094','送僧归江南','周賀','quantangshi','','卷28','洗足北林去，远途今已分。
麻衣行岳色，竹杖带湘云。
饥鼠缘危壁，寒狸出坏坟。
前峰一声磬，此夕不同闻。','',''),('quantangshi-27095','早春越中留故人','周賀','quantangshi','','卷28','此行经岁近，唯约半年回。
野渡人初过，前山云未开。
雁羣逢晓断，林色映川来。
清夜芦中客，严家旧钓台。','',''),('quantangshi-27096','送友人','周賀','quantangshi','','卷28','弹琴多去情，浮檝背潮行。
人望丰壖宿，虫依蠹木鸣。
樯烟离浦色，芦雨入船声。
如疾登云路，凭君寄此生。','',''),('quantangshi-27097','春日重到王依村居','周賀','quantangshi','','卷28','野烟居舍在，曾约此重过。
久雨初招客，新田未种禾。
夜虫鸣井浪，春鸟宿庭柯。
莫为儿孙役，余生能几何。','',''),('quantangshi-27098','入静隐寺途中作','周賀','quantangshi','','卷28','乱云迷远寺，入路认青松。
鸟道缘巢影，僧鞋印雪踪。
草烟连野烧，溪雾隔霜钟。
更遇樵人问，犹言过数峰。','',''),('quantangshi-27099','送杨岳归巴陵','周賀','quantangshi','','卷28','何处得乡信，告行当雨天。
人离京口日，潮送岳阳船。
孤鸟背林色，远帆开浦烟。
悲君惟此别，不肯话回年。','',''),('quantangshi-27100','赠朱庆余校书','周賀','quantangshi','','卷28','风泉尽结冰，寒梦彻西陵。
越信楚城得，远怀中夜兴。
树停沙岛鹤，茶会石桥僧。
寺阁连官舍，行吟过几层。','',''),('quantangshi-27101','逢播公','周賀','quantangshi','','卷28','带病希相见，西城早晚来。
衲衣风坏帛，香印雨霑灰。
坐久钟声尽，谈余岳影回。
却思同宿夜，高枕说天台。','',''),('quantangshi-27102','寻北冈韩处士','周賀','quantangshi','','卷28','相过值早凉，松帚扫山牀。
坐石泉痕黑，登城藓色黄。
逆风沈寺磬，初日晒隣桑。
几处逢僧说，期来宿北冈。','',''),('quantangshi-27103','哭闲霄上人','周賀','quantangshi','','卷28','林迳西风急，松枝讲钞余。
冻髭亡夜剃，遗偈病时书。
地燥焚身后，堂空着影初。
吊来频落泪，曾忆到吾庐。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-27104','城中秋作','周賀','quantangshi','','卷28','已落关东叶，空悬浙右心。
寒灯随故病，伏雨接秋霖。
客话曾谁和，虫声少我吟。
蒹葭半波水，夜夜宿边禽。','',''),('quantangshi-27105','玉芝观王道士','周賀','quantangshi','','卷28','四面杉萝合，空堂画老仙。
蠹根停雪水，曲角积茶烟。
道至心机尽，宵晴瑟韵全。
暂来还又去，未得坐经年。','',''),('quantangshi-27106','出关后寄贾岛','周賀','quantangshi','','卷28','故国知何处，西风已度关。
归人值落叶，远路入寒山。
多难喜相识，久贫宁自闲。
唯将往来信，遥慰别离颜。','',''),('quantangshi-27107','题昼公院','周賀','quantangshi','','卷28','丛木开风径，过从白昼寒。
舍深原草合，茶疾竹薪干。
夕雨生眠兴，禅心少话端。
频来觉无事，尽日坐相看。','',''),('quantangshi-27108','京口赠崔固','周賀','quantangshi','','卷28','积雨晴时近，西风叶满泉。
相逢嵩岳客，共听楚城蝉。
宿馆横秋岛，归帆涨远田。
别多还寂寞，不似剡中年。','',''),('quantangshi-27109','书实上人房','周賀','quantangshi','','卷28','绝顶言无伴，长怀剃发师。
禅中灯落烬，讲次栢生枝。
沙井泉澄疾，秋钟韵尽迟。
里闾还受请，空有向南期。','',''),('quantangshi-27110','送张諲之睦州','周賀','quantangshi','','卷28','遥忆新安旧，扁舟往复还。
浅深看水石，来往逐云山。
到县余花在，过门五柳闲。
东征随子去，俱隐薜萝间。','',''),('quantangshi-27111','赠王道士','周賀','quantangshi','','卷28','药力资苍鬓，应非旧日身。
一为嵩岳客，几葬洛阳人。
石缝瓢探水，云根斧斫薪。
关西来往路，谁得水银银。','',''),('quantangshi-27112','冬日山居思乡','周賀','quantangshi','','卷28','大野始严凝，云天晓色澄。
树寒稀宿鸟，山迥少来僧。
背日收窗雪，开炉释砚冰。
忽然归故国，孤想寓西陵。','',''),('quantangshi-27113','如空上人移居大云寺','周賀','quantangshi','','卷28','竹溪人请住，何日向中峰。
瓦舍山情少，斋身疾色浓。
夏高移坐次，菊浅露行踪。
来往湓城下，三年两度逢。','',''),('quantangshi-27114','送幻羣法师','周賀','quantangshi','','卷28','北京一别后，吴楚几听砧。
住久白发出，讲长枯叶深。
香连隣舍像，磬彻远巢禽。
寂默应关道，何人见此心。','',''),('quantangshi-27115','春喜友人至山舍','周賀','quantangshi','','卷28','鸟鸣春日晓，喜见竹门开。
路自高岩出，人骑大马来。
折花林影断，移石洞阴回。
更欲留深语，重城暮色催。','',''),('quantangshi-27116','春日重至南徐旧居','周賀','quantangshi','','卷28','绿水阴空院，春深喜再来。
独眠从草长，留酒看花开。
过雨远山出，向风孤鸟回。
忽思秋夕事，云物却悠哉。','',''),('quantangshi-27117','早秋过郭涯书堂','周賀','quantangshi','','卷28','暑消冈舍清，闲语有余情。
涧水生茶味，松风灭扇声。
远分临海雨，静觉掩山城。
此地秋吟苦，时来遶菊行。','',''),('quantangshi-27118','长安送人','周賀','quantangshi','','卷28','上国多离别，年年渭水滨。
空将未归意，说向欲行人。
雁度池塘月，山连井邑春。
临岐惜分手，日暮一霑巾。','',''),('quantangshi-27119','寄宁海李明府','周賀','quantangshi','','卷28','山县风光异，公门水石清。
一官居外府，几载别东京。
故疾梅天发，新诗雪夜成。
家贫思减选，时静忆归耕。
把疏寻书义，澄心得狱情。
梦灵邀客解，劒古拣人呈。
守月通宵坐，寻花迥路行。
从来爱知道，何虑白髭生。','',''),('quantangshi-27120','投江州张郎中','周賀','quantangshi','','卷28','要地无闲日，仍容冒谒频。
借山年涉闰，寝郡月逾旬。
驿径曾冲雪，方泉省涤尘。
随行溪路细，接话草堂新。
减药痊余癖，飞书苦问贫。
噪蝉离宿壳，吟客寄秋身。
炼句贻箱箧，悬图见蜀岷。
使君匡岳近，终作社中人。','',''),('quantangshi-27121','晚题江馆','周賀','quantangshi','','卷28','病寄曲江居带城，傍门孤柳一蝉鸣。
澄波月上见鱼掷，晚径叶多闻犬行。
越岛夜无侵阁色，寺钟凉有隔原声。
故园尽卖休官去，潮水秋来空自平。','',''),('quantangshi-27122','秋晚归庐山留别道友','周賀','quantangshi','','卷28','病起陵阳思翠微，秋风动后着行衣。
月生石齿人同见，霜落木梢愁独归。
已许衲僧修静社，便将樵叟对闲扉。
不嫌旧隐相随去，庐岳临天好息机。','',''),('quantangshi-27123','同徐处士秋怀少室旧居','周賀','quantangshi','','卷28','曾居少室黄河畔，秋梦长悬未得回。
扶病半年离水石，思归一夜隔风雷。
荒斋几遇僧眠后，晚菊频经鹿踏来。
灯下此心谁共说，傍松幽径已多栽。','',''),('quantangshi-27124','赠神遘上人','周賀','quantangshi','','卷28','草履蒲团山意存，坐看庭木长桐孙。
行斋罢讲仍香气，布褐离牀带雨痕。
夏满寻医还出寺，晴来晒疏暂开门。
道情淡薄闲愁尽，霜色何因入鬓根。','',''),('quantangshi-27125','赠道人','周賀','quantangshi','','卷28','布褐高眠石窦春，迸泉多溅黑纱巾。
摇头说易当朝客，落手围碁对俗人。
自筭天年穷甲子，谁同雨夜守庚申。
拟归太华何时去，他日相寻乞药银。','',''),('quantangshi-27126','赠厉玄侍御','周賀','quantangshi','','卷28','山松径与瀑泉通，巾舃行吟想越中。
塞雁去经华顶末，乡僧来自海涛东。
关分河汉秋钟绝，露滴狝猴夜岳空。
抱疾因寻周柱史，杜陵寒叶落无穷。','',''),('quantangshi-27127','送韩评事','周賀','quantangshi','','卷28','门枕平湖秋景好，水烟松色远相依。
罢官余俸租田种，送客回舟载石归。
离岸游鱼逢浪返，望巢寒鸟逆风飞。
嵩阳旧隐多时别，闭目闲吟忆翠微。','',''),('quantangshi-27128','宿隐静寺上人','周賀','quantangshi','','卷28','一宿五峰杯度寺，虚廊中夜磬声分。
疎林未落上方月，深涧忽生平地云。
幽鸟背泉栖静境，远人当烛想遗文。
暂来此地歇劳足，望断故山沧海濆。','',''),('quantangshi-27129','寄新头陀','周賀','quantangshi','','卷28','见说北京寻祖后，瓶盂自挈遶穷边。
相逢竹坞晦暝夜，一别苕溪多少年。
远洞省穿湖底过，断崖曾向壁中禅。
青城不得师同住，坐想沧江忆浩然。','',''),('quantangshi-27130','湘汉旅怀翁杰','周賀','quantangshi','','卷28','一宿空江听急流，仍同贾客坐归舟。
远书来隔巴陵雨，衰鬓去经彭蠡秋。
不拟为身谋旧业，终期断谷隐高丘。
吾宗尚无憀者，中夜闲吟生旅愁。','',''),('quantangshi-27131','寄韩司兵','周賀','quantangshi','','卷28','多病十年无旧识，沧州乱后只逢君。
已知罢秩辞泷水，相劝移家近岳云。
泗上旅帆侵叠浪，雪中归路踏荒坟。
若为此别终期老，书札何因寄北军。','',''),('quantangshi-27132','寺居寄杨侍御','周賀','quantangshi','','卷28','雨过北林空晚凉，院闲人去掩斜阳。
十年多病度落叶，万里乱愁生夜牀。
终欲返耕甘性拙，久惭他事与身忙。
还知谢客名先重，肯为诗篇问楚狂。','',''),('quantangshi-27133','上陕府姚中丞','周賀','quantangshi','','卷28','此心长爱狎禽鱼，仍候登封独着书。
领郡只嫌生药少，在官长恨与山疎。
成家尽是经纶后，得句应多谏诤余。
见说养真求退静，溪南泉石许同居。','',''),('quantangshi-27134','赠僧','周賀','quantangshi','','卷28','藩府十年为律业，南朝本寺往来新。
辞归几别深山客，赴请多从远处人。
松吹入堂资讲力，野蔬供饭爽禅身。
他年更息登坛计，应与云泉作四邻。','',''),('quantangshi-27135','送石协律归吴','周賀','quantangshi','','卷28','僧窗梦后忆归耕，水涉应多半月程。
幕府罢来无药价，纱巾带去有山情。
夜随净渚离蛩语，早过寒潮背井行。
已让辟书称抱疾，沧洲便许白髭生。','',''),('quantangshi-27136','寄金陵僧','周賀','quantangshi','','卷28','水石致身闲自得，平云竹阁少炎蒸。
斋牀几减供禽食，禅径寒通照像灯。
觅句当秋山落叶，临书近腊砚生冰。
行登总到诸山寺，坐听蝉声满四棱。','',''),('quantangshi-27137','送忍禅师归庐岳','周賀','quantangshi','','卷28','浪匝湓城岳壁青，白头僧去扫禅扃。
龛灯度雪补残衲，山日上轩看旧经。
泉水带冰寒溜涩，薜萝新雨曙烟腥。
已知身事非吾道，甘卧荒斋竹满庭。','',''),('quantangshi-27138','赠姚合郎中','周賀','quantangshi','','卷28','望重来为守土臣，清高还似武功贫。
道从会解唯求静，时造玄微不趁新。
玉帛已知难挠思，云泉终是得闲身。
两衙向后长无事，门馆多逢请益人。','',''),('quantangshi-27139','宿李主簿','周賀','quantangshi','','卷28','独树倚亭新月入，城墙四面鏁山多。
去年今夜还来此，坐见西风褭鹊窠。','',''),('quantangshi-27140','寄潘纬','周賀','quantangshi','','卷28','杨柳垂丝与地连，归来一醉向溪边。
相逢头白莫惆怅，世上无人长少年。','',''),('quantangshi-27141','浔阳与孙郎中宴回','周賀','quantangshi','','卷28','别酒已酣春漏前，他人扶上北归船。
浔阳渡口月未上，渔火照江仍独眠。','',''),('quantangshi-27142','送宗禅师','周賀','quantangshi','','卷28','衡阳到却十三春，行脚同来有几人。
老大又思归岳里，当时来漆祖师身。','',''),('quantangshi-27143','送僧','周賀','quantangshi','','卷28','草履初登南客船，铜瓶犹贮北山泉。
衡阳旧寺秋归去，门鏁寒潭几树蝉。','',''),('quantangshi-27144','送蜀僧','周賀','quantangshi','','卷28','万里独行无弟子，惟赍筇竹与檀龛。
看经更向吴中老，应是山川似劒南。','',''),('quantangshi-27145','过僧竹院','周賀','quantangshi','','卷28','一生爱竹自未有，每到此房归不能。
高人留宿话禅后，寂寞雨堂空夜灯。','',''),('quantangshi-27146','忆浔阳旧居兼感长孙郎中','周賀','quantangshi','','卷28','浔阳却到是何日，此地今无旧使君。
长忆穷冬宿庐岳，瀑泉冰折共僧闻。','',''),('quantangshi-27147','送郭秀才归金陵','周賀','quantangshi','','卷28','夏后客堂黄叶多，又怀家国起悲歌。
酒前欲别语难尽，云际相思心若何。
鸟下独山秋寺磬，人随大舸晚江波。
南徐旧业几时到，门掩残阳积翠萝。','',''),('quantangshi-27148','宿李枢书斋','周賀','quantangshi','','卷28','小斋经暮雨，四面绝纤埃。
眠客闻风觉，飞虫入烛来。
夜凉书读遍，月正户全开。
住远稀相见，留连宿始回。','',''),('quantangshi-27149','杪秋登江楼','周賀','quantangshi','','卷28','平楚起寒色，长沙犹未还。
世情何处淡，湘水向人闲。
空翠隐高鸟，夕阳归远山。
孤云万余里，惆怅洞庭间。','',''),('quantangshi-27150','秋宿洞庭','周賀','quantangshi','','卷28','洞庭初叶下，旅客不胜愁。
明月天涯夜，青山江上秋。
一官成白首，万里寄沧洲。
只被浮名系，宁无愧海鸥。','',''),('quantangshi-27151','重阳','周賀','quantangshi','','卷28','云木疎黄秋满川，茱萸风里一樽前。
几回为客逢佳节，曾见何人再少年。
霜报征衣冷针指，雁惊幽隐泣云泉。
古来醉乐皆难得，留取穷通委上天。','',''),('quantangshi-27152','送李亿东归','周賀','quantangshi','','卷28','黄山远隔秦树，紫禁斜通渭城。
别路青青柳发，前溪漠漠花生。
和风澹荡归客，落日殷勤早莺。
灞上金樽未饮，宴歌已有余声。','',''),('quantangshi-27153','泊灵溪馆','鄭巢','quantangshi','','卷28','孤吟疎雨绝，荒馆乱峰前。
晓鹭栖危石，秋萍满败船。
溜从华顶落，树与赤城连。
已有求闲意，相期在暮年。','',''),('quantangshi-27154','瀑布寺贞上人院','鄭巢','quantangshi','','卷28','林疎多暮蝉，师去宿山烟。
古壁灯熏画，秋琴雨润弦。
竹间窥远鹤，岩上取寒泉。
西岳沙房在，归期更几年。','',''),('quantangshi-27155','寄贞法师','鄭巢','quantangshi','','卷28','巡礼知难尽，幽人见亦稀。
几年潭上过，何待雪中归。
远瀑穿经室，寒螿发定衣。
无因寻道者，独坐对松扉。','',''),('quantangshi-27156','送灵溪李侍郎','鄭巢','quantangshi','','卷28','貂裘离阙下，初佐汉元勋。
河偃流澌叠，沙晴远树分。
牛羊下暮霭，鼓角调寒云。
中夕萧关宿，边声不可闻。','',''),('quantangshi-27157','送姚郎中罢郡游越','鄭巢','quantangshi','','卷28','逍遥方罢郡，高兴接东瓯。
几处行杉迳，何时宿石楼。
湘声穿古窦，华影在空舟。
惆怅云门路，无因得从游。','',''),('quantangshi-27158','送魏校书赴夏口从事','鄭巢','quantangshi','','卷28','西风吹远蝉，驿路在云边。
独梦诸山外，高谈大斾前。
夜灯分楚塞，秋角满湘船。
郡邑多岩窦，何方便学仙。','',''),('quantangshi-27159','送衡州薛从事','鄭巢','quantangshi','','卷28','吟去望双旌，沧洲晚气清。
遥分高岳色，乱出远蝉声。
楚霁云连寺，湘寒浪浸城。
孤猨不可听，一听白髭生。','',''),('quantangshi-27160','送边使','鄭巢','quantangshi','','卷28','关河度几重，边色上离容。
灞水方为别，沙场又入冬。
曙雕回大旆，夕雪没前峰。
汉使多长策，须令远国从。','',''),('quantangshi-27161','送人赴举','鄭巢','quantangshi','','卷28','篇章动玉京，坠叶满前程。
旧国与僧别，秋江罢钓行。
马过隋代寺，樯出楚山城。
应近嵩阳宿，潜闻瀑布声。','',''),('quantangshi-27162','送袁肇归山阴','鄭巢','quantangshi','','卷28','论文意有违，寒雨洒行衣。
南渡久谁语，后吟今独归。
河帆因树落，沙鸟背潮飞。
若值云门侣，多因宿翠微。','',''),('quantangshi-27163','送李式','鄭巢','quantangshi','','卷28','潇湘路杳然，清兴起秋前。
去寺多随磬，看山半在船。
绿云天外鹤，红树雨中蝉。
莫使游华顶，逍遥更过年。','',''),('quantangshi-27164','送韦弇','鄭巢','quantangshi','','卷28','挂席曙钟初，家山半在吴。
橹声过远寺，江色润秋芜。
陂鹤巢城木，边鸿宿岸芦。
知君当永夜，独钓五湖隅。','',''),('quantangshi-27165','送人南游','鄭巢','quantangshi','','卷28','南京路悄然，欹石漱流泉。
远寺寒云外，扬帆暑雨前。
雁行回晓岫，蜃色上湖田。
更想清吟处，多同隐者眠。','',''),('quantangshi-27166','送省空上人归南岳','鄭巢','quantangshi','','卷28','又归衡岳寺，旧院树冥冥。
坐石逢寒衲，寻龛补坏经。
峤云笼曙磬，潭草落秋萍。
谁伴高牕宿，禅衣挂桂馨。','',''),('quantangshi-27167','送象上人还山中','鄭巢','quantangshi','','卷28','竹锡与袈裟，灵山笑暗霞。
泉痕生净藓，烧力落寒花。
高户闲听雪，空窗静捣茶。
终期宿华顶，须会说三巴。','',''),('quantangshi-27168','送僧归富春','鄭巢','quantangshi','','卷28','忆过僧禅处，遥山抱竹门。
古房关藓色，秋径扫潮痕。
石净闻泉落，沙寒见鹤翻。
终当从此望，更与道人言。','',''),('quantangshi-27169','送琇上人','鄭巢','quantangshi','','卷28','古殿焚香外，清羸坐石棱。
茶烟开瓦雪，鹤迹上潭冰。
孤磬侵云动，灵山隔水登。
白云归意远，旧寺在庐陵。','',''),('quantangshi-27170','哭虚海上人','鄭巢','quantangshi','','卷28','一化西风外，禅流稍稍分。
买碑行暮雨，斲石葬寒云。
静户关松色，荒斋聚鸟羣。
朗吟声不倦，高传有遗文。','',''),('quantangshi-27171','和姚郎中题凝公院','鄭巢','quantangshi','','卷28','后房寒竹连，白昼坐冥然。
片衲何山至，空堂几夜禅。
叶侵经上字，冰结砚中泉。
雪夕谁同话，悬灯古像前。','',''),('quantangshi-27172','赠丘先生','鄭巢','quantangshi','','卷28','云泉心不爽，垂日坐柴关。
砚取檐前雨，图开异国山。
原僧招过宿，沙鸟伴长闲。
地与中峰近，残阳独不还。','',''),('quantangshi-27173','赠蛮僧','鄭巢','quantangshi','','卷28','南海何年过，中林一磬微。
病逢秋雨发，心逐暮潮归。
久卧前山寺，犹逢故国衣。
近来慵步履，石藓满柴扉。','',''),('quantangshi-27174','秋思','鄭巢','quantangshi','','卷28','寒蛩鸣不定，郭外水云幽。
南浦雁来日，北窗人卧秋。
病身多在远，生计少于愁。
薄暮西风急，清砧响未休。','',''),('quantangshi-27175','楚城秋夕','鄭巢','quantangshi','','卷28','故苑多愁夕，西风木叶黄。
寒江浸雾月，晓角满城霜。
弟侄来书少，关河去路长。
几时停桂檝，故国隔潇湘。','',''),('quantangshi-27176','秋日陪姚郎中登郡中南亭','鄭巢','quantangshi','','卷28','云水生寒色，高亭发远心。
雁来疎角韵，槐落减秋阴。
隔石尝茶坐，当山抱瑟吟。
谁知潇洒意，不似有朝簪。','',''),('quantangshi-27177','宿天竺寺','鄭巢','quantangshi','','卷28','暮过潭上寺，独宿白云间。
钟磬遥连树，星河半隔山。
石中泉暗落，松外户初关。
却忆终南里，前秋此夕还。','',''),('quantangshi-27178','陈氏园林','鄭巢','quantangshi','','卷28','当门三四峰，高兴几人同。
寻鹤新泉外，留僧古木中。
蝉鸣槐叶雨，鱼散芰荷风。
多喜陪幽赏，清吟绕石丛。','',''),('quantangshi-27179','题崔中丞北斋','鄭巢','quantangshi','','卷28','湖近草侵庭，秋来道兴生。
寒潮添井味，远漏带松声。
放卷听泉坐，寻僧踏雪行。
何年各无事，高论宿青城。','',''),('quantangshi-27180','题崔行先石室别墅','鄭巢','quantangshi','','卷28','山空水绕篱，几日此栖迟。
采菊频秋醉，留僧拟夜棊。
桂阴生野菌，石缝结寒澌。
更喜连幽洞，唯君与我知。','',''),('quantangshi-27181','题灵隐寺皖公院','鄭巢','quantangshi','','卷28','山寒叶满衣，孤鹤偶清羸。
已在云房老，休为内殿期。
岚昏声磬早，菓熟唤猨迟。
未得终高论，明朝更别离。','',''),('quantangshi-27182','题寺壁二首 一','呂羣','quantangshi','','卷28','路行三蜀尽，身及一阳生。
赖有残灯火，相依坐到明。','',''),('quantangshi-27183','题寺壁二首 二','呂羣','quantangshi','','卷28','社后辞巢燕，霜前别蔕蓬。
愿为蝴蝶梦，飞去觅关中。','',''),('quantangshi-27184','黄蜀葵','崔涯','quantangshi','','卷28','野栏秋景晚，疎散两三枝。
嫩碧浅轻态，幽香闲澹姿。
露倾金盏小，风引道冠欹。
独立悄无语，清愁人讵知。','',''),('quantangshi-27185','咏春风','崔涯','quantangshi','','卷28','动地经天物不伤，高情逸韵住何方。
扶持燕雀连天去，断送杨花尽日狂。
遶桂月明过万户，弄帆晴晚渡三湘。
孤云虽是无心物，借便吹教到帝乡。','',''),('quantangshi-27186','竹','崔涯','quantangshi','','卷28','领得溪风不放回，傍窗缘砌遍庭栽。
须招野客为邻住，看引山禽入郭来。
幽院独惊秋气早，小门深向绿阴开。
谁怜翠色兼寒影，静落茶瓯与酒杯。','',''),('quantangshi-27187','侠士诗','崔涯','quantangshi','','卷28','太行岭上二尺雪，崔涯袖中三尺铁。
一朝若遇有心人，出门便与妻儿别。','',''),('quantangshi-27188','别妻','崔涯','quantangshi','','卷28','陇上泉流陇下分，断肠呜咽不堪闻。
嫦娥一入月中去，巫峡千秋空白云。','',''),('quantangshi-27189','杂嘲二首 一','崔涯','quantangshi','','卷28','二年不到宋家东，阿母深居僻巷中。
含泪向人羞不语，琵琶弦断倚屏风。','',''),('quantangshi-27190','杂嘲二首 二','崔涯','quantangshi','','卷28','日暮迎来香合中，百年心事一宵同。
寒鸡鼓翼纱窗外，已觉恩情逐晓风。','',''),('quantangshi-27191','悼妓','崔涯','quantangshi','','卷28','赤板桥西小竹篱，槿花还似去年时。
淡黄衫子浑无色，肠断丁香画雀儿。','',''),('quantangshi-27192','自苏州至望亭驿有作','郭良驥','quantangshi','','卷28','南浦菰蒲遶白苹，东吴黎庶逐黄巾。
野棠自发空流水，江燕初归不见人。
远岫依依如送客，平田渺渺独伤春。
那堪回首长洲苑，烽火年年报虏尘。','',''),('quantangshi-27193','邺中行','郭良驥','quantangshi','','卷28','年去年来秋更春，魏家园庙已成尘。
只今惟有西陵在，无复当时歌舞人。','',''),('quantangshi-27194','公无渡河','王叡','quantangshi','','卷28','浊波洋洋兮凝晓雾，公无渡河兮公竟渡。
风号水激兮呼不闻，提壶看入兮中流去。
浪摆衣裳兮随步没，沈尸深入兮蛟螭窟。
蛟螭尽醉兮君血干，推出黄沙兮泛君骨。
当时君死妾何适，遂就波涛合魂魄。
愿持精卫衔石心，穷取河源塞泉脉。','',''),('quantangshi-27195','松','王叡','quantangshi','','卷28','寒松耸拔倚苍岑，绿叶扶疎自结阴。
丁固梦时还有意，秦王封日岂无心。
常将正节栖孤鹤，不遣高枝宿众禽。
好是特凋羣木后，护霜凌雪翠逾深。','',''),('quantangshi-27196','竹','王叡','quantangshi','','卷28','庭竹森疎玉质寒，色包葱碧尽琅玕。
翠筠不乐湘娥泪，斑箨堪裁汉主冠。
成韵含风已萧瑟，媚涟凝渌更檀栾。
此君引凤为龙日，耸节稍云直上看。','',''),('quantangshi-27197','解昭君怨','王叡','quantangshi','','卷28','莫怨工人丑画身，莫嫌明主遣和亲。
当时若不嫁胡虏，秖是宫中一舞人。','',''),('quantangshi-27198','祠渔山神女歌二首 一','王叡','quantangshi','','卷28','蓪草头花椰叶裙，蒲葵树下舞蛮云。
引领望江遥滴酒，白苹风起水生文。','',''),('quantangshi-27199','祠渔山神女歌二首 二','王叡','quantangshi','','卷28','枨枨山响答琵琶，酒湿青莎肉饲鸦。
树叶无声神去后，纸钱灰出木绵花。','',''),('quantangshi-27200','牡丹','王叡','quantangshi','','卷28','牡丹妖艳乱人心，一国如狂不惜金。
曷若东园桃与李，果成无语自成阴。','',''),('quantangshi-27201','秋','王叡','quantangshi','','卷28','蝉噪古槐疏叶下，树衔斜日映孤城。
欲知潘鬓愁多少，一夜新添白数茎。','',''),('quantangshi-27202','燕','王叡','quantangshi','','卷28','海燕双飞意若何，曲梁呕嘎语声多。
茅檐不必嫌卑陋，犹胜吴宫爇尔窠。','',''),('quantangshi-27203','白云向空尽','焦郁','quantangshi','','卷28','白云升远岫，摇曳入晴空。
乘化随舒卷，无心任始终。
欲销仍带日，将断更因风。
势薄飞难定，天高色易穷。
影收元气表，光灭太虚中。
傥若从龙去，还施济物功。','',''),('quantangshi-27204','春雪 一','焦郁','quantangshi','','卷28','散漫天涯色，乘春四望平。
不分残照影，何处断鸿声。
缭绕先经塞，霏微近过城。
因风低未歛，带雨重还轻。
干吕知时泰，如膏候岁成。
小儒同品物，无以答皇明。','',''),('quantangshi-27205','春雪 二','焦郁','quantangshi','','卷28','春雪空蒙帘外斜，霏微半入野人家。
长天远树山山白，不辨梅花与柳花。','',''),('quantangshi-27206','赠去婢','崔郊','quantangshi','','卷28','公子王孙逐后尘，绿珠垂泪滴罗巾。
侯门一入深如海，从此萧郎是路人。','',''),('quantangshi-27207','江西投谒所知为典客所阻因赋','劉魯風','quantangshi','','卷28','万卷书生刘鲁风，烟波万里谒文翁。
无钱岂与韩知客，名纸毛生不肯通。','',''),('quantangshi-27208','玉清行','柳泌','quantangshi','','卷28','遥遥寒冬时，萧萧蹑太无。
仰望蘂宫殿，横天临不虚。
下看白日流，上造真皇居。
西牖日门开，南衢星宿疎。
王母来瑶池，庆云拥琼轝。
嵬峩丹凤冠，摇曳紫霞裾。
照彻圣姿严，飘颻神步徐。
仙郎执玉节，侍女捧金书。
灵香散彩烟，北阙路軿阗。
龙马行无迹，歌钟声沸天。
驭风升宝坐，郁景晏华筵。
妙奏三春曲，高罗万古仙。
七珍飞满坐，九液酌如泉。
灵佩垂轩下，旗幡列帐前。
狮麟威赫赫，鸾凤影翩翩。
顾盼乃须臾，已是数千年。','',''),('quantangshi-27209','琼台','柳泌','quantangshi','','卷28','崖壁盘空天路回，白云行尽见琼台。
洞门黯黯阴云闭，金阙曈曈日殿开。','',''),('quantangshi-27210','操莲曲','何希堯','quantangshi','','卷28','锦莲浮处水粼粼，风外香生袜底尘。
荷叶荷裙相映色，闻歌不见采莲人。','',''),('quantangshi-27211','一枝花','何希堯','quantangshi','','卷28','几树晴葩映水开，乱红狼籍点苍苔。
东风留得残枝在，为惜余芳独看来。','',''),('quantangshi-27212','柳枝词','何希堯','quantangshi','','卷28','大堤杨柳雨沈沈，万缕千条惹恨深。
飞絮满天人去远，东风无力系春心。','',''),('quantangshi-27213','海棠','何希堯','quantangshi','','卷28','着雨胭脂点点消，半开时节最妖娆。
谁家更有黄金屋，深锁东风贮阿娇。','',''),('quantangshi-27214','遗临平监吏','朱沖和','quantangshi','','卷28','三千里外布干戈，果得鲸鲵入网罗。
今日宝刀无杀气，只缘君处受恩多。','',''),('quantangshi-27215','荻塘西庄赠房元垂','張光朝','quantangshi','','卷28','门在荻塘西，塘高何联联。
往昔分地利，远近无闲田。
水国信污下，霖霪即成川。
苗稼尽湮没，兹乡独丰年。
家肥待亲懿，人乐思管弦。
日晏始能起，盥漱看厨烟。
酝酒寒正熟，养鱼长食鲜。
黄昏钟未鸣，偃息早已眠。
何意久城市，寂寥丘中缘。
俯仰在颜色，区区人事间。
忆昔炎汉时，乃知绮季贤。
静默不能仕，养老终南山。','',''),('quantangshi-27216','天门街西观荣王聘妃','張光朝','quantangshi','','卷28','仙媛来朱邸，名山出紫微。
三周初展义，百两遂言归。
郑国通梁苑，天津接帝畿。
桥成乌鹊助，盖转凤皇飞。
霜仗迎秋色，星缸满夜辉。
从兹磐石固，应为得贤妃。','',''),('quantangshi-27217','天门街西观荣王聘妃','梁鉉','quantangshi','','卷28','帝子乘龙夜，三星照户前。
两行宫火出，十里道铺筵。
罗绮明中识，箫韶暗里传。
灯攒九华扇，帐撒五铢钱。
交颈文鸳合，和鸣彩凤连。
欲知来日美，双拜紫微天。','',''),('quantangshi-27218','上浙东元相','章孝標','quantangshi','','卷28','婺女星边喜气频，越王台上坐诗人。
雪晴山水勾留客，风暖旌旗计会春。
黎庶已同猗顿富，烟花却为相公贫。
何言禹迹无人继，万顷湖田又斩新。','',''),('quantangshi-27219','赠茅山高拾遗蔓','章孝標','quantangshi','','卷28','人皆贪禄利，白首更营营。
若见无为理，兼忘不朽名。
幽禽窥饭下，好药入篱生。
梦觉幽泉滴，应疑禁漏声。','',''),('quantangshi-27220','次韵和光禄钱卿二首 一','章孝標','quantangshi','','卷28','大隐严城内，闲门向水开。
扇风知暑退，树影觉秋来。
望远云生海，行稀砌长苔。
废兴今古事，何必叹池灰。','',''),('quantangshi-27221','次韵和光禄钱卿二首 二','章孝標','quantangshi','','卷28','闲论忧王室，愁眉仗酒开。
方嗟三覆役，又喜四愁来。
晨起萤穿竹，晡餐鸟下苔。
同期阳月至，灵室祝葭灰。','',''),('quantangshi-27222','赠庐山钱卿','章孝標','quantangshi','','卷28','象魏抽簪早，匡庐筑室牢。
宦情归去薄，天爵隐来高。
箧有新征诏，囊余旧緼袍。
何如舍麋鹿，明主仰风骚。','',''),('quantangshi-27223','山中送进士刘蟾赴举','章孝標','quantangshi','','卷28','去住迹虽异，爱憎情不同。
因君向帝里，使我厌山中。
故友多朝客，新文尽国风。
艺精心更苦，何患不成功。','',''),('quantangshi-27224','送进士陈峣往睦州谒冯郎中','章孝標','quantangshi','','卷28','孤帆几日程，投刺水边城。
倚棹逢春老，登筵见月生。
饮酣杯有浪，棋散漏无声。
太守怜才者，从容礼不轻。','',''),('quantangshi-27225','丰城劒池即事','章孝標','quantangshi','','卷28','神物不复见，小池空在兹。
因嫌冲斗夜，未是偃戈时。
岸古鱼藏穴，蒲凋翠立危。
吾皇别有劒，何必铸金为。','',''),('quantangshi-27226','咏弓','章孝標','quantangshi','','卷28','较量武艺论勋庸，曾发将军箭落鸿。
握内从夸弯似月，眼前还怕撇来风。
只知击起穿雕镞，不解容和射鹄功。
得病自从杯里后，至今形状怕相逢。','',''),('quantangshi-27227','送无相禅师入关','章孝標','quantangshi','','卷28','九衢车马尘，不染了空人。
蹔舍中峰雪，应看内殿春。
斋心无外事，定力见前身。
圣主方崇教，深宜谒紫宸。','',''),('quantangshi-27228','赠匡山道者','章孝標','quantangshi','','卷28','尝闻一粒功，足以反衰容。
方寸如不达，此生安可逢。
寄书时态尽，忆语道情浓。
争得携巾履，同归鸟外峯。','',''),('quantangshi-27229','道者与金丹开合已失因为二首再有投掷 一','章孝標','quantangshi','','卷28','木钻钻盘石，辛勤四十年。
一朝才见物，五色互呈妍。
七魄憎阳盛，三彭恶命延。
被他迷失却，叹息只澘然。','',''),('quantangshi-27230','道者与金丹开合已失因为二首再有投掷 二','章孝標','quantangshi','','卷28','阴阳曾作炭，造化亦分功。
减自青囊里，收安玉合中。
凡材难度世，神物自归空。
惆怅流年速，看成白首翁。','',''),('quantangshi-27231','思越州山水寄朱庆余','章孝標','quantangshi','','卷28','窗户潮头雪，云霞镜里天。
岛桐秋送雨，江艇暮摇烟。
藕折莲芽脆，茶挑茗眼鲜。
还将欧冶劒，更淬若耶泉。','',''),('quantangshi-27232','蜀中上王尚书','章孝標','quantangshi','','卷28','梓桐花幕碧云浮，天许文星寄上头。
武略劒峰环相府，诗情锦浪浴仙洲。
丁香风里飞牋草，邛竹烟中动酒钩。
自古名高闲不得，肯容王粲赋登楼。','',''),('quantangshi-27233','赠陆鬯浙西进诗除官','章孝標','quantangshi','','卷28','帝城云物得阳春，水国烟花失主人。
昨日天风吹乐府，六宫丝管一时新。','',''),('quantangshi-27234','古行宫','章孝標','quantangshi','','卷28','瓦烟疎冷古行宫，寂寞朱门反鏁空。
残粉水银流砌下，堕环秋月落泥中。
莺传旧语娇春日，花学严妆妬晓风。
天子时清不巡幸，秖应鸾凤集梧桐。','',''),('quantangshi-27235','题上皇观','章孝標','quantangshi','','卷28','烟霞星盖七星坛，想像先朝驻禁銮。
辇路已平栽药地，皇风犹在步虚寒。
楼台瑞气晴萧索，杉桧龙身老屈蟠。
翻感惠休并李郭，劒门空处望长安。','',''),('quantangshi-27236','鹰','章孝標','quantangshi','','卷28','星眸未放瞥秋毫，频掣金铃试雪毛。
会使老拳供口腹，莫辞亲手啖腥臊。
穿云自怪身如电，煞兔谁知吻胜刀。
可惜忍饥寒日暮，向人鹐断碧丝縧。','',''),('quantangshi-27237','方山寺松下泉','章孝標','quantangshi','','卷28','石脉绽寒光，松根喷晓霜。
注瓶云母滑，漱齿茯苓香。
野客偷煎茗，山僧惜净床。
三禅不要问，孤月在中央。','',''),('quantangshi-27238','瀑布','章孝標','quantangshi','','卷28','秋河溢长空，天洒万丈布。
深雷隐云壑，孤电挂岩树。
沧溟晓喷寒，碧落晴荡素。
非趋下流急，势使不得住。','',''),('quantangshi-27239','送张使君赴饶州','章孝標','quantangshi','','卷28','饶阳因富得州名，不独农桑别有营。
日暖提筐依茗树，天阴把酒入银坑。
江寒鱼动枪旗影，山晚云和鼓角声。
太守能诗兼爱静，西楼见月几篇成。','',''),('quantangshi-27240','和滕迈先辈伤马','章孝標','quantangshi','','卷28','浮云变化失龙儿，始忆嘶风喷沫时。
蹄想尘中翻碧玉，尾休烟里掉青丝。
曾同客舍吞饥渴，久共名场踏嶮巘。
今日枥前兴一叹，不关行李乏金羁。','',''),('quantangshi-27241','省试骐骥长鸣','章孝標','quantangshi','','卷28','有马骨堪惊，无人眼暂明。
力穷吴坂峻，嘶苦朔风生。
逐逐怀良御，萧萧顾乐鸣。
瑶池期弄影，天路拟飞声。
皎月谁知种，浮云莫问程。
盐车今愿脱，千里为君行。','',''),('quantangshi-27242','鲤鱼','章孝標','quantangshi','','卷28','眼似真珠鳞似金，时时动浪出还沈。
河中得上龙门去，不叹江湖岁月深。','',''),('quantangshi-27243','饥鹰词','章孝標','quantangshi','','卷28','遥想平原兔正肥，千回砺吻振毛衣。
纵令啄解丝縧结，未得人呼不敢飞。','',''),('quantangshi-27244','归燕词辞工部侍郎','章孝標','quantangshi','','卷28','旧垒危巢泥已落，今年故向社前归。
连云大厦无栖处，更望谁家门户飞。','',''),('quantangshi-27245','归海上旧居','章孝標','quantangshi','','卷28','乡路绕蒹葭，萦纡出海涯。
人衣披蜃气，马迹印盐花。
草没题诗石，潮摧坐钓槎。
还归旧窗里，凝思向余霞。','',''),('quantangshi-27246','答友人惠牙簪','章孝標','quantangshi','','卷28','牙簪不可忘，来处隔炎荒。
截得半环月，磨成四寸霜。
晓辞梳齿腻，秋入发根凉。
好是纱巾下，纤纤锥出囊。','',''),('quantangshi-27247','日者','章孝標','quantangshi','','卷28','十指中央了五行，说人休咎见前生。
我来本乞真消息，却怕呵钱卦欲成。','',''),('quantangshi-27248','送金可纪归新罗','章孝標','quantangshi','','卷28','登唐科第语唐音，望日初生忆故林。
鲛室夜眠阴火冷，蜃楼朝泊晓霞深。
风高一叶飞鱼背，潮净三山出海心。
想把文章合夷乐，蟠桃花里醉人参。','',''),('quantangshi-27249','闻角','章孝標','quantangshi','','卷28','边秋画角怨金微，半夜对吹惊贼围。
塞雁遶空秋不下，胡云着草冻还飞。
关头老马嘶看月，碛里疲兵泪湿衣。
余韵袅空何处尽，戍天寥落晓星稀。','',''),('quantangshi-27250','梦乡','章孝標','quantangshi','','卷28','家住吴王旧苑东，屋头山水胜屏风。
寻常梦在秋江上，钓艇游扬藕叶中。','',''),('quantangshi-27251','织绫词','章孝標','quantangshi','','卷28','去年蚕恶绫帛贵，官急无丝织红泪。
残经脆纬不通梭，鹊凤阑珊失头尾。
今年蚕好缲白丝，鸟鲜花活人不知。
瑶台雪里鹤张翅，禁苑风前梅折枝。
不学隣家妇慵懒，蜡揩粉拭谩官眼。','',''),('quantangshi-27252','诸葛武侯庙','章孝標','quantangshi','','卷28','木牛零落阵图残，山姥烧钱古栢寒。
七纵七擒何处在，茅花枥叶盖神坛。','',''),('quantangshi-27253','长安秋夜','章孝標','quantangshi','','卷28','田家无五行，水旱卜蛙声。
牛犊乘春放，儿童候暖耕。
池塘烟未起，桑柘雨初晴。
岁晚香醪熟，村村自送迎。','',''),('quantangshi-27254','钱塘赠武翊黄','章孝標','quantangshi','','卷28','曾将心劒作戈矛，一战名场造化愁。
花锦文章开四面，天人科第上三头。
鸳鸿待侣飞清禁，山水缘情住外州。
时伴庾公看海月，好吟诗断望潮楼。','',''),('quantangshi-27255','风不鸣条','章孝標','quantangshi','','卷28','旭日悬清景，微风在绿条。
入松声不发，过柳影空摇。
长养应潜变，扶疎每暗飘。
有林时杳杳，无树蹔萧萧。
慢逐清烟散，轻和瑞气饶。
丰年知有待，歌咏美唐尧。','',''),('quantangshi-27256','贻美人','章孝標','quantangshi','','卷28','诸侯帐下惯新妆，皆怯刘家薄媚娘。
宝髻巧梳金翡翠，罗裙宜着绣鸳鸯。
轻轻舞汗初沾袖，细细歌声欲遶梁。
何事不归巫峡去，故来人世断人肠。','',''),('quantangshi-27257','闻云中唳鹤','章孝標','quantangshi','','卷28','久在青田唳，天高忽暂闻。
翩翻萦碧落，嘹唳入重云。
出谷莺何待，鸣岐凤欲羣。
九臯宁足道，此去透絪緼。','',''),('quantangshi-27258','柘枝','章孝標','quantangshi','','卷28','柘枝初出鼓声招，花钿罗衫耸细腰。
移步锦靴空绰约，迎风绣帽动飘颻。
亚身踏节鸾形转，背面羞人凤影娇。
祗恐相公看未足，便随风雨上青霄。','',''),('quantangshi-27259','上太皇先生','章孝標','quantangshi','','卷28','颢气贯精神，苍崖老姓名。
烟霞空送景，水木苦无情。
斸药云根断，眠花石面平。
折松开月色，决水放秋声。
颜为忘忧嫩，身缘绝粒轻。
围棋看局势，对镜戮妖精。
过海量鲸力，归天算鹤程。
露凝钟乳冷，风定玉箫清。
坐觉衣裳古，行疑羽翼生。
应怜市朝客，开眼鏁浮荣。','',''),('quantangshi-27260','破山水屏风','章孝標','quantangshi','','卷28','时人嫌古画，倚壁不曾收。
雨滴胶山断，风吹绢海秋。
残云飞屋里，片水落牀头。
尚胜凡花鸟，君能补缀休。','',''),('quantangshi-27261','览杨校书文卷','章孝標','quantangshi','','卷28','跪伸霜素剖琅玕，身堕瑶池魄暗寒。
红锦晚开云母殿，白珠秋写水精盘。
情高鹤立昆仑峭，思壮鲸跳渤澥宽。
谁有轩辕古铜片，为持相并照妖看。','',''),('quantangshi-27262','送陈校书赴蔡州幕','章孝標','quantangshi','','卷28','天假纵横入幕筹，东南顿减一方忧。
行賷健笔辞天阁，坐见妖星落蔡州。
青草袍襟翻日脚，黄金马镫照旄头。
此行领取从军乐，莫虑功名不拜侯。','',''),('quantangshi-27263','少年行','章孝標','quantangshi','','卷28','平明小猎出中军，异国名香满袖薰。
画榼倒悬鹦鹉觜，花衫对舞凤凰文。
手抬白马嘶春雪，臂竦青骹入暮云。
落日胡姬楼上饮，风吹箫管满楼闻。','',''),('quantangshi-27264','蜀中赠广上人','章孝標','quantangshi','','卷28','曾持麈尾引金根，万乘前头草五言。
疏讲青龙归禁苑，歌抄白雪乞梨园。
朝惊云气遮天阁，暮踏猨声入劒门。
今日西川无子美，诗风又起浣花村。','',''),('quantangshi-27265','和顾校书新开井','章孝標','quantangshi','','卷28','霜锸破桐阴，青丝试浅深。
月轮开地脉，镜面写天心。
碧甃花千片，香泉乳百寻。
欲知争汲引，听取辘轳音。','',''),('quantangshi-27266','游云际寺','章孝標','quantangshi','','卷28','衫袖拂青冥，推鞍上翠屏。
尘埃辞马尾，城阙入窗棂。
云领浮名去，钟撞大梦醒。
茫茫山下事，满眼送流萍。','',''),('quantangshi-27267','赠刘宽夫昆季','章孝標','quantangshi','','卷28','文聚星辰衣彩霞，问谁兄弟是刘家。
雁行云掺参差翼，琼树风开次第花。
天假声名悬日月，国凭骚雅变浮华。
曾穷晋汉儒林传，龙虎虽多未足夸。','',''),('quantangshi-27268','赠杭州严史君','章孝標','quantangshi','','卷28','州青县白淛河濆，饱向苍龙阙下闻。
鼓角自严寒海月，旌旗不动湿江云。
风骚处处文章主，井邑家家父母君。
长恐抱辕留不住，九天鸳鹭待成羣。','',''),('quantangshi-27269','题朱秀城南亭子','章孝標','quantangshi','','卷28','朱家亭子象悬匏，阶莹青莎栋剪茆。
瘿挂眼开欺鸲鹆，花缘网结妬螵蛸。
有时风月输三虎，无壁琴书属四郊。
土木欲知精洁处，社天归燕怯安巢。','',''),('quantangshi-27270','上西川王尚书','章孝標','quantangshi','','卷28','人人入蜀谒文翁，妍丑终须露镜中。
诗景荒凉难道合，客情疎密分当同。
城南歌吹琴台月，江上旌旗锦水风。
下客低头来又去，暗堆冰炭在深衷。','',''),('quantangshi-27271','骆谷行','章孝標','quantangshi','','卷28','扪云褭栈入青冥，鞿马铃骡傍日星。
仰踏劒棱梯万仞，下缘冰岫杳千寻。
山花织锦时聊看，涧水弹琴不暇听。
若比争名求利处，寻思此路却安宁。','',''),('quantangshi-27272','初及第归酬孟元翊见赠','章孝標','quantangshi','','卷28','六年衣破帝城尘，一日天池水脱鳞。
未有片言惊后辈，不无慙色见同人。
每登公宴思来日，渐听乡音认本身。
何幸致诗相慰贺，东归花发杏桃春。','',''),('quantangshi-27273','淮南李相公绅席上赋春雪','章孝標','quantangshi','','卷28','六出花飞处处飘，黏窗着砌上寒条。
朱门到晓难盈尺，尽是三军喜气消。','',''),('quantangshi-27274','及第后寄广陵故人','章孝標','quantangshi','','卷28','及第全胜十政官，金鞍镀了出长安。
马头渐入扬州郭，为报时人洗眼看。','',''),('quantangshi-27275','小松','章孝標','quantangshi','','卷28','爪叶鳞条龙不盘，梳风幕翠一庭寒。
莫言只是人长短，须作浮云向上看。','',''),('quantangshi-27276','宫词','章孝標','quantangshi','','卷28','明日銮舆欲向东，守宫金翠带愁红。
九门佳气已西去，千里花开一夜风。','',''),('quantangshi-27277','题杭州樟亭驿','章孝標','quantangshi','','卷28','樟亭驿上题诗客，一半寻为山下尘。
世事日随流水去，红花还似白头人。','',''),('quantangshi-27278','刘侍中宅盘花紫蔷薇','章孝標','quantangshi','','卷28','真宰偏饶丽景家，当春盘出带根霞。
从开一朵朝衣色，免踏尘埃看杂花。','',''),('quantangshi-27279','题东林寺寄江州李员外','章孝標','quantangshi','','卷28','山势棱层入杳冥，寺形高下趂山行。
象牙牀坐莲花佛，玛瑙函盛贝叶经。
日映砌阴移宝阁，风吹天乐动金铃。
门前更有清江水，便是浔阳太守厅。','',''),('quantangshi-27280','玄都观栽桃十韵','章孝標','quantangshi','','卷28','驱使鬼神功，攒栽万树红。
薰香丹凤阙，妆点紫琼宫。
宝帐重遮日，妖金遍累空。
色然烧药火，影舞步虚风。
粉扑青牛过，枝惊白鹤冲。
拜星春锦上，服食晚霞中。
棋局阴长合，箫声祕不通。
艳阳迷俗客，幽邃失壶公。
根柢终盘石，桑麻自转蓬。
求师饱灵药，他日访辽东。','',''),('quantangshi-27281','僧院小松','章孝標','quantangshi','','卷28','抛杉背栢冷僧帘，锁月梳风出殿檐。
还似天台新雨后，小峯云外碧尖尖。','',''),('quantangshi-27282','春原早望','章孝標','quantangshi','','卷28','一忝乡书荐，长安未得回。
年光逐渭水，春色上秦台。
燕掠平芜去，人冲细雨来。
东风生故里，又过几花开。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-27283','西山广福院','章孝標','quantangshi','','卷28','野寺孤峯上，危楼耸翠微。
卷帘沧海近，洗钵白云飞。
竹影临经案，松花点衲衣。
日斜登望处，湖畔一僧归。','',''),('quantangshi-27284','游地肺','章孝標','quantangshi','','卷28','市朝扰扰千古，林壑冥冥四贤。
黄鹤不归丹竈，白云自养芝田。
溪滩永夜流月，羽翼清秋在天。
高迹无人更蹑，碧峯寥落孤烟。','',''),('quantangshi-27285','八月','章孝標','quantangshi','','卷28','徙倚仙居遶翠楼，分明宫漏静兼秋。
长安夜夜家家月，几处笙歌几处愁。','',''),('quantangshi-27286','题紫微山上方','章孝標','quantangshi','','卷28','地势连沧海，山名号紫微。
景闲僧坐久，路僻客来稀。
峡影云相照，河流石自围。
尘喧都不到，安得此忘归。','',''),('quantangshi-27287','题杜宾客新丰里幽居','蔣防','quantangshi','','卷28','退迹依三迳，辞荣继二疏。
圣情容解印，帝里许悬车。
已去龙楼籍，犹分御廪储。
风泉输耳目，松竹助玄虚。
调护心常在，山林意有余。
应嗤紫芝客，远就白云居。','',''),('quantangshi-27288','望禁苑祥光','蔣防','quantangshi','','卷28','嘉瑞生天色，葱茏几效祥。
树摇三殿侧，日映九城傍。
仙雾今同色，卿云未可章。
拱汾疑鼎气，临渭比荧光。
岂并春风旧，俄同圣寿长。
微臣时一望，短羽欲翺翔。','',''),('quantangshi-27289','冬至日祥风应候','蔣防','quantangshi','','卷28','节逢清景空，气占二仪中。
独喜登高日，先知应候风。
瑞呈光舜化，庆表盛尧聪。
况与承时叶，还将入律同。
微微万井逼，习习九门通。
遶殿炉烟起，殷勤报岁功。','',''),('quantangshi-27290','春风扇微和','蔣防','quantangshi','','卷28','丽日催迟景，和风扇早春。
暖浮丹凤阙，韶媚黑龙津。
澹荡迎仙仗，霏微送画轮。
绿摇官柳散，红待禁花新。
舞席皆回雪，歌筵暗送尘。
幸当阳律候，惟愿及佳辰。','',''),('quantangshi-27291','日暖万年枝','蔣防','quantangshi','','卷28','新阳归上苑，嘉树独含妍。
散漫添和气，曈昽卷曙烟。
流辉宜圣日，接影贵芳年。
自与恩光近，那关煦妪偏。
结根诚得地，表寿愿符天。
谁道凌寒质，从兹不暧然。','',''),('quantangshi-27292','秋月悬清辉','蔣防','quantangshi','','卷28','秋月沿霄汉，亭亭委素辉。
山明桂花发，池满夜珠归。
入牖人偏揽，临枝鹊正飞。
影连平野净，轮度晓云微。
晶晃浮轻露，裴回映薄帷。
此时千里道，延望独依依。','',''),('quantangshi-27293','八风从律','蔣防','quantangshi','','卷28','制律窥元化，因声感八风。
还从万籁起，更与五音同。
习习芦灰上，泠泠玉管中。
气随时物好，响彻霁天空。
自得阴阳顺，能令惠泽通。
愿吹寒谷里，从此达前蒙。','',''),('quantangshi-27294','藩臣恋魏阙','蔣防','quantangshi','','卷28','剖竹随皇命，分忧镇大藩。
恩波怀魏阙，献纳望天阍。
政奉南风顺，心依北极尊。
梦魂通玉陛，动息寄朱轩。
直以蒸黎念，思陈政化源。
如何子牟意，今古道斯存。','',''),('quantangshi-27295','[秋]稼如云','蔣防','quantangshi','','卷28','肆目如云处，三田大有秋。
葱茏初蔽野，散漫正盈畴。
稍混从龙势，宁同触石幽。
紫芒分羃羃，青頴澹油油。
始惬仓箱望，终无灭裂忧。
西成知不远，雨露复何酬。','',''),('quantangshi-27296','玉巵无当','蔣防','quantangshi','','卷28','美玉常为器，兹焉变漏巵。
酒浆悲莫挹，樽俎念空施。
符彩功难补，盈虚数已亏。
岂惟孤玩好，抑亦类瑕疵。
清越音虽在，操持意渐隳。
赋形期大匠，良璞勿同斯。','',''),('quantangshi-27297','至人无梦','蔣防','quantangshi','','卷28','已赜希微理，知将静默邻。
坐忘宁有梦，迹灭示凝神。
化蝶诚知幻，征兰匪契真。
抱玄虽解带，守一自离尘。
寥朗壶中晓，虚明洞里春。
翛然碧霞客，那比漆园人。','',''),('quantangshi-27298','玄都楼桃','蔣防','quantangshi','','卷28','旧传天上千年熟，今日人间五日香。
红软满枝须作意，莫交方朔施偷将。','',''),('quantangshi-27299','题李宾客旧居','李虞','quantangshi','','卷28','逢时不得致升平，岂是明君忘姓名。
眼暗发枯缘世事，今来无泪哭先生。','',''),('quantangshi-27300','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 一','裴潾','quantangshi','','卷28','动复有原，进退有期。
用在得正，明以知微。
夫惟哲人，会且有归。
静固胜热，安每虑危。
将憩于盘，止亦先机。','',''),('quantangshi-27301','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 二','裴潾','quantangshi','','卷28','植爱在根，钟福有兆。
珠潜巨海，玉蕴昆峤。
披室生白，照夜成昼。
挥翰飞文，入侍左右。
出纳帝命，弘兹在宥。','',''),('quantangshi-27302','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 三','裴潾','quantangshi','','卷28','历难求试，执宪成风。
四镇咸乂，三阶以融。
捧日柱天，造膝纳忠。
建储固本，树屏息戎。
彼狐彼鼠，窒穴扫踪。','',''),('quantangshi-27303','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 四','裴潾','quantangshi','','卷28','我力或屈，我躬莫汚。
三黜如饴，三起惟惧。
再宾为宠，一麾为饫。
昔在治繁，常思归去。
今则合契，行斯中虑。','',''),('quantangshi-27304','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 五','裴潾','quantangshi','','卷28','有凤自南，亦翽其羽。
好姱佳丽，于伊之浒。
五彩含章，九苞合矩。
佩仁服义，鸣中律吕。
我来思卷，薄言遵渚。','',''),('quantangshi-27305','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 六','裴潾','quantangshi','','卷28','凿龙中辟，伊原古奔。
下有秘洞，豁起石门。
竹涧水横，松架雪屯。
岫环如壁，岩虚若轩。
朝昏含景，夏凊冬温。','',''),('quantangshi-27306','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 七','裴潾','quantangshi','','卷28','南溪回舟，西岭望竦。
水远如空，山微似𡾩。
二室峯连，四山骈耸。
五女乍欹，玉华独踊。
云翔日耀，如戴如拱。','',''),('quantangshi-27307','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 八','裴潾','quantangshi','','卷28','飞泉挂空，如决天浔。
万仞悬注，直贯潭心。
月正中央，洞见浅深。
羣山无影，孤鹤时吟。
我啸我歌，或眺或临。','',''),('quantangshi-27308','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 九','裴潾','quantangshi','','卷28','鸟之在巢，风起林摇。
退翔城颠，翠虬扪天。
雨止雪旋，亦息于渊。
人皆知进，我独止焉。
人皆务明，我独晦焉。
邈矣其山默矣其泉。','',''),('quantangshi-27309','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 十','裴潾','quantangshi','','卷28','寝丘之田，土山之上。
孙既贻谋，谢亦遐想。
俭则为福，华固难长。
宁若我心，一泉一壤。
造适为足，超然孤赏。','',''),('quantangshi-27310','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 十一','裴潾','quantangshi','','卷28','其风自西，言发帝庭。
飘彼黄素，堕于山楹。
公拜稽首，靡敢受荣。
宸严再临，俾抚百城。
恋此莫处，星言其征。','',''),('quantangshi-27311','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 十二','裴潾','quantangshi','','卷28','公昔南迈，我不及覩。
言旋旧观，莫获安语。
今则不遑，载骞载举。
离忧莫写，欢好曷叙。
怆矣东望，泣涕如雨。','',''),('quantangshi-27312','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 十三','裴潾','quantangshi','','卷28','山嵇之旧，刘卢之恩。
举世莫尚，惟公是敦。
哀我蠢蠢，念我谆谆。
振此铩翮，扇之腾翻。
斯德未报，只誓子孙。','',''),('quantangshi-27313','前相国赞皇公早葺平泉山居蹔还憩旋起赴诏命作镇浙右輙抒怀赋四言诗十四首奉寄 十四','裴潾','quantangshi','','卷28','迢迢秦塞，南望吴门。
对酒不饮，设琴不援。
何以代面，寄之濡翰。
何以写怀，诗以足言。
无密玉音，以慰我魂。','',''),('quantangshi-27314','白牡丹','裴潾','quantangshi','','卷28','长安豪贵惜春残，争赏先开紫牡丹。
别有玉杯承露冷，无人起就月中看。','',''),('quantangshi-27315','送黄明府晔赴岳州湘阴任','劉三復','quantangshi','','卷28','拟占名场第一科，龙门十上困风波。
三年护塞从戎远，万里投荒失意多。
花县到时铜墨贵，叶舟行处水云和。
遥知布惠苏民后，应向祠堂吊汨罗。','',''),('quantangshi-27316','留题桂州碧浔亭','韋瓘','quantangshi','','卷28','半年领郡固无劳，一日为心素所操。
轮奂未成绳墨在，规模已壮闶闳高。
理人虽切才常短，薄宦都缘命不遭。
从此归耕洛川上，大千江路任风涛。','',''),('quantangshi-27317','赠毛仙翁','崔郾','quantangshi','','卷28','存亡去住一壶中，兄事安期弟葛洪。
甲子已过千岁鹤，仪容方称十年童。
心灵暗合行人数，药力潜均造化功。
终待此身无系累，武陵山下等黄公。','',''),('quantangshi-27318','鸟散余花落','孔溫業','quantangshi','','卷28','美景春堪赏，芳园白日斜。
共看飞好鸟，复见落余花。
来往惊翻电，经过想散霞。
雨余飘处处，风送满家家。
求友声初去，离枝色可嗟。
从兹时节换，谁为惜年华。','',''),('quantangshi-27319','鸟散余花落','趙存約','quantangshi','','卷28','春晓游禽集，幽庭几树花。
坐来惊艳色，飞去堕晴霞。
翅拂繁枝落，风添舞影斜。
彩云飘玉砌，绛雪下仙家。
分散音初静，凋零蘂带葩。
空阶瞻翫久，应共惜年华。','',''),('quantangshi-27320','鸟散余花落','竇洵直','quantangshi','','卷28','晚树春归后，花飞鸟下初。
参差分羽翼，零落满空虚。
风外清香转，林边艳影疎。
轻盈疑雪舞，仿髴似霞舒。
万片情难极，迁乔思有余。
微臣一何幸，吟赏对寒居。','',''),('quantangshi-27321','公无渡河','陳標','quantangshi','','卷28','阴云飒飒浪花愁，半度惊湍半挂舟。
声尽云天君不住，命悬鱼鳖妾同休。
黛娥芳脸垂珠泪，罗袜香裾赴碧流。
余魄岂能衔木石，独将遗恨付箜篌。','',''),('quantangshi-27322','秦王卷衣','陳標','quantangshi','','卷28','秦王宫阙霭春烟，珠树琼枝近碧天。
御气馨香苏合启，帘光浮动水精悬。
霏微罗縠随芳袖，宛转鲛鮹逐宝筵。
从此咸阳一回首，暮云愁色已千年。','',''),('quantangshi-27323','倢伃怨','陳標','quantangshi','','卷28','掌上恩移玉帐空，香珠满眼泣春风。
飘零怨柳凋眉翠，狼籍愁桃坠脸红。
凤辇祗应三殿北，鸾声不向五湖中。
笙歌处处回天睠，独自无情长信宫。','',''),('quantangshi-27324','饮马长城窟','陳標','quantangshi','','卷28','日日风吹虏骑尘，年年饮马汉营人。
千堆战骨那知主，万里枯沙不辨春。
浴谷气寒愁坠指，断崖冰滑恐伤神。
金鞍玉勒无颜色，泪满征衣怨暴秦。','',''),('quantangshi-27325','江南行','陳標','quantangshi','','卷28','水光春色满江天，苹叶风吹荷叶钱。
香蚁翠旗临岸市，艳娥红袖渡江船。
晓惊白鹭联翩雪，浪蹙青茭潋滟烟。
不怕江洲芳草暮，待将秋兴折湖莲。','',''),('quantangshi-27326','长安秋思','陳標','quantangshi','','卷28','吴女秋机织曙霜，冰蚕吐丝月盈筐。
金刀玉指裁缝促，水殿花楼弦管长。
舞袖慢移凝瑞雪，歌尘微动避雕梁。
唯愁陌上芳菲度，狼籍风池荷叶黄。','',''),('quantangshi-27327','赠元和十三年登第进士','陳標','quantangshi','','卷28','春官南院粉墙东，地色初分月色红。
文字一千重马拥，喜欢三十二人同。
眼看鱼变辞凡水，心逐鹦飞出瑞风。
莫怪云泥从此别，总曾惆怅去年中。','',''),('quantangshi-27328','焦桐树','陳標','quantangshi','','卷28','江上烹鱼采野樵，鸾枝摧折半曾烧。
未经良匠材虽散，待得知音尾已焦。
若使琢磨徽白玉，便来风律轸青瑶。
还能万里传山水，三峡泉声岂寂寥。','',''),('quantangshi-27329','寄友人','陳標','quantangshi','','卷28','杜甫在时贪入蜀，孟郊生处却归秦。
如今始会麻姑意，借问山川与后人。','',''),('quantangshi-27330','啄木谣','陳標','quantangshi','','卷28','丁丁向晚急还稀，啄徧庭槐未肯归。
终日与君除蠹害，莫嫌无事不频飞。','',''),('quantangshi-27331','僧院牡丹','陳標','quantangshi','','卷28','琉璃地上开红艳，碧落天头散晓霞。
应是向西无地种，不然争肯重莲花。','',''),('quantangshi-27332','蜀葵','陳標','quantangshi','','卷28','眼前无奈蜀葵何，浅紫深红数百窠。
能共牡丹争几许，得人嫌处祗缘多。','',''),('quantangshi-27333','离家','袁不約','quantangshi','','卷28','步步远晨昏，凄心出里门。
见乌唯有泪，看雁更伤魂。
宿酒宁辞醉，回书讳苦言。
野人应怪笑，不解爱田园。','',''),('quantangshi-27334','送人至岭南','袁不約','quantangshi','','卷28','度岭春风暖，花多不识名。
瘴烟迷月色，巴路傍溪声。
畏药将银试，防蛟避水行。
知君怜酒兴，莫杀醉猩猩。','',''),('quantangshi-27335','长安夜游','袁不約','quantangshi','','卷28','凤城连夜九门通，帝女皇妃出汉宫。
千乘宝莲珠箔卷，万条银烛碧纱笼。
歌声缓过青楼月，香霭潜来紫陌风。
长乐晓钟归骑后，遗簪堕珥满街中。','',''),('quantangshi-27336','病宫人','袁不約','quantangshi','','卷28','佳人卧病动经秋，帘幕繿縿不挂钩。
四体强扶藤夹膝，双环慵整玉搔头。
花颜有幸君王问，药饵无征待诏愁。
惆怅近来销瘦尽，泪珠时傍枕函流。','',''),('quantangshi-27337','句','袁不約','quantangshi','','卷28','愁声秋遶杵，寒色碧归山。
送将欢笑去，收得寂寥回。','',''),('quantangshi-27338','临邛怨','李餘','quantangshi','','卷28','藕花衫子柳花裙，多着沈香慢火熏。
惆怅妆成君不见，空教绿绮伴文君。','',''),('quantangshi-27339','寒食','李餘','quantangshi','','卷28','玉轮江上雨丝丝，公子游春醉不知。
翦渡归来风正急，水溅鞍帕嫩鹅儿。','',''),('quantangshi-27340','句','李餘','quantangshi','','卷28','长安东门别，立马生白发。
霁后轩盖繁，南山瑞烟发。
尝忧车马繁，土薄闻水声。','',''),('quantangshi-27341','至日上公献寿酒','白敏中','quantangshi','','卷28','候晓天门辟，朝天万国同。
瑞云升观阙，香气映华宫。
日色临仙籞，龙颜对昊宫。
羽仪瞻百姓，献寿侍三公。
化被君王洽，恩沾草木丰。
自欣朝玉座，宴此咏皇风。','',''),('quantangshi-27342','贺收复秦原诸州诗','白敏中','quantangshi','','卷28','一诏皇城四海颁，丑戎无数束身还。
戍楼吹笛人休战，牧野嘶风马自闲。
河水九盘收数曲，天山千里锁诸关。
西边北塞今无事，为报东南夷与蛮。','',''),('quantangshi-27343','句','白敏中','quantangshi','','卷28','南浦花临水，东楼月映风。','',''),('quantangshi-27344','遣兴','李敬方','quantangshi','','卷28','果窥丹竈鹤，莫羡白头翁。
日月仙壶外，筋骸药臼中。
云归无定所，鸟迹不留空。
何必劳方寸，岖岐问远公。','',''),('quantangshi-27345','劝酒','李敬方','quantangshi','','卷28','不向花前醉，花应解笑人。
只忧连夜雨，又过一年春。
日日无穷事，区区有限身。
若非杯酒里，何以寄天真。','',''),('quantangshi-27346','近无西耗','李敬方','quantangshi','','卷28','远戎兵压境，迁客泪横襟。
烽候惊春塞，缧囚困越吟。
自怜牛马走，未识犬羊心。
一月无消息，西看日又沈。','',''),('quantangshi-27347','天台晴望','李敬方','quantangshi','','卷28','天台十二旬，一片雨中春。
林果黄梅尽，山苗半夏新。
阳乌晴展翅，阴魄夜飞轮。
坐冀无云物，分明见北辰。','',''),('quantangshi-27348','闻高侍御卒贬所','李敬方','quantangshi','','卷28','西京高院长，直气似吾徒。
走马论边备，飞声感庙谟。
官移人未察，身没事多符。
寂寞他年后，名编野史无。','',''),('quantangshi-27349','题黄山汤院','李敬方','quantangshi','','卷28','楚镇惟黄岫，灵泉浴圣源。
煎熬何处所，炉炭孰司存。
沙暖泉长拂，霜笼水更温。
不疏还自决，虽挠未尝浑。
地启岩为洞，天开石作盆。
常留今日色，不减故年痕。
阴焰潜生海，阳光暗烛坤。
定应邻火宅，非独过焦原。
龙讶经冬润，莺疑满谷暄。
善烹寒食茗，能变早春园。
及物功何大，随流道益尊。
洁斋齐物主，疗病夺医门。
外祕千峰秀，旁通百潦奔。
禅家休问疾，骚客罢招魂。
卧理黔川守，分忧汉主恩。
惨伤因有暇，徒御诫无喧。
痒闷头风切，爬搔臂力烦。
披榛通白道，束马置朱幡。
谢屐缘危磴，戎装逗远村。
慢游登竹迳，高步入山根。
崖巘差行竈，蓬茅过小轩。
御寒增帐幕，甃影尽璵璠。
不与华池语，宁将浴室论。
洗心过顷刻，浸发迨朝暾。
汗洽聊箕踞，支羸暂虎蹲。
濯缨闲更入，漱齿渴仍吞。
气燠胜重絸，风和敌一尊。
适来还蹭蹬，复出又攀援。
形秽忻除垢，神嚣喜破昏。
明夷征立象，既济感文言。
已阂眠沙麂，仍妨卧石猨。
香驱蒸雾起，烟霿湿云屯。
破险更祠宇，凭高易庙垣。
旧基绝仄足，新构忽行鵷。
胜地非无栋，征途遽改辕。
贪程归路远，折政讼庭繁。
兴往留年月，诗成遗子孙。
已镌东壁石，名姓寄无垠。','',''),('quantangshi-27350','太和公主还宫','李敬方','quantangshi','','卷28','二纪烟尘外，凄凉转战归。
胡笳悲蔡琰，汉使泣明妃。
金殿更戎幄，青祛换毳衣。
登车随伴仗，谒庙入中闱。
汤沐疏封在，关山故梦非。
笑看鸿北向，休咏鹊南飞。
宫髻怜新样，庭柯想旧围。
生还侍儿少，熟识内家稀。
凤去楼扃夜，鸾孤匣掩辉。
应怜禁园柳，相见倍依依。','',''),('quantangshi-27351','汴河直进船','李敬方','quantangshi','','卷28','汴水通淮利最多，生人为害亦相和。
东南四十三州地，取尽脂膏是此河。','',''),('quantangshi-27352','享太庙乐章','李回','quantangshi','','卷28','受天明命，敷佑下土。
化时以俭，卫文以武。
氛消夷夏，俗臻往古。
亿万斯年，形于律吕。','',''),('quantangshi-27353','天长路别朱大山路却寄','李回','quantangshi','','卷28','驿骑难随伴，寻山半忆君。
苍崖残月路，犹数过溪云。','',''),('quantangshi-27354','寄酬朱大后亭夜坐留别','李回','quantangshi','','卷28','十夜郡城宿，苦吟身未闲。
那堪西郭别，雪路问青山。','',''),('quantangshi-27355','祖龙行','常楚老','quantangshi','','卷28','黑云兵气射天裂，壮士朝眠梦冤结。
祖龙一夜死沙丘，胡亥空随鲍鱼辙。
腐肉偷生三千里，伪书先赐扶苏死。
墓接骊山土未干，瑞光已向芒砀起。
陈胜城中鼓三下，秦家天地如崩瓦。
龙蛇撩乱入咸阳，少帝空随汉家马。','',''),('quantangshi-27356','江上蚊子','常楚老','quantangshi','','卷28','飘摇挟翅亚红腹，江边夜起如雷哭。
请问贪婪一点心，臭腐填腹几多足。
越女如花住江曲，嫦娥夜夜凝双睩。
怕君撩乱锦窗中，十轴轻绡围夜玉。','',''),('quantangshi-27357','句','常楚老','quantangshi','','卷28','一从黄帝葬桥山，碧落千门锁元气。','',''),('quantangshi-27358','九成宫','李甘','quantangshi','','卷28','中原无鹿海无波，凤辇鸾旗出幸多。
今日故宫归寂寞，太平功业在山河。','',''),('quantangshi-27359','谒李相不遇','平曾','quantangshi','','卷28','老夫三日门前立，珠箔银屏昼不开。
诗卷却抛书袋里，正如闲看华山来。','',''),('quantangshi-27360','留别薛仆射','平曾','quantangshi','','卷28','梯山航海几崎岖，来谒金陵薜大夫。
毛发竖时趋剑戟，衣冠俨处拜冰壶。
诚知两轴非珠玉，深愧三缣恤旅途。
明日过江风景好，不堪回首望勾吴。','',''),('quantangshi-27361','絷白马诗上薛仆射','平曾','quantangshi','','卷28','白马披鬃练一团，今朝被绊欲行难。
雪中放去空留迹，月下牵来只见鞍。
向北长鸣天外远，临风斜控耳边寒。
自知毛骨还应异，更请孙阳仔细看。','',''),('quantangshi-27362','题所书黄庭经后','景審','quantangshi','','卷28','金粉为书重莫过，黄庭旧许右军多。
请看今日酬恩德，何似当年为爱鹅。','',''),('quantangshi-27363','句','景審','quantangshi','','卷28','暮鵶不噪禁城树，衙鼓未残兵卫秋。','',''),('quantangshi-27364','秋日陕州道中作','顧非熊','quantangshi','','卷28','孤客秋风里，驱车入陕西。
关河午时路，村落一声鸡。
树势标秦远，天形到岳低。
谁知我名姓，来往自栖栖。','',''),('quantangshi-27365','经杭州','顧非熊','quantangshi','','卷28','郡郭遶江濆，人家近白云。
晚涛临槛看，夜橹隔城闻。
浦转山初尽，虹斜雨未分。
有谁知我意，心绪逐鸥羣。','',''),('quantangshi-27366','经河中','顧非熊','quantangshi','','卷28','一望蒲城路，关河气象雄。
楼台山色里，杨柳水声中。
思起怀吴客，行斜向碛鸿。
我来寻古迹，唯见舜祠风。','',''),('quantangshi-27367','送僧归洞庭','顧非熊','quantangshi','','卷28','江山万万重，归去指何峰。
未入连云寺，先斋越浪钟。
岛香廻栈柏，秋荫出庵松。
若救吴人病，须降震泽龙。','',''),('quantangshi-27368','题觉真上人院','顧非熊','quantangshi','','卷28','长安车马地，此院闭松声。
新罢九天讲，旧曾诸岳行。
能诗因作偈，好客岂关名。
约我中秋夜，同来看月明。','',''),('quantangshi-27369','寄太白无能禅师','顧非熊','quantangshi','','卷28','太白山中寺，师居最上方。
猎人偷佛火，栎鼠戏禅牀。
定久衣尘积，行稀径草长。
有谁来问法，林杪过残阳。','',''),('quantangshi-27370','舒州酬别侍御','顧非熊','quantangshi','','卷28','故交他郡见，下马失愁容。
执手向残日，分襟在晚钟。
乡心随皖水，客路过庐峰。
众惜君材器，何为滞所从。','',''),('quantangshi-27371','姚岩寺路怀友','顧非熊','quantangshi','','卷28','路向姚岩寺，多行洞壑间。
鹤声连坞静，溪色带村闲。
疎叶秋前渚，斜阳雨外山。
怜君不得见，诗思最相关。','',''),('quantangshi-27372','天河阁到啼猿阁即事','顧非熊','quantangshi','','卷28','万壑褒中路，何层不架虚。
湿云和栈起，燋枿带畲余。
岩狖牵垂果，湍禽接迸鱼。
每逢维艇处，坞里有人居。','',''),('quantangshi-27373','夏日会修行段将军宅','顧非熊','quantangshi','','卷28','爱君书院静，莎覆藓堦浓。
连穗古藤暗，领雏幽鸟重。
罇前迎远客，林杪见晴峰。
谁谓朱门内，云山满座逢。','',''),('quantangshi-27374','送杭州姚员外','顧非熊','quantangshi','','卷28','浙江江上郡，杨柳到时春。
堑起背城雁，帆分向海人。
峤云侵寺吐，汀月隔楼新。
静理更何事，还应咏白苹。','',''),('quantangshi-27375','送朴处士归新罗','顧非熊','quantangshi','','卷28','少年离本国，今去已成翁。
客梦孤舟里，乡山积水东。
鳌沈崩巨岸，龙鬬出遥空。
学得中华语，将归谁与同。','',''),('quantangshi-27376','送马戴入山','顧非熊','quantangshi','','卷28','古木乱重重，何人识去踪。
斜阳收万壑，圆月上三峰。
云里泉萦石，窗间鸟下松。
唯应采药客，时与此相逢。','',''),('quantangshi-27377','送喻凫春归江南','顧非熊','quantangshi','','卷28','去年登第客，今日及春归。
鸎影离秦马，莲香入楚衣。
里闾争庆贺，亲戚共光辉。
唯我门前浦，苔应满钓矶。','',''),('quantangshi-27378','送友人及第归苏州','顧非熊','quantangshi','','卷28','见君先得意，希我命还通。
不道才堪竝，多缘蹇共同。
鹤鸣荒苑内，鱼跃夜潮中。
若问家山路，知连震泽东。','',''),('quantangshi-27379','送皇甫司录赴黔南幕','顧非熊','quantangshi','','卷28','黔南从事客，禄利先来饶。
官受外台屈，家移一舸遥。
夜猿声不断，寒木叶微凋。
远别因多感，新郎倍寂寥。','',''),('quantangshi-27380','寄九华山费拾遗','顧非熊','quantangshi','','卷28','先生九华隐，鸟道隔尘埃。
石室和云住，山田引烧开。
久闲仙客降，高卧诏书来。
一入深林去，人间更不回。','',''),('quantangshi-27381','雁','顧非熊','quantangshi','','卷28','逐暖来南国，迎寒背朔云。
下时波势出，起处阵形分。
声急奔前侣，行低续后羣。
何人寄书札，绝域可知闻。','',''),('quantangshi-27382','铜雀妓','顧非熊','quantangshi','','卷28','鸦散陵树晓，筵开繐帐空。
婵娟宠休妬，歌舞怨来同。
往事与尘化，新愁生曲终。
廻轩叶正落，寂寞听秋风。','',''),('quantangshi-27383','早秋雨夕','顧非熊','quantangshi','','卷28','贫居常寂寞，况复是秋天。
黄叶如霜后，清风似水边。
中宵疑有雁，当夕暂无蝉。
就枕终难寐，残灯灭又然。','',''),('quantangshi-27384','天津桥晚望','顧非熊','quantangshi','','卷28','晴登洛桥望，寒色古槐稀。
流水东不息，翠华西未归。
云收中岳近，钟出后宫微。
回首禁门路，羣鸦度落晖。','',''),('quantangshi-27385','月夜登王屋仙坛','顧非熊','quantangshi','','卷28','月临峰顶坛，气爽觉天宽。
身去银河近，衣霑玉露寒。
云中日已赤，山外夜初残。
即此是仙境，惟愁再上难。','',''),('quantangshi-27386','下第后晓坐','顧非熊','quantangshi','','卷28','远客滞都邑，老惊时节催。
海边身梦觉，枕上鼓声来。
起见银河没，坐知阊阖开。
何为此生内，终夜泣尘埃。','',''),('quantangshi-27387','下第后送友人不及','顧非熊','quantangshi','','卷28','失意经寒食，情偏感别离。
来逢人已去，坐见柳空垂。
细雨飞黄鸟，新蒲长绿池。
自倾相送酒，终不展愁眉。','',''),('quantangshi-27388','与无可宿辉公院','顧非熊','quantangshi','','卷28','夜僧同静语，秋寺近严城。
世路虽多梗，玄心各自明。
寒池清月彩，危阁听林声。
傥许双摩顶，随缘万劫生。','',''),('quantangshi-27389','题平陆县亭','顧非熊','quantangshi','','卷28','孤亭临峭岸，别有远泉来。
山与中条合，河逢一曲廻。
夜声多雁过，晚色乱云开。
却自求僮仆，淹留莫谩催。','',''),('quantangshi-27390','题马儒乂石门山居','顧非熊','quantangshi','','卷28','寻君石门隐，山近渐无青。
鹿迹入柴户，树身穿草亭。
云低收药径，苔惹取泉瓶。
此地客难到，夜琴谁共听。','',''),('quantangshi-27391','题春明门外镇国禅院','顧非熊','quantangshi','','卷28','空门临大道，师坐此中禅。
过客自生敬，焚香惟默然。
书灯明象外，古木覆檐前。
不得如驯鸽，人间万虑牵。','',''),('quantangshi-27392','夏夜汉渚归舟即事','顧非熊','quantangshi','','卷28','扁舟江濑尽，归路海山青。
巨浸分圆象，危樯入众星。
雨遥明电影，蜃晓识楼形。
不是长游客，那知造化灵。','',''),('quantangshi-27393','酬均州郑使君见送归茅山','顧非熊','quantangshi','','卷28','饯行诗意厚，惜别独筵重。
解缆城边柳，还舟海上峰。
饮猨当濑见，浴鸟带槎逢。
吏隐应难逐，为霖是蛰龙。','',''),('quantangshi-27394','成名后将归茅山酬羣公见送','顧非熊','quantangshi','','卷28','此名谁不得，人贺至公难。
素业承家了，离筵去国欢。
暮天行雁断，晓渡落潮寒。
旧隐茅峰下，松根石上盘。','',''),('quantangshi-27395','酬陈摽评事喜及第与段何共贻','顧非熊','quantangshi','','卷28','至公平得意，自喜不因媒。
榜入金门去，名从玉案来。
欢情听鸟语，笑眼对花开。
若拟华筵贺，当期醉百杯。','',''),('quantangshi-27396','关试后嘉会里闻蝉感怀呈主司','顧非熊','quantangshi','','卷28','昔闻惊节换，常抱异乡愁。
今听当命遂，方欢上国游。
吟才依树午，风已报庭秋。
并觉声声好，怀恩忽泪流。','',''),('quantangshi-27397','赠友人','顧非熊','quantangshi','','卷28','吾友昔同道，唯予今独行。
青云期未遂，白发镊还生。
旧隐连江色，新春闻鸟声。
休明独不遇，何计可归耕。','',''),('quantangshi-27398','落第后赠同居友人','顧非熊','quantangshi','','卷28','有情天地内，多感是诗人。
见月长怜夜，看花又惜春。
愁为终日客，闲过少年身。
寂寞正相对，笙歌满四隣。','',''),('quantangshi-27399','冬日寄蔡先辈校书京','顧非熊','quantangshi','','卷28','弱冠下茅岭，中年道不行。
旧交因贵绝，新月对愁生。
旅思风飘叶，归心雁过城。
惟君知我苦，何异爨桐鸣。','',''),('quantangshi-27400','行经褒城寄兴元姚从事','顧非熊','quantangshi','','卷28','往岁客龟城，同时听鹿鸣。
君兼莲幕贵，我得桂枝荣。
栈阁危初尽，褒川路忽平。
心期一壶酒，静话别离情。','',''),('quantangshi-27401','下第后寄高山人','顧非熊','quantangshi','','卷28','我家堂屋前，仰视大茅巅。
潭静鸟声异，地寒松色鲜。
人眠瓮牖月，鹿饮竹门泉。
多愧隣高隐，无成又一年。','',''),('quantangshi-27402','寄紫阁无名新罗头陁僧','顧非熊','quantangshi','','卷28','椶牀已自檠，野宿更何营。
大海谁同过，空山虎共行。
身心相外尽，鬓发定中生。
紫阁人来礼，无名便是名。','',''),('quantangshi-27403','送信州卢员外兼寄薛员外','顧非熊','quantangshi','','卷28','五马弋阳行，分忧出禁城。
粉闱移席近，茜斾越疆行。
德茂荣方渐，仁深瑞必呈。
疲甿复何幸，前政已残声。','',''),('quantangshi-27404','送于中丞入回鹘','顧非熊','quantangshi','','卷28','风沙万里行，边色看双旌。
去展中华礼，将安外国情。
朝衣惊异俗，牙帐见新正。
料得归来路，春深草未生。','',''),('quantangshi-27405','送李廓侍御赴劒南','顧非熊','quantangshi','','卷28','鸟道见狼烟，元戎正急贤。
图书借朋友，吟咏入戈鋋。
山色城池近，江声鼓角连。
不应夸战胜，知在檄蛮篇。','',''),('quantangshi-27406','送友人归汉阳','顧非熊','quantangshi','','卷28','罇前别楚客，云水思萦回。
秦野春将尽，商山花不开。
鸥惊帆乍起，虹见雨初来。
自有归期在，蝉声处处催。','',''),('quantangshi-27407','送造微上人归淮南觐兄','顧非熊','quantangshi','','卷28','到家方坐夏，柳巷对兄禅。
雨断芜城路，虹分建邺天。
赴斋随野鹤，迎水上渔船。
终拟归何处，三湘思渺然。','',''),('quantangshi-27408','赋得江边柳送陈许郭员外','顧非熊','quantangshi','','卷28','拂水复含烟，行分古岸边。
春风正摇落，客思共悠然。
絮急频萦水，根灵复系船。
微阴覆离岸，祗此醉昏眠。','',''),('quantangshi-27409','武宗挽歌词二首 一','顧非熊','quantangshi','','卷28','睿略皇威远，英风帝业开。
竹林方受位，薤露忽兴哀。
静塞妖星落，和戎贵主回。
龙髯不可附，空见望仙台。','',''),('quantangshi-27410','武宗挽歌词二首 二','顧非熊','quantangshi','','卷28','苍生期渐泰，皇道欲中兴。
国用销灵像，农功复冗僧。
冕旒辞北阙，歌舞怨西陵。
惟有金茎石，长宵对玉绳。','',''),('quantangshi-27411','会中赋得新年','顧非熊','quantangshi','','卷28','万古如昨日，一年加一晨。
暗生无限事，潜老几多人。
归路旧侣尽，故乡回雁新。
那堪独惆怅，犹是白衣身。','',''),('quantangshi-27412','斜谷邮亭翫海棠花','顧非熊','quantangshi','','卷28','忽识海棠花，令人只叹嗟。
艳繁惟共笑，香近试堪夸。
驻骑忘山险，持杯任日斜。
何川是多处，应遶羽人家。','',''),('quantangshi-27413','万年厉员外宅残菊','顧非熊','quantangshi','','卷28','才过重阳后，人心已为残。
近霜须苦惜，带蝶更宜看。
色减频经雨，香销恐渐寒。
今朝陶令宅，不醉却应难。','',''),('quantangshi-27414','题永福寺临淮亭','顧非熊','quantangshi','','卷28','淮上前朝寺，因公始建亭。
虽无山可望，多有鹤堪听。
引客闲垂钓，看僧静灌瓶。
带潮秋见月，隔竹晓闻经。
水气侵衣冷，苹风入座馨。
路逢沙獭上，船值海人停。
砧杵鸣孤戍，乌鸢下远汀。
连波芳草阔，极目暮天青。
创置嗟心匠，幽栖得地形。
常来劝农事，赖此近郊坰。','',''),('quantangshi-27415','陈情上郑主司','顧非熊','quantangshi','','卷28','登第久无缘，归情思渺然。
艺慙公道日，身贱太平年。
未识笙歌乐，虚逢岁月迁。
羁怀吟独苦，愁眼愧花妍。
求达非荣己，修辞欲继先。
秦城春十二，吴苑路三千。
茅屋山岚入，柴门海浪连。
遥心犹送雁，归梦不离船。
时节思家夜，风霜作客天。
庭闱乖旦暮，兄弟阻团圆。
朝乏新知己，邨荒旧业田。
受恩期望外，效死誓生前。
愿察为裘意，彷徉和角篇。
恳情今吐尽，万一冀哀怜。','',''),('quantangshi-27416','长安清明言怀','顧非熊','quantangshi','','卷28','明时帝里遇清明，还逐游人出禁城。
九陌芳菲莺自啭，万家车马雨初晴。
客中下第逢今日，愁里看花厌此生。
春色来年谁是主，不堪憔悴更无成。','',''),('quantangshi-27417','出塞即事二首 一','顧非熊','quantangshi','','卷28','塞山行尽到乌延，万顷沙堆见极边。
河上月沉鸿雁起，碛中风度犬羊膻。
席箕草断城池外，护柳花开帐幕前。
此处游人堪下泪，更闻终日望狼烟。','',''),('quantangshi-27418','出塞即事二首 二','顧非熊','quantangshi','','卷28','贺兰山便是戎疆，此去萧关路几荒。
无限城池非汉界，几多人物在胡乡。
诸侯持节望吾土，男子生身负我唐。
廻望风光成异域，谁能献计复河湟。','',''),('quantangshi-27419','送李相公昭义平复起彼宣慰员外副行','顧非熊','quantangshi','','卷28','天井虽收寇未平，所司促战急王程。
晓驰云骑穿花去，夜与星郎带月行。
新咏尽题关外事，故乡因过洛阳城。
时逢寒食游人识，竟说从来有大名。','',''),('quantangshi-27420','送从叔尉渑池','顧非熊','quantangshi','','卷28','同登科第皆清列，尚爱东畿一尉闲。
虽有田园供海畔，且无宗党在朝班。
甘贫只为心知道，晚达多缘性好山。
白首青衫犹未换，又骑羸马出函关。','',''),('quantangshi-27421','哭韩将军','顧非熊','quantangshi','','卷28','将军不复见仪形，笑语随风入杳冥。
战马旧骑嘶引葬，歌姬新嫁哭辞灵。
功勋客问求为志，服玩僧收与转经。
寂寞一家春色里，百花开落满山庭。','',''),('quantangshi-27422','崔卿双白鹭','顧非熊','quantangshi','','卷28','朝客高清爱水禽，绿波双鹭在园林。
立当风里丝摇急，步遶池边字印深。
刷羽竞生堪画势，依泉各有取鱼心。
我乡多傍门前见，坐觉烟波思不禁。','',''),('quantangshi-27423','子夜夏秋二曲 一','顧非熊','quantangshi','','卷28','相持薄罗扇，绿树听鸣蜩。
君筵呈妙舞，香汗湿鲛绡。','',''),('quantangshi-27424','子夜夏秋二曲 二','顧非熊','quantangshi','','卷28','银牀梧叶下，便觉漏声长。
露砌蛩吟切，那怜白苎凉。','',''),('quantangshi-27425','关山月','顧非熊','quantangshi','','卷28','海上清光发，边营照转凄。
深闺此宵梦，带月过辽西。','',''),('quantangshi-27426','采莲词','顧非熊','quantangshi','','卷28','纤手折芙蕖，花洒罗衫湿。
女伴唤回船，前溪风浪急。','',''),('quantangshi-27427','秋月夜','顧非熊','quantangshi','','卷28','旅雁迎风度，阶翻月露华。
砧声鸣夜永，江上几多家。','',''),('quantangshi-27428','登楼','顧非熊','quantangshi','','卷28','登楼一南望，淮树楚山连。
见雁无书寄，归吴定此年。','',''),('quantangshi-27429','阊门书感','顧非熊','quantangshi','','卷28','凫鹥踏波舞，树色接横塘。
远近蘼芜绿，吴宫总夕阳。','',''),('quantangshi-27430','送内乡张主簿赴任','顧非熊','quantangshi','','卷28','松窗久是飡霞客，山县新为主印官。
混俗故来分利禄，不教长作异人看。','',''),('quantangshi-27431','瓜洲送朱万言','顧非熊','quantangshi','','卷28','渡头风晚叶飞频，君去还吴我入秦。
双泪别家犹未断，不堪仍送故乡人。','',''),('quantangshi-27432','秋夜长安病后作','顧非熊','quantangshi','','卷28','秋中帝里经旬雨，晴后蝉声更不闻。
牢落闲庭新病起，故乡南去雁成羣。','',''),('quantangshi-27433','题王使君片石','顧非熊','quantangshi','','卷28','势似孤峯一片成，坐来疑有白云生。
主人莫怪殷勤看，远客长怀旧隐情。','',''),('quantangshi-27434','暮春早起','顧非熊','quantangshi','','卷28','柳[梢]暗露滴清晨，帘下偏惊独起人。
鶗鴂数声花渐落，园林是处总残春。','',''),('quantangshi-27435','途次怀归','顧非熊','quantangshi','','卷28','陇头禾偃乳乌飞，兀倚征鞍倍忆归。
正值江南新酿熟，可容闲却老莱衣。','',''),('quantangshi-27436','寄陆隐君','顧非熊','quantangshi','','卷28','相思迢递隔重城，鸟散堦前竹坞清。
定拟秋凉过南崦，长松石上听泉声。','',''),('quantangshi-27437','寄吴山净上人','顧非熊','quantangshi','','卷28','忆共蒲团话夜钟，别来落叶閟行踪。
遥知黛色秋常翫，住向灵岩第几峯。','',''),('quantangshi-27438','送徐五纶南行过吴','顧非熊','quantangshi','','卷28','吴门东去路三千，到得阊门暂泊船。
老父出迎应倒屣，贫居江上信谁传。','',''),('quantangshi-27439','游天台山','張祜','quantangshi','','卷28','崔嵬海西镇，灵迹传万古。
羣峰日来朝，累累孙侍祖。
三茅即拳石，二室犹块土。
傍洞窟神仙，中岩宅龙虎。
名从干取象，位与坤作辅。
鸾鹤自相羣，前人空若瞽。
巉巉割秋碧，娲女徒巧补。
视听出尘埃，处高心渐苦。
才登招手石，肘底笑天姥。
仰看华盖尖，赤日云上午。
奔雷撼深谷，下见山脚雨。
回首望四明，矗若城一堵。
昏晨邈千态，恐动非自主。
控鹄大梦中，坐觉身[栩栩]。
东溟子时月，却孕元化母。
彭蠡不盈杯，浙江微辨缕。
石梁屹横架，万仞青壁竖。
却瞰赤城颠，势来如刀弩。
盘松国清道，九里天莫覩。
穹崇上攒三，突兀傍耸五。
空崖绝凡路，痴立麋与麈。
邈峻极天门，覰深窥地户。
金庭路非远，徒步将欲举。
身乐道家流，敦儒若一矩。
行寻白云叟，礼象登峻宇。
佛窟绕杉岚，仙坛半榛莽。
悬崖与飞瀑，险喷难足俯。
海眼三井通，洞门双阙拄。
琼台下昏侧，手足前采乳。
但造不死乡，前劳何足数。','',''),('quantangshi-27440','送蜀客','張祜','quantangshi','','卷28','楚客去岷江，西南指天末。
平生不达意，万里船一发。
行行三峡夜，十二峰顶月。
哀猨别曾林，忽忽声断咽。
嘉陵水初涨，岩岭耗积雪。
不妨高唐云，却藉宋玉说。
峨眉远凝黛，脚底谷洞穴。
锦城昼氲氲，锦水春活活。
成都滞游地，酒客须醉杀。
莫恋卓家垆，相如已屑屑。','',''),('quantangshi-27441','团扇郎','張祜','quantangshi','','卷28','白团扇，今来此去捐。
愿得入郎手，团圆郎眼前。','',''),('quantangshi-27442','西江行','張祜','quantangshi','','卷28','日下西塞山，南来东庭客。
晴空一鸟渡，万里秋江碧。
惆怅异乡人，偶言空脉脉。','',''),('quantangshi-27443','涢川寺路','張祜','quantangshi','','卷28','日沉西涧阴，远驱愁突兀。
烟苔湿凝地，露竹光滴月。
时见一僧来，脚边云勃勃。','',''),('quantangshi-27444','夜雨','張祜','quantangshi','','卷28','霭霭云四黑，秋林响空堂。
始从寒瓦中，淅沥断人肠。
愁肠方九回，寂寂夜未央。','',''),('quantangshi-27445','秋晚途中作','張祜','quantangshi','','卷28','落日驰车道，秋郊思不胜。
水云遥断绪，山日半衔棱。
远吠邻村处，计想羡他能。','',''),('quantangshi-27446','拔蒲歌','張祜','quantangshi','','卷28','拔蒲来，领郎镜湖边。
郎心在何处，莫趁新莲去。
拔得无心蒲，问郎看好无。','',''),('quantangshi-27447','车遥遥','張祜','quantangshi','','卷28','东方昽昽车轧轧，地色不分新去辙。
闺门半掩窗半空，斑斑枕花残泪红。
君心若车千万转，妾身如辙遗渐远。
碧川迢迢山宛宛，马蹄在耳轮在眼。
桑间女儿情不浅，莫道野蚕能作茧。','',''),('quantangshi-27448','捉搦歌','張祜','quantangshi','','卷28','门上关，墙上棘。
窗中女子声唧唧，洛阳大道徒自直。
女子心在婆舍侧，呜呜笼鸟触四隅。
养男男娶妇，养女女嫁夫。
阿婆六十翁七十，不知女子长日泣，从他嫁去无悒悒。','',''),('quantangshi-27449','雁门太守行','張祜','quantangshi','','卷28','城头月没霜如水，趚趚踏沙人似鬼。
灯前拭泪试香裘，长引一声残漏子。
驼囊泻酒酒一杯，前头滴血心不回。
闺中年少妻莫哀，鱼金虎竹天上来，雁门山边骨成灰。','',''),('quantangshi-27450','思归引','張祜','quantangshi','','卷28','重重作闺清旦鐍，两耳深声长不彻。
深宫坐愁百年身，一片玉中生愤血。
焦桐弹罢丝自绝，漠漠暗魂愁夜月。
故乡不归谁共穴，石上作蒲蒲九节。','',''),('quantangshi-27451','司马相如琴歌','張祜','quantangshi','','卷28','凤兮凤兮非无皇，山重水阔不可量。
梧桐结阴在朝阳，濯羽弱水鸣高翔。','',''),('quantangshi-27452','雉朝飞操','張祜','quantangshi','','卷28','朝阳陇东泛暖景，双啄双飞双顾影。
朱冠锦襦聊日整，漠漠雾中如衣褧。
伤心卢女弦，七十老翁长独眠。
雄飞在草雌在田，衷肠结愤气呵天。
圣人在上心不偏，翁得女妻甚可怜。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-27453','观徐州李司空猎','張祜','quantangshi','','卷28','晓出郡城东，分围浅草中。
红旗开向日，白马骤迎风。
背手抽金镞，翻身控角弓。
万人齐指处，一雁落寒空。','',''),('quantangshi-27454','猎','張祜','quantangshi','','卷28','残猎渭城东，萧萧西北风。
雪花[鹰]背上，冰片马蹄中。
臂挂捎荆兔，腰悬落箭鸿。
归来逞余勇，儿子乱弯弓。','',''),('quantangshi-27455','鹦鹉','張祜','quantangshi','','卷28','栖栖南越鸟，色丽思沉淫。
暮隔碧云海，春依红树林。
雕笼悲敛翅，画阁岂关心。
无事能言语，人闻怨恨深。','',''),('quantangshi-27456','再吟鹦鹉','張祜','quantangshi','','卷28','万里去心违，奇毛觉自非。
美人怜解语，凡鸟畏多机。
未胜无丹嘴，何劳事绿衣。
雕笼终不恋，会向故山归。','',''),('quantangshi-27457','酬郑模司直见寄','張祜','quantangshi','','卷28','故人沧海曲，聊复话平生。
喜是狂奴态，羞为老婢声。
宦途终日薄，身事长年轻。
犹赖书千卷，长随一棹行。','',''),('quantangshi-27458','送苏绍之归岭南','張祜','quantangshi','','卷28','孤舟越客吟，万里旷离襟。
夜月江流阔，春云岭路深。
珠繁杨氏果，翠耀孔家禽。
无复天南梦，相思空树林。','',''),('quantangshi-27459','送沈下贤谪尉南康','張祜','quantangshi','','卷28','秋风江上草，先是客心摧。
万里故人去，一行新雁来。
山高云绪断，浦逈日波颓。
莫怪南康远，相思不可裁。','',''),('quantangshi-27460','送卢弘本浙东觐省','張祜','quantangshi','','卷28','东望故山高，秋归值小舠。
怀中陆绩橘，江上伍员涛。
好去宁鸡口，加餐及蟹螯。
知君思无倦，为我续离骚。','',''),('quantangshi-27461','晚次荆溪馆呈崔明府','張祜','quantangshi','','卷28','舣舟阳羡馆，飞步缭疎楹。
山暝水云碧，月凉烟树清。
长桥深漾影，远橹下摇声。
况是无三害，弦歌初政成。','',''),('quantangshi-27462','寄朗州徐员外','張祜','quantangshi','','卷28','江岭昔飘蓬，人间值俊雄。
关西今孔子，城北旧徐公。
清夜游何处，良辰此不同。
伤心几年事，一半在湖中。','',''),('quantangshi-27463','旅次上饶溪','張祜','quantangshi','','卷28','碧溪行几折，凝棹宿汀沙。
角断孤城掩，楼深片月斜。
夜桥昏水气，秋竹静霜华。
更想曾题壁，凋零可叹嗟。','',''),('quantangshi-27464','送徐彦夫南迁','張祜','quantangshi','','卷28','万里客南迁，孤城涨海边。
瘴云秋不断，阴火夜长然。
月上行虚市，风廻望舶船。
知君还自洁，更为酌贪泉。','',''),('quantangshi-27465','送韦整尉长沙','張祜','quantangshi','','卷28','远远长沙去，怜君利一官。
风帆彭蠡疾，云水洞庭宽。
木客提蔬束，江乌接饭丸。
莫言卑湿地，未必乏新欢。','',''),('quantangshi-27466','送外甥','張祜','quantangshi','','卷28','衰年生侄少，唯尔最关心。
偶作魏舒别，聊为殷浩吟。
白波舟不定，黄叶路难寻。
自此尊中物，谁当更共斟。','',''),('quantangshi-27467','赠薛鼎臣侍御','張祜','quantangshi','','卷28','一命前途远，双曹小邑闲。
夜潮人到郭，春雾鸟啼山。
浅濑横沙堰，高岩峻石斑。
不堪曾倚棹，犹复梦升攀。','',''),('quantangshi-27468','送曾黯游夔州','張祜','quantangshi','','卷28','不远夔州路，层波滟滪连。
下来千里峡，入去一条天。
树色秋帆上，滩声夜枕前。
何堪正危侧，百丈半山颠。','',''),('quantangshi-27469','送李长史归涪州','張祜','quantangshi','','卷28','涪江江上客，岁晚却还乡。
暮过高唐雨，秋经巫峡霜。
急滩船失次，叠嶂树无行。
好为题新什，知君思不常。','',''),('quantangshi-27470','赠契衡上人','張祜','quantangshi','','卷28','小门开板阁，终日是逢迎。
语笑人同坐，修持意别行。
水花秋始发，风竹夏长清。
一恨凄惶久，怜师记姓名。','',''),('quantangshi-27471','走笔赠许玖赴桂州命','張祜','quantangshi','','卷28','桂林真重德，莲幕藉殊才。
直气自消瘴，远心无暂灰。
劒棱丛石险，箭激乱流回。
莫说雁不到，长江鱼尽来。','',''),('quantangshi-27472','题上饶亭','張祜','quantangshi','','卷28','溪亭拂一琴，促轸坐披衿。
夜月水南寺，秋风城外砧。
早霜红叶静，新雨碧潭深。
唯是壶中物，忧来且自斟。','',''),('quantangshi-27473','题僧壁','張祜','quantangshi','','卷28','出门无一事，忽忽到天涯。
客地多逢酒，僧房却厌花。
棊因王粲覆，鼓是禰衡挝。
自喜疎成品，生前不怨嗟。','',''),('quantangshi-27474','寄卢载','張祜','quantangshi','','卷28','故人卢氏子，十载旷佳期。
少见双鱼信，多闻八米诗。
侏儒他甚饱，欵段尔应羸。
忽谓今刘二，相逢不熟槌。','',''),('quantangshi-27475','送杨秀才游蜀','張祜','quantangshi','','卷28','鄂渚逢游客，瞿塘上去船。
峡深明月夜，江静碧云天。
旧俗巴渝舞，新声蜀国弦。
不堪挥惨恨，一涕自潸然。','',''),('quantangshi-27476','送杨秀才往夔州','張祜','quantangshi','','卷28','鄂渚逢游客，瞿塘上去船。
江连万里海，峡入一条天。
鸟影沉沙日，猨声隔树烟。
新诗逢北使，为草几巴牋。','',''),('quantangshi-27477','途中逢李道实游蔡州','張祜','quantangshi','','卷28','征马汉江头，逢君上蔡游。
野桥经亥市，山路过申州。
僻地人行涩，荒林虎迹稠。
殷勤话新守，生物赖诸侯。','',''),('quantangshi-27478','富阳道中送王正夫','張祜','quantangshi','','卷28','㭊㭊上荒原，霜林赤叶翻。
孤帆天外出，远戍日中昏。
摘橘防深刺，攀萝畏断根。
何堪衰草色，一酌送王孙。','',''),('quantangshi-27479','送韦正字㭊贯赴制举','張祜','quantangshi','','卷28','可爱汉文年，鸿恩荡海壖。
木鸡方备德，金马正求贤。
大战希游刃，长途在着鞭。
竚看晁董策，便向史中传。','',''),('quantangshi-27480','赠贞固上人','張祜','quantangshi','','卷28','南国披僧籍，高标一道林。
律仪精氎布，真行正吞针。
掇火身潜起，焚香口旋吟。
非论坐中社，余亦旧知音。','',''),('quantangshi-27481','题赠志凝上人','張祜','quantangshi','','卷28','悟色身无染，观空事不生。
道心长日笑，觉路几年行。
片月山林静，孤云海棹轻。
愿为尘外契，一就智珠明。','',''),('quantangshi-27482','送琼贞发述怀','張祜','quantangshi','','卷28','送出南溪日，离情不忍看。
渐遥犹顾首，帆去意难判。
最恨临行夜，相期几百般。
但能存岁节，终久得同欢。','',''),('quantangshi-27483','寄灵澈上人','張祜','quantangshi','','卷28','老僧何处寺，秋梦绕江滨。
独树月中鹤，孤舟云外人。
荣华长指幻，衰病久观身。
应笑无成者，沧洲垂一轮。','',''),('quantangshi-27484','溪行寄京师故人道侣','張祜','quantangshi','','卷28','白日长多事，清溪偶独寻。
云归秋水阔，月出夜山深。
坐想天涯去，行悲泽畔吟。
东郊故人在，应笑未抽簪。','',''),('quantangshi-27485','赠僧云栖','張祜','quantangshi','','卷28','麈尾与筇枝，几年离石坛。
梵余林雪厚，棊罢岳钟残。
开卷喜先悟，漱瓶知早寒。
衡阳寺前雁，今日到长安。','',''),('quantangshi-27486','送魏尚书赴镇州行营','張祜','quantangshi','','卷28','河塞日骎骎，恩讐报尽深。
伍员忠是节，陆绩孝为心。
坐激书生愤，行歌壮士吟。
慙非燕地客，不得受黄金。','',''),('quantangshi-27487','寄迁客','張祜','quantangshi','','卷28','万里南迁客，辛勤岭路遥。
溪行防水弩，野店避山魈。
瘴海须求药，贪泉莫举瓢。
但能坚志义，白日甚昭昭。','',''),('quantangshi-27488','题苏小小墓','張祜','quantangshi','','卷28','漠漠穷尘地，萧萧古树林。
脸浓花自发，眉恨柳长深。
夜月人何待，春风鸟为吟。
不知谁共穴，徒愿结同心。','',''),('quantangshi-27489','江南作','張祜','quantangshi','','卷28','楚塞南行久，秦城北望遥。
少年花已过，衰病柳先凋。
客泪收回日，乡心寄落潮。','',''),('quantangshi-27490','题王右丞山水障二首 一','張祜','quantangshi','','卷28','精华在笔端，咫尺匠心难。
日月中堂见，江湖满座看。
夜凝岚气湿，秋浸壁光寒。
料得昔人意，平生诗思残。','',''),('quantangshi-27491','题王右丞山水障二首 二','張祜','quantangshi','','卷28','右丞今已殁，遗画世间稀。
咫尺江湖尽，寻常鸥鸟飞。
山光全在掌，云气欲生衣。
以此常为玩，平生沧海机。','',''),('quantangshi-27492','将之衡阳道中作','張祜','quantangshi','','卷28','万里南方去，扁舟泛自身。
长年无爱物，深话少情人。
醉卧襟长散，闲书字不真。
衡阳路犹远，独与雁为宾。','',''),('quantangshi-27493','读狄梁公传','張祜','quantangshi','','卷28','失运庐陵厄，乘时武后尊。
五丁扶造化，一柱正干坤。
上保储皇位，深然国老勋。
圣朝虽百代，长合问王孙。','',''),('quantangshi-27494','题真娘墓','張祜','quantangshi','','卷28','佛地葬罗衣，孤魂此是归。
舞为蝴蝶梦，歌谢伯劳飞。
翠发朝云在，青蛾夜月微。
伤心一花落，无复怨春辉。','',''),('quantangshi-27495','洞庭南馆','張祜','quantangshi','','卷28','一迳逗霜林，朱栏遶碧岑。
地盘云梦角，山镇洞庭心。
树白看烟起，沙红见日沉。
还因此悲屈，惆怅又行吟。','',''),('quantangshi-27496','题赠仲仪上人院','張祜','quantangshi','','卷28','星霜几朝寺，香火静居人。
黄叶不经意，青山无事身。
抛生台上日，结座履中尘。
自说一时课，别来诗更新。','',''),('quantangshi-27497','题圣女庙','張祜','quantangshi','','卷28','古庙无人入，苍皮涩老桐。
蚁行蝉壳上，蛇窜雀巢中。
浅水孤舟泊，轻尘一座蒙。
晚来云雨去，荒草是残风。','',''),('quantangshi-27498','题山水障子','張祜','quantangshi','','卷28','一见秋山色，方怜画手稀。
波涛连壁动，云物下檐飞。
岭树冬犹发，江帆暮不归。
端然是渔叟，相向日依依。','',''),('quantangshi-27499','咏风','張祜','quantangshi','','卷28','摇摇歌扇举，悄悄舞衣轻。
引笛秋临塞，吹沙夜遶城。
向峰回雁影，出峡送猨声。
何似琴中奏，依依别带情。','',''),('quantangshi-27500','奉和令狐相公送陈肱侍御','張祜','quantangshi','','卷28','高馆动离瑟，亲宾聊叹稀。
笑歌情不尽，欢待礼无违。
清露府莲结，碧云臯鹤飞。
还家与□惠，雨露岂殊归。','',''),('quantangshi-27501','陪范宣城北楼夜宴','張祜','quantangshi','','卷28','华轩敞碧流，官妓拥诸侯。
粉项高丛鬓，檀妆慢裹头。
亚身摧蜡烛，斜眼送香球。
何处偏堪恨，千回下客筹。','',''),('quantangshi-27502','宪宗皇帝挽歌词','張祜','quantangshi','','卷28','呜咽上攀龙，升平不易逢。
武皇虚好道，文帝未登封。
寿域无千载，泉门是九重。
桥山非远地，云去莫疑峰。','',''),('quantangshi-27503','发蜀客','張祜','quantangshi','','卷28','风吹鲁国人，飘荡蜀江滨。
湿地饶蛙黾，衰年足鬼神。
时清归去路，日复病来身。
千万长堤柳，从他烂熳春。','',''),('quantangshi-27504','江城晚眺','張祜','quantangshi','','卷28','重槛构云端，江城四郁盘。
河流出郭静，山色对楼寒。
浪草侵天白，霜林映日丹。
悠然此江思，树杪几樯竿。','',''),('quantangshi-27505','题樟亭','張祜','quantangshi','','卷28','晓霁凭虚槛，云山四望通。
地盘江岸绝，天映海门空。
树色连秋霭，潮声入夜风。
年年此光景，催尽白头翁。','',''),('quantangshi-27506','乐静','張祜','quantangshi','','卷28','引手强篸巾，徐徐起病身。
远心羣野鹤，闲话对村人。
发匣琴徽静，开瓶酒味真。
纵闻兵赋急，原宪本家贫。','',''),('quantangshi-27507','登广武原','張祜','quantangshi','','卷28','广武原西北，华夷此浩然。
地盘山入海，河遶国连天。
远树千门邑，高樯万里船。
乡心日云暮，犹在楚城边。','',''),('quantangshi-27508','观宋州田大夫打球','張祜','quantangshi','','卷28','白马顿红缨，梢球紫袖轻。
晓冰蹄下裂，寒瓦杖头鸣。
叉手胶黏去，分鬃线道絣。
自言无战伐，髀肉已曾生。','',''),('quantangshi-27509','题丹阳永泰寺练湖亭','張祜','quantangshi','','卷28','小槛俯澄鲜，龙宫浸浩然。
孤光悬夜月，一片割秋天。
浅派胤沙草，余波漂岸船。
聊当因畎浍，披拂坐潺湲。','',''),('quantangshi-27510','题程氏书斋','張祜','quantangshi','','卷28','僻巷难通马，深园不藉篱。
青萝缠栢叶，红粉坠莲枝。
雨燕衔泥近，风鱼咂网迟。
缘君寻小阮，好是更题诗。','',''),('quantangshi-27511','毁浮图年逢东林寺旧','張祜','quantangshi','','卷28','可惜东林寺，空门失所依。
翻经谢灵运，画壁陆探微。
隙地泉声在，荒途马迹稀。
殷勤话僧辈，未敢保儒衣。','',''),('quantangshi-27512','贵池道中作','張祜','quantangshi','','卷28','羸骖驱野岸，山远路盘盘。
清露月华晓，碧江星影寒。
离羣徒长泣，去国自加餐。
霄汉宁无旧，相哀自语端。','',''),('quantangshi-27513','喜王子载话旧','張祜','quantangshi','','卷28','相逢青眼日，相叹白头时。
累话三朝事，重看一局棊。
欢娱非老大，成长是婴儿。
且尽尊中物，无烦更后期。','',''),('quantangshi-27514','秋日病中','張祜','quantangshi','','卷28','析析檐前竹，秋声拂簟凉。
病加阴已久，愁觉夜初长。
坐拾车前子，行看肘后方。
无端忧食忌，开镜倍萎黄。','',''),('quantangshi-27515','访许用晦','張祜','quantangshi','','卷28','远郭日曛曛，停桡一访君。
小桥通野水，高树入江云。
酒兴曾无敌，诗情旧逸羣。
怪来音信少，五十我无闻。','',''),('quantangshi-27516','题海盐南馆','張祜','quantangshi','','卷28','故人营此地，台馆尚依依。
黑夜山魈语，黄昏海燕归。
旧阴杨叶在，残雨槿花稀。
无复南亭赏，高檐红烛辉。','',''),('quantangshi-27517','晚秋江上作','張祜','quantangshi','','卷28','万里穷秋客，萧条对落晖。
烟霞山鸟散，风雨庙神归。
地远蛩声切，天长雁影稀。
那堪正砧杵，幽思想寒衣。','',''),('quantangshi-27518','吴宫曲','張祜','quantangshi','','卷28','日下苑西宫，花飘香径红。
玉钗斜白燕，罗带弄青虫。
皓齿初含雪，柔枝欲断风。
可怜倾国艳，谁信女为戎。','',''),('quantangshi-27519','赋昭君冢','張祜','quantangshi','','卷28','万里关山冢，明妃旧死心。
恨为秋色晚，愁结暮云阴。
夜切胡风起，天高汉月临。
已知无玉貌，何事送黄金。','',''),('quantangshi-27520','哭汴州陆大夫','張祜','quantangshi','','卷28','利劒太坚操，何妨拔一毛。
冤深陆机雾，愤积伍员涛。
直道非无验，明时不录劳。
谁当青史上，卒为显词褒。','',''),('quantangshi-27521','晚夏归别业','張祜','quantangshi','','卷28','古岸扁舟晚，荒园一径微。
鸟啼新果熟，花落故人稀。
宿润侵苔甃，斜阳照竹扉。
相逢尽乡老，无复话时机。','',''),('quantangshi-27522','公子行','張祜','quantangshi','','卷28','春色满城池，杯盘着处移。
镫金斜雁子，鞍帕嫩鹅儿。
买笑歌桃李，寻歌折柳枝。
可怜明月夜，长是管弦随。','',''),('quantangshi-27523','题曾氏园林','張祜','quantangshi','','卷28','十亩长堤宅，萧疎半老槐。
醉眠风卷簟，棋罢月移堦。
斫树遗桑斧，浇花湿笋鞋。
还将齐物论，终岁自安排。','',''),('quantangshi-27524','读始兴公传','張祜','quantangshi','','卷28','殁世议方存，升平道几论。
诗情光日月，笔力动干坤。
乱首光雄筭，朝纲在典坟。
明时封禅绩，山下见丘门。','',''),('quantangshi-27525','中秋月','張祜','quantangshi','','卷28','碧落桂含姿，清秋是素期。
一年逢好夜，万里见明时。
绝域行应久，高城下更迟。','',''),('quantangshi-27526','江西道中作三首 一','張祜','quantangshi','','卷28','日落江村远，烟霞度几重。
问人孤驿路，驱马乱山峰。
夜入霜林火，寒生水寺钟。
凄凉哭途意，行处又饥凶。','',''),('quantangshi-27527','江西道中作三首 二','張祜','quantangshi','','卷28','西江江上月，远远照征衣。
夜色草中网，秋声林外机。
渚田牛路熟，石岸客船稀。
无复是乡井，鹧鸪聊自飞。','',''),('quantangshi-27528','江西道中作三首 三','張祜','quantangshi','','卷28','秋滩一望平，远远见山城。
落日啼乌桕，空林露寄生。
烧畲残火色，荡桨夜溪声。
况是曾游处，桑田小变更。','',''),('quantangshi-27529','题常州水西馆','張祜','quantangshi','','卷28','隟地丛筠植，修廊列堵环。
楼台疎占水，冈岸远成山。
尽日草深映，无风舟自闲。
聊当俟芳夕，一泛芰荷间。','',''),('quantangshi-27530','题李渎山居玉潭','張祜','quantangshi','','卷28','古树千年色，苍崖百尺阴。
发寒泉气静，神骇玉光沉。
上穴青冥小，中连碧海深。
何当烟月下，一听夜龙吟。','',''),('quantangshi-27531','题陆墉金沙洞居','張祜','quantangshi','','卷28','东溪泉一眼，归卧惬高疎。
决水金沙静，梯云石壁虚。
细吟搔短发，深话笑长裾。
莫道遗名品，尝闻入洛初。','',''),('quantangshi-27532','题陆敦礼山居伏牛潭','張祜','quantangshi','','卷28','伏牛真怪事，余胜几人谙。
日彩沉青壁，烟容静碧潭。
泛心何虑冷，漱齿讵忘甘。
幸挈壶中物，期君正兴酣。','',''),('quantangshi-27533','旅次石头岸','張祜','quantangshi','','卷28','行行石头岸，身事两相违。
旧国日边远，故人江上稀。
水声寒不尽，山色暮相依。
惆怅未成语，数行鵶又飞。','',''),('quantangshi-27534','观宋州于使君家乐琵琶','張祜','quantangshi','','卷28','历历四弦分，重来上界闻。
玉盘飞夜雹，金磬入秋云。
陇雾笳凝水，砂风雁咽羣。
不堪天塞恨，青冢是昭君。','',''),('quantangshi-27535','筝','張祜','quantangshi','','卷28','绰绰下云烟，微收皓腕鲜。
夜风生碧柱，春水咽红弦。
翠佩轻犹触，莺枝涩未迁。
芳音何更妙，清月共婵娟。','',''),('quantangshi-27536','歌','張祜','quantangshi','','卷28','一夜列三清，闻歌曲阜城。
雪飞红烬影，珠贯碧云声。
皓齿娇微发，青蛾怨自生。
不知新弟子，谁解啭喉轻。','',''),('quantangshi-27537','笙','張祜','quantangshi','','卷28','董双成一妙，历历韵风篁。
清露鹤声远，碧云仙吹长。
气侵银项湿，膏胤漆瓢香。
曲罢不知处，巫山空夕阳。','',''),('quantangshi-27538','五弦','張祜','quantangshi','','卷28','小小月轮中，斜抽半袖红。
玉瓶秋滴水，珠箔夜悬风。
征调侵弦乙，商声过指拢。
只愁才曲罢，云雨去巴东。','',''),('quantangshi-27539','𥷑篥','張祜','quantangshi','','卷28','一管妙清商，纤红玉指长。
雪藤新换束，霞锦旋抽囊。
并揭声犹远，深含曲未央。
坐中知密顾，微笑是周郎。','',''),('quantangshi-27540','笛','張祜','quantangshi','','卷28','紫清人一管，吹在月堂中。
雁起雪云夕，龙吟烟水空。
虏尘深汉地，羌思切边风。
试弄阳春曲，西园桃已红。','',''),('quantangshi-27541','舞','張祜','quantangshi','','卷28','荆台呈妙舞，云雨半罗衣。
褭褭腰疑折，褰褰袖欲飞。
雾轻红踯躅，风艳紫蔷薇。
强许传新态，人间弟子稀。','',''),('quantangshi-27542','箜篌','張祜','quantangshi','','卷28','星汉夜牢牢，深帘调更高。
乱流公莫度，沉骨妪空嘷。
向月轻轮甲，迎风重纫绦。
不堪闻别引，沧海恨波涛。','',''),('quantangshi-27543','箫','張祜','quantangshi','','卷28','清籁远愔愔，秦楼夜思深。
碧空人已去，沧海凤难寻。
杳妙和云绝，依微向水沉。
还将九成意，高阁竚芳音。','',''),('quantangshi-27544','夕次桐庐','張祜','quantangshi','','卷28','百里清溪口，扁舟此去过。
晚潮风势急，寒叶雨声多。
戍出山头鼓，樵通竹里歌。
不堪无酒夜，廻首梦烟波。','',''),('quantangshi-27545','入潼关','張祜','quantangshi','','卷28','都城三百里，雄险此廻环。
地势遥尊岳，河流侧让关。
秦皇曾虎视，汉祖昔龙颜。
何处枭凶辈，干戈自不闲。','',''),('quantangshi-27546','南宫叹亦述玄宗追恨太真妃事','張祜','quantangshi','','卷28','北陆冰初结，南宫漏更长。
何劳却睡草，不验返魂香。
月隐仙娥艳，风残梦蝶扬。
徒悲旧行迹，一夜玉堦霜。','',''),('quantangshi-27547','题平望驿','張祜','quantangshi','','卷28','一派吴兴水，西来此驿分。
路遥经几日，身去是孤云。
雨气朝忙蚁，雷声夜聚蚊。
何堪秋草色，到处重离羣。','',''),('quantangshi-27548','隋宫怀古','張祜','quantangshi','','卷28','废宫深苑路，炀帝此东行。
往事余山色，流年是水声。
古墙丹雘尽，深栋黑煤生。
惆怅从今客，经过未了情。','',''),('quantangshi-27549','偶苏求至话别','張祜','quantangshi','','卷28','几年沧海别，万里白头吟。
夜月江流阔，春云岭路深。
珠繁杨氏果，翠耀孔家禽。
无复天南梦，相思空树林。','',''),('quantangshi-27550','秋霁','張祜','quantangshi','','卷28','垂老归休意，栖栖陋巷中。
暗灯棋子落，残语酒瓶空。
滴羃侵檐露，虚疎入槛风。
何妨一蝉嘒，自抱木兰丛。','',''),('quantangshi-27551','咏史二首 一','張祜','quantangshi','','卷28','汉代非良计，西戎世世尘。
无何求善马，不筭苦生民。
外国讐虚结，中华愤莫伸。
却教为后耻，昭帝远和亲。','',''),('quantangshi-27552','咏史二首 二','張祜','quantangshi','','卷28','留名鲁连去，于世绝遗音。
尽爱聊城下，宁知沧海深。
偶然飞一箭，无事在千金。
回望凌烟阁，何人是此心。','',''),('quantangshi-27553','洞房燕','張祜','quantangshi','','卷28','清晓洞房开，佳人喜燕来。
乍疑钗上动，轻似掌中回。
暗语临窗户，深窥傍镜台。
新妆正含思，莫拂画梁埃。','',''),('quantangshi-27554','答僧赠柱杖','張祜','quantangshi','','卷28','千回掌上横，珍重远方情。
客问何人与，闽僧寄一茎。
画空疑未决，卓地计初成。
幸以文堪采，扶持力不轻。','',''),('quantangshi-27555','鹭鸶','張祜','quantangshi','','卷28','深窥思不穷，揭趾浅沙中。
一点山光净，孤飞潭影空。
暗栖松叶露，双下蓼花风。
好是沧波侣，垂丝趣亦同。','',''),('quantangshi-27556','塞下','張祜','quantangshi','','卷28','万里配长征，连年惯野营。
入羣来拣马，抛伴去擒生。
箭插雕翎阔，弓盘鹊角轻。
问看行近远，西去受降城。','',''),('quantangshi-27557','忆云阳宅','張祜','quantangshi','','卷28','一别云阳宅，深愁度岁华。
翠浓春槛柳，红满夜庭花。
鸟影垂纤竹，鱼行践浅沙。
聊当因寤寐，归思浩无涯。','',''),('quantangshi-27558','题造微禅师院','張祜','quantangshi','','卷28','夜香闻偈后，岑寂掩双扉。
照竹灯和雪，穿云月到衣。
草堂疎磬断，江寺故人稀。
唯忆江南雨，春风独鸟归。','',''),('quantangshi-27559','酬武藴之乙丑之岁始见华发余自悲遂成继和','張祜','quantangshi','','卷28','贾生年尚少，华发近相侵。
不是流光促，因缘别恨深。
怜君成苦调，感我独长吟。
岂料清秋日，星星共映簪。','',''),('quantangshi-27560','题万道人禅房','張祜','quantangshi','','卷28','何处凿禅壁，西南江上峰。
残阳过远水，落叶满疎钟。
世事静中去，道心尘外逢。
欲知情不动，牀下虎留踪。','',''),('quantangshi-27561','病后访山客','張祜','quantangshi','','卷28','久病倦衾枕，独行来访君。
因逢归马客，共对出溪云。
新月坐中见，暮蝉愁处闻。
相欢贵无事，莫想路歧分。','',''),('quantangshi-27562','题松汀驿','張祜','quantangshi','','卷28','山色远含空，苍茫泽国东。
海明先见日，江白逈闻风。
鸟道高原去，人烟小径通。
那知旧遗逸，不在五湖中。','',''),('quantangshi-27563','处士隐居','張祜','quantangshi','','卷28','斜日半飞合，高帘轻翳空。
清香芙蓉水，碧冷琅玕风。
绝岸派沿洑，修廊趾崇隆。
唯当饵仙术，坐作朱颜翁。','',''),('quantangshi-27564','早春钱塘湖晚眺','張祜','quantangshi','','卷28','落日下林坂，抚襟睇前踪。
轻澌流回浦，残雪明高峰。
仰视天宇旷，俯登云树重。
聊当问真界，昨夜西峦钟。','',''),('quantangshi-27565','濠州水馆','張祜','quantangshi','','卷28','高阁去烦燠，客心遂安舒。
清流中浴鸟，白石下游鱼。
秋树色凋翠，夜桥声褭虚。
南轩更何待，坐见玉蟾蜍。','',''),('quantangshi-27566','石头城寺','張祜','quantangshi','','卷28','山势抱烟光，重门突兀傍。
连檐金像阁，半壁石龛廊。
碧树藂高顶，清池占下方。
徒悲宦游意，尽日老僧房。','',''),('quantangshi-27567','伤迁客殁南中','張祜','quantangshi','','卷28','故人何处殁，谪宦极南天。
远地身狼狈，穷途事果然。
白须才过海，丹旐却归船。
肠断相逢路，新来客又迁。','',''),('quantangshi-27568','乌夜啼','張祜','quantangshi','','卷28','忽忽南飞返，危丝共怨凄。
暗霜移树宿，残夜遶枝啼。
咽绝声重叙，愔淫思乍迷。
不妨还报喜，悞使玉颜低。','',''),('quantangshi-27569','题润州金山寺','張祜','quantangshi','','卷28','一宿金山寺，超然离世羣。
僧归夜船月，龙出晓堂云。
树色中流见，钟声两岸闻。
翻思在朝市，终日醉醺醺。','',''),('quantangshi-27570','题润州甘露寺','張祜','quantangshi','','卷28','千重构横险，高步出尘埃。
日月光先见，江山势尽来。
冷云归水石，清露滴楼台。
况是东溟上，平生意一开。','',''),('quantangshi-27571','题杭州孤山寺','張祜','quantangshi','','卷28','楼台耸碧岑，一径入湖心。
不雨山长润，无云水自阴。
断桥荒藓涩，空院落花深。
犹忆西窗月，钟声在北林。','',''),('quantangshi-27572','题余杭县龙泉观','張祜','quantangshi','','卷28','四回山一面，台殿已嵯峨。
中路见山远，上方行石多。
天晴花气漫，地暖鸟音和。
徒漱葛仙井，此生其奈何。','',''),('quantangshi-27573','题径山大觉禅师影堂','張祜','quantangshi','','卷28','超然彼岸人，一径谢微尘。
见相即非相，观身岂是身。
空门性未灭，旧里化犹新。
谩指堂中影，谁言影似真。','',''),('quantangshi-27574','题濠州钟离寺','張祜','quantangshi','','卷28','遥遥东郭寺，数里占原田。
远岫碧光合，长淮清派连。
院藏归鸟树，钟到落帆船。
唯羡空门叟，栖心尽百年。','',''),('quantangshi-27575','秋夜宿灵隐寺师上人','張祜','quantangshi','','卷28','月色荒城外，江声野寺中。
贫知交道薄，老信释门空。
露叶凋堦藓，风枝戞井桐。
不妨无酒夜，闲话值生公。','',''),('quantangshi-27576','题苏州灵岩寺','張祜','quantangshi','','卷28','碧海西陵岸，吴王此盛时。
山行今佛寺，水见旧宫池。
亡国人遗恨，空门事少悲。
聊当值僧语，尽日把松枝。','',''),('quantangshi-27577','题苏州楞伽寺','張祜','quantangshi','','卷28','楼台山半腹，又此一经行。
树隔夫差苑，溪连句践城。
上坡松径涩，深坐石池清。
况是西峰顶，凄凉故国情。','',''),('quantangshi-27578','题苏州思益寺','張祜','quantangshi','','卷28','四面山形断，楼台此逈临。
两峰高崪屼，一水下淫渗。
凿石西龛小，穿松北坞深。
会当来结社，长日为僧吟。','',''),('quantangshi-27579','题重居寺','張祜','quantangshi','','卷28','浮图经近郭，长日羡僧闲。
竹径深开院，松门远对山。
重廊标板榜，高殿锁金环。
更问寻雷室，西行咫尺间。','',''),('quantangshi-27580','题善权寺','張祜','quantangshi','','卷28','碧峰南一寺，最胜是仙源。
峻坂依岩壁，清泉泄洞门。
金函崇宝藏，玉树閟灵根。
寄谢香花叟，高踪不可援。','',''),('quantangshi-27581','题南陵隐静寺','張祜','quantangshi','','卷28','松迳上登攀，深行烟霭间。
合流厨下水，对耸殿前山。
润壁鸟音逈，泉源僧步闲。
更怜飞一锡，天外与云还。','',''),('quantangshi-27582','题丘山寺','張祜','quantangshi','','卷28','几代儒家业，何年佛寺碑。
地平边海处，江出上山时。
故国人长往，空门事可知。
凄凉问禅客，身外即无为。','',''),('quantangshi-27583','题道光上人山院','張祜','quantangshi','','卷28','真僧上方界，山路正岩岩。
地僻泉长冷，亭香草不凡。
火田生白菌，烟岫老青杉。
尽日唯山水，当知律行严。','',''),('quantangshi-27584','赠庐山僧','張祜','quantangshi','','卷28','一室炉峰下，荒榛手自开。
粉牌新薤叶，竹援小葱台。
树黑云归去，山明日上来。
便知心是佛，坚坐对寒灰。','',''),('quantangshi-27585','题惠山寺','張祜','quantangshi','','卷28','旧宅人何在，空门客自过。
泉声到池尽，山色上楼多。
小洞生斜竹，重堦夹细莎。
殷勤望城市，云水暮钟和。','',''),('quantangshi-27586','题虎丘寺','張祜','quantangshi','','卷28','轻棹驻廻流，门登西虎丘。
雾青山月晓，云白海天秋。
倚殿松株涩，欹庭石片幽。
青蛾几时墓，空色尚悠悠。','',''),('quantangshi-27587','题普贤寺','張祜','quantangshi','','卷28','何人知寺路，松竹暗春山。
潭黑龙应在，巢空鹤未还。
经年来客倦，半日与僧闲。
更共尝新茗，闻钟笑语间。','',''),('quantangshi-27588','题虎丘东寺','張祜','quantangshi','','卷28','云树拥崔嵬，深行异俗埃。
寺门山外入，石壁地中开。
仰砌池光动，登楼海气来。
伤心万古意，金玉葬寒灰。','',''),('quantangshi-27589','题虎丘西寺','張祜','quantangshi','','卷28','嚣尘楚城外，一寺枕通波。
松色入门远，冈形连院多。
花时长到处，别路半经过。
惆怅旧禅客，空房深薜萝。','',''),('quantangshi-27590','题招隐寺','張祜','quantangshi','','卷28','千年戴颙宅，佛庙此崇修。
古井人名在，清泉鹿迹幽。
竹光寒闭院，山影夜藏楼。
未得高僧旨，烟霞空暂游。','',''),('quantangshi-27591','塞下曲','張祜','quantangshi','','卷28','二十逐嫖姚，分兵远戍辽。
雪迷经塞夜，冰壮渡河朝。
促放雕难下，生骑马未调。
小儒何足问，看取劒横腰。','',''),('quantangshi-27592','宿淮阴水馆','張祜','quantangshi','','卷28','积水自成阴，昏昏月映林。
五更离浦棹，一夜隔淮砧。
漂母乡非远，王孙道岂沉。
不当无健妪，谁肯效前心。','',''),('quantangshi-27593','题小松','張祜','quantangshi','','卷28','何处斸云烟，新移此馆前。
碧姿尘不染，清影露长鲜。
耸地心才直，凌云操未全。
可悲人自老，何日是千年。','',''),('quantangshi-27594','夏日梅溪馆寄庞舍人','張祜','quantangshi','','卷28','东阳宾礼重，高馆望行期。
埽簟因松叶，篸瓜使竹枝。
卷帘闻鸟近，翻枕梦人迟。
坐听津桥说，今营太守碑。','',''),('quantangshi-27595','感河上兵','張祜','quantangshi','','卷28','一闻河塞上，非是欲权兵。
首尾诚须畏，膏肓慎勿轻。
多门徒可入，尽室且思行。
莫为无媒者，沧浪不濯缨。','',''),('quantangshi-27596','赠淮南将','張祜','quantangshi','','卷28','年少好风情，垂鞭眦睚行。
带金狮子小，裘锦麒麟狞。
拣匠装银镫，堆钱买钿筝。
李陵虽效死，时论亦轻生。','',''),('quantangshi-27597','题惠昌上人','張祜','quantangshi','','卷28','半岩开一室，香穟细氛氲。
石上漱秋水，月中行夏云。
律持僧讲疏，经诵梵书文。
好是风廊下，遥遥挂褐裙。','',''),('quantangshi-27598','塞上曲','張祜','quantangshi','','卷28','边风卷地时，日暮帐初移。
碛逈三通角，山寒一点旗。
连收榻索马，引满射雕儿。
莫道功勋细，将军昔戍师。','',''),('quantangshi-27599','折杨柳','張祜','quantangshi','','卷28','红粉青楼曙，垂杨仲月春。
怀君重攀折，非妾妬腰身。
舞带萦丝断，娇娥向叶嚬。
横吹凡几曲，独自最愁人。','',''),('quantangshi-27600','采桑','張祜','quantangshi','','卷28','自古多征战，由来尚甲兵。
长驱千里去，一举两番平。
按劒从沙漠，歌谣满帝京。
寄言天下将，须立武功名。','',''),('quantangshi-27601','禅智寺','張祜','quantangshi','','卷28','宝殿依山嶮，临虚势若吞。
画檐齐木末，香砌压云根。
远景窗中岫，孤烟竹里村。
凭高聊一望，乡思隔吴门。','',''),('quantangshi-27602','寄题商洛王隐居','張祜','quantangshi','','卷28','近逢商洛口，知尔坐南塘。
草阁平春水，柴门掩夕阳。
随蜂收野蜜，寻麝采生香。
更忆前年醉，松花满石牀。','',''),('quantangshi-27603','送客归湘楚','張祜','quantangshi','','卷28','无辞一杯酒，昔日与君深。
秋色换归鬓，曙光生别心。
桂花山庙冷，枫树水楼阴。
此路千余里，应劳楚客吟。','',''),('quantangshi-27604','登金山寺','張祜','quantangshi','','卷28','古今斯岛绝，南北大江分。
水阔吞沧海，亭高宿断云。
返潮千涧落，啼鸟半空闻。
皆是登临处，归航酒半醺。','',''),('quantangshi-27605','洛阳感寓','張祜','quantangshi','','卷28','扰扰都城晓四开，不关名利也尘埃。
千门甲第身遥入，万里铭旌死后来。
洛水暮烟横莽苍，邙山秋日露崔嵬。
须知此事堪为镜，莫遣黄金漫作堆。','',''),('quantangshi-27606','从军行','張祜','quantangshi','','卷28','少年金紫就光辉，直指边城虎翼飞。
一卷旌收千骑虏，万全身出百重围。
黄云断塞寻鹰去，白草连天射雁归。
白首汉廷刀笔吏，丈夫功业本相依。','',''),('quantangshi-27607','爱妾换马 一','張祜','quantangshi','','卷28','一面妖桃千里蹄，娇姿骏骨价应齐。
乍牵玉勒辞金栈，催整花钿出绣闺。
去日岂无沾袂泣，归时还有顿衔嘶。
婵娟躞蹀春风里，挥手摇鞭杨柳堤。','',''),('quantangshi-27608','爱妾换马 二','張祜','quantangshi','','卷28','绮阁香销华廐空，忍将行雨换追风。
休怜柳叶双眉翠，却爱桃花两耳红。
侍宴永辞春色里，趁朝休立漏声中。
恩劳未尽情先尽，暗泣嘶风两意同。','',''),('quantangshi-27609','病宫人','張祜','quantangshi','','卷28','佳人卧病动经秋，帘幕繿縿不挂钩。
四体强扶藤夹膝，双鬟慵插玉搔头。
花颜有幸君王问，药饵无征待诏愁。
惆怅近来消瘦尽，泪珠时傍枕函流。','',''),('quantangshi-27610','观杭州柘枝','張祜','quantangshi','','卷28','舞停歌罢鼓连摧，软骨仙蛾暂起来。
红罨画衫缠腕出，碧排方胯背腰来。
旁收拍拍金铃摆，却踏声声锦袎摧。
看着遍头香袖褶，粉屏香帕又重隈。','',''),('quantangshi-27611','周员外席上观柘枝','張祜','quantangshi','','卷28','画鼓拖环锦臂攘，小娥双换舞衣裳。
金丝蹙雾红衫薄，银蔓垂花紫带长。
鸾影乍回头并举，凤声初歇翅齐张。
一时欻腕招残拍，斜敛轻身拜玉郎。','',''),('quantangshi-27612','观杨瑗柘枝','張祜','quantangshi','','卷28','促叠蛮鼍引柘枝，卷檐虚帽带交垂。
紫罗衫宛蹲身处，红锦靴柔踏节时。
微动翠蛾抛旧态，缓遮檀口唱新词。
看看舞罢轻云起，却赴襄王梦里期。','',''),('quantangshi-27613','感王将军柘枝妓殁','張祜','quantangshi','','卷28','寂寞春风旧柘枝，舞人休唱曲休吹。
鸳鸯钿带抛何处，孔雀罗衫付阿谁。
画鼓不闻招节拍，锦靴空想挫腰肢。
今来座上偏惆怅，曾是堂前教彻时。','',''),('quantangshi-27614','扬州法云寺双桧','張祜','quantangshi','','卷28','谢家双植本图荣，树老人因地变更。
朱顶鹤知深盖偃，白眉僧见小枝生。
高临月殿秋云影，静入风檐夜雨声。
纵使百年为上寿，绿阴终借暂时行。','',''),('quantangshi-27615','忆游天台寄道流','張祜','quantangshi','','卷28','忆昨天台到赤城，几朝仙籁耳中生。
云龙出水风声过，海鹤鸣臯日色清。
石笋半山移步险，桂花当洞拂衣轻。','',''),('quantangshi-27616','寄王尊师','張祜','quantangshi','','卷28','天台南洞一灵仙，骨耸冰棱貌莹然。
曾对浦云长昧齿，重来华表不知年。
溪桥晚下玄龟出，草露朝行白鹿眠。
犹忆夜深华盖上，更无人处话丹田。','',''),('quantangshi-27617','公子行','張祜','quantangshi','','卷28','锦堂昼永绣帘垂，立却花骢待出时。
红粉美人擎酒劝，青衣年少臂鹰随。
轻将玉杖敲花片，旋把金鞭约柳枝。
近地独游三五骑，等闲行傍曲江池。','',''),('quantangshi-27618','寓怀寄苏州刘郎中','張祜','quantangshi','','卷28','一闻周召佐明时，西望都门强策羸。
天子好文才自薄，诸侯力荐命犹奇。
贺知章口徒劳说，孟浩然身更不疑。
唯是胜游行未遍，欲离京国尚迟迟。','',''),('quantangshi-27619','和杜牧之齐山登高','張祜','quantangshi','','卷28','秋溪南岸菊霏霏，急管烦弦对落晖。
红叶树深山径断，碧云江静浦帆稀。
不堪孙盛嘲时笑，愿送王弘醉夜归。
流落正怜芳意在，砧声徒促授寒衣。','',''),('quantangshi-27620','题于越亭','張祜','quantangshi','','卷28','扁舟亭下驻烟波，十五年游重此过。
洲觜露沙人渡浅，树稍藏竹鸟啼多。
山衔落照欹红盖，水蹙斜文卷绿罗。
肠断中秋正圆月，夜来谁唱异乡歌。','',''),('quantangshi-27621','秋夜登润州慈和寺上方','張祜','quantangshi','','卷28','清夜浮埃暂歇鄽，塔轮金照露华鲜。
人行中路月生海，鹤语上方星满天。
楼影半连深岸水，钟声寒彻远林烟。
僧房闭尽下楼去，一半梦魂离世缘。','',''),('quantangshi-27622','寄献萧相公','張祜','quantangshi','','卷28','东去江干是胜游，鼎湖兴望不堪愁。
谢安近日违朝旨，傅说当时允帝求。
暂向聊城飞一箭，长为沧海系扁舟。
分明此事无人见，白首相看未肯休。','',''),('quantangshi-27623','哭京兆庞尹','張祜','quantangshi','','卷28','杨子江头昔共迷，一为京兆隔云泥。
故人昨日同时吊，旧马今朝别处嘶。
向壁愁眉无复画，扶牀稚齿已能啼。
也知世路名堪贵，谁信庄周论物齐。','',''),('quantangshi-27624','送周尚书赴滑台','張祜','quantangshi','','卷28','楚谣襦袴整三年，喉舌新恩下九天。
鼓角雄都分节钺，蛇龙旧国罢楼船。
昆河已在兵钤内，堂柳空留鹤岭前。
多病无由酬一顾，鄢陵千骑去翩翩。','',''),('quantangshi-27625','和杜使君九华楼见寄','張祜','quantangshi','','卷28','孤城高柳晓鸣鸦，风帘半钩清露华。
九峰聚翠宿危槛，一夜孤光悬冷沙。
出岸远晖帆欲落，入溪寒影雁差斜。
杜陵归去春应早，莫厌青山谢朓家。','',''),('quantangshi-27626','送人归蜀','張祜','quantangshi','','卷28','锦城春色溯江源，三峡经过几夜猨。
红树两厓开霁色，碧岩千仞涨波痕。
萧萧暮雨荆王梦，漠漠春烟蜀帝魂。
长怨相如留滞处，富家还忆卓王孙。','',''),('quantangshi-27627','酬答柳宗言秀才见赠','張祜','quantangshi','','卷28','南下天台厌绝冥，五湖波上泛如萍。
江鸥自戏为踪迹，野鹿闲惊是性灵。
任子偶垂沧海钓，戴逵虚认少微星。
金门后俊徒相唁，且为人间寄茯苓。','',''),('quantangshi-27628','题杭州天竺寺','張祜','quantangshi','','卷28','西南山最胜，一界是诸天。
上路穿岩竹，分流入寺泉。
蹑云丹井畔，望月石桥边。
洞壑江声远，楼台海气连。
塔明春岭雪，钟散暮松烟。
何处去犹恨，更看峰顶莲。','',''),('quantangshi-27629','题杭州灵隐寺','張祜','quantangshi','','卷28','峰峦开一掌，朱槛几环延。
佛地花分界，僧房竹引泉。
五更楼下月，十里郭中烟。
后塔耸亭后，前山横阁前。
溪沙涵水静，涧石点苔鲜。
好是呼猨久，西岩深响连。','',''),('quantangshi-27630','中秋夜杭州翫月','張祜','quantangshi','','卷28','万古太阴精，中秋海上生。
鬼愁缘辟照，人爱为高明。
历历华星远，霏霏薄晕萦。
影流江不尽，轮曳谷无声。
似镜当楼晓，如珠出浦盈。
岸沙全借白，山木半含清。
小槛循环看，长堤蹋阵行。
殷勤未归客，烟水夜来情。','',''),('quantangshi-27631','高闲上人','張祜','quantangshi','','卷28','座上辞安国，禅房恋沃州。
道心黄叶老，诗思碧云秋。
卷轴朝廷饯，书函内库收。
陶欣入社叟，生怯论经俦。
日色屏初揭，风声笔未休。
长波溢海岸，大点出嵩丘。
不绝羲之法，难穷智永流。
殷勤一牋在，留着看银钩。','',''),('quantangshi-27632','题灵隐寺师一上人十韵','張祜','quantangshi','','卷28','八十空门子，深山土木骸。
片衣闲自衲，单食老长斋。
道性终能遣，人情少不乖。
樔枸居上院，薜荔俯层阶。
洗钵前临水，窥门外有柴。
朗吟挥竹拂，高楫曳芒鞋。
迸笋斜穿坞，飞泉下喷崖。
种花忻土润，拨石虑沙埋。
旧往师招隐，初临我咏怀。
何当缘兴翫，更为表新牌。','',''),('quantangshi-27633','投常州从兄中丞','張祜','quantangshi','','卷28','扁舟何所往，言入善人邦。
旧爱鹏抟海，今闻虎渡江。
士因为政乐，儒为说诗降。
素履冰容静，新词玉润枞。
金鱼聊解带，画鷁稍移桩。
邀妓思逃席，留宾命倒缸。
史材谁是伍，经术世无双。
广厦当宏构，洪钟并待撞。
成龙须讲邴，展骥莫先庞。
应念宗中末，秋萤照一牕。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-27634','送王昌涉侍御','張祜','quantangshi','','卷28','十里指东平，军前首出征。
诸侯青服旧，御史紫衣荣。
入陈枭心死，分围虎力生。
画时安楚塞，刻日下齐城。
号令朝移幕，偷踪夜斫营。
云梯曾险上，地道惯深行。
举斾招降将，投戈趁败兵。
自慙居虏者，当此立功名。','',''),('quantangshi-27635','少年乐','張祜','quantangshi','','卷28','二十便封侯，名居第一流。
绿鬟深小院，清管下高楼。
醉把金船掷，闲敲玉镫游。
带盘红鼹鼠，袍砑紫犀牛。
锦袋归调箭，罗鞋起拨球。
眼前长贵盛，那信世间愁。','',''),('quantangshi-27636','华清宫和杜舍人','張祜','quantangshi','','卷28','五十年天子，离宫旧粉墙。
登封时正泰，御宇日初长。
上位先名实，中兴事宪章。
举戎轻甲胄，余地取河湟。
道帝玄元祖，儒封孔子王。
因缘百司署，藂会一人汤。
渭水波摇绿，秦山草半黄。
马头开夜照，鹰眼利星芒。
下箭朱弓满，鸣鞭皓腕攘。
畋思获吕望，谏只避周昌。
兔迹贪前逐，枭心不早防。
几添鹦鹉劝，频赐荔支尝。
月锁千门静，天高一笛凉。
细音摇翠佩，轻步宛霓裳。
祸乱根潜结，升平意遽忘。
衣冠逃犬虏，鼙鼓动渔阳。
外戚心殊迫，中途事可量。
雪埋妃子貌，刃断禄儿肠。
近侍烟尘隔，前踪辇路荒。
益知迷宠佞，惟恨丧忠良。
北阙尊明主，南宫逊上皇。
禁清余凤吹，池冷映龙光。
祝寿山犹在，流年水共伤。
杜鹃魂厌蜀，蝴蝶梦悲庄。
雀卵遗雕栱，虫丝罥画梁。
紫苔侵壁润，红树闭门芳。
守吏齐鸳瓦，耕民得翠璫。
欢康昔时乐，讲武旧兵场。
莫草深岩霭，幽花坠径香。
不堪垂白叟，行折御沟杨。','',''),('quantangshi-27637','穆护砂','張祜','quantangshi','','卷28','玉管朝朝弄，清歌日日新。
折花当驿路，寄与陇头人。','',''),('quantangshi-27638','思归乐二首 一','張祜','quantangshi','','卷28','晚日催弦管，春风入绮罗。
杏花如有意，偏落舞衫多。','',''),('quantangshi-27639','思归乐二首 二','張祜','quantangshi','','卷28','万里春应尽，三江雁亦稀。
连天汉水广，孤客未言归。','',''),('quantangshi-27640','金殿乐','張祜','quantangshi','','卷28','入夜秋砧动，千声起四邻。
不缘楼上月，应为陇头人。','',''),('quantangshi-27641','墙头花二首 一','張祜','quantangshi','','卷28','蟋蟋鸣洞房，梧桐落金井。
为君裁舞衣，天寒剪刀冷。','',''),('quantangshi-27642','墙头花二首 二','張祜','quantangshi','','卷28','妾有罗衣裳，秦王在时作。
为舞春风多，秋来不堪着。','',''),('quantangshi-27643','胡渭州','張祜','quantangshi','','卷28','杨柳千寻色，桃花一苑芳。
风吹入帘里，唯有惹衣香。','',''),('quantangshi-27644','白鼻騧','張祜','quantangshi','','卷28','为底胡姬酒，长来白鼻騧。
摘莲抛水上，郎意在浮花。','',''),('quantangshi-27645','戎浑','張祜','quantangshi','','卷28','风劲角弓鸣，将军猎渭城。
草枯鹰眼疾，雪尽马蹄轻。','',''),('quantangshi-27646','杨下采桑','張祜','quantangshi','','卷28','飞丝惹绿尘，软叶对孤轮。
今朝入园去，物色强着人。','',''),('quantangshi-27647','宫词二首 一','張祜','quantangshi','','卷28','故国三千里，深宫二十年。
一声河满子，双泪落君前。','',''),('quantangshi-27648','宫词二首 二','張祜','quantangshi','','卷28','自倚能歌日，先皇掌上怜。
新声何处唱，肠断李延年。','',''),('quantangshi-27649','昭君怨二首 一','張祜','quantangshi','','卷28','万里边城远，千山行路难。
举头唯见日，何处是长安。','',''),('quantangshi-27650','昭君怨二首 二','張祜','quantangshi','','卷28','汉庭无大议，戎虏几先和。
莫羡倾城色，昭君恨最多。','',''),('quantangshi-27651','夕次竟陵','張祜','quantangshi','','卷28','南风吹五两，日暮竟陵城。
肠断巴江月，夜蝉何处声。','',''),('quantangshi-27652','信州水亭','張祜','quantangshi','','卷28','南檐架短廊，沙路白茫茫。
尽日不归处，一庭栀子香。','',''),('quantangshi-27653','苏小小歌三首 一','張祜','quantangshi','','卷28','车轮不可遮，马足不可绊。
长怨十字街，使郎心四散。','',''),('quantangshi-27654','苏小小歌三首 二','張祜','quantangshi','','卷28','新人千里去，故人千里来。
剪刀横眼底，方觉泪难裁。','',''),('quantangshi-27655','苏小小歌三首 三','張祜','quantangshi','','卷28','登山不愁峻，涉海不愁深。
中擘庭前枣，教郎见赤心。','',''),('quantangshi-27656','树中草','張祜','quantangshi','','卷28','青青树中草，托根非不危。
草生树却死，荣枯君可知。','',''),('quantangshi-27657','七里濑渔家','張祜','quantangshi','','卷28','七里垂钓叟，还傍钓台居。
莫恨无姓名，严陵不卖鱼。','',''),('quantangshi-27658','读曲歌五首 一','張祜','quantangshi','','卷28','窗中独自起，帘外独自行。
愁见蜘蛛织，寻思直到明。','',''),('quantangshi-27659','读曲歌五首 二','張祜','quantangshi','','卷28','碓上米不舂，窗中丝罢络。
看渠驾去车，定是无四角。','',''),('quantangshi-27660','读曲歌五首 三','張祜','quantangshi','','卷28','不见心相许，徒云脚漫勤。
摘荷空摘叶，是底采莲人。','',''),('quantangshi-27661','读曲歌五首 四','張祜','quantangshi','','卷28','窗外山魈立，知渠脚不多。
三更机底下，摸着是谁梭。','',''),('quantangshi-27662','读曲歌五首 五','張祜','quantangshi','','卷28','郎去摘黄瓜，郎来收赤枣。
郎耕种麻地，今作西舍道。','',''),('quantangshi-27663','玉树后庭花','張祜','quantangshi','','卷28','轻车何草草，独唱后庭花。
玉座谁为主，徒悲张丽华。','',''),('quantangshi-27664','莫愁乐','張祜','quantangshi','','卷28','侬居石城下，郎到石城游。
自郎石城出，长在石城头。','',''),('quantangshi-27665','襄阳乐','張祜','quantangshi','','卷28','大堤花月夜，长江春水流。
东风正上信，春夜特来游。','',''),('quantangshi-27666','自君之出矣','張祜','quantangshi','','卷28','自君之出矣，万物看成古。
千寻葶苈枝，争奈长长苦。','',''),('quantangshi-27667','梦江南','張祜','quantangshi','','卷28','行吟洞庭句，不见洞庭人。
尽日碧江梦，江南红树春。','',''),('quantangshi-27668','将离岳州留献徐员外','張祜','quantangshi','','卷28','高斋长对酒，下客亦霑鱼。
不为江南去，还来郡北居。','',''),('quantangshi-27669','题彭泽卢明府新楼','張祜','quantangshi','','卷28','碧落新楼迥，清池古树闲。
先贤尽为宰，空看县南山。','',''),('quantangshi-27670','赠禅师','張祜','quantangshi','','卷28','坐见三生事，宗传一衲来。
已知无法说，心向定中灰。','',''),('quantangshi-27671','江南逢故人','張祜','quantangshi','','卷28','河洛多尘事，江山半旧游。
春风故人夜，又醉白苹洲。','',''),('quantangshi-27672','松江怀古','張祜','quantangshi','','卷28','碧树吴洲远，青山震泽深。
无人踪范蠡，烟水暮沈沈。','',''),('quantangshi-27673','书愤','張祜','quantangshi','','卷28','三十未封侯，颠狂遍九州。
平生镆鎁剑，不报小人雠。','',''),('quantangshi-27674','题孟处士宅','張祜','quantangshi','','卷28','高才何必贵，下位不妨贤。
孟简虽持节，襄阳属浩然。','',''),('quantangshi-27675','首阳行','張祜','quantangshi','','卷28','首阳山下路，孤竹节长存。
为问无心草，如何庇本根。','',''),('quantangshi-27676','题僧影堂','張祜','quantangshi','','卷28','寒叶坠清霜，空帘着烬香。
生前既无事，何事更悲伤。','',''),('quantangshi-27677','边思','張祜','quantangshi','','卷28','苏武节旌尽，李陵音信稀。
花当陇上发，人向陇头归。','',''),('quantangshi-27678','题弋阳馆','張祜','quantangshi','','卷28','一叶飘然下弋阳，残霞昏日树苍苍。
吴溪漫淬干将剑，却是猨声断客肠。','',''),('quantangshi-27679','题秀师影堂','張祜','quantangshi','','卷28','阴阴古寺杉松下，记得长明一焰灯。
尽日看山人不会，影堂中是别来僧。','',''),('quantangshi-27680','赠李修源','張祜','quantangshi','','卷28','岳阳新尉晓衙参，却是傍人意未甘。
昨夜与君思贾谊，长沙犹在洞庭南。','',''),('quantangshi-27681','瓜洲闻晓角','張祜','quantangshi','','卷28','寒耿稀星照碧霄，月楼吹角夜江遥。
五更人起烟霜静，一曲残声遍落潮。','',''),('quantangshi-27682','元日仗','張祜','quantangshi','','卷28','文武千官岁仗兵，万方同轨奏升平。
上皇一御含元殿，丹凤门开白日明。','',''),('quantangshi-27683','连昌宫','張祜','quantangshi','','卷28','龙虎旌旗雨露飘，玉楼歌断碧山遥。
玄宗上马太真去，红树满园香自销。','',''),('quantangshi-27684','正月十五夜灯','張祜','quantangshi','','卷28','千门开锁万灯名，正月中旬动帝京。
三百内人连袖舞，一时天上着词声。','',''),('quantangshi-27685','上巳乐','張祜','quantangshi','','卷28','猩猩血彩系头标，天上齐声举画桡。
却是内人争意切，六宫红袖一时招。','',''),('quantangshi-27686','千秋乐','張祜','quantangshi','','卷28','八月平时花蕚楼，万方同乐奏千秋。
倾城人看长竿出，一伎初成赵解愁。','',''),('quantangshi-27687','春莺啭','張祜','quantangshi','','卷28','兴庆池南柳未开，太真先把一枝梅。
内人已唱春莺啭，花下傞傞软舞来。','',''),('quantangshi-27688','大酺乐二首 一','張祜','quantangshi','','卷28','车架东来值太平，大酺三日洛阳城。
小儿一伎竿头绝，天下传呼万岁声。','',''),('quantangshi-27689','大酺乐二首 二','張祜','quantangshi','','卷28','紫陌酺归日欲斜，红尘开路薛王家。
双鬟笑说楼前鼓，两仗争轮好落花。','',''),('quantangshi-27690','邠王小管','張祜','quantangshi','','卷28','虢国潜行韩国随，宜春深院映花枝。
金舆远幸无人见，偷把邠王小管吹。','',''),('quantangshi-27691','李谟笛','張祜','quantangshi','','卷28','平时东幸洛阳城，天乐宫中夜彻明。
无奈李谟偷曲谱，酒楼吹笛是新声。','',''),('quantangshi-27692','宁哥来','張祜','quantangshi','','卷28','日映宫城雾半开，太真帘下畏人猜。
黄翻绰指向西树，不信宁哥回马来。','',''),('quantangshi-27693','丁巳年仲冬月江上作','張祜','quantangshi','','卷28','南来驱马渡江濆，消息前年此月闻。
唯是贾先生恸哭，不堪天意重阴云。','',''),('quantangshi-27694','邺中怀古','張祜','quantangshi','','卷28','邺中城下漳河水，日夜东流莫记春。
肠断宫中望陵处，不堪台上也无人。','',''),('quantangshi-27695','读池州杜员外杜秋娘诗','張祜','quantangshi','','卷28','年少多情杜牧之，风流仍作杜秋诗。
可知不是长门闭，也得相如第一词。','',''),('quantangshi-27696','杭州开元寺牡丹','張祜','quantangshi','','卷28','浓艳初开小药栏，人人惆怅出长安。
