分明西国人来说，赤佛堂西是汉家。','',''),('quantangshi-27783','听岳州徐员外弹琴','張祜','quantangshi','','卷28','玉律潜符一古琴，哲人心见圣人心。
尽日南风似遗意，九疑猨鸟满山吟。','',''),('quantangshi-27784','钩弋夫人词','張祜','quantangshi','','卷28','惆怅云陵事不回，万金重更筑仙台。
莫言天上无消息，犹是夫人作鸟来。','',''),('quantangshi-27785','鸿沟','張祜','quantangshi','','卷28','龙蛇百战争天下，各制雄心指此沟。
宁似九州分国土，地图初割海中流。','',''),('quantangshi-27786','悲纳铁','張祜','quantangshi','','卷28','长闻为政古诸侯，使佩刀人尽佩牛。
谁谓今来正耕垦，却销农器作戈矛。','',''),('quantangshi-27787','胡渭州','張祜','quantangshi','','卷28','亭亭孤月照行舟，寂寂长江万里流。
乡国不知何处是，云山漫漫使人愁。','',''),('quantangshi-27788','破阵乐','張祜','quantangshi','','卷28','秋风四面足风沙，塞外征人暂别家。
千里不辞行路远，时光早晚到天涯。','',''),('quantangshi-27789','枫桥','張祜','quantangshi','','卷28','长洲苑外草萧萧，却算游城岁月遥。
唯有别时今不忘，暮烟疎雨过枫桥。','',''),('quantangshi-27790','句','張祜','quantangshi','','卷28','万国见清道，一身成白头。
此地荣辱盛，岂宜山中人。
椿儿遶树春园里，桂子寻花夜月中。
一身扶杖二儿随。
夏雨莲苞破，秋风桂子雕。
杜鹃花发杜鹃叫，乌臼花生乌臼啼。
茶风无奈笔，酒秃不胜簪。','',''),('quantangshi-27791','答李昌期','楊洵美','quantangshi','','卷28','三山载羣仙，峨峨咸浪中。
云衣剪不得，此路安可从。
我生亦何事，出门如飞蓬。
白日又黄昏，所悲瑶草空。
虫声故乡梦，枕上禾黍风。','',''),('quantangshi-27792','宫词','長孫翱','quantangshi','','卷28','一道甘泉接御沟，上皇行处不曾秋。
谁言水是无情物，也到宫前咽不流。','',''),('quantangshi-27793','和于中丞登越王楼见寄','盧求','quantangshi','','卷28','高情推谢守，善政属绵州。
未落紫泥诏，闲登白雪楼。
晴江如送日，寒岭镇迎秋。
满壁朝天士，唯予不系舟。','',''),('quantangshi-27794','雨','歐陽衮','quantangshi','','卷28','细雨弄春阴，余寒入昼深。
山姿轻薄雾，烟色澹幽林。
鹿践莓苔滑，鱼牵水荇沈。
怀情方未已，清酒漫须斟。','',''),('quantangshi-27795','田家','歐陽衮','quantangshi','','卷28','黯黯日将夕，牛羊村外来。
岩阿青气发，篱落杏花开。
草木应初感，鸧鹒亦已催。
晚间春作好，行乐不须猜。','',''),('quantangshi-27796','神光寺','歐陽衮','quantangshi','','卷28','香刹悬青磴，飞楼界碧空。
石门栖怖鸽，慈塔绕归鸿。
有法将心镜，无名属性通。
从来乐幽寂，寻觅未能穷。','',''),('quantangshi-27797','和项斯游头陀寺上方','歐陽衮','quantangshi','','卷28','步入桃源里，晴花更满枝。
峰回山意旷，林杳竹光迟。
远寺寻龙藏，名香发雁池。
间能将远语，况及上阳时。','',''),('quantangshi-27798','秦原道中','歐陽衮','quantangshi','','卷28','分险架长澜，斜梁控夕峦。
宿云依岭断，初月入江寒。
缁化秦裘敝，尘惊汉策残。
无言倦行旅，遥路属时难。','',''),('quantangshi-27799','月峰寺忆理公','歐陽衮','quantangshi','','卷28','共来江海上，清论一宵同。
禅榻浑依旧，心期浩已空。
惊春花落树，闻梵涧摇风。
二谛欣咨启，还应梦寐通。','',''),('quantangshi-27800','寄陈去疾进士','歐陽衮','quantangshi','','卷28','放迹疑辞垢，栖心亦道门。
玄言萝幌馥，诗思竹炉温。
解带摇花落，弹琴散鸟喧。
江山兹夕意，唯有素交存。','',''),('quantangshi-27801','听郢客歌阳春白雪','歐陽衮','quantangshi','','卷28','寂听郢中人，高歌已绝伦。
临风飘白雪，向日奏阳春。
调雅偏盈耳，声长杳入神。
连连贯珠并，袅袅遏云频。
度曲知难和，凝情想任真。
周郎如赏羡，莫使滞芳晨。','',''),('quantangshi-27802','南涧寺','歐陽衮','quantangshi','','卷28','春寺无人乱鸟啼，藤萝阴磴野僧迷。
云藏古壁遗龙象，草没香台抱鹿麛。
松籁泠泠疑梵呗，柳烟历历见招提。
为耽寂乐亲禅侣，莫怪闲行费马蹄。','',''),('quantangshi-27803','献岁书情','裴夷直','quantangshi','','卷28','白发添双鬓，空宫又一年。
音书鸿不到，梦寐兔空悬。
地远星辰侧，天高雨露偏。
圣期知有感，云海漫相连。','',''),('quantangshi-27804','奉和大梁相公重九日军中宴会之什','裴夷直','quantangshi','','卷28','今古同嘉节，欢娱但异名。
陶公缘绿醑，谢傅为苍生。
酒泛金英丽，诗通玉律清。
何言辞物累，方系万人情。','',''),('quantangshi-27805','奉和大梁相公同张员外重九日宴集','裴夷直','quantangshi','','卷28','重九思嘉节，追欢从谢公。
酒清欺玉露，菊盛愧金风。
不待秋蟾白，须沈落照红。
更将门下客，酬和管弦中。','',''),('quantangshi-27806','同乐天中秋夜洛河翫月二首 一','裴夷直','quantangshi','','卷28','清洛半秋悬璧月，彩船当夕泛银河。
苍龙颔底珠皆没，白帝心边镜乍磨。
海上几时霜雪积，人间此夜管弦多。
须知天地为炉意，尽取黄金铸作波。','',''),('quantangshi-27807','同乐天中秋夜洛河翫月二首 二','裴夷直','quantangshi','','卷28','不热不寒三五夕，晴川明月正相临。
千珠竞没苍龙颔，一镜高悬白帝心。
几处凄凉缘地远，有时惆怅值云阴。
如何清洛如清昼，共见初升又见沈。','',''),('quantangshi-27808','和邢郎中病中重阳强游乐游原','裴夷直','quantangshi','','卷28','嘉晨令节共陶陶，风景牵情并不劳。
晓日整冠兰室静，秋原骑马菊花高。
晴光一一呈金刹，诗思浸浸逼水曹。
何必销忧凭外物，祗将清韵敌春醪。','',''),('quantangshi-27809','观淬龙泉劒','裴夷直','quantangshi','','卷28','欧冶将成器，风胡幸见逢。
发硎思剸玉，投水化为龙。
讵肯藏深匣，终朝用刜钟。
莲花生宝锷，秋日励霜锋。
炼质才三尺，吹毛过百重。
击磨如不倦，提握愿长从。','',''),('quantangshi-27810','春色满皇州','裴夷直','quantangshi','','卷28','寒销山水地，春遍帝王州。
北阙晴光动，南山喜气浮。
夭红妆暖树，急绿走阴沟。
思妇开香阁，王孙上玉楼。
氛氲直城北，骀荡曲江头。
今日灵台下，翻然却是愁。','',''),('quantangshi-27811','亚夫碎玉斗','裴夷直','quantangshi','','卷28','雄谋竟不决，宝玉终不爱。
倏尔霜刃挥，飒然春冰碎。
飞光动旗帜，散响惊环佩。
霜洒绣障前，星流锦筵内。
图王业已失，为虏言空悔。
独有青史中，英风观千载。','',''),('quantangshi-27812','水亭','裴夷直','quantangshi','','卷28','岁律行将变，君恩竟未回。
门前即潮水，朝去暮常来。','',''),('quantangshi-27813','扬州寄诸子','裴夷直','quantangshi','','卷28','千里隔烟波，孤舟宿何处？遥思耿不眠，淮南夜风雨。','',''),('quantangshi-27814','酬卢郎中游寺见招不遇','裴夷直','quantangshi','','卷28','偶出送山客，不知游梵宫。
秋光古松下，谁伴一仙翁。','',''),('quantangshi-27815','寓言','裴夷直','quantangshi','','卷28','秋树却逢暖，未凋能几时。
何须尚松桂，摇动暂青枝。','',''),('quantangshi-27816','唁人丧侍儿','裴夷直','quantangshi','','卷28','夜情河耿耿，春恨草绵绵。
唯有嫦娥月，从今照墓田。','',''),('quantangshi-27817','席上夜别张主簿','裴夷直','quantangshi','','卷28','红烛剪还明，绿尊添又满。
不愁前路长，只畏今宵短。','',''),('quantangshi-27818','方丈泉','裴夷直','quantangshi','','卷28','循涯不知浅，见底似非深。
永日无波浪，澄澄照我心。','',''),('quantangshi-27819','晚望','裴夷直','quantangshi','','卷28','日下夕阴长，前山凝积翠。
白鸟一行飞，联联粉书字。','',''),('quantangshi-27820','前山','裴夷直','quantangshi','','卷28','只谓一苍翠，不知犹数重。
晚来云映处，更见两三峰。','',''),('quantangshi-27821','发交州日留题解炼师房','裴夷直','quantangshi','','卷28','久喜房廊接，今成道路赊。
明朝回首处，此地是天涯。','',''),('quantangshi-27822','令和州买松','裴夷直','quantangshi','','卷28','好觅凌霜质，仍须带雨栽。
须知剖竹日，便是看松来。','',''),('quantangshi-27823','题断金集后','裴夷直','quantangshi','','卷28','一览断金集，再悲埋玉人。
牙弦千古绝，珠泪万行新。','',''),('quantangshi-27824','晚凉','裴夷直','quantangshi','','卷28','檐前蔽日多高树，竹下添池有小渠。
山客野僧归去后，晚凉移案独临书。','',''),('quantangshi-27825','和周侍御洛城雪','裴夷直','quantangshi','','卷28','天街飞辔踏琼英，四顾全疑在玉京。
一种相如抽祕思，兔园那比凤凰城。','',''),('quantangshi-27826','奉和大梁相公送人二首 一','裴夷直','quantangshi','','卷28','谢公日日伤离别，又向西堂送阿连。
想到越中秋已尽，镜河应羡月团圆。','',''),('quantangshi-27827','奉和大梁相公送人二首 二','裴夷直','quantangshi','','卷28','北津杨柳迎烟绿，南岸阑干映水红。
君到襄阳渡江处，始应回首忆羊公。','',''),('quantangshi-27828','酬唐仁烈相别后喜阻风未发见寄','裴夷直','quantangshi','','卷28','离心一起泪双流，春浪无情也白头。
风若有知须放去，莫教重别又重愁。','',''),('quantangshi-27829','秦中卧病思归','裴夷直','quantangshi','','卷28','索索凉风满树头，破窗残月五更秋。
病身归处吴江上，一寸心中万里愁。','',''),('quantangshi-27830','送王缋','裴夷直','quantangshi','','卷28','翠羽长将玉树期，偶然飞下肯多时。
翩翩一路岚阴晚，却入青葱宿旧枝。','',''),('quantangshi-27831','赠美人琴弦','裴夷直','quantangshi','','卷28','应从玉指到金徽，万态千情料可知。
今夜灯前湘水怨，殷勤封在七条丝。','',''),('quantangshi-27832','病中知皇子陂荷花盛发寄王缋','裴夷直','quantangshi','','卷28','十里莲塘路不赊，病来帘外是天涯。
烦君四句遥相寄，应得诗中便看花。','',''),('quantangshi-27833','戏唐仁烈','裴夷直','quantangshi','','卷28','自知年几偏应少，先把屠苏不让春。
傥更数年逢此日，还应惆怅羡他人。','',''),('quantangshi-27834','上下七盘二首 一','裴夷直','quantangshi','','卷28','斗回山路掩皇州，二载欢娱一望休。
从此万重青嶂合，无因更得重回头。','',''),('quantangshi-27835','上下七盘二首 二','裴夷直','quantangshi','','卷28','商山半月雨漫漫，偶值新晴下七盘。
山似换来天似洗，可怜风日到长安。','',''),('quantangshi-27836','八月十五日夜','裴夷直','quantangshi','','卷28','去年今夜在商州，还为清光上驿楼。
宛是依依旧颜色，自怜人换几般愁。','',''),('quantangshi-27837','南诏朱藤杖','裴夷直','quantangshi','','卷28','六节南藤色似朱，拄行阶砌胜人扶。
会须将入深山去，倚看云泉作老夫。','',''),('quantangshi-27838','夜意','裴夷直','quantangshi','','卷28','萧疎尽地林无影，浩荡连天月有波。
独立空亭人睡后，洛桥风便水声多。','',''),('quantangshi-27839','漫作','裴夷直','quantangshi','','卷28','月色莫来孤寝处，春风又向别人家。
梁园桃李虽无数，断定今年不看花。','',''),('quantangshi-27840','访刘君','裴夷直','quantangshi','','卷28','扰扰驰蹄又走轮，五更飞尽九衢尘。
灵芝破观深松院，还有斋时未起人。','',''),('quantangshi-27841','杨柳枝词','裴夷直','quantangshi','','卷28','已作绿丝笼晓日，又成飞絮扑晴波。
隋家不合栽杨柳，长遣行人春恨多。','',''),('quantangshi-27842','寄杭州崔使君','裴夷直','quantangshi','','卷28','朝下归来只闭关，羡君高步出人寰。
三年不见尘中事，满眼江涛送雪山。','',''),('quantangshi-27843','穷冬曲江闲步','裴夷直','quantangshi','','卷28','雪尽南坡雁北飞，草根春意胜春晖。
曲江永日无人到，独遶寒池又独归。','',''),('quantangshi-27844','省中题新植双松','裴夷直','quantangshi','','卷28','端坐高宫起远心，云高水阔共幽沈。
更堂寓直将谁语，自种双松伴夜吟。','',''),('quantangshi-27845','崇山郡','裴夷直','quantangshi','','卷28','地尽炎荒瘴海头，圣朝今又放驩兜。
交州已在南天外，更过交州四五州。','',''),('quantangshi-27846','临水','裴夷直','quantangshi','','卷28','一见心原断百忧，益知身世两悠悠。
江亭独倚阑干处，人亦无言水自流。','',''),('quantangshi-27847','题江上柳寄李使君','裴夷直','quantangshi','','卷28','桂江南渡无杨柳，见此令人眼暂明。
应学郡中贤太守，依依相向许多情。','',''),('quantangshi-27848','江上见月怀古','裴夷直','quantangshi','','卷28','月上江平夜不风，伏波遗迹半成空。
今宵倍欲悲陵谷，铜柱分明在水中。','',''),('quantangshi-27849','鹦鹉','裴夷直','quantangshi','','卷28','劝尔莫移禽鸟性，翠毛红觜任天真。
如今漫学人言巧，解语终须累尔身。','',''),('quantangshi-27850','寄婺州李给事二首 一','裴夷直','quantangshi','','卷28','心尽玉皇恩已远，迹留江郡宦应孤。
不知壮气今何似，犹得凌云贯日无。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-27851','寄婺州李给事二首 二','裴夷直','quantangshi','','卷28','瘴鬼翻能念直心，五年相遇不相侵。
目前唯有思君病，无底沧溟未是深。','',''),('quantangshi-27852','秋日','裴夷直','quantangshi','','卷28','六眸龟北凉应早，三足乌南日正长。
常记京关怨摇落，如今目断满林霜。','',''),('quantangshi-27853','遣意','裴夷直','quantangshi','','卷28','梧桐坠露悲先朽，松桂凌霜倚后枯。
不是世间长在物，蹔分贞脆竟何殊。','',''),('quantangshi-27854','戏酬惟赏上人','裴夷直','quantangshi','','卷28','师是浮云无着身，我居尘网敢相亲。
应从海上秋风便，偶自飞来不为人。','',''),('quantangshi-27855','寓言','裴夷直','quantangshi','','卷28','流水颓阳不暂停，东流西落两无情。
不是世间人自老，古来华发此中生。','',''),('quantangshi-27856','忆家','裴夷直','quantangshi','','卷28','天海相连无尽处，梦魂来往尚应难。
谁言南海无霜雪，试向愁人两鬓看。','',''),('quantangshi-27857','留客','裴夷直','quantangshi','','卷28','青梅欲熟笋初长，嫩绿新阴遶砌凉。
湖馆翛然无俗客，白衣居士且匡牀。','',''),('quantangshi-27858','别蕲春王判官','裴夷直','quantangshi','','卷28','四十年来[真]久故，三千里外暂相逢。
今日一杯成远别，烟波眇眇恨重重。','',''),('quantangshi-27859','将发循州社日于所居馆宴送','裴夷直','quantangshi','','卷28','浪花如雪叠江风，社过高秋万恨中。
明日便随江燕去，依依俱是故巢空。','',''),('quantangshi-27860','泛溪','朱慶餘','quantangshi','','卷28','曲渚回花舫，生衣卧向风。
鸟飞溪色里，人语棹声中。
余卉才分影，新蒲自作丛。
前湾更幽绝，虽浅去犹通。','',''),('quantangshi-27861','宿陈处士书斋','朱慶餘','quantangshi','','卷28','结茅当此地，下马见高情。
菰叶寒塘晚，杉阴白石明。
向炉新茗色，隔雪远钟声。
闲得相逢少，吟多寐不成。','',''),('quantangshi-27862','上宣州沈大夫','朱慶餘','quantangshi','','卷28','科名继世古来稀，高步何年下紫微。
帝命几曾移重镇，时清犹望领春闱。
登朝旧友常思见，开幕贤人并望归。
今日得游风化地，却回沧海有光辉。','',''),('quantangshi-27863','杭州送萧宝校书','朱慶餘','quantangshi','','卷28','马识青山路，人随白浪船。
别君犹有泪，学道谩经年。','',''),('quantangshi-27864','送盛长史','朱慶餘','quantangshi','','卷28','莫辞东路远，此别岂闲行。
职处中军要，官兼上佐荣。
野亭枫叶暗，秋水藕花明。
拜省期将近，孤舟促去程。','',''),('quantangshi-27865','宿道士观','朱慶餘','quantangshi','','卷28','堂闭仙人影，空坛月露初。
闲听道家子，盥漱读灵书。','',''),('quantangshi-27866','湖州韩使君置宴','朱慶餘','quantangshi','','卷28','老大成名仍足病，纵听丝竹也无欢。
高情太守容闲坐，借与青山尽日看。','',''),('quantangshi-27867','题仙游寺','朱慶餘','quantangshi','','卷28','石抱龙堂藓石干，山遮白日寺门寒。
长松瀑布饶奇状，曾有仙人驻鹤看。','',''),('quantangshi-27868','宫词','朱慶餘','quantangshi','','卷28','寂寂花时闭院门，美人相并立琼轩。
含情欲说宫中事，鹦鹉前头不敢言。','',''),('quantangshi-27869','公子行','朱慶餘','quantangshi','','卷28','闲从结客冶游时，忘却红楼薄暮期。
醉上黄金堤上去，马鞭捎断绿杨丝。','',''),('quantangshi-27870','送陈摽','朱慶餘','quantangshi','','卷28','满酌劝童仆，好随郎马蹄。
春风慎行李，莫上白铜鞮。','',''),('quantangshi-27871','寻古观','朱慶餘','quantangshi','','卷28','仙观曾过知不远，花藏石室杳难寻。
泉边白鹿闻人语，看过天坛渐入深。','',''),('quantangshi-27872','南岭路','朱慶餘','quantangshi','','卷28','越岭向南风景异，人人传说到京城。
经冬来往不踏雪，尽在刺桐花下行。','',''),('quantangshi-27873','陪江州李使君重阳宴百花亭','朱慶餘','quantangshi','','卷28','闲携九日酒，共到百花亭。
醉里求诗境，回看岛屿青。','',''),('quantangshi-27874','上张水部','朱慶餘','quantangshi','','卷28','出入门阑久，儿童亦有情。
不忘将姓字，常说向公卿。
每许连牀坐，仍容并马行。
恩深转无语，怀抱甚分明。','',''),('quantangshi-27875','凤翔西池与贾岛纳凉','朱慶餘','quantangshi','','卷28','四面无炎气，清池阔复深。
蝶飞逢草住，鱼戏见人沉。
拂石安茶器，移牀选树阴。
几回同到此，尽日得闲吟。','',''),('quantangshi-27876','上汴州令狐相公','朱慶餘','quantangshi','','卷28','罢相恩犹在，那容处静司。
政严初领节，名重更因诗。
公事巡营外，戎装拜勅时。
恭闻长与善，应念出身迟。','',''),('quantangshi-27877','送于中丞入蕃册立','朱慶餘','quantangshi','','卷28','上马生边思，戎装别众僚。
双旌衔命重，空碛去程遥。
迥没沙中树，孤飞雪外雕。
蕃庭过册礼，几日却回朝。','',''),('quantangshi-27878','送淮阴丁明府','朱慶餘','quantangshi','','卷28','之官未入境，已有爱人心。
遣吏回中路，停舟对远林。
岛声淮浪静，雨色稻苗深。
暇日公门掩，唯应伴客吟。','',''),('quantangshi-27879','送韦校书佐灵州幕','朱慶餘','quantangshi','','卷28','共知行处乐，犹惜此时分。
职已为书记，官曾校典坟。
寒城初落叶，高戍远生云。
边事何须问，深谋祗在君。','',''),('quantangshi-27880','上江州李史君','朱慶餘','quantangshi','','卷28','起家声望重，自古更谁过。
得在朝廷少，还因谏诤多。
经年愁瘴疠，几处遇恩波。
入境无余事，唯闻父老歌。','',''),('quantangshi-27881','发凤翔后涂中怀田少府','朱慶餘','quantangshi','','卷28','识君春未半，意欲住经秋。
见酒连诗句，逢花跋马头。
别来唯独宿，梦里尚同游。
所在求飱过，无因离得愁。','',''),('quantangshi-27882','雪夜与真上人宿韩协律宅','朱慶餘','quantangshi','','卷28','斜雪微霑砌，空堂夜语清。
逆风听漏短，回烛向楼明。
盥漱随禅伴，讴吟得野情。
此欢那敢忘，世贵丈夫名。','',''),('quantangshi-27883','与贾岛顾非熊无可上人宿万年姚少府宅','朱慶餘','quantangshi','','卷28','莫厌通宵坐，贫中会聚难。
堂虚雪气入，灯在漏声残。
役思因生病，当禅岂觉寒。
开门各有事，非不惜余欢。','',''),('quantangshi-27884','震为苍筤竹','朱慶餘','quantangshi','','卷28','为擢东方秀，修然异众筠。
青苍才映粉，蒙密正含春。
嫩箨霑微雨，幽根绝细尘。
乍怜分径小，偏觉带烟新。
结实皆留凤，垂阴似庇人。
顾唯竿在手，深水挂頳鳞。','',''),('quantangshi-27885','题青龙寺','朱慶餘','quantangshi','','卷28','寺好因岗势，登临值夕阳。
青山当佛阁，红叶满僧廊。
竹色连平地，虫声在上方。
最怜东面静，为近楚城墙。','',''),('quantangshi-27886','送滕庶子致仕归江南','朱慶餘','quantangshi','','卷28','常怀独往意，此日去朝簪。
丹诏荣归骑，清风满故林。
诸侯新起敬，遗老重相寻。
在处饶山水，堪行慰所心。','',''),('quantangshi-27887','夏日题武功姚主簿','朱慶餘','quantangshi','','卷28','亭午无公事，垂帘树色间。
僧来茶竈动，吏去印牀闲。
傍竹行寻巷，当门立看山。
吟诗老不倦，未省话官班。','',''),('quantangshi-27888','送张景宣下第东归','朱慶餘','quantangshi','','卷28','归省值花时，闲吟落第诗。
高情怜道在，公论觉才遗。
春雨连淮暗，私船过马迟。
离心可惆怅，为有入城期。','',''),('quantangshi-27889','送顾非熊下第归','朱慶餘','quantangshi','','卷28','但取诗名远，宁论下第频。
惜为今日别，共受几年贫。
听雨宿吴寺，过江逢越人。
知从本府荐，秋晚又辞亲。','',''),('quantangshi-27890','送韦繇校书赴浙东幕','朱慶餘','quantangshi','','卷28','丞相辟书新，秋关独去人。
官离芸阁早，名占甲科频。
水驿迎船火，山城候骑尘。
湖边寄家久，到日喜荣亲。','',''),('quantangshi-27891','寻贾岛所居','朱慶餘','quantangshi','','卷28','求闲身未得，此日到京东。
独在钟声外，相逢树色中。
谁言人渐老，所向意皆同。
月上因留宿，移牀对药丛。','',''),('quantangshi-27892','题毗陵上人院','朱慶餘','quantangshi','','卷28','院深终日静，落叶覆秋虫。
盥漱新斋后，修行未老中。
映松山色远，隔水磬声通。
此处宜清夜，高吟永与同。','',''),('quantangshi-27893','送李侍御入蕃','朱慶餘','quantangshi','','卷28','远使随双节，新官属外台。
戎装非好武，书记本多才。
移帐依泉宿，迎人带雪来。
心知玉关道，稀见一花开。','',''),('quantangshi-27894','望萧关','朱慶餘','quantangshi','','卷28','渐见风沙暗，萧关欲到时。
儿童能探火，妇女解缝旗。
川绝衔鱼鹭，林多带箭麋。
暂来戎马地，不敢苦吟诗。','',''),('quantangshi-27895','送韩校书赴江西幕','朱慶餘','quantangshi','','卷28','从军五湖外，终是称诗人。
酒后愁将别，涂中过却春。
山桥槲叶暗，水馆燕巢新。
驿舫迎应远，京书寄自频。
野情随到处，公务日关身。
久共趋名利，龙钟独滞秦。','',''),('quantangshi-27896','题寄王秘书','朱慶餘','quantangshi','','卷28','唯求买药价，此外更无机。
扶病看红叶，辞官着白衣。
断篱通野径，高树荫邻扉。
时复留僧宿，余人得见稀。','',''),('quantangshi-27897','山居','朱慶餘','quantangshi','','卷28','归来青壁下，又见满篱霜。
转觉琴斋静，闲从菊地荒。
山泉共鹿饮，林果让僧尝。
时复收新药，随云过石梁。','',''),('quantangshi-27898','重过惟贞上人院','朱慶餘','quantangshi','','卷28','老去唯求静，都忘外学名。
扫牀秋叶满，对客远云生。
香合闲留宿，晴阶暖共行。
窗西暮山色，依旧入诗情。','',''),('quantangshi-27899','与石昼秀才过普照寺','朱慶餘','quantangshi','','卷28','问人知寺路，松竹暗春山。
潭黑龙应在，巢空鹤未还。
经年为客倦，半日与僧闲。
更共尝新茗，闻钟笑语间。','',''),('quantangshi-27900','题任处士幽居','朱慶餘','quantangshi','','卷28','惜与幽人别，停舟对草堂。
湖云侵卧位，杉露滴茶牀。
山月吟时在，池花觉后香。
生涯无一物，谁与读书粮。','',''),('quantangshi-27901','送僧往太原谒李司空','朱慶餘','quantangshi','','卷28','已共邻房别，应无更住心。
中时过野店，后夜宿寒林。
寺去人烟远，城连塞雪深。
禅余得新句，堪对上公吟。','',''),('quantangshi-27902','将之上京别淮南书记李侍御','朱慶餘','quantangshi','','卷28','心地偶相见，语多为别难。
诗成公府晚，路入翠微寒。
逢石自应坐，有花谁共看。
身为当去雁，云尽到长安。','',''),('quantangshi-27903','韩协律相送精舍读书四韵奉寄呈陆补阙','朱慶餘','quantangshi','','卷28','白鹤西山别，更看上去船。
遥知寻寺路，应念宿江烟。
到处无闲日，回期已隔年。
何因陪夜坐，清论谏臣边。','',''),('quantangshi-27904','过苏州晓上人院','朱慶餘','quantangshi','','卷28','夏满律当清，无中景自生。
移松不避远，取石亦亲行。
经案离时少，绳牀着处平。
若将林下比，应只欠泉声。','',''),('quantangshi-27905','送僧游缙云','朱慶餘','quantangshi','','卷28','但望青山去，何山不是缘。
寺幽堪讲律，月冷称当禅。
水落无风夜，猨吟欲雨天。
寻师若有路，终作缓归年。','',''),('quantangshi-27906','赠道者','朱慶餘','quantangshi','','卷28','自识来清瘦，寻常语论真。
药成休伏火，符验不传人。
独有年过鹤，曾无病到身。
潜教问弟子，居处与谁邻。','',''),('quantangshi-27907','杭州卢录事山亭','朱慶餘','quantangshi','','卷28','山色满公署，到来诗景饶。
解衣临曲榭，隔竹见红蕉。
清漏焚香夕，轻岚视事朝。
静中看锁印，高处见迎潮。
曳履庭芜近，当身树叶飘。
傍城余菊在，步入一仙瓢。','',''),('quantangshi-27908','送品上人入秦','朱慶餘','quantangshi','','卷28','独去何人见，林塘共寂寥。
生缘闻磬早，觉路出尘遥。
江雪霑新草，秦园发故条。
心知禅定处，石室对芭蕉。','',''),('quantangshi-27909','题蔷薇花','朱慶餘','quantangshi','','卷28','四面垂条密，浮阴入夏清。
绿攒伤手刺，红堕断肠英。
粉着蜂须腻，光凝蝶翅明。
雨中看亦好，况复值初晴。','',''),('quantangshi-27910','题胡氏溪亭','朱慶餘','quantangshi','','卷28','亭与溪相近，无时不有风。
涧松生便黑，野藓看多红。
雨足秋声后，山沈夜色中。
主人能守静，略与客心同。','',''),('quantangshi-27911','看涛','朱慶餘','quantangshi','','卷28','不知来远近，但见白峨峨。
风雨驱寒玉，鱼龙迸上波。
声长势未尽，晓去夕还过。
要路横天堑，其如造化何。','',''),('quantangshi-27912','和刘补阙秋园寓兴之什十首 一','朱慶餘','quantangshi','','卷28','闲园清气满，新兴日堪追。
隔水蝉鸣后，当檐雁过时。
雨余槐穟重，霜近药苗衰。
不以朝簪贵，多将野客期。','',''),('quantangshi-27913','和刘补阙秋园寓兴之什十首 二','朱慶餘','quantangshi','','卷28','谁言高静意，不异在衡茅。
竹冷人离洞，天晴鹤出巢。
深篱藏白菌，荒蔓露青匏。
几见中宵月，清光坠树梢。','',''),('quantangshi-27914','和刘补阙秋园寓兴之什十首 三','朱慶餘','quantangshi','','卷28','逍遥人事外，杖屦入杉萝。
草色寒犹在，虫声晚渐多。
静逢山鸟下，幽称野僧过。
几许新开菊，闲从落叶和。','',''),('quantangshi-27915','和刘补阙秋园寓兴之什十首 四','朱慶餘','quantangshi','','卷28','留情清景宴，朝罢有余闲。
蝶散红兰外，萤飞白露间。
墙高微见寺，林静远分山。
吟足期相访，残阳自掩关。','',''),('quantangshi-27916','和刘补阙秋园寓兴之什十首 五','朱慶餘','quantangshi','','卷28','深斋尝独处，讵肯厌秋声。
翠筱寒愈静，孤花晚更明。
每因逢石坐，多见抱书行。
入夜听疎杵，遥知耿此情。','',''),('quantangshi-27917','和刘补阙秋园寓兴之什十首 六','朱慶餘','quantangshi','','卷28','苍翠经宵在，园庐景自深。
风凄欲去燕，月思向来砧。
碧石当莎迳，寒烟冒竹林。
杯瓢闲寄咏，清绝是知音。','',''),('quantangshi-27918','和刘补阙秋园寓兴之什十首 七','朱慶餘','quantangshi','','卷28','门巷唯苔藓，谁言不称贫。
台闲人下晚，果熟鸟来频。
石脉潜通井，松枝静离尘。
残蔬得晴后，又见一番新。','',''),('quantangshi-27919','和刘补阙秋园寓兴之什十首 八','朱慶餘','quantangshi','','卷28','卷帘天色静，近濑觉衣单。
蕉叶犹停翠，桐阴已爽寒。
云从高处望，琴爱静时弹。
正去重阳近，吟秋意未阑。','',''),('quantangshi-27920','和刘补阙秋园寓兴之什十首 九','朱慶餘','quantangshi','','卷28','竹迳通邻圃，清深称独游。
虫丝交影细，藤子坠声幽。
积润苔纹厚，迎寒荠叶稠。
闲来寻古画，未废执茶瓯。','',''),('quantangshi-27921','和刘补阙秋园寓兴之什十首 十','朱慶餘','quantangshi','','卷28','风物已萧飒，晚烟生霁容。
斜分紫陌树，远隔翠微钟。
宿客论文静，闲灯落烬重。
无穷林下意，真得古人风。','',''),('quantangshi-27922','上翰林蒋防舍人','朱慶餘','quantangshi','','卷28','清重可过知内制，从前礼绝外庭人。
看花在处多随驾，召宴无时不及旬。
马自赐来骑觉稳，诗缘得后意长新。
应怜独在文场久，十有余年浪过春。','',''),('quantangshi-27923','上翰林李舍人','朱慶餘','quantangshi','','卷28','记得早年曾拜识，便怜孤进赏文章。
免令汩没慙时辈，与作声名彻举场。
一自凤池承密旨，今因世路接余光。
云泥虽隔思长在，纵使无成也不忘。','',''),('quantangshi-27924','题章正字道正新居','朱慶餘','quantangshi','','卷28','独在御楼南畔住，生涯还似旧时贫。
全无竹可侵行迳，一半花犹属别人。
吟处不妨嫌鼓闹，眼前唯称与僧邻。
近来渐觉青莎巷，车马过从已有尘。','',''),('quantangshi-27925','送李余及第归蜀','朱慶餘','quantangshi','','卷28','从得高科名转盛，亦言归去满城知。
发时谁不开筵送，到处人争与马骑。
剑路红蕉明栈阁，巴村绿树荫神祠。
乡中后辈游门馆，半是来求近日诗。','',''),('quantangshi-27926','送唐中丞开淘西湖夏日游泛因书示郡人','朱慶餘','quantangshi','','卷28','萍岸新淘见碧霄，中流相去忽成遥。
空余孤屿来诗景，无复横槎碍柳条。
红斾路幽山翠湿，锦帆风起浪花飘。
共知浸润同雷泽，何虑川源有旱苗。','',''),('quantangshi-27927','过旧宅','朱慶餘','quantangshi','','卷28','古巷戟门谁旧宅，早曾闻说属官家。
更无新燕来巢屋，唯有闲人去看花。
空廐欲摧尘满枥，小池初涸草侵沙。
荣华事歇皆如此，立马踟蹰到日斜。','',''),('quantangshi-27928','鄂渚送白舍人赴杭州','朱慶餘','quantangshi','','卷28','岂知鹦鹉洲边路，得见凤皇池上人。
从此不同诸客礼，故乡西与郡城邻。','',''),('quantangshi-27929','题崔驸马林亭','朱慶餘','quantangshi','','卷28','选居幽近御街东，易得诗人聚会同。
白练鸟飞深竹里，朱弦琴在乱书中。
亭开山色当高枕，楼静箫声落远风。
何事宦涂犹寂寞，都缘清苦道难通。','',''),('quantangshi-27930','赠韩协律','朱慶餘','quantangshi','','卷28','永日微吟在竹前，骨清唯爱漱寒泉。
门闲多有投文客，身病长无买药钱。
岭寺听猨频独宿，湖亭避宴动经年。
亲知尽怪疎荣禄，的是将心暗学禅。','',''),('quantangshi-27931','自萧关望临洮','朱慶餘','quantangshi','','卷28','玉关西路出临洮，风卷边沙入马毛。
寺寺院中无竹树，家家壁上有弓刀。
惟怜战士垂金甲，不尚游人着白袍。
日暮独吟秋色里，平原一望戍楼高。','',''),('quantangshi-27932','送崔约下第归淮南觐省','朱慶餘','quantangshi','','卷28','远忆拜亲留不住，出门行计与谁同。
程涂半是依船上，请谒多愁值雨中。
堰水静连堤树绿，村桥时映野花红。
回期须及来春事，莫便江边逐钓翁。','',''),('quantangshi-27933','羽林郎','朱慶餘','quantangshi','','卷28','紫髯年少奉恩初，直合将军尽不如。
酒后引兵围百草，风前驻斾领边书。
宅将公主同时赐，官与中郎共日除。
大笑鲁儒年四十，腰间犹未识金鱼。','',''),('quantangshi-27934','归故园','朱慶餘','quantangshi','','卷28','桑柘骈阗数亩间，门前五柳正堪攀。
尊中美酒长须满，身外浮名总是闲。
竹迳有时风为扫，柴门无事日常关。
于焉已是忘机地，何用将金别买山。','',''),('quantangshi-27935','同友人看花','朱慶餘','quantangshi','','卷28','寻花不问春深浅，纵是残红也入诗。
每个树边行一匝，谁家园里最多时。','',''),('quantangshi-27936','种花','朱慶餘','quantangshi','','卷28','忆昔两京官道上，可怜桃李昼阴垂。
不知谁作巡花使，空记玄宗遣种时。','',''),('quantangshi-27937','早发庐江涂中遇雪寄李侍御','朱慶餘','quantangshi','','卷28','芦苇声多雁满陂，湿云连野见山稀。
遥知将吏相逢处，半是春城贺雪归。','',''),('quantangshi-27938','登望云亭招友','朱慶餘','quantangshi','','卷28','日日恐无云可望，不辞逐静望来频。
共知亭下眠云远，解到上头能几人。','',''),('quantangshi-27939','刘补阙西亭晚宴','朱慶餘','quantangshi','','卷28','虫声已尽菊花干，共立松阴向晚寒。
对酒看山俱惜去，不知斜月下栏干。','',''),('quantangshi-27940','送长安罗少府','朱慶餘','quantangshi','','卷28','科名再得年犹少，今日休官更觉贤。
去国已辞趋府伴，向家还入渡江船。
雪晴新雁斜行出，潮落残云远色鲜。
在处若逢山水住，到时应不及秋前。','',''),('quantangshi-27941','林下招胡长官','朱慶餘','quantangshi','','卷28','语低清貌似休粮，称着朱衣入草堂。
销暑近来无别物，桂阴当午满绳牀。','',''),('quantangshi-27942','与真上人一二禅师题玢寺主院','朱慶餘','quantangshi','','卷28','杖屦相随任处便，不唯空寄上方眠。
归时亦取湖边路，晚映枫林共上船。','',''),('quantangshi-27943','寻僧','朱慶餘','quantangshi','','卷28','吟背春城出草迟，天晴紫阁赴僧期。
山边树下行人少，一派新泉日午时。','',''),('quantangshi-27944','题王丘长史宅','朱慶餘','quantangshi','','卷28','更无人吏在门前，不似居官似学仙。
药气暗侵朝服上，花阴晚到簿书边。
玉琴闲把看山坐，筒簟长铺与客眠。
时见街中骑瘦马，低头只是为诗篇。','',''),('quantangshi-27945','寄刘少府','朱慶餘','quantangshi','','卷28','唯爱图书兼古器，在官犹自未离贫。
更闻县去青山近，称与诗人作主人。','',''),('quantangshi-27946','哭胡遇','朱慶餘','quantangshi','','卷28','寻僧昨日尚相随，忽见绯幡意可知。
题处旧诗休更读，买来新马忆曾骑。
不应随分空营奠，终拟求人与立碑。
每向宣阳里中过，遥闻哭临泪先垂。','',''),('quantangshi-27947','自述','朱慶餘','quantangshi','','卷28','诗人甘寂寞，居处遍苍苔。
后夜蟾光满，邻家树影来。
岂知莲帐好，自爱草堂开。
愿答相思意，援毫愧不才。','',''),('quantangshi-27948','省试晦日与同志昆明池泛舟','朱慶餘','quantangshi','','卷28','故人同泛处，远色望中明。
静见沙痕露，微思月魄生。
周回余雪在，浩渺暮云平。
戏鸟随兰棹，空波荡石鲸。
劫灰难问理，岛树偶知名。
自省曾追赏，无如此日情。','',''),('quantangshi-27949','送崔拾遗赴阙','朱慶餘','quantangshi','','卷28','清貌淩寒玉，朝来拜拾遗。
行承天子诏，去感主人知。
劒佩分班日，风霜独立时。
名高住不得，非与九霄期。','',''),('quantangshi-27950','酬李处士见赠','朱慶餘','quantangshi','','卷28','干上非无援，才多却累身。
云霄未得路，江海作闲人。
久别唯谋道，相逢不话贫。
行藏一如此，可便老风尘。','',''),('quantangshi-27951','送僧游温州','朱慶餘','quantangshi','','卷28','夏满随所适，江湖非系缘。
卷经离峤寺，隔苇上秋船。
水落无风夜，猨啼欲雨天。
石门期独往，谢守有遗篇。','',''),('quantangshi-27952','梦谢亭','朱慶餘','quantangshi','','卷28','梦后何人见，孤亭似旧时。
褰开诚得地，冥感竟因诗。
不往过应少，悲来下独迟。
顾慙非谢客，灵贶杳难追。','',''),('quantangshi-27953','河亭','朱慶餘','quantangshi','','卷28','孤亭临绝岸，猨鸟识幽蹊。
花落曾谁到，诗成独未题。
潮痕经雨在，石笋与杉齐。
谢守便登陟，秋来屐齿低。','',''),('quantangshi-27954','送吴秀才之山西','朱慶餘','quantangshi','','卷28','泽潞西边路，兰桡北去人。
出门谁恨别，投分不缘贫。
杯酒从年少，知音在日新。
东湖发诗意，夏卉竟如春。','',''),('quantangshi-27955','和处州严郎中游南溪','朱慶餘','quantangshi','','卷28','四望非人境，从前洞穴深。
潭清蒲远岸，岚积树无阴。
看草初移屐，扪萝忽并簪。
世嫌山水僻，谁伴谢公吟。','',''),('quantangshi-27956','秋宵宴别卢侍御','朱慶餘','quantangshi','','卷28','风亭弦管绝，玉漏一声新。
绿茗香醒酒，寒灯静照人。
清班无意恋，素业本来贫。
明发青山道，谁逢去马尘。','',''),('quantangshi-27957','酬于欣校书见贻','朱慶餘','quantangshi','','卷28','能□得从军，清嬴□□□。
绮罗徒满目，山水不离心。
暂别愁花老，相思倚竹阴。
家贫无以养，未可话抽簪。','',''),('quantangshi-27958','送石协律归吴兴别业','朱慶餘','quantangshi','','卷28','识来无定居，此去复何如。
一与耕者遇，转将朝客疎。
资身唯药草，教子但诗书。
曾许黄庭本，斯言岂合虚。','',''),('quantangshi-27959','同卢校书游新兴寺','朱慶餘','quantangshi','','卷28','山深云景别，有寺亦堪过。
才子将迎远，林僧气性和。
潭清蒲影定，松老鹤声多。
岂不思公府，其如野兴何。','',''),('quantangshi-27960','送马秀才','朱慶餘','quantangshi','','卷28','清貌不识睡，见来尝苦吟。
风尘归省日，江海寄家心。
与鹤期前岛，随僧过远林。
相于竟何事，无语与知音。','',''),('quantangshi-27961','赠律师院','朱慶餘','quantangshi','','卷28','粉壁通莲径，扁舟到不迷。
苇声过枕上，湖色满窗西。
但见修行苦，谁论夏腊低。
闲看种来树，已觉与身齐。','',''),('quantangshi-27962','送僧往台岳','朱慶餘','quantangshi','','卷28','五城初罢讲，海上忆闲行。
触雪麻衣静，登山竹锡轻。
天寒岳寺出，日晚岛泉清。
坐与幽期遇，何人识此情。','',''),('quantangshi-27963','送惠雅上人西游','朱慶餘','quantangshi','','卷28','五湖僧独往，此去与谁期。
兴远常怜鹤，禅余肯废诗。
望云回寺晚，为讲到城迟。
还想安居日，应当后夏时。','',''),('quantangshi-27964','将之上京留别淮南书记李侍御','朱慶餘','quantangshi','','卷28','半似无名位，门当静处开。
人心皆向德，物色不供才。
酒兴春边过，军谋意外来。
取名荣相府，却虑诏书催。','',''),('quantangshi-27965','送祝秀才归衢州','朱慶餘','quantangshi','','卷28','旧隐縠溪上，忆归年已深。
学徒花下别，乡路雪边寻。
骑吏陪春赏，江僧伴晚吟。
高科如在意，当自惜光阴。','',''),('quantangshi-27966','过孟浩然旧居','朱慶餘','quantangshi','','卷28','命合终山水，才非不称时。
冢边空有树，身后独无儿。
散尽诗篇本，长存道德碑。
平生谁见重，应只是王维。','',''),('quantangshi-27967','送虚上人游天台','朱慶餘','quantangshi','','卷28','青冥通去路，谁见独随缘。
此地春前别，何山夜后禅。
石桥隐深树，朱阙见晴天。
好是修行处，师当住几年。','',''),('quantangshi-27968','孔尚书致仕因而有寄赠','朱慶餘','quantangshi','','卷28','高人心易足，三表乞身闲。
与世长疎索，唯僧得往还。
直声留阙下，生事在林间。
时复逢清景，乘车看远山。','',''),('quantangshi-27969','和处州韦使君新开南溪','朱慶餘','quantangshi','','卷28','地里光图谶，樵人共说深。
悠然想高躅，坐使变荒岑。
疏凿因殊旧，亭台亦自今。
静容猨暂下，闲与鹤同寻。
转斾驯禽起，褰帷瀑溜侵。
石稀潭见底，岚暗树无阴。
跻险难通屐，攀栖称抱琴。
云风开物意，潭水识人心。
携榼巡花遍，移舟惜景沈。
世嫌山水僻，谁伴谢公吟。','',''),('quantangshi-27970','送罗先辈书记归后却还闽中留别','朱慶餘','quantangshi','','卷28','同是越人从小别，忽归乡里见皆惊。
湖边访旧知谁在，幕下留欢但觉荣。
望岭又生红槿思，登车岂倦白云程。
况当季父承恩日，廉问南州政已成。','',''),('quantangshi-27971','送浙东陆中丞','朱慶餘','quantangshi','','卷28','坐将文教镇藩维，花满东南圣主知。
公务肯容私暂入，丰年长与德相随。
无贤不是朱门客，有子皆如玉树枝。
自爱此身居乐土，咏歌林下日忘疲。','',''),('quantangshi-27972','送元处士游天台','朱慶餘','quantangshi','','卷28','青冥路口绝人行，独与僧期上赤城。
树列烟岚春更好，溪藏冰雪夜偏明。
空山雉雊禾苗短，野馆风来竹气清。
若过石桥看瀑布，不妨高处便题名。','',''),('quantangshi-27973','吴兴新堤','朱慶餘','quantangshi','','卷28','春堤一望思无涯，树势还同水势斜。
深映菰蒲三十里，晴分功利几千家。
谋成既不劳人力，境远偏宜隔浪花。
若与青山长作固，汀洲肯恨柳丝遮。','',''),('quantangshi-27974','酬萧员外见寄','朱慶餘','quantangshi','','卷28','麦风吹雨正徘徊，忽报书从郡合来。
道薄谬应宗伯选，诗成徒费谢公才。
九霄示路空知感，十上惊魂尚未回。
胜寄幸容溪馆宿，龙钟慙见妓筵开。
傥期霁后陪新兴，一滴还须当一杯。','',''),('quantangshi-27975','台州郑员外郡斋双鹤','朱慶餘','quantangshi','','卷28','丹顶分明音响别，况闻来处隔云涛。
情悬碧落飞何晚，立近清池意自高。
向夜双栖惊玉漏，临轩对舞拂朱袍。
仙郎为尔开笼早，莫虑回翔损羽毛。','',''),('quantangshi-27976','送窦秀才','朱慶餘','quantangshi','','卷28','江南才子日纷纷，少有篇章得似君。
清话未同山寺宿，离歌已向客亭闻。
梅天马上愁黄鸟，泽国帆前见白云。
通籍名高年又少，回头应笑晚从军。','',''),('quantangshi-27977','送邵州林使君','朱慶餘','quantangshi','','卷28','轩车此去也逢时，地近湘南颇入诗。
一月计程那是远，中年出守未为迟。
水边花气熏章服，岭上岚光照画旗。
想得化行风土变，州人应为立生祠。','',''),('quantangshi-27978','送饶州张使君','朱慶餘','quantangshi','','卷28','白头为郡清秋别，山水南行岂觉赊。
楚老只应思入境，吴儿从此去移家。
馆依高岭分樟叶，路出重江见苇花。
务退唯当吟咏苦，留心曾不在生涯。','',''),('quantangshi-27979','题开元寺','朱慶餘','quantangshi','','卷28','西入山门十里程，粉墙书字甚分明。
萧帝坏陵深虎迹，广师遗院闭松声。
长廊画剥僧形影，石壁尘昏客姓名。
何必更将空色遣，眼前人事是浮生。','',''),('quantangshi-27980','与庞复言携酒望洞庭','朱慶餘','quantangshi','','卷28','南湖春色通平远，贪记诗情忘酒杯。
帆自巴陵山下过，雨从神女峡边来。
青蒲映水疎还密，白鸟飜空去复回。
尽日与君同看望，了然胜见画屏开。','',''),('quantangshi-27981','送浙东周判官','朱慶餘','quantangshi','','卷28','久闻从事沧江外，谁谓无官已白头。
来备戎装嘶数骑，去持丹诏入孤舟。
蝉鸣远驿残阳树，鹭起湖田片雨秋。
到日重陪丞相宴，镜湖新月在城楼。','',''),('quantangshi-27982','塞下曲','朱慶餘','quantangshi','','卷28','万里去长征，连年惯野营。
入羣来择马，抛伴去擒生。
箭拈雕翎阔，弓盘鹊角轻。
问看行近远，西过受降城。','',''),('quantangshi-27983','送僧','朱慶餘','quantangshi','','卷28','客行皆有为，师去是闲游。
野望携金策，禅栖寄石楼。
山深松翠冷，潭静菊花秋。
几处题青壁，袈裟溅瀑流。','',''),('quantangshi-27984','望早日','朱慶餘','quantangshi','','卷28','窗下闻鸡后，苍茫映远林。
才分天地色，便禁虎狼心。
是处程涂远，何山洞府深。
此时堪竚望，万象豁尘襟。','',''),('quantangshi-27985','旅中秋月有怀','朱慶餘','quantangshi','','卷28','久客未还乡，中秋倍可伤。
暮天飞旅雁，故国在衡阳。
岛外归云迥，林间坠叶黄。
数宵千里梦，时见旧书堂。','',''),('quantangshi-27986','十六夜月','朱慶餘','quantangshi','','卷28','昨夜忽已过，冰轮始觉亏。
孤光犹不定，浮世更堪疑。
影落澄江海，寒生静路岐。
皎然银汉外，长有众星随。','',''),('quantangshi-27987','行路难','朱慶餘','quantangshi','','卷28','世事浇浮后，艰难向此生。
人心不自足，公道为谁平。
德丧淳风尽，年荒蔓草盈。
堪悲山下路，非祗客中行。','',''),('quantangshi-27988','闲居冬末寄友人','朱慶餘','quantangshi','','卷28','短亭分袂后，倚槛思偏孤。
雨雪落残腊，轮蹄在远涂。
人情难故旧，草色易凋枯。
共有男儿事，何年入帝都。','',''),('quantangshi-27989','望九疑','朱慶餘','quantangshi','','卷28','浮生犹役役，未得便寻真。
白日如无路，青山岂有人。
烟收遥岫小，雨过晚川新。
倚杖何凝望，中宵梦往频。','',''),('quantangshi-27990','赠陈逸人','朱慶餘','quantangshi','','卷28','乐道辞荣禄，安居桂水东。
得闲多事外，知足少年中。
药圃无凡草，松庭有素风。
朝昏吟步处，琴酒与谁同。','',''),('quantangshi-27991','湖中闲夜遣兴','朱慶餘','quantangshi','','卷28','钓艇同琴酒，良宵背水滨。
风波不起处，星月尽随身。
浦迥湘烟卷，林香岳气春。
谁知此中兴，宁羡五湖人。','',''),('quantangshi-27992','题娥皇庙','朱慶餘','quantangshi','','卷28','娥皇挥涕处，东望九疑天。
往事难重问，孤峰尚惨然。
夜深寒峒响，秋近碧萝鲜。
未省明君意，遗踪万古传。','',''),('quantangshi-27993','送友人赴举','朱慶餘','quantangshi','','卷28','世路□□久，嗟君进取身。
十年虽苦志，万里托何人。
处困非乖道，求名本为亲。
惟应□□意，先与化龙鳞。','',''),('quantangshi-27994','中秋月','朱慶餘','quantangshi','','卷28','自古分功定，唯应缺又盈。
一宵当皎洁，四海尽澄清。
静觉风微起，寒过雪乍倾。
孤高稀此遇，吟赏倍牵情。','',''),('quantangshi-27995','宿山居','朱慶餘','quantangshi','','卷28','山店灯前客，醻身未有媒。
乡关贫后别，风雨夜深来。
上国求丹桂，衡门长绿苔。
堪惊双鬓雪，不待岁寒催。','',''),('quantangshi-27996','夏末留别洞庭知己','朱慶餘','quantangshi','','卷28','清秋时节近，分袂独凄然。
此地折高柳，何门听暮蝉。
浪摇湖外日，山背楚南天。
空感迢迢事，荣归在几年。','',''),('quantangshi-27997','过洞庭','朱慶餘','quantangshi','','卷28','帆挂狂风起，茫茫既往时。
波涛如未息，舟楫亦堪疑。
旅雁投孤岛，长天下四维。
前程有平处，谁敢与心期。','',''),('quantangshi-27998','旅中过重阳','朱慶餘','quantangshi','','卷28','一岁重阳至，羁游在异乡。
登高思旧友，满目是穷荒。
草际飞云片，天涯落雁行。
故山篱畔菊，今日为谁黄。','',''),('quantangshi-27999','送人下第归','朱慶餘','quantangshi','','卷28','独立身难达，新春与志违。
异乡青草长，故国白头归。
岸阔湖波溢，程遥楚岫微。
高秋期再会，此去莫忘机。','',''),('quantangshi-28000','叙吟','朱慶餘','quantangshi','','卷28','雅道辛勤久，潜疑鬓雪侵。
未能酬片善，难更免孤吟。
有景皆牵思，无愁不到心。
遥天一轮月，几夜见西沈。','',''),('quantangshi-28001','塞下感怀','朱慶餘','quantangshi','','卷28','塞下闲为客，乡心岂易安。
程涂过万里，身事尚孤寒。
竟日风沙急，临秋草木残。
何年方致主，时拂劒尘看。','',''),('quantangshi-28002','宿江馆','朱慶餘','quantangshi','','卷28','江馆迢遥处，知音信渐赊。
夜深乡梦觉，窗下月明斜。
起雁看荒草，惊波尚白沙。
那堪动乡思，故国在天涯。','',''),('quantangshi-28003','早梅','朱慶餘','quantangshi','','卷28','天然根性异，万物尽难陪。
自古承春早，严冬鬬雪开。
艳寒宜雨露，香冷隔尘埃。
堪把依松竹，良涂一处栽。','',''),('quantangshi-28004','夏日访贞上人院','朱慶餘','quantangshi','','卷28','炎夏寻灵境，高僧澹荡中。
命棊隈绿竹，尽日有清风。
流水离经阁，闲云入梵宫。
此时祛万虑，直似出尘笼。','',''),('quantangshi-28005','春日旅次','朱慶餘','quantangshi','','卷28','林中莺又啭，为客恨因循。
故里遥千里，青春过数春。
弟兄来渐少，岁月去何频。
早晚荣归计，中堂会所亲。','',''),('quantangshi-28006','赠至寂禅师','朱慶餘','quantangshi','','卷28','处世唯披衲，禅门几岁寒。
法空无所染，性悟不多看。
竟日门长掩，相逢草自残。
有时寻道侣，飞锡度峰峦。','',''),('quantangshi-28007','闲居即事','朱慶餘','quantangshi','','卷28','深嶂多幽景，闲居野兴清。
满庭秋雨过，连夜绿苔生。
石面横琴坐，松阴采药行。
超然尘事外，不似绊浮名。','',''),('quantangshi-28008','废宅花','朱慶餘','quantangshi','','卷28','数树荒庭上，芬芳映绿苔。
自缘逢暖发，不是为人开。
色艳莺犹在，香消蝶已回。
相从无胜事，谁向此倾杯。','',''),('quantangshi-28009','寄友人','朱慶餘','quantangshi','','卷28','当代知音少，相思在此身。
一分南北路，长问往来人。
是处应为客，何门许扫尘。
凭书正惆怅，蜀魄数声新。','',''),('quantangshi-28010','涂中感怀','朱慶餘','quantangshi','','卷28','世上名利牵，涂中意惨然。
到家能几日，为客便经年。
迹似萍随水，情同鹤在田。
何当功业遂，归路下遥天。','',''),('quantangshi-28011','赠道者','朱慶餘','quantangshi','','卷28','独住神仙境，门当瀑布开。
地多临水石，行不惹尘埃。
风起松花散，琴鸣鹤翅回。
还归九天上，时有故人来。','',''),('quantangshi-28012','长安春日野中','朱慶餘','quantangshi','','卷28','青春思楚地，闲步出秦城。
满眼是岐路，何年见弟兄。
烟霞装媚景，霄汉指前程。
尽日徘徊处，归鸿过玉京。','',''),('quantangshi-28013','长城','朱慶餘','quantangshi','','卷28','秦帝防胡虏，关心倍可嗟。
一人如有德，四海尽为家。
往事干坤在，荒基草木遮。
至今徒者骨，犹自哭风沙。','',''),('quantangshi-28014','酬李躔侍御','朱慶餘','quantangshi','','卷28','此去非关兴，君行不当游。
无因两处马，共饮一溪流。','',''),('quantangshi-28015','别李侍御后亭夜坐却寄','朱慶餘','quantangshi','','卷28','已作亭下别，未忘灯下情。
吟今欲就枕，更漏转分明。','',''),('quantangshi-28016','题钱宇别墅','朱慶餘','quantangshi','','卷29','林居向晚饶清景，惜去非关恋酒杯。
石净每因杉露滴，地幽渐觉水禽来。
药蔬秋后供僧尽，竹杖吟中望月回。
红叶闲飘篱落迥，行人远见草堂开。','',''),('quantangshi-28017','近试上张籍水部','朱慶餘','quantangshi','','卷29','洞房昨夜停红烛，待晓堂前拜舅姑。
[妆]罢低声问夫壻，画眉深浅入时无。','',''),('quantangshi-28018','留别卢玄休归荆门','朱慶餘','quantangshi','','卷29','江边离别心，言罢各霑襟。
以我去帆远，知君离恨深。
云开孤岛出，浪起白鸥沈。
更作来年约，阳台许伴寻。','',''),('quantangshi-28019','采莲','朱慶餘','quantangshi','','卷29','隔烟花草远蒙蒙，恨个来时路不同。
正是停桡相遇处，鸳鸯飞去急流中。','',''),('quantangshi-28020','都门晚望','朱慶餘','quantangshi','','卷29','绿槐花堕御沟边，步出都门雨后天。
日暮野人耕种罢，烽楼原上一条烟。','',''),('quantangshi-28021','舜井','朱慶餘','quantangshi','','卷29','碧甃磷磷不记年，青萝锁在小山颠。
向来下视千山水，疑是苍梧万里天。','',''),('quantangshi-28022','商州王中丞留吃枳壳','朱慶餘','quantangshi','','卷29','方物就中名最远，只应愈疾味偏佳。
若交尽乞人人与，采尽商山枳壳花。','',''),('quantangshi-28023','登玄都阁','朱慶餘','quantangshi','','卷29','野色晴宜上阁看，树阴遥映御沟寒。
豪家旧宅无人住，空见朱门锁牡丹。','',''),('quantangshi-28024','赠凤翔柳司录','朱慶餘','quantangshi','','卷29','杏园北寺题名日，数到如今四十年。
点检生涯与官职，一茎野竹在身边。','',''),('quantangshi-28025','啄木儿','朱慶餘','quantangshi','','卷29','丁丁向晚急还稀，啄遍庭槐未肯归。
终日与君除蠹害，莫嫌无事不频飞。','',''),('quantangshi-28026','榜曲','朱慶餘','quantangshi','','卷29','荷花明灭水烟空，惆怅来时径不同。
欲到前洲堪入处，鸳鸯飞出碧流中。','',''),('quantangshi-28027','逢山人','朱慶餘','quantangshi','','卷29','星月相逢现此身，自然无迹又无尘。
秋来若向金天会，便是青莲叶上人。','',''),('quantangshi-28028','过耶溪','朱慶餘','quantangshi','','卷29','春溪缭绕出无穷，两岸桃花正好风。
恰是扁舟堪入处，鸳鸯飞起碧流中。','',''),('quantangshi-28029','贺张水部员外拜命','朱慶餘','quantangshi','','卷29','省中官最美，无似水曹郎。
前代佳名逊，当时重姓张。
白须吟丽句，红叶吐朝阳。
徒有归山意，君恩未可忘。','',''),('quantangshi-28030','送璧州刘使君','朱慶餘','quantangshi','','卷29','王府登朝后，巴乡典郡新。
江分入峡路，山见采鞭人。
旧业孤城梦，生祠几处身。
知君素清俭，料得却来贫。','',''),('quantangshi-28031','赠江夏卢使君','朱慶餘','quantangshi','','卷29','诗人中最屈，无与使君俦。
白发虽求退，明时合见收。
登山犹自健，纵酒可多愁。
好是能骑马，相逢见鄂州。','',''),('quantangshi-28032','送崔秀才游江陵','朱慶餘','quantangshi','','卷29','樽前荆楚客，云外思萦回。
秦野春已尽，商山花正开。
鸥惊帆乍起，虹见雨初来。
自有归期在，蝉声处处催。','',''),('quantangshi-28033','观涛','朱慶餘','quantangshi','','卷29','木落霜飞天地清，空江百里见潮生。
鲜飙出海鱼龙气，晴雪喷山雷鼓声。
云日半阴川渐满，客帆皆过浪难平。
高楼晓望无穷意，丹叶黄花绕郡城。','',''),('quantangshi-28034','南湖','朱慶餘','quantangshi','','卷29','湖上微风小槛凉，翻翻菱荇满回塘。
野船着岸入春草，水鸟带波飞夕阳。
芦叶有声疑露雨，浪花无际似潇湘。
飘然蓬艇东归客，尽日相看忆楚乡。','',''),('quantangshi-28035','镜湖西岛言事','朱慶餘','quantangshi','','卷29','慵拙幸便荒僻地，纵闻猨鸟亦何愁。
偶因药酒欺梅雨，却着寒衣过麦秋。
岁计有余添橡实，生涯一半在渔舟。
世人若便无知己，应向此溪成白头。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-28036','送刘思复南河从军','朱慶餘','quantangshi','','卷29','七千里别宁无恨，且贵从军乐事多。
不驻节旄先候发，偶逢山寺亦难过。
蛮人独放畲田火，海兽羣游落日波。
远作受恩身不易，莫抛书劒近笙歌。','',''),('quantangshi-28037','宣武军镇作','王彥威','quantangshi','','卷29','天兵十万勇如貔，正是酬恩报国时。
汴水波澜喧鼓角，隋堤杨柳拂旌旗。
前驱红斾关西将，坐间青娥赵国姬。
寄语长安旧冠盖，麤官到底是男儿。','',''),('quantangshi-28038','春雪映早梅','庾敬休','quantangshi','','卷29','清晨凝雪彩，新候变庭梅。
树爱春荣徧，窗惊曙色催。
寒光添粉壁，积润履青苔。
分明六出瑞，隐映几枝开。
闻笛花疑落，挥琴兴转来。
曲成非寡和，长使思悠哉。','',''),('quantangshi-28039','题雁塔','許玫','quantangshi','','卷29','宝轮金地压人寰，独坐苍冥启玉关。
北岭风烟开魏阙，南轩气象镇商山。
灞陵车马垂杨里，京国城池落照间。
蹔放尘心游物外，六街钟鼓又催还。','',''),('quantangshi-28040','从军行','厲玄','quantangshi','','卷29','边草旱不春，劒光增野尘。
战场收骥尾，清瀚怯龙鳞。
帆色起归越，松声厌避秦。
几时逢范蠡，处处是通津。','',''),('quantangshi-28041','寄婺州温郎中','厲玄','quantangshi','','卷29','积雪没兰溪，邻州望不迷。
波中分雁宿，树杪接猨啼。
婺女家空在，星郎手未携。
故山新寺额，掩泣荷重题。','',''),('quantangshi-28042','送顾非熊及第归茅山','厲玄','quantangshi','','卷29','故山登第去，不似旧归难。
帆卷江初夜，梅生洞少寒。
采薇留客饮，折竹扫仙坛。
名在仪曹籍，何人肯挂冠。','',''),('quantangshi-28043','送黄晔明府岳州湘阴赴任','厲玄','quantangshi','','卷29','恩霑谴雪几人同，归宰湘阴六月中。
商岭马嘶残暑雨，席帆高挂早秋风。
贡名频向书闱失，飞檄曾传朔漠空。
西省尚嗟君宦远，水鸡啼处莫听鸿。','',''),('quantangshi-28044','缑山月夜闻王子晋吹笙','厲玄','quantangshi','','卷29','缑山明月夜，岑寂隔尘氛。
紫府参差曲，清宵次第闻。
韵流多入洞，声度半和云。
拂竹鸾惊侣，经松鹤对羣。
蟾光听处合，仙路望中分。
坐惜千岩曙，遗香过汝坟。','',''),('quantangshi-28045','和白敏中圣德和平致兹休运岁终功就合咏盛明呈上','魏扶','quantangshi','','卷29','萧关新复旧山川，古戍秦原景象鲜。
戎虏乞降归惠化，皇威渐被慑腥膻。
穹庐远戍烟尘灭，神武光扬竹帛传。
左袵尽知謌帝泽，从兹不更备三边。','',''),('quantangshi-28046','贡院题','魏扶','quantangshi','','卷29','梧桐叶落满庭阴，锁闭朱门试院深。
曾是昔年辛苦地，不将今日负初心。','',''),('quantangshi-28047','赋愁','魏扶','quantangshi','','卷29','愁，逈野，深秋。
生枕上，起眉头。
闺合危坐，风尘远游。
巴猨啼不住，谷水咽还流。
送客泊舟入浦，思乡望月登楼。
烟波早晚长羁旅，弦管终年乐五侯。','',''),('quantangshi-28048','登郡中销暑楼寄东川汝士','楊漢公','quantangshi','','卷29','岧嶤下瞰霅溪流，极目烟波望梓州。
虽有清风当夏景，只能销暑不销忧。','',''),('quantangshi-28049','明月楼','楊漢公','quantangshi','','卷29','吴兴城阙水云中，画舫青帘处处通。
溪上玉楼楼上月，清光合作水晶宫。','',''),('quantangshi-28050','送阆州妓人归老','何扶','quantangshi','','卷29','竹翠婵娟草迳幽，佳人归老傍汀洲。
玉蟾露冷梁尘暗，金凤花开云鬓秋。
十亩稻香新绿野，一声歌断旧青楼。
芭蕉半卷西池雨，日暮门前双白鸥。','',''),('quantangshi-28051','寄旧同年','何扶','quantangshi','','卷29','金榜题名墨尚新，今年依旧去年春。
花间每被红妆问，何事重来只一人。','',''),('quantangshi-28052','望九华山','柴夔','quantangshi','','卷29','九华如剑插云霓，青霭连空望欲迷。
北截吴门疑地尽，南连楚界觉天低。
龙池水蘸中秋月，石路人攀上汉梯。
惆怅旧游无复到，会须登此出尘泥。','',''),('quantangshi-28053','寄妾赵氏','房千里','quantangshi','','卷29','鸾凤分飞海树秋，忍听钟鼓越王楼。
只应霜月明君意，缓抚瑶琴送我愁。
山远莫教双泪尽，雁来空寄八行幽。
相如若返临邛市，画舸朱轩万里游。','',''),('quantangshi-28054','早行','劉郇伯','quantangshi','','卷29','钟静人犹寝，天高月自凉。
一星深戍火，残月半桥霜。
客老愁尘下，蝉寒怨路傍。
青山依旧色，宛是马卿乡。','',''),('quantangshi-28055','句','劉郇伯','quantangshi','','卷29','人生分外愁。','',''),('quantangshi-28056','赠成都僧','李章武','quantangshi','','卷29','南宗尚许通方便，何处心中更有经？好去苾蒭云水畔，何山松栢不青青。','',''),('quantangshi-28057','享太庙乐章','蕭倣','quantangshi','','卷29','圣祚无疆，庆传乐章。
金枝繁茂，玉叶延长。
海渎常晏，波涛不扬。
汪汪美化，垂范今王。','',''),('quantangshi-28058','享太庙乐章','蕭倣','quantangshi','','卷29','于铄丕嗣，惟帝之光。
羽龠象德，金石荐祥。
圣系无极，景命永昌。
神降上哲，维天配长。','',''),('quantangshi-28059','答杨尚书','柳棠','quantangshi','','卷29','未向燕台逢厚礼，幸因社会接余欢。
一鱼吃了终无愧，鵾化为鹏也不难。','',''),('quantangshi-28060','席上戏东川杨尚书','柳棠','quantangshi','','卷29','莫言名位未相俦，风月何曾阻献酬。
前辈不须轻后辈，靖安今日在衡州。','',''),('quantangshi-28061','缑山月夜闻王子晋吹笙','鍾輅','quantangshi','','卷29','月满缑山夜，风传子晋笙。
初闻盈谷远，渐听入云清。
杳异人间曲，遥分鹤上情。
孤鸾惊欲舞，万籁寂无声。
此夕留烟驾，何时返玉京？
唯愁音响绝，晓色出都城。','',''),('quantangshi-28062','南溪书院','楊發','quantangshi','','卷29','茅屋住来久，山深不置门。
草生垂井口，花发接篱根。
入院将雏鸟，攀萝抱子猨。
曾逢异人说，风景似桃源。','',''),('quantangshi-28063','春园醉醒闲卧小斋','楊發','quantangshi','','卷29','酣醉送余春，醒来恨更频。
花残蜂蠹物，叶暗鸟欺人。
帘闭高眠贵，斋空浩气新。
从今北牕蝶，长是梦中身。','',''),('quantangshi-28064','小园秋兴','楊發','quantangshi','','卷29','谁言帝城里，独作野人居。
石磴晴看叠，山苗晚自锄。
相惭五秉粟，尚癖一车书。
昔日扬雄宅，还无乡相舆。','',''),('quantangshi-28065','与诸公池上待月','楊發','quantangshi','','卷29','树密云萦岸，池遥水际空。
芰开方吐镜，苹动欲含风。
渐映沙汀白，微分渚叶红。
金波宜共赏，仙棹一宵同。','',''),('quantangshi-28066','檐雀','楊發','quantangshi','','卷29','弱羽怯孤飞，投檐幸所依。
衔环唯报德，贺厦本知归。
红觜休争顾，丹心自识机。
从来攀凤足，生死恋光辉。','',''),('quantangshi-28067','残花','楊發','quantangshi','','卷29','已笑良时晚，仍悲别酒催。
暖芳随日薄，残片逐风回。
黛歛愁歌扇，妆残泣镜台。
繁阴莫矜炫，终是共尘埃。','',''),('quantangshi-28068','山泉','楊發','quantangshi','','卷29','半空飞下水，势去响如雷。
静彻啼猨寺，高陵坐客台。
耳同经劒阁，身若到天台。
溅树吹成冻，邻祠触作灰。
深中试榔栗，浅处落莓苔。
半夜重城闭，潺湲枕底来。','',''),('quantangshi-28069','秋晚日少陵原游山泉之什','楊發','quantangshi','','卷29','喧浊侵肌性未沈，每来云外恣幽寻。
尘衣更喜秋泉洁，倦迹方依竹洞深。
暂过偶然应系分，有期终去但劳心。
唯怜一夜空山月，似许他年伴独吟。','',''),('quantangshi-28070','秋晴独立南亭','楊發','quantangshi','','卷29','昼对南风独闭关，暗期幽鸟去仍还。
如今有待终身贵，未若忘机尽日闲。
心似蒙庄游物外，官惭许掾在人间。
开襟自向清风笑，无限秋光为解颜。','',''),('quantangshi-28071','宿黄花馆','楊發','quantangshi','','卷29','孤馆萧条槐叶稀，暮蝉声隔水声微。
年年为客路无尽，日日送人身未归。
何处迷鸿离浦月，谁家愁妇捣霜衣。
夜深不卧帘犹卷，数点残萤入户飞。','',''),('quantangshi-28072','南野逢田客','楊發','quantangshi','','卷29','桑柘悠悠水蘸堤，晚风晴景不妨犂。
高机犹织卧蚕子，下坂未饥逢饲妻。
杏色满林羊酪熟，麦凉浮壠雉媒低。
生时自乐死由命，万事在天管不迷。','',''),('quantangshi-28073','东斋夜宴酬绍之起居见赠','楊發','quantangshi','','卷29','龙门八上不知津，唯有君心困益亲。
白社追游名自远，青袍相映道逾新。
十年江海鱼缄尽，一夜笙歌凤吹频。
渐老旧交情更重，莫将美酒负良辰。','',''),('quantangshi-28074','翫残花','楊發','quantangshi','','卷29','十日浓芳一岁程，东风初急眼偏明。
低枝似泥幽人醉，莫道无情似有情。','',''),('quantangshi-28075','咏蛙','楊收','quantangshi','','卷29','兔边分玉树，龙底耀铜仪。
会当同鼓吹，不复问官私。','',''),('quantangshi-28076','笔','楊收','quantangshi','','卷29','虽匪囊中物，何坚不可钻。
一朝操政柄，定使冠三端。','',''),('quantangshi-28077','嘲吴人观者','楊收','quantangshi','','卷29','尔幸无羸角，何用触吾藩。
若是升堂者，还应自得门。','',''),('quantangshi-28078','甲子岁书事','楊乘','quantangshi','','卷29','竖子未鼎烹，大君尚旰食。
风雷随出师，云霞有战色。
犒功椎万牛，募勇悬千帛。
武士日曳柴，飞将竞执馘。
喜气迎捷书，懽声送羽檄。
天兵日雄强，桀犬稍离析。
贼臂既已断，贼喉既已搤。
乐祸但鲸鲵，同恶为肘腋。
小大势难侔，逆顺初不敌。
违命固天亡，恃险乖长策。
虿毒久萌牙，狼顾非日夕。
礼貌忽骄狂，疏奏遂指斥。
动众岂佳兵，含忍恐无益。
鸿恩既已孤，小效不足惜。
腐儒一铅刀，投笔时感激。
帝阍不敢干，恓恓坐长画。','',''),('quantangshi-28079','南徐春日怀古','楊乘','quantangshi','','卷29','六代骄奢地，三春物象繁。
灵湖通涨海，天堑隔中原。
晓渡高帆驶，阴风巨舰翻。
旌旗西日落，戈甲夏云屯。
豹变资陈武，龙飞拥晋元。
风流前事尽，文物旧仪存。
邪侮尝移润，忠贞几度冤。
兴亡山兀兀，今古水浑浑。
露滴蜂偷蘂，莺啼日到轩。
酒肠堆麴糵，诗思遶干坤。
愁梦全无蝶，离忧每愧萱。
形骸劳大块，玉石任炎昆。
出处宁由己，升沈未足言。
且应中圣乐，坐起任昏昏。','',''),('quantangshi-28080','吴中书事','楊乘','quantangshi','','卷29','十万人家天堑东，管弦台榭满春风。
名归范蠡五湖上，国破西施一笑中。
香迳自生兰叶小，响廊深映月华空。
尊前多暇但怀古，尽日愁吟谁与同。','',''),('quantangshi-28081','建邺怀古','楊乘','quantangshi','','卷29','故城故垒满江濆，尽是干戈旧苦辛。
见此即须知帝力，生来便作太平人。','',''),('quantangshi-28082','牓句','楊乘','quantangshi','','卷29','伶俜乖拙两何如，昼泥琴声夜泥书。
数拍胡笳弹未熟，故人新命画胡车。','',''),('quantangshi-28083','题杨收相公宅','尹璞','quantangshi','','卷29','祸福从来路不遥，偶然平地上烟霄。
烟霄未稳还平地，门对孤峯占寂寥。','',''),('quantangshi-28084','明月照高楼','雍陶','quantangshi','','卷29','朗月何高高，楼中帘影寒。
一妇独含叹，四坐谁成欢。
时节屡已移，游旅杳不还。
沧溟傥未涸，妾泪终不干。
君若无定云，妾若不动山。
云行出山易，山逐云去难。
愿为边塞尘，因风委君颜。
君颜良洗多，荡妾浊水间。','',''),('quantangshi-28085','酬秘书王丞见寄','雍陶','quantangshi','','卷29','朝下有闲思，南沟边水行。
因来见寥落，转自叹平生。
白首丈夫气，赤心知己情。
留诗本相慰，却忆苦吟声。','',''),('quantangshi-28086','赠金河戍客','雍陶','quantangshi','','卷29','惯猎金河路，曾逢雪不迷。
射雕青冢北，走马黑山西。
戍远旌幡少，年深帐幕低。
酬恩须尽敌，休说梦中闺。','',''),('quantangshi-28087','孤桐','雍陶','quantangshi','','卷29','疎桐余一干，风雨日萧条。
岁晚琴材老，天寒桂叶凋。
已悲根半死，复恐尾全焦。
幸在龙门下，知音肯寂寥。','',''),('quantangshi-28088','秋露','雍陶','quantangshi','','卷29','白露暧秋色，月明清漏中。
痕沾珠箔重，点落玉盘空。
竹动时惊鸟，莎寒暗滴虫。
满园生永夜，渐欲与霜同。','',''),('quantangshi-28089','送徐使君赴岳州','雍陶','quantangshi','','卷29','渺渺楚江上，风旗摇去舟。
马归云梦晚，猨叫洞庭秋。
别思满南渡，乡心生北楼。
巴陵山水郡，应称谢公游。','',''),('quantangshi-28090','送裴璋还蜀因亦怀归','雍陶','quantangshi','','卷29','客在劒门外，新年音信稀。
自为千里别，已送几人归。
陌上月初落，马前花正飞。
离言殊未尽，春雨满行衣。','',''),('quantangshi-28091','送前鄠县李少府','雍陶','quantangshi','','卷29','近出圭峯下，还期又不赊。
身闲多宿寺，官满未移家。
罢钓临秋水，开尊对月华。
自当蓬阁选，岂得卧烟霞。','',''),('quantangshi-28092','送宜春裴明府之任','雍陶','quantangshi','','卷29','南行春已满，路半水茫然。
楚望花当渡，湘阴橘满川。
山横湖色上，帆出鸟行前。
此任无辞远，亲人贵用还。','',''),('quantangshi-28093','赠宗静上人','雍陶','quantangshi','','卷29','世上方传教，山中未得归。
闲花飘讲席，驯鸽污禅衣。
积雨谁过寺，残钟自掩扉。
寒来垂顶帽，白发剃应稀。','',''),('quantangshi-28094','同贾岛宿无可上人院','雍陶','quantangshi','','卷29','何处销愁宿，携囊就远僧。
中宵吟有雪，空屋语无灯。
静境唯闻铎，寒牀但枕肱。
还因爱闲客，始得见南能。','',''),('quantangshi-28095','和刘补阙秋园寓兴六首 一','雍陶','quantangshi','','卷29','水木夕阴冷，池塘秋意多。
庭风吹故叶，阶露净寒莎。
愁燕窥灯语，情人见月过。
砧声听已别，虫响复相和。','',''),('quantangshi-28096','和刘补阙秋园寓兴六首 二','雍陶','quantangshi','','卷29','闭门无事后，此地即山中。
但觉鸟声异，不知人境同。
晚花开为雨，残果落因风。
独坐还吟酌，诗成酒已空。','',''),('quantangshi-28097','和刘补阙秋园寓兴六首 三','雍陶','quantangshi','','卷29','自得家林趣，常时在外稀。
对僧餐野食，迎客着山衣。
雀鬬翻檐散，蝉惊出树飞。
功成他日后，何必五湖归。','',''),('quantangshi-28098','和刘补阙秋园寓兴六首 四','雍陶','quantangshi','','卷29','秋色庭芜上，清朝见露华。
疎篁抽晚笋，幽药吐寒芽。
引水新渠净，登台小径斜。
人来多爱此，萧爽似仙家。','',''),('quantangshi-28099','和刘补阙秋园寓兴六首 五','雍陶','quantangshi','','卷29','禁掖朝回后，林园胜赏时。
野人来辨药，庭鹤往看棊。
晚日明丹枣，朝霜润紫棃。
还因重风景，犹自有秋诗。','',''),('quantangshi-28100','和刘补阙秋园寓兴六首 六','雍陶','quantangshi','','卷29','圣代少封事，闲居方屏喧。
漏寒云外阙，木落月中园。
山鸟宿檐树，水萤流洞门。
无人见清景，林下自开尊。','',''),('quantangshi-28101','岳阳晚景','雍陶','quantangshi','','卷29','汉阳无远寺，见说过汾城。
云雨经春客，江山几日程。
终随鸥鸟去，祗在海潮生。
前路逢渔父，多愁问姓名。','',''),('quantangshi-28102','塞上宿野寺','雍陶','quantangshi','','卷29','塞上蕃僧老，天寒疾上关。
远烟平似水，高树暗如山。
去马朝常急，行人夜始闲。
更深听刁斗，时到磬声间。','',''),('quantangshi-28103','寒食夜池上对月怀友','雍陶','quantangshi','','卷29','人间多别离，处处是相思。
海内无烟夜，天涯有月时。
跳鱼翻荇叶，惊鹊出花枝。
亲友皆千里，三更独遶池。','',''),('quantangshi-28104','自述','雍陶','quantangshi','','卷29','万事谁能问，一名犹未知。
贫当多累日，闲过少年时。
灯下和愁睡，花前带酒悲。
无谋常委命，转觉命堪疑。','',''),('quantangshi-28105','送契玄上人南游','雍陶','quantangshi','','卷29','红叶落湘川，枫明映水天。
寻钟过楚寺，拥锡上泷船。
病客思留药，迷人待说禅。
南中多古迹，应访虎溪泉。','',''),('quantangshi-28106','少年行','雍陶','quantangshi','','卷29','不倚军功有侠名，可怜球猎少年情。
戴铃健鹘随声下，撼佩骄骢弄影行。
觅匠重装燕客劒，对人新按越姬筝。
岂知儒者心偏苦，吟向秋风白发生。','',''),('quantangshi-28107','咏双白鹭','雍陶','quantangshi','','卷29','双鹭应怜水满池，风飘不动顶丝垂。
立当青草人先见，行傍白莲鱼未知。
一足独拳寒雨里，数声相叫早秋时。
林塘得尔须增价，况与诗家物色宜。','',''),('quantangshi-28108','晴诗','雍陶','quantangshi','','卷29','晚虹斜日塞天昏，一半山川带雨痕。
新水乱侵青草路，残烟犹傍绿杨村。
胡人羊马休南牧，汉将旌旗在北门。
行子喜闻无战伐，闲看游骑猎秋原。','',''),('quantangshi-28109','送徐山人归睦州旧隐','雍陶','quantangshi','','卷29','君在桐庐何处住，草堂应与戴家邻。
初归山犬翻惊主，久别江鸥却避人。
终日欲为相逐计，临岐空羡独行身。
秋风钓艇遥相忆，七里滩西片月新。','',''),('quantangshi-28110','到蜀后记途中经历','雍陶','quantangshi','','卷29','劒峯重叠雪云漫，忆昨来时处处难。
大散岭头春足雨，褒斜谷里夏犹寒。
蜀门去国三千里，巴路登山八十盘。
自到成都烧酒熟，不思身更入长安。','',''),('quantangshi-28111','忆山寄僧','雍陶','quantangshi','','卷29','尘路谁知蹋雪踪，到来空认出云峯。
天晴远见月中树，风便细听烟际钟。
阅世数思僧并院，忆山长羡鹤归松。
新愁旧恨多难说，半在眉间半在胸。','',''),('quantangshi-28112','赠玉芝观王尊师','雍陶','quantangshi','','卷29','处处烟霞寻总遍，却来城市喜逢师。
时流见说无人在，年纪唯应有鹤知。
