长忧一日归天去，未授灵方遣问谁。','',''),('quantangshi-28113','哭饶州吴谏议使君','雍陶','quantangshi','','卷29','忽闻身谢满朝惊，俄感鄱阳罢市情。
遗爱永存今似古，高名不朽死如生。
神仙难见青骡事，谏议空留白马名。
授馆曾为门下客，几回垂泪过宣平。','',''),('quantangshi-28114','经杜甫旧宅','雍陶','quantangshi','','卷29','浣花溪里花多处，为忆先生在蜀时。
