沙崩水槛鸥飞尽，树压村桥马过迟。
山月不知人事变，夜来江上与谁期。','',''),('quantangshi-28115','河阴新城','雍陶','quantangshi','','卷29','高城新筑压长川，虎踞龙盘气色全。
