自有此来当汴口，武牢何用锁风烟。','',''),('quantangshi-28116','秋居病中','雍陶','quantangshi','','卷29','幽居悄悄何人到，落日清凉满树梢。
新句有时愁里得，古方无效病来抛。
荒檐数蝶悬蛛网，空屋孤萤入燕巢。
独卧南窗秋色晚，一庭红叶掩衡茅。','',''),('quantangshi-28117','罢还边将','雍陶','quantangshi','','卷29','白须虏将话边事，自失公权怨语多。
汉主岂劳思李牧，赵王犹是用廉颇。
