百战无功身老去，羡他年少渡黄河。','',''),('quantangshi-28118','永乐殷尧藩明府县池嘉莲咏','雍陶','quantangshi','','卷29','青苹白石匝莲塘，水里莲开带瑞光。
露湿红芳双朵重，风飘绿蔕一枝长。
同心栀子徒夸艳，合穗嘉禾岂解香。
