飞蝇一一皆先去，度鸟双双亦远鸣。
蹇步不唯伤旅思，此中兼见宦途情。','',''),('quantangshi-28121','寄永乐殷尧藩明府','雍陶','quantangshi','','卷29','古县萧条秋景晚，昔年陶令亦如君。
