相思不恨书来少，佳句多从阙下闻。','',''),('quantangshi-28122','蜀中战后感事','雍陶','quantangshi','','卷29','蜀道英灵地，山重水又回。
文章四子盛，道路五丁开。
词客题桥去，忠臣叱驭来。
卧龙同骇浪，跃马比浮埃。
已谓无妖土，那知有祸胎。
蕃兵依𣾴柳，蛮斾指江梅。
战后悲逢血，烧余恨见灰。
空留犀厌怪，无复酒除灾。
岁积苌弘怨，春深杜宇哀。
家贫移未得，愁上望乡台。','',''),('quantangshi-28123','答蜀中经蛮后友人马艾见寄','雍陶','quantangshi','','卷29','茜马渡泸水，北来如鸟轻。
几年朝凤阙，一日破龟城。
此地有征战，谁家无死生。
人悲还旧里，鸟喜下空营。
弟侄意初定，交朋心尚惊。
自从经难后，吟苦似猿声。','',''),('quantangshi-28124','卢岳闲居十韵','雍陶','quantangshi','','卷29','扰扰走人寰，争如占得闲。
防愁心付酒，求静力登山。
见药芳时采，逢花好处攀。
望云开病眼，临涧洗愁颜。
春色流岩下，秋声碎竹间。
锦文苔点点，钱样菊斑斑。
路远朝无客，门深夜不关。
鹤飞高缥缈，莺语巧绵蛮。
养拙甘沈默，忘怀绝险艰。
更怜云外路，空去又空还。','',''),('quantangshi-28125','送于中丞使北蕃','雍陶','quantangshi','','卷29','朔将引双旌，山遥碛雪平。
经年通国信，计日得蕃情。
野次依泉宿，沙中望火行。
远雕秋有力，寒马夜无声。
看猎临胡帐，思乡见汉城。
来春拥边骑，新草满归程。','',''),('quantangshi-28126','和河南白尹西池北新葺水斋招赏十二韵','雍陶','quantangshi','','卷29','二室峯前水，三川府右亭。
