雨夜思巫峡，秋朝想洞庭。
千年孤镜碧，一片远天青。
鱼戏摇红尾，鸥闲退白翎。
荷倾泻珠露，沙乱动金星。
藤架如纱帐，苔墙似锦屏。
龙门人少到，仙棹自多停。
