渐近蛮城谁敢哭，一时收泪羡猨啼。','',''),('quantangshi-28186','宿石门山居','雍陶','quantangshi','','卷29','牕灯欲灭夜愁生，萤火飞来促织鸣。
宿客几回眠又起，一溪秋水枕边声。','',''),('quantangshi-28187','过旧宅看花','雍陶','quantangshi','','卷29','山桃野杏两三栽，树树繁花去复开。
今日主人相引看，谁知曾是客移来。','',''),('quantangshi-28188','寄襄阳章孝标','雍陶','quantangshi','','卷29','青油幕下白云边，日日空山夜夜泉。
闻说小斋多野意，枳花阴里麝香眠。','',''),('quantangshi-28189','洛中感事','雍陶','quantangshi','','卷29','洛城今古足繁华，最恨乔家似石家。
行到窈娘身没处，水边愁见亚枝花。','',''),('quantangshi-28190','阴地关见入蕃公主石上手迹','雍陶','quantangshi','','卷29','汉家公主昔和蕃，石上今余手迹存。
风雨几年侵不灭，分明纤指印苔痕。','',''),('quantangshi-28191','美人春风怨','雍陶','quantangshi','','卷29','澹荡春风满眼来，落花飞蝶共裴回。
偏能飘散同心蔕，无那愁眉吹不开。','',''),('quantangshi-28192','过南邻花园','雍陶','quantangshi','','卷29','莫怪频过有酒家，多情长是惜年华。
春风堪赏还堪恨，才见开花又落花。','',''),('quantangshi-28193','劝行乐','雍陶','quantangshi','','卷29','老去风光不属身，黄金莫惜买青春。
白头纵作花园主，醉折花枝是别人。','',''),('quantangshi-28194','渡桑干河','雍陶','quantangshi','','卷29','南客岂曾谙塞北，年年唯见雁飞回。
今朝忽渡桑干水，不似身来似梦来。','',''),('quantangshi-28195','月下喜吕郎中除兵部','雍陶','quantangshi','','卷29','北阙云间见碧天，南宫月似旧时圆。
喜看列宿今朝正，休叹参差十四年。','',''),('quantangshi-28196','天津桥望春','雍陶','quantangshi','','卷29','津桥春水浸红霞，烟柳风丝拂岸斜。
翠辇不来金殿闭，宫莺衔出上阳花。','',''),('quantangshi-28197','自蔚州南入真谷有似劒门因有归思','雍陶','quantangshi','','卷29','我家蜀地身离久，忽见胡山似劒门。
马上欲垂千里泪，耳边唯欠一声猨。','',''),('quantangshi-28198','再经天涯地角山','雍陶','quantangshi','','卷29','每忆云山养短才，悔缘名利入尘埃。
十年马足行多少，两度天涯地角来。','',''),('quantangshi-28199','题等界寺二首 一','雍陶','quantangshi','','卷29','吴蜀千年等界村，英雄无主岂长存。
思量往事今何在，万里山中一寺门。','',''),('quantangshi-28200','题等界寺二首 二','雍陶','quantangshi','','卷29','两国道涂都万里，来从此地等平分。
行人竞说东西利，事不关心耳不闻。','',''),('quantangshi-28201','洛源驿戏题','雍陶','quantangshi','','卷29','柳阴春岭鸟新啼，暖色浓烟深处迷。
如恨往来人不见，水声呦咽出花溪。','',''),('quantangshi-28202','遣愁','雍陶','quantangshi','','卷29','抛掷泥中一听沈，不能三叹引愁深。
莫言客子无愁易，须识愁多暗损心。','',''),('quantangshi-28203','送友人弃官归山居','雍陶','quantangshi','','卷29','不爱人间紫与绯，却思松下着山衣。
春郊雨尽多新草，一路青青蹋雨归。','',''),('quantangshi-28204','山行','雍陶','quantangshi','','卷29','野花幽鸟几千般，头白山僧遍识难。
世上游人无复见，一生唯向画图看。','',''),('quantangshi-28205','送客二首 一','雍陶','quantangshi','','卷29','与君同在少年场，知己萧条壮士伤。
可惜报恩无处所，却提孤劒过咸阳。','',''),('quantangshi-28206','送客二首 二','雍陶','quantangshi','','卷29','行人立马强盘回，别字犹含未忍开。
好去出门休落泪，不如前路早归来。','',''),('quantangshi-28207','安国寺赠广宣上人','雍陶','quantangshi','','卷29','马急人忙尘路喧，几从朝出到黄昏。
今来合掌听师语，一似敲冰清耳根。','',''),('quantangshi-28208','初醒','雍陶','quantangshi','','卷29','心中得胜暂抛愁，醉卧凉风拂簟秋。
半夜觉来新酒醒，一条斜月到牀头。','',''),('quantangshi-28209','送客归襄阳旧居','雍陶','quantangshi','','卷29','襄阳耆旧别来稀，此去何人共掩扉。
唯有白铜鞮上月，水楼闲处待君归。','',''),('quantangshi-28210','夜闻方响','雍陶','quantangshi','','卷29','方响闻时夜已深，声声敲着客愁心。
不知正在谁家乐，月下犹疑是远砧。','',''),('quantangshi-28211','路逢有似亡友者恻然赋此','雍陶','quantangshi','','卷29','吾友今生不可逢，风流空想旧仪容。
朝来马上频回首，惆怅他人似蔡邕。','',''),('quantangshi-28212','望月怀江上旧游','雍陶','quantangshi','','卷29','往岁曾随江客船，秋风明月洞庭边。
为看今夜天如水，忆得当时水似天。','',''),('quantangshi-28213','途中西望','雍陶','quantangshi','','卷29','行行何处散离愁，长路无因暂上楼。
唯到高原即西望，马知人意亦回头。','',''),('quantangshi-28214','题友人所居','雍陶','quantangshi','','卷29','亚尹故居经几主，只因君住有诗情。
夜吟邻叟闻惆怅，七八年来无此声。','',''),('quantangshi-28215','蔚州晏内遇新雪','雍陶','quantangshi','','卷29','胡卢河畔逢秋雪，疑是风飘白鹤毛。
坐客停杯看未定，将军已湿褐花袍。','',''),('quantangshi-28216','蔚州晏内遇新雪 句','雍陶','quantangshi','','卷29','古木闽州道，驱羸落照间。
投村碍野水，问店隔荒山。','',''),('quantangshi-28217','立春日','李遠','quantangshi','','卷29','暖日傍帘晓，浓春开箧红。
钗斜穿彩燕，罗薄翦春虫。
巧着金刀力，寒侵玉指风。
娉婷何处戴，山鬓绿成藂。','',''),('quantangshi-28218','翦彩','李遠','quantangshi','','卷29','翦彩赠相亲，银钗缀凤真。
双双衔绶鸟，两两度桥人。
叶逐金刀出，花随玉指新。
愿君千万岁，无岁不逢春。','',''),('quantangshi-28219','题僧院','李遠','quantangshi','','卷29','不用问汤休，何人免白头。
百年如过鸟，万事尽浮沤。
别绪长牵梦，情由乱种愁。
却嫌风景丽，窗外碧云秋。','',''),('quantangshi-28220','观廉女真葬','李遠','quantangshi','','卷29','玉窗抛翠管，轻袖掩银鸾。
错落云车断，丁泠金磬寒。
鹤寻深院宿，人借旧书看。
寂寞焚香处，红花满石坛。','',''),('quantangshi-28221','闲居','李遠','quantangshi','','卷29','尘事久相弃，沈浮皆不知。
牛羊归古巷，燕雀遶疎篱。
买药经年晒，留僧尽日棊。
唯忧钓鱼伴，秋水隔波时。','',''),('quantangshi-28222','及第后送家兄游蜀','李遠','quantangshi','','卷29','人谁无远别，此别意多违。
正鹄虽言中，冥鸿不共飞。
玉京烟雨断，巴国梦魂归。
若过严家濑，殷勤看钓矶。','',''),('quantangshi-28223','送人入蜀','李遠','quantangshi','','卷29','蜀客本多愁，君今是胜游。
碧藏云外树，红露驿边楼。
杜魄呼名语，巴江作字流。','',''),('quantangshi-28224','游故王驸马池亭','李遠','quantangshi','','卷29','花树杳玲珑，渔舟处处通。
醉销罗绮艳，香暖芰荷风。
野鸟翻萍绿，斜桥印水红。
子猷箫管绝，谁爱碧鲜浓。','',''),('quantangshi-28225','悲铜雀台','李遠','quantangshi','','卷29','西陵树已尽，铜雀思偏多。
雪密疑楼阁，花开想绮罗。
影销堂上舞，声断帐前歌。
唯有漳河水，年年旧绿波。','',''),('quantangshi-28226','陪新及第赴同年会','李遠','quantangshi','','卷29','曾攀芳桂英，处处共君行。
今日杏园宴，当时天乐声。
柳浓堪系马，花上未藏莺。
满座皆仙侣，同年别有情。','',''),('quantangshi-28227','咏雁','李遠','quantangshi','','卷29','早晚辞沙漠，南来处处飞。
关山多雨雪，风水损毛衣。
碧海魂应断，红楼信自稀。
不知矰缴外，留得几行归。','',''),('quantangshi-28228','与碧溪上人别','李遠','quantangshi','','卷29','欲入凤城游，西溪别惠休。
色随花旋落，年共水争流。
客思偏来夜，蝉声觉送秋。
明朝逢旧侣，唯拟上歌楼。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-28229','赠殷山人','李遠','quantangshi','','卷29','有客抱琴宿，值予多怨怀。
啼乌弦易断，啸鹤调难谐。
曲罢月移幌，韵清风满斋。
谁能将此妙，一为奏金堦。','',''),('quantangshi-28230','咏壁鱼','李遠','quantangshi','','卷29','鳞细粉光鲜，开书乱眼前。
透窗疑漏网，落砚似流泉。
潜穴河图内，吞钩乙字边。
莫言鬐鬣小，食尽白苹篇。','',''),('quantangshi-28231','听话丛台','李遠','quantangshi','','卷29','有客新从赵地回，自言曾上古丛台。
云遮襄国天边去，树绕漳河地里来。
弦管变成山鸟哢，绮罗留作野花开。
金舆玉辇无行迹，风雨惟知长绿苔。','',''),('quantangshi-28232','失鹤','李遠','quantangshi','','卷29','秋风吹却九臯禽，一片闲云万里心。
碧落有情应怅望，青天无路可追寻。
来时白雪翎犹短，去日丹砂顶渐深。
华表柱头留语后，更无消息到如今。','',''),('quantangshi-28233','赠写御容李长史','李遠','quantangshi','','卷29','玉座尘消砚水清，龙髯不动彩毫轻。
初分隆准山河秀，乍点重瞳日月明。
宫女卷帘皆暗认，侍臣开殿尽遥惊。
三朝供奉无人敌，始觉僧繇浪得名。','',''),('quantangshi-28234','赠潼关不下山僧','李遠','quantangshi','','卷29','与君同在苦空间，君得空门我爱闲。
禁足已教修雁塔，终身不拟下鸡山。
窗中遥指三千界，枕上斜看百二关。
香茗一瓯从此别，转蓬流水几时还。','',''),('quantangshi-28235','过旧游见双鹤怆然有怀','李遠','quantangshi','','卷29','谢公何岁掩松楸，双鹤依然傍玉楼。
朱顶巑岏荒草上，雪毛零落小池头。
蓬瀛路断君何在，云水情深我尚留。
他日若来华表上，更添多少令威愁。','',''),('quantangshi-28236','赠友人','李遠','quantangshi','','卷29','凤城烟霭思偏多，曾向刘郎住处过。
银烛焰前贪劝酒，玉箫声里已闻歌。
佳人惜别看嘶马，公子含情向翠蛾。
今日重来门巷改，出墙桐树绿婆娑。','',''),('quantangshi-28237','赠南岳僧','李遠','quantangshi','','卷29','曾住衡阳岳寺边，门开江水与云连。
数州城郭藏寒树，一片风帆着远天。
猨啸不离行道处，客来皆到卧牀前。
今朝惆怅红尘里，惟忆闲陪尽日眠。','',''),('quantangshi-28238','赠弘文杜校书','李遠','quantangshi','','卷29','高倚霞梯万丈余，共看移步入宸居。
晓随鵷鹭排金锁，静对铅黄校玉书。
漠漠禁烟笼远树，泠泠宫漏响前除。
还闻汉帝亲词赋，好为从容奏子虚。','',''),('quantangshi-28239','听王氏话归州昭君庙','李遠','quantangshi','','卷29','献之闲坐说归州，曾到昭君庙里游。
自古行人多怨恨，至今乡土尽风流。
泉如珠泪侵阶滴，花似红妆满岸愁。
河畔犹残翠眉样，有时新月傍帘钩。','',''),('quantangshi-28240','过马嵬山','李遠','quantangshi','','卷29','金甲云旗尽日回，仓皇罗袖满尘埃。
浓香犹自飘銮辂，恨魄无因离马嵬。
南内宫人悲帐殿，东溟方士问蓬莱。
唯余坡上弯环月，时送残蛾入帝台。','',''),('quantangshi-28241','吴越怀古','李遠','quantangshi','','卷29','吴越千年奈怨何，两宫清吹作樵歌。
姑苏一败云无色，范蠡长游水自波。
霞拂故城疑转斾，月依荒树想嚬蛾。
行人欲问西施馆，江鸟寒飞碧草多。','',''),('quantangshi-28242','长安即事寄友人','李遠','quantangshi','','卷29','绮陌千年思断蓬，今来还宿凤城东。
瑶台钟鼓长依旧，巫峡烟花自不同。
千结故心为怨网，万条新景作愁笼。
何时更伴刘郎去，却见夭桃满树红。','',''),('quantangshi-28243','闻明上人逝寄友人','李遠','quantangshi','','卷29','萧寺曾过最上方，碧桐浓叶覆西廊。
游人缥缈红衣乱，座客从容白日长。
别后旋成庄叟梦，书来忽报惠休亡。
他时若更相随去，祗是含酸对影堂。','',''),('quantangshi-28244','赠咸阳李少府','李遠','quantangshi','','卷29','美貌雄才已少齐，宝书仙简两看题。
金刀片片裁新锦，玉步重重上旧梯。
鹏到碧天排雾去，凤游琼树拣枝栖。
蓬瀛宴罢试回首，一望尘中路正迷。','',''),('quantangshi-28245','隣人自金仙观移竹','李遠','quantangshi','','卷29','移居新竹已堪看，斸破莓苔得几竿。
圆节不教伤粉箨，低枝犹拟拂霜坛。
墙头枝动如烟绿，枕上风来送夜寒。
第一莫教渔父见，且从萧飒满朱栏。','',''),('quantangshi-28246','慈恩寺避暑','李遠','quantangshi','','卷29','香荷疑散麝，风铎似调琴。
不觉清凉晚，归人满柳阴。','',''),('quantangshi-28247','读田光传','李遠','quantangshi','','卷29','秦灭燕丹怨正深，古来豪客尽沾襟。
荆卿不了真闲事，辜负田光一片心。','',''),('quantangshi-28248','友人下第因以赠之','李遠','quantangshi','','卷29','刘毅虽然不掷卢，谁人不道解樗蒲。
黄金百万终须得，只有挼莎更一呼。','',''),('quantangshi-28249','咏鸳鸯','李遠','quantangshi','','卷29','鸳鸯离别伤，人意似鸳鸯。
试取鸳鸯看，多应断寸肠。','',''),('quantangshi-28250','赠筝妓伍卿','李遠','quantangshi','','卷29','轻轻没后更无筝，玉腕红纱到伍卿。
座客满筵都不语，一行哀雁十三声。','',''),('quantangshi-28251','黄陵庙词','李遠','quantangshi','','卷29','黄陵庙前莎草春，黄陵女儿蒨裙新。
轻舟小楫唱歌去，水远山长愁杀人。','',''),('quantangshi-28252','句','李遠','quantangshi','','卷29','人事三杯酒，流年一局棋。
青山不厌三杯酒，长日惟消一局棋。','',''),('quantangshi-28253','感怀诗一首','杜牧','quantangshi','','卷29','高文会隋季，提劒徇天意。
扶持万代人，步骤三皇地。
圣云继之神，神仍用文治。
德泽酌生灵，沈酣薰骨髓。
旄头骑箕尾，风尘蓟门起。
胡兵杀汉兵，尸满咸阳市。
宣皇走豪杰，谈笑开中否。
蟠联两河间，烬萌终不弭。
号为精兵处，齐蔡燕赵魏。
合环千里疆，争为一家事。
逆子嫁虏孙，西隣聘东里。
急热同手足，唱和如宫征。
法制自作为，礼文争僭拟。
压阶螭鬬角，画屋龙交尾。
署纸日替名，分财赏称赐。
刳隍𣤮万寻，缭垣叠千雉。
誓将付孱孙，血绝然方已。
九庙仗神灵，四海为输委。
如何七十年，汗赩含羞耻。
韩彭不再生，英卫皆为鬼。
凶门爪牙辈，穰穰如儿戏。
累圣但日吁，阃外将谁寄。
屯田数十万，堤防常慴惴。
急征赴军须，厚赋资凶器。
因隳画一法，且逐随时利。
流品极蒙尨，网罗渐离弛。
夷狄日开张，黎元愈憔悴。
邈矣远太平，萧然尽烦费。
至于贞元末，风流恣绮靡。
艰极泰循来，元和圣天子。
元和圣天子，英明汤武上。
茅茨覆宫殿，封章绽帷帐。
伍旅拔雄儿，梦卜庸真相。
勃云走轰霆，河南一平荡。
继于长庆初，燕赵终舁襁。
携妻负子来，北阙争顿颡。
故老抚儿孙，尔生今有望。
茹鲠喉尚隘，负重力未壮。
坐幄无奇兵，吞舟漏疎网。
骨添蓟垣沙，血涨滹沱浪。
秖云徒有征，安能问无状。
一日五诸侯，奔亡如鸟往。
取之难梯天，失之易反掌。
苍然太行路，翦翦还榛莽。
关西贱男子，誓肉虏杯羹。
请数系虏事，谁其为我听。
荡荡干坤大，曈曈日月明。
叱起文武业，可以豁洪溟。
安得封域内，长有扈苗征。
七十里百里，彼亦何尝争。
往往念所至，得醉愁苏醒。
韬舌辱壮心，叫阍无助声。
聊书感怀韵，焚之遗贾生。','',''),('quantangshi-28254','杜秋娘诗','杜牧','quantangshi','','卷29','京江水清滑，生女白如脂。
其间杜秋者，不劳朱粉施。
老濞即山铸，后庭千双眉。
秋持玉斝醉，与唱金缕衣。
濞既白首叛，秋亦红泪滋。
吴江落日渡，灞岸绿杨垂。
联裾见天子，盼眄独依依。
椒壁悬锦幕，镜奁蟠蛟螭。
低鬟认新宠，窈袅复融怡。
月上白璧门，桂影凉参差。
金阶露新重，闲捻紫箫吹。
莓苔夹城路，南苑雁初飞。
红粉羽林仗，独赐辟邪旗。
归来煮豹胎，餍饫不能饴。
咸池升日庆，铜雀分香悲。
雷音后车远，事往落花时。
燕禖得皇子，壮髪绿緌緌。
画堂授傅姆，天人亲捧持。
虎睛珠络褓，金盘犀镇帷。
长杨射熊罴，武帐弄哑咿。
渐抛竹马剧，稍出舞鸡奇。
崭崭整冠佩，侍宴坐瑶池。
眉宇俨图画，神秀射朝辉。
一尺桐偶人，江充知自欺。
王幽茅土削，秋放故乡归。
觚棱拂斗极，回首尚迟迟。
四朝三十载，似梦复疑非。
潼关识旧吏，吏髪已如丝。
却唤吴江渡，舟人那得知。
归来四隣改，茂苑草菲菲。
清血洒不尽，仰天知问谁。
寒衣一匹素，夜借隣人机。
我昨金陵过，闻之为歔欷。
自古皆一贯，变化安能推。
夏姬灭两国，逃作巫臣姬。
西子下姑苏，一舸逐鸱夷。
织室魏豹俘，作汉太平基。
误置代籍中，两朝尊母仪。
光武绍高祖，本系生唐儿。
珊瑚破高齐，作婢舂黄糜。
萧后去扬州，突厥为阏氏。
女子固不定，士林亦难期。
射钩后呼父，钓翁王者师。
无国要孟子，有人毁仲尼。
秦因逐客令，柄归丞相斯。
安知魏齐首，见断箦中尸。
给丧蹶张辈，廊庙冠峩危。
珥貂七叶贵，何妨戎虏支。
苏武却生返，邓通终死饥。
主张既难测，翻覆亦其宜。
地尽有何物，天外复何之。
指何为而捉，足何为而驰。
耳何为而听，目何为而窥。
己身不自晓，此外何思惟。
因倾一樽酒，题作杜秋诗。
愁来独长咏，聊可以自怡。','',''),('quantangshi-28255','郡斋独酌','杜牧','quantangshi','','卷29','前年鬓生雪，今年须带霜。
时节序鳞次，古今同雁行。
甘英穷西海，四万到洛阳。
东南我所见，北可计幽荒。
中画一万国，角角棊布方。
地顽压不穴，天逈老不僵。
屈指百万世，过如霹雳忙。
人生落其内，何者为彭殇。
促束自系缚，儒衣宽且长。
旗亭雪中过，敢问当垆娘。
我爱李侍中，标标七尺强。
白羽八扎弓，䏶压绿檀枪。
风前略横阵，紫髯分两傍。
淮西万虎士，怒目不敢当。
功成赐宴麟德殿，猨超鹘掠广球场。
三千宫女侧头看，相排踏碎双明璫。
旌竿幖幖旗㸌㸌，意气横鞭归故乡。
我爱朱处士，三吴当中央。
罢亚百顷稻，西风吹半黄。
尚可活乡里，岂唯满囷仓。
后岭翠扑扑，前溪碧泱泱。
雾晓起凫雁，日晚下牛羊。
叔舅欲饮我，社瓮尔来尝。
伯姊子欲归，彼亦有壶浆。
西阡下柳坞，东陌绕荷塘。
姻亲骨肉舍，烟火遥相望。
太守政如水，长官贪似狼。
征输一云毕，任尔自存亡。
我昔造其室，羽仪鸾鹤翔。
交横碧流上，竹映琴书牀。
出语无近俗，尧舜禹武汤。
问今天子少，谁人为栋梁。
我曰天子圣，晋公提纪纲。
联兵数十万，附海正诛沧。
谓言大义小不义，取易卷席如探囊。
犀甲吴兵鬬弓弩，虵矛燕戟驰锋铓。
岂知三载几百战，钩车不得望其墙。
答云此山外，有事同胡羌。
谁将国伐叛，话与钓鱼郎。
溪南重回首，一径出修篁。
尔来十三岁，斯人未曾忘。
往往自抚己，泪下神苍茫。
御史诏分洛，举趾何猖狂。
阙下谏官业，拜疏无文章。
寻僧解忧梦，乞酒缓愁肠。
岂为妻子计，未去山林藏。
平生五色线，愿补舜衣裳。
弦歌教燕赵，兰芷浴河湟。
腥膻一扫洒，凶狠皆披攘。
生人但眠食，寿域富农桑。
孤吟志在此，自亦笑荒唐。
江郡雨初霁，刀好截秋光。
池边成独酌，拥鼻菊枝香。
醺酣更唱太平曲，仁圣天子寿无疆。','',''),('quantangshi-28256','张好好诗','杜牧','quantangshi','','卷29','君为豫章姝，十三才有余。
翠茁凤生尾，丹叶莲含跗。
高阁倚天半，章江联碧虚。
此地试君唱，特使华筵铺。
主人顾四座，始讶来踟蹰。
吴娃起引赞，低徊映长裾。
双鬟可高下，才过青罗襦。
盼盼乍垂袖，一声雏凤呼。
繁弦迸关纽，塞管裂圆芦。
众音不能逐，褭褭穿云衢。
主人再三叹，谓言天下殊。
赠之天马锦，副以水犀梳。
龙沙看秋浪，明月游朱湖。
自此每相见，三日已为疎。
玉质随月满，艳态逐春舒。
绛唇渐轻巧，云步转虚徐。
旌斾忽东下，笙歌随舳舻。
霜凋谢楼树，沙暖句溪蒲。
身外任尘土，罇前极欢娱。
飘然集仙客，讽赋欺相如。
聘之碧瑶佩，载以紫云车。
洞闭水声远，月高蟾影孤。
尔来未几岁，散尽高阳徒。
洛城重相见，婥婥为当垆。
怪我苦何事，少年垂白须。
朋游今在否，落拓更能无。
门馆恸哭后，水云秋景初。
斜日挂衰柳，凉风生座隅。
洒尽满襟泪，短歌聊一书。','',''),('quantangshi-28257','冬至日寄小侄阿宜诗','杜牧','quantangshi','','卷29','小侄名阿宜，未得三尺长。
头圆筋骨紧，两眼明且光。
去年学官人，竹马遶四廊。
指挥羣儿辈，意气何坚刚。
今年始读书，下口三五行。
随兄旦夕去，歛手整衣裳。
去岁冬至日，拜我立我旁。
祝尔愿尔贵，仍且寿命长。
今年我江外，今日生一阳。
忆尔不可见，祝尔倾一觞。
阳德比君子，初生甚微茫。
排阴出九地，万物随开张。
一似小儿学，日就复月将。
勤勤不自已，二十能文章。
仕宦至公相，致君作尧汤。
我家公相家，劒佩尝丁当。
旧第开朱门，长安城中央。
第中无一物，万卷书满堂。
家集二百编，上下驰皇王。
多是抚州写，今来五纪强。
尚可与尔读，助尔为贤良。
经书括根本，史书阅兴亡。
高摘屈宋艳，浓薰班马香。
李杜泛浩浩，韩柳摩苍苍。
近者四君子，与古争强梁。
愿尔一祝后，读书日日忙。
一日读十纸，一月读一箱。
朝廷用文治，大开官职场。
愿尔出门去，取官如驱羊。
吾兄苦好古，学问不可量。
昼居府中治，夜归书满牀。
后贵有金玉，必不为汝藏。
崔昭生崔芸，李兼生窟郎。
堆钱一百屋，破散何披猖。
今虽未即死，饿冻几欲僵。
参军与县尉，尘土惊匡勷。
一语不中治，笞棰身满疮。
官罢得丝髪，好买百树桑。
税钱未输足，得米不敢尝。
愿尔闻我语，懽喜入心肠。
大明帝宫阙，杜曲我池塘。
我若自潦倒，看汝争翶翔。
总语诸小道，此诗不可忘。','',''),('quantangshi-28258','李甘诗','杜牧','quantangshi','','卷29','太和八九年，训注极虓虎。
潜身九地底，转上青天去。
四海镜清澄，千官云片缕。
公私各闲暇，追游日相伍。
岂知祸乱根，枝叶潜滋莽。
九年夏四月，天诫若言语。
烈风驾地震，狞雷驱猛雨。
夜于正殿阶，拔去千年树。
吾君不省觉，二凶日威武。
操持北斗柄，开闭天门路。
森森明庭士，缩缩循墙鼠。
平生负奇节，一旦如奴虏。
指名为锢党，状迹谁告诉。
喜无李杜诛，敢惮髡钳苦。
时当秋夜月，日值曰庚午。
喧喧皆传言，明晨相登注。
予时与和鼎，官班各持斧。
和鼎顾予言，我死知处所。
当庭裂诏书，退立须鼎俎。
君门晓日开，赭案横霞布。
俨雅千官容，勃郁吾累怒。
适属命鄜将，昨之传者误。
明日诏书下，谪斥南荒去。
夜登青泥坂，坠车伤左股。
病妻尚在牀，稚子初离乳。
幽兰思楚泽，恨水啼湘渚。
怳怳三闾魂，悠悠一千古。
其冬二凶败，涣汗开汤罟。
贤者须丧亡，谗人尚堆堵。
予于后四年，谏官事明主。
常欲雪幽冤，于时一裨补。
拜章岂艰难，胆薄多忧惧。
如何干斗气，竟作炎荒土。
题此涕滋笔，以代投湘赋。','',''),('quantangshi-28259','洛中送冀处士东游','杜牧','quantangshi','','卷29','处士有儒术，走可挟车輈。
坛宇宽帖帖，符彩高酋酋。
不爱事耕稼，不乐干王侯。
四十余年中，超超为浪游。
元和五六岁，客于幽魏州。
幽魏多壮士，意气相淹留。
刘济愿跪履，田兴请建筹。
处士拱两手，笑之但掉头。
自此南走越，寻山入罗浮。
愿学不死药，粗知其来由。
却于童顶上，萧萧玄髪抽。
我作八品吏，洛中如系囚。
忽遭冀处士，豁若登高楼。
拂榻与之坐，十日语不休。
论今星璨璨，考古寒飕飕。
治乱掘根本，蔓延相牵钩。
武事何骏壮，文理何优柔。
颜回捧俎豆，项羽横戈矛。
祥云遶毛髪，高浪开咽喉。
但可感神鬼，安能为献酬。
好入天子梦，刻像来尔求。
胡为去吴会，欲浮沧海舟。
赠以蜀马棰，副之胡罽裘。
饯酒载三斗，东郊黄叶稠。
我感有泪下，君唱高歌酬。
嵩山高万尺，洛水流千秋。
往事不可问，天地空悠悠。
四百年炎汉，三十代宗周。
二三里遗堵，八九所高丘。
人生一世内，何必多悲愁。
謌阕解携去，信非吾辈流。','',''),('quantangshi-28260','送沈处士赴苏州李中丞招以诗赠行','杜牧','quantangshi','','卷29','山城树叶红，下有碧溪水。
溪桥向吴路，酒旗夸酒美。
下马此送君，高歌为君醉。
念君苞材能，百工在城垒。
空山三十年，鹿裘挂窓睡。
自言陇西公，飘然我知己。
举酒属吴门，今朝为君起。
悬弓三百斤，囊书数万纸。
战贼即战贼，为吏即为吏。
尽我所有无，惟公之指使。
予曰陇西公，滔滔大君子。
常思抡羣材，一为国家治。
譬如匠见木，碍眼皆不弃。
大者麤十围，小者细一指。
㨝橛与栋梁，施之皆有位。
忽然竖明堂，一挥立能致。
予亦何为者，亦受公恩纪。
处士有常言，残虏为犬豕。
常恨两手空，不得一马棰。
今依陇西公，如虎傅两翅。
公非刺史材，当坐岩廊地。
处士魁奇姿，必展平生志。
东吴饶风光，翠巘多名寺。
疎烟亹亹秋，独酌平生思。
因书问故人，能忘批纸尾。
公或忆姓名，为说都憔悴。','',''),('quantangshi-28261','长安送友人游湖南','杜牧','quantangshi','','卷29','子性剧弘和，愚衷深褊狷。
相舍嚣譊中，吾过何由鲜。
楚南饶风烟，湘岸苦萦宛。
山密夕阳多，人稀芳草远。
青梅繁枝低，斑笋新梢短。
莫哭葬鱼人，酒醒且眠饭。','',''),('quantangshi-28262','皇风','杜牧','quantangshi','','卷29','仁圣天子神且武，内兴文教外披攘。
以德化人汉文帝，侧身修道周宣王。
迒蹊巢穴尽窒塞，礼乐刑政皆弛张。
何当提笔侍巡狩，前驱白斾吊河湟。','',''),('quantangshi-28263','雪中书怀','杜牧','quantangshi','','卷29','腊雪一尺厚，云冻寒顽痴。
孤城大泽畔，人疎烟火微。
愤悱欲谁语，忧愠不能持。
天子号仁圣，任贤如事师。
凡称曰治具，小大无不施。
明庭开广敞，才隽受羁维。
如日月縆升，若鸾凤葳蕤。
人才自朽下，弃去亦其宜。
北虏坏亭障，闻屯千里师。
牵连久不解，他盗恐旁窥。
臣实有长策，彼可徐鞭笞。
如蒙一召议，食肉寝其皮。
斯乃庙堂事，尔微非尔知。
向来躐等语，长作陷身机。
行当腊欲破，酒齐不可迟。
且想春候暖，瓮间倾一巵。','',''),('quantangshi-28264','雨中作','杜牧','quantangshi','','卷29','贱子本幽慵，多为隽贤侮。
得州荒僻中，更值连江雨。
一褐拥秋寒，小窗侵竹坞。
浊醪气色严，皤腹瓶甖古。
酣酣天地宽，怳怳嵇刘伍。
但为适性情，岂是藏鳞羽。
一世一万朝，朝朝醉中去。','',''),('quantangshi-28265','偶游石盎僧舍','杜牧','quantangshi','','卷29','敬岑草浮光，句沚水解脉。
益郁乍怡融，凝严忽颓坼。
梅纇暖眠酣，风绪和无力。
凫浴涨汪汪，雏娇村幂幂。
落日美楼台，轻烟饰阡陌。
潋绿古津远，积润苔基释。
孰谓汉陵人，来作江汀客。
载笔念无能，捧筹慙所画。
任辔偶追闲，逢幽果遭适。
僧语淡如云，尘事繁堪织。
今古几辈人，而我何能息。','',''),('quantangshi-28266','赴京初入汴口晓景即事先寄兵部李郎中','杜牧','quantangshi','','卷29','清淮控隋漕，北走长安道。
樯形栉栉斜，浪态迤迤好。
初旭红可染，明河澹如扫。
泽阔鸟来迟，村饥人语早。
露蔓虫丝多，风蒲燕雏老。
秋思高萧萧，客态长褭褭。
因怀京洛间，宦游何戚草。
什伍持津梁，澒涌争追讨。
翾便讵可寻，几秘安能考。
小人乏馨香，上下将何祷。
唯有君子心，显豁知幽抱。','',''),('quantangshi-28267','独酌','杜牧','quantangshi','','卷29','长空碧杳杳，万古一飞鸟。
生前酒伴闲，愁醉闲多少。
烟深隋家寺，殷叶暗相照。
独佩一壶游，秋毫泰山小。','',''),('quantangshi-28268','惜春','杜牧','quantangshi','','卷29','春半年已除，其余强为有。
即此醉残花，便同尝腊酒。
怅望送春杯，殷勤扫花箒。
谁为驻东流，年年长在手。','',''),('quantangshi-28269','题安州浮云寺楼寄湖州张郎中','杜牧','quantangshi','','卷29','去夏疎雨余，同倚朱阑语。
当时楼下水，今日到何处？
恨如春草多，事与孤鸿去。
楚岸柳何穷，别愁纷若絮。','',''),('quantangshi-28270','过骊山作','杜牧','quantangshi','','卷29','始皇东游出周鼎，刘项纵观皆引颈。
削平天下实辛勤，却为道傍穷百姓。
黔首不愚尔益愚，千里函关囚独夫。
牧童火入九泉底，烧作灰时犹未枯。','',''),('quantangshi-28271','池州送孟迟先辈','杜牧','quantangshi','','卷29','昔子来陵阳，时当苦炎热。
我虽在金台，头角长垂折。
奉披尘意惊，立语平生豁。
寺楼最骞轩，坐送飞鸟没。
一罇中夜酒，半破前峰月。
烟院松飘萧，风廊竹交戛。
时步郭西南，缭径苔圆折。
好鸟响丁丁，小溪光汃汃。
篱落见娉婷，机丝弄哑轧。
烟湿树姿娇，雨余山态活。
仲秋往历阳，同上牛矶歇。
大江吞天去，一练横坤抹。
千帆美满风，晓日殷鲜血。
历阳裴太守，襟韵苦超越。
鞔鼓画麒麟，看君击狂节。
离袖颭应劳，恨粉啼还咽。
明年忝谏官，绿树秦川阔。
子提健笔来，势若夸父渴。
九衢林马挝，千门织车辙。
秦台破心胆，黥阵惊毛髪。
子既屈一鸣，余固宜三刖。
慵忧长者来，病怯长街喝。
僧炉风雪夜，相对眠一褐。
暖灰重拥瓶，晓粥还分钵。
青云马生角，黄州使持节。
秦岭望樊川，秖得回头别。
商山四皓祠，心与樗蒲说。
大泽蒹葭风，孤城狐兔窟。
且复考诗书，无因见簪笏。
古训屹如山，古风冷刮骨。
周鼎列瓶罂，荆璧横抛摋。
力尽不可取，忽忽狂歌发。
三年未为苦，两郡非不达。
秋浦倚吴江，去檝飞青鹘。
溪山好画图，洞壑深闺闼。
竹冈森羽林，花坞团宫缬。
景物非不佳，独坐如韝绁。
丹鹊东飞来，喃喃送君札。
呼儿旋供衫，走门空踏袜。
手把一枝物，桂花香带雪。
喜极至无言，笑余翻不悦。
人生直作百岁翁，亦是万古一瞬中。
我欲东召龙伯翁，上天揭取北斗柄。
蓬莱顶上斡海水，水尽到底看海空。
月于何处去，日于何处来？
跳丸相趁走不住，尧舜禹汤文武周孔皆为灰。
酌此一杯酒，与君狂且歌。
离别岂足更关意，衰老相随可奈何。','',''),('quantangshi-28272','重送','杜牧','quantangshi','','卷29','手拈金仆姑，腰悬玉辘轳。
爬头峰北正好去，系取可汗钳作奴。
六宫虽念相如赋，其那防边重武夫。','',''),('quantangshi-28273','题池州弄水亭','杜牧','quantangshi','','卷29','弄水亭前溪，颭滟翠绡舞。
绮席草芊芊，紫岚峯伍伍。
螭蟠得形势，翚飞如轩户。
一镜匳曲堤，万丸跳猛雨。
槛前燕雁栖，枕上巴帆去。
丛筠侍修廊，密蕙媚幽圃。
杉树碧为幢，花骈红作堵。
停樽迟晚月，咽咽上幽渚。
客舟耿孤灯，万里人夜语。
漫流罥苔槎，饥凫晒雪羽。
玄丝落钩饵，冰鳞看吞吐。
断霓天帔垂，狂烧汉旗怒。
旷朗半秋晓，萧瑟好风露。
光洁疑可揽，欲以襟怀贮。
幽抱吟九歌，羁情思湘浦。
四时皆异状，终日为良遇。
小山浸石棱，撑舟入幽处。
孤歌倚桂岩，晚酒眠松坞。
纡余带竹村，蚕乡足砧杵。
塍泉落环佩，畦苗差纂组。
风俗知所尚，豪强耻孤侮。
隣丧不相舂，公租无诟负。
农时贵伏腊，簪瑱事礼赂。
乡校富华礼，征行产强弩。
不能自勉去，但愧来何暮。
故园汉上林，信美非吾土。','',''),('quantangshi-28274','题宣州开元寺','杜牧','quantangshi','','卷29','南朝谢眺城，东吴最深处。
亡国去如鸿，遗寺藏烟坞。
楼飞九十尺，廊环四百柱。
高高下下中，风绕松桂树。
青苔照朱阁，白鸟两相语。
溪声入僧梦，月色晖粉堵。
阅景无旦夕，凭阑有今古。
留我酒一罇，前山看春雨。','',''),('quantangshi-28275','大雨行','杜牧','quantangshi','','卷29','东垠黑风驾海水，海底卷上天中央。
三吴六月忽凄惨，晚后点滴来苍茫。
铮栈雷车轴辙壮，矫躩蛟龙爪尾长。
神鞭鬼驭载阴帝，来往喷洒何顚狂。
四面崩腾玉京仗，万里横互羽林枪。
云缠风束乱敲磕，黄帝未胜蚩尤强。
百川气势苦豪俊，坤关密鏁愁开张。
太和六年亦如此，我时壮气神洋洋。
东楼耸首看不足，恨无羽翼高飞翔。
尽召邑中豪健者，阔展朱盘开酒场。
奔觥槌鼓助声势，眼底不顾纤腰娘。
今年闒茸鬓已白，奇游壮观唯深藏。
景物不尽人自老，谁知前事堪悲伤。','',''),('quantangshi-28276','自宣州赴官入京路逢裴坦判官归宣州因题赠','杜牧','quantangshi','','卷29','敬亭山下百顷竹，中有诗人小谢城。
城高跨楼满金碧，下听一溪寒水声。
梅花落径香缭绕，雪白玉璫花下行。
萦风酒斾挂朱阁，半醉游人闻弄笙。
我初到此未三十，头脑钐利筋骨轻。
画堂檀板秋拍碎，一引有时联十觥。
老闲腰下丈二组，尘土高悬千载名。
重游鬓白事皆改，唯见东流春水平。
对酒不敢起，逢君还眼明。
云罍看人捧，波脸任他横。
一醉六十日，古来闻阮生。
是非离别际，始见醉中情。
今日送君话前事，高歌引劒还一倾。
江湖酒伴如相问，终老烟波不计程。','',''),('quantangshi-28277','赠宣州元处士','杜牧','quantangshi','','卷29','陵阳北郭隐，身世两忘者。
蓬蒿三亩居，宽于一天下。
罇酒对不酌，默与玄相话。
人生自不足，爱叹遭逢寡。','',''),('quantangshi-28278','村行','杜牧','quantangshi','','卷29','春半南阳西，柔桑过村坞。
褭褭垂柳风，点点回塘雨。
蓑唱牧牛儿，篱窥蒨裙女。
半湿解征衫，主人馈鸡黍。','',''),('quantangshi-28279','史将军二首 一','杜牧','quantangshi','','卷29','长鉟周都尉，闲如秋岭云。
取蝥弧登垒，以骈隣翼军。
百战百胜价，河南河北闻。
今遇太平日，老去谁怜君。','',''),('quantangshi-28280','史将军二首 二','杜牧','quantangshi','','卷29','壮气盖燕赵，耽耽魁杰人。
弯弧五百步，长戟八十斤。
河湟非内地，安史有遗尘。
何日武台坐，兵符授虎臣。','',''),('quantangshi-28281','华清宫三十韵','杜牧','quantangshi','','卷29','绣岭明珠殿，层峦下缭墙。
仰窥丹槛影，犹想赭袍光。
昔帝登封后，中原自古强。
一千年际会，三万里农桑。
几席延尧舜，轩墀接禹汤。
雷霆驰号令，星斗焕文章。
钓筑乘时用，芝兰在处芳。
北扉闲木索，南面富循良。
至道思玄圃，平居厌未央。
钩陈裹岩谷，文陛压青苍。
歌吹千秋节，楼台八月凉。
神仙高缥缈，环佩碎丁当。
泉暖涵窓镜，云娇惹粉囊。
嫩岚滋翠葆，清渭照红妆。
帖泰生灵寿，懽娱岁序长。
月闻仙曲调，霓作舞衣裳。
雨露偏金穴，干坤入醉乡。
玩兵师汉武，回手倒干将。
黥鬣掀东海，胡牙揭上阳。
喧呼马嵬血，零落羽林枪。
倾国留无路，还魂怨有香。
蜀峰横惨澹，秦树远微茫。
鼎重山难转，天扶业更昌。
望贤余故老，花萼旧池塘。
往事人谁问，幽襟泪独伤。
碧檐斜送日，殷叶半凋霜。
迸水倾瑶砌，疎风罅玉房。
尘埃羯鼓索，片段荔枝筐。
鸟啄摧寒木，蜗涎蠹画梁。
孤烟知客恨，遥起泰陵傍。','',''),('quantangshi-28282','长安杂题长句六首 一','杜牧','quantangshi','','卷29','觚棱金碧照山高，万国圭璋捧赭袍。
舐笔和铅欺贾马，赞功论道鄙萧曹。
东南楼日珠帘卷，西北天宛玉厄豪。
四海一家无一事，将军携镜泣霜毛。','',''),('quantangshi-28283','长安杂题长句六首 二','杜牧','quantangshi','','卷29','晴云似絮惹低空，紫陌微微弄袖风。
韩嫣金丸莎覆绿，许公鞯汗杏粘红。
烟生窈窕深东第，轮撼流苏下北宫。
自笑苦无楼护智，可怜铅椠竟何功。','',''),('quantangshi-28284','长安杂题长句六首 三','杜牧','quantangshi','','卷29','雨晴九陌铺江练，岚嫩千峰叠海涛。
南苑草芳眠锦雉，夹城云暖下霓旄。
少年羁络青纹玉，游女花簪紫蒂桃。
江碧柳深人尽醉，一瓢颜巷日空高。','',''),('quantangshi-28285','长安杂题长句六首 四','杜牧','quantangshi','','卷29','束带谬趋文石陛，有章曾拜皂囊封。
期严无奈睡留癖，势窘犹为酒泥慵。
偷钓侯家池上雨，醉吟隋寺日沈钟。
九原可作吾谁与，师友琅琊邴曼容。','',''),('quantangshi-28286','长安杂题长句六首 五','杜牧','quantangshi','','卷29','洪河清渭天池浚，太白终南地轴横。
祥云辉映汉宫紫，春光绣画秦川明。
草妬佳人钿朵色，风回公子玉衔声。
六飞南幸芙蓉苑，十里飘香入夹城。','',''),('quantangshi-28287','长安杂题长句六首 六','杜牧','quantangshi','','卷29','丰貂长组金张辈，驷马文衣许史家。
白鹿原头回猎骑，紫云楼下醉江花。
九重树影连清汉，万寿山光学翠华。
谁识大君谦让德，一毫名利鬬鼃蟇。','',''),('quantangshi-28288','河湟','杜牧','quantangshi','','卷29','元载相公曾借箸，宪宗皇帝亦留神。
旋见衣冠就东市，忽遗弓劒不西巡。
牧羊驱马虽戎服，白发丹心尽汉臣。
唯有凉州歌舞曲，流传天下乐闲人。','',''),('quantangshi-28289','许七侍御弃官东归潇洒江南颇闻自适高秋企望题诗寄赠十韵','杜牧','quantangshi','','卷29','天子绣衣吏，东吴美退居。
有园同庾信，避事学相如。
兰畹晴香嫩，筠溪翠影疎。
江山九秋后，风月六朝余。
锦帙开诗轴，青囊结道书。
霜岩红薜荔，露沼白芙蕖。
睡雨高梧密，棊灯小阁虚。
冻醪元亮秫，寒鲙季鹰鱼。
尘意迷今古，云情识卷舒。
他年雪中棹，阳羡访吾庐。','',''),('quantangshi-28290','李给事中敏二首 一','杜牧','quantangshi','','卷29','一章缄拜皂囊中，懔懔朝廷有古风。
元礼去归缑氏学江充来见犬台宫。
纷纭白昼惊千古，鈇锧朱殷几一空。
曲突徙薪人不会，海边今作钓鱼翁。','',''),('quantangshi-28291','李给事中敏二首 二','杜牧','quantangshi','','卷29','晚髪闷还梳，忆君秋醉余。
可怜刘校尉，曾讼石中书。
消长虽殊事，仁贤每自如。','',''),('quantangshi-28292','题永崇西平王宅太尉愬院六韵','杜牧','quantangshi','','卷29','天下无双将，关西第一雄。
授符黄石老，学劒白猿翁。
矫矫云长勇，恂恂郄縠风。
家呼小太尉，国号大梁公。
半夜龙骧去，中原虎穴空。
陇山兵十万，嗣子握雕弓。','',''),('quantangshi-28293','东兵长句十韵','杜牧','quantangshi','','卷29','上党争为天下脊，邯郸四十万秦坑。
狂童何者欲专地，圣主无私岂翫兵。
玄象森罗摇北落，诗人章句咏东征。
雄如马武皆弹劒，少似终军亦请缨。
屈指庙堂无失策，垂衣尧舜待升平。
羽林东下雷霆怒，楚甲南来组练明。
即墨龙文光照曜，常山蛇阵势纵横。
落雕都尉万人敌，黑矟将军一鸟轻。
渐见长围云欲合，可怜穷垒带犹萦。
凯歌应是新年唱，便逐春风浩浩声。','',''),('quantangshi-28294','过勤政楼','杜牧','quantangshi','','卷29','千秋令节名空在，承露丝囊世已无。
唯有紫苔偏得意，年年因雨上金铺。','',''),('quantangshi-28295','过魏文贞公宅','杜牧','quantangshi','','卷29','蟪蛄宁与雪霜期，贤哲难教俗士知。
可怜贞观太平后，天且不留封德彝。','',''),('quantangshi-28296','早春阁下寓直萧九舍人亦直内署因寄书怀四韵','杜牧','quantangshi','','卷29','御水初销冻，宫花尚怯寒。
千峰横紫翠，双阙凭阑干。
玉漏轻风顺，金茎淡日残。
王乔在何处，清汉正骖鸾。','',''),('quantangshi-28297','秋晚与沈十七舍人期游樊川不至','杜牧','quantangshi','','卷29','邀侣以官解，泛然成独游。
川光初媚日，山色正矜秋。
野竹疎还密，岩泉咽复流。
杜村连潏水，晚步见垂钩。','',''),('quantangshi-28298','念昔游三首 一','杜牧','quantangshi','','卷29','十载飘然绳检外，罇前自献自为酬。
秋山春雨闲吟处，倚徧江南寺寺楼。','',''),('quantangshi-28299','念昔游三首 二','杜牧','quantangshi','','卷29','云门寺外逢猛雨，林黑山高雨脚长。
曾奉郊宫为近侍，分明羽林枪。','',''),('quantangshi-28300','念昔游三首 三','杜牧','quantangshi','','卷29','李白题诗水西寺，古木回岩楼阁风。
半醒半醉游三日，红白花开山雨中。','',''),('quantangshi-28301','今皇帝陛下一诏征兵不日功集河湟诸郡次第归降臣获覩圣功辄献歌咏','杜牧','quantangshi','','卷29','捷书皆应睿谋期，十万曾无一镞遗。
汉武慙夸朔方地，周宣休道太原师。
威加塞外寒来早，恩入河源冻合迟。
听取满城歌舞曲，凉州声韵喜参差。','',''),('quantangshi-28302','奉和白相公圣德和平致兹休运岁终功就合咏盛明呈上三相公长句四韵','杜牧','quantangshi','','卷29','行看腊破好年光，万寿南山对未央。
黠戛可汗修职贡，文思天子复河湟。
应须日驭西巡狩，不假星弧北射狼。
吉甫裁诗歌盛业，一篇江汉美宣王。','',''),('quantangshi-28303','过华清宫绝句三首 一','杜牧','quantangshi','','卷29','长安回望绣成堆，山顶千门次第开。
一骑红尘妃子笑，无人知是荔枝来。','',''),('quantangshi-28304','过华清宫绝句三首 二','杜牧','quantangshi','','卷29','新丰绿树起黄埃，数骑渔阳探使回。
霓裳一曲千峰上，舞破中原始下来。','',''),('quantangshi-28305','过华清宫绝句三首 三','杜牧','quantangshi','','卷29','万国笙歌醉太平，倚天楼殿月分明。
云中乱拍禄山舞，风过重峦下笑声。','',''),('quantangshi-28306','登乐游原','杜牧','quantangshi','','卷29','长空澹澹孤鸟没，万古销沈向此中。
看取汉家何事业，五陵无树起秋风。','',''),('quantangshi-28307','闻庆州赵纵使君与党项战中箭身死辄书长句','杜牧','quantangshi','','卷29','将军独乘铁骢马，榆溪战中金仆姑。
死绥却是古来有，骁将自惊今日无。
青史文章争点笔，朱门歌舞笑捐躯。
谁知我亦轻生者，不得君王丈二殳。','',''),('quantangshi-28308','送容州唐中丞赴镇','杜牧','quantangshi','','卷29','交址同星座，龙泉佩斗文。
烧香翠羽帐，看舞郁金裙。
鷁首冲泷浪，犀渠拂岭云。
莫教铜柱北，空说马将军。','',''),('quantangshi-28309','夏州崔常侍自少常亚列出领麾幢十韵','杜牧','quantangshi','','卷29','帝命诗书将，登坛礼乐卿。
三边要高枕，万里得长城。
对客犹褒博，填门已斾旌。
腰间五绶贵，天下一家荣。
野水差新燕，芳郊哢夏莺。
别风嘶玉勒，残日望金茎。
榆塞孤烟媚，银川绿草明。
戈矛虓虎士，弓箭落雕兵。
魏绛言堪采，陈汤事偶成。
若须垂竹帛，静胜是功名。','',''),('quantangshi-28310','街西长句','杜牧','quantangshi','','卷29','碧池新涨浴娇鸦，分鏁长安富贵家。
游骑偶同人鬬酒，名园相倚杏交花。
银秋騕褭嘶宛马，绣鞅璁珑走钿车。
一曲将军何处笛，连云芳草日初斜。','',''),('quantangshi-28311','春申君','杜牧','quantangshi','','卷29','烈士思酬国士恩，春申谁与快冤魂。
三千宾客总珠履，欲使何人杀李园。','',''),('quantangshi-28312','奉陵宫人','杜牧','quantangshi','','卷29','相如死后无词客，延寿亡来绝画工。
玉颜不是黄金少，泪滴秋山入寿宫。','',''),('quantangshi-28313','读韩杜集','杜牧','quantangshi','','卷29','杜诗韩集愁来读，似倩麻姑痒处抓。
天外凤凰谁得髓，无人解合续弦胶。','',''),('quantangshi-28314','春日言怀寄虢州李常侍十韵','杜牧','quantangshi','','卷29','岸藓生红药，岩泉涨碧塘。
地分莲岳秀，草接鼎原芳。
雨派潀漴急，风畦芷若香。
织蓬眠舴艋，惊梦起鸳鸯。
论吐开冰室，诗陈曝锦张。
貂簪荆玉润，丹穴凤毛光。
今日还珠守，何年执戟郎。
且嫌游昼短，莫问积薪长。
无计披清裁，唯持祝寿觞。
愿公如卫武，百岁尚康强。','',''),('quantangshi-28315','李侍郎于阳羡里富有泉石牧亦于阳羡粗有薄产叙旧述怀因献长句四韵','杜牧','quantangshi','','卷29','冥鸿不下非无意，塞马归来是偶然。
紫绶公卿今放旷，白头郎吏尚留连。
终南山下抛泉洞，阳羡溪中买钓船。
欲与明公操履杖，愿闻休去是何年。','',''),('quantangshi-28316','赠李处士长句四韵','杜牧','quantangshi','','卷29','玉函怪牒锁灵篆，紫洞香风吹碧桃。
老翁四目牙爪利，掷火万里精神高。
霭霭祥云随步武，累累秋冢叹蓬蒿。
三山朝去应非久，姹女当窗绣羽袍。','',''),('quantangshi-28317','送国棊王逢','杜牧','quantangshi','','卷29','玉子纹楸一路饶，最宜檐雨竹萧萧。
羸形暗去春泉长，拔势横来野火烧。
守道还如周柱史，鏖兵不羡霍嫖姚。
浮生七十更万日，与子期于局上销。','',''),('quantangshi-28318','重送绝句','杜牧','quantangshi','','卷29','绝艺如君天下少，闲人似我世间无。
别后竹窓风雪夜，一灯明暗覆吴图。','',''),('quantangshi-28319','少年行','杜牧','quantangshi','','卷29','连环羁玉声光碎，绿锦蔽泥虬卷高。
春风细雨走马去，珠落璀璀白罽袍。','',''),('quantangshi-28320','奉和门下相公送西川相公兼领相印出镇全蜀诗十八韵','杜牧','quantangshi','','卷29','盛业冠伊唐，台阶翊戴光。
无私天雨露，有截舜衣裳。
蜀辍新衡镜，池留旧凤凰。
同心真石友，写恨蔑河梁。
虎骑摇风斾，貂冠韵水苍。
彤弓随武库，金印逐文房。
栈压嘉陵咽，峰横劒阁长。
前驱二星去，开险五丁忙。
回首峥嵘尽，连天草树芳。
丹心悬魏阙，往事怆甘棠。
治化轻诸葛，威声慑夜郎。
君平教说卦，夫子召升堂。
塞接西山雪，桥维万里樯。
夺霞红锦烂，扑地酒垆香。
忝逐三千客，曾依数仞墙。
滞顽堪白屋，攀附亦同行。
肉管伶伦曲，箫韶清庙章。
唱高知和寡，小子斐然狂。','',''),('quantangshi-28321','朱坡','杜牧','quantangshi','','卷29','下杜乡园古，泉声绕舍啼。
静思长惨切，薄宦与乖暌。
北阙千门外，南山午谷西。
倚川红叶岭，连寺绿杨堤。
迥野翘霜鹤，澄潭舞锦鸡。
涛惊堆万岫，舸急转千溪。
眉点萱牙嫩，风条柳幄迷。
岸藤梢虺尾，沙渚印麑蹄。
火燎湘桃坞，波光碧绣畦。
日痕絙翠巘，陂影堕晴霓。
蜗壁斓斑藓，银筵豆蔻泥。
洞云生片段，苔径缭高低。
偃蹇松公老，森严竹阵齐。
小莲娃欲语，幽笋稚相携。
汉馆留余趾，周台接故蹊。
蟠蛟冈隐隐，班雉草萋萋。
树老萝纡组，岩深石启闺。
侵窓紫桂茂，拂面翠禽栖。
有计冠终挂，无才笔谩提。
自尘何太甚，休笑触藩羝。','',''),('quantangshi-28322','早春寄岳州李使君李善棊爱酒情地闲雅','杜牧','quantangshi','','卷29','城高倚峭巘，地胜足楼台。
朔漠暖鸿去，潇湘春水来。
萦盈几多思，掩抑若为裁。
返照三声角，寒香一树梅。
乌林芳草远，赤壁健帆开。
往事空遗恨，东流岂不回。
分符颍川政，吊屈洛阳才。
拂匣调珠柱，磨铅勘玉杯。
棊翻小窟势，垆拨冻醪醅。','',''),('quantangshi-28323','送王侍御赴夏口座主幕','杜牧','quantangshi','','卷29','君为珠履三千客，我是青衿七十徒。
礼数全优知隗始，讨论常见念回愚。
黄鹤楼前春水阔，一杯还忆故人无。','',''),('quantangshi-28324','自贻','杜牧','quantangshi','','卷29','杜陵萧次君，迁少去官频。
寂寞怜吾道，依稀似古人。
餙心无彩缋，到骨是风尘。
自嫌如匹素，刀尺不由身。','',''),('quantangshi-28325','自遣','杜牧','quantangshi','','卷29','四十已云老，况逢忧窘余。
且抽持板手，却展小年书。
嗜酒狂嫌阮，知非晚笑蘧。
闻流宁叹吒，待俗不亲疎。
遇事知裁剪，操心识卷舒。
还称二千石，于我意何如。','',''),('quantangshi-28326','题桐叶','杜牧','quantangshi','','卷29','去年桐落故溪上，把笔偶题归燕诗。
江楼今日送归燕，正是去年题叶时。
叶落燕归真可惜，东流玄髪且无期。
笑筵歌席反惆怅，明月清风怆别离。
庄叟彭殇同在梦，陶潜身世两相遗。
一丸五色成虚语，石烂松薪更莫疑。
哆侈不劳文似锦，进趋何必利如锥。
钱神任尔知无敌，酒圣于吾亦庶几。
江畔秋光蟾阁镜，槛前山翠茂陵眉。
樽香轻泛数枝菊，檐影斜侵半局棊。
休指宦游论巧拙，秪将愚直祷神只。
三吴烟水平生念，宁向闲人道所之。','',''),('quantangshi-28327','沈下贤','杜牧','quantangshi','','卷29','斯人清唱何人和，草径苔芜不可寻。
一夕小敷山下梦，水如环佩月如襟。','',''),('quantangshi-28328','李和鼎','杜牧','quantangshi','','卷29','鵩鸟飞来庚子直，谪去日蚀辛卯年。
由来枉死贤才事，消长相持势自然。','',''),('quantangshi-28329','赠沈学士张歌人','杜牧','quantangshi','','卷29','拖袖事当年，郎教唱客前。
断时轻裂玉，收处远缲烟。
孤直縆云定，光明滴水圆。
泥情迟急管，流恨咽长弦。
吴苑春风起，河桥酒斾悬。
凭君更一醉，家在杜陵边。','',''),('quantangshi-28330','忆游朱坡四韵','杜牧','quantangshi','','卷29','秋草樊川路，斜阳覆盎门。
猎逢韩嫣骑，树识馆陶园。
带雨经荷沼，盘烟下竹村。
如今归不得，自戴望天盆。','',''),('quantangshi-28331','朱坡绝句三首 一','杜牧','quantangshi','','卷29','故国池塘倚御渠，江城三诏换鱼书。
贾生辞赋恨流落，秪向长沙住岁余。','',''),('quantangshi-28332','朱坡绝句三首 二','杜牧','quantangshi','','卷29','烟深苔巷唱樵儿，花落寒轻倦客归。
藤岸竹洲相掩映，满池春雨䴙鹈飞。','',''),('quantangshi-28333','朱坡绝句三首 三','杜牧','quantangshi','','卷29','乳肥春洞生鹅管，沼避回岩势犬牙。
自笑卷怀头角缩，归盘烟磴恰如蜗。','',''),('quantangshi-28334','出宫人二首 一','杜牧','quantangshi','','卷29','闲吹玉殿昭华管，醉折梨园缥蔕花。
十年一梦归人世，绛缕犹封系臂纱。','',''),('quantangshi-28335','出宫人二首 二','杜牧','quantangshi','','卷29','平阳拊背穿驰道，铜雀分香下璧门。
几向缀珠深殿里，妬抛羞态卧黄昏。','',''),('quantangshi-28336','长安秋望','杜牧','quantangshi','','卷29','楼倚霜树外，镜天无一毫。
南山与秋色，气势两相高。','',''),('quantangshi-28337','独酌','杜牧','quantangshi','','卷29','窓外正风雪，拥炉开酒缸。
何如钓船雨，蓬底睡秋江。','',''),('quantangshi-28338','醉眠','杜牧','quantangshi','','卷29','秋醪雨中熟，寒斋落叶中。
幽人本多睡，更酌一樽空。','',''),('quantangshi-28339','不饮赠酒','杜牧','quantangshi','','卷29','细算人生事，彭殇共一筹。
与愁争底事，要尔作戈矛。','',''),('quantangshi-28340','昔事文皇帝三十二韵','杜牧','quantangshi','','卷29','昔事文皇帝，叨官在谏垣。
奏章为得地，齚齿负明恩。
金虎知难动，毛厘亦耻言。
掩头虽欲吐，到口却成吞。
照胆常悬镜，窥天自戴盆。
周钟既窕槬，黥阵亦瘢痕。
凤阙觚棱影，仙盘晓日暾。
雨晴文石滑，风暖戟衣翻。
每虑号无告，长忧骇不存。
随行唯局蹐，出语但寒暄。
宫省咽喉任，戈矛羽卫屯。
光尘皆影附，车马定西奔。
亿万持衡价，锱铢挟契论。
堆时过北斗，积处满西园。
接棹隋河溢，连蹄蜀栈刓。
漉空沧海水，搜尽卓王孙。
鬬巧猴雕刺，夸趫索挂跟。
狐威假白额，枭啸得黄昏。
馥馥芝兰圃，森森枳棘藩。
吠声嗾国猘，公议怯膺门。
窜逐诸丞相，苍茫远帝阍。
一名为吉士，谁免吊湘魂。
间世英明主，中兴道德尊。
昆冈怜积火，河汉注清源。
川口堤防决，阴车鬼怪掀。
重云开朗照，九地雪幽冤。
我实刚肠者，形甘短褐髠。
曾经触虿尾，犹得凭熊轩。
杜若芳洲翠，严光钓濑喧。
溪山侵越角，封壤尽吴根。
客恨萦春细，乡愁压思繁。
祝尧千万寿，再拜揖余罇。','',''),('quantangshi-28341','道一大尹存之庭美二学士简于圣明自致霄汉皆与舍弟昔年还往牧支离穷悴窃于一麾书美歌诗兼自言志因成长句四韵呈上三君子','杜牧','quantangshi','','卷29','九金神鼎重丘山，五玉诸侯杂佩环。
星座通霄狼鬣暗，戍楼吹笛虎牙闲。
斗间紫气龙埋狱，天上洪炉帝铸颜。
若念西河旧交友，鱼符应许出函关。','',''),('quantangshi-28342','杏园','杜牧','quantangshi','','卷29','夜来微雨洗芳尘，公子骅骝步贴匀。
莫怪杏园顦顇去，满城多少插花人。','',''),('quantangshi-28343','春晚题韦家亭子','杜牧','quantangshi','','卷29','拥鼻侵襟花草香，高台春去恨茫茫。
蔫红半落平池晚，曲渚飘成锦一张。','',''),('quantangshi-28344','过田家宅','杜牧','quantangshi','','卷29','安邑南门外，谁家板筑高。
奉诚园里地，墙缺见蓬蒿。','',''),('quantangshi-28345','见宋拾遗题名处感而成诗','杜牧','quantangshi','','卷29','窜逐穷荒与死期，饿唯蒿藿病无医。
怜君更抱重泉恨，不见崇山谪去时。','',''),('quantangshi-28346','雪晴访赵嘏街西所居三韵','杜牧','quantangshi','','卷29','命代风骚将，谁登李杜坛。
少陵鲸海动，翰苑鹤天寒。
今日访君还有意，三条冰雪独来看。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-28347','将赴吴兴登乐游原一绝','杜牧','quantangshi','','卷29','清时有味是无能，闲爱孤云静爱僧。
欲把一麾江海去，乐游原上望昭陵。','',''),('quantangshi-28348','洛阳长句二首 一','杜牧','quantangshi','','卷29','草色人心相与闲，是非名利有无间。
桥横落照虹堪画，树锁千门鸟自还。
芝盖不来云杳杳，仙舟何处水潺潺？
君王谦让泥金事，苍翠空高万岁山。','',''),('quantangshi-28349','洛阳长句二首 二','杜牧','quantangshi','','卷29','天汉东穿白玉京，日华浮动翠光生。
桥边游女佩环委，波底上阳金碧明。
月锁名园孤鹤唳，川酣秋梦凿龙声。','',''),('quantangshi-28350','洛中监察病假满送韦楚老拾遗归朝','杜牧','quantangshi','','卷29','洛桥风暖细翻衣，春引仙官去玉墀。
独鹤初冲太虚日，九牛新落一毛时。
行开教化期君是，卧病神只祷我知。
十载丈夫堪耻处，朱云犹掉直言旗。','',''),('quantangshi-28351','东都送郑处诲校书归上都','杜牧','quantangshi','','卷29','悠悠渠水清，雨霁洛阳城。
槿堕初开艳，蝉闻第一声。
故人容易去，白发等闲生。
此别无多语，期君晦盛名。','',''),('quantangshi-28352','故洛阳城有感','杜牧','quantangshi','','卷29','一片宫墙当道危，行人为尔去迟迟。
筚圭苑里秋风后，平乐馆前斜日时。
锢党岂能留汉鼎，清谈空解识胡儿。
千烧万战坤灵死，惨惨终年鸟雀悲。','',''),('quantangshi-28353','扬州三首 一','杜牧','quantangshi','','卷29','炀帝雷塘土，迷藏有旧楼。
谁家唱水调，明月满扬州。
骏马宜闲出，千金好旧游。
喧阗醉年少，半脱紫茸裘。','',''),('quantangshi-28354','扬州三首 二','杜牧','quantangshi','','卷29','秋风放萤苑，春草鬬鸡台。
金络擎雕去，鸾环拾翠来。
蜀船红锦重，越橐水沈堆。
处处皆华表，淮王奈却回。','',''),('quantangshi-28355','扬州三首 三','杜牧','quantangshi','','卷29','街垂千步柳，霞映两重城。
天碧台阁丽，风凉歌管清。
纤腰间长袖，玉佩杂繁缨。
拖轴诚为壮，豪华不可名。
自是荒淫罪何妨作帝京。','',''),('quantangshi-28356','润州二首 一','杜牧','quantangshi','','卷29','句吴亭东千里秋，放歌曾作昔年游。
青苔寺里无马迹，绿水桥边多酒楼。
大抵南朝皆旷达，可怜东晋最风流。
月明更想桓伊在，一笛闻吹出塞愁。','',''),('quantangshi-28357','润州二首 二','杜牧','quantangshi','','卷29','谢眺诗中佳丽地，夫差传里水犀军。
城高铁瓮横强弩，柳暗朱楼多梦云。
画角爱飘江北去，钓歌长向月中闻。
扬州尘土试回首，不惜千金借与君。','',''),('quantangshi-28358','题扬州禅智寺','杜牧','quantangshi','','卷29','雨过一蝉噪，飘萧松桂秋。
青苔满阶砌，白鸟故迟留。
暮霭生深树，斜阳下小楼。
谁知竹西路，歌吹是扬州。','',''),('quantangshi-28359','西江怀古','杜牧','quantangshi','','卷29','上吞巴汉控潇湘，怒似连山净镜光。
魏帝缝囊真戏剧，苻坚投棰更荒唐。
千秋钓艇歌明月，万里沙鸥弄夕阳。
范蠡清尘何寂寞，好风唯属往来商。','',''),('quantangshi-28360','江南怀古','杜牧','quantangshi','','卷29','车书混一业无穷，井邑山川今古同。
戊辰年向金陵过，惆怅闲吟忆庾公。','',''),('quantangshi-28361','江南春绝句','杜牧','quantangshi','','卷29','千里莺啼绿映江，水村山郭酒旗风。
南朝四百八十寺，多少楼台烟雨中。','',''),('quantangshi-28362','将赴宣州留题扬州禅智寺','杜牧','quantangshi','','卷29','故里溪头松柏双，来时尽日倚松窓。
杜陵隋苑已绝国，秋晚南游更渡江。','',''),('quantangshi-28363','题宣州开元寺水阁阁下宛溪夹溪居人','杜牧','quantangshi','','卷29','六朝文物草连空，天淡云闲今古同。
鸟去鸟来山色里，人歌人哭水声中。
深秋帘幕千家雨，落日楼台一笛风。
惆怅无因见范蠡，参差烟树五湖东。','',''),('quantangshi-28364','宣州送裴坦判官往舒州时牧欲赴官归京','杜牧','quantangshi','','卷29','日暖泥融雪半销，行人芳草马声骄。
九华山路云遮寺，清弋江村柳拂桥。
君意如鸿高的的，我心悬斾正摇摇。
同来不得同归去，故国逢春一寂寥。','',''),('quantangshi-28365','句溪夏日送卢霈秀才归王屋山将欲赴举','杜牧','quantangshi','','卷29','野店正纷泊，茧蚕初引丝。
行人碧溪渡，系马绿杨枝。
苒苒迹始去，悠悠心所期。
秋山念君别，惆怅桂花时。','',''),('quantangshi-28366','自宣城赴官上京','杜牧','quantangshi','','卷29','潇洒江湖十过秋，酒杯无日不淹留。
谢公城畔溪惊梦，苏小门前柳拂头。
千里云山何处好，几人襟韵一生休。
尘冠挂却知闲事，终拟蹉跎访旧游。','',''),('quantangshi-28367','春末题池州弄水亭','杜牧','quantangshi','','卷29','使君四十四，两佩左铜鱼。
为吏非循吏，论书读底书。
晚花红艳静，高树绿阴初。
亭宇清无比，溪山画不如。
嘉宾能啸咏，宫妓巧妆梳。
逐日愁皆碎，随时醉有余。
偃须求五鼎，陶秪爱吾庐。
趣向人皆异，贤豪莫笑渠。','',''),('quantangshi-28368','登池州九峰楼寄张祜','杜牧','quantangshi','','卷29','百感中来不自由，角声孤起夕阳楼。
碧山终日思无尽，芳草何年恨即休。
睫在眼前长不见，道非身外更何求。
谁人得似张公子，千首诗轻万户侯。','',''),('quantangshi-28369','齐安郡晚秋','杜牧','quantangshi','','卷29','柳岸风来影渐疎，使君家似野人居。
云容水态还堪赏，啸志歌怀亦自如。
雨暗残灯碁散后，酒醒孤枕雁来初。
可怜赤壁争雄渡，唯有蓑翁坐钓鱼。','',''),('quantangshi-28370','九日齐安登高','杜牧','quantangshi','','卷29','江涵秋影雁初飞，与客携壶上翠微。
尘世难逢开口笑，菊花须插满头归。
但将酩酊酬佳节，不用登临叹落晖。
古往今来只如此，牛山何必泪霑衣。','',''),('quantangshi-28371','池州春送前进士蒯希逸','杜牧','quantangshi','','卷29','芳草复芳草，断肠还断肠。
自然堪下泪，何必更残阳。
楚岸千万里，燕鸿三两行。
有家归不得，况举别君觞。','',''),('quantangshi-28372','齐安郡中偶题二首 一','杜牧','quantangshi','','卷29','两竿落日溪桥上，半缕轻烟柳影中。
多少绿荷相倚恨，一时回首背西风。','',''),('quantangshi-28373','齐安郡中偶题二首 二','杜牧','quantangshi','','卷29','秋声无不搅离心，梦泽蒹葭楚雨深。
自滴阶前大梧叶，干君何事动哀吟。','',''),('quantangshi-28374','齐安郡后池绝句','杜牧','quantangshi','','卷29','菱透浮萍绿锦池，夏莺千啭弄蔷薇。
尽日无人看微雨，鸳鸯相对浴红衣。','',''),('quantangshi-28375','题齐安城楼','杜牧','quantangshi','','卷29','呜咽江楼角一声，微阳潋潋落寒汀。
不用凭阑苦回首，故乡七十五长亭。','',''),('quantangshi-28376','池州李使君没后十一日处州新命始到后见归妓感而成诗','杜牧','quantangshi','','卷29','缙云新命诏初行，才是孤魂寿器成。
黄壤不知新雨露，粉书空换旧铭旌。
巨卿哭处云空断，阿骛归来月正明。
多少四年遗爱事，乡闾生子李为名。','',''),('quantangshi-28377','见刘秀才与池州妓别','杜牧','quantangshi','','卷29','远风南浦万重波，未似生离别恨多。
楚管能吹柳花怨，吴姬争唱竹枝歌。
金钗横处绿云堕，玉筯凝时红粉和。
待得枚臯相见日，自应妆镜笑蹉跎。','',''),('quantangshi-28378','池州废林泉寺','杜牧','quantangshi','','卷29','废寺林溪上，颓垣倚乱峰。
看栖归树鸟，犹想过山钟。
石路寻僧去，此生应不逢。','',''),('quantangshi-28379','忆齐安郡','杜牧','quantangshi','','卷29','平生睡足处，云梦泽南州。
一夜风欺竹，连江雨送秋。
格卑常汩汩，力学强悠悠。
终掉尘中手，潇湘钓漫流。','',''),('quantangshi-28380','池州清溪','杜牧','quantangshi','','卷29','弄溪终日到黄昏，照数秋来白发根。
何物赖君千遍洗，笔头尘土渐无痕。','',''),('quantangshi-28381','游池州林泉寺金碧洞','杜牧','quantangshi','','卷29','袖拂霜林下石棱，潺湲声断满溪冰。
携茶腊月游金碧，合有文章病茂陵。','',''),('quantangshi-28382','即事','杜牧','quantangshi','','卷29','因思上党三年战，闲咏周公七月诗。
竹帛未闻书死节，丹青空见画灵旗。
萧条井邑如鱼尾，早晚干戈识虎皮。
莫笑一麾东下计，满江秋浪碧参差。','',''),('quantangshi-28383','赠李秀才','杜牧','quantangshi','','卷29','骨清年少眼如冰，凤羽参差五色层。
天上麒麟时一下，人间不独有徐陵。','',''),('quantangshi-28384','寄李起居四韵','杜牧','quantangshi','','卷29','楚女梅簪白雪姿，前溪碧水冻醪时。
云罍心凸知难捧，凤管簧寒不受吹。
南国劒眸能盼眄，侍臣香袖爱僛垂。
自怜穷律穷途客，正怯孤灯一局碁。','',''),('quantangshi-28385','题池州贵池亭','杜牧','quantangshi','','卷29','势比凌歊宋武台，分明百里远帆开。
蜀江雪浪西江满，强半春寒去却来。','',''),('quantangshi-28386','兰溪','杜牧','quantangshi','','卷29','兰溪春尽碧泱泱，映水兰花雨发香。
楚国大夫憔悴日，应寻此路去潇湘。','',''),('quantangshi-28387','睦州四韵','杜牧','quantangshi','','卷29','州在钓台边，溪山实可怜。
有家皆掩映，无处不潺湲。
好树鸣幽鸟，晴楼入野烟。
残春杜陵客，中酒落花前。','',''),('quantangshi-28388','秋晚早发新定','杜牧','quantangshi','','卷29','解印书千轴，重阳酒百缸。
凉风满红树，晓月下秋江。
岩壑会归去，尘埃终不降。
悬缨未敢濯，严濑碧淙淙。','',''),('quantangshi-28389','除官归京睦州雨霁','杜牧','quantangshi','','卷29','秋半吴天霁，清凝万里光。
水声侵笑语，岚翠扑衣裳。
远树疑罗帐，孤云认粉囊。
溪山侵两越，时节到重阳。
顾我能甘贱，无由得自强。
悮曾公触尾，不敢夜循墙。
岂意笼飞鸟，还为锦帐郎。
网今开傅燮，书旧识黄香。
姹女真虚语，饥儿欲一行。
浅深须揭厉，休更学张纲。','',''),('quantangshi-28390','夜泊桐庐先寄苏台卢郎中','杜牧','quantangshi','','卷29','水槛桐庐馆，归舟系石根。
笛吹孤戌月，犬吠隔溪村。
十载违清裁，幽怀未一论。','',''),('quantangshi-28391','新转南曹未叙朝散初秋暑退出守吴兴书此篇以自见志','杜牧','quantangshi','','卷29','捧诏汀洲去，全家羽翼飞。
喜抛新锦帐，荣借旧朱衣。
且免材为累，何妨拙有机。
宋株聊自守，鲁酒怕旁围。
清尚宁无素，光阴亦未曦。
一杯宽幕席，五字弄珠玑。
越浦黄柑嫩，吴溪紫蟹肥。
平生江海志，佩得左鱼归。','',''),('quantangshi-28392','题白苹洲','杜牧','quantangshi','','卷29','山鸟飞红带，亭薇拆紫花。
溪光初透彻，秋色正清华。
静处知生乐，喧中见死夸。
无多圭组累，终不负烟霞。','',''),('quantangshi-28393','题茶山','杜牧','quantangshi','','卷29','山实东吴秀，茶称瑞草魁。
剖符虽俗吏，修贡亦仙才。
溪尽停蛮棹，旗张卓翠苔。
柳村穿窈窕，松涧渡喧豗。
等级云峰峻，宽平洞府开。
拂天闻笑语，特地见楼台。
泉嫩黄金涌，牙香紫璧裁。
拜章期沃日，轻骑疾奔雷。
舞袖岚侵涧，歌声谷答回。
磬音藏叶鸟，雪艳照潭梅。
好是全家到，兼为奉诏来。
树阴香作帐，花径落成堆。
景物残三月，登临怆一杯。
重游难自尅，俛首入尘埃。','',''),('quantangshi-28394','茶山下作','杜牧','quantangshi','','卷29','春风最窈窕，日晓柳村西。
娇云光占岫，健水鸣分溪。
燎岩野花远，戛瑟幽鸟啼。
把酒坐芳草，亦有佳人携。','',''),('quantangshi-28395','入茶山下题水口草市绝句','杜牧','quantangshi','','卷29','倚溪侵岭多高树，夸酒书旗有小楼。
惊起鸳鸯岂无恨，一双飞去却回头。','',''),('quantangshi-28396','春日茶山病不饮酒因呈宾客','杜牧','quantangshi','','卷29','笙歌登画船，十日清明前。
山秀白云腻，溪光红粉鲜。
欲开未开花，半阴半晴天。
谁知病太守，犹得作茶仙。','',''),('quantangshi-28397','不饮赠官妓','杜牧','quantangshi','','卷29','芳草正得意，汀洲日欲西。
无端千树柳，更拂一条溪。
几朵梅堪折，何人手好携。
谁怜佳丽地，春恨却凄凄。','',''),('quantangshi-28398','早春赠军事薛判官','杜牧','quantangshi','','卷29','雪后新正半，春来四刻长。
晴梅朱粉艳，嫩水碧罗光。
弦管开双调，花钿坐两行。
唯君莫惜醉，认取少年场。','',''),('quantangshi-28399','代吴兴妓春初寄薛军事','杜牧','quantangshi','','卷29','雾冷侵红粉，春阴扑翠钿。
自悲临晓镜，谁与惜流年。
柳暗霏微雨，花愁黯淡天。
金钗有几只，抽当酒家钱。','',''),('quantangshi-28400','八月十二日得替后移居霅溪馆因题长句四韵','杜牧','quantangshi','','卷29','万家相庆喜秋成，处处楼台歌板声。
千岁鹤归犹有恨，一年人住岂无情。
夜凉溪馆留僧话，风定苏潭看月生。
景物登临闲始见，愿为闲客此闲行。','',''),('quantangshi-28401','初冬夜饮','杜牧','quantangshi','','卷29','淮阳多病偶求欢，客袖侵霜与烛盘。
砌下梨花一堆雪，明年谁此凭阑干。','',''),('quantangshi-28402','栽竹','杜牧','quantangshi','','卷29','本因遮日种，却似为溪移。
历历羽林影，疎疎烟露姿。
萧骚寒雨夜，敲劼晚风时。
故国何年到，尘冠挂一枝。','',''),('quantangshi-28403','梅','杜牧','quantangshi','','卷29','轻盈照溪水，掩敛下瑶台。
妬雪聊相比，欺春不逐来。
偶同佳客见，似为冻醪开。
若在秦楼畔，堪为弄玉媒。','',''),('quantangshi-28404','山石榴','杜牧','quantangshi','','卷29','似火山榴映小山，繁中能薄艳中闲。
一朵佳人玉钗上，秪疑烧却翠云鬟。','',''),('quantangshi-28405','柳长句','杜牧','quantangshi','','卷29','日落水流西复东，春光不尽柳何穷。
巫娥庙里低含雨，宋玉宅前斜带风。
不嫌榆荚共争翠，深与桃花相映红。
灞上汉南千万树，几人游宦别离中。','',''),('quantangshi-28406','隋堤柳','杜牧','quantangshi','','卷29','夹岸垂杨三百里，秪应图画最相宜。
自嫌流落西归疾，不见东风二月时。','',''),('quantangshi-28407','柳绝句','杜牧','quantangshi','','卷29','数树新开翠影齐，倚风情态被春迷。
依依故国樊川恨，半掩村桥半掩溪。','',''),('quantangshi-28408','独柳','杜牧','quantangshi','','卷29','含烟一株柳，拂地摇风久。
佳人不忍折，怅望回纤手。','',''),('quantangshi-28409','早雁','杜牧','quantangshi','','卷29','金河秋半虏弦开，云外惊飞四散哀。
仙掌月明孤影过，长门灯暗数声来。
须知胡骑纷纷在，岂逐春风一一回。
莫厌潇湘少人处，水多菰米岸莓苔。','',''),('quantangshi-28410','䴔䴖','杜牧','quantangshi','','卷29','芝茎抽绀趾，清唳掷金梭。
日翅闲张锦，风池去罥罗。
静眠依翠荇，暖戏折高荷。
山阴岂无尔，茧字换羣鹅。','',''),('quantangshi-28411','鹦鹉','杜牧','quantangshi','','卷29','华堂日渐高，雕槛系红绦。
故国陇山树，美人金剪刀。
避笼交翠尾，罅嘴静新毛。
不念三缄事，世途皆尔曹。','',''),('quantangshi-28412','鹤','杜牧','quantangshi','','卷29','清音迎晓月，愁思立寒蒲。
丹顶西施颊，霜毛四皓须。
碧云行止躁，白鹭性灵麤。
