故关何日到，且看小三峰。','',''),('quantangshi-28436','往年随故府吴兴公夜泊芜湖口今赴官西去再宿芜湖感旧伤怀因成十六韵','杜牧','quantangshi','','卷29','南指陵阳路，东流似昔年。
重恩山未答，双鬓雪飘然。
数仞慙投迹，群公愧拍肩。
驽骀蒙锦绣，尘土浴潺湲。
郭隗黄金峻，虞卿白璧鲜。
貔貅环玉帐，鹦鹉破蛮牋。
极浦沈碑会，秋花落帽筵。
旌旗明迥野，冠佩照神仙。
筹画言何补，优容道实全。
讴谣人扑地，鸡犬树连天。
紫凤超如电，青襟散似烟。
苍生未经济，坟草已芊绵。
往事惟沙月，孤灯但客船。
岘山云影畔，棠叶水声前。
故国还归去，浮生亦可怜。
高歌一曲泪，明日夕阳边。','',''),('quantangshi-28437','怀钟陵旧游四首 一','杜牧','quantangshi','','卷29','一谒征南最少年，虞卿双璧截肪鲜。
