两地差池恨，江汀醉送君。','',''),('quantangshi-28465','初春雨中舟次和州横江裴使君见迎李赵二秀才同来因书四韵兼寄江南许浑先辈','杜牧','quantangshi','','卷29','芳草渡头微雨时，万株杨柳拂波垂。
