慷慨匡时畧，从容问罪师。
褒中秋鼓角，渭曲晚旌旗。
仗义悬无敌，鸣攻故有辞。
若非天夺去，岂复虑能支。
子夜星才落，鸿毛鼎便移。
邮亭世自换，白日事长垂。
何处躬耕者，犹题殄瘁诗。','',''),('quantangshi-28481','重题绝句一首','杜牧','quantangshi','','卷29','邮亭寄人世，人世寄邮亭。
何如自筹度，鸿路有冥冥。','',''),('quantangshi-28482','送陆洿郎中弃官东归','杜牧','quantangshi','','卷29','少微星动照春云，魏阙衡门路自分。
倏去忽来应有意，世间尘土谩疑君。','',''),('quantangshi-28483','寄珉笛与宇文舍人','杜牧','quantangshi','','卷29','调高银字声还侧，物比柯亭韵校奇。
寄与玉人天上去，桓将军见不教吹。','',''),('quantangshi-28484','寄内兄和州崔员外十二韵','杜牧','quantangshi','','卷29','历阳崔太守，何日不含情。
恩义同钟李，埙篪实弟兄。
光尘能混合，擘画最分明。
台阁仁贤誉，闺门孝友声。
西方像教毁，南海绣衣行。
金橐宁回顾，珠簟肯一枨。
秪宜裁密诏，何自取专城。
进退无非道，徊翔必有名。
好风初婉软，离思苦萦盈。
金马旧游贵，桐庐春水生。
雨侵寒牖梦，梅引冻醪倾。
共祝中兴主，高歌唱太平。','',''),('quantangshi-28485','遣兴','杜牧','quantangshi','','卷29','镜弄白髭须，如何作老夫。
浮生长勿勿，儿小且呜呜。
忍过事堪喜，泰来忧胜无。
治平心径熟，不遣有穷途。','',''),('quantangshi-28486','早秋','杜牧','quantangshi','','卷29','疎雨洗空旷，秋标惊意新。
大热去酷吏，清风来故人。
尊酒酌未酌，晚花嚬不嚬。
铢秤与缕雪，谁觉老陈陈。','',''),('quantangshi-28487','秋思','杜牧','quantangshi','','卷29','热去解钳釱，飘萧秋半时。
微雨池塘见，好风襟袖知。
髪短梳未足，枕凉闲且欹。
平生分过此，何事不参差。','',''),('quantangshi-28488','途中一绝','杜牧','quantangshi','','卷29','镜中丝髪悲来惯，衣上尘痕拂渐难。
惆怅江湖钓竿手，却遮西日向长安。','',''),('quantangshi-28489','春尽途中','杜牧','quantangshi','','卷29','田园不事来游宦，故国谁教尔别离。
独倚关亭还把酒，一年春尽送春诗。','',''),('quantangshi-28490','题村舍','杜牧','quantangshi','','卷29','三树稚桑春未到，扶床乳女午啼饥。
潜销暗铄归何处，万指侯家自不知。','',''),('quantangshi-28491','代人寄远六言二首 一','杜牧','quantangshi','','卷29','河桥酒斾风软，候馆梅花雪娇。
宛陵楼上瞪目，我郎何处情饶。','',''),('quantangshi-28492','代人寄远六言二首 二','杜牧','quantangshi','','卷29','绣领任垂蓬髻，丁香闲结春梢。
剩肯新年归否，江南绿草迢迢。','',''),('quantangshi-28493','闺情','杜牧','quantangshi','','卷29','娟娟却月眉，新鬓学鵶飞。
暗砌匀檀粉，晴窓画夹衣。
袖红垂寂寞，眉黛歛衣稀。
还向长陵去，今宵归不归。','',''),('quantangshi-28494','旧游','杜牧','quantangshi','','卷29','闲吟芍药诗，惆望久嚬眉。
盼眄回眸远，纤衫整髻迟。
重寻春昼梦，笑把浅花枝。
小市长陵住，非郎谁得知。','',''),('quantangshi-28495','寄远','杜牧','quantangshi','','卷29','只影随惊雁，单栖鏁画笼。
向春罗袖薄，谁念舞台风。','',''),('quantangshi-28496','帘','杜牧','quantangshi','','卷29','徒云逢剪削，岂谓见偏装。
凤节轻雕日，鸾花薄餙香。
问屏何屈曲，怜帐解周防。
下渍金阶露，斜分碧瓦霜。
沈沈伴春梦，寂寂侍华堂。
谁见昭阳殿，真珠十二行。','',''),('quantangshi-28497','寄题甘露寺北轩','杜牧','quantangshi','','卷29','曾向蓬莱宫里行，北轩阑槛最留情。
孤高堪弄桓伊笛，缥缈宜闻子晋笙。
天接海门秋水色，烟笼隋苑暮钟声。
他年会着荷衣去，不向山僧说姓名。','',''),('quantangshi-28498','题青云馆','杜牧','quantangshi','','卷29','虬蟠千仞剧羊肠，天府由来百二强。
四皓有芝轻汉祖，张仪无地与怀王。
云连帐影萝阴合，枕遶泉声客梦凉。
深处会容高尚者，水苗三顷百株桑。','',''),('quantangshi-28499','正初奉酬歙州刺史邢羣','杜牧','quantangshi','','卷29','翠岩千尺倚溪斜，曾得严光作钓家。
越嶂远分丁字水，腊梅迟见二年花。
明时刀尺君须用，幽处田园我有涯。
一壑风烟阳羡里，解龟休去路非赊。','',''),('quantangshi-28500','江上偶见绝句','杜牧','quantangshi','','卷29','楚江寒食橘花时，野渡临风驻彩旗。
草色连云人去住，水纹如縠燕差池。','',''),('quantangshi-28501','题木兰庙','杜牧','quantangshi','','卷29','弯弓征战作男儿，梦里曾经与画眉。
几度思归还把酒，拂云堆上祝明妃。','',''),('quantangshi-28502','入商山','杜牧','quantangshi','','卷29','早入商山百里云，蓝溪桥下水声分。
流水旧声人旧耳，此回呜咽不堪闻。','',''),('quantangshi-28503','偶题','杜牧','quantangshi','','卷29','甘罗昔作秦丞相，子政曾为汉辇郎。
千载更逢王侍读，当时还道有文章。','',''),('quantangshi-28504','送卢秀才一绝','杜牧','quantangshi','','卷29','春濑与烟远，送君孤棹开。
潺湲如不改，愁更钓鱼来。','',''),('quantangshi-28505','醉题','杜牧','quantangshi','','卷29','金镊洗霜鬓，银觥敌露桃。
醉头扶不起，三丈日还高。','',''),('quantangshi-28506','题商山四皓庙一绝','杜牧','quantangshi','','卷29','吕氏强梁嗣子柔，我于天性岂恩讐。
南军不袒左边袖，四老安刘是灭刘。','',''),('quantangshi-28507','送隐者一绝','杜牧','quantangshi','','卷29','无媒径路草萧萧，自古云林远市朝。
公道世间唯白发，贵人头上不曾饶。','',''),('quantangshi-28508','题张处士山庄一绝','杜牧','quantangshi','','卷29','好鸟疑敲磬，风蝉认轧筝。
修篁与嘉树，偏倚半岩生。','',''),('quantangshi-28509','有怀重送斛斯判官','杜牧','quantangshi','','卷29','苍苍烟月满川亭，我有劳歌一为听。
将取离魂随白骑，三台星里拜文星。','',''),('quantangshi-28510','赠别二首 一','杜牧','quantangshi','','卷29','娉娉褭褭十三余，豆蔻梢头二月初。
春风十里扬州路，卷上珠帘总不如。','',''),('quantangshi-28511','赠别二首 二','杜牧','quantangshi','','卷29','多情却似总无情，唯觉尊前笑不成。
蜡烛有心还惜别，替人垂泪到天明。','',''),('quantangshi-28512','寄远','杜牧','quantangshi','','卷29','前山极远碧云合，清夜一声白雪微。
欲寄相思千里月，溪边残照雨霏霏。','',''),('quantangshi-28513','少年行','杜牧','quantangshi','','卷29','官为骏马监，职帅羽林儿。
两绶藏不见，落花何处期？
猎敲白玉镫，怒袖紫金锤。
田窦长留醉，苏辛曲让岐。
豪持出塞节，笑别远山眉。
捷报云台贺，公卿拜寿巵。','',''),('quantangshi-28514','盆池','杜牧','quantangshi','','卷29','凿破苍苔地，偷他一片天。
白云生镜里，明月落堦前。','',''),('quantangshi-28515','有寄','杜牧','quantangshi','','卷29','云阔烟深树，江澄水浴秋。
美人何处在，明月万山头。','',''),('quantangshi-28516','斑竹筒簟','杜牧','quantangshi','','卷29','血染斑斑成锦纹，昔年遗恨至今存。
分明知是湘妃泣，何忍将身卧泪痕。','',''),('quantangshi-28517','和严恽秀才落花','杜牧','quantangshi','','卷29','共惜流年留不得，且环流水醉流杯。
无情红艳年年盛，不恨凋零却恨开。','',''),('quantangshi-28518','倡楼戏赠','杜牧','quantangshi','','卷29','细柳桥边深半春，缬衣帘里动香尘。
无端有寄闲消息，背插金钗笑向人。','',''),('quantangshi-28519','初上船留寄','杜牧','quantangshi','','卷29','烟水本好尚，亲交何惨凄。
况为珠履客，即泊锦帆堤。
沙雁同船去，田鵶遶岸啼。
此时还有味，必卧日从西。','',''),('quantangshi-28520','秋岸','杜牧','quantangshi','','卷29','河岸微退落，柳影微雕疎。
船上听呼穉，堤南趁漉鱼。
数帆旗去疾，一艇箭回初。
曾入相思梦，因凭附远书。','',''),('quantangshi-28521','过大梁闻河亭方宴赠孙子端','杜牧','quantangshi','','卷29','梁园纵翫归应少，赋雪搜才去必频。
板落岂缘无罚酒，不教客右更添人。','',''),('quantangshi-28522','题吴兴消暑楼十二韵','杜牧','quantangshi','','卷29','晴日登攀好，危楼物象饶。
一溪通四境，万岫饶层霄。
鸟翼舒华屋，鱼鳞棹短桡。
浪花机乍织，云叶匠新雕。
台榭罗嘉卉，城池敞丽谯。
蟾蜍来作鉴，螮蝀引成桥。
燕任随秋叶，人空集早潮。
楚鸿行尽直，沙鹭立偏翘。
暮角凄游旅，清歌惨泬寥。
景牵游目困，愁托酒肠销。
远吹流松韵，残阳渡柳桥。
时陪庾公赏，还悟脱烦嚣。','',''),('quantangshi-28523','奉送中丞姊夫俦自大理卿出镇江西叙事书怀因成十二韵','杜牧','quantangshi','','卷29','惟帝忧南纪，搜贤与大藩。
梅仙调步骤，庾亮拂橐鞬。
一室何劳扫，三章自不冤。
精明如定国，孤峻似陈蕃。
灞岸秋犹嫩，蓝桥水始喧。
红旓罣石壁，黑矟断云根。
滕阁丹霄倚，章江碧玉奔。
一声仙妓唱，千里暮江痕。
私好初童稚，官荣见子孙。
流年休挂念，万事至无言。
玉辇君频过，冯唐将未论。
庸书醻万债，竹坞问樊村。','',''),('quantangshi-28524','中丞业深韬畧志在功名再奉长句一篇兼有谘劝','杜牧','quantangshi','','卷29','樯似邓林江拍天，越香巴锦万千千。
滕王阁上柘枝鼓，徐孺亭西铁轴船。
八部元侯非不贵，万人师长岂无权。
要君严重疎欢乐，犹有河湟可下鞭。','',''),('quantangshi-28525','和裴杰秀才新樱桃','杜牧','quantangshi','','卷29','新果真琼液，人应宴紫兰。
圆疑窃龙颔，色已夺鸡冠。
远火微微辨，繁星历历看。
茂先知味好，曼倩恨偷难。
忍用烹酥酪，从将翫玉盘。
流年如可驻，何必九华丹。','',''),('quantangshi-28526','春思','杜牧','quantangshi','','卷29','岂君心的的，嗟我泪涓涓。
绵羽啼来久，锦鳞书未传。
兽垆凝冷焰，罗暮蔽晴烟。
自是求佳梦，何须讶画眠。','',''),('quantangshi-28527','代人作','杜牧','quantangshi','','卷29','楼高春日早，屏束麝烟堆。
盼眄凝魂别，依稀梦雨来。
绿鬟羞妥么，红颊思天偎。
鬬草怜香蕙，簪花间雪梅。
戌辽虽咽切，游蜀亦迟回。
锦字梭悬壁，琴心月满台。
笑筵凝贝启，眠箔晓珠开。
腊破征车动，袍襟对泪裁。','',''),('quantangshi-28528','偶题二首 一','杜牧','quantangshi','','卷29','劳劳千里身，襟袂满行尘。
深夜悬双泪，短亭思远人。
苍江程未息，黑水梦何频。
明月轻桡去，唯应钓赤鳞。','',''),('quantangshi-28529','偶题二首 二','杜牧','quantangshi','','卷29','有恨秋来极，无端别后知。
夜阑终耿耿，明发竟迟迟。
信已凭鸿去，归唯与燕期。
只因明月见，千里两相思。','',''),('quantangshi-28530','冬至日遇京使发寄舍弟','杜牧','quantangshi','','卷29','远信初凭双鲤去，他乡正遇一阳生。
尊前岂解愁家国，辇下唯能忆弟兄。
旅馆夜忧姜被冷，暮江寒觉晏裘轻。
竹门风过还惆怅，疑是松窗雪打声。','',''),('quantangshi-28531','洛下送张曼容赴上党召','杜牧','quantangshi','','卷29','歌阕罇残恨却偏，凭君不用设离筵。
未趍雉尾随元老，且蓦羊肠过少年。
七叶汉貂真密近，一枝诜桂亦徒然。
羽书正急征兵地，须遣头风处处痊。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-28532','宣州留赠','杜牧','quantangshi','','卷29','红铅湿尽半罗裙，洞府人间手欲分。
满面风流虽似玉，四年夫婿恰如云。
当春离恨杯长满，倚柱关情日渐曛。
为报眼波须稳当，五陵游宕莫知闻。','',''),('quantangshi-28533','寄题宣州开元寺','杜牧','quantangshi','','卷29','松寺曾同一鹤栖，夜深台殿月高低。
何人为倚东楼柱，正是千山雪涨溪。','',''),('quantangshi-28534','赠张祜','杜牧','quantangshi','','卷29','诗韵一逢君，平生称所闻。
粉毫唯画月，琼尺只裁云。
鲸阵人人慑，秋星历历分。
数篇留别我，羞杀李将军。','',''),('quantangshi-28535','残春独来南亭因寄张祜','杜牧','quantangshi','','卷29','暖云如粉草如茵，独步长堤不见人。
一岭桃花红锦黦，半溪山水碧罗新。
高枝百舌犹欺鸟，带叶梨花独送春。
仲蔚欲知何处在，苦吟林下拂诗尘。','',''),('quantangshi-28536','宣州开元寺南楼','杜牧','quantangshi','','卷29','小楼才受一牀横，终日看山酒满倾。
可惜和风夜来雨，醉中虚度打窗声。','',''),('quantangshi-28537','寄远人','杜牧','quantangshi','','卷29','终日求人卜，回回道好音。
那时离别后，入梦到如今。','',''),('quantangshi-28538','别沈处士','杜牧','quantangshi','','卷29','旧事参差梦，新程逦迤秋。
故人如见忆，时到寺东楼。','',''),('quantangshi-28539','留赠','杜牧','quantangshi','','卷29','舞靴应任闲人看，笑脸还须待我开。
不用镜前空有泪，蔷薇花谢即归来。','',''),('quantangshi-28540','奉和仆射相公春泽稍愆圣君轸虑嘉雪忽降品汇昭苏即事书成四韵','杜牧','quantangshi','','卷29','飘来鸡树凤池边，渐压琼枝冻碧涟。
银阙双高银汉里，玉山横列玉墀前。
昭阳殿下风回急，承露盘中月彩圆。
上相抽毫歌帝德，一篇风雅美丰年。','',''),('quantangshi-28541','寄李播评事','杜牧','quantangshi','','卷29','子列光殊价，明时忍自高。
宁无好舟檝，不泛恶风涛。
大翼终难戢，奇锋且自韬。
春来烟渚上，几净雪霜毫。','',''),('quantangshi-28542','送牛相出镇襄州','杜牧','quantangshi','','卷29','盛时常注意，南雍暂分茅。
紫殿辞明主，岩廊别旧交。
危幢侵碧雾，寒斾猎红旓。
德业悬秦镜，威声隐楚郊。
拜尘先洒泪，成厦昔容巢。
遥仰沈碑会，鸳鸯玉佩敲。','',''),('quantangshi-28543','送薛邽二首 一','杜牧','quantangshi','','卷29','可怜走马骑驴汉，岂有风光肯占伊。
只有三张最惆怅，下山回马尚迟迟。','',''),('quantangshi-28544','送薛邽二首 二','杜牧','quantangshi','','卷29','小捷风流已俊才，便将红粉作金台。
明年未去池阳郡，更乞春时却重来。','',''),('quantangshi-28545','见穆三十宅中庭海榴花谢','杜牧','quantangshi','','卷29','矜红掩素似多才，不待樱桃不逐梅。
春到未曾逢宴赏，雨余争解免低徊。
巧穷南国千般艳，趁得春风二月开。
堪恨王孙浪游去，落英狼籍始归来。','',''),('quantangshi-28546','留诲曹师等诗','杜牧','quantangshi','','卷29','万物有丑好，各一姿状分。
唯人即不尔，学与不学论。
学非探其花，要自拨其根。
