唯念贤哉崔大让，可怜无事不歌鱼。','',''),('quantangshi-28624','寄杜子二首 一','杜牧','quantangshi','','卷29','不识长杨事北胡，且教红袖醉来扶。
狂风烈焰虽千尺，豁得平生俊气无。','',''),('quantangshi-28625','寄杜子二首 二','杜牧','quantangshi','','卷29','武牢关吏应相笑，个里年年往复来。
若问使君何处去，为言相忆首长回。','',''),('quantangshi-28626','卢秀才将出王屋高步名场江南相逢赠别','杜牧','quantangshi','','卷29','王屋山人有古文，欲攀青桂弄氛氲。
将携健笔干明主，莫向仙坛问白云。
驰逐宁教争处让，是非偏忌众人分。
交游话我凭君道，除却鲈鱼更不闻。','',''),('quantangshi-28627','送刘三复郎中赴阙','杜牧','quantangshi','','卷29','横溪辞寂寞，金马去追游。
好是鸳鸯侣，正逢霄汉秋。
玉珂声琐琐，锦帐梦悠悠。
微笑知今是，因风谢钓舟。','',''),('quantangshi-28628','羊栏浦夜陪宴会','杜牧','quantangshi','','卷29','戈槛营中夜未央，雨沾云惹侍襄王。
球来香袖依稀暖，酒凸斛心泛滟光。
红弦高紧声声急，珠唱铺圆褭褭长。','',''),('quantangshi-28629','送杜顗赴润州幕','杜牧','quantangshi','','卷29','少年才俊赴知音，丞相门栏不觉深。
直道事人男子业，异乡加饭弟兄心。
还须整理韦弦佩，莫独矜夸玳瑁簪。
若去上元怀古去，谢安坟下与沈吟。','',''),('quantangshi-28630','有感','杜牧','quantangshi','','卷29','宛溪垂柳最长枝，曾被春风尽日吹。
不堪攀折犹堪看，陌上少年来自迟。','',''),('quantangshi-28631','书怀寄卢州','杜牧','quantangshi','','卷29','谢山南畔州，风物最宜秋。
太守悬金印，佳人敞画楼。
凝缸暗醉夕，残月上汀州。
可惜当年鬓，朱门不得游。','',''),('quantangshi-28632','贺崔大夫崔正字','杜牧','quantangshi','','卷29','内举无惭古所难，燕台遥想拂尘冠。
登龙有路水不峻，一雁背飞天正寒。
别夜酒余红烛短，映山帆满碧霞残。
谢公楼下潺湲响，离恨诗情添几般。','',''),('quantangshi-28633','江南送左师','杜牧','quantangshi','','卷29','江南为客正悲秋，更送吾师古渡头。
惆怅不同尘土别，水云踪迹去悠悠。','',''),('quantangshi-28634','寝夜','杜牧','quantangshi','','卷29','蛩唱如波咽，更深似水寒。
露华惊弊褐，灯影挂尘冠。
故国初离梦，前溪更下滩。
纷纷毫髪事，多少宦游难。','',''),('quantangshi-28635','十九兄郡楼有宴病不赴','杜牧','quantangshi','','卷29','十二层楼敞画檐，连云歌尽草纤纤。
空堂病怯阶前月，燕子嗔垂一竹帘。','',''),('quantangshi-28636','愁','杜牧','quantangshi','','卷29','聚散竟无形，回肠自结成。
古今留不得，离别又潜生。
降虏将军思，穷秋远客情。
何人更憔悴，落第泣秦京。','',''),('quantangshi-28637','隋苑','杜牧','quantangshi','','卷29','红霞一抹广陵春，定子当筵睡脸新。
却笑吃亏隋炀帝，破家亡国为谁人。','',''),('quantangshi-28638','芭蕉','杜牧','quantangshi','','卷29','芭蕉为雨移，故向窓前种。
怜渠点滴声，留得归乡梦。
梦远莫归乡，觉来一翻动。','',''),('quantangshi-28639','汴人舟行答张祜','杜牧','quantangshi','','卷29','千万长河共使船，听君诗句倍怆然。
春风野岸名花发，一道帆樯画柳烟。','',''),('quantangshi-28640','牧陪昭应卢郎中在江西宣州佐今吏部沈公幕罢府周岁公宰昭应牧在淮南縻职叙旧成二十二韵用以投寄','杜牧','quantangshi','','卷29','燕雁下扬州，凉风柳陌愁。
可怜千里梦，还是一年秋。
宛水环朱槛，章江敞碧流。
谬陪吾益友，祗事我贤侯。
印组萦光马，锋铓看解牛。
井闾安乐易，冠盖惬依投。
政简稀开阁，功成每运筹。
送春经野坞，迟日上高楼。
玉裂歌声断，霞飘舞带收。
泥情斜拂印，别脸小低头。
日晚花枝烂，釭凝粉彩稠。
未曾孤酩酊，剩肯只淹留。
重德俄征宠，诸生苦宦游。
分途之绝国，洒泪拜行輈。
聚散真漂梗，光阴急转邮。
铭心徒历历，屈指尽悠悠。
君作烹鲜用，谁膺仄席求。
卷怀能愤悱，卒岁且优游。
去矣时难遇，沽哉价莫酬。
满枝为鼓吹，衷甲避戈矛。
隋帝宫荒草，秦王土一丘。
相逢好大笑，除此总云浮。','',''),('quantangshi-28641','寓言','杜牧','quantangshi','','卷29','暖风迟日柳初含，顾影看身又自慙。
何事明朝独惆怅，杏花时节在江南。','',''),('quantangshi-28642','猿','杜牧','quantangshi','','卷29','月白烟青水暗流，孤猿衔恨叫中秋。
三声欲断疑肠断，饶是少年今白头。','',''),('quantangshi-28643','怀归','杜牧','quantangshi','','卷29','尘埃终日满牕前，水态云容思浩然。
争得便归湘浦去，却持竿上钓鱼船。','',''),('quantangshi-28644','边上晚秋','杜牧','quantangshi','','卷29','黑山南面更无州，马放平沙夜不收。
风送孤城临晚角，一声声入客心愁。','',''),('quantangshi-28645','伤友人悼吹箫妓','杜牧','quantangshi','','卷29','玉箫声断没流年，满目春愁陇树烟。
艳质已随云雨散，凤楼空锁月明天。','',''),('quantangshi-28646','访许颜','杜牧','quantangshi','','卷29','门近寒溪牕近山，枕山流水日潺潺。
长嫌世上浮云客，老向尘中不解颜。','',''),('quantangshi-28647','春日古道傍作','杜牧','quantangshi','','卷29','万古荣华旦暮齐，楼台春尽草萋萋。
君看陌上何人墓，旋化红尘送马蹏。','',''),('quantangshi-28648','青冢','杜牧','quantangshi','','卷29','青冢前头陇水流，燕支山上暮云秋。
蛾眉一坠穷泉路，夜夜孤魂月下愁。','',''),('quantangshi-28649','大梦上人自庐峰回','杜牧','quantangshi','','卷29','行脚寻常到寺稀，一枝藜杖一禅衣。
开门满院空秋色，新向庐峰过夏归。','',''),('quantangshi-28650','洛中二首 一','杜牧','quantangshi','','卷29','柳动晴风拂路尘，年年宫阙锁浓春。
一从翠辇无巡幸，老却蛾眉几许人。','',''),('quantangshi-28651','洛中二首 二','杜牧','quantangshi','','卷29','风吹柳带摇晴绿，蝶遶花枝恋暖香。
多把芳菲泛春酒，直教愁色对愁肠。','',''),('quantangshi-28652','边上闻笳三首 一','杜牧','quantangshi','','卷29','何处吹笳薄暮天，塞垣高鸟没狼烟。
游人一听头堪白，苏武争禁十九年。','',''),('quantangshi-28653','边上闻笳三首 二','杜牧','quantangshi','','卷29','海路无尘边草新，荣枯不见绿杨春。
白沙日暮愁云起，独感离乡万里人。','',''),('quantangshi-28654','边上闻笳三首 三','杜牧','quantangshi','','卷29','胡雏吹笛上高台，寒雁惊飞去不回。
尽日春风吹不散，只应分付客愁来。','',''),('quantangshi-28655','春日寄许浑先辈','杜牧','quantangshi','','卷29','蓟北雁初去，湘南春又归。
水流沧海急，人到白头稀。
塞路尽何处，我愁当落晖。
终须接鸳鹭，霄汉共高飞。','',''),('quantangshi-28656','经阖闾城','杜牧','quantangshi','','卷29','遗踪委衰草，行客思悠悠。
昔日人何处，终年水自流。
