吟罢独归去，烟云尽惨愁。','',''),('quantangshi-28657','并州道中','杜牧','quantangshi','','卷29','行役我方倦，苦吟谁复闻。
戌楼春带雪，边角暮吹云。
极目无人迹，回头送雁羣。
如何遣公子，高卧醉醺醺。','',''),('quantangshi-28658','别怀','杜牧','quantangshi','','卷29','相别徒成泣，经过总是空。
劳生惯离别，夜梦苦西东。
去路三湘浪，归程一片风。
他年寄消息，书在鲤鱼中。','',''),('quantangshi-28659','渔父','杜牧','quantangshi','','卷29','白发沧浪上，全忘是与非。
秋潭垂钓去，夜月叩船归。
烟影侵芦岸，潮痕在竹扉。
终年狎鸥鸟，来去且无机。','',''),('quantangshi-28660','秋梦','杜牧','quantangshi','','卷29','寒空动高吹，月色满清砧。
残梦夜魂断，美人边思深。
孤鸿秋出塞，一叶暗辞林。
又寄征衣去，迢迢天外心。','',''),('quantangshi-28661','早秋客舍','杜牧','quantangshi','','卷29','风吹一片叶，万物已惊秋。
独夜他乡泪，年年为客愁。
别离何处尽，摇落几时休。
不及磻溪叟，身闲长自由。','',''),('quantangshi-28662','逢故人','杜牧','quantangshi','','卷29','故交相见稀，相见倍依依。
尘路事不尽，云岩闲好归。
投人销壮志，徇俗变真机。
又落他乡泪，风前一满衣。','',''),('quantangshi-28663','秋晚江上遣怀','杜牧','quantangshi','','卷29','孤舟天际外，去路望中赊。
贫病远行客，梦魂多在家。
蝉吟秋色树，鸦噪夕阳沙。
不拟彻双鬓，他方掷岁华。','',''),('quantangshi-28664','长安夜月','杜牧','quantangshi','','卷29','寒光垂静夜，皓彩满重城。
万国尽分照，谁家无此明。
古槐疎影薄，仙桂动秋声。
独有长门里，蛾眉对晓晴。','',''),('quantangshi-28665','云','杜牧','quantangshi','','卷29','东西那有碍，出处岂虚心。
晓入洞庭阔，暮归巫峡深。
渡江随鸟影，拥树隔猿吟。
莫隐高唐去，枯苗待作霖。','',''),('quantangshi-28666','春怀','杜牧','quantangshi','','卷29','年光何太急，倏忽又青春。
明月谁为主，江山暗换人。
莺花潜运老，荣乐渐成尘。
遥忆朱门柳，别离应更频。','',''),('quantangshi-28667','逢故人','杜牧','quantangshi','','卷29','年年不相见，相见却成悲。
教我泪如霰，嗟君髪似丝。
正伤携手处，况值落花时。
莫惜今宵醉，人间忽忽期。','',''),('quantangshi-28668','闲题','杜牧','quantangshi','','卷29','男儿所在即为家，百镒黄金一朵花。
借问春风何处好，绿杨深巷马头斜。','',''),('quantangshi-28669','金谷园','杜牧','quantangshi','','卷29','繁华事散逐香尘，流水无情草自春。
日暮东风怨啼鸟，落花犹似堕楼人。','',''),('quantangshi-28670','重登科','杜牧','quantangshi','','卷29','星汉离宫月出轮，满街含笑绮罗春。
花前每被青蛾问，何事重来只一人。','',''),('quantangshi-28671','游边','杜牧','quantangshi','','卷29','黄沙连海路无尘，边草长枯不见春。
日暮拂云堆下过，马前逢着射雕人。','',''),('quantangshi-28672','将赴池州道中作','杜牧','quantangshi','','卷29','青阳云水去年寻，黄绢歌诗出翰林。
