一呌一回肠一断，三春三月忆三巴。','',''),('quantangshi-28679','江楼','杜牧','quantangshi','','卷29','独酌芳春酒，登楼已半醺。
谁惊一行雁，冲断过江云。','',''),('quantangshi-28680','旅宿','杜牧','quantangshi','','卷29','旅馆无良伴，凝情自悄然。
寒灯思旧事，断雁警愁眠。
远梦归侵晓，家书到隔年。
湘江好烟月，门系钓鱼船。','',''),('quantangshi-28681','杜鹃','杜牧','quantangshi','','卷29','杜宇竟何冤，年年呌蜀门。
至今衔积恨，终古吊残魂。
芳草迷肠结，红花染血痕。
山川尽春色，呜咽复谁论。','',''),('quantangshi-28682','闻蝉','杜牧','quantangshi','','卷29','火云初似灭，晓角欲微清。
故国行千里，新蝉忽数声。
时行仍仿髴，度日更分明。
不敢频倾耳，唯忧白发生。','',''),('quantangshi-28683','送友人','杜牧','quantangshi','','卷29','十载名兼利，人皆与命争。
青春留不住，白发自然生。
夜雨滴乡思，秋风从别情。
都门五十里，驰马逐鸡声。','',''),('quantangshi-28684','旅情','杜牧','quantangshi','','卷29','窗虚枕簟凉，寝倦忆潇湘。
山色几时老，人心终日忙。
松风半夜雨，帘月满堂霜。
匹马好归去，江头橘正香。','',''),('quantangshi-28685','晓望','杜牧','quantangshi','','卷29','独起望山色，水鸡鸣蓼洲。
房星随月晓，楚木向云秋。
曲渚疑江尽，平沙似浪浮。
秦原在何处，泽国碧悠悠。','',''),('quantangshi-28686','贻友人','杜牧','quantangshi','','卷29','自是东西客，逢人又送人。
不应相见老，秖是别离频。
度日还知暮，平生未识春。
傥无迁谷分，归去养天真。','',''),('quantangshi-28687','书事','杜牧','quantangshi','','卷29','自笑走红尘，流年旧复新。
东风半夜雨，南国万家春。
失计抛鱼艇，何门化涸鳞。
是谁添岁月，老却暗投人。','',''),('quantangshi-28688','别鹤','杜牧','quantangshi','','卷29','分飞共所从，六翮势催风。
声断碧云外，影孤明月中。
青田归路远，丹桂旧巢空。
矫翼知何处，天涯不可穷。','',''),('quantangshi-28689','晚泊','杜牧','quantangshi','','卷29','帆湿去悠悠，停桡宿渡头。
乱烟迷野岸，独鸟出中流。
[篷]雨延乡梦，江风阻暮秋。
傥无身外事，甘老向扁舟。','',''),('quantangshi-28690','山寺','杜牧','quantangshi','','卷29','峭壁引行径，截溪开石门。
泉飞溅虚槛，云起涨河轩。
隔水看来路，疎篱见定猿。
未闲难久住，归去复何言。','',''),('quantangshi-28691','早行','杜牧','quantangshi','','卷29','垂鞭信马行，数里未鸡鸣。
林下带残梦，叶飞时忽惊。
霜凝孤鹤逈，月晓远山横。
僮仆休辞险，时平路复平。','',''),('quantangshi-28692','秋日偶题','杜牧','quantangshi','','卷29','荷花兼柳叶，彼此不胜秋。
玉露滴初泣，金风吹更愁。
绿眉甘弃坠，红脸恨飘流。
叹息是游子，少年还白头。','',''),('quantangshi-28693','忆归','杜牧','quantangshi','','卷29','新城非故里，终日想柴扃。
兴罢花还落，愁来酒欲醒。
何人初髪白，几处乱山青。
远忆湘江上，渔歌对月听。','',''),('quantangshi-28694','偶见','杜牧','quantangshi','','卷29','朔风高紧掠河楼，白鼻騧郎白罽裘。
有个当垆明似月，马鞭斜揖笑回头。','',''),('quantangshi-28695','醉倒','杜牧','quantangshi','','卷29','日晴空乐下仙云，俱在凉亭送使君。
莫辞一盏即相请，还是三年更不闻。','',''),('quantangshi-28696','酬许十三秀才兼依来韵','杜牧','quantangshi','','卷29','多为裁诗步竹轩，有时凝思过朝昏。
篇成敢道怀金璞，吟苦唯应似岭猿。
迷兴每慙花月夕，寄愁长在别离魂。
凭君把卷侵寒烛，丽句时传画戟门。','',''),('quantangshi-28697','后池泛舟送王十秀才','杜牧','quantangshi','','卷29','城日晚悠悠，弦歌在碧流。
夕风飘度曲，烟屿隐行舟。
问拍拟新令，怜香占彩球。
当筵虽一醉，宁复缓离愁。','',''),('quantangshi-28698','书情','杜牧','quantangshi','','卷29','谁家洛浦神，十四五来人。
媚髪轻垂额，香衫软着身。
摘莲红袖湿，窥渌翠蛾频。
飞鹊徒来往，平阳公主亲。','',''),('quantangshi-28699','兵部尚书席上作','杜牧','quantangshi','','卷29','华堂今日绮筵开，谁唤分司御史来。
偶发狂言惊满坐，三重粉面一时回。','',''),('quantangshi-28700','驌驦坂','杜牧','quantangshi','','卷29','荆州一万里，不如蒯易度。
仰首望飞鸣，伊人何异趣。','',''),('quantangshi-28701','冬日五湖馆水亭怀别','杜牧','quantangshi','','卷29','芦荻花多触处飞，独凭虚槛雨微微。
寒林叶落鸟巢出，古渡风高渔艇稀。
云抱四山终日在，草荒三径几时归。
江城向晚西流急，无限乡心闻捣衣。','',''),('quantangshi-28702','不寝','杜牧','quantangshi','','卷29','到晓不成梦，思量堪白头。
多无百年命，长有万般愁。
世路应难尽，营生卒未休。
莫言名与利，名利是身讐。','',''),('quantangshi-28703','泊松江','杜牧','quantangshi','','卷29','清露白云明月天，与君齐棹木兰船。
南湖风雨一相失，夜泊横塘心渺然。','',''),('quantangshi-28704','题水西寺','杜牧','quantangshi','','卷29','三日去还住，一生焉再游。
含情碧溪水，重上粲公楼。','',''),('quantangshi-28705','赠别宣州崔羣相公','杜牧','quantangshi','','卷29','衰散相逢洛水边，却思同在紫薇天。
尽将舟楫板桥去，早晚归来更济川。','',''),('quantangshi-28706','闻开江相国宋下世二首 一','杜牧','quantangshi','','卷29','权门阴进夺移才，驿骑如星堕峡来。
晁氏有恩忠作祸，贾生无罪直为灾。
贞魂误向崇山没，冤气疑从湘水回。
毕竟成功何处是，五湖云月一帆开。','',''),('quantangshi-28707','闻开江相国宋下世二首 二','杜牧','quantangshi','','卷29','月落清湘棹不喧，玉杯瑶瑟奠苹蘩。
谁令力制乘轩鹤，自取机沈在槛猿。
位极干坤三事贵，谤兴华夏一夫冤。
宵衣旰食明天子，日伏青蒲不为言。','',''),('quantangshi-28708','出关','杜牧','quantangshi','','卷29','朝缨初解佐江濆，麋鹿心知自有羣。
汉囿猎稀慵献赋，楚山耕早任移文。
卧归渔浦月连海，行望凤城花隔云。
关吏不须迎马笑，去时无意学终军。','',''),('quantangshi-28709','暝投云智寺渡溪不得却取沿江路往','杜牧','quantangshi','','卷29','双嵓泻一川，回马断桥前。
古庙阴风地，寒钟暮雨天。
沙虚留虎迹，水滑带龙涎。
却下临江路，潮深无渡船。','',''),('quantangshi-28710','宣城赠萧兵曹','杜牧','quantangshi','','卷29','桂檝谪湘渚，三年波上春。
舟寒句溪雪，衣故洛城尘。
客道耻摇尾，皇恩宽犯鳞。
花时去国远，月夕上楼频。
赊酒不辞病，佣书非为贫。
行吟值渔父，坐隐对樵人。
紫陌罢双辙，碧潭穷一纶。
高秋更南去，烟水是通津。','',''),('quantangshi-28711','过鲍溶宅有感','杜牧','quantangshi','','卷29','寥落故人宅，重来身已亡。
古苔残墨沼，深竹旧书堂。
秋色池馆静，雨声云木凉。
无因展交道，日暮倍心伤。','',''),('quantangshi-28712','寄兄弟','杜牧','quantangshi','','卷29','江城红叶尽，旅思倍凄凉。
孤梦家山远，独眠秋夜长。
道存空倚命，身贱未归乡。
南望仍垂泪，天边雁一行。','',''),('quantangshi-28713','秋日','杜牧','quantangshi','','卷29','有计自安业，秋风罢远吟。
买山惟种竹，对客更弹琴。
烟起药厨晚，杵声松院深。
闲眠得真性，惆怅旧时心。','',''),('quantangshi-28714','卜居招书侣','杜牧','quantangshi','','卷29','忆昨未知道，临川每羡鱼。
世途行处见，人事病来疎。
微雨秋栽竹，孤灯夜读书。
怜君亦同志，晚岁傍山居。','',''),('quantangshi-28715','西山草堂','杜牧','quantangshi','','卷29','何处人事少，西峰旧草堂。
晒书秋日晚，洗药石泉香。
后岭有微雨，北牕生晓凉。
徒劳问归路，峰叠遶家乡。','',''),('quantangshi-28716','贻隐者','杜牧','quantangshi','','卷29','回报隐居山，莫忧山兴阑。
求人颜色尽，知道性情宽。
信谱弹琴误，缘崖斸药难。
东臯亦自给，殊愧远相安。','',''),('quantangshi-28717','石池','杜牧','quantangshi','','卷29','通竹引泉脉，泓澄深石盆。
惊鱼翻藻叶，浴鸟上松根。
残月留山影，高风耗水痕。
谁家洗秋药，来往自开门。','',''),('quantangshi-28718','送苏协律从事振武','杜牧','quantangshi','','卷29','琴尊诗思劳，更欲学龙韬。
王粲暂投笔，吕虔初佩刀。
夜吟关月苦，秋望塞云高。
去去从军乐，雕飞岱马豪。','',''),('quantangshi-28719','怀政禅师院','杜牧','quantangshi','','卷29','山斋路几层，败衲学真乘。
寒暑移双树，光阴尽一灯。
风飘高竹雪，泉涨小池冰。
莫讶频来此，修身欲到僧。','',''),('quantangshi-28720','送荔浦蒋明府赴任','杜牧','quantangshi','','卷29','路长春欲尽，歌怨酒多酣。
白社莲塘北，青袍桂水南。
驿行盘鸟道，船宿避龙潭。
真得诗人趣，烟霞处处谙。','',''),('quantangshi-28721','秋夕有怀','杜牧','quantangshi','','卷29','念远坐西阁，华池涵月凉。
书回秋欲尽，酒醒夜初长。
露白莲衣浅，风清蕙带香。
前年此佳景，兰棹醉横塘。','',''),('quantangshi-28722','秋霁寄远','杜牧','quantangshi','','卷29','初霁独登赏，西楼多远风。
横烟秋水上，疎雨夕阳中。
高树下山鸟，平芜飞草虫。
唯应待明月，千里与君同。','',''),('quantangshi-28723','经古行宫','杜牧','quantangshi','','卷29','台阁参差倚太阳，年年花发满山香。
重门勘锁青春晚，深殿垂帘白日长。
草色芊绵侵御路，泉声呜咽绕宫墙。
先皇一去无回驾，红粉云环空断肠。','',''),('quantangshi-28724','宣州开元寺赠惟真上人','杜牧','quantangshi','','卷29','曾与径山为小师，千年僧行众人知。
夜深月色当禅处，斋后钟声到讲时。
经雨绿苔侵古画，过秋红叶落新诗。
劝君莫厌江城客，虽在风尘别有期。','',''),('quantangshi-28725','秋晚怀茅山石涵村舍','杜牧','quantangshi','','卷29','十亩山田近石涵，村居风俗旧曾谙。
帘前白艾惊春燕，篱上青桑待晚蚕。
云暖采茶来岭北，月明沽酒过溪南。
陵阳秋尽多归思，红树萧萧覆碧潭。','',''),('quantangshi-28726','留题李侍御书斋','杜牧','quantangshi','','卷29','曾话平生志，书斋几见留。
道孤心易感，恩重力难酬。
独立千峰晚，频来一叶秋。
鸡鸣应有处，不学泪空流。','',''),('quantangshi-28727','行次白沙馆先寄上河南王侍郎','杜牧','quantangshi','','卷29','夜程何处宿，山叠树层层。
孤馆闲秋雨，空堂停曙灯。
歌慙渔浦客，诗学雁门僧。
此意无人识，明朝见李膺。','',''),('quantangshi-28728','贵游','杜牧','quantangshi','','卷29','朝回佩马草萋萋，年少恩深卫霍齐。
斧钺旧威龙塞北，池台新赐凤城西。
门通碧树开金锁，楼对青山倚玉梯。
南陌行人尽廻首，笙歌一曲暮云低。','',''),('quantangshi-28729','越中','杜牧','quantangshi','','卷29','石城花暖鹧鸪飞，征客春帆秋不归。
犹自保郎心似石，绫梭夜夜织寒衣。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-28730','闻范秀才自蜀游江湖','杜牧','quantangshi','','卷29','蜀道下湘渚，客帆应不迷。
江分三峡响，山竝九华齐。
秋泊雁初宿，夜吟猿乍啼。
归时慎行李，莫到石城西。','',''),('quantangshi-28731','绿萝','杜牧','quantangshi','','卷29','绿萝萦数匝，本在草堂间。
秋色寄高树，昼阴笼近山。
移花疎处过，斸药困时攀。
日暮微风起，难寻旧径还。','',''),('quantangshi-28732','宿东横山濑','杜牧','quantangshi','','卷29','孤舟路渐赊，时见碧桃花。
溪雨滩声急，岩风树势斜。
猕猴悬弱柳，鸂鶒睡横楂。
谩向仙林宿，无人识阮家。','',''),('quantangshi-28733','贻迁客','杜牧','quantangshi','','卷29','无机还得罪，直道不伤情。
微雨昏山色，疎笼闭鹤声。
闲居多野客，高枕见江城。
门外长溪水，怜君又濯缨。','',''),('quantangshi-28734','陵阳送客','杜牧','quantangshi','','卷29','南楼送郢客，西郭望荆门。
凫鹄下寒渚，牛羊归远村。
兰舟倚行棹，桂酒掩余罇。
重此一留宿，前汀烟月昏。','',''),('quantangshi-28735','寄桐江隐者','杜牧','quantangshi','','卷29','潮去潮来洲渚春，山花如绣草如茵。
严陵台下桐江水，解钓鲈鱼能几人。','',''),('quantangshi-28736','长兴里夏日寄南隣避暑','杜牧','quantangshi','','卷29','侯家大道傍，蝉噪树苍苍。
开锁洞门远，卷帘官舍凉。
栏围红药盛，架引绿萝长。
永日一欹枕，故山云水乡。','',''),('quantangshi-28737','送太昱禅师','杜牧','quantangshi','','卷29','禅牀深竹里，心与径山期。
结社多高客，登坛尽小师。
早秋归寺远，新雨上滩迟。
别后江云碧，南斋一首诗。','',''),('quantangshi-28738','梁秀才以早春旅次大梁将归郊扉言怀兼别示亦蒙见赠凡二十韵走笔依韵','杜牧','quantangshi','','卷29','玉塞功犹阻，金门事已陈。
世途皆扰扰，乡党尽循循。
客道难投足，家声易发身。
松篁标节晚，兰蕙吐词春。
处困羞摇尾，怀忠壮犯鳞。
宅临三楚水，衣带二京尘。
歛迹愁山鬼，遗形慕谷神。
采芝先避贵，栽橘早防贫。
弦泛桐材响，杯澄糯醁醇。
但寻陶令集，休献楚王珍。
林密闻风远，池平见月匀。
藤龛红婀娜，苔磴绿嶙峋。
雪树交梁苑，冰河涨孟津。
面邀文作友，心许德为隣。
旅馆将分被，婴儿共洒巾。
渭阳连汉曲，京口接漳滨。
通塞时应定，荣枯理会均。
儒流当自勉，妻族更谁亲。
照瞩三光政，生成四气仁。
磻溪有心者，垂白肯湮沦。','',''),('quantangshi-28739','川守大夫刘公早岁寓居敦行里肆有题壁十韵今之置第乃获旧居洛下大僚因有唱和叹咏不足輙献此诗','杜牧','quantangshi','','卷29','旅馆当年葺，公才此日论。
林繁轻竹祖，树暗惜桐孙。
炼药藏金鼎，疏泉陷石盆。
散科松有节，深剃草无根。
龙卧池犹在，鸎迁谷尚存。
昔为扬子宅，今是李膺门。
积学萤尝聚，微词凤早吞。
百年明素志，三顾起新恩。
雪耀冰霜冷，尘飞水墨昏。
莫教垂露迹，岁晚杂苔痕。','',''),('quantangshi-28740','中秋日拜起居表晨渡天津桥即事十六韵献居守相国崔公兼呈工部刘公','杜牧','quantangshi','','卷29','碧树康庄内，清川巩洛间。
坛分中岳顶，城缭大河湾。
广殿含凉静，深宫积翠闲。
楼齐云漠漠，桥束水潺潺。
过雨柽枝润，迎霜柿叶殷。
紫鳞冲晚浪，白鸟背秋山。
月拜西归表，晨趋北向班。
鸳鸿随半仗，貔虎护重关。
玉帐才容足，金罇暂解颜。
迹留伤堕屦，恩在乐衔环。
南省兰先握，东堂桂早攀。
龙门君夭矫，莺谷我绵蛮。
分薄嵇心懒，哀多庾鬓班。
人慙公干卧，频送子牟还。
自覩宸居壮，谁忧国步艰。
只应时与醉，因病纵疎顽。','',''),('quantangshi-28741','分司东都寓居履道叨承川尹刘侍郎大夫恩知上四十韵','杜牧','quantangshi','','卷29','命世须人瑞，匡君在岳灵。
气和薰北陆，襟旷纳东溟。
赋妙排鹦鹉，诗能继鹡鸰。
蒲亲香案色，兰动粉闱馨。
周孔传文教，萧曹授武经。
家童谙禁掖，廐马识金铃。
性与奸邪背，心因启沃冥。
进贤光日月，诛恶助雷霆。
阊阖开时召，箫韶奏处听。
水精悬御幄，云母展宫屏。
捧诏巡汧陇，飞书护井陉。
先声威虎兕，余力活蟭螟。
荣重秦军箭，功高汉将铭。
戈鋋回紫塞，干戚散彤庭。
顺美皇恩洽，扶颠国步宁。
禹谟推掌诰，汤网属司刑。
穉榻蓬莱掩，膺舟巩洛停。
马羣先去害，民籍更添丁。
猾吏门长塞，豪家户不扃。
四知台上镜，三惑井中瓶。
雅韵凭开匣，雄铓待发硎。
火中胶绿树，泉下斸青萍。
五岳期双节，三台空一星。
凤池方注意，麟阁会图行。
寒暑逾流电，光阴甚建瓴。
散曹分已白，崇直眼由青。
赐第成官舍，佣居起客亭。
松筠侵巷陌，禾黍接郊坰。
宿雨回为沼，春沙淀作汀。
鱼罾栖翡翠，蛛网挂蜻蜓。
迟晓河初转，伤秋露已零。
梦余钟杳杳，吟罢烛荧荧。
字小书难写，杯迟酒易醒。
久贫惊早雁，多病放残萤。
雪劲孤根竹，风雕数荚蓂。
转喉空婀娜，垂手自娉婷。
胫细摧新履，腰羸减旧鞓。
海边慵逐臭，尘外怯吞腥。
隐豹窥重巘，潜虬避浊泾。
商歌如不顾，归棹越南{氵雨/品}。','',''),('quantangshi-28742','题白云楼','杜牧','quantangshi','','卷29','西北楼开四望通，残霞成绮月悬弓。
江村夜涨浮天水，泽国秋生动地风。
高下绿苗千顷尽，新陈红粟万箱空。
才微分薄忧何益，却欲回心学塞翁。','',''),('quantangshi-28743','赠别','杜牧','quantangshi','','卷29','眼前迎送不曾休，相续轮蹄似水流。
门外若无南北路，人间应免别离愁。
苏秦六印归何日，潘岳双毛去值秋。
莫怪分襟衔泪语，十年耕钓忆沧洲。','',''),('quantangshi-28744','秋夜与友人宿','杜牧','quantangshi','','卷29','楚国同游过十霜，万重心事几堪伤。
蒹葭露白莲塘浅，砧杵夜清河汉凉。
云外山川归梦远，天涯歧路客愁长。
寒城欲晓闻吹笛，犹卧东轩月满牀。','',''),('quantangshi-28745','将赴京留赠僧院','杜牧','quantangshi','','卷29','九衢尘土递追攀，马迹轩车日暮间。
玄髪尽惊为客换，白头曾见几人闲。
空悲浮世云无定，多感流年水不还。
谢却从前受恩地，归来依止叩禅关。','',''),('quantangshi-28746','寄湘中友人','杜牧','quantangshi','','卷29','莫恋醉乡迷酒杯，流年长怕少年催。
西陵水阔鱼难到，南国路遥书未回。
匹马计程愁日尽，一蝉何事引秋来。
相如已定题桥志，江上无由梦钓台。','',''),('quantangshi-28747','江上逢友人','杜牧','quantangshi','','卷29','故国归人酒一杯，暂亭兰棹共裴回。
村连三峡暮云起，潮送九江寒雨来。
已作相如投赋计，还凭殷浩寄书回。
到时若见东篱菊，为问经霜几度开。','',''),('quantangshi-28748','金谷怀古','杜牧','quantangshi','','卷29','凄凉遗迹洛川东，浮世荣枯万古同。
桃李香消金谷在，绮罗魂断玉楼空。
往年人事伤心外，今日风光属梦中。
徒想夜泉流客恨，夜泉流恨恨无穷。','',''),('quantangshi-28749','寄卢先辈','杜牧','quantangshi','','卷29','一从分首劒江滨，南国相思寄梦频。
书去又逢商岭雪，信回应过洞庭春。
关河日日悲长路，霄汉年年望后尘。
愿指丹梯曾到处，莫教犹作独迷人。','',''),('quantangshi-28750','南楼夜','杜牧','quantangshi','','卷29','玉管金罇夜不休，如悲昼短惜年流。
歌声褭褭澈清夜，月色娟娟当翠楼。
枕上暗惊垂钓梦，灯前偏起别家愁。
思量今日英雄事，身到簪裾已白头。','',''),('quantangshi-28751','行经庐山东林寺','杜牧','quantangshi','','卷29','离魂断续楚江壖，叶坠初红十月天。
紫陌事多难暂息，青山长在好闲眠。
方趋上国期干禄，未得空堂学坐禅。
他岁若教如范蠡，也应须入五湖烟。','',''),('quantangshi-28752','途中逢故人话西山读书早曾游览','杜牧','quantangshi','','卷29','西岩曾到读书堂，穿竹行莎十里强。
湖上梦余波滟滟，岭头愁断路茫茫。
经过事寄烟霞远，名利尘随日月长。
莫道少年头不白，君看潘岳几茎霜。','',''),('quantangshi-28753','将赴京题陵阳王氏水居','杜牧','quantangshi','','卷29','帘卷平芜接远天，暂宽行役到罇前。
是非境里有闲日，荣辱尘中无了年。
山簇暮云千野雨，江分秋水九条烟。
马蹄不道贪西去，争向一声高树蝉。','',''),('quantangshi-28754','送别','杜牧','quantangshi','','卷29','溪边杨柳色参差，攀折年年赠别离。
一片风帆望已极，三湘烟水返何时？
多缘去棹将愁远，犹倚危亭欲下迟。
莫殢酒杯闲过日，碧云深处是佳期。','',''),('quantangshi-28755','寄远','杜牧','quantangshi','','卷29','两叶愁眉愁不开，独含惆怅上层台。
碧云空断雁行处，红叶已雕人未来。
塞外音书无信息，道傍车马起尘埃。
功名待寄凌烟阁，力尽辽城不肯回。','',''),('quantangshi-28756','新柳','杜牧','quantangshi','','卷29','无力摇风晓色新，细腰争妬看来频。
绿阴未覆长堤水，金穗先迎上苑春。
几处伤心怀远路，一枝和雨送行尘。
东门门外多离别，愁杀朝朝暮暮人。','',''),('quantangshi-28757','旅怀作','杜牧','quantangshi','','卷29','促促因吟昼短诗，朝惊穠色暮空枝。
无情春色不长久，有限年光多盛衰。
往事只应随梦里，劳生何处是闲时？
眼前扰扰日一日，暗送白头人不知。','',''),('quantangshi-28758','雁','杜牧','quantangshi','','卷29','万里衔芦别故乡，云飞雨宿向潇湘。
数声孤枕堪垂泪，几处高楼欲断肠。
度日翩翩斜避影，临风一一直成行。
年年辛苦来衡岳，羽翼摧残陇塞霜。','',''),('quantangshi-28759','惜春','杜牧','quantangshi','','卷29','花开又花落，时节暗中迁。
无计延春日，何能驻少年。
小藂初散蝶，高柳即闻蝉。
繁艳归何处，满山啼杜鹃。','',''),('quantangshi-28760','鸳鸯','杜牧','quantangshi','','卷29','两两戏沙汀，长疑画不成。
锦机争织样，歌曲爱呼名。
好育顾栖息，堪怜泛浅清。
凫鸥皆尔类，惟羡独含情。','',''),('quantangshi-28761','闻雁','杜牧','quantangshi','','卷29','带霜南去雁，夜好宿汀沙。
惊起向何处，高飞极海涯。
入云声渐远，离岳路由赊。
归梦当时断，参差欲到家。','',''),('quantangshi-28762','江楼晚望','杜牧','quantangshi','','卷29','湖山翠欲结蒙笼，汗漫谁游夕照中。
初语燕雏知社日，习飞鹰隼识秋风。
波摇珠树千寻拔，山凿金陵万仞空。
不欲登楼更怀古，斜阳江上正飞鸿。','',''),('quantangshi-28763','九日','杜牧','quantangshi','','卷29','金英繁乱拂阑香，明府辞官酒满缸。
还有玉楼轻薄女，笑他寒燕一双双。','',''),('quantangshi-28764','寄牛相公','杜牧','quantangshi','','卷29','汉水横冲蜀浪分，危楼点的拂孤云。
六年仁政讴歌去，柳遶春堤处处闻。','',''),('quantangshi-28765','为人题赠二首 一','杜牧','quantangshi','','卷29','我乏青云称，君无买笑金。
虚传南国貌，争奈五陵心。
桂席尘瑶佩，琼炉烬水沈。
凝魂空荐梦，低耳悔听琴。
月落珠帘卷，春寒锦幕深。
谁家楼上笛，何处月明砧？
兰径飞蝴蝶，筠笼语翠襟。
和簪抛凤髻，将泪入鸳衾。
的的新添恨，迢迢绝好音。
文园终病渴，休咏白头吟。','',''),('quantangshi-28766','为人题赠二首 二','杜牧','quantangshi','','卷29','绿树莺莺语，平江燕燕飞。
枕前闻[雁去]，楼上送春归。
半月縆双脸，凝腰素一围。
西墙苔漠漠，南浦梦依依。
有恨簪花懒，无聊鬬草稀。
雕笼长惨淡，兰畹谩芳菲。
镜歛青蛾黛，灯挑皓腕肌。
避人匀迸泪，拖袖倚残晖。
有貌虽桃李，单栖足是非。
云軿载驭去，寒夜看裁衣。','',''),('quantangshi-28767','怀紫阁山','杜牧','quantangshi','','卷29','学他趋世少深机，紫阁青霄半掩扉。
山路远怀王子晋，诗家长忆谢玄晖。
百年不肯疎荣辱，双鬓终应老是非。
人道青山归去好，青山曾有几人归。','',''),('quantangshi-28768','题孙逸人山居','杜牧','quantangshi','','卷29','长悬青紫与芳枝，尘刹无应免别离。
马上多于在家日，罇前堪忆少年时。
关河客梦还乡远，雨雪山程出店迟。
却羡高人终此老，轩车过尽不知谁。','',''),('quantangshi-28769','中途寄友人','杜牧','quantangshi','','卷29','道傍高木尽依依，落叶惊风处处飞。
未到乡关闻早雁，独于客路授寒衣。
烟霞旧想长相阻，书劒投人久不归。
何日一名随事了，与君同采碧溪薇。','',''),('quantangshi-28770','怅诗','杜牧','quantangshi','','卷29','自是寻春去校迟，不须惆怅怨芳时。
狂风落尽深红色，绿叶成阴子满枝。','',''),('quantangshi-28771','吴宫词二首 一','杜牧','quantangshi','','卷29','越兵驱绮罗，越女唱吴歌。
宫烬花声少，台荒麋迹多。
茱萸垂晓露，菡萏落秋波。
无遣君王醉，满城嚬翠蛾。','',''),('quantangshi-28772','吴宫词二首 二','杜牧','quantangshi','','卷29','香迳遶吴宫，千帆落照中。
鹤鸣山苦雨，鱼跃水多风。
城带晚莎绿，池连秋蓼红。
当年国门外，谁信伍员忠。','',''),('quantangshi-28773','金陵','杜牧','quantangshi','','卷29','始发碧江口，旷然谐远心。
风清舟在鉴，日落水浮金。
瓜步逢潮信，台城过雁音。
故乡何处是，云外即乔林。','',''),('quantangshi-28774','即事','杜牧','quantangshi','','卷29','小院无人雨长苔，满庭修竹间疎槐。
春愁兀兀成幽梦，又被流莺唤醒来。','',''),('quantangshi-28775','七夕','杜牧','quantangshi','','卷29','云堦月地一相过，未抵经年别恨多。
最恨明朝洗车雨，不教回脚渡天河。','',''),('quantangshi-28776','蔷薇花','杜牧','quantangshi','','卷29','朵朵精神叶叶柔，雨晴香拂醉人头。
石家锦幛依然在，闲倚狂风夜不收。','',''),('quantangshi-28777','句','杜牧','quantangshi','','卷29','幽人听达曙，聊罢苏牀琴。
鱼多知海熟，药少觉山贫。
土控吴兼越，州连歙与池。
山河地襟带，军镇国藩维。
绿水棹云月，洞庭归路长。
春桥垂酒幔，夜栅集茶樯。
箬影沈溪暖，苹花遶郭香。
经冬野菜青青色，未腊山梅树树花。
半破前峰月。','',''),('quantangshi-28778','陪王尚书泛舟莲池','許渾','quantangshi','','卷29','莲塘移画舸，泛泛日华清。
水暖鱼频跃，烟秋雁早鸣。
舞疑回雪态，歌转遏云声。
客散山公醉，风高月满城。','',''),('quantangshi-28779','赠裴处士','許渾','quantangshi','','卷29','为儒白发生，乡里早闻名。
暖酒雪初下，读书山欲明。
字形翻鸟迹，诗调合猿声。
门外沧浪水，知君欲濯缨。','',''),('quantangshi-28780','对雪','許渾','quantangshi','','卷29','飞舞北风凉，玉人歌玉堂。
帘帷增曙色，珠翠发寒光。
柳重絮微湿，梅繁花未香。
兹辰贺丰岁，箫鼓宴梁王。','',''),('quantangshi-28781','王居士','許渾','quantangshi','','卷29','筇杖倚柴关，都城卖卜还。
雨中耕白水，云外斸青山。
有药身长健，无机性自闲。
即应生羽翼，华表在人间。','',''),('quantangshi-28782','早秋三首 一','許渾','quantangshi','','卷29','遥夜泛清瑟，西风生翠萝。
残萤委玉露，早雁拂银河。
高树晓还密，远山晴更多。
淮南一叶下，自觉老烟波。','',''),('quantangshi-28783','早秋三首 二','許渾','quantangshi','','卷29','一叶下前墀，淮南人已悲。
蹉跎青汉望，迢遰白云期。
老信相如渴，贫忧曼倩饥。','',''),('quantangshi-28784','早秋三首 三','許渾','quantangshi','','卷29','蓟北雁犹远，淮南人已悲。
残桃间堕井，新菊亦侵篱。
书劒岂相误，琴尊聊自持。
西斋风雨夜，更有咏贫诗。','',''),('quantangshi-28785','洛东兰若夜归','許渾','quantangshi','','卷29','一衲老禅牀，吾生半异乡。
管弦愁里老，书劒梦中忙。
鸟急山初暝，蝉稀树正凉。
又归何处去，尘路月苍苍。','',''),('quantangshi-28786','送段觉归杜曲闲居','許渾','quantangshi','','卷29','书劒南归去，山扉别几年。
苔侵岩下路，果落洞中泉。
红叶高斋雨，青萝曲槛烟。
宁知远游客，羸马太行前。','',''),('quantangshi-28787','寄天乡寺仲仪上人富春孙处士','許渾','quantangshi','','卷29','诗僧与钓翁，千里两情通。
云带雁门雪，水连渔浦风。
心期荣辱外，名挂是非中。
岁晚亦归去，田园清洛东。','',''),('quantangshi-28788','寄契盈上人','許渾','quantangshi','','卷29','何处是西林，疎钟复远砧。
雁来秋水阔，鸦尽夕阳沈。
婚嫁乖前志，功名异夙心。
汤师不可问，江上碧云深。','',''),('quantangshi-28789','晨起二首 一','許渾','quantangshi','','卷29','桂树绿层层，风微烟露凝。
檐楹衔落月，帏幌映残灯。
蕲簟曙香冷，越瓶秋水澄。
心闲即无事，何异住山僧。','',''),('quantangshi-28790','晨起二首 二','許渾','quantangshi','','卷29','残月皓烟露，掩门深竹斋。
水虫鸣曲槛，山鸟下空阶。
清镜晓看髪，素琴秋寄怀。
因知北窗客，日与世情乖。','',''),('quantangshi-28791','晓发鄞江北渡寄崔韩二先辈','許渾','quantangshi','','卷29','南北信多岐，生涯半别离。
地穷山尽处，江泛水寒时。
露晓蒹葭重，霜晴橘柚垂。
无劳促回檝，千里有心期。','',''),('quantangshi-28792','盈上人','許渾','quantangshi','','卷29','月沈霜已凝，无梦竟寒灯。
寄世何殊客，修身未到僧。
二毛梳上雪，双泪枕前冰。
借问曹溪路，山多路几层。','',''),('quantangshi-28793','广陵道中','許渾','quantangshi','','卷29','城势已坡陀，城边东逝波。
绿桑非苑树，青草是宫莎。
山暝牛羊少，水寒凫雁多。
因高一回首，还咏黍离歌。','',''),('quantangshi-28794','宿开元寺楼','許渾','quantangshi','','卷29','谁家歌褭褭，孤枕在西楼。
竹色寒清簟，松香染翠帱。
月移珠殿晓，风遰玉筝秋。
日出应移棹，三湘万里愁。','',''),('quantangshi-28795','洞灵观冬青','許渾','quantangshi','','卷29','霜霰不凋色，两株交石坛。
未秋红实浅，经夏绿阴寒。
露重蝉鸣急，风多鸟宿难。
何如西禁柳，晴舞玉阑干。','',''),('quantangshi-28796','送友人自荆襄归江东','許渾','quantangshi','','卷29','商洛转江濆，一杯聊送君。
劒愁龙失伴，琴怨鹤离羣。
楚驿枕秋水，湘帆凌暮云。
猿声断肠夜，应向雨中闻。','',''),('quantangshi-28797','送同年崔先辈','許渾','quantangshi','','卷29','西风帆势轻，南浦遍离情。
菊艳含秋水，荷花遰雨声。
扣舷滩鸟没，移棹草虫鸣。
更忆前年别，槐花满凤城。','',''),('quantangshi-28798','山鸡','許渾','quantangshi','','卷29','珍禽暂不扃，飞舞跃前庭。
翠网摧金距，雕笼减绣翎。
月圆疑望镜，花暖似依屏。
何必旧巢去，山山芳草青。','',''),('quantangshi-28799','孤雁','許渾','quantangshi','','卷29','昔年双颉颃，池上霭春晖。
霄汉力犹怯，稻粱心已违。
芦洲寒独宿，榆塞夜孤飞。
不及营巢燕，西风相伴归。','',''),('quantangshi-28800','寓怀','許渾','quantangshi','','卷29','南国浣纱伴，盈盈天下姝。
盘金明绣带，动佩响罗襦。
素手怨瑶瑟，清心悲玉壶。
春华坐销落，未忍泣蘼芜。','',''),('quantangshi-28801','洛中游眺贻同志','許渾','quantangshi','','卷29','康衢一望通，河洛正天中。
楼势排高凤，桥形架断虹。
远山晴带雪，寒水晚多风。
几日还携手，鸟鸣花满宫。','',''),('quantangshi-28802','夏日戏题郭别驾东堂','許渾','quantangshi','','卷29','微风起画鸾，金翠暗珊珊。
晚树垂朱实，春篁露粉竿。
散香蕲簟滑，沈水越瓶寒。
犹恐何郎热，冰生白玉盘。','',''),('quantangshi-28803','长安旅夜','許渾','quantangshi','','卷29','久客怨长夜，西风吹雁声。
云移河汉浅，月泛露华清。
掩瑟独凝思，缓歌空寄情。
门前有归路，迢遰洛阳城。','',''),('quantangshi-28804','鸂鶒','許渾','quantangshi','','卷29','池寒柳复凋，独宿夜迢迢。
雨顶冠应冷，风毛劒欲飘。
故巢迷碧水，旧侣越丹霄。
不是无归处，心高多寂寥。','',''),('quantangshi-28805','懿安皇太后挽歌词','許渾','quantangshi','','卷29','陵前春不尽，陵下夜何穷。
未信金蚕老，先惊玉燕空。
挽移兰殿月，笳引柏城风。
自此随龙驭，桥山翠霭中。','',''),('quantangshi-28806','示弟','許渾','quantangshi','','卷29','自尔出门去，泪痕长满衣。
家贫为客早，路远得书稀。
文字何人赏，烟波几日归。
秋风正摇落，孤雁又南飞。','',''),('quantangshi-28807','送杨处士叔初卜居曲江','許渾','quantangshi','','卷29','雁门归去远，垂老脱袈裟。
萧寺休为客，曹溪便寄家。
绿琪千岁树，黄槿四时花。
别怨应无限，门前桂水斜。','',''),('quantangshi-28808','发灵溪馆','許渾','quantangshi','','卷29','山多水不穷，一叶似渔翁。
鸟浴寒潭雨，猿吟暮岭风。
杂英垂锦绣，众籁合丝桐。
应有曹溪路，千岩万壑中。','',''),('quantangshi-28809','题杜居士','許渾','quantangshi','','卷29','松偃石牀平，何人识姓名。
溪冰寒棹响，岩雪夜窗明。
机尽心猿伏，神闲意马行。
应知此来客，身世两无情。','',''),('quantangshi-28810','神女祠','許渾','quantangshi','','卷29','停车祀圣女，凉叶下阴风。
龙气石牀湿，鸟声山庙空。
长眉留桂绿，丹脸寄莲红。
莫学阳台畔，朝云暮雨中。','',''),('quantangshi-28811','送李定言南游','許渾','quantangshi','','卷29','酒酣轻别恨，酒醒复离忧。
远水应移棹，高峯更上楼。
簟凉清露夜，琴响碧天秋。
重惜芳尊宴，满城无旧游。','',''),('quantangshi-28812','早发中岩寺别契直上人','許渾','quantangshi','','卷29','苍苍松桂阴，残月半西岑。
素壁寒灯暗，红炉夜火深。
厨开山鼠散，钟尽岭猿吟。
行役方如此，逢师嬾话心。','',''),('quantangshi-28813','行次潼关题驿后轩','許渾','quantangshi','','卷29','飞阁极层台，终南此路回。
山形朝阙去，河势抱关来。
雁过秋风急，蝉鸣宿雾开。
平生无限意，驱马任尘埃。','',''),('quantangshi-28814','晨至南亭呈裴明府','許渾','quantangshi','','卷29','南斋梦钓竿，晨起月犹残。
露重萤依草，风高蝶委兰。
池光秋镜澈，山色晓屏寒。
更恋陶彭泽，无心议去官。','',''),('quantangshi-28815','灞东题司马郊园','許渾','quantangshi','','卷29','楚翁秦塞住，昔事李轻车。
白社贫思橘，青门老仰瓜。
读书三迳草，沽酒一篱花。
更欲寻芝术，商山便寄家。','',''),('quantangshi-28816','游维山新兴寺宿石屏村谢叟家','許渾','quantangshi','','卷29','晚过石屏村，村长日渐曛。
僧归下岭见，人语隔溪闻。
谷响寒耕雪，山明夜烧云。
家家扣铜鼓，欲赛鲁将军。','',''),('quantangshi-28817','送从兄归隐蓝溪二首 一','許渾','quantangshi','','卷29','名高犹素衣，穷巷掩荆扉。
渐老故人少，久贫豪客稀。
塞云横劒望，山月抱琴归。
几日蓝溪醉，藤花拂钓矶。','',''),('quantangshi-28818','送从兄归隐蓝溪二首 二','許渾','quantangshi','','卷29','京洛多高盖，怜兄剧断蓬。
身随一劒老，家入万山空。
夜忆萧关月，行悲易水风。
无人知此意，甘卧白云中。','',''),('quantangshi-28819','村舍','許渾','quantangshi','','卷29','燕雁下秋塘，田家自此忙。
移蔬通远水，收果待繁霜。
野碓舂秔滑，山厨焙茗香。
客来还有酒，随事宿茅堂。','',''),('quantangshi-28820','思归','許渾','quantangshi','','卷29','叠嶂平芜外，依依识旧邦。
气高诗易怨，愁极酒难降。
树暗支公院，山寒谢守窗。
殷勤楼下水，几日到荆江。','',''),('quantangshi-28821','晚泊七里滩','許渾','quantangshi','','卷29','天晚日沈沈，归舟系柳阴。
江村平见寺，山郭远闻砧。
树密猿声响，波澄雁影深。
荣华暂时事，谁识子陵心。','',''),('quantangshi-28822','寄题南山王隐居','許渾','quantangshi','','卷29','近逢商洛客，知尔住南塘。
草阁平春水，柴门掩夕阳。
随蜂收野蜜，寻麝采生香。
更忆前年醉，松花满石牀。','',''),('quantangshi-28823','晨装','許渾','quantangshi','','卷29','带月饭行侣，西游关塞长。
晨鸡鸣远戍，宿雁起寒塘。
云卷四山雪，风凝千树霜。
谁家游侠子，沈醉卧兰堂。','',''),('quantangshi-28824','题韦隐居西斋','許渾','quantangshi','','卷29','斸药去还归，家人半掩扉。
山风藤子落，溪雨豆花肥。
寺远僧来少，桥危客到稀。
不闻砧杵动，应解制荷衣。','',''),('quantangshi-28825','送李溟秀才西行','許渾','quantangshi','','卷29','万里不辞劳，寒装叠緼袍。
停车山店雨，挂席海门涛。
鹰势暮偏急，鹤声秋更高。
知君北邙路，留劒泣黄蒿。','',''),('quantangshi-28826','经马镇西宅','許渾','quantangshi','','卷29','将军久已没，行客自兴哀。
功业山长在，繁华水不回。
乱藤侵废井，荒菊上丛台。
借问此中事，几家歌舞来。','',''),('quantangshi-28827','重游郁林寺道玄上人院','許渾','quantangshi','','卷29','藤杖叩松关，春溪斸药还。
雨晴巢燕急，波暖浴鸥闲。
倚槛花临水，回舟月照山。
忆归师莫笑，书劒在人间。','',''),('quantangshi-28828','泛溪','許渾','quantangshi','','卷29','疑与武陵通，青溪碧嶂中。
水寒深见石，松晚静闻风。
遯迹驱鸡吏，冥心失马翁。
才应毕婚嫁，还此息微躬。','',''),('quantangshi-28829','送楼烦李别驾','許渾','quantangshi','','卷29','琴清诗思劳，更欲学龙韬。
王粲暂停笔，吕虔初佩刀。
夜吟关月静，秋望塞云高。
去去从军乐，雕飞代马豪。','',''),('quantangshi-28830','闻两河用兵因贻友人','許渾','quantangshi','','卷29','故人日已远，身事与谁论。
性拙难趋世，心孤易感恩。
秋悲怜宋玉，夜舞笑刘琨。
徒有干时策，青山尚掩门。','',''),('quantangshi-28831','献白尹','許渾','quantangshi','','卷29','醉舞任生涯，褐宽乌帽斜。
庾公先在郡，疎傅早还家。
林晚鸟争树，园春蜂护花。
高吟应更逸，嵩洛旧烟霞。','',''),('quantangshi-28832','茅山赠梁尊师','許渾','quantangshi','','卷29','云屋何年客，青山白日长。
种花春扫雪，看箓夜焚香。
上象壶中阔，平生梦里忙。
幸承仙籍后，乞取大还方。','',''),('quantangshi-28833','闻薛先辈陪大夫看早梅因寄','許渾','quantangshi','','卷29','涧梅寒正发，莫信笛中吹。
素艳雪凝树，清香风满枝。
折惊山鸟散，携任野蜂随。
今日从公醉，何人倒接䍦。','',''),('quantangshi-28834','送前缑氏韦明府南游','許渾','quantangshi','','卷29','酒阑横劒歌，日暮望关河。
道直去官早，家贫为客多。
山昏函谷雨，木落洞庭波。
莫尽远游兴，故园荒薜萝。','',''),('quantangshi-28835','看雪','許渾','quantangshi','','卷29','松亚竹珊珊，心知万井欢。
山明迷旧径，溪满涨新澜。
客醉瑶台曙，兵防玉塞寒。
红楼知有酒，谁肯学袁安。','',''),('quantangshi-28836','赠僧','許渾','quantangshi','','卷29','心法本无住，流沙归复来。
锡随山鸟动，经附海船回。
洗足柳遮寺，坐禅花委苔。
唯将一童子，又欲上天台。','',''),('quantangshi-28837','趋慈和寺移宴','許渾','quantangshi','','卷29','高寺移清宴，渔舟系绿萝。
潮平秋水阔，云歛暮山多。
广槛停箫鼓，繁弦散绮罗。
西楼半牀月，莫问夜如何。','',''),('quantangshi-28838','留赠偃师主人','許渾','quantangshi','','卷29','孤城漏未残，徒侣拂征鞍。
洛北去游远，淮南归梦阑。
晓灯回壁暗，晴雪卷帘寒。
强尽主人酒，出门行路难。','',''),('quantangshi-28839','送南陵李少府','許渾','quantangshi','','卷29','高人亦未闲，来往楚云间。
劒在心应壮，书穷鬓已斑。
落帆秋水寺，驱马夕阳山。
明日南昌尉，空斋又掩关。','',''),('quantangshi-28840','别韦处士','許渾','quantangshi','','卷29','南北断蓬飞，别多相见稀。
更伤今日酒，未换昔年衣。
旧友几人在，故乡何处归？
秦原向西路，云晚雪霏霏。','',''),('quantangshi-28841','九日登樟亭驿楼','許渾','quantangshi','','卷29','鲈鲙与蒪羹，西风片席轻。
潮回孤岛晚，云歛众山晴。
丹羽下高阁，黄花垂古城。
因秋倍多感，乡树接咸京。','',''),('quantangshi-28842','再游越中伤朱余庆协律好直上人','許渾','quantangshi','','卷29','昔年湖上客，留访雪山翁。
王氏船犹在，萧家寺已空。
月高花有露，烟合水无风。
处处多遗韵，何曾入剡中。','',''),('quantangshi-28843','京口津亭送张崔二侍御','許渾','quantangshi','','卷29','爱树满西津，津亭堕泪频。
素车应度洛，珠履更归秦。
水接三湘暮，山通五岭春。
伤离与怀旧，明日白头人。','',''),('quantangshi-28844','江楼夜别','許渾','quantangshi','','卷29','离别奈情何，江楼凝艳歌。
蕙兰秋露重，芦苇夜风多。
深怨寄清瑟，远愁生翠蛾。
酒酣相顾起，明月棹寒波。','',''),('quantangshi-28845','送惟素上人归新安','許渾','quantangshi','','卷29','山空叶复落，一迳下新安。
风急渡溪晚，雪晴归寺寒。
寻云策藤杖，向日倚蒲团。
宁忆西游客，劳劳歌路难。','',''),('quantangshi-28846','霅上宴别','許渾','quantangshi','','卷29','山断水茫茫，洛人西路长。
笙歌留远棹，风雨寄华堂。
红壁耿秋烛，翠帘凝晓香。
谁堪从此去，云树满陵阳。','',''),('quantangshi-28847','下第别友人杨至之','許渾','quantangshi','','卷29','花落水潺潺，十年离旧山。
夜愁添白发，春泪减朱颜。
孤劒北游塞，远书东出关。
逢君话心曲，一醉灞陵间。','',''),('quantangshi-28848','寻戴处士','許渾','quantangshi','','卷29','车马长安道，谁知大隐心。
蛮僧留古镜，蜀客寄新琴。
晒药竹斋暖，捣茶松院深。
思君一相访，残雪似山阴。','',''),('quantangshi-28849','放猿','許渾','quantangshi','','卷29','殷勤解金锁，昨夜雨凄凄。
山浅忆巫峡，水寒思建溪。
远寻红树宿，深向白云啼。
好觅来时路，烟萝莫共迷。','',''),('quantangshi-28850','将离郊园留示弟侄','許渾','quantangshi','','卷29','身贱与心违，秋风生旅衣。
久贫辞国远，多病在家稀。
山暝客初散，树凉人未归。
西都万余里，明旦别柴扉。','',''),('quantangshi-28851','夜归丁卯桥村舍','許渾','quantangshi','','卷29','月凉风静夜，归客泊岩前。
桥响犬遥吠，庭空人散眠。
紫蒲低水槛，红叶半江船。
自有还家计，南湖二顷田。','',''),('quantangshi-28852','题青山馆','許渾','quantangshi','','卷29','昔人诗酒地，芳草思王孙。
白水半塘岸，青山横郭门。
悬岩碑已折，盘石井犹存。
无处继行乐，野花空一尊。','',''),('quantangshi-28853','秋日众哲馆对竹','許渾','quantangshi','','卷29','萧萧凌雪霜，浓翠异三湘。
疎影月移壁，寒声风满堂。
卷帘秋更早，高枕夜偏长。
忽忆秦溪路，万竿今正凉。','',''),('quantangshi-28854','春日题韦曲野老村舍二首 一','許渾','quantangshi','','卷29','遶屋遍桑麻，村南第一家。
林繁树势直，溪转水纹斜。
竹院昼看笋，药栏春卖花。
故园归未得，到此是天涯。','',''),('quantangshi-28855','春日题韦曲野老村舍二首 二','許渾','quantangshi','','卷29','北岭枕南塘，数家村落长。
莺啼幼妇嬾，蚕出小姑忙。
烟草近沟湿，风花临路香。
自怜非楚客，春望亦心伤。','',''),('quantangshi-28856','崇圣寺别杨至之','許渾','quantangshi','','卷29','萧寺暂相逢，离忧满病容。
寒斋秋少燕，阴壁夜多蛩。
树暗水千里，山深云万重。
怀君在书信，莫过雁回峯。','',''),('quantangshi-28857','途经李翰林墓','許渾','quantangshi','','卷29','气逸何人识，才高举世疑。
禰生狂善赋，陶令醉能诗。
碧水鲈鱼思，青山鵩鸟悲。
至今孤冢在，荆棘楚江湄。','',''),('quantangshi-28858','严陵钓台贻行侣','許渾','quantangshi','','卷29','故人天下定，垂钓碧岩幽。
旧迹随台古，高名寄水流。
鸟喧羣木晚，蝉急众山秋。
更待新安月，凭君暂驻舟。','',''),('quantangshi-28859','南楼春望','許渾','quantangshi','','卷29','南楼春一望，云水共昏昏。
野店归山路，危桥带郭村。
晴烟和草色，夜雨长溪痕。
下岸谁家住，残阳半掩门。','',''),('quantangshi-28860','送无梦道人先归甘露寺','許渾','quantangshi','','卷29','飘飘随晚浪，杯影入鸥羣。
岸冻千船雪，岩阴一寺云。
夜灯江北见，寒磬水西闻。
鹤岭烟霞在，归期不羡君。','',''),('quantangshi-28861','闲居孟夏即事','許渾','quantangshi','','卷29','绿树荫青苔，柴门临水开。
簟凉初熟麦，枕腻乍经梅。
鱼跃海风起，鼍鸣江雨来。
佳人竟何处，日夕上楼台。','',''),('quantangshi-28862','题灞西骆隐士','許渾','quantangshi','','卷29','磻溪连灞水，商岭接秦山。
青汉不回驾，白云长掩关。
雀喧知鹤静，凫戏识鸥闲。
却笑南昌尉，悠悠城市间。','',''),('quantangshi-28863','溪亭二首 一','許渾','quantangshi','','卷29','溪亭四面山，横柳半溪湾。
蝉响螳螂急，鱼深翡翠闲。
水寒留客醉，月上与僧还。
犹恋萧萧竹，西斋未掩关。','',''),('quantangshi-28864','溪亭二首 二','許渾','quantangshi','','卷29','暖枕眠溪柳，僧斋昨夜期。
茶香秋梦后，松韵晚吟时。
共戏鱼翻藻，争栖鸟坠枝。
重阳应一醉，栽菊助东篱。','',''),('quantangshi-28865','秋日赴阙题潼关驿楼','許渾','quantangshi','','卷29','红叶晚萧萧，长亭酒一瓢。
残云归太华，疎雨过中条。
树色随山迥，河声入海遥。
帝乡明日到，犹自梦渔樵。','',''),('quantangshi-28866','吴门送客早发','許渾','quantangshi','','卷29','吴歌咽深思，楚客怨归程。
寺晓楼台迥，江秋管吹清。
早潮低水槛，残月下山城。
惆怅回舟日，湘南春草生。','',''),('quantangshi-28867','送太昱禅师','許渾','quantangshi','','卷29','禅牀深竹里，心与径山期。
结社多高客，登坛尽小师。
早秋归寺远，新雨上滩迟。
别后江云碧，南斋一首诗。','',''),('quantangshi-28868','旅怀','許渾','quantangshi','','卷29','征车何轧轧，南北极天涯。
孤枕易为客，远书难到家。
乡连云外树，城闭月中花。
犹有扁舟思，前年别若耶。','',''),('quantangshi-28869','南亭与首公宴集','許渾','quantangshi','','卷29','秋来水上亭，几处似岩扃。
戏鸟翻江叶，游龟带绿萍。
管弦心戚戚，罗绮鬓星星。
行乐非吾事，西斋尚有萤。','',''),('quantangshi-28870','早发寿安次永寿渡','許渾','quantangshi','','卷29','东西车马尘，巩洛与咸秦。
山月夜行客，水烟朝渡人。
树凉风皓皓，滩浅石磷磷。
会待功名就，扁舟寄此身。','',''),('quantangshi-28871','泊松江渡','許渾','quantangshi','','卷29','漠漠故宫地，月凉风露幽。
鸡鸣荒戍晓，雁过古城秋。
杨柳北归路，蒹葭南渡舟。
去乡今已远，更上望京楼。','',''),('quantangshi-28872','送鱼思别处士归有怀','許渾','quantangshi','','卷29','宴罢众宾散，长歌携一巵。
溪亭相送远，山郭独归迟。
风槛夕云散，月轩寒露滋。
病来双鬓白，不是旧离时。','',''),('quantangshi-28873','重经姑苏怀古二首 一','許渾','quantangshi','','卷29','越兵驱绮罗，越女唱吴歌。
宫尽燕声少，台荒麋迹多。
茱萸垂晓露，菡萏落秋波。
无复君王醉，满城颦翠蛾。','',''),('quantangshi-28874','重经姑苏怀古二首 二','許渾','quantangshi','','卷29','香迳遶吴宫，千帆落照中。
鹳鸣山欲雨，鱼跃水多风。
城带晚莎绿，池连秋蓼红。
当年国门外，谁识伍员忠。','',''),('quantangshi-28875','将赴京师留题孙处士山居二首 一','許渾','quantangshi','','卷29','草堂近西郭，遥对敬亭开。
枕腻海云起，簟凉山雨来。
高歌怀地肺，远赋忆天台。
应学相如志，终须驷马回。','',''),('quantangshi-28876','将赴京师留题孙处士山居二首 二','許渾','quantangshi','','卷29','西岩有高兴，路僻几人知。
松荫花开晚，山寒酒熟迟。
游从随野鹤，休息遇灵龟。
长见邻翁说，容华似旧时。','',''),('quantangshi-28877','下第寓居崇圣寺感事','許渾','quantangshi','','卷29','怀土泣京华，旧山归路赊。
静依禅客院，幽学野人家。
林晚鸟争树，园春蝶护花。
东门有闲地，谁种邵平瓜。','',''),('quantangshi-28878','晓发天井关寄李师晦','許渾','quantangshi','','卷29','山在水滔滔，流年欲二毛。
湘潭归梦远，燕赵客程劳。
露晓红兰重，云晴碧树高。
逢秋正多感，万里别同袍。','',''),('quantangshi-28879','喜远书','許渾','quantangshi','','卷29','端居换时节，离恨隔龙泷。
苔色上春阁，柳阴移晚窗。
寄怀因桂水，流泪极枫江。
此日南来使，金盘鱼一双。','',''),('quantangshi-28880','怀江南同志','許渾','quantangshi','','卷29','南国别经年，云晴波接天。
蒲深鸂鶒戏，花暖鹧鸪眠。
竹暗湘妃庙，枫阴楚客船。
唯应洞庭月，万里共婵娟。','',''),('quantangshi-28881','洛中秋日','許渾','quantangshi','','卷29','故国无归处，官闲忆远游。
吴僧秣陵寺，楚客洞庭舟。
久病先知雨，长贫早觉秋。
壮心能几许，伊水更东流。','',''),('quantangshi-28882','将赴京师蒜山津送客还荆渚','許渾','quantangshi','','卷29','尊前万里愁，楚塞与皇州。
云识潇湘雨，风知鄠杜秋。
潮平犹倚棹，月上更登楼。
他日沧浪水，渔歌对白头。','',''),('quantangshi-28883','潼关兰若','許渾','quantangshi','','卷29','来往几经过，前轩枕大河。
远帆春水阔，高寺夕阳多。
蝶影下红药，鸟声喧绿萝。
故山归未得，徒咏采芝歌。','',''),('quantangshi-28884','翫残雪寄江南尹刘大夫','許渾','quantangshi','','卷29','艳阳无处避，皎洁不成容。
素质添瑶水，清光散玉峯。
眠鸥犹恋草，栖鹤未离松。
闻在金銮望，羣仙对九重。','',''),('quantangshi-28885','陪越中使院诸公镜波馆饯明台裴郑二使君','許渾','quantangshi','','卷29','倾幕来华馆，淹留二使君。
舞移清夜月，歌断碧空云。
海郡楼台接，江船劒戟分。
明时自骞翥，无复叹离羣。','',''),('quantangshi-28886','春泊弋阳','許渾','quantangshi','','卷29','江行春欲半，孤枕弋阳堤。
云暗犹飘雪，潮寒未应溪。
饮猿闻棹散，飞鸟背船低。
此路成幽绝，家山巩洛西。','',''),('quantangshi-28887','晨别翛然上人','許渾','quantangshi','','卷29','吴僧诵经罢，败衲倚蒲团。
钟韵花犹歛，楼阴月向残。
晴山开殿响，秋水卷帘寒。
独恨孤舟去，千滩复万滩。','',''),('quantangshi-28888','送客江行','許渾','quantangshi','','卷29','萧萧芦荻花，郢客独辞家。
远棹依山响，危樯转浦斜。
水寒澄浅石，潮落涨虚沙。
莫与征徒望，乡园去渐赊。','',''),('quantangshi-28889','将归涂口宿郁林寺道玄上人院二首 一','許渾','quantangshi','','卷29','西岩一磬长，僧起树苍苍。
开殿洒寒水，诵经焚晚香。
竹风云渐散，杉露月犹光。
无复重来此，归舟凌夕阳。','',''),('quantangshi-28890','将归涂口宿郁林寺道玄上人院二首 二','許渾','quantangshi','','卷29','春寻采药翁，归路宿禅宫。
云起客眠处，月残僧定中。
藤花深洞水，槲叶满山风。
清境不能住，朝朝慙远公。','',''),('quantangshi-28891','题宣州元处士幽居','許渾','quantangshi','','卷29','潺湲遶门水，未省濯缨尘。
鸟散千岩曙，蜂来一迳春。
杉松还待客，芝术不求人。
宁学磻溪叟，逢时罢隐沦。','',''),('quantangshi-28892','送李秀才','許渾','quantangshi','','卷29','南楼送郢客，西郭见荆门。
凫鹄下寒渚，牛羊归远村。
兰舟倚行掉，桂酒掩余尊。
重此一留宿，前村烟水昏。','',''),('quantangshi-28893','题倪处士旧居','許渾','quantangshi','','卷29','儒翁九十余，旧向此山居。
生寄一壶酒，死留千卷书。
槛摧新竹少，池浅故莲疎。
但有子孙在，带经还荷锄。','',''),('quantangshi-28894','赠梁将军','許渾','quantangshi','','卷29','曾经黑山虏，一劒出重围。
年长穷书意，时清隐钓矶。
高斋云外住，瘦马月中归。
唯说乡心苦，春风雁北飞。','',''),('quantangshi-28895','春望思旧游','許渾','quantangshi','','卷29','适意极春日，南台披薜萝。
花光晴漾漾，山色昼峨峨。
湘水美人远，信陵豪客多。
唯凭一瓢酒，弹瑟纵高歌。','',''),('quantangshi-28896','病中二首 一','許渾','quantangshi','','卷29','三年婴酒渴，高卧似袁安。
秋色鬓应改，夜凉心已宽。
风衣藤簟滑，露井竹牀寒。
卧忆郊扉月，恩深未挂冠。','',''),('quantangshi-28897','病中二首 二','許渾','quantangshi','','卷29','私归人暂适，扶杖遶西林。
风急柳溪响，露寒莎径深。
一身仍白发，万虑只丹心。
此意无言处，高窗托素琴。','',''),('quantangshi-28898','姑熟官舍寄汝洛友人','許渾','quantangshi','','卷29','[官]静亦无能，平生少面朋。
务开唯印吏，公退只棊僧。
药鼎初寒火，书龛欲夜灯。
安知北溟水，终日送抟鹏。','',''),('quantangshi-28899','恩德寺','許渾','quantangshi','','卷29','楼台横复重，犹有半岩空。
萝洞浅深水，竹廊高下风。
晴山疎雨后，秋树断云中。
未尽平生意，孤帆又向东。','',''),('quantangshi-28900','天竺寺题葛洪井','許渾','quantangshi','','卷29','羽客炼丹井，井留人已无。
旧泉青石下，余甃碧山隅。
云朗镜开匣，月寒冰在壶。
仍闻酿仙酒，此水过琼酴。','',''),('quantangshi-28901','朗上人院晨坐','許渾','quantangshi','','卷29','簟凉襟袖清，月没尚残星。
山果落秋院，水花开晓庭。
疎藤风袅袅，圆桂露冥冥。
正忆江南寺，岩斋闻诵经。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-28902','送客归湘楚','許渾','quantangshi','','卷29','无辞一杯酒，昔日与君深。
秋色换归鬓，曙光生别心。
桂花山庙冷，枫树水楼阴。
此路千余里，应劳楚客吟。','',''),('quantangshi-28903','过故友旧居','許渾','quantangshi','','卷29','往年公子宅，夜宴乐难忘。
高竹动疎翠，早莲飘暗香。
珠盘凝宝瑟，绮席遰华觞。
今日皆何处，闭门春草长。','',''),('quantangshi-28904','送客归峡中','許渾','quantangshi','','卷29','津亭多别离，杨柳半无枝。
住接猿啼处，行逢雁过时。
江风扬帆急，山月下楼迟。
还就西斋宿，烟波劳梦思。','',''),('quantangshi-28905','题冲沼上人院','許渾','quantangshi','','卷29','斸石种松子，数根侵杳冥。
天寒犹讲律，雨暗尚寻经。
小殿灯千盏，深炉水一瓶。
碧云多别思，休到望溪亭。','',''),('quantangshi-28906','和毕员外雪中见寄','許渾','quantangshi','','卷29','仙署淹清景，雪华松桂阴。
夜凌瑶席宴，春寄玉京吟。
烛晃垂罗幙，香寒重绣衾。
相思不相访，烟月剡溪深。','',''),('quantangshi-28907','春醉','許渾','quantangshi','','卷29','酒醲花一树，何暇卓文君。
客坐长先饮，公闲半已曛。
水乡春足雨，山郭夜多云。
何似参禅理，荣枯尽不闻。','',''),('quantangshi-28908','题岫上人院','許渾','quantangshi','','卷29','病客与僧闲，频来不掩关。
高窗云外树，疎磬雨中山。
离索秋虫响，登临夕鸟还。
心知落帆处，明日淛河湾。','',''),('quantangshi-28909','送客南归有怀','許渾','quantangshi','','卷29','绿水暖青苹，湘潭万里春。
瓦尊迎海客，铜鼓赛江神。
避雨松枫岸，看云杨柳津。
长安一杯酒，座上有归人。','',''),('quantangshi-28910','李生弃官入道因寄','許渾','quantangshi','','卷29','西岩一径通，知学采芝翁。
寒暑丹心外，光阴白发中。
水深鱼避钓，云迥鹤辞笼。
坐想还家日，人非井邑空。','',''),('quantangshi-28911','长兴里夏日南邻避暑','許渾','quantangshi','','卷29','侯门大道傍，蝉噪树苍苍。
开鏁洞门远，下帘宾馆凉。
栏围红药盛，架引绿萝长。
永日一欹枕，故山云水乡。','',''),('quantangshi-28912','送韩校书','許渾','quantangshi','','卷29','恨与前欢隔，愁因此会同。
迹高芸阁吏，名散雪楼翁。
城闭三秋雨，帆飞一夜风。
酒醒鲈鲙美，应在竟陵东。','',''),('quantangshi-28913','秋晚登城','許渾','quantangshi','','卷29','城高不可下，永日一登临。
曲槛凉飙急，空楼返照深。
苇花迷夕棹，梧叶散秋砧。
谩作归田赋，蹉跎岁欲阴。','',''),('quantangshi-28914','江西郑常侍赴镇之日有寄因酬和','許渾','quantangshi','','卷29','来暮亦何愁，金貂在鷁舟。
斾随寒浪动，帆带夕阳收。
布令滕王阁，裁诗郢客楼。
即应归凤沼，中外赞天休。','',''),('quantangshi-28915','蒙河南刘大夫见示与吏部张公喜雪酬唱辄敢攀和','許渾','quantangshi','','卷29','风度龙山暗，云凝象阙阴。
瑞花琼树合，仙草玉苗深。
欲醉梁王酒，先调楚客琴。
即应携手去，将此助商霖。','',''),('quantangshi-28916','下第送宋秀才游岐下杨秀才还江东','許渾','quantangshi','','卷29','年来不自得，一望几伤心。
风转蕙兰色，月移松桂阴。
马随边草远，帆落海云深。
明旦各分首，更听梁甫吟。','',''),('quantangshi-28917','南亭偶题','許渾','quantangshi','','卷29','城下水萦回，潮冲野艇来。
鸟惊山果落，龟泛绿萍开。
白首书千卷，朱颜酒一杯。
南轩自流涕，不是望燕台。','',''),('quantangshi-28918','与裴三十秀才自越西归望亭阻冻登虎丘山寺精舍','許渾','quantangshi','','卷29','春草越吴间，心期旦夕还。
酒乡逢客病，诗境遇僧闲。
倚棹冰生浦，登楼雪满山。
东风不可待，归鬓坐斑斑。','',''),('quantangshi-28919','太和初靖恭里感事','許渾','quantangshi','','卷29','清湘吊屈原，垂泪撷苹蘩。
谤起乘轩鹤，机沈在槛猨。
干坤三事贵，华夏一夫冤。
宁有唐虞世，心知不为言。','',''),('quantangshi-28920','与侯春时同年南池夜话','許渾','quantangshi','','卷29','芦苇暮修修，溪禽上钓舟。
露凉花歛夕，风静竹含秋。
素志应难契，清言岂易求。
相欢一瓢酒，明日醉西楼。','',''),('quantangshi-28921','广陵送剡县薛明府赴任','許渾','quantangshi','','卷29','车马楚城壕，清歌送浊醪。
露花羞别泪，烟草让归袍。
鸟浴春塘暖，猨吟暮岭高。
寻仙在仙骨，不用废牛刀。','',''),('quantangshi-28922','游果昼二僧院','許渾','quantangshi','','卷29','何必老林泉，冥心便是禅。
讲时开院去，斋后下帘眠。
镜朗灯分焰，香销印绝烟。
真乘不可到，云尽月明天。','',''),('quantangshi-28923','题官舍','許渾','quantangshi','','卷29','燕雁水乡飞，京华信自稀。
簟瓢贫守道，书劒病忘机。
叠鼓吏初散，繁钟鸟独归。
高梧与疎柳，风雨似郊扉。','',''),('quantangshi-28924','酬报先上人登楼见寄','許渾','quantangshi','','卷29','丹叶下西楼，知君万里愁。
钟非黔峡寺，帆是敬亭舟。
山色和云暮，湖光共月秋。
天台多道侣，何惜更南游。','',''),('quantangshi-28925','晓过郁林寺戏呈李明府','許渾','quantangshi','','卷29','身闲白日长，何处不寻芳？
山崦登楼寺，溪湾泊晚樯。
洞花蜂聚蜜，岩栢麝留香。
若指求仙路，刘郎学阮郎。','',''),('quantangshi-28926','泛舟寻郁林寺道玄上人遇雨而返因寄','許渾','quantangshi','','卷29','禅扉倚石梯，云湿雨凄凄。
草色分松迳，泉声咽稻畦。
棹移滩鸟没，钟断岭猨啼。
入夜花如雪，回舟忆剡溪。','',''),('quantangshi-28927','郁林寺','許渾','quantangshi','','卷29','台殿冠嵯峨，春来日日过。
水分诸院少，云近上方多。
众籁凝丝竹，繁英耀绮罗。
酒酣诗自逸，乘月棹寒波。','',''),('quantangshi-28928','题崇圣寺','許渾','quantangshi','','卷29','西林本行殿，池榭日坡陁。
雨过水初涨，云开山渐多。
晓街垂御柳，秋院闭宫莎。
借问龙归处，鼎湖空碧波。','',''),('quantangshi-28929','赠高处士','許渾','quantangshi','','卷29','宅前云水满，高兴一书生。
垂钓有深意，望山多远情。
夜棊留客宿，春酒劝僧倾。
未作干时计，何人问姓名。','',''),('quantangshi-28930','送僧归金山寺','許渾','quantangshi','','卷29','老归江上寺，不忘旧师恩。
驻锡逢山色，停杯见浪痕。
秋涛吞楚驿，晓月上荆门。
为访题诗处，莓苔几字存。','',''),('quantangshi-28931','金谷桃花','許渾','quantangshi','','卷29','花在舞楼空，年年依旧红。
泪光停晓露，愁态倚春风。
开处妾先死，落时君亦终。
东流两三片，应在夜泉中。','',''),('quantangshi-28932','忆长洲','許渾','quantangshi','','卷29','香径小船通，菱歌遶故宫。
鱼沈秋水静，鸟宿暮山空。
荷叶桥边雨，芦花海上风。
归心无处托，高枕画屏中。','',''),('quantangshi-28933','寄殷尧藩','許渾','quantangshi','','卷29','直道知难用，经年向水滨。
宅从栽竹贵，家为买书贫。
就学多新客，登朝尽故人。
蓬莱自有路，莫羡武陵春。','',''),('quantangshi-28934','题邹处士隐居','許渾','quantangshi','','卷29','桑柘满江村，西斋接海门。
浪冲高岸响，潮入小池浑。
岩树阴棊局，山花落酒樽。
相逢亦留宿，还似识王孙。','',''),('quantangshi-28935','送僧归敬亭山寺','許渾','quantangshi','','卷29','十年劒中路，传尽本师经。
晓月下黔峡，秋风归敬亭。
开门新树绿，登阁旧山青。
遥想论禅处，松阴水一瓶。','',''),('quantangshi-28936','新卜原上居寄袁校书','許渾','quantangshi','','卷29','贫居乐游此，江海思迢迢。
雪夜书千卷，花时酒一瓢。
独愁秦树老，孤梦楚山遥。
有路应相念，风尘满黑貂。','',''),('quantangshi-28937','天街晓望','許渾','quantangshi','','卷29','明星低未央，莲阙逈苍苍。
叠鼓催残月，疎钟迎早霜。
关防浮瑞气，宫馆耀神光。
再拜为君寿，南山高且长。','',''),('quantangshi-28938','江上喜洛中亲友继至','許渾','quantangshi','','卷29','战马昔纷纷，风惊嵩少尘。
全家南渡远，旧友北来频。
罢酒松筠晚，赋诗杨柳春。
谁言今夜月，同是洛阳人。','',''),('quantangshi-28939','下第归朱方寄刘三复','許渾','quantangshi','','卷29','素衣京洛尘，归棹过南津。
故里迹犹在，旧交心更亲。
月高萧寺夜，风暖庾楼春。
诗酒应无暇，朝朝问旅人。','',''),('quantangshi-28940','送人归吴兴','許渾','quantangshi','','卷29','绿水棹云月，洞庭归路长。
春桥悬酒幔，夜栅集茶樯。
箬叶沈溪暖，苹花遶郭香。
应逢柳太守，为说过潇湘。','',''),('quantangshi-28941','月夜期友人不至','許渾','quantangshi','','卷29','坐待故人宿，月华清兴秋。
管弦谁处醉，池馆此时愁。
风过渚荷动，露含山桂幽。
孤吟不可曙，昨夜共登楼。','',''),('quantangshi-28942','白马寺不出院僧','許渾','quantangshi','','卷29','禅空心已寂，世路任多岐。
到院客长见，闭关人不知。
寺喧听讲绝，厨远送斋迟。
墙外洛阳道，东西无尽时。','',''),('quantangshi-28943','寄袁校书','許渾','quantangshi','','卷29','扰扰换时节，旧山琪树阴。
犹乖清汉志，空负白云心。
广陌埃尘远，重门管吹深。
劳歌极西望，芸省有知音。','',''),('quantangshi-28944','赠柳璟冯陶二校书','許渾','quantangshi','','卷29','霄汉两飞鸣，喧喧动禁城。
桂堂同日盛，芸阁间年荣。
香掩蕙兰气，韵高鸾鹤声。
应怜茂陵客，未有子虚名。','',''),('quantangshi-28945','王秀才自越见寻不遇题诗而回因以酬寄','許渾','quantangshi','','卷29','南斋知数宿，半为木兰开。
晴阁留诗遍，春帆载酒回。
烟深杨子宅，云断越王台。
自有孤舟兴，何妨更一来。','',''),('quantangshi-28946','秋霁潼关驿亭','許渾','quantangshi','','卷29','霁色明高巘，关河独望遥。
残云归太华，疎雨过中条。
鸟散绿萝静，蝉鸣红树凋。
何言此时节，去去任蓬飘。','',''),('quantangshi-28947','送客归兰溪','許渾','quantangshi','','卷29','花下送归客，路长应过秋。
暮随江鸟宿，寒共岭猨愁。
众水喧严濑，羣峰抱沈楼。
因君几南望，曾向此中游。','',''),('quantangshi-28948','贻终南山隐者','許渾','quantangshi','','卷29','中岩多少隐，提榼抱琴游。
潭冷薜萝晚，山香松桂秋。
瓢闲高树挂，杯急曲池流。
独有迷津客，东西南北愁。','',''),('quantangshi-28949','送李文明下第鄜州觐兄','許渾','quantangshi','','卷29','征夫天一涯，醉赠别吾诗。
雁迥参差远，龙多次第迟。
宁歌还夜苦，宋赋更秋悲。
的的遥相待，清风白露时。','',''),('quantangshi-28950','送段觉归东阳兼寄窦使君','許渾','quantangshi','','卷29','山水引归路，陆郎从此谙。
秋茶垂露细，寒菊带霜甘。
台倚乌龙岭，楼侵白雁潭。
沈公如借问，心在浙河南。','',''),('quantangshi-28951','韶州送窦司直北归','許渾','quantangshi','','卷29','江曲山如画，贪程亦驻舟。
果随岩狖落，槎带水禽流。
客散他乡夜，人归故国秋。
樽前挂帆去，风雨下西楼。','',''),('quantangshi-28952','伤冯秀才','許渾','quantangshi','','卷29','旅葬不可问，茫茫西陇头。
水云青草湿，山月白杨愁。
琴信有时罢，劒伤无处留。
淮南旧烟月，孤棹更逢秋。','',''),('quantangshi-28953','送郑寂上人南行','許渾','quantangshi','','卷29','儒家有释子，年少学支公。
心出是非外，迹辞荣辱中。
锡寒秦岭月，杯急楚江风。
离怨故园思，小秋梨叶红。','',''),('quantangshi-28954','赠王处士','許渾','quantangshi','','卷29','归卧养天真，鹿裘乌角巾。
茂陵闲久病，彭泽醉长贫。
冠盖西园夜，笙歌北里春。
谁怜清渭曲，又老钓鱼人。','',''),('quantangshi-28955','送友人归荆楚','許渾','quantangshi','','卷29','调瑟劝离酒，苦谙荆楚门。
竹斑悲帝女，草绿怨王孙。
潮落九疑迥，雨连三峡昏。
同来不同去，迢遰更伤魂。','',''),('quantangshi-28956','重伤杨攀处士二首 一','許渾','quantangshi','','卷29','绿云多学术，黄髪竟无成。
酒纵山中性，诗留海上名。
读书新树老，垂钓旧矶平。
今日悲前事，西风闻哭声。','',''),('quantangshi-28957','重伤杨攀处士二首 二','許渾','quantangshi','','卷29','从官任直道，几处脱长裾。
殁后儿犹小，葬来人渐疎。
新隣占池馆，长史觅图书。
身贱难相报，平生恨有余。','',''),('quantangshi-28958','送友人罢举归东海','許渾','quantangshi','','卷29','沧波天堑外，何岛是新罗。
舶主辞番远，碁僧入汉多。
海风吹白鹤，沙日晒红螺。
此去知投笔，须求利劒磨。','',''),('quantangshi-28959','西园','許渾','quantangshi','','卷29','西园春欲尽，芳草径难分。
静语唯幽鸟，闲眠独使君。
密林生雨气，古石带苔文。
虽去清朝远，朝朝见白云。','',''),('quantangshi-28960','苦雨','許渾','quantangshi','','卷29','江昏山半晴，南阻绝人行。
葭菼连云色，杉松共雨声。
早秋仍燕舞，深夜更鼍鸣。
为报迷津客，讹言未可轻。','',''),('quantangshi-28961','游茅山','許渾','quantangshi','','卷29','步步入山门，仙家鸟径分。
渔樵不到处，麋鹿自成羣。
石面迸出水，松头穿破云。
道人星月下，相次礼茅君。','',''),('quantangshi-28962','洛阳道中','許渾','quantangshi','','卷29','洛阳多旧迹，一日几堪愁。
风起林花晚，月明陵树秋。
兴亡不可问，自古水东流。','',''),('quantangshi-28963','江上燕别','許渾','quantangshi','','卷29','云物如故乡，山川异岐路。
年来未归客，马上春欲暮。
一樽花下酒，残日水西树。
不待管弦终，摇鞭背花去。','',''),('quantangshi-28964','卜居招书侣','許渾','quantangshi','','卷29','忆昨未知道，临川每羡鱼。
世途行处见，人事病来疎。
微雨秋栽竹，孤灯夜读书。
怜君亦同志，晚岁傍山居。','',''),('quantangshi-28965','西山草堂','許渾','quantangshi','','卷29','何处少人事，西山旧草堂。
晒书秋日晚，洗药石泉香。
浚岭有朝雨，北窗生夜凉。
从劳问归路，峰叠遶家乡。','',''),('quantangshi-28966','赠隐者','許渾','quantangshi','','卷29','回报隐居士，莫愁山兴阑。
求人颜色尽，知道性情宽。
信谱弹琴误，缘崖劚药难。
东臯亦自给，殊愧远相安。','',''),('quantangshi-28967','舟次武陵寄天竺僧无昼','許渾','quantangshi','','卷29','溪长山几重，十里万株松。
秋日下丹槛，暮云归碧峰。
树栖新放鹤，潭隐旧降龙。
还在孤舟宿，卧闻初夜钟。','',''),('quantangshi-28968','寄小弟','許渾','quantangshi','','卷29','江城红叶尽，旅思复凄伤。
孤梦家山远，独眠秋夜长。
道存空倚命，身贱未归乡。
南望空垂泪，天边雁一行。','',''),('quantangshi-28969','秋日','許渾','quantangshi','','卷29','有计自安业，秋风罢苦吟。
买山兼种竹，对客更弹琴。
烟起药园晚，杵声松院深。
闲眠得真性，惆怅旧时心。','',''),('quantangshi-28970','石池','許渾','quantangshi','','卷29','通竹引泉脉，泓澄潋石盆。
惊鱼翻藻叶，浴鸟上松根。
残月留山影，高风耗水痕。
谁家秋洗药，来往自开门。','',''),('quantangshi-28971','留题李侍御书斋','許渾','quantangshi','','卷29','昔话平生志，高斋曾见留。
道孤心易感，恩重力难酬。
独立千峰晓，频来一叶秋。
鸡鸣应有处，不觉泪空流。','',''),('quantangshi-28972','行次白沙馆先寄上河南王侍御','許渾','quantangshi','','卷29','夜程何处宿，山叠树层层。
孤馆闭秋雨，空堂停曙灯。
歌慙渔浦客，诗学雁门僧。
此意无人识，明朝见李膺。','',''),('quantangshi-28973','紫藤','許渾','quantangshi','','卷29','绿萝萦数匝，本在草堂间。
秋色寄高树，昼阴笼远山。
移花疎处种，劚药困时攀。
日暮微风起，难寻旧径还。','',''),('quantangshi-28974','暝投灵智寺渡溪不得却取沿江路往','許渾','quantangshi','','卷29','双岩泻一川，回马断桥前。
古庙阴风地，寒钟暮雨天。
沙虚留虎迹，水滑带龙涎。
却下临江路，潮深无渡船。','',''),('quantangshi-28975','下第归蒲城墅居','許渾','quantangshi','','卷29','失意归三径，伤春别九门。
薄烟杨柳路，微雨杏花村。
牧竖还呼犊，隣翁亦抱孙。
不知余正苦，迎马问寒温。','',''),('quantangshi-28976','重赋鹭鸶','許渾','quantangshi','','卷29','何年去此地，南浦满凫雏。
云汉知心远，林塘觉思孤。
低飞下晚树，独睡映新蒲。
为尔多归兴，前年在五湖。','',''),('quantangshi-28977','途中寒食','許渾','quantangshi','','卷29','处处哭声悲，行人马亦迟。
店闲无火日，村暖斫桑时。
泣路同杨子，烧山忆介推。
清明明日是，甘负故园期。','',''),('quantangshi-28978','深春','許渾','quantangshi','','卷29','故里千帆外，深春一雁飞。
干名频恸哭，将老欲何归。
未谷抛还忆，交亲晚更稀。
空持望乡泪，霑洒寄来衣。','',''),('quantangshi-28979','岁首怀甘露寺自省上人','許渾','quantangshi','','卷29','心悟觉身劳，云中弃宝刀。
久闲生䏶肉，多寿长眉毫。
客棹春潮急，禅斋暮雪高。
南𤃩一回首，山碧水滔滔。','',''),('quantangshi-28980','寻周炼师不遇留赠','許渾','quantangshi','','卷29','闭门池馆静，云访紫芝翁。
零落槿花雨，参差荷叶风。
夜碁全局在，春酒半壶空。
长啸倚西阁，悠悠名利中。','',''),('quantangshi-28981','题灞西骆隐居','許渾','quantangshi','','卷29','志凌三蜀客，心爱五湖人。
𢬵死酒中老，谋生书外贫。
扫花眠石榻，捣药转溪轮。
往往乘黄牸，鹿裘乌角巾。','',''),('quantangshi-28982','旅夜怀远客','許渾','quantangshi','','卷29','异乡多远情，梦断落江城。
病起慙书癖，贫家负酒名。
过春花自落，竟晓月空明。
独此一长啸，故人天际行。','',''),('quantangshi-28983','秋夜棹舟访李隐君','許渾','quantangshi','','卷29','望月忆披襟，长溪柳半阴。
高斋初酿酒，孤棹远携琴。
犬吠秋山迥，鸡鸣晓树深。
开门更攲枕，谁识野人心。','',''),('quantangshi-28984','卧病寄诸公','許渾','quantangshi','','卷29','飞盖集兰堂，清歌遰柏觞。
高城榆柳荫，虚阁芰荷香。
海月秋偏静，山风夜更凉。
自怜书万卷，扶病对萤光。','',''),('quantangshi-28985','寓崇圣寺怀李校书','許渾','quantangshi','','卷29','几日卧南亭，卷帘秋月清。
河关初罢梦，池阁更含情。
寒露润金井，高风飘玉筝。
前年共游客，刀笔事戎旌。','',''),('quantangshi-28986','秋日行次关西','許渾','quantangshi','','卷29','金风荡天地，关西羣木凋。
早霜鸡喔喔，残月马萧萧。
紫陌秦山近，青枫楚树遥。
还同长卿志，题字满河桥。','',''),('quantangshi-28987','山居冬夜喜魏扶见访因赠','許渾','quantangshi','','卷29','霜风露叶下，远思独裴回。
夜久草堂静，月明山客来。
遣贫相劝酒，忆字共书灰。
何事清平世，干名待有媒。','',''),('quantangshi-28988','喜李诩秀才见访因赠','許渾','quantangshi','','卷29','浙南分首日，谁谓别经时。
路远遥相访，家贫喜见知。
不须辞小酌，更请续新诗。
但得心中劒，酬恩会有期。','',''),('quantangshi-28989','晚投慈恩寺呈俊上人','許渾','quantangshi','','卷29','双岩泻一川，十里绝人烟。
古庙阴风地，寒钟暮雨天。
沙虚留虎迹，水滑带龙涎。
不及曹溪侣，空林已夜禅。','',''),('quantangshi-28990','行次虎头岩酬寄路中丞','許渾','quantangshi','','卷29','樟亭去已远，来上虎头岩。
滩急水移棹，山回风满帆。
石梯迎雨滑，沙井落潮醎。
何以慰行旅，如公书一缄。','',''),('quantangshi-28991','送荔浦蒋明府赴任','許渾','quantangshi','','卷29','路长春欲尽，歌怨酒初酣。
白社莲宫北，青袍桂水南。
驿行盘鸟道，船宿避龙潭。
真得诗人趣，烟霞处处谙。','',''),('quantangshi-28992','怀政禅师院','許渾','quantangshi','','卷29','山斋路几层，败衲学真乘。
寒暑移双树，光阴尽一灯。
风飘高竹雪，泉涨小池冰。
莫讶频来此，修身欲到僧。','',''),('quantangshi-28993','秋夕有怀','許渾','quantangshi','','卷29','念远坐西阁，华池涵月凉。
书回秋欲尽，酒醒夜初长。
露白莲衣浅，风清蕙带香。
前年此佳景，兰棹醉横塘。','',''),('quantangshi-28994','秋霁寄远','許渾','quantangshi','','卷29','初霁独登赏，西楼多远风。
横烟秋水上，疎雨夕阳中。
高树下山鸟，平芜飞草虫。
唯应待明月，千里与君同。','',''),('quantangshi-28995','闻范秀才自蜀游江湖','許渾','quantangshi','','卷29','蜀道下湘渚，客帆应不迷。
江分三峡响，山并九华齐。
秋泊雁初宿，夜吟猨乍啼。
归时慎行李，莫到石城西。','',''),('quantangshi-28996','惜春','許渾','quantangshi','','卷29','花开又花落，时节暗中迁。
无计延春日，可能留少年。
小藂初散蝶，高柳即闻蝉。
繁艳归何处，满山啼杜鹃。','',''),('quantangshi-28997','题愁','許渾','quantangshi','','卷29','聚散竟无形，回肠百结成。
古今销不得，离别觉潜生。
降虏将军思，穷秋远客情。
何人更憔悴，落第泣秦京。','',''),('quantangshi-28998','鸳鸯','許渾','quantangshi','','卷29','两两戏沙汀，长疑画不成。
锦机争织样，歌曲爱呼名。
好□顾栖息，堪怜泛浅情。
凫鸥皆尔类，唯羡独含情。','',''),('quantangshi-28999','闻雁','許渾','quantangshi','','卷29','带霜南去雁，夜好宿汀沙。
惊起向何处，高飞极海涯。
入云声渐远，离岳路犹赊。
归梦当时断，参差欲到家。','',''),('quantangshi-29000','不寝','許渾','quantangshi','','卷29','到晓不成梦，思量堪白头。
多无百年命，长有万般愁。
世事应难尽，营生卒未休。
莫言名与利，名利是身讐。','',''),('quantangshi-29001','宿东横山','許渾','quantangshi','','卷29','孤舟路渐赊，时见碧桃花。
溪雨滩声急，岩风树势斜。
猕猴垂弱蔓，鹳鹤[睡]横槎。
谩向仙林宿，无人[识]阮家。','',''),('quantangshi-29002','早行','許渾','quantangshi','','卷29','失枕惊先起，人家半梦中。
闻鸡凭早晏，占斗认西东。
辔湿知行露，衣单觉晓风。
秋阳弄光影，忽吐半林红。','',''),('quantangshi-29003','陪郑史君泛舟晚归','許渾','quantangshi','','卷29','南郭望归处，郡楼高卷帘。
平桥低皂盖，曲岸转彤襜。
江晚笙歌促，山晴鼓角严。
羊公莫先醉，清晓月纤纤。','',''),('quantangshi-29004','酬殷尧藩','許渾','quantangshi','','卷29','相如愧许询，寥落向溪滨。
竹马儿犹小，荆钗妇惯贫。
独愁忧过日，多病不如人。
莫怪青袍选，长安隐旧春。','',''),('quantangshi-29005','赠迁客','許渾','quantangshi','','卷29','无机还得罪，直道不伤情。
微雨昏山色，疎笼闭鹤声。
闲居多野客，高枕见江城。
门外长溪水，怜君又濯缨。','',''),('quantangshi-29006','征西旧卒','許渾','quantangshi','','卷29','少年乘勇气，百战过乌孙。
力尽边城难，功加上将恩。
晓风听戍角，残月倚营门。
自说轻生处，金疮有旧痕。','',''),('quantangshi-29007','南陵留别段氏兄弟','許渾','quantangshi','','卷29','不知身老大，犹似旧时狂。
为酒游山县，留诗遍草堂。
归期秋未尽，离恨日偏长。
更羡君兄弟，参差雁一行。','',''),('quantangshi-29008','旅中别侄暐','許渾','quantangshi','','卷29','相见又南北，中宵泪满襟。
旅游知世薄，贫别觉情深。
歌管一尊酒，山川万里心。
此身多在路，休诵异乡吟。','',''),('quantangshi-29009','松江渡送人','許渾','quantangshi','','卷29','故国今何在，扁舟竟不归。
云移山漠漠，江阔树依依。
晚色千帆落，秋声一雁飞。
此时兼送客，凭槛欲霑衣。','',''),('quantangshi-29010','过鲍溶宅有感','許渾','quantangshi','','卷29','寥落故人宅，重来身已亡。
古苔残墨沼，深竹旧书堂。
秋色馆池静，雨声云木凉。
无因展交道，日暮倍心伤。','',''),('quantangshi-29011','金陵怀古','許渾','quantangshi','','卷29','玉树歌残王气终，景阳兵合戍楼空。
松楸远近千官冢，禾黍高低六代宫。
石燕拂云晴亦雨，江豚吹浪夜还风。
英雄一去豪华尽，唯有青山似洛中。','',''),('quantangshi-29012','姑苏怀古','許渾','quantangshi','','卷29','宫馆余基辍棹过，黍苗无限独悲歌。
荒台麋鹿争新草，空苑凫鹥占浅莎。
吴岫雨来虚槛冷，楚江风急远帆多。
可怜国破忠臣死，日日东流生白波。','',''),('quantangshi-29013','凌歊台','許渾','quantangshi','','卷29','宋祖凌高乐未回，三千歌舞宿层台。
湘潭云尽暮山出，巴蜀雪消春水来。
行殿有基荒荠合，寝园无主野棠开。
百年便作万年计，岩畔古碑空绿苔。','',''),('quantangshi-29014','骊山','許渾','quantangshi','','卷29','闻说先皇醉碧桃，日华浮动郁金袍。
风随玉辇笙歌逈，云卷珠帘劒佩高。
凤驾北归山寂寂，龙旟西幸水滔滔。
贵妃没后巡游少，瓦落宫墙见野蒿。','',''),('quantangshi-29015','咸阳城东楼','許渾','quantangshi','','卷29','一上高城万里愁，蒹葭杨柳似汀洲。
溪云初起日沈阁，山雨欲来风满楼。
鸟下绿芜秦苑夕，蝉鸣黄叶汉宫秋。
行人莫问当年事，故国东来渭水流。','',''),('quantangshi-29016','京口闲居寄京洛友人','許渾','quantangshi','','卷30','吴门烟月昔同游，枫叶芦花并客舟。
聚散有期云北去，浮沈无计水东流。
一尊酒尽青山暮，千里书回碧树秋。
何处相思不相见，凤城龙阙楚江头。','',''),('quantangshi-29017','冬日登越王台怀归','許渾','quantangshi','','卷30','月沈高岫宿云开，万里归心独上来。
河畔雪飞扬子宅，海边花盛越王台。
泷分桂岭鱼难过，瘴近衡峯雁却回。
乡信渐稀人渐老，只应频看一枝梅。','',''),('quantangshi-29018','对雪','許渾','quantangshi','','卷30','云度龙山暗倚城，先飞淅沥引轻盈。
素娥冉冉拜瑶阙，皓鹤纷纷朝玉京。
阴岭有风梅艳散，寒林无月桂华生。
剡溪一醉十年事，忽忆棹回天未明。','',''),('quantangshi-29019','送萧处士归缑岭别业','許渾','quantangshi','','卷30','醉斜乌帽髪如丝，曾看仙人一局棋。
宾馆有鱼为客久，乡书无雁到家迟。
缑山住近吹笙庙，湘水行逢鼓瑟祠。
今夜月明何处宿，九疑云尽碧参差。','',''),('quantangshi-29020','与郑二秀才同舟东下洛中亲朋送至景云寺','許渾','quantangshi','','卷30','三十六峰横一川，绿波无路草芊芊。
牛羊晚食铺平地，雕鹗晴飞摩远天。
洛客尽回临水寺，楚人皆逐下江船。
东西未有相逢日，更把繁华共醉眠。','',''),('quantangshi-29021','长安岁暮','許渾','quantangshi','','卷30','独望天门倚劒歌，干时无计老关河。
东归万里慙张翰，西上四年羞卞和。
花暗楚城春醉少，月凉秦塞夜愁多。
三山岁岁有人去，唯恐海风生白波。','',''),('quantangshi-29022','赠茅山高拾遗','許渾','quantangshi','','卷30','谏猎归来绮季歌，大茅峯影满秋波。
山斋留客扫红叶，野艇送僧披绿莎。
长覆旧图棊势尽，遍添新品药名多。
云中黄鹄日千里，自宿自飞无网罗。','',''),('quantangshi-29023','李秀才近自涂口迁居新安适枉缄书见寛悲戚因以此答','許渾','quantangshi','','卷30','远书开罢更依依，晨坐高台竟落晖。
颜巷雪深人已去，庾楼花盛客初归。
东堂望绝迁莺起，南国哀余候雁飞。
今日劳君犹问讯，一官唯长故山薇。','',''),('quantangshi-29024','赠萧兵曹先辈','許渾','quantangshi','','卷30','广陵堤上昔离居，帆转潇湘万里余。
楚客病时无鵩鸟，越乡归处有鲈鱼。
潮生水郭蒹葭响，雨过山城橘柚疎。
闻说携琴兼载酒，邑人争识马相如。','',''),('quantangshi-29025','题舒女庙','許渾','quantangshi','','卷30','山乐来迎去不言，庙前高柳水禽喧。
绮罗无色雨侵帐，珠翠有声风绕幡。
妆镜尚疑山月满，寝屏犹认野花繁。
孤舟梦断行云散，何限离心寄晓猨。','',''),('quantangshi-29026','姑孰官舍','許渾','quantangshi','','卷30','草生官舍似闲居，雪照南窗满素书。
贫后始知为吏拙，病来还喜识人疎。
青云岂有窥梁燕，浊水应无避钓鱼。
不待秋风便归去，紫阳山下是吾庐。','',''),('quantangshi-29027','凌歊台送韦秀才','許渾','quantangshi','','卷30','云起高台日未沈，数村残照半岩阴。
野蚕成茧桑柘尽，溪鸟引雏蒲稗深。
帆势依依投极浦，钟声[杳杳]隔前林。
故山迢遰故人去，一夜月明千里心。','',''),('quantangshi-29028','送岭南卢判官罢职归华阴山居','許渾','quantangshi','','卷30','曾事刘琨雁塞空，十年书劒任飘蓬。
东堂旧屈移山志，南国新留煮海功。
还挂一帆青海上，更开三迳碧莲中。
关西旧友如相问，已许沧浪伴钓翁。','',''),('quantangshi-29029','将度故城湖阻风夜泊永阳戍','許渾','quantangshi','','卷30','行尽青溪日已蹉，云容山影水嵯峨。
楼前归客怨清梦，楼上美人凝夜歌。
独树高高风势急，平湖渺渺月明多。
终期一艇载樵去，来往使帆凌白波。','',''),('quantangshi-29030','郑侍御厅翫鹤','許渾','quantangshi','','卷30','碧天飞舞下晴莎，金阁瑶池绝网罗。
岩响数声风满树，岸移孤影雪凌波。
缑山去远云霄迥，辽海归迟岁月多。
双翅一开千万里，秖应栖隐恋乔柯。','',''),('quantangshi-29031','南亭夜坐贻开元禅定二道者','許渾','quantangshi','','卷30','暮暮焚香何处宿，西岩一室映疎藤。
光阴难驻迹如客，寒暑不惊心似僧。
高树有风闻夜磬，远山无月见秋灯。
身闲境静日为乐，若问其余非我能。','',''),('quantangshi-29032','朱坡故少保杜公池亭','許渾','quantangshi','','卷30','杜陵池榭绮城东，孤岛回汀路不穷。
高岫乍疑三峡近，远波初似五湖通。
楸梧叶暗潇潇雨，菱荇花香淡淡风。
还有昔时巢燕在，飞来飞去画堂中。','',''),('quantangshi-29033','秋日早朝','許渾','quantangshi','','卷30','宵衣应待绝更筹，环佩锵锵月下楼。
井转辘轳千树晓，鏁开阊阖万山秋。
龙旗尽列趋金殿，雉扇才分见玉旒。
虚戴铁冠无一事，沧江归去老渔舟。','',''),('quantangshi-29034','沧浪峡','許渾','quantangshi','','卷30','缨带流尘髪半霜，独寻残月下沧浪。
一声溪鸟暗云散，万片野花流水香。
昔日未知方外乐，暮年初信梦中忙。
红虾青鲫紫芹脆，归去不辞来路长。','',''),('quantangshi-29035','故洛城','許渾','quantangshi','','卷30','禾黍离离半野蒿，昔人城此岂知劳。
水声东去市朝变，山势北来宫殿高。
鸦噪暮云归古堞，雁迷寒雨下空壕。
可怜缑岭登仙子，犹自吹笙醉碧桃。','',''),('quantangshi-29036','闻释子栖玄欲奉道因寄','許渾','quantangshi','','卷30','欲求真诀恋禅扃，羽帔方袍尽有情。
仙骨本微灵鹤远，法心潜动毒龙惊。
三山未有偷桃计，四海初传问菊名。
今日劝师师莫惑，长生难学证无生。','',''),('quantangshi-29037','南海府罢南康阻浅行侣稍登陆而迈主人燕饯至频暮宿东溪','許渾','quantangshi','','卷30','暗滩水落涨虚沙，滩去秦吴万里赊。
马上折残江北柳，舟中开尽岭南花。
离歌不断如留客，归梦初惊似到家。
山鸟一声人未起，半牀春月在天涯。','',''),('quantangshi-29038','秋晚云阳驿西亭莲池','許渾','quantangshi','','卷30','心忆莲池秉烛游，叶残花败尚维舟。
烟开翠扇清风晓，水泥红衣白露秋。
神女暂来云易散，仙娥初去月难留。
空怀远道难持赠，醉倚阑干尽日愁。','',''),('quantangshi-29039','题勤尊师历阳山居','許渾','quantangshi','','卷30','二十知兵在羽林，中年潜识子房心。
苍鹰出塞胡尘灭，白鹤还乡楚水深。
春坼酒瓶浮药气，晚携棊局带松阴。
鸡笼山上云多处，自斸黄精不可寻。','',''),('quantangshi-29040','怀旧居','許渾','quantangshi','','卷30','兵书一箧老无功，故国郊扉在梦中。
藤蔓覆梨张谷暗，草花侵菊庾园空。
朱门迹忝登龙客，白屋心期失马翁。
楚水吴山何处是，北窗残月照屏风。','',''),('quantangshi-29041','祗命许昌自郊居移就公馆秋日寄茅山高拾遗','許渾','quantangshi','','卷30','一笛迎风万叶飞，强携刀笔换荷衣。
潮寒水国秋砧早，月暗山城夜漏稀。
岩响远闻樵客过，浦深遥送钓童归。
中年未识从军乐，虚近三茅望少微。','',''),('quantangshi-29042','伤虞将军','許渾','quantangshi','','卷30','白首从军未有名，近将孤劒到江城。
巴童戍久能番语，胡马调多解汉行。
对雪夜穷黄石略，望云秋计黑山程。
可怜身死家犹远，汴水东流无哭声。','',''),('quantangshi-29043','晚自朝台津至韦隐居郊园','許渾','quantangshi','','卷30','秋来凫雁下方塘，系马朝台步夕阳。
村径绕山松叶暗，野门临水稻花香。
云连海气琴书润，风带潮声枕簟凉。
西下磻溪犹万里，可能垂白待文王。','',''),('quantangshi-29044','寓居开元精舍酬薛秀才见贻','許渾','quantangshi','','卷30','知己萧条信陆沈，茂陵扶疾卧西林。
芰荷风起客堂静，松桂月高僧院深。
清露下时伤旅鬓，白云归处寄乡心。
怜君诗句犹相忆，题在空斋夜夜吟。','',''),('quantangshi-29045','别刘秀才','許渾','quantangshi','','卷30','三献无功玉有瑕，更携书劒客天涯。
孤帆夜别潇湘雨，广陌春期鄠杜花。
灯照水萤千点灭，棹惊滩雁一行斜。
关河万里秋风急，望见乡山不到家。','',''),('quantangshi-29046','早发天台中岩寺度关岭次天姥岑','許渾','quantangshi','','卷30','来往天台天姥间，欲求真诀驻衰颜。
星河半落岩前寺，云雾初开岭上关。
丹壑树多风浩浩，碧溪苔浅水潺潺。
可知刘阮逢人处，行尽深山又是山。','',''),('quantangshi-29047','游钱塘青山李隐居西斋','許渾','quantangshi','','卷30','小隐西亭为客开，翠萝深处遍苍苔。
林间扫石安棊局，岩下分泉递酒杯。
兰叶露光秋月上，芦花风起夜潮来。
云山遶屋犹嫌浅，欲棹渔舟近钓台。','',''),('quantangshi-29048','春日郊园戏赠杨嘏评事','許渾','quantangshi','','卷30','十里蒹葭入薜萝，春风谁许暂鸣珂。
相如渴后狂还减，曼倩归来语更多。
门枕碧溪冰皓耀，槛齐青嶂雪嵯峨。
野桥沽酒茅檐醉，谁羡红楼一曲歌。','',''),('quantangshi-29049','晚自东郭回留一二游侣','許渾','quantangshi','','卷30','乡心迢遰宦情微，吏散寻幽竟落晖。
林下草腥巢鹭宿，洞前云湿雨龙归。
钟随野艇回孤棹，鼓绝山城掩半扉。
今夜西斋好风月，一瓢春酒莫相违。','',''),('quantangshi-29050','与郑秀才叔侄会送杨秀才昆仲东归','許渾','quantangshi','','卷30','书劒功迟白发新，异乡仍送故乡人。
阮公留客竹林晚，田氏到家荆树春。
雪尽塞鸿南翥少，风来胡马北嘶频。
洞庭烟月如终老，谁是长杨谏猎臣。','',''),('quantangshi-29051','送郭秀才游天台','許渾','quantangshi','','卷30','云埋阴壑雪凝峯，半壁天台已万重。
人度碧溪疑辍棹，僧归苍岭似闻钟。
暖眠鸂鶒晴滩草，高挂猕猴暮涧松。
曾约共游今独去，赤城西面水溶溶。','',''),('quantangshi-29052','送张尊师归洞庭','許渾','quantangshi','','卷30','能琴道士洞庭西，风满归帆路不迷。
对岸水花霜后浅，傍檐山果雨来低。
杉松近晚移茶竈，岩谷初寒盖药畦。
他日相思两行字，无人知处武陵溪。','',''),('quantangshi-29053','移摄太平寄前李明府','許渾','quantangshi','','卷30','病移岩邑称闲身，何处风光贳酒频。
溪柳遶门彭泽令，野花连洞武陵人。
娇歌自驻壶中景，艳舞长留海上春。
早晚高台更同醉，绿萝如帐草如茵。','',''),('quantangshi-29054','再游姑苏玉芝观','許渾','quantangshi','','卷30','高梧一叶下秋初，迢遰重廊旧寄居。
月过碧窗今夜酒，雨昏红壁去年书。
玉池露冷芙蓉浅，琼树风高薜荔疎。
明日挂帆更东去，仙翁应笑为鲈鱼。','',''),('quantangshi-29055','夜归驿楼','許渾','quantangshi','','卷30','水晚云秋山不穷，自疑身在画屏中。
孤舟移棹一江月，高阁卷帘千树风。
窗下覆棋残局在，橘边沽酒半壜空。
早炊香稻待鲈鲙，南渚未明寻钓翁。','',''),('quantangshi-29056','题灵山寺行坚师院','許渾','quantangshi','','卷30','西岩一迳不通樵，八十持杯未觉遥。
龙在石潭闻夜雨，雁移沙渚见秋潮。
经函露湿文多暗，香印风吹字半销。
应笑东归又南去，越山无路水迢迢。','',''),('quantangshi-29057','湖州韦长史山居','許渾','quantangshi','','卷30','一官唯买昼公堂，但得身闲日自长。
琴曲少声重勘谱，药丸多忌更寻方。
溪浮箬叶添醅绿，泉遶松根助茗香。
明日鳜鱼何处钓，门前春水似沧浪。','',''),('quantangshi-29058','赠李伊阙','許渾','quantangshi','','卷30','桐履如飞不可寻，一壶双笈峄阳琴。
舟横野度寒风急，门掩荒山夜雪深。
贫笑白驹无去意，病慙黄鹄有归心。
云间二室劳君画，水墨苍苍半壁阴。','',''),('quantangshi-29059','重游綀湖怀旧','許渾','quantangshi','','卷30','西风渺渺月连天，同醉兰舟未十年。
鵩鸟赋成人已没，嘉鱼诗在世空传。
荣枯尽寄浮云外，哀乐犹惊逝水前。
日暮长堤更回首，一声邻笛旧山川。','',''),('quantangshi-29060','乘月棹舟送大历寺灵聪上人不及','許渾','quantangshi','','卷30','万峰秋尽百泉清，旧锁禅扉在赤城。
枫浦客来烟未散，竹窗僧去月犹明。
杯浮野渡鱼龙远，锡响空山虎豹惊。
一字不留何足讶，白云无路水无情。','',''),('quantangshi-29061','汴河亭','許渾','quantangshi','','卷30','广陵花盛帝东游，先劈昆仑一派流。
百二禁兵辞象阙，三千宫女下龙舟。
凝云鼓震星辰动，拂浪旗开日月浮。
四海义师归有道，迷楼还似景阳楼。','',''),('quantangshi-29062','村舍二首 一','許渾','quantangshi','','卷30','自翦青莎织雨衣，南峰烟火是柴扉。
莱妻早报蒸藜熟，童子遥迎种豆归。
鱼下碧潭当镜跃，鸟还青嶂拂屏飞。
花时未免人来往，欲买严光旧钓矶。','',''),('quantangshi-29063','村舍二首 二','許渾','quantangshi','','卷30','尚平多累自归难，一日身闲一日安。
山迳晓云收猎网，水门凉月挂鱼竿。
花间酒气春风暖，竹里棋声暮雨寒。
三顷水田秋更熟，北窗谁拂旧尘冠。','',''),('quantangshi-29064','郑秀才东归凭达家书','許渾','quantangshi','','卷30','欲寄家书少客过，闭门心远洞庭波。
两岩花落夜风急，一迳草荒春雨多。
愁泛楚江吟浩渺，忆归吴岫梦嵯峨。
贫居不问应知处，溪上闲船系绿萝。','',''),('quantangshi-29065','伤故湖州李郎中','許渾','quantangshi','','卷30','政成身没共兴衰，乡路兵戈旅榇回。
城上暮云凝鼓角，海边春草闭池台。
经年未葬家人散，昨夜因斋故吏来。
南北相逢皆掩泣，白苹洲暖百花开。','',''),('quantangshi-29066','和友人送僧归桂州灵岩寺','許渾','quantangshi','','卷30','楚客送僧归桂阳，海门帆势极潇湘。
碧云千里暮愁合，白雪一声春思长。
柳絮拥堤添衲软，松花浮水注瓶香。
南京长老几年别，闻道半岩多影堂。','',''),('quantangshi-29067','淮阴阻风寄呈楚州韦中丞','許渾','quantangshi','','卷30','垂钓京江欲白头，江鱼堪钓却西游。
刘伶台下稻花晚，韩信庙前枫叶秋。
淮月未明先倚槛，海云初起更维舟。
河桥有酒无人醉，独上高城望庾楼。','',''),('quantangshi-29068','途经敷水','許渾','quantangshi','','卷30','修蛾颦翠倚柔桑，遥谢春风白面郎。
五夜有情随暮雨，百年无节待秋霜。
重寻绣带朱藤合，更认罗帬碧草长。
何处野花何处水，下峰流出一渠香。','',''),('quantangshi-29069','和人贺杨仆射致政','許渾','quantangshi','','卷30','莲府公卿拜后尘，手持优诏挂朱轮。
从军暮下三千客，闻礼庭中七十人。
锦帐丽词推北巷，画堂清乐掩南邻。
岂同王谢山阴会，空叙流杯醉暮春。','',''),('quantangshi-29070','题四皓庙','許渾','quantangshi','','卷30','桂香松暖庙门开，独泻椒浆奠一杯。
秦法欲兴鸿已去，汉储将废凤还来。
紫芝翳翳多青草，白石苍苍半绿苔。
山下驿尘南窜路，不知冠盖几人回。','',''),('quantangshi-29071','鹤林寺中秋夜翫月','許渾','quantangshi','','卷30','待月东林月正圆，广庭无树草无烟。
中秋云尽出沧海，半夜露寒当碧天。
轮彩渐移金殿外，镜光犹挂玉楼前。
莫辞达曙殷勤望，一堕西岩又隔年。','',''),('quantangshi-29072','南海府罢归京口经大庾岭赠张明府','許渾','quantangshi','','卷30','楼船旌斾极天涯，一剑从军两鬓华。
回日眼明河畔草，去时肠断岭头花。
陶诗尽写行过县，张赋初成卧到家。
官满知君有归处，姑苏台上旧烟霞。','',''),('quantangshi-29073','题卫将军庙','許渾','quantangshi','','卷30','武牢关下护龙旗，挟槊弯弧马上飞。
汉业未兴王霸在，秦军才散鲁连归。
坟穿大泽埋金剑，庙枕长溪挂铁衣。
欲奠忠魂何处问，苇花枫叶雨霏霏。','',''),('quantangshi-29074','访别韦隐居不值','許渾','quantangshi','','卷30','犬吠双岩碧树间，主人朝出半开关。
汤师阁上留诗别，杜叟桥边载酒还。
栎坞炭烟晴过岭，蓼村渔火夜移湾。
故乡芜没兵戈后，凭向溪南买一山。','',''),('quantangshi-29075','送前东阳于明府由鄂渚归故林','許渾','quantangshi','','卷30','结束征车换黑貂，灞西风雨正潇潇。
茂陵久病书千卷，彭泽初归酒一瓢。
帆背夕阳湓水阔，棹经沧海甑山遥。
殷勤为谢南溪客，白首萤窗未见招。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-29076','听歌鹧鸪辞','許渾','quantangshi','','卷30','南国多情多艳词，鹧鸪清怨遶梁飞。
甘棠城上客先醉，苦竹岭头人未归。
响转碧霄云驻影，曲终清漏月沈晖。
山行水宿不知远，犹梦玉钗金缕衣。','',''),('quantangshi-29077','寄题华严韦秀才院','許渾','quantangshi','','卷30','三面楼台百丈峰，西岩高枕树重重。
晴攀翠竹题诗滑，秋摘黄花酿酒浓。
山殿日斜喧鸟雀，石潭波动戏鱼龙。
今来故国遥相忆，月照千山半夜钟。','',''),('quantangshi-29078','戏代李协律松江有赠','許渾','quantangshi','','卷30','蜀客操琴吴女歌，明珠十斛是天河。
霜凝薜荔怯秋树，露滴芙蓉愁晚波。
兰浦远乡应解佩，柳堤残月未鸣珂。
西楼沈醉不知散，潮落洞庭洲渚多。','',''),('quantangshi-29079','送黄隐居归南海','許渾','quantangshi','','卷30','瘴雾南边久寄家，海中来往信流槎。
林藏●●多残笋，树过猩猩少落花。
深洞有云龙蜕骨，半岩无草象生牙。
知君爱宿层峰顶，坐到三更见日华。','',''),('quantangshi-29080','朝台送客有怀','許渾','quantangshi','','卷30','赵佗西拜已登坛，马援南征土宇宽。
越国旧无唐印绶，蛮乡今有汉衣冠。
江云带日秋偏热，海雨随风夏亦寒。
岭北归人莫回首，蓼花枫叶万重滩。','',''),('quantangshi-29081','自楞伽寺晨起泛舟道中有怀','許渾','quantangshi','','卷30','碧树苍苍茂苑东，佳期迢遰路何穷。
一声山鸟曙云外，万点水萤秋草中。
门掩竹斋微有月，棹移兰渚淡无风。
欲知此路堪惆怅，菱叶蓼花连故宫。','',''),('quantangshi-29082','十二月拜起居表回','許渾','quantangshi','','卷30','一章西奏拜仙曹，回马天津北望劳。
寒水欲春冰彩薄，晓山初霁雪峰高。
楼形向日攒飞凤，宫势凌波压拚鳌。
空锁烟霞绝巡幸，周人谁识郁金袍。','',''),('quantangshi-29083','观章中丞夜按歌舞','許渾','quantangshi','','卷30','夜按双娃禁曲新，东西箫鼓接云津。
舞衫未换红铅湿，歌扇初移翠黛颦。
彩槛烛烟光吐日，画屏香雾暖如春。
西楼月在襄王醉，十二山高不见人。','',''),('quantangshi-29084','重游飞泉观题故梁道士宿龙池','許渾','quantangshi','','卷30','西岩泉落水容宽，灵物蜿蜒黑处蟠。
松叶正秋琴韵响，菱花初晓镜光寒。
云开星月浮山殿，雨过风雷遶石坛。
仙客不归龙亦去，稻畦长满此池干。','',''),('quantangshi-29085','下第贻友人','許渾','quantangshi','','卷30','身在关西家洞庭，夜寒歌苦烛荧荧。
人心高下月中桂，客思往来波上萍。
马氏识君眉最白，阮公留我眼长青。
花前失意共寥落，莫遣东风吹酒醒。','',''),('quantangshi-29086','晚登龙门驿楼','許渾','quantangshi','','卷30','鱼龙多处凿门开，万古人知夏禹材。
青嶂远分从地断，洪流高泻自天来。
风云有路皆烧尾，波浪无程尽曝腮。
心感膺门身过此，晚山秋树独徘徊。','',''),('quantangshi-29087','题故李秀才居','許渾','quantangshi','','卷30','曾醉笙歌日正迟，醉中相送易前期。
橘花满地人亡后，菰叶连天雁过时。
琴倚旧窗尘漠漠，剑埋新冢草离离。
河桥酒熟平生事，更向东流奠一巵。','',''),('quantangshi-29088','韶州韶阳楼夜宴','許渾','quantangshi','','卷30','待月西楼卷翠罗，玉杯瑶瑟近星河。
帘前碧树穷秋密，窗外青山薄暮多。
鸜鹆未知狂客醉，鹧鸪先让美人歌。
使君莫惜通宵饮，刀笔初从马伏波。','',''),('quantangshi-29089','闻韶州李相公移拜郴州因寄','許渾','quantangshi','','卷30','诏移丞相木兰舟，桂水潺湲岭北流。
青汉梦归双阙曙，白云吟过五湖秋。
恩回玉扆人先喜，道在金縢世不忧。
闻说公卿尽南望，甘堂花暖凤池头。','',''),('quantangshi-29090','游江令旧宅','許渾','quantangshi','','卷30','身没南朝宅已荒，邑人犹赏旧风光。
芹根生叶石池浅，桐树落花金井香。
带暖山蜂巢画阁，欲阴溪燕集书堂。
闲愁此地更西望，潮侵台城春草长。','',''),('quantangshi-29091','灞上逢元九处士东归','許渾','quantangshi','','卷30','瘦马频嘶灞水寒，灞南高处望长安。
何人更结王生韤，此客虚弹贡氏冠。
江上蟹螯沙渺渺，坞中蜗殻雪漫漫。
旧交已变新知少，却伴渔郎把钓竿。','',''),('quantangshi-29092','别张秀才','許渾','quantangshi','','卷30','不知何计写离忧，万里山川半旧游。
风卷暮沙和雪起，日融春水带冰流。
凌晨客泪分东郭，竟夕乡心共北楼。
青桂一枝年少事，莫因鲈鲙涉穷秋。','',''),('quantangshi-29093','别表兄军倅','許渾','quantangshi','','卷30','卢橘花香拂钓矶，佳人犹舞越罗衣。
三洲水浅鱼来少，五岭山高雁到稀。
客路晚依红树宿，乡关朝望白云归。
交亲不念征南吏，昨夜风帆去似飞。','',''),('quantangshi-29094','题苏州虎丘寺僧院','許渾','quantangshi','','卷30','暂引寒泉濯远尘，此生多是异乡人。
荆溪夜雨花开疾，吴苑秋风月满频。
万里高低门外路，百年荣辱梦中身。
世间谁似西林客，一卧烟霞四十春。','',''),('quantangshi-29095','酬郭少府先奉使巡涝见寄兼呈裴明府','許渾','quantangshi','','卷30','载书携榼别池龙，十幅轻帆处处通。
谢朓宅荒山翠里，王敦城古月明中。
江村夜涨浮天水，泽国秋生动地风。
饱食鲙鱼榜归檝，待君琴酒醉陶公。','',''),('quantangshi-29096','出永通门经李氏庄','許渾','quantangshi','','卷30','飞轩危槛百花堂，朝宴歌钟暮已荒。
中散狱成琴自怨，步兵厨废酒犹香。
风池宿鸟喧朱阁，雨砌秋萤拂画梁。
力保山河家又庆，秪应中令敌汾阳。','',''),('quantangshi-29097','汉水伤稼','許渾','quantangshi','','卷30','西北楼开四望通，残霞成绮月悬弓。
江村夜涨浮天水，泽国秋生动地风。
高下绿苗千顷尽，新陈红粟万厫空。
才微分薄忧何益，却欲回心学钓翁。','',''),('quantangshi-29098','送王总下第归丹阳','許渾','quantangshi','','卷30','秦楼心断楚江湄，系马春风酒一巵。
汴水月明东下疾，练塘花发北来迟。
青芜定没安贫处，黄叶应催献赋诗。
凭寄家书为回报，旧乡还有故人知。','',''),('quantangshi-29099','南阳道中','許渾','quantangshi','','卷30','月斜孤馆傍村行，野店高低带古城。
篱上晓花斋后落，井边秋叶社前生。
饥乌索哺随雏叫，乳牸慵归望犊鸣。
荒草连天风动地，不知谁学武侯耕。','',''),('quantangshi-29100','破北虏太和公主归宫阙','許渾','quantangshi','','卷30','毳幕承秋极断蓬，飘颻一剑黑山空。
匈奴北走荒秦垒，贵主西还盛汉宫。
定是庙谟倾种落，必知边寇畏骁雄。
恩霑残类从归去，莫使华人杂犬戎。','',''),('quantangshi-29101','李定言自殿院衔命归阙拜员外郎迁右史因寄','許渾','quantangshi','','卷30','白笔南征变二毛，越山愁瘴海惊涛。
才归龙尾含鸡舌，更立螭头运兔毫。
阊阖欲开宫漏尽，冕旒初坐御香高。
吴中旧侣君先贵，曾忆王祥与佩刀。','',''),('quantangshi-29102','早秋韶阳夜雨','許渾','quantangshi','','卷30','宋玉含凄梦亦惊，芙蓉山响一猨声。
阴云迎雨枕先润，夜电引雷窗暂明。
暗惜水花飘广槛，远愁风叶下高城。
西归万里未千里，应到故园春草生。','',''),('quantangshi-29103','将为南行陪尚书崔公宴海榴堂','許渾','quantangshi','','卷30','朝宴华堂暮未休，几人偏得谢公留。
风传鼓角霜侵戟，云卷笙歌月上楼。
宾馆尽开徐穉榻，客帆空恋李膺舟。
谩夸书剑无知己，水远山长步步愁。','',''),('quantangshi-29104','赠王山人','許渾','quantangshi','','卷30','贳酒携琴访我频，始知城市有闲人。
君臣药在宁忧病，子母钱成岂患贫。
年长每劳推甲子，夜寒初共守庚申。
近来闻说烧丹处，玉洞桃花万树春。','',''),('quantangshi-29105','宣城崔大夫召联句偶疾不获赴因献','許渾','quantangshi','','卷30','心慕知音命自拘，画堂闻欲试吹竽。
茂陵罢酒慙中圣，漳浦题诗怯大巫。
鬐鬣几年伤在藻，羽毛终日羡栖梧。
还愁旅棹空归去，枫叶荷花钓五湖。','',''),('quantangshi-29106','赠郑处士','許渾','quantangshi','','卷30','道傍年少莫矜夸，心在重霄鬓未华。
杨子可曾过北里，鲁人何必敬东家。
寒云晓散千峰雪，暖雨晴开一迳花。
且卖湖田酿春酒，与君书剑是生涯。','',''),('quantangshi-29107','正元','許渾','quantangshi','','卷30','高揭鸡竿辟帝阍，祥风微暖瑞云屯。
千官共削奸臣迹，万国初衔圣主恩。
宫殿雪华齐紫阁，关河春色到青门。
华夷一轨人方泰，莫学论兵误至尊。','',''),('quantangshi-29108','登尉佗楼','許渾','quantangshi','','卷30','刘项持兵鹿未穷，自乘黄屋岛夷中。
南来作尉任嚣力，北向称臣陆贾功。
箫鼓尚陈今世庙，旌旗犹镇昔时宫。
越人未必知虞舜，一奏薰弦万古风。','',''),('quantangshi-29109','诏州驿楼宴罢','許渾','quantangshi','','卷30','檐外千帆背夕阳，归心杳杳鬓苍苍。
岭猨羣宿夜山静，沙鸟独飞秋水凉。
露堕桂花棋局湿，风吹荷叶酒瓶香。
主人不醉下楼去，月在南轩更漏长。','',''),('quantangshi-29110','和淮南王相公与宾僚同游瓜洲别业题旧书斋','許渾','quantangshi','','卷30','碧油红斾想青衿，积雪窗前尽日吟。
巢鹤去时云树老，卧龙归处石潭深。
道傍苦李犹垂实，城外甘棠已布阴。
宾御莫辞岩下醉，武丁高枕待为霖。','',''),('quantangshi-29111','送卢先辈自衡岳赴复州嘉礼二首 一','許渾','quantangshi','','卷30','名振金闺步玉京，暂留沧海见高情。
众花尽处松千尺，羣鸟喧时鹤一声。
朱阁簟凉疎雨过，碧溪船动早潮生。
离心不异西江水，直送征帆万里行。','',''),('quantangshi-29112','送卢先辈自衡岳赴复州嘉礼二首 二','許渾','quantangshi','','卷30','湘南诗客海中行，鹏翅垂云不自矜。
秋水静磨金镜土，夜风寒结玉壶冰。
万重岭峤辞衡岳，千里山陂问竟陵。
醉倚西楼人已远，柳溪无浪月澄澄。','',''),('quantangshi-29113','哭杨攀处士','許渾','quantangshi','','卷30','先生忧道乐清贫，白发终为不仕身。
嵇阮没来无酒客，应刘亡后少诗人。
山前月照荒坟晓，溪上花开旧宅春。
昨夜回舟更惆怅，至今钟磬满南邻。','',''),('quantangshi-29114','宿松江驿却寄苏州一二同志','許渾','quantangshi','','卷30','候馆人稀夜自长，姑苏台远树苍苍。
江湖潮落高楼迥，河汉秋归广簟凉。
月转碧梧移鹊影，露低红叶湿萤光。
西园诗侣应多思，莫醉笙歌掩画堂。','',''),('quantangshi-29115','卢山人自巴蜀由湘潭归茅山因赠','許渾','quantangshi','','卷30','太乙灵方炼紫荷，紫荷飞尽髪皤皤。
猨啼巫峡晓云薄，雁宿洞庭秋月多。
导引岂如桃叶舞，步虚宁比竹枝歌。
华阳旧隐莫归去，水没芝田生绿莎。','',''),('quantangshi-29116','颍州从事西湖亭宴饯','許渾','quantangshi','','卷30','西湖清宴不知回，一曲离歌酒一杯。
城带夕阳闻鼓角，寺临秋水见楼台。
兰堂客散蝉犹噪，桂檝人稀鸟自来。
独想征车过巩洛，此中霜菊遶潭开。','',''),('quantangshi-29117','瓜洲留别李诩','許渾','quantangshi','','卷30','泣玉三年一见君，白衣顦顇更离羣。
柳堤惜别春潮落，花榭留欢夜漏分。
孤馆宿时风带雨，远帆归处水连云。
悲歌曲尽莫重奏，心遶关河不忍闻。','',''),('quantangshi-29118','余谢病东归王秀才见寄今潘秀才南棹奉酬','許渾','quantangshi','','卷30','酷似牢之玉不如，落星山下白云居。
春耕旋构金门客，夜学兼修玉府书。
风扫碧云迎鸷鸟，水还沧海养嘉鱼。
莫将年少轻时节，王氏家风在石渠。','',''),('quantangshi-29119','献韶阳相国崔公','許渾','quantangshi','','卷30','一匮为功极九层，康庄犹自剑棱棱。
舟回北渚经年泊，门接东山尽日登。
万国已闻传玉玺，百官犹望启金縢。
贤臣会致唐虞世，独倚江楼笑范增。','',''),('quantangshi-29120','郡斋夜坐寄旧乡二侄','許渾','quantangshi','','卷30','千官奉职衮龙垂，旅卧淮阳鬓日衰。
三月已乖棠树政，二年空负竹林期。
楼侵白浪风来远，城抱丹岩日到迟。
长欲挂帆君莫笑，越禽花晚梦南枝。','',''),('quantangshi-29121','病间寄郡中文士','許渾','quantangshi','','卷30','卢橘含花处处香，老人依旧卧清漳。
心同客舍惊秋早，迹似僧斋厌夜长。
风卷翠帘琴自响，露凝朱阁簟先凉。
明朝欲醉文中彦，犹觉吟声带越乡。','',''),('quantangshi-29122','贺少师相公致政','許渾','quantangshi','','卷30','六十悬车自古稀，我公年少独忘机。
门临二室留侯隐，棹倚三川越相归。
不拟优游同陆贾，已回清白遗胡威。
龙城凤沼棠阴在，只恐归鸿更北飞。','',''),('quantangshi-29123','题崔处士山居','許渾','quantangshi','','卷30','坐穷今古掩书堂，二顷湖田一半荒。
荆树有花兄弟乐，橘林无实子孙忙。
龙归晓洞云犹湿，麝过春山草自香。
向夜欲归心万里，故园松月更苍苍。','',''),('quantangshi-29124','疾后与郡中羣公宴李秀才','許渾','quantangshi','','卷30','强留佳客宴王孙，岩上余花落酒樽。
书院欲开虫网户，讼庭犹掩雀罗门。
耳虚尽日疑琴癖，眼暗经秋觉镜昏。
莫引刘安倚西槛，夜来红叶下江村。','',''),('quantangshi-29125','晨起白云楼寄龙兴江准上人兼呈窦秀才','許渾','quantangshi','','卷30','兹楼今是望乡台，乡信全稀晓雁哀。
山翠万重当槛出，水华千里抱城来。
东岩月在僧初定，南浦花残客未回。
欲吊灵均能赋否，秋风还有木兰开。','',''),('quantangshi-29126','宴饯李员外','許渾','quantangshi','','卷30','病守江城眼暂开，昔年吴越共衔杯。
膺舟出镇虚陈榻，郑履还京下隗台。
云叶渐低朱阁掩，浪花初起画樯回。
心期解印同君醉，九曲池西望月来。','',''),('quantangshi-29127','酬钱汝州','許渾','quantangshi','','卷30','白雪多随汉水流，谩劳旌斾晚悠悠。
笙歌暗写终年恨，台榭潜消尽日忧。
鸟散落花人自醉，马嘶芳草客先愁。
怪来雅韵清无敌，三十六峰当庾楼。','',''),('quantangshi-29128','将归姑苏南楼饯送李明府','許渾','quantangshi','','卷30','无处登临不系情，一凭春酒醉高城。
暂移罗绮见山色，才驻管弦闻水声。
花落西亭添别恨，柳阴南浦促归程。
前期迢遰今宵短，更倚朱阑待月明。','',''),('quantangshi-29129','和浙西从事刘三复送僧南归','許渾','quantangshi','','卷30','楚客送僧归故乡，海门帆势极潇湘。
碧云千里暮愁合，白雪一声春思长。
满院草花平讲席，绕龛藤叶盖禅牀。
怜师不得随师去，已戴儒冠事素王。','',''),('quantangshi-29130','送上元王明府赴任','許渾','quantangshi','','卷30','莫言名重懒驱鸡，六代江山碧海西。
日照蒹葭明楚塞，烟分杨柳见隋堤。
荒城树暗沈书浦，旧宅花连罨画溪。
官满定知归未得，九重霄汉有丹梯。','',''),('quantangshi-29131','送沈卓少府任江都','許渾','quantangshi','','卷30','炀帝都城春水边，笙歌夜上木兰船。
三千宫女自涂地，十万人家如洞天。
艳艳花枝官舍晚，重重云影寺墙连。
少年作尉须兢慎，莫向楼前坠马鞭。','',''),('quantangshi-29132','酬邢杜二员外','許渾','quantangshi','','卷30','雪带东风洗画屏，客星悬处聚文星。
未归嵩岭暮云碧，久别杜陵春草青。
熊轼并驱因雀噪，隼旟齐驻是鸿冥。
岂知京洛旧亲友，梦绕潺湲江上亭。','',''),('quantangshi-29133','经故丁补阙郊居','許渾','quantangshi','','卷30','死酧知己道终全，波暖孤冰且自坚。
鵩上承尘才一日，鹤归华表已千年。
风吹药蔓迷樵径，雨暗芦花失钓船。
四尺孤坟何处是，阖闾城外草连天。','',''),('quantangshi-29134','陪宣城大夫崔公泛后池兼北楼宴二首 一','許渾','quantangshi','','卷30','陪泛芳池醉北楼，水花繁艳照膺舟。
亭台阴合树初昼，弦管韵高山欲秋。
皆贺虢岩终选傅，自伤燕谷未逢邹。
昔时恩遇今能否，一尉沧洲已白头。','',''),('quantangshi-29135','陪宣城大夫崔公泛后池兼北楼宴二首 二','許渾','quantangshi','','卷30','江上西来共鸟飞，翦荷浮泛似轻肥。
王珣作簿公曾喜，刘表为邦客尽依。
云外轩窗通早景，风前箫鼓送残晖。
宛陵行乐金陵住，遥对家山未忆归。','',''),('quantangshi-29136','留别赵端公','許渾','quantangshi','','卷30','海门征棹赴龙泷，暂寄华筵倒玉缸。
箫鼓散时逢夜雨，绮罗分处下秋江。
孤帆已过滕王阁，高榻留眠谢守窗。
却愿烟波阻风雪，待君同拜碧油幢。','',''),('quantangshi-29137','寄阳陵处士','許渾','quantangshi','','卷30','旧隐青山紫桂阴，一书迢遰寄归心。
谢公楼上晚花盛，杨子宅前春草深。
吴岫雨来溪鸟浴，楚江云暗岭猨吟。
野人宁忆沧洲畔，会待吹嘘定至音。','',''),('quantangshi-29138','与张道士同访李隐君不遇','許渾','quantangshi','','卷30','千岩万壑独携琴，知在陵阳不可寻。
去辙已平秋草遍，空斋长掩暮云深。
霜寒橡栗留山鼠，月冷菰蒲散水禽。
唯有西邻张仲蔚，坐来同怆别离心。','',''),('quantangshi-29139','闻州中有宴寄崔大夫兼简邢羣评事','許渾','quantangshi','','卷30','箫管筵间列翠蛾，玉杯金液耀金波。
池边雨过飘帷幕，海上风来动绮罗。
颜子巷深青草遍，庾君楼迥碧山多。
甘心不及同年友，卧听行云一曲歌。','',''),('quantangshi-29140','寄殷尧藩先辈','許渾','quantangshi','','卷30','十载功名翰墨林，为从知己信浮沈。
青山有雪谙松性，碧落无云称鹤心。
带月独归萧寺远，翫花频醉庾楼深。
思君一见如琼树，空把新诗尽日吟。','',''),('quantangshi-29141','赠河东虞押衙二首 一','許渾','quantangshi','','卷30','长剑高歌换素衣，君恩未报不言归。
旧精鸟篆谙书体，新授龙韬识战机。
万里往来征马瘦，十年离别故人稀。
生平志气何人见，空上西楼望落晖。','',''),('quantangshi-29142','赠河东虞押衙二首 二','許渾','quantangshi','','卷30','吴门风水各萍流，月满花开懒独游。
万里山川分晓梦，四邻歌管送春愁。
昔年顾我长青眼，今日逢君尽白头。
莫向尊前更惆怅，古来投笔尽封侯。','',''),('quantangshi-29143','陵阳春日寄汝洛旧游','許渾','quantangshi','','卷30','百年身世似飘蓬，泽国移家叠嶂中。
万里绿波鱼恋钓，九重青汉鹤愁笼。
西池水冷春岩雪，南浦花香晓树风。
纵倒芳尊心不醉，故人多在洛城东。','',''),('quantangshi-29144','酬杜补阙初春雨中舟次横江喜裴郎中相迎见寄','許渾','quantangshi','','卷30','江馆维舟为庾公，暖波微渌雨蒙蒙。
红桥迤逦春岩下，朱斾联翩晓树中。
柳滴圆波生细浪，梅含香艳吐轻风。
郢歌莫问青山吏，鱼在深池鸟在笼。','',''),('quantangshi-29145','送张厚浙东谒丁常侍','許渾','quantangshi','','卷30','凉露清蝉柳陌空，故人遥指浙江东。
青山有雪松当涧，碧落无云鹤出笼。
齐唱离歌愁晚月，独看征棹怨秋风。
定知洛下声名士，共说膺门得孔融。','',''),('quantangshi-29146','酬副使郑端公见寄','許渾','quantangshi','','卷30','一日高名遍九州，玄珠仍向道中求。
郢中白雪慙新唱，涂上青山忆旧游。
笙磬有文终易别，珠玑无价竟难酬。
柳营迢遰江风阔，夜夜孤吟月下楼。','',''),('quantangshi-29147','酬绵州于中丞使君见寄','許渾','quantangshi','','卷30','故人书信越襃斜，新意虽多旧约赊。
皆就一麾先去国，共谋三迳未还家。
荆巫夜隔巴西月，鄢郢春连汉上花。
半月离居犹怅望，可堪垂白各天涯。','',''),('quantangshi-29148','春早郡楼书事寄呈府中羣公','許渾','quantangshi','','卷30','两鬓垂丝髪半霜，石城孤梦绕襄阳。
鸳鸿幕里莲披槛，虎豹营中柳拂墙。
画舸欲行春水急，翠帘初卷暮山长。
岘亭风起花千片，流入南湖尽日香。','',''),('quantangshi-29149','元处士自洛归宛陵山居见示詹事相公饯行之什因赠','許渾','quantangshi','','卷30','紫霄峰下绝韦编，旧隐相如结韈前。
月落尚留东合醉，风高还忆北窗眠。
江城夜别潇潇雨，山槛晴归漠漠烟。
一顷豆花三顷竹，想应抛却钓鱼船。','',''),('quantangshi-29150','送元昼上人归苏州兼寄张厚二首 一','許渾','quantangshi','','卷30','自卜闲居荆水头，感时相别思悠悠。
一樽酒尽青山暮，千里书回碧树秋。
深巷久贫知寂寞，小诗多病尚风流。
昼公此去应相问，为说沾巾忆旧游。','',''),('quantangshi-29151','送元昼上人归苏州兼寄张厚二首 二','許渾','quantangshi','','卷30','三年无事客吴乡，南陌春园碧草长。
共醉八门回画舸，独还三径掩书堂。
前山雨过池塘满，小院秋归枕簟凉。
经岁别离心自苦，何堪黄叶落清漳。','',''),('quantangshi-29152','送陆拾遗东归','許渾','quantangshi','','卷30','独振儒风遇盛时，紫泥初降世人知。
文章报主非无意，书剑还家素有期。
秋寺卧云移棹晚，暮江乘月落帆迟。
东归自是缘清兴，莫比商山咏紫芝。','',''),('quantangshi-29153','湖南徐明府余之南邻久不还家因题林馆','許渾','quantangshi','','卷30','湘南官罢不归来，高阁经年掩绿苔。
鱼溢池塘秋雨过，鸟还洲岛暮潮回。
阶前石稳棋终局，窗外山寒酒满杯。
借问先生独何处，一篱疎菊又花开。','',''),('quantangshi-29154','酬和杜侍御','許渾','quantangshi','','卷30','花时曾省杜陵游，闻下书帷不举头。
因过石城先访戴，欲朝金阙暂依刘。
征帆夜转鸬鷀穴，骋骑春辞鹳雀楼。
正把新诗望南浦，棹歌应是木兰舟。','',''),('quantangshi-29155','酬河中杜侍御重寄','許渾','quantangshi','','卷30','五色如丝下碧空，片帆还遶楚王宫。
文章已变南山雾，羽翼应抟北海风。
春雪预呈霜简白，晓霞先染绣衣红。
十千沽酒留君醉，莫道归心似转蓬。','',''),('quantangshi-29156','寄献三川守刘公 一','許渾','quantangshi','','卷30','三川歌颂彻咸秦，十二楼前侍从臣。
休闭玉笼留鸑鷟，早开金埒纵麒麟。
花深穉榻迎何客，月在膺舟醉几人。
自笑东风过寒食，茂陵寥落未知春。','',''),('quantangshi-29157','寄献三川守刘公 二','許渾','quantangshi','','卷30','半年三度转蓬居，锦帐心阑羡隼旟。
老去自惊秦塞雁，病来先忆楚江鱼。
长闻季氏千金诺，更望刘公一纸书。
春雪未晴春酒贵，莫教愁杀马相如。','',''),('quantangshi-29158','送段觉之西蜀结婚','許渾','quantangshi','','卷30','词赋名高身不闲，彩衣如锦度函关。
镜中鸾影胡威去，剑外花归卫玠还。
秋浪远侵黄鹤岭，暮云遥断碧鸡山。
时人若问西游客，心在重霄鬓欲斑。','',''),('quantangshi-29159','长庆寺遇常州阮秀才','許渾','quantangshi','','卷30','高阁晴轩对一峰，毗陵书客此相逢。
晚收红叶题诗遍，秋待黄花酿酒浓。
山馆日斜喧鸟雀，石潭波动戏鱼龙。
上方有路应知处，疎磬寒蝉树几重。','',''),('quantangshi-29160','赠闲师','許渾','quantangshi','','卷30','近日高僧更有谁，宛陵山下遇闲师。
东林共许三乘学，南国争传五字诗。
初到庾楼红叶坠，夜投萧寺碧云随。
秋江莫惜题佳句，正是磷磷见底时。','',''),('quantangshi-29161','东游留别李丛秀才','許渾','quantangshi','','卷30','烦君沽酒强登楼，罢唱离歌说远游。
文字岂劳诸子重，风尘多幸故人忧。
数程山路长侵夜，千里家书动隔秋。
起凭栏干各垂泪，又驱羸马向东州。','',''),('quantangshi-29162','竹林寺别友人','許渾','quantangshi','','卷30','骚人吟罢起乡愁，暗觉年华似水流。
花满谢城伤共别，蝉鸣萧寺喜同游。
前山月落杉松晚，深夜风清枕簟秋。
明日分襟又何处，江南江北路悠悠。','',''),('quantangshi-29163','送处士武君归章洪山居','許渾','quantangshi','','卷30','形影无羣消息沈，登闻三击血沾襟。
皇纲一日开冤气，青史千年重壮心。
却望乌台春树老，独归蜗舍暮云深。
他时纵有征书至，雪满空山不可寻。','',''),('quantangshi-29164','题义女亭','許渾','quantangshi','','卷30','身没兰闺道日明，郭南寻得旧池亭。
诗人愁立暮山碧，贾客怨离秋草青。
四望月沈疑掩镜，两檐花动认收屏。
至今乡里风犹在，借问谁传义女铭。','',''),('quantangshi-29165','吴门送振武李从事','許渾','quantangshi','','卷30','晚促离筵醉玉缸，伊州一曲泪双双。
欲携刀笔从新幕，更宿烟霞别旧窗。
胡马近秋侵紫塞，吴帆乘月下清江。
嫖姚若许传书檄，坐筑三城看受降。','',''),('quantangshi-29166','郊居春日有怀府中诸公并柬王兵曹','許渾','quantangshi','','卷30','欲学渔翁钓艇新，濯缨犹惜九衢尘。
花前更谢依刘客，雪后空怀访戴人。
僧舍覆碁消白日，市楼赊酒过青春。
一山桃杏同时发，谁似东风不厌贫。','',''),('quantangshi-29167','同韦少尹伤故卫尉李少卿','許渾','quantangshi','','卷30','客醉更长乐未穷，似知身世一宵空。
香街宝马嘶残月，暖阁佳人哭晓风。
未卷绣筵朱阁上，已开尘席画屏中。
何须更赋山阳笛，寒月沈西水向东。','',''),('quantangshi-29168','舟行早发庐陵郡郭寄滕郎中','許渾','quantangshi','','卷30','楚客停桡太守知，露凝丹叶自秋悲。
蟹螯只恐相如渴，鲈鲙应防曼倩饥。
风卷曙云飘角远，雨昏寒浪挂帆迟。
离心更羡高斋夕，巫峡花深醉玉巵。','',''),('quantangshi-29169','闻边将刘臯无辜受戮','許渾','quantangshi','','卷30','外监多假帝王尊，威胁偏裨势不存。
才许誓心安玉垒，已伤传首动金门。
三千客里宁无义，五百人中必有恩。
却赖汉庭多烈士，至今犹自伏蒲轮。','',''),('quantangshi-29170','送薛秀才南游','許渾','quantangshi','','卷30','姑苏城外柳初凋，同上江楼更寂寥。
遶壁旧诗尘漠漠，对窗寒竹雨潇潇。
怜君别路随秋雁，尽我离觞任晚潮。
从此草玄应有处，白云青嶂一相招。','',''),('quantangshi-29171','夜归孤山寺却寄卢郎中','許渾','quantangshi','','卷30','青山有志路犹赊，心在琴书自忆家。
醉别庾楼山色晓，夜归萧寺月光斜。
落帆露湿回塘柳，别院风惊满地花。
他日此身须报德，莫言空爱旧烟霞。','',''),('quantangshi-29172','赠桐庐房明府先辈','許渾','quantangshi','','卷30','帝城春榜谪灵仙，四海声华二十年。
阙下书功无后辈，卷中文字掩前贤。
官闲每喜江山静，道在宁忧雨露偏。
自笑小儒非一鹗，亦趋门屏冀相怜。','',''),('quantangshi-29173','甘露寺感事贻同志','許渾','quantangshi','','卷30','云蔽长安路更赊，独随渔艇老天涯。
青山尽日寻黄绢，沧海经年梦绛纱。
雪愤有期心自壮，报恩无处髪先华。
东堂旧侣勤书剑，同出膺门是一家。','',''),('quantangshi-29174','泛溪夜回寄道玄上人','許渾','quantangshi','','卷30','南郭烟光异世间，碧桃红杏水潺潺。
猨来近岭猕猴散，鱼下深潭翡翠闲。
犹阻晚风停桂檝，欲乘春月访松关。
几回策杖终难去，洞口云归不见山。','',''),('quantangshi-29175','客至','許渾','quantangshi','','卷30','得路逢津更俊才，可怜鞍马照春来。
残花几日小斋闭，大笑一声幽抱开。
袖拂碧溪寒缭绕，冠欹红树晚徘徊。
相逢少别更堪恨，何必秋风江上台。','',''),('quantangshi-29176','经李给事旧居','許渾','quantangshi','','卷30','归作儒翁出致君，故山谁复有遗文。
汉庭使气摧张禹，楚国怀忧送范云。
枫叶暗时迷旧宅，芳花落处认荒坟。
朱弦一奏沈湘怨，风起寒波日欲曛。','',''),('quantangshi-29177','新兴道中','許渾','quantangshi','','卷30','芙蓉村步失官金，折狱无功不可寻。
初挂海帆逢岁暮，却开山馆值春深。
波浑未辨鱼龙迹，雾暗宁知蚌鹬心。
夜榜归舟望渔火，一溪风雨两岩阴。','',''),('quantangshi-29178','下第有怀亲友','許渾','quantangshi','','卷30','万山晴雪九衢尘，何处风光寄梦频？
花盛庾园携酒客，草深颜巷读书人。
征帆又过湘南月，旅馆还悲渭水春。
无限别情多病后，杜陵寥落在漳滨。','',''),('quantangshi-29179','中秋夕寄大梁刘尚书','許渾','quantangshi','','卷30','汴人迎拜洛人留，虎豹旌旗拥碧油。
[刁]斗严更军耳目，戈鋋长控国咽喉。
柳营出号风生纛，莲幕题诗月上楼。
应念散郎千里外，去年今夜醉兰舟。','',''),('quantangshi-29180','卧病','許渾','quantangshi','','卷30','寒窗灯尽月斜晖，佩马朝天独掩扉。
清露已凋秦塞柳，白云空长越山薇。
病中送客难为别，梦里还家不当归。
惟有寄书书未得，卧闻燕雁向南飞。','',''),('quantangshi-29181','残雪','許渾','quantangshi','','卷30','忆昨新春霰雪飞，堦前檐上鬬寒姿。
狂风送在竹深处，隔日未消花发时。
轻压嫩蔬旁出土，冷冲幽鸟别寻枝。
晚来又喜登楼见，一曲高歌和者谁。','',''),('quantangshi-29182','和常秀才寄简归州郑使君借猨','許渾','quantangshi','','卷30','谢守携猨东路长，褭藤穿竹似潇湘。
碧山初鸣啸秋月，红树生寒啼晓霜。
陌上楚人皆驻马，里中巴客半归乡。
心知欲借南游侣，未到三声恐断肠。','',''),('quantangshi-29183','送人之任邛州','許渾','quantangshi','','卷30','绿发监州丹府归，还家乐事我先知。
羣童竹马交迎日，二老兰觞初见时。
黄卷新书芸委积，青山旧路菊离披。
亨衢自有横飞势，便到西垣视训辞。','',''),('quantangshi-29184','和河南杨少尹奉陪薛司空石笋诗','許渾','quantangshi','','卷30','暖溪寒井碧岩前，谢傅宾朋盛绮筵。
云断石峰高竝笋，日临山势远开莲。
闲留幢节低春水，醉拥笙歌出暮烟。
闻道诗成归已夕，柳风花露月初圆。','',''),('quantangshi-29185','献鄜坊丘常侍','許渾','quantangshi','','卷30','诏选将军护北戎，身骑白马臂彤弓。
柳营远识金貂贵，榆塞遥知玉帐雄。
秋槛鼓鼙惊朔雪，晓阶旗纛起边风。
蓬莱每望平安火，应奏班超定远功。','',''),('quantangshi-29186','寄当涂李远','許渾','quantangshi','','卷30','赋拟相如诗似陶，云阳烟月又同袍。
车前骥病驽骀逸，架上鹰闲鸟雀高。
旧日乐贫能饮水，他时随俗愿哺糟。
不须倚向青山住，咏雪题诗用意劳。','',''),('quantangshi-29187','和崔大夫新广北楼登眺','許渾','quantangshi','','卷30','北望高楼夏亦寒，山重水阔接长安。
修梁暗换丹楹小，疎牖全开彩槛宽。
风卷浮云披睥睨，露凉明月坠阑干。
庾公恋阙怀乡处，目送归帆下远滩。','',''),('quantangshi-29188','送客自两河归江南','許渾','quantangshi','','卷30','两河庶事已堪伤，南客秋归路更长。
台畔古松悲魏帝，苑边修竹吊梁王。
山行露变茱萸色，水宿风披菡萏香。
遥羡落帆逢旧友，绿蛾青鬓醉横塘。','',''),('quantangshi-29189','题陆侍御林亭','許渾','quantangshi','','卷30','野水通池石叠台，五营无事隐雄才。
松斋下马书千卷，兰舫逢人酒一杯。
寒树雪晴红艳吐，远山云晓翠光来。
定知别后无多日，海柳江花次第开。','',''),('quantangshi-29190','泊蒜山津闻东林寺光仪上人物故','許渾','quantangshi','','卷30','云斋曾宿借方袍，因说浮生大梦劳。
言下是非齐虎尾，宿来荣辱比鸿毛。
孤舟千棹水犹阔，寒殿一灯夜更高。
明日东林有谁在，不堪秋磬拂烟涛。','',''),('quantangshi-29191','春日思旧游寄南徐从事刘三复','許渾','quantangshi','','卷30','风暖曲江花半开，忽思京口共衔杯。
湘潭云尽暮山出，巴蜀雪消春水来。
怀玉尚悲迷楚塞，捧金犹羡乐燕台。
蓟门高处极归思，陇雁北飞双燕回。','',''),('quantangshi-29192','郊园秋日寄洛中友人','許渾','quantangshi','','卷30','楚水西来天际流，感时伤别思悠悠。
一尊酒尽青山莫，万里书回碧树秋。
日落远波惊宿雁，风吹轻浪起眠鸥。
嵩阳亲友如相问，潘岳闲居欲白头。','',''),('quantangshi-29193','送杜秀才归桂林','許渾','quantangshi','','卷30','桂州南去与谁同，处处山连水自通。
两岸晓霞千里草，半帆斜日一江风。
瘴雨欲来枫树黑，火云初起荔枝红。
愁君路远销年月，莫滞三湘五岭中。','',''),('quantangshi-29194','春雨舟中次和横江裴使君见迎李赵二秀才同来因书四韵兼寄江南','許渾','quantangshi','','卷30','芳草渡头微雨时，万株杨柳拂波垂。
蒲根水暖雁初落，梅径香寒蜂未知。
词客倚风吹暗淡，使君回马湿旌旗。
江南仲蔚多情调，怅望青云几首诗。','',''),('quantangshi-29195','东陵赴京道病东归寓居开元寺寄卢员外宋魏二先辈','許渾','quantangshi','','卷30','西风吹雨雁初时，病寄僧斋罢献书。
万里咸秦劳我马，四邻松桂忆吾庐。
沧洲有约心还静，青汉无媒迹自疎。
不是醉眠愁不散，莫言琴酒学相如。','',''),('quantangshi-29196','闻开江宋相公申锡下世二首 一','許渾','quantangshi','','卷30','权门阴奏夺移才，馹骑如星堕峡来。
鼂氏有恩忠作祸，贾生无罪直为灾。
贞魂误向崇山殁，冤气疑从汩水回。
毕竟功成何处是，五湖云月一帆开。','',''),('quantangshi-29197','闻开江宋相公申锡下世二首 二','許渾','quantangshi','','卷30','月落湘潭棹不喧，玉杯瑶瑟奠苹蘩。
谁能力制乘时鹤，自取机沈在槛猨。
位极干坤三事贵，谤兴华夏一夫冤。
宵衣旰食明天子，日伏青蒲不敢言。','',''),('quantangshi-29198','赠所知','許渾','quantangshi','','卷30','因钓鲈鱼住淛河，挂帆千里亦相过。
茅檐夜醉平阶月，兰棹春归拍岸波。
湖日似阴鼍鼓响，海云才起蜃楼多。
明时又作闲居赋，谁荐东门策四科。','',''),('quantangshi-29199','谢人赠鞭','許渾','quantangshi','','卷30','蜀国名鞭见惠稀，驽骀从此长光辉。
独根拥肿来云岫，紫陌提携在绣衣。
几度拂花香里过，也曾敲𩍐月中归。
莫言三尺长无用，百万军中要指挥。','',''),('quantangshi-29200','早秋寄刘尚书','許渾','quantangshi','','卷30','天生心识富人侯，将相门中第一流。
旗纛早开擒虎帐，戈[鋋]初发斩鲸舟。
柳营书号海山暝，菌阁赋诗江树秋。
昨夜雨凉今夜月，笙歌应醉最高楼。','',''),('quantangshi-29201','及第后春情','許渾','quantangshi','','卷30','世间得意是春风，散诞经过触处通。
细摇柳脸牵长带，慢撼桃株舞碎红。
也从吹幌惊残梦，何处飘香别故丛？
犹以西都名下客，今年一月始相逢。','',''),('quantangshi-29202','归长安','許渾','quantangshi','','卷30','三年何处泪丸澜，白帝城边晓角残。
非是无心恋巫峡，自缘□臂到长安。
黔江水暖还曾饮，楚岫云深不识寒。
大抵莫教闻雨后，此时肠断不应难。','',''),('quantangshi-29203','经古行宫','許渾','quantangshi','','卷30','台阁参差倚太阳，年年花发满山香。
重门堪锁青春晚，深院垂帘白昼长。
草色芊绵侵御路，泉声呜咽绕宫墙。
先皇一去无回驾，红粉云鬟空断肠。','',''),('quantangshi-29204','秋晚怀茅山石涵村舍','許渾','quantangshi','','卷30','十亩山田近石涵，村居风俗旧曾谙。
帘前白艾惊春燕，篱上青桑待晚蚕。
云暖采茶来岭北，月明沽酒过溪南。
陵阳秋尽多归思，红树萧萧覆碧潭。','',''),('quantangshi-29205','贵游','許渾','quantangshi','','卷30','朝回佩马早凄凄，年少恩深卫霍齐。
斧钺旧威龙塞北，池台新赐凤城西。
门通碧树开金锁，楼对青山倚玉梯。
南陌行人尽回首，笙歌一曲暮云低。','',''),('quantangshi-29206','赠别','許渾','quantangshi','','卷30','眼前迎送不曾休，相续轮蹄似水流。
门外若无南北路，人间应免别离愁。
苏秦六印归何日，潘岳双毛去值秋。
莫怪分襟衔泪语，十年耕钓忆沧洲。','',''),('quantangshi-29207','秋夜与友人宿','許渾','quantangshi','','卷30','楚国同游过十霜，万重心事几堪伤。
蒹葭露白莲塘浅，砧杵夜清河汉凉。
云外山川归梦远，天涯岐路客愁长。
塞城欲晓闻吹笛，犹卧东轩月满牀。','',''),('quantangshi-29208','将赴京留赠僧院','許渾','quantangshi','','卷30','九衢尘土递追攀，马迹轩车日暮间。
玄髪尽惊为客换，白头曾见几人闲。
空悲浮世云无定，多感流年水不还。
谢却从前受恩地，归来依止叩禅关。','',''),('quantangshi-29209','寄湘中友人','許渾','quantangshi','','卷30','莫恋醉乡迷酒杯，流年长怕老年催。
西陵水阔鱼难到，南国路遥书未回。
匹马计程愁日尽，一蝉何事引秋来。
相如已定题桥志，江上无由梦钓台。','',''),('quantangshi-29210','江上逢友人','許渾','quantangshi','','卷30','故国归人酒一杯，暂停兰棹共徘徊。
村连三峡暮云起，潮送九江寒雨来。
已作相如投赋计，还凭殷浩寄书回。
到时若见东篱菊，为问经霜几度开。','',''),('quantangshi-29211','金谷怀古','許渾','quantangshi','','卷30','凄凉遗迹洛川东，浮世荣枯万古同。
桃李香销金谷在，绮罗魂断玉楼空。
往年人事伤心外，今日风光属梦中。
□□□□□□□，□□□□□□□。','',''),('quantangshi-29212','经行庐山东林寺','許渾','quantangshi','','卷30','离魂断续楚江壖，叶坠初红十月天。
紫陌事多难数悉，青山长在好闲眠。
方趋上国期干禄，未得空堂学坐禅。
他岁若教如范蠡，也应须入五湖烟。','',''),('quantangshi-29213','途中逢故人话西山读书早曾游览','許渾','quantangshi','','卷30','西岩曾到读书堂，穿竹行沙十里强。
湖上梦余波滟滟，岭头愁断路茫茫。
经过事寄烟霞远，名利尘随日月长。
莫道少年头不白，君看潘岳几茎霜。','',''),('quantangshi-29214','将赴京题陵阳王氏水居','許渾','quantangshi','','卷30','帘卷平芜接远天，暂宽行役到尊前。
是非境里有闲日，荣辱尘中无了年。
山簇暮云千野雨，江分秋水九条烟。
马蹄不道贪西去，争向一声高树蝉。','',''),('quantangshi-29215','冬日五浪馆水亭怀别','許渾','quantangshi','','卷30','芦荻花多触处飞，独凭虚槛雨微微。
寒林叶落鸟巢出，古渡浪高鱼艇稀。
云抱四山终日在，草荒三径几时归。
江城向暝东风急，一半乡愁闻捣衣。','',''),('quantangshi-29216','送别','許渾','quantangshi','','卷30','溪边杨柳色参差，攀折年年赠别离。
一片风帆望已极，三湘烟水返何时？
多缘去棹将愁远，犹倚危楼欲下迟。
莫殢酒杯闲过日，碧云深处是佳期。','',''),('quantangshi-29217','寄远','許渾','quantangshi','','卷30','两叶愁眉愁不开，独含惆怅上层台。
碧云空断雁行处，红叶已凋人未来。
塞外音书无信息，道傍车马起尘埃。
功名待寄凌烟阁，力尽辽城不肯回。','',''),('quantangshi-29218','新柳','許渾','quantangshi','','卷30','无力摇风晓色新，细腰争妒看来频。
绿阴未覆长堤水，金穗先迎上苑春。
几处伤心怀远路，一枝和日送行尘。
东□门外多离别，愁杀朝朝暮暮人。','',''),('quantangshi-29219','旅怀作','許渾','quantangshi','','卷30','促促因吟昼短诗，朝惊穠色暮空枝。
无情春色不长久，有限年光多盛衰。
往事只应随梦里，劳生何处是闲时。
眼前扰扰日一日，暗送白头人不知。','',''),('quantangshi-29220','雁','許渾','quantangshi','','卷30','万里衔芦别故乡，云飞水宿向潇湘。
数声孤枕堪垂泪，几处高楼欲断肠。
度日翩翩斜避影，临风一一直成行。
年年辛苦来衡岳，羽翼摧残陇塞霜。','',''),('quantangshi-29221','出关','許渾','quantangshi','','卷30','朝缨初解佐江滨，麋鹿心知自有羣。
汉囿猎稀慵献赋，楚山耕早任移文。
卧归渔浦月连海，行望凤城花隔云。
关吏不须迎马笑，去时无意学终军。','',''),('quantangshi-29222','寄房千里博士','許渾','quantangshi','','卷30','春风白马紫丝缰，正值蚕眠未采桑。
五夜有心随暮雨，百年无节待秋霜。
重寻绣带朱藤合，更认罗裙碧草长。
为报西游减离恨，阮郎才去嫁刘郎。','',''),('quantangshi-29223','泛五云溪','許渾','quantangshi','','卷30','此溪何处路，遥问白髯翁。
佛庙千岩里，人家一岛中。
鱼倾荷叶露，蝉噪柳林风。
急濑鸣车轴，微波漾钓筒。
石苔萦棹绿，山果拂舟红。
更就千村宿，溪桥与剡通。','',''),('quantangshi-29224','寄郴州李相公','許渾','quantangshi','','卷30','高楼王与谢，逸韵比南金。
不遇销忧日，埃尘谁复寻。
旷怀澹得丧，失意纵登临。
彩槛浮云迥，绮窗明月深。
虬龙压沧海，鸳鸯思邓林。
青云伤国器，白发轸乡心。
功高恩自洽，道直谤徒侵。
应笑灵均恨，江畔独行吟。','',''),('quantangshi-29225','赠萧炼师','許渾','quantangshi','','卷30','曾试昭阳曲，瑶斋帝自临。
红珠络绣帽，翠钿束罗襟。
双阙胡尘起，千门宿露阴。
出宫迷国步，回驾轸皇心。
桂殿春空晚，椒房夜自深。
急宣求故劒，冥契得遗簪。
暗记神仙传，潜封女史箴。
壶中知日永，掌上畏年侵。
莫比班家扇，宁同卓氏琴。
云车辞凤辇，羽帔别鸳衾。
网断鱼游藻，笼开鹤戏林。
洛烟浮碧汉，嵩月上丹岑。
露草争三秀，风篁共八音。
吹笙延鹤舞，敲磬引龙吟。
旄节纤腰举，霞杯皓腕斟。
还磨照宝镜，犹插辟寒金。
东海人情变，南山圣寿沈。
朱颜常似渥，绿髪已如寻。
养气齐生死，留形尽古今。
更求应不见，鸡犬日骎骎。','',''),('quantangshi-29226','冬日宣城开元寺赠元孚上人','許渾','quantangshi','','卷30','一钵事南宗，僧仪称病容。
曹溪花里别，萧寺竹前逢。
烛影深寒殿，经声彻曙钟。
欲斋檐睡鸽，初定壁吟蛩。
诗继休遗韵，书传永逸踪。
艺多人誉洽，机绝道情浓。
汲涧瓶沈藻，眠堦锡挂松。
云鸣新放鹤，池卧旧降龙。
露茗山厨焙，霜秔野碓舂。
梵文明处译，禅衲暖时缝。
层塔题应遍，飞轩步不慵。
绣梁交薜荔，画井倒芙蓉。
翠户垂旗网，朱窗列劒锋。
寒风金磬远，晴雪玉楼重。
妙理三乘达，清才万象供。
山高横睥睨，滩浅聚艨艟。
微雾苍平楚，残晖淡远峰。
林疎霜摵摵，波静月溶溶。
劒出因雷焕，琴全遇蔡邕。
西方知有社，支许合相从。','',''),('quantangshi-29227','维舟秦淮过温州李给事宅','許渾','quantangshi','','卷30','给事为郎日，青溪醉隐衔。
冰池通极浦，雪迳遶高岩。
珠玉砂同弃，松筠草共芟。
帝图忧一失，臣节耻三缄。
代有王陵戆，时无靳尚谗。
定应标直笔，宁为发空函。
雾黑连云栈，风狂截海帆。
石梯迎雨润，沙井待潮咸。
蜡屐青筇杖，蓝舆白罽衫。
应劳北归梦，山路正巉巉。','',''),('quantangshi-29228','登蒜山观发军','許渾','quantangshi','','卷30','羽檄征兵急，辕门选将雄。
犬羊忧破竹，貔虎极飞蓬。
定系猖狂虏，何烦矍铄翁。
更探黄石略，重振黑山功。
别马嘶营柳，惊乌散井桐。
低星连宝剑，残月让雕弓。
浪晓戈鋋里，山晴鼓角中。
甲开鱼照水，旗扬虎拏风。
去想金河远，行知玉塞空。
汉庭应有问，师律在元戎。','',''),('quantangshi-29229','送从兄别驾归蜀','許渾','quantangshi','','卷30','闻与湘南令，童年侍玉墀。
家留秦塞曲，官谪瘴溪湄。
道直奸臣屏，冤深圣主知。
逝川东去疾，霈泽北来迟。
青汉龙髯绝，苍岑马鬣移。
风凄闻笛处，月惨罢琴时。
客路黄公庙，乡关白帝祠。
已称鹦鹉赋，宁诵鹡鸰诗。
远道书难达，长亭酒莫持。
当凭蜀江水，万里寄相思。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-29230','金陵阻风登延祚阁','許渾','quantangshi','','卷30','极目皆陈迹，披图问远公。
戈鋋三国后，冠盖六朝中。
葛蔓交残垒，芒花没后宫。
水流箫鼓绝，山在绮罗空。
极浦千艘聚，高台一径通。
云移吴岫雨，潮转楚江风。
登阁慙漂梗，停舟忆断蓬。
归期与归路，杉桂海门东。','',''),('quantangshi-29231','送林处士自闽中道越由霅抵两川','許渾','quantangshi','','卷30','书劒少青眼，烟波初白头。
乡关背梨岭，客路转苹洲。
处困道难固，乘时恩易酬。
镜中非访戴，劒外欲依刘。
高枕海天暝，落帆江雨秋。
鼍声应远鼓，蜃气学危楼。
智士役千虑，达人经百忧。
唯闻陶靖节，多在醉乡游。','',''),('quantangshi-29232','宣城赠萧兵曹','許渾','quantangshi','','卷30','桂檝谪湘渚，三年波上春。
舟寒剡溪雪，衣破洛城尘。
客道耻摇尾，皇恩宽犯鳞。
花时去国远，月夕上楼频。
贪酒不辞病，佣书非为贫。
行吟值渔父，坐隐对樵人。
紫陌罢双辙，碧潭穷一纶。
高歌更南去，烟水是通津。','',''),('quantangshi-29233','秋夕宴李侍御宅','許渾','quantangshi','','卷30','公子征词客，秋堂递玉杯。
月高罗幕卷，风度锦屏开。
凤管添簧品，鵾弦促柱哀。
转喉云旋合，垂手露徐来。
烛换三条烬，香销十炷灰。
蛩声闻鼓歇，萤焰触帘回。
广槛烟分柳，空庭露积苔。
解酲须满酌，应为拨新醅。','',''),('quantangshi-29234','晨自竹径至龙兴寺崇隐上人院','許渾','quantangshi','','卷30','佛寺通南径，僧堂倚北坡。
藤阴迷晚竹，苔滑仰晴莎。
病忆春前别，闲宜雨后过。
石横闻水远，林缺见山多。
欲结三天社，初降十地魔。
毒龙来有窟，灵鹤去无窠。
客路随萍梗，乡园失薜萝。
禅心如可学，不藉鲁阳戈。','',''),('quantangshi-29235','岁暮自广江至新兴往复中题峡山寺四首 一','許渾','quantangshi','','卷30','夜醉晨方醒，孤吟恐失羣。
海䲡潮上见，江鹄雾中闻。
未腊梅先实，经冬草自薰。
树随山崦合，泉到石棱分。
虎迹空林雨，猨声绝岭云。
萧萧异乡鬓，明日共丝棼。','',''),('quantangshi-29236','岁暮自广江至新兴往复中题峡山寺四首 二','許渾','quantangshi','','卷30','薄暮缘西峡，停桡一访僧。
鹭巢横卧柳，猨饮倒垂藤。
水曲岩千叠，云重树百层。
山风寒殿磬，溪雨夜船灯。
滩涨危槎没，泉冲怪石崩。
中台一襟泪，岁杪别良朋。','',''),('quantangshi-29237','岁暮自广江至新兴往复中题峡山寺四首 三','許渾','quantangshi','','卷30','密树分苍壁，长溪抱碧岑。
海风闻鹤远，潭日见鱼深。
松盖环清韵，榕根架绿阴。
洞丁多斵石，蛮女半淘金。
