几时緜竹颂，拟荐子虚名。','',''),('quantangshi-29313','崔处士','李商隱','quantangshi','','卷30','真人塞其内，夫子入于机。
未肯投竿起，惟欢负米归。
雪中东郭履，堂上老莱衣。
读遍先贤传，如君事者稀。','',''),('quantangshi-29314','自喜','李商隱','quantangshi','','卷30','自喜蜗牛舍，兼容燕子巢。
绿筠遗粉箨，红药绽香苞。
虎过遥知穽，鱼来且佐庖。
慢行成酩酊，邻壁有松醪。','',''),('quantangshi-29315','题僧壁','李商隱','quantangshi','','卷30','舍生求道有前踪，乞脑剜身结愿重。
大去便应欺粟颗，小来兼可隐针锋。
蚌胎未满思新桂，琥珀初成忆旧松。
若信贝多真实语，三生同听一楼钟。','',''),('quantangshi-29316','霜月','李商隱','quantangshi','','卷30','初闻征雁已无蝉，百尺楼高水接天。
青女素娥俱耐冷，月中霜里鬬婵娟。','',''),('quantangshi-29317','异俗二首 一','李商隱','quantangshi','','卷30','鬼疟朝朝避，春寒夜夜添。
未惊雷破柱，不报水齐檐。
虎箭侵肤毒，鱼钩刺骨銛。
鸟言成谍诉，多是恨彤幨。','',''),('quantangshi-29318','异俗二首 二','李商隱','quantangshi','','卷30','户尽悬秦网，家多事越巫。
未曾容獭祭，只是纵猪都。
点对连鳌饵，搜求缚虎符。
贾生兼事鬼，不信有洪炉。','',''),('quantangshi-29319','归墅','李商隱','quantangshi','','卷30','行李逾南极，旬时到旧乡。
楚芝应徧紫，邓橘未全黄。
渠浊村舂急，旗高社酒香。
故山归梦喜，先入读书堂。','',''),('quantangshi-29320','商于','李商隱','quantangshi','','卷30','商于朝雨霁，归路有秋光。
背坞猿收果，投岩麝退香。
建瓴真得势，横戟岂能当。
割地张仪诈，谋身绮季长。
清渠州外月，黄叶庙前霜。
今日看云意，依依入帝乡。','',''),('quantangshi-29321','和孙朴韦蟾孔雀咏','李商隱','quantangshi','','卷30','此去三梁远，今来万里携。
西施因网得，秦客被花迷。
可在青鹦鹉，非关碧野鸡。
约眉怜翠羽，刮目想金篦。
瘴气笼飞远，蛮花向坐低。
轻于赵皇后，贵极楚悬黎。
都护矜罗幕，佳人炫绣袿。
屏风临烛扣，捍拨倚香脐。
旧思牵云叶，新愁待雪泥。
爱堪通梦寐，画得不端倪。
地锦排苍雁，帘钉镂白犀。
曙霞星斗外，凉月露盘西。
妬好休夸舞，经寒且少啼。
红楼三十级，稳稳上丹梯。','',''),('quantangshi-29322','人欲','李商隱','quantangshi','','卷30','人欲天从竟不疑，莫言圆盖便无私。
秦中已久乌头白，却是君王未备知。','',''),('quantangshi-29323','华山题王母祠','李商隱','quantangshi','','卷30','莲华峰下锁雕梁，此去瑶池地共长。
好为麻姑到东海，劝栽黄竹莫栽桑。','',''),('quantangshi-29324','华清宫','李商隱','quantangshi','','卷30','华清恩幸古无伦，犹恐蛾眉不胜人。
未免被他褒女笑，只教天子暂蒙尘。','',''),('quantangshi-29325','楚泽','李商隱','quantangshi','','卷30','夕阳归路后，霜野物声干。
集鸟翻渔艇，残虹拂马鞍。
刘桢元抱病，虞寄数辞官。
白袷经年卷，西来及早寒。','',''),('quantangshi-29326','蝉','李商隱','quantangshi','','卷30','本以高难饱，徒劳恨费声。
五更疎欲断，一树碧无情。
薄宦梗犹泛，故园芜已平。
烦君最相警，我亦举家清。','',''),('quantangshi-29327','江亭散席循柳路吟','李商隱','quantangshi','','卷30','春咏敢轻裁，衔辞入半杯。
已遭江映柳，更被雪藏梅。
寡和真徒尔，殷忧动即来。
从诗得何报，惟感二毛催。','',''),('quantangshi-29328','潭州','李商隱','quantangshi','','卷30','潭州官舍暮楼空，今古无端入望中。
湘泪浅深滋竹色，楚歌重叠怨兰丛。
陶公战舰空滩雨，贾傅承尘破庙风。
目断故园人不至，松醪一醉与谁同。','',''),('quantangshi-29329','赠刘司户','李商隱','quantangshi','','卷30','江风吹浪动云根，重碇危樯白日昏。
已断燕鸿初起势，更惊骚客后归魂。
汉廷急诏谁先入，楚路高歌自欲翻。
万里相逢欢复泣，凤巢西隔九重门。','',''),('quantangshi-29330','哭刘司户二首 一','李商隱','quantangshi','','卷30','离居星岁易，失望死生分。
酒瓮凝余桂，书签冷旧芸。
江风吹雁急，山木带蝉曛。
一呌千回首，天高不为闻。','',''),('quantangshi-29331','哭刘司户二首 二','李商隱','quantangshi','','卷30','有美扶皇运，无谁荐直言。
已为秦逐客，复作楚冤魂。
湓浦应分派，荆江有会源。
并将添恨泪，一洒问干坤。','',''),('quantangshi-29332','悼伤后赴东蜀辟至散关遇雪','李商隱','quantangshi','','卷30','剑外从军远，无家与寄衣。
散关三尺雪，回梦旧鸳机。','',''),('quantangshi-29333','乐游原','李商隱','quantangshi','','卷30','向晚意不适，驱车登古原。
夕阳无限好，只是近黄昏。','',''),('quantangshi-29334','北齐二首 一','李商隱','quantangshi','','卷30','一笑相倾国便亡，何劳荆棘始堪伤。
小怜玉体横陈夜，已报周师入晋阳。','',''),('quantangshi-29335','北齐二首 二','李商隱','quantangshi','','卷30','巧笑知堪敌万几，倾城最在着戎衣。
晋阳已陷休回顾，更请君王猎一围。','',''),('quantangshi-29336','街西池馆','李商隱','quantangshi','','卷30','白阁他年别，朱门此夜过。
疎帘留月魄，珍簟接烟波。
太守三刀梦，将军一箭歌。
国租容客旅，香熟玉山禾。','',''),('quantangshi-29337','南朝','李商隱','quantangshi','','卷30','玄武湖中玉漏催，鸡鸣埭口绣襦回。
谁言琼树朝朝见，不及金莲步步来。
敌国军营漂木柹，前朝神庙锁烟煤。
满宫学士皆颜色，江令当年只费才。','',''),('quantangshi-29338','复京','李商隱','quantangshi','','卷30','虏骑胡兵一战摧，万灵回首贺轩台。
天教李令心如日，可要昭陵石马来。','',''),('quantangshi-29339','浑河中','李商隱','quantangshi','','卷30','九庙无尘八马回，奉天城垒长春苔。
咸阳原上英雄骨，半向君家养马来。','',''),('quantangshi-29340','鄠杜马上念汉书','李商隱','quantangshi','','卷30','世上苍龙种，人间武帝孙。
小来惟射猎，兴罢得干坤。
渭水天开苑，咸阳地献原。
英灵殊未已，丁傅渐华轩。','',''),('quantangshi-29341','柳','李商隱','quantangshi','','卷30','动春何限叶，撼晓几多枝。
解有相思[否]，应无不舞时。
絮飞藏皓蝶，带弱露黄鹂。
倾国宜通体，谁来独赏眉。','',''),('quantangshi-29342','巴江柳','李商隱','quantangshi','','卷30','巴江可惜柳，柳色绿侵江。
好向金銮殿，移阴入绮窗。','',''),('quantangshi-29343','咸阳','李商隱','quantangshi','','卷30','咸阳宫阙郁嵯峨，六国楼台艳绮罗。
自是当时天帝醉，不关秦地有山河。','',''),('quantangshi-29344','同崔八诣药山访融禅师','李商隱','quantangshi','','卷30','共受征南不次恩，报恩惟是有忘言。
岩花涧草西林路，未见高僧只见猿。','',''),('quantangshi-29345','闻着明凶问哭寄飞卿','李商隱','quantangshi','','卷30','昔叹谗销骨，今伤泪满膺。
空余双玉剑，无复一壶冰。
江势翻银砾，天文露玉绳。
何因携庾信，同去哭徐陵。','',''),('quantangshi-29346','听鼓','李商隱','quantangshi','','卷30','城头叠鼓声，城下暮江清。
欲问渔阳掺，时无禰正平。','',''),('quantangshi-29347','送崔珏往西川','李商隱','quantangshi','','卷30','年少因何有旅愁，欲为东下更西游。
一条雪浪吼巫峡，千里火云烧益州。
卜肆至今多寂寞，酒垆从古擅风流。
浣花牋纸桃花色，好好题诗咏玉钩。','',''),('quantangshi-29348','代赠','李商隱','quantangshi','','卷30','杨柳路尽处，芙蓉湖上头。
虽同锦步障，独映钿箜篌。
鸳鸯可羡头俱白，飞去飞来烟雨秋。','',''),('quantangshi-29349','桂林','李商隱','quantangshi','','卷30','城窄山将压，江宽地共浮。
东南通绝域，西北有高楼。
神护青枫岸，龙移白石湫。
殊乡竟何祷，箫鼓不曾休。','',''),('quantangshi-29350','夜雨寄北','李商隱','quantangshi','','卷30','君问归期未有期，巴山夜雨涨秋池。
何当共剪西窗烛，却话巴山夜雨时。','',''),('quantangshi-29351','陈后宫','李商隱','quantangshi','','卷30','茂苑城如画，阊门瓦欲流。
还依水光殿，更起月华楼。
侵夜鸾开镜，迎冬雉献裘。
从臣皆半醉，天子正无愁。','',''),('quantangshi-29352','属疾','李商隱','quantangshi','','卷30','许靖犹羁宦，安仁复悼亡。
兹辰聊属疾，何日免殊方。
秋蝶无端丽，寒花只暂香。
多情真命薄，容易即回肠。','',''),('quantangshi-29353','石榴','李商隱','quantangshi','','卷30','榴枝婀娜榴实繁，榴膜轻明榴子鲜。
可羡瑶池碧桃树，碧桃红颊一千年。','',''),('quantangshi-29354','明日','李商隱','quantangshi','','卷30','天上参旗过，人间烛焰销。
谁言整双履，便是隔三桥。
知处黄金鏁，曾来碧绮寮。
凭栏明日意，池阔雨萧萧。','',''),('quantangshi-29355','饮席戏赠同舍','李商隱','quantangshi','','卷30','洞中屐响省分携，不是花迷客自迷。
珠树重行怜翡翠，玉楼双舞羡鵾鸡。
兰回旧蘂缘屏绿，椒缀新香和壁泥。
唱尽阳关无限叠，半杯松叶冻颇黎。','',''),('quantangshi-29356','西溪','李商隱','quantangshi','','卷30','近郭西溪好，谁堪共酒壶。
苦吟防柳恽，多泪怯杨朱。
野鹤随君子，寒松揖大夫。
天涯常病意，岑寂胜欢娱。','',''),('quantangshi-29357','忆梅','李商隱','quantangshi','','卷30','定定住天涯，依依向物华。
寒梅最堪恨，常作去年花。','',''),('quantangshi-29358','赠柳','李商隱','quantangshi','','卷30','章台从掩映，郢路更参差。
见说风流极，来当婀娜时。
桥回行欲断，堤远意相随。
忍放花如雪，青楼扑酒旗。','',''),('quantangshi-29359','谑柳','李商隱','quantangshi','','卷30','已带黄金缕，仍飞白玉花。
长时须拂马，密处少藏鸦。
眉细从他敛，腰轻莫自斜。
玳梁谁道好，偏拟映卢家。','',''),('quantangshi-29360','北禽','李商隱','quantangshi','','卷30','为恋巴江好，无辞瘴雾蒸。
纵能朝杜宇，可得值苍鹰。
石小虚填海，芦銛未破矰。','',''),('quantangshi-29361','初起','李商隱','quantangshi','','卷30','想像咸池日欲光，五更钟后更回肠。
三年苦雾巴江水，不为离人照屋梁。','',''),('quantangshi-29362','楚宫','李商隱','quantangshi','','卷30','复壁交青琐，重帘挂紫绳。
如何一柱观，不碍九枝灯。
扇薄常规月，钗斜只镂冰。
歌成犹未唱，秦火入夷陵。','',''),('quantangshi-29363','柳','李商隱','quantangshi','','卷30','柳映江潭底有情，望中频遣客心惊。
巴雷隐隐千山外，更作章台走马声。','',''),('quantangshi-29364','石城','李商隱','quantangshi','','卷30','石城夸窈窕，花县更风流。
簟冰将飘枕，帘烘不隐钩。
玉童收夜钥，金狄守更筹。
共笑鸳鸯绮，鸳鸯两白头。','',''),('quantangshi-29365','韩碑','李商隱','quantangshi','','卷30','元和天子神武姿，彼何人哉轩与羲。
誓将上雪列圣耻，坐法宫中朝四夷。
淮西有贼五十载，封狼生貙貙生罴。
不据山河据平地，长戈利矛日可麾。
帝得圣相相曰度，贼斫不死神扶持。
腰悬相印作都统，阴风惨澹天王旗。
愬武古通作牙爪，仪曹外郎载笔随。
行军司马智且勇，十四万众犹虎貔。
入蔡缚贼献太庙，功无与让恩不訾。
帝曰汝度功第一，汝从事愈宜为辞。
愈拜稽首蹈且舞，金石刻画臣能为。
古者世称大手笔，此事不系于职司。
当仁自古有不让，言讫屡颔天子颐。
公退斋戒坐小阁，濡染大笔何淋漓。
点窜尧典舜典字，涂改清庙生民诗。
文成破体书在纸，清晨再拜铺丹墀。
表曰臣愈昧死上，咏神圣功书之碑。
碑高三丈字如斗，负以灵鳌蟠以螭。
句奇语重喻者少，谗之天子言其私。
长绳百尺拽碑倒，麤砂大石相磨治。
公之斯文若元气，先时已入人肝脾。
汤盘孔鼎有述作，今无其器存其辞。
呜呼圣皇及圣相，相与烜赫流淳熙。
公之斯文不示后，曷与三五相攀追。
愿书万本诵万过，口角流沫右手胝。
传之七十有二代，以为封禅玉检明堂基。','',''),('quantangshi-29366','令狐八拾遗见招送裴十四归华州','李商隱','quantangshi','','卷30','二十中郎未足希，骊驹先自有光辉。
兰亭宴罢方回去，雪夜诗成道韫归。
汉苑风烟吹客梦，云台洞穴接郊扉。
嗟予久抱临邛渴，便欲因君问钓矶。','',''),('quantangshi-29367','离思','李商隱','quantangshi','','卷30','气尽前溪舞，心酸子夜歌。
峡云寻不得，沟水欲如何。
朔雁传书绝，湘篁染泪多。
无由见颜色，还自托微波。','',''),('quantangshi-29368','宿骆氏亭寄怀崔雍衮','李商隱','quantangshi','','卷30','竹坞无尘水槛清，相思迢递隔重城。
秋阴不散霜飞晚，留得枯荷听雨声。','',''),('quantangshi-29369','风雨','李商隱','quantangshi','','卷30','凄凉宝剑篇，羁泊欲穷年。
黄叶仍风雨，青楼自管弦。
新知遭薄俗，旧好隔良缘。
心断新丰酒，销愁斗几千。','',''),('quantangshi-29370','梦泽','李商隱','quantangshi','','卷30','梦泽悲风动白茅，楚王葬尽满城娇。
未知歌舞能多少，虚减宫厨为细腰。','',''),('quantangshi-29371','赠歌妓二首 一','李商隱','quantangshi','','卷30','水精如意玉连环，下蔡城危莫破颜。
红绽樱桃含白雪，断肠声里唱阳关。','',''),('quantangshi-29372','赠歌妓二首 二','李商隱','quantangshi','','卷30','白日相思可奈何，严城清夜断经过。
只知解道春来瘦，不道春来独自多。','',''),('quantangshi-29373','谢书','李商隱','quantangshi','','卷30','微意何曾有一毫，空携笔砚奉龙韬。
自蒙半夜传衣后，不羡王祥得佩刀。','',''),('quantangshi-29374','寄令狐学士','李商隱','quantangshi','','卷30','秘殿崔嵬拂彩霓，曹司今在殿东西。
赓歌太液翻黄鹄，从猎陈仓获碧鸡。
晓饮岂知金掌迥，夜吟应讶玉绳低。
钧天虽许人间听，阊阖门多梦自迷。','',''),('quantangshi-29375','酬令狐郎中见寄','李商隱','quantangshi','','卷30','望郎临古郡，佳句洒丹青。
应自丘迟宅，仍过柳恽汀。
封来江渺渺，信去雨冥冥。
句曲闻仙诀，临川得佛经。
朝吟搘客枕，夜读漱僧瓶。
不见衔芦雁，空流腐草萤。
土宜悲坎井，天怒识雷霆。
象卉分疆近，蛟涎浸岸腥。
补羸贪紫桂，负气托青萍。
万里悬离抱，危于讼合铃。','',''),('quantangshi-29376','七月二十八日夜与王郑二秀才听雨后梦作','李商隱','quantangshi','','卷30','初梦龙宫宝焰然，瑞霞明丽满晴天。
旋成醉倚蓬莱树，有个仙人拍我肩。
少顷远闻吹细管，闻声不见隔飞烟。
逡巡又过潇湘雨，雨打湘灵五十弦。
瞥见冯夷殊怅望，鲛绡休卖海为田。
亦逢毛女无憀极，龙伯擎将华岳莲。
恍惚无倪明又暗，低迷不已断还连。
觉来正是平阶雨，独背寒灯枕手眠。','',''),('quantangshi-29377','寄令狐郎中','李商隱','quantangshi','','卷30','嵩云秦树久离居，双鲤迢迢一纸书。
休问梁园旧宾客，茂陵秋雨病相如。','',''),('quantangshi-29378','漫成三首 一','李商隱','quantangshi','','卷30','不妨何范尽诗家，未解当年重物华。
远把龙山千里雪，将来拟并洛阳花。','',''),('quantangshi-29379','漫成三首 二','李商隱','quantangshi','','卷30','沈约怜何逊，延年毁谢庄。
清新俱有得，名誉底相伤。','',''),('quantangshi-29380','漫成三首 三','李商隱','quantangshi','','卷30','雾夕咏芙蕖，何郎得意初。
此时谁最赏，沈范两尚书。','',''),('quantangshi-29381','无题','李商隱','quantangshi','','卷30','白道萦回入暮霞，斑骓嘶断七香车。
春风自共何人笑，枉破阳城十万家。','',''),('quantangshi-29382','槿花二首 一','李商隱','quantangshi','','卷30','燕体伤风力，鸡香积露文。
殷鲜一相杂，啼笑两难分。
月里宁无姊，云中亦有君。
三清与仙岛，何事亦离羣。','',''),('quantangshi-29383','槿花二首 二','李商隱','quantangshi','','卷30','珠馆薰燃久，玉房梳扫余。
烧兰才作烛，襞锦不成书。
本以亭亭远，翻嫌眽眽疎。
回头问残照，残照更空虚。','',''),('quantangshi-29384','哭刘蕡','李商隱','quantangshi','','卷30','上帝深宫闭九阍，巫咸不下问衔冤。
广陵别后春涛隔，湓浦书来秋雨翻。
只有安仁能作诔，何曾宋玉解招魂。
平生风义兼师友，不敢同君哭寝门。','',''),('quantangshi-29385','杜司勋','李商隱','quantangshi','','卷30','高楼风雨感斯文，短翼差池不及羣。
刻意伤春复伤别，人间惟有杜司勋。','',''),('quantangshi-29386','荆门西下','李商隱','quantangshi','','卷30','一夕南风一叶危，荆云回望夏云时。
人生岂得轻离别，天意何曾忌嶮巇。
骨肉书题安绝徼，蕙兰蹊径失佳期。
洞庭湖阔蛟龙恶，却羡杨朱泣路岐。','',''),('quantangshi-29387','碧瓦','李商隱','quantangshi','','卷30','碧瓦衔珠树，红轮结绮寮。
无双汉殿鬓，第一楚宫腰。
雾唾香难尽，珠啼冷易销。
歌从雍门学，酒是蜀城烧。
柳暗将翻巷，荷欹正抱桥。
钿辕开道入，金管隔隣调。
梦到飞魂急，书成即席遥。
河流冲柱转，海沫近槎飘。
吴市蠀蛦甲，巴賨翡翠翘。
他时未知意，重叠赠娇饶。','',''),('quantangshi-29388','蜨','李商隱','quantangshi','','卷30','叶叶复翻翻，斜桥对侧门。
芦花惟有白，柳絮可能温。
西子寻遗殿，昭君觅故村。
年年芳物尽，来别败兰荪。','',''),('quantangshi-29389','蝇蜨鸡麝鸶凤等成篇','李商隱','quantangshi','','卷30','韩蝶翻罗幕，曹蝇拂绮窗。
鬬鸡回玉勒，融麝暖金釭。
瑇瑁明书阁，琉璃冰酒缸。
画楼多有主，鸾凤各双双。','',''),('quantangshi-29390','韩翃舍人即事','李商隱','quantangshi','','卷30','萱草含丹粉，荷花抱绿房。
鸟应悲蜀帝，蝉是怨齐王。
通内藏珠府，应官解玉坊。
桥南荀令过，十里送衣香。','',''),('quantangshi-29391','公子','李商隱','quantangshi','','卷30','一盏新罗酒，凌晨恐易消。
归应冲鼓半，去不待笙调。
歌好惟愁和，香浓岂惜飘。
春场铺艾帐，下马雉媒娇。','',''),('quantangshi-29392','子初全溪作','李商隱','quantangshi','','卷30','全溪不可到，况复尽余醅。
汉苑生春水，昆池换劫灰。
战蒲知雁唼，皱月觉鱼来。
清兴恭闻命，言诗未敢回。','',''),('quantangshi-29393','杨本胜说于长安见小男阿衮','李商隱','quantangshi','','卷30','闻君来日下，见我最娇儿。
渐大啼应数，长贫学恐迟。
寄人龙种瘦，失母凤雏痴。
语罢休边角，青灯两鬓丝。','',''),('quantangshi-29394','西溪','李商隱','quantangshi','','卷30','怅望西溪水，潺湲奈尔何。
不惊春物少，只觉夕阳多。
色染妖韶柳，光含窈窕萝。
人间从到海，天上莫为河。
凤女弹瑶瑟，龙孙撼玉珂。
京华他夜梦，好好寄云波。','',''),('quantangshi-29395','柳下暗记','李商隱','quantangshi','','卷30','无奈巴南柳，千条傍吹台。
更将黄映白，拟作杏花媒。','',''),('quantangshi-29396','妓席','李商隱','quantangshi','','卷30','乐府闻桃叶，人前道得无。
劝君书小字，慎莫唤官奴。','',''),('quantangshi-29397','少年','李商隱','quantangshi','','卷30','外戚平羌第一功，生年二十有重封。
直登宣室螭头上，横过干泉豹尾中。
别馆觉来云雨梦，后门归去蕙兰丛。
灞陵夜猎随田窦，不识寒郊自转蓬。','',''),('quantangshi-29398','无题','李商隱','quantangshi','','卷30','近知名阿侯，住处小江流。
腰细不胜舞，眉长惟是愁。
黄金堪作屋，何不作重楼。','',''),('quantangshi-29399','玄微先生','李商隱','quantangshi','','卷30','仙翁无定数，时入一壶藏。
夜夜桂露湿，村村桃水香。
醉中抛浩劫，宿处起神光。
药裹丹山凤，碁函白石郎。
弄河移砥柱，吞日倚扶桑。
龙竹裁轻策，鲛绡熨下裳。
树栽嗤汉帝，桥扳笑秦王。
径欲随关令，龙沙万里强。','',''),('quantangshi-29400','药转','李商隱','quantangshi','','卷30','郁金堂北画楼东，换骨神方上药通。
露气暗连青桂苑，风声偏猎紫兰丛。
长筹未必输孙皓，香枣何劳问石崇。
忆事怀人兼得句，翠衾归卧绣帘中。','',''),('quantangshi-29401','岳阳楼','李商隱','quantangshi','','卷30','欲为平生一散愁，洞庭湖上岳阳楼。
可怜万里堪乘兴，枉是蛟龙解覆舟。','',''),('quantangshi-29402','寄成都高苗二从事','李商隱','quantangshi','','卷30','家近红蕖曲水滨，全家罗袜起秋尘。
莫将越客千丝网，网得西施别赠人。','',''),('quantangshi-29403','岳阳楼','李商隱','quantangshi','','卷30','汉水方城带百蛮，四隣谁道乱周班。
如何一梦高唐雨，自此无心入武关。','',''),('quantangshi-29404','越燕二首 一','李商隱','quantangshi','','卷30','上国社方见，此乡秋不归。
为矜皇后舞，犹着羽人衣。
拂水斜纹乱，衔花片影微。
卢家文杏好，试近莫愁飞。','',''),('quantangshi-29405','越燕二首 二','李商隱','quantangshi','','卷30','将泥红蓼岸，得草绿杨村。
命侣添新意，安巢复旧痕。
去应逢阿母，来莫害王孙。
记取丹山凤，今为百鸟尊。','',''),('quantangshi-29406','杜工部蜀中离席','李商隱','quantangshi','','卷30','人生何处不离羣，世路干戈惜暂分。
雪岭未归天外使，松州犹驻殿前军。
座中醉客延醒客，江上晴云杂雨云。
美酒成都堪送老，当垆仍是卓文君。','',''),('quantangshi-29407','隋宫','李商隱','quantangshi','','卷30','紫泉宫殿锁烟霞，欲取芜城作帝家。
玉玺不缘归日角，锦帆应是到天涯。
于今腐草无萤火，终古垂杨有暮鸦。
地下若逢陈后主，岂宜重问后庭花。','',''),('quantangshi-29408','二月二日','李商隱','quantangshi','','卷30','二月二日江上行，东风日暖闻吹笙。
花须柳眼各无赖，紫蝶黄蜂俱有情。
万里忆归元亮井，三年从事亚夫营。
新滩莫悟游人意，更作风檐夜雨声。','',''),('quantangshi-29409','筹笔驿','李商隱','quantangshi','','卷30','猿鸟犹疑畏简书，风云常为护储胥。
徒令上将挥神笔，终见降王走传车。
管乐有才终不忝，关张无命欲何如。
他年锦里经祠庙，梁父吟成恨有余。','',''),('quantangshi-29410','屏风','李商隱','quantangshi','','卷30','六曲连环接翠帷，高楼半夜酒醒时。
掩灯遮雾密如此，雨落月明俱不知。','',''),('quantangshi-29411','春日','李商隱','quantangshi','','卷30','欲入卢家白玉堂，新春催破舞衣裳。
蝶衔红蘂蜂衔粉，共助青楼一日忙。','',''),('quantangshi-29412','武侯庙古柏','李商隱','quantangshi','','卷30','蜀相阶前柏，龙蛇捧閟宫。
阴成外江畔，老向惠陵东。
大树思冯异，甘棠忆召公。
叶凋湘燕雨，枝拆海鹏风。
玉垒经纶远，金刀历数终。
谁将出师表，一为问昭融。','',''),('quantangshi-29413','风','李商隱','quantangshi','','卷30','撩钗盘孔雀，恼带拂鸳鸯。
萝荐谁教近，斋时锁洞房。','',''),('quantangshi-29414','即日','李商隱','quantangshi','','卷30','一岁林花即日休，江间亭下怅淹留。
重吟细把真无奈，已落犹开未放愁。
山色正来衔小苑，春阴只欲傍高楼。
金鞍忽散银壶漏，更醉谁家白玉钩。','',''),('quantangshi-29415','九成宫','李商隱','quantangshi','','卷30','十二层城阆苑西，平时避暑拂虹霓。
云随夏后双龙尾，风逐周王八骏蹄。
吴岳晓光连翠巘，甘泉晚景上丹梯。
荔枝卢橘沾恩幸，鸾鹊天书湿紫泥。','',''),('quantangshi-29416','少将','李商隱','quantangshi','','卷30','族亚齐安陆，风高汉武威。
烟波别墅醉，花月后门归。
青海闻传箭，天山报合围。
一朝携剑起，上马即如飞。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-29417','咏史','李商隱','quantangshi','','卷30','历览前贤国与家，成由勤俭破由奢。
何须琥珀方为枕，岂得真珠始是车。
运去不逢青海马，力穷难拔蜀山蛇。
几人曾预南薰曲，终古苍梧哭翠华。','',''),('quantangshi-29418','赠白道者','李商隱','quantangshi','','卷30','十二楼前再拜辞，灵风正满碧桃枝。
壶中若是有天地，又向壶中伤别离。','',''),('quantangshi-29419','无题二首 一','李商隱','quantangshi','','卷30','昨夜星辰昨夜风，画楼西畔桂堂东。
身无彩凤双飞翼，心有灵犀一点通。
隔座送钩春酒暖，分曹射覆蜡灯红。
嗟余听鼓应官去，走马兰台类断蓬。','',''),('quantangshi-29420','无题二首 二','李商隱','quantangshi','','卷30','闻到阊门萼绿华，昔年相望抵天涯。
岂知一夜秦楼客，偷看吴王苑内花。','',''),('quantangshi-29421','汉宫词','李商隱','quantangshi','','卷30','青雀西飞竟未回，君王长在集灵台。
侍臣最有相如渴，不赐金茎露一杯。','',''),('quantangshi-29422','无题四首 一','李商隱','quantangshi','','卷30','来是空言去绝踪，月斜楼上五更钟。
梦为远别啼难唤，书被催成墨未浓。
蜡照半笼金翡翠，麝熏微度绣芙蓉。
刘郎已恨蓬山远，更隔蓬山一万重。','',''),('quantangshi-29423','无题四首 二','李商隱','quantangshi','','卷30','飒飒东风细雨来，芙蓉塘外有轻雷。
金蟾啮鏁烧香入，玉虎牵丝汲井回。
贾氏窥帘韩掾少，宓妃留枕魏王才。
春心莫共花争发，一寸相思一寸灰。','',''),('quantangshi-29424','无题四首 三','李商隱','quantangshi','','卷30','含情春晼晚，暂见夜阑干。
楼响将登怯，帘烘欲过难。
多羞钗上燕，真愧镜中鸾。
归去横塘晓，华星送宝鞍。','',''),('quantangshi-29425','无题四首 四','李商隱','quantangshi','','卷30','何处哀筝随急管，樱花永巷垂杨岸。
东家老女嫁不售，白日当天三月半。
溧阳公主年十四，清明暖后同墙看。
归来展转到五更，梁间燕子闻长叹。','',''),('quantangshi-29426','赴职梓潼留别畏之员外同年','李商隱','quantangshi','','卷30','佳兆联翩遇凤凰，雕文羽帐紫金牀。
桂花香处同高第，柿叶翻时独悼亡。
乌鹊失栖长不定，鸳鸯何事自相将。
京华庸蜀三千里，送到咸阳见夕阳。','',''),('quantangshi-29427','桂林路中作','李商隱','quantangshi','','卷30','地暖无秋色，江晴有暮晖。
空余蝉嘒嘒，犹向客依依。
村小犬相护，沙平僧独归。
欲成西北望，又见鹧鸪飞。','',''),('quantangshi-29428','无题','李商隱','quantangshi','','卷30','照梁初有情，出水旧知名。
帬衩芙蓉小，钗茸翡翠轻。
锦长书郑重，眉细恨分明。
莫近弹碁局，中心最不平。','',''),('quantangshi-29429','蝶三首 一','李商隱','quantangshi','','卷30','初来小苑中，稍与琐闱通。
远恐芳尘断，轻忧艳雪融。
只知防皓露，不觉逆尖风。
回首双飞燕，乘时入绮栊。','',''),('quantangshi-29430','蝶三首 二','李商隱','quantangshi','','卷30','长眉画了绣帘开，碧玉行收白玉台。
为问翠钗钗上凤，不知香颈为谁回。','',''),('quantangshi-29431','蝶三首 三','李商隱','quantangshi','','卷30','寿阳公主嫁时妆，八字宫眉捧额黄。
见我佯羞频照影，不知身属冶游郎。','',''),('quantangshi-29432','无题二首 一','李商隱','quantangshi','','卷30','八岁偷照镜，长眉已能画。
十岁去踏青，芙蓉作帬衩。
十二学弹筝，银甲不曾卸。
十四藏六亲，悬知犹未嫁。
十五泣春风，背面秋千下。','',''),('quantangshi-29433','无题二首 二','李商隱','quantangshi','','卷30','幽人不倦赏，秋暑贵招邀。
竹碧转怅望，池清尤寂寥。
露花终裛湿，风蝶强娇饶。
此地如携手，兼君不自聊。','',''),('quantangshi-29434','王十二兄与畏之员外相访见招小饮时予以悼亡日近不去因寄','李商隱','quantangshi','','卷30','谢傅门庭旧末行，今朝歌管属檀郎。
更无人处帘垂地，欲拂尘时簟竟牀。
嵇氏幼男犹可悯，左家娇女岂能忘。
秋霖腹疾俱难遣，万里西风夜正长。','',''),('quantangshi-29435','隋宫','李商隱','quantangshi','','卷30','乘兴南游不戒严，九重谁省谏书函。
春风举国裁宫锦，半作障泥半作帆。','',''),('quantangshi-29436','落花','李商隱','quantangshi','','卷30','高阁客竟去，小园花乱飞。
参差连曲陌，迢遰送斜晖。
肠断未忍扫，眼穿仍欲归。
芳心向春尽，所得是沾衣。','',''),('quantangshi-29437','月','李商隱','quantangshi','','卷30','池上与桥边，难忘复可怜。
帘开最明夜，簟卷已凉天。
流处水花急，吐时云叶鲜。
姮娥无粉黛，只是逞婵娟。','',''),('quantangshi-29438','赠宗鲁筇竹杖','李商隱','quantangshi','','卷30','大夏资轻策，全溪赠所思。
静怜穿树远，滑想过苔迟。
鹤怨朝还望，僧闲暮有期。
风流真底事，常欲傍清羸。','',''),('quantangshi-29439','垂柳','李商隱','quantangshi','','卷30','娉婷小苑中，婀娜曲池东。
朝佩皆垂地，仙衣尽带风。
七贤宁占竹，三品且饶松。
肠断灵和殿，先皇玉座空。','',''),('quantangshi-29440','曲池','李商隱','quantangshi','','卷30','日下繁香不自持，月中流艳与谁期。
迎忧急鼓疎钟断，分隔休灯灭烛时。
张盖欲判江滟滟，回头更望柳丝丝。
从来此地黄昏散，未信河梁是别离。','',''),('quantangshi-29441','代应二首 一','李商隱','quantangshi','','卷30','沟水分流西复东，九秋霜月五更风。
离鸾别凤今何在，十二玉楼空更空。','',''),('quantangshi-29442','代应二首 二','李商隱','quantangshi','','卷30','昨夜双钩败，今朝百草输。
关西狂小吏，惟喝遶牀卢。','',''),('quantangshi-29443','席上作','李商隱','quantangshi','','卷30','淡云轻雨拂高唐，玉殿秋来夜正长。
料得也应怜宋玉，一生惟事楚襄王。','',''),('quantangshi-29444','访隐者不遇成二绝 一','李商隱','quantangshi','','卷30','秋水悠悠浸墅扉，梦中来数觉来稀。
玄蝉去尽叶黄落，一树冬青人未归。','',''),('quantangshi-29445','访隐者不遇成二绝 二','李商隱','quantangshi','','卷30','城郭休过识者稀，哀猿啼处有柴扉。
沧江白日樵渔路，日暮归来雨满衣。','',''),('quantangshi-29446','破镜','李商隱','quantangshi','','卷30','玉匣清光不复持，菱花散乱月轮亏。
秦台一照山鸡后，便是孤鸾罢舞时。','',''),('quantangshi-29447','无题','李商隱','quantangshi','','卷30','紫府仙人号宝灯，云浆未饮结成冰。
如何雪月交光夜，更在瑶台十二层。','',''),('quantangshi-29448','赠庾十二朱版','李商隱','quantangshi','','卷30','固漆投胶不可开，赠君珍重抵琼瑰。
君王晓坐金銮殿，只待相如草诏来。','',''),('quantangshi-29449','李花','李商隱','quantangshi','','卷30','李径独来数，愁情相与悬。
自明无月夜，强笑欲风天。
减粉与园箨，分香沾渚莲。
徐妃久已嫁，犹自玉为钿。','',''),('quantangshi-29450','柳','李商隱','quantangshi','','卷30','曾逐东风拂舞筵，乐游春苑断肠天。
如何肯到清秋日，已带斜阳又带蝉。','',''),('quantangshi-29451','三月十日流杯亭','李商隱','quantangshi','','卷30','身属中军少得归，木兰花尽失春期。
偷随柳絮到城外，行过水西闻子规。','',''),('quantangshi-29452','过招国李家南园二首 一','李商隱','quantangshi','','卷30','潘岳无妻客为愁，新人来坐旧妆楼。
春风犹自疑联句，雪絮相和飞不休。','',''),('quantangshi-29453','过招国李家南园二首 二','李商隱','quantangshi','','卷30','长亭岁尽雪如波，此去秦关路几多。
惟有梦中相近分，卧来无睡欲如何。','',''),('quantangshi-29454','留赠畏之 一','李商隱','quantangshi','','卷30','清时无事奏明光，不遣当关报早霜。
中禁词臣寻引领，左川归客自回肠。
郎君下笔惊鹦鹉，侍女吹笙弄凤凰。
空寄大罗天上事，众仙同日咏霓裳。','',''),('quantangshi-29455','留赠畏之 二','李商隱','quantangshi','','卷30','待得郎来月已低，寒暄不道醉如泥。
五更又欲向何处，骑马出门乌夜啼。','',''),('quantangshi-29456','留赠畏之 三','李商隱','quantangshi','','卷30','户外重阴黯不开，含羞迎夜复临台。
潇湘浪上有烟景，安得好风吹汝来。','',''),('quantangshi-29457','为有','李商隱','quantangshi','','卷30','为有云屏无限娇，凤城寒尽怕春宵。
无端嫁得金龟壻，辜负香衾事早朝。','',''),('quantangshi-29458','无题','李商隱','quantangshi','','卷30','相见时难别亦难，东风无力百花残。
春蚕到死丝方尽，蜡炬成灰泪始干。
晓镜但愁云鬓改，夜吟应觉月光寒。
蓬山此去无多路，青鸟殷勤为探看。','',''),('quantangshi-29459','碧城三首 一','李商隱','quantangshi','','卷30','碧城十二曲阑干，犀辟尘埃玉辟寒。
阆苑有书多附鹤，女牀无树不栖鸾。
星沉海底当窗见，雨过河源隔座看。
若是晓珠明又定，一生长树水晶盘。','',''),('quantangshi-29460','碧城三首 二','李商隱','quantangshi','','卷30','对影闻声已可怜，玉池荷叶正田田。
不逢萧史休回首，莫见洪崖又拍肩。
紫凤放娇衔楚佩，赤鳞狂舞拨湘弦。
鄂君怅望舟中夜，绣被焚香独自眠。','',''),('quantangshi-29461','碧城三首 三','李商隱','quantangshi','','卷30','七夕来时先有期，洞房帘箔至今垂。
玉轮顾兔初生魄，铁网珊瑚未有枝。
检与神方教驻景，收将凤纸写相思。
武皇内传分明在，莫道人间总不知。','',''),('quantangshi-29462','对雪二首 一','李商隱','quantangshi','','卷30','寒气先侵玉女扉，清光旋透省郎闱。
梅花大庾岭头发，柳絮章台街里飞。
欲舞定随曹植马，有情应湿谢庄衣。
龙山万里无多远，留待行人二月归。','',''),('quantangshi-29463','对雪二首 二','李商隱','quantangshi','','卷30','旋扑珠帘过粉墙，轻于柳絮重于霜。
已随江令夸琼树，又入卢家妬玉堂。
侵夜可能争桂魄，忍寒应欲试梅妆。
关河冻合东西路，肠断斑骓送陆郎。','',''),('quantangshi-29464','蜂','李商隱','quantangshi','','卷30','小苑华池烂熳通，后门前槛思无穷。
宓妃腰细才胜露，赵后身轻欲倚风。
红壁寂寥崖蜜尽，碧帘迢遰雾巢空。
青陵粉碟休离恨，长定相逢二月中。','',''),('quantangshi-29465','公子','李商隱','quantangshi','','卷30','外戚封侯自有恩，平明通籍九华门。
金唐公主年应小，二十君王未许婚。','',''),('quantangshi-29466','赋得鸡','李商隱','quantangshi','','卷30','稻粱犹足活诸雏，妬敌专场好自娱。
可要五更惊晓梦，不辞风雪为阳乌。','',''),('quantangshi-29467','明神','李商隱','quantangshi','','卷30','明神司过岂令冤，暗室由来有祸门。
莫为无人欺一物，他时须虑石能言。','',''),('quantangshi-29468','辛未七夕','李商隱','quantangshi','','卷30','恐是仙家好别离，故教迢遰作佳期。
由来碧落银河畔，可要金风玉露时。
清漏渐移相望久，微云未接过来迟。
岂能无意酬乌鹊，惟与蜘蛛乞巧丝。','',''),('quantangshi-29469','壬申七夕','李商隱','quantangshi','','卷30','已驾七香车，心心待晓霞。
风轻惟响佩，日薄不嫣花。
桂嫩传香远，榆高送影斜。
成都过卜肆，曾妬识灵槎。','',''),('quantangshi-29470','壬申闰秋题赠鸟鹊','李商隱','quantangshi','','卷30','绕树无衣月正高，邺城新泪溅云袍。
几年始得逢秋闰，两度填河莫告劳。','',''),('quantangshi-29471','端居','李商隱','quantangshi','','卷30','远书归梦两悠悠，只有空牀敌素秋。
堦下青苔与红树，雨中寥落月中愁。','',''),('quantangshi-29472','夜半','李商隱','quantangshi','','卷30','三更三点万家眠，露欲为霜月堕烟。
鬬鼠上堂蝙蝠出，玉琴时动倚窗弦。','',''),('quantangshi-29473','玉山','李商隱','quantangshi','','卷30','玉山高与阆风齐，玉水清流不贮泥。
何处更求回日驭，此中兼有上天梯。
珠容百斛龙休睡，桐拂千寻凤要栖。
闻道神仙有才子，赤箫吹罢好相携。','',''),('quantangshi-29474','张恶子庙','李商隱','quantangshi','','卷30','下马捧椒浆，迎神白玉堂。
如何铁如意，独自与姚苌。','',''),('quantangshi-29475','雨','李商隱','quantangshi','','卷30','摵摵度瓜园，依依傍竹轩。
秋池不自冷，风叶共成喧。
窗迥有时见，檐高相续翻。
侵宵送书雁，应为稻粱恩。','',''),('quantangshi-29476','菊','李商隱','quantangshi','','卷30','暗暗淡淡紫，融融冶冶黄。
陶令篱边色，罗含宅里香。
几时禁重露，实是怯残阳。
愿泛金鹦鹉，升君白玉堂。','',''),('quantangshi-29477','牡丹','李商隱','quantangshi','','卷30','锦帏初卷卫夫人，绣被犹堆越鄂君。
垂手乱翻雕玉佩，招腰争舞郁金帬。
石家蜡烛何曾剪，荀令香炉可待熏。
我是梦中传彩笔，欲书花叶寄朝云。','',''),('quantangshi-29478','北楼','李商隱','quantangshi','','卷30','春物岂相干，人生只强欢。
花犹曾敛夕，酒竟不知寒。
异城东风湿，中华上象宽。
此楼堪北望，轻命倚危栏。','',''),('quantangshi-29479','拟沈下贤','李商隱','quantangshi','','卷30','千二百轻鸾，春衫瘦着宽。
倚风行稍急，含雪语应寒。
带火遗金斗，兼珠碎玉盘。
河阳看花过，曾不问潘安。','',''),('quantangshi-29480','蝶','李商隱','quantangshi','','卷30','飞来绣户阴，穿过画楼深。
重傅秦台粉，轻涂汉殿金。
相兼惟柳絮，所得是花心。
可要凌孤客，邀为子夜吟。','',''),('quantangshi-29481','饮席代官妓赠两从事','李商隱','quantangshi','','卷30','新人桥上着春衫，旧主江边侧帽檐。
愿得化为红绶带，许教双凤一时衔。','',''),('quantangshi-29482','代魏宫私赠','李商隱','quantangshi','','卷30','来时西馆阻佳期，去后漳河隔梦思。
知有宓妃无限意，春松秋菊可同时。','',''),('quantangshi-29483','代元城吴令暗为答','李商隱','quantangshi','','卷30','背阙归藩路欲分，水边风日半西曛。
荆王枕上原无梦，莫枉阳台一片云。','',''),('quantangshi-29484','牡丹','李商隱','quantangshi','','卷30','压迳复缘沟，当窗又映楼。
终销一国破，不啻万金求。
鸾凤戏三岛，神仙居十洲。
应怜萱草淡，却得号忘忧。','',''),('quantangshi-29485','百果嘲樱桃','李商隱','quantangshi','','卷30','珠实虽先熟，琼莩纵早开。
流鸎犹故在，争得讳含来。','',''),('quantangshi-29486','樱桃答','李商隱','quantangshi','','卷30','众果莫相诮，天生名品高。
何因古乐府，惟有郑樱桃。','',''),('quantangshi-29487','晓坐','李商隱','quantangshi','','卷30','后合罢朝眠，前墀思黯然。
梅应未假雪，柳自不胜烟。
泪续浅深绠，肠危高下弦。
红颜无定所，得失在当年。','',''),('quantangshi-29488','咏史','李商隱','quantangshi','','卷30','北湖南埭水漫漫，一片降旗百尺竿。
三百年间同晓梦，钟山何处有龙盘。','',''),('quantangshi-29489','一片','李商隱','quantangshi','','卷30','一片非烟隔九枝，蓬峦仙仗俨云旗。
天泉水暖龙吟细，露畹春多凤舞迟。
榆荚散来星斗转，桂花寻去月轮移。
人间桑海朝朝变，莫遣佳期更后期。','',''),('quantangshi-29490','日射','李商隱','quantangshi','','卷30','日射纱窗风撼扉，香罗拭手春事违。
回廊四合掩寂寞，碧鹦鹉对红蔷薇。','',''),('quantangshi-29491','题鹅','李商隱','quantangshi','','卷30','眠沙卧水自成羣，曲岸残阳极浦云。
那解将心怜孔翠，羁雌长共故雄分。','',''),('quantangshi-29492','华清宫','李商隱','quantangshi','','卷30','朝元阁迥羽衣新，首按昭阳第一人。
当日不来高处舞，可能天下有胡尘。','',''),('quantangshi-29493','梓潼望长卿山至巴西复怀谯秀','李商隱','quantangshi','','卷30','梓潼不见马相如，更欲南行问酒垆。
行到巴西觅谯秀，巴西惟是有寒芜。','',''),('quantangshi-29494','齐宫词','李商隱','quantangshi','','卷30','永寿兵来夜不扃，金莲无复印中庭。
梁台歌管三更罢，犹自风摇九子铃。','',''),('quantangshi-29495','十一月中旬至扶风界见梅花','李商隱','quantangshi','','卷30','匝路亭亭艳，非时裛裛香。
素娥惟与月，青女不饶霜。
赠远虚盈手，伤离适断肠。
为谁成早秀，不待作年芳。','',''),('quantangshi-29496','青陵台','李商隱','quantangshi','','卷30','青陵台畔日光斜，万古贞魂倚暮霞。
莫讶韩凭为蛱蝶，等闲飞上别枝花。','',''),('quantangshi-29497','东还','李商隱','quantangshi','','卷30','自有仙才自不知，十年长梦采华芝。
秋风动地黄云暮，归去嵩阳寻旧师。','',''),('quantangshi-29498','酬崔八早梅有赠兼示之作','李商隱','quantangshi','','卷30','知访寒梅过野塘，久留金勒为回肠。
谢郎衣袖初翻雪，荀令熏炉更换香。
何处拂胸资蝶粉，几时涂额藉蜂黄。
维摩一室虽多病，亦要天花作道场。','',''),('quantangshi-29499','春风','李商隱','quantangshi','','卷30','春风虽自好，春物太昌昌。
若教春有意，惟遣一枝芳。
我意殊春意，先春已断肠。','',''),('quantangshi-29500','蜀桐','李商隱','quantangshi','','卷30','玉垒高桐拂玉绳，上含非雾下含冰。
枉教紫凤无栖处，斵作秋琴弹坏陵。','',''),('quantangshi-29501','汉宫','李商隱','quantangshi','','卷30','通灵夜醮达清晨，承露盘曦甲帐春。
王母不来方朔去，更须重见李夫人。','',''),('quantangshi-29502','判春','李商隱','quantangshi','','卷30','一桃复一李，井上占年芳。
笑处如临镜，窥时不隐墙。
敢言西子短，谁觉宓妃长。
珠玉终相类，同名作夜光。','',''),('quantangshi-29503','促漏','李商隱','quantangshi','','卷30','促漏遥钟动静闻，报章重叠杳难分。
舞鸾镜匣收残黛，睡鸭香炉换夕熏。
归去定知还向月，梦来何处更为云？
南塘渐暖蒲堪结，两两鸳鸯护水纹。','',''),('quantangshi-29504','江东','李商隱','quantangshi','','卷30','惊鱼拨刺燕翩翾，独自江东上钓船。
今日春光太漂荡，谢家轻絮沈郎钱。','',''),('quantangshi-29505','读任彦升碑','李商隱','quantangshi','','卷30','任昉当年有美名，可怜才调最纵横。
梁台初建应惆怅，不得萧公作骑兵。','',''),('quantangshi-29506','荷花','李商隱','quantangshi','','卷30','都无色可并，不奈此香何。
瑶席乘凉设，金羁落晚过。
回衾灯照绮，渡韈水沾罗。
预想前秋别，离居梦棹歌。','',''),('quantangshi-29507','五松驿','李商隱','quantangshi','','卷30','独下长亭念过秦，五松不见见舆薪。
只应既斩斯高后，寻被樵人用斧斤。','',''),('quantangshi-29508','灞岸','李商隱','quantangshi','','卷30','山东今岁点行频，几处冤魂哭虏尘。
灞水桥边倚华表，平时二月有东巡。','',''),('quantangshi-29509','送臻师二首 一','李商隱','quantangshi','','卷30','昔去灵山非拂席，今来沧海欲求珠。
楞伽顶上清凉池，善眼仙人忆我无。','',''),('quantangshi-29510','送臻师二首 二','李商隱','quantangshi','','卷30','苦海迷途去未因，东方过此几微尘。
何当百亿莲花上，一一莲花见佛身。','',''),('quantangshi-29511','七夕','李商隱','quantangshi','','卷30','鸾扇斜分凤幄开，星桥横过鹊飞回。
争将世上无期别，换得年年一度来。','',''),('quantangshi-29512','谢先辈防记念拙诗甚多异日偶有此寄','李商隱','quantangshi','','卷30','晓用云添句，寒将雪命篇。
良辰多自感，作者岂皆然。
熟寝初同鹤，含嘶欲并蝉。
题诗长不展，得处定应偏。
南浦无穷树，西楼不住烟。
改成人寂寂，寄与路绵绵。
星势寒垂地，河声晓上天。
夫君自有恨，聊借此中传。','',''),('quantangshi-29513','马嵬二首 一','李商隱','quantangshi','','卷30','冀马燕犀动地来，自埋红粉自成灰。
君王若道能倾国，玉辇何由过马嵬。','',''),('quantangshi-29514','马嵬二首 二','李商隱','quantangshi','','卷30','海外徒闻更九州，他生未卜此生休。
空闻虎旅传宵柝，无复鸡人报晓筹。
此日六军同驻马，当时七夕笑牵牛。
如何四纪为天子，不及卢家有莫愁。','',''),('quantangshi-29515','可叹','李商隱','quantangshi','','卷30','幸会东城宴未回，年华忧共水相催。
梁家宅里秦宫入，赵后楼中赤凤来。
冰簟且眠金镂枕，琼筵不醉玉交杯。
宓妃愁坐芝田馆，用尽陈王八斗才。','',''),('quantangshi-29516','望喜驿别嘉陵江水二绝 一','李商隱','quantangshi','','卷30','嘉陵江水此东流，望喜楼中忆阆州。
若到阆中还赴海，阆州应更有高楼。','',''),('quantangshi-29517','望喜驿别嘉陵江水二绝 二','李商隱','quantangshi','','卷30','千里嘉陵江水色，含烟带月碧于蓝。
今朝相送东流后，犹自驱车更向南。','',''),('quantangshi-29518','别薛岩宾','李商隱','quantangshi','','卷30','曙爽行将拂，晨清坐欲凌。
别离真不那，风物正相仍。
漫水任谁照，衰花浅自矜。
还将两袖泪，同向一窗灯。
桂树乖真隐，芸香是小惩。
清规无以况，且用玉壶冰。','',''),('quantangshi-29519','富平少侯','李商隱','quantangshi','','卷30','七国三边未到忧，十三身袭富平候。
不收金弹抛林外，却惜银牀在井头。
彩树转灯珠错落，绣檀回枕玉雕锼。
当关不报侵晨客，新得佳人字莫愁。','',''),('quantangshi-29520','肠','李商隱','quantangshi','','卷30','有怀非惜恨，不奈寸肠何。
即席回弥久，前时断固多。
热应翻急烧，冷欲彻微波。
隔树澌澌雨，通池点点荷。
倦程山向背，望国阙嵯峨。
故念飞书及，新懽借梦过。
染筠休伴泪，绕雪莫追歌。
拟问阳台事，年深楚语讹。','',''),('quantangshi-29521','赠宇文中丞','李商隱','quantangshi','','卷30','欲构中天正急材，自缘烟水恋平台。
人间只有嵇延祖，最望山公启事来。','',''),('quantangshi-29522','晓起','李商隱','quantangshi','','卷30','拟杯当晓起，呵镜可微寒。
隔箔山樱熟，褰帷桂烛残。
书长为报晚，梦好更寻难。
影响输双蝶，偏过旧畹兰。','',''),('quantangshi-29523','闺情','李商隱','quantangshi','','卷30','红露花房白蜜脾，黄蜂紫蝶两参差。
春窗一觉风流梦，却是同袍不得知。','',''),('quantangshi-29524','月夕','李商隱','quantangshi','','卷30','草下阴虫叶上霜，朱栏迢遰压湖光。
兔寒蟾冷桂花白，此夜姮娥应断肠。','',''),('quantangshi-29525','杏花','李商隱','quantangshi','','卷30','上国昔相值，亭亭如欲言。
异乡今暂赏，眽眽岂无恩。
援少风多力，墙高月有痕。
为含无限意，遂对不胜繁。
仙子玉京路，主人金谷园。
几时辞碧落，谁伴过黄昏。
镜拂铅华腻，炉藏桂烬温。
终应催竹叶，先拟咏桃根。
莫学啼成血，从教梦寄魂。
吴王采香径，失路入烟村。','',''),('quantangshi-29526','灯','李商隱','quantangshi','','卷30','皎洁终无倦，煎熬亦自求。
花时随酒远，雨后背窗休。
冷暗黄茅驿，暄明紫桂楼。
锦囊名画揜，玉局败碁收。
何处无佳梦，谁人不隐忧。
影随帘押转，光信簟文流。
客自胜潘岳，侬今定莫愁。
固应留半焰，廻照下帏羞。','',''),('quantangshi-29527','清河','李商隱','quantangshi','','卷30','舟小回仍数，楼危凭亦频。
燕来从及社，蝶舞太侵晨。
绛雪除烦后，霜梅取味新。
年华无一事，只是自伤春。','',''),('quantangshi-29528','韈','李商隱','quantangshi','','卷30','尝闻宓妃韈，渡水欲生尘。
好借常娥着，清秋踏月轮。','',''),('quantangshi-29529','追代卢家人嘲堂内','李商隱','quantangshi','','卷30','道却横波字，人前莫谩羞。
只应同楚水，长短入淮流。','',''),('quantangshi-29530','代应','李商隱','quantangshi','','卷30','本来银汉是红墙，隔得卢家白玉堂。
谁与王昌报消息，尽知三十六鸳鸯。','',''),('quantangshi-29531','离亭赋得折杨柳二首 一','李商隱','quantangshi','','卷30','暂凭樽酒送无憀，莫损愁眉与细腰。
人世死前惟有别，春风争拟惜长条。','',''),('quantangshi-29532','离亭赋得折杨柳二首 二','李商隱','quantangshi','','卷30','含烟惹雾每依依，万绪千条拂落晖。
为报行人休尽折，半留相送半迎归。','',''),('quantangshi-29533','寄永道士','李商隱','quantangshi','','卷30','共上云山独下迟，阳台白道细如丝。
君今并倚三珠树，不记人间落叶时。','',''),('quantangshi-29534','华州周大夫宴席','李商隱','quantangshi','','卷30','郡斋何用酒如泉，饮德先时已醉眠。
若共门人推礼分，戴崇争得及彭宣。','',''),('quantangshi-29535','荆山','李商隱','quantangshi','','卷30','压河连华势孱颜，鸟没云归一望间。
杨仆移关三百里，可能全是为荆山。','',''),('quantangshi-29536','次陕州先寄源从事','李商隱','quantangshi','','卷30','离思羁愁日欲晡，东周西雍此分涂。
回銮佛寺高多少，望尽黄河一曲无。','',''),('quantangshi-29537','过郑广文旧居','李商隱','quantangshi','','卷30','宋玉平生恨有余，远循三楚吊三闾。
可怜留着临江宅，异代应教庾信居。','',''),('quantangshi-29538','东下三旬苦于风土马上戏作','李商隱','quantangshi','','卷30','路遶函关东复东，身骑征马逐惊蓬。
天池辽阔谁相待，日日虚乘九万风。','',''),('quantangshi-29539','莫愁','李商隱','quantangshi','','卷30','雪中梅下与谁期，梅雪相兼一万枝。
若是石城无艇子，莫愁还自有愁时。','',''),('quantangshi-29540','梦令狐学士','李商隱','quantangshi','','卷30','山驿荒凉白竹扉，残灯向晓梦清晖。
右银台路雪三尺，凤诏裁成当直归。','',''),('quantangshi-29541','涉洛川','李商隱','quantangshi','','卷30','通谷阳林不见人，我来遗恨古时春。
宓妃漫结无穷恨，不为君王杀灌均。','',''),('quantangshi-29542','有感','李商隱','quantangshi','','卷30','中路因循我所长，古来才命两相妨。
劝君莫强安蛇足，一盏芳醪不得尝。','',''),('quantangshi-29543','宫妓','李商隱','quantangshi','','卷30','珠箔轻明拂玉墀，披香新殿鬬腰支。
不须看尽鱼龙戏，终遣君王怒偃师。','',''),('quantangshi-29544','宫辞','李商隱','quantangshi','','卷30','君恩如水向东流，得宠忧移失宠愁。
莫向尊前奏花落，凉风只在殿西头。','',''),('quantangshi-29545','代赠二首 一','李商隱','quantangshi','','卷30','楼上黄昏欲望休，玉梯横绝月中钩。
芭蕉不展丁香结，同向春风各自愁。','',''),('quantangshi-29546','代赠二首 二','李商隱','quantangshi','','卷30','东南日出照高楼，楼上离人唱石州。
总把春山扫眉黛，不知供得几多愁。','',''),('quantangshi-29547','楚吟','李商隱','quantangshi','','卷30','山上离宫宫上楼，楼前宫畔暮江流。
楚天长短黄昏雨，宋玉无愁亦自愁。','',''),('quantangshi-29548','瑶池','李商隱','quantangshi','','卷30','瑶池阿母绮窗开，黄竹歌声动地哀。
八骏日行三万里，穆王何事不重来。','',''),('quantangshi-29549','柳','李商隱','quantangshi','','卷30','为有桥边拂面香，何曾自敢占流光。
后庭玉树承恩泽，不信年华有断肠。','',''),('quantangshi-29550','寄在朝郑曹独孤李四同年','李商隱','quantangshi','','卷30','昔岁陪游旧迹多，风光今日两蹉跎。
不因醉本兰亭在，兼忘当年旧永和。','',''),('quantangshi-29551','南朝','李商隱','quantangshi','','卷30','地险悠悠天险长，金陵王气应瑶光。
休夸此地分天下，只得徐妃半面妆。','',''),('quantangshi-29552','题汉祖庙','李商隱','quantangshi','','卷30','乘运应须宅八荒，男儿安在恋池隍。
君王自起新丰后，项羽何曾在故乡。','',''),('quantangshi-29553','韩冬郎即席为诗相送一座尽惊他日余方追吟连宵侍坐裴回久之句有老成之风因成二绝寄酬兼呈畏之员外 一','李商隱','quantangshi','','卷30','十岁裁诗走马成，冷灰残烛动离情。
桐花万里丹山路，雏凤清于老凤声。','',''),('quantangshi-29554','韩冬郎即席为诗相送一座尽惊他日余方追吟连宵侍坐裴回久之句有老成之风因成二绝寄酬兼呈畏之员外 二','李商隱','quantangshi','','卷30','劒栈风樯各苦辛，别时冰雪到时春。
为凭何逊休联句，瘦尽东阳姓沈人。','',''),('quantangshi-29555','评事翁寄赐饧粥走笔为答','李商隱','quantangshi','','卷30','粥香饧白杏花天，省对流鸎坐绮筵。
今日寄来春已老，凤楼迢递忆秋千。','',''),('quantangshi-29556','东阿王','李商隱','quantangshi','','卷30','国事分明属灌均，西陵魂断夜来人。
君王不得为天子，半为当时赋洛神。','',''),('quantangshi-29557','圣女祠','李商隱','quantangshi','','卷30','松篁台殿蕙香帏，龙护瑶窗凤掩扉。
无质易迷三里雾，不寒长着五铢衣。
人间定有崔罗什，天上应无刘武威。
寄问钗头双白燕，每朝珠馆几时归。','',''),('quantangshi-29558','独居有怀','李商隱','quantangshi','','卷30','麝重愁风逼，罗疎畏月侵。
怨魂迷恐断，娇喘细疑沈。
数急芙蓉带，频抽翡翠簪。
柔情终不远，遥妬已先深。
浦冷鸳鸯去，园空蛱蝶寻。
蜡花长递泪，筝柱镇移心。
觅使嵩云暮，回头灞岸阴。
只闻凉叶院，露井近寒砧。','',''),('quantangshi-29559','过景陵','李商隱','quantangshi','','卷30','武皇精魄久仙升，帐殿凄凉烟雾凝。
俱是苍生留不得，鼎湖何异魏西陵。','',''),('quantangshi-29560','临发崇让宅紫薇','李商隱','quantangshi','','卷30','一树浓姿独看来，秋庭暮雨类轻埃。
不先摇落应为有，已欲别离休更开。
桃绶含情依露井，柳绵相忆隔章台。
天涯地角同荣谢，岂要移根上苑栽。','',''),('quantangshi-29561','及第东归次灞上却寄同年','李商隱','quantangshi','','卷30','芳桂当年各一枝，行期未分压春期。
江鱼朔雁长相忆，秦树嵩云自不知。
下苑经过劳想像，东门送饯又差池。
灞陵柳色无离恨，莫枉长条赠所思。','',''),('quantangshi-29562','野菊','李商隱','quantangshi','','卷30','苦竹园南椒坞边，微香冉冉泪涓涓。
已悲节物同寒雁，忍委芳心与暮蝉。
细路独来当此夕，清尊相伴省他年。
紫云新苑移花处，不取霜栽近御筵。','',''),('quantangshi-29563','板桥晓别','李商隱','quantangshi','','卷30','回望高城落晓河，长亭窗户压微波。
水仙欲上鲤鱼去，一夜芙蓉红泪多。','',''),('quantangshi-29564','过伊仆射旧宅','李商隱','quantangshi','','卷30','朱邸方酬力战功，华筵俄叹逝波穷。
回廊檐断燕飞去，小阁尘凝人语空。
幽泪欲干残菊露，余香犹入败荷风。
何能更涉泷江去，独立寒流吊楚宫。','',''),('quantangshi-29565','关门柳','李商隱','quantangshi','','卷30','永定河边一行柳，依依长发故年春。
东来西去人情薄，不为清阴减路尘。','',''),('quantangshi-29566','酬别令狐补阙','李商隱','quantangshi','','卷30','惜别夏仍半，回途秋已期。
那修直谏草，更赋赠行诗。
锦段知无报，青萍肯见疑。
人生有通塞，公等系安危。
警露鹤辞侣，吸风蝉抱枝。
弹冠如不问，又到扫门时。','',''),('quantangshi-29567','银河吹笙','李商隱','quantangshi','','卷30','怅望银河吹玉笙，楼寒院冷接平明。
重衾幽梦他年断，别树羁雌昨夜惊。
月榭故香因雨发，风帘残烛隔霜清。
不须浪作缑山意，湘瑟秦箫自有情。','',''),('quantangshi-29568','与同年李定言曲水闲话戏作','李商隱','quantangshi','','卷30','海燕参差沟水流，同君身世属离忧。
相携花下非秦赘，对泣春天类楚囚。
碧草暗侵穿苑路，珠帘不卷枕江楼。
莫惊五胜埋香骨，地下伤春亦白头。','',''),('quantangshi-29569','彭城公薨后赠杜二十七胜李十七潘二君竝与愚同出故尚书安平公门下','李商隱','quantangshi','','卷30','梁山兖水约从公，两地参差一旦空。
谢墅庾村相吊后，自今歧路各西东。','',''),('quantangshi-29570','闻歌','李商隱','quantangshi','','卷30','敛笑凝眸意欲歌，高云不动碧嵯峨。
铜台罢望归何处，玉辇忘还事几多。
青冢路边南雁尽，细腰宫里北人过。
此声肠断非今日，香灺灯光奈尔何。','',''),('quantangshi-29571','赠华阳宋真人兼寄清都刘先生','李商隱','quantangshi','','卷30','沦谪千年别帝宸，至今犹谢蘂珠人。
但惊茅许同仙籍，不道刘卢是世亲。
玉捡赐书迷凤篆，金华归驾冷龙鳞。
不因杖屦逢周史，徐甲何曾有此身。','',''),('quantangshi-29572','楚宫二首 一','李商隱','quantangshi','','卷30','十二峰前落照微，高唐宫暗坐迷归。
朝云暮雨长相接，犹自君王恨见稀。','',''),('quantangshi-29573','楚宫二首 二','李商隱','quantangshi','','卷30','月姊曾逢下彩蟾，倾城消息隔重帘。
已闻佩响知腰细，更辨弦声觉指纤。
暮雨自归山悄悄，秋河不动夜厌厌。
王昌且在墙东住，未必金堂得免嫌。','',''),('quantangshi-29574','和友人戏赠二首 一','李商隱','quantangshi','','卷30','东望花楼会不同，西来双燕信休通。
仙人掌冷三霄露，玉女窗虚五夜风。
翠袖自随回雪转，烛房寻类外庭空。
殷勤莫使清香透，牢合金鱼鏁桂丛。','',''),('quantangshi-29575','和友人戏赠二首 二','李商隱','quantangshi','','卷30','迢遰青门有几关，柳梢楼角见南山。
明珠可贯须为佩，白璧堪裁且作环。
子夜休歌团扇揜，新正未破剪刀闲。
猿啼鹤怨终年事，未抵熏炉一夕间。','',''),('quantangshi-29576','题二首后重有戏赠任秀才','李商隱','quantangshi','','卷30','一丈红蔷拥翠筠，罗窗不识绕街尘。
峡中寻觅长逢雨，月里依稀更有人。
虚为错刀留远客，枉缘书札损文鳞。
遥知小阁还斜照，羡杀乌龙卧锦茵。','',''),('quantangshi-29577','有感二首 一','李商隱','quantangshi','','卷30','九服归元化，三灵叶睿图。
如何本初辈，自取屈氂诛。
有甚当车泣，因劳下殿趋。
何成奏云物，直是灭萑苻。
证逮符书密，辞连性命俱。
竟缘尊汉相，不早辨胡雏。
鬼箓分朝部，军烽照上都。
敢云堪恸哭，未免怨洪炉。','',''),('quantangshi-29578','有感二首 二','李商隱','quantangshi','','卷30','丹陛犹敷奏，彤庭歘战争。
临危对卢植，始悔用庞萌。
御仗收前殿，兵徒剧背城。
苍黄五色棒，掩遏一阳生。
古有清君侧，今非乏老成。
素心虽未易，此举太无名。
谁瞑衔冤目，宁吞欲绝声。
近闻开寿宴，不废用咸英。','',''),('quantangshi-29579','重有感','李商隱','quantangshi','','卷30','玉帐牙旗得上游，安危须共主君忧。
窦融表已来关右，陶侃军宜次石头。
岂有蛟龙愁失水，更无鹰隼与高秋。
昼号夜哭兼幽显，早晚星关雪涕收。','',''),('quantangshi-29580','寿安公主出降','李商隱','quantangshi','','卷30','沩水闻贞媛，常山索锐师。
昔忧迷帝力，今分送王姬。
事等和强虏，恩殊睦本枝。
四郊多垒在，此礼恐无时。','',''),('quantangshi-29581','夕阳楼','李商隱','quantangshi','','卷30','花明柳暗绕天愁，上尽重城更上楼。
欲问孤鸿向何处，不知身世自悠悠。','',''),('quantangshi-29582','春雨','李商隱','quantangshi','','卷30','怅卧新春白袷衣，白门寥落意多违。
红楼隔雨相望冷，珠箔飘灯独自归。
远路应悲春晼晚，残宵犹得梦依稀。
玉璫缄札何由达，万里云罗一雁飞。','',''),('quantangshi-29583','中元作','李商隱','quantangshi','','卷30','绛节飘颻宫国来，中元朝拜上清回。
羊权须得金条脱，温峤终虚玉镜台。
曾省惊眠闻雨过，不知迷路为花开。
有娀未抵瀛洲远，青雀如何鸩鸟媒。','',''),('quantangshi-29584','鸳鸯','李商隱','quantangshi','','卷30','雌去雄飞万里天，云罗满眼泪潸然。
不须长结风波愿，锁向金笼始两全。','',''),('quantangshi-29585','楚宫','李商隱','quantangshi','','卷30','湘波如泪色漻缪，楚厉迷魂逐恨遥。
枫树夜猿愁自断，女萝山鬼语相邀。
空归腐败犹难复，更困腥臊岂易招。
但使故乡三户在，彩丝谁惜惧长蛟。','',''),('quantangshi-29586','妓席暗记送同年独孤云之武昌','李商隱','quantangshi','','卷30','叠嶂千重呌恨猿，长江万里洗离魂。
武昌若有山头石，为拂苍苔检泪痕。','',''),('quantangshi-29587','宿晋昌亭闻惊禽','李商隱','quantangshi','','卷30','羇绪鳏鳏夜景侵，高窗不掩见惊禽。
飞来曲渚烟方合，过尽南塘树更深。
胡马嘶和榆塞笛，楚猿吟杂橘村砧。
失羣挂木知何限，远隔天涯共此心。','',''),('quantangshi-29588','深宫','李商隱','quantangshi','','卷30','金殿销香闭绮栊，玉壶传点咽铜龙。
狂飙不惜萝阴薄，清露偏知桂叶浓。
斑竹岭边无限泪，景阳宫里及时钟。
岂知为雨为云处，只有高唐十二峰。','',''),('quantangshi-29589','明禅师院酬从兄见寄','李商隱','quantangshi','','卷30','贞吝嫌兹世，会心驰本原。
人非四禅缚，地绝一尘喧。
霜露欹高木，星河压故园。
撕游傥为胜，九折幸回轩。','',''),('quantangshi-29590','寄裴衡','李商隱','quantangshi','','卷30','别地萧条极，如何更独来。
秋应为黄叶，雨不厌青苔。
沈约只能瘦，潘仁岂是才。
杂情堪底寄，惟有冷于灰。','',''),('quantangshi-29591','即日','李商隱','quantangshi','','卷30','小苑试春衣，高楼倚暮晖。
夭桃惟是笑，舞蝶不空飞。
赤岭久无耗，鸿门犹合围。
几家缘锦字，含泪坐鸳机。','',''),('quantangshi-29592','淮阳路','李商隱','quantangshi','','卷30','荒村倚废营，投宿旅魂惊。
断雁高仍急，寒溪晓更清。
昔年尝聚盗，此日颇分兵。
猜贰谁先致，三朝事始平。','',''),('quantangshi-29593','崇让宅东亭醉后沔然有作','李商隱','quantangshi','','卷30','曲岸风雷罢，东亭霁日凉。
新秋仍酒困，幽兴暂江乡。
摇落真何遽，交亲或未忘。
一帆彭蠡月，数雁塞门霜。
俗态虽多累，仙标发近狂。
声名佳句在，身世玉琴张。
万古山空碧，无人鬓免黄。
骅骝忧老大，鶗鴂妬芬芳。
密竹沉虚籁，孤莲泊晚香。
如何此幽胜，淹卧剧清漳。','',''),('quantangshi-29594','晚晴','李商隱','quantangshi','','卷30','深居俯夹城，春去夏犹清。
天意怜幽草，人间重晚晴。
并添高阁迥，微注小窗明。
越鸟巢干后，归飞体更轻。','',''),('quantangshi-29595','迎寄韩鲁州','李商隱','quantangshi','','卷30','积雨晚骚骚，相思正郁陶。
不知人万里，时有燕双高。
寇盗缠三辅，莓苔滑百牢。
圣朝推卫霍，归日动仙曹。','',''),('quantangshi-29596','武夷山','李商隱','quantangshi','','卷30','只得流霞酒一杯，空中箫鼓几时回。
武夷洞里生毛竹，老尽曾孙更不来。','',''),('quantangshi-29597','一片','李商隱','quantangshi','','卷30','一片琼英价动天，连城十二昔虚传。
良工巧费真为累，楮叶成来不直钱。','',''),('quantangshi-29598','寄成都高苗二从事','李商隱','quantangshi','','卷30','红莲幕下紫棃新，命断湘南病渴人。
今日问君能寄否，二江风水接天津。','',''),('quantangshi-29599','郑州献从叔舍人袖','李商隱','quantangshi','','卷30','蓬岛烟霞阆苑钟，三官笺奏附金龙。
茅君奕世仙曹贵，许掾全家道气浓。
绛简尚参黄纸案，丹炉犹用紫泥封。
不知他日华阳洞，许上经楼第几重。','',''),('quantangshi-29600','西南行却寄相送者','李商隱','quantangshi','','卷30','百里阴云覆雪泥，行人只在雪云西。
明朝惊破还乡梦，定是陈仓碧野鸡。','',''),('quantangshi-29601','四皓庙','李商隱','quantangshi','','卷30','羽翼殊勋弃若遗，皇天有运我无时。
庙前便接山门路，不长青松长紫芝。','',''),('quantangshi-29602','题白石莲花寄楚公','李商隱','quantangshi','','卷30','白石莲花谁所共，六时长捧佛前灯。
空庭苔藓饶霜露，时梦西山老病僧。
大海龙宫无限地，诸天雁塔几多层。
漫夸鹙子真罗汉，不会牛车是上乘。','',''),('quantangshi-29603','[安定]城楼','李商隱','quantangshi','','卷30','迢遰高城百尺楼，绿杨枝外尽汀洲。
贾生年少虚垂泪，王粲春来更远游。
永忆江湖归白发，欲回天地入扁舟。
不知腐鼠成滋味，猜意鸳雏竟未休。','',''),('quantangshi-29604','隋宫守岁','李商隱','quantangshi','','卷30','消息东郊木帝回，宫中行乐有新梅。
沈香甲煎为庭燎，玉液琼苏作寿杯。
遥望露盘疑是月，远闻鼍鼓欲惊雷。
昭阳第一倾城客，不踏金莲不肯来。','',''),('quantangshi-29605','利州江潭作','李商隱','quantangshi','','卷30','神劒飞来不易销，碧潭珍重驻兰桡。
自携明月移灯疾，欲就行云散锦遥。
河伯轩窗通贝阙，水宫帷箔卷冰绡。
他时燕脯无人寄，雨满空城蕙叶雕。','',''),('quantangshi-29606','即目','李商隱','quantangshi','','卷30','地宽楼已迥，人更迥于楼。
细意经春物，伤酲属暮愁。
望赊殊易断，恨久欲难收。
大埶真无利，多情岂自由。
空园兼树废，败港拥花流。
书去青枫驿，鸿归杜若洲。
单栖应分定，辞疾索谁忧。
更替林鵶恨，惊频去不休。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-29607','相思','李商隱','quantangshi','','卷30','相思树上合欢枝，紫凤青鸾共羽仪。
肠断秦台吹管客，日西春尽到来迟。','',''),('quantangshi-29608','茂陵','李商隱','quantangshi','','卷30','汉家天马出蒲梢，苜蓿榴花遍近郊。
内苑只知含凤觜，属车无复插鸡翘。
玉桃偷得怜方朔，金屋修成贮阿娇。
谁料苏卿老归国，茂陵松栢雨萧萧。','',''),('quantangshi-29609','镜槛','李商隱','quantangshi','','卷30','镜槛芙蓉入，香台翡翠过。
拨弦惊火凤，交扇拂天鹅。
隐忍阳城笑，喧传郢市歌。
仙眉琼作叶，佛髻钿为螺。
五里无因雾，三秋只见河。
月中供药剩，海上得绡多。
玉集胡沙割，犀留圣水磨。
斜门穿戏蝶，小阁锁飞蛾。
骑襜侵鞯卷，车帷约幰鈋。
传书两行雁，取酒一封駞。
桥迥凉风压，沟横夕照和。
待乌燕太子，驻马魏东阿。
想像铺芳褥，依稀解醉罗。
散时帘隔露，卧后幕生波。
梯稳从攀桂，弓调任射莎。
岂能抛断梦，听鼓事朝珂。','',''),('quantangshi-29610','送郑大台文南觐','李商隱','quantangshi','','卷30','黎辟滩声五月寒，南风无处附平安。
君怀一匹胡威绢，争拭酬恩泪得干。','',''),('quantangshi-29611','风','李商隱','quantangshi','','卷30','迥拂来鸿急，斜催别燕高。
已寒休惨淡，更远尚呼号。
楚色分西塞，夷音接下牢。
归舟天外有，一为戒波涛。','',''),('quantangshi-29612','洞庭鱼','李商隱','quantangshi','','卷30','洞庭鱼可拾，不假更垂罾。
闹若雨前蚁，多于秋后蝇。
岂思鳞作簟，仍计腹为灯。
浩荡天池路，翱翔欲化鹏。','',''),('quantangshi-29613','天涯','李商隱','quantangshi','','卷30','春日在天涯，天涯日又斜。
莺啼如有泪，为湿最高花。','',''),('quantangshi-29614','喜舍弟羲叟及第上礼部魏公','李商隱','quantangshi','','卷30','国以斯文重，公仍内署来。
风标森太华，星象逼中台。
朝满迁鸎侣，门多吐凤才。
宁同鲁司寇，惟铸一颜回。','',''),('quantangshi-29615','哀筝','李商隱','quantangshi','','卷30','延颈全同鹤，柔肠素怯猿。
湘波无限泪，蜀魄有余冤。
轻幰长无道，哀筝不出门。
何由问香炷，翠幕自黄昏。','',''),('quantangshi-29616','自南山北归经分水岭','李商隱','quantangshi','','卷30','水急愁无地，山深故有云。
那通极目望，又作断肠分。
郑驿来虽及，燕台哭不闻。
犹余遗意在，许刻镇南勋。','',''),('quantangshi-29617','旧顿','李商隱','quantangshi','','卷30','东人望幸久咨嗟，四海于今是一家。
犹锁平时旧行殿，尽无宫户有宫鸦。','',''),('quantangshi-29618','代董秀才却扇','李商隱','quantangshi','','卷30','莫将画扇出帷来，遮掩春山滞上才。
若道团圆似明月，此中须放桂花开。','',''),('quantangshi-29619','有感','李商隱','quantangshi','','卷30','非关宋玉有微辞，却是襄王梦觉迟。
一自高唐赋成后，楚天云雨尽堪疑。','',''),('quantangshi-29620','骊山有感','李商隱','quantangshi','','卷30','骊岫飞泉泛暖香，九龙呵护玉莲房。
平明每幸长生殿，不从金舆惟寿王。','',''),('quantangshi-29621','别智玄法师','李商隱','quantangshi','','卷30','云鬓无端怨别离，十年移易住山期。
东西南北皆垂泪，却是杨朱真本师。','',''),('quantangshi-29622','赠孙绮新及第','李商隱','quantangshi','','卷30','长乐遥听上苑钟，彩衣称庆桂香浓。
陆机始拟夸文赋，不觉云间有士龙。','',''),('quantangshi-29623','代秘书赠弘文馆诸校书','李商隱','quantangshi','','卷30','清切曹司近玉除，比来秋兴复何如。
崇文馆里丹霜后，无限红棃忆校书。','',''),('quantangshi-29624','乱石','李商隱','quantangshi','','卷30','虎踞龙蹲纵复横，星光渐减雨痕生。
不须并碍东西路，哭杀厨头阮步兵。','',''),('quantangshi-29625','日日','李商隱','quantangshi','','卷30','日日春光鬬日光，山城斜路杏花香。
几时心绪浑无事，得及游丝百尺长。','',''),('quantangshi-29626','过楚宫','李商隱','quantangshi','','卷30','巫峡迢迢旧楚宫，至今云雨暗丹枫。
微生尽恋人间乐，只有襄王忆梦中。','',''),('quantangshi-29627','龙池','李商隱','quantangshi','','卷30','龙池赐酒敞云屏，羯鼓声高众乐停。
夜半宴归宫漏永，薛王沉醉寿王醒。','',''),('quantangshi-29628','涙','李商隱','quantangshi','','卷30','永巷长年怨绮罗，离情终日思风波。
湘江竹上痕无限，岘首碑前洒几多。
人去紫台秋入塞，兵残楚帐夜闻歌。
朝来灞水桥边问，未抵青袍送玉珂。','',''),('quantangshi-29629','十字水期韦潘侍御同年不至时韦寓居水次故郭汾宁宅','李商隱','quantangshi','','卷30','伊水溅溅相背流，朱栏画阁几人游。
漆灯夜照真无数，蜡炬晨炊竟未休。
顾我有怀同大梦，期君不至更沉忧。
西园碧树今谁主，与近高窗卧听秋。','',''),('quantangshi-29630','流鸎','李商隱','quantangshi','','卷30','流鸎飘荡复参差，渡陌临流不自持。
巧啭岂能无本意，良辰未必有佳期。
风朝露夜阴晴里，万户千门开闭时。','',''),('quantangshi-29631','出关宿盘豆馆对丛芦有感','李商隱','quantangshi','','卷30','芦叶梢梢夏景深，邮亭暂欲洒尘襟。
昔年曾是江南客，此日初为关外心。
思子台边风自急，玉娘湖上月应沈。
清声不远行人去，一世荒城伴夜砧。','',''),('quantangshi-29632','和韩录事送宫人入道','李商隱','quantangshi','','卷30','星使追还不自由，双童捧上绿琼輈。
九枝灯下朝金殿，三素云中侍玉楼。
凤女颠狂成久别，月娥孀独好同游。
当时若爱韩公子，埋骨成灰恨未休。','',''),('quantangshi-29633','即目','李商隱','quantangshi','','卷30','小鼎煎茶面曲池，白须道士竹间棋。
何人书破蒲葵扇，记着南塘移树时。','',''),('quantangshi-29634','圣女祠','李商隱','quantangshi','','卷30','杳蔼逢仙迹，苍茫滞客途。
何年归碧落，此路向皇都。
消息期青雀，逢迎异紫姑。
肠回楚国梦，心断汉宫巫。
从骑裁寒竹，行车荫白榆。
星娥一去后，月姊更来无。
寡鹄迷苍壑，羇凰怨翠梧。
惟应碧桃下，方朔是狂夫。','',''),('quantangshi-29635','七月二十九日崇让宅宴作','李商隱','quantangshi','','卷30','露如微霰下前池，月过回塘万竹悲。
浮世本来多聚散，红蕖何事亦离披。
悠扬归梦惟灯见，濩落生涯独酒知。
岂到白头长只尔，嵩阳松雪有心期。','',''),('quantangshi-29636','赠从兄阆之','李商隱','quantangshi','','卷30','怅望人间万事违，私书幽梦约忘机。
荻花村里鱼标在，石藓庭中鹿迹微。
幽径定携僧共入，寒塘好与月相依。
城中猘犬憎兰佩，莫损幽芳久不归。','',''),('quantangshi-29637','吴宫','李商隱','quantangshi','','卷30','龙槛沈沈水殿清，禁门深揜断人声。
吴王宴罢满宫醉，日暮水漂花出城。','',''),('quantangshi-29638','常娥','李商隱','quantangshi','','卷30','云母屏风烛影深，长河渐落晓星沈。
常娥应悔偷灵药，碧海青天夜夜心。','',''),('quantangshi-29639','残花','李商隱','quantangshi','','卷30','残花啼露莫留春，尖髪谁非怨别人。
若但掩关劳烛梦，宝钗何日不生尘。','',''),('quantangshi-29640','天津西望','李商隱','quantangshi','','卷30','虏马崩腾忽一狂，翠华无日到东方。
天津西望肠真断，满眼秋波出苑墙。','',''),('quantangshi-29641','西亭','李商隱','quantangshi','','卷30','此夜西亭月正圆，疎帘相伴宿风烟。
梧桐莫更翻清露，孤鹤从来不得眠。','',''),('quantangshi-29642','忆住一师','李商隱','quantangshi','','卷30','无事经年别远公，帝城钟晓忆西峰。
炉烟消尽寒灯晦，童子开门雪满松。','',''),('quantangshi-29643','昨夜','李商隱','quantangshi','','卷30','不辞鶗鴂妬年芳，但惜流尘暗烛房。
昨夜西池凉露满，桂花吹断月中香。','',''),('quantangshi-29644','海客','李商隱','quantangshi','','卷30','海客乘槎上紫氛，星娥罢织一相闻。
只应不惮牵牛妬，聊用支机石赠君。','',''),('quantangshi-29645','初食笋呈座中','李商隱','quantangshi','','卷30','嫩箨香苞初出林，于陵论价重如金。
皇都陆海应无数，忍剪凌云一寸心。','',''),('quantangshi-29646','早起','李商隱','quantangshi','','卷30','风露澹清晨，帘间独起人。
鸎花啼又笑，毕竟是谁春。','',''),('quantangshi-29647','寄蜀客','李商隱','quantangshi','','卷30','君到临邛问酒垆，近来还有长卿无。
金徽却是无情物，不许文君忆故夫。','',''),('quantangshi-29648','行至金牛驿寄兴元渤海尚书','李商隱','quantangshi','','卷30','楼上春云水底天，五云章色破巴牋。
诸生个个王恭柳，从事人人庾杲莲。
六曲屏风江雨急，九枝灯檠夜珠圆。
深慙走马金牛路，骤和陈王白玉篇。','',''),('quantangshi-29649','深树见一颗樱桃尚在','李商隱','quantangshi','','卷30','高桃留晚实，寻得小庭南。
矮堕绿云髻，欹危红玉簪。
惜堪充凤食，痛已被鸎含。
越鸟夸香荔，齐名亦未甘。','',''),('quantangshi-29650','细雨','李商隱','quantangshi','','卷30','帷飘白玉堂，簟卷碧牙牀。
楚女当时意，萧萧髪彩凉。','',''),('quantangshi-29651','歌舞','李商隱','quantangshi','','卷30','遏云歌响清，回雪舞腰轻。
只要君流眄，君倾国自倾。','',''),('quantangshi-29652','海上','李商隱','quantangshi','','卷30','石桥东望海连天，徐福空来不得仙。
直遣麻姑与搔背，可能留命待桑田。','',''),('quantangshi-29653','魏侯第东北楼堂郢叔言别聊用书所见成篇','李商隱','quantangshi','','卷30','暗楼连夜阁，不拟为黄昏。
未必断别泪，何曾妨梦魂。
疑穿花逶迤，渐近火温黁。
海底翻无水，仙家却有邨。
锁香金屈[戌]，殢酒玉昆仑。
羽白风交扇，冰清月映盆。
旧欢尘自积，新岁电犹奔。
霞绮空留段，云峰不带根。
念君千里舸，江草漏灯痕。','',''),('quantangshi-29654','白云夫旧居','李商隱','quantangshi','','卷30','平生误识白云夫，再到仙檐忆酒垆。
墙外万株人绝迹，夕阳惟照欲栖乌。','',''),('quantangshi-29655','同学彭道士参寥','李商隱','quantangshi','','卷30','莫羡仙家有上真，仙家暂谪亦千春。
月中桂树高多少，试问西河斫树人。','',''),('quantangshi-29656','到秋','李商隱','quantangshi','','卷30','扇风淅沥簟流离，万里南风滞所思。
守到清秋还寂莫，叶丹苔碧闭门时。','',''),('quantangshi-29657','华师','李商隱','quantangshi','','卷30','孤鹤不睡云无心，衲衣筇杖来西林。
院门昼锁回廊静，秋日当堦柿叶阴。','',''),('quantangshi-29658','华岳下题西王母庙','李商隱','quantangshi','','卷30','神仙有分岂关情，八马虚随落日行。
莫恨名姬中夜没，君王犹自不长生。','',''),('quantangshi-29659','过华清内廐门','李商隱','quantangshi','','卷30','华清别馆闭黄昏，碧草悠悠内厩门。
自是明时不巡幸，至今青海有龙孙。','',''),('quantangshi-29660','乐游原','李商隱','quantangshi','','卷30','万树鸣蝉隔岸虹，乐游原上有西风。
羲和自趁虞泉宿，不放斜阳更向东。','',''),('quantangshi-29661','赠荷花','李商隱','quantangshi','','卷30','世间花叶不相伦，花入金盆叶作尘。
惟有绿荷红菡萏，卷舒开合任天真。
此[花]此叶常相映，翠减红衰愁杀人。','',''),('quantangshi-29662','丹丘','李商隱','quantangshi','','卷30','青女丁宁结夜霜，羲和辛苦送朝阳。
丹丘万里无消息，几对梧桐忆凤皇。','',''),('quantangshi-29663','房君珊瑚散','李商隱','quantangshi','','卷30','不见姮娥影，清秋守月轮。
月中闲杵臼，桂子捣成尘。','',''),('quantangshi-29664','小桃园','李商隱','quantangshi','','卷30','竟日小桃园，休寒亦未暄。
坐鸎当酒重，送客出墙繁。
啼久艳粉薄，舞多香雪翻。
犹怜未圆月，先出照黄昏。','',''),('quantangshi-29665','嘲樱桃','李商隱','quantangshi','','卷30','朱实鸟含尽，青楼人未归。
南园无限树，独自叶如帏。','',''),('quantangshi-29666','和张秀才落花有感','李商隱','quantangshi','','卷30','晴暖感余芳，红苞杂绛房。
落时犹自舞，扫后更闻香。
梦罢收罗荐，仙归勅玉箱。
回肠九回后，犹有剩回肠。','',''),('quantangshi-29667','代越公房妓嘲徐公主','李商隱','quantangshi','','卷30','笑啼俱不敢，几欲是吞声。
遽遣离琴怨，都由半镜明。
应防啼与笑，微露浅深情。','',''),('quantangshi-29668','代贵公主','李商隱','quantangshi','','卷30','芳条得意红，飘落忽西东。
分逐春风去，风回得故丛。
明朝金井露，始看忆春风。','',''),('quantangshi-29669','凤','李商隱','quantangshi','','卷30','万里峰峦归路迷，未判容彩借山鸡。
新春定有将雏乐，阿阁华池两处栖。','',''),('quantangshi-29670','昭肃皇帝挽歌辞三首 一','李商隱','quantangshi','','卷30','九县怀雄武，三灵仰睿文。
周王传叔父，汉后重神君。
玉律朝惊露，金茎夜切云。
笳箫凄欲断，无复咏横汾。','',''),('quantangshi-29671','昭肃皇帝挽歌辞三首 二','李商隱','quantangshi','','卷30','玉塞惊宵柝，金桥罢举烽。
始巢阿阁凤，旋驾鼎湖龙。
门咽通神鼓，楼凝警夜钟。
小臣观吉从，犹误欲东封。','',''),('quantangshi-29672','昭肃皇帝挽歌辞三首 三','李商隱','quantangshi','','卷30','莫验昭华琯，虚传甲帐神。
海迷求药使，雪隔献桃人。
桂寝青云断，松扉白露新。
万方同象鸟，举恸满秋尘。','',''),('quantangshi-29673','梓州罢吟寄同舍','李商隱','quantangshi','','卷30','不拣花朝与雪朝，五年从事霍嫖姚。
君缘接座交珠履，我为分行近翠翘。
楚雨含情皆有托，漳滨卧病竟无憀。
长吟远下燕台去，惟有衣香染未销。','',''),('quantangshi-29674','无题二首 一','李商隱','quantangshi','','卷30','凤尾香罗薄几重，碧文圆顶夜深缝。
扇裁月魄羞难掩，车走雷声语未通。
曾是寂寥金烬暗，断无消息石榴红。','',''),('quantangshi-29675','无题二首 二','李商隱','quantangshi','','卷30','重帷深下莫愁堂，卧后清宵细细长。
神女生涯原是梦，小姑居处本无郎。
风波不信菱枝弱，月露谁教桂叶香。
直道相思了无益，未妨惆怅是清狂。','',''),('quantangshi-29676','病中早访招国李十将军遇挈家游曲江','李商隱','quantangshi','','卷30','十顷平波溢岸清，病来惟梦此中行。
相如未是真消渴，犹放沱江过锦城。','',''),('quantangshi-29677','昨日','李商隱','quantangshi','','卷30','昨日紫姑神去也，今朝青鸟使来赊。
未容言语还分散，少得团圆足怨嗟。
