却羡卞和双刖足，一生无复没阶趋。','',''),('quantangshi-29683','赠句芒神','李商隱','quantangshi','','卷30','佳期不定春期赊，春物夭阏兴咨嗟。
愿得句芒索青女，不教容易损年华。','',''),('quantangshi-29684','无愁果有愁曲北齐歌','李商隱','quantangshi','','卷30','东有青龙西白虎，中含福星包世度。
玉壶渭水笑清潭，凿天不到牵牛处。
骐驎踏云天马狞，牛山撼碎珊瑚声。
秋娥点滴不成泪，十二玉楼无故钉。
推烟唾月抛千里，十番红桐一行死。
白杨别屋鬼迷人，空留暗记如蚕纸。
日暮向风牵短丝，血凝血散今谁是。','',''),('quantangshi-29685','房中曲','李商隱','quantangshi','','卷30','蔷薇泣幽素，翠带花钱小。
娇郎痴若云，抱日西帘晓。
枕是龙宫石，割得秋波色。
玉簟失柔肤，但见蒙罗碧。
忆得前年春，未语含悲辛。
归来已不见，锦瑟长于人。
今日涧底松，明日山头檗。
愁到天池翻，相看不相识。','',''),('quantangshi-29686','齐梁晴云','李商隱','quantangshi','','卷30','缓逐烟波起，如妬柳緜飘。
故临飞阁度，欲入回陂销。
萦歌怜画扇，敞景弄柔条。
更奈天南位，牛渚宿残宵。','',''),('quantangshi-29687','效徐陵体赠更衣','李商隱','quantangshi','','卷30','密帐真珠络，温帏翡翠装。
楚腰知便宠，宫眉正鬬强。
结带悬栀子，绣领刺鸳鸯。
轻寒衣省夜，金斗熨沉香。','',''),('quantangshi-29688','又效江南曲','李商隱','quantangshi','','卷30','郎船安两桨，侬舸动双桡。
扫黛开宫额，裁裙约楚腰。
乖期方积思，临酒欲拌娇。
莫以采菱唱，欲羡秦台箫。','',''),('quantangshi-29689','月夜重寄宋华阳姊妹','李商隱','quantangshi','','卷30','偷桃窃药事难兼，十二城中锁彩蟾。
应共三英同夜赏，玉楼仍是水精帘。','',''),('quantangshi-29690','访人不遇留别馆','李商隱','quantangshi','','卷30','卿卿不惜锁窗春，去作长楸走马身。
闲倚绣帘吹柳絮，日高深院断无人。','',''),('quantangshi-29691','雨中长乐水馆送赵十五滂不及','李商隱','quantangshi','','卷30','碧云东去雨云西，苑路高高驿路低。
秋水绿芜终尽分，夫君太骋锦障泥。','',''),('quantangshi-29692','汴上送李郢之苏州','李商隱','quantangshi','','卷30','人高诗苦滞夷门，万里梁王有旧园。
烟幌自应怜白紵，月楼谁伴咏黄昏。
露桃涂颊依苔井，风柳夸腰住水村。
苏小小坟今在否，紫兰香径与招魂。','',''),('quantangshi-29693','赠郑谠处士','李商隱','quantangshi','','卷30','浪迹江湖白发新，浮云一片是吾身。
寒归山观随碁局，暖入汀洲逐钓轮。
越桂留烹张翰鲙，蜀姜供煮陆机莼。
相逢一笑怜疎放，他日扁舟有故人。','',''),('quantangshi-29694','复至裴明府所居','李商隱','quantangshi','','卷30','伊人卜筑自幽深，桂巷杉篱不可寻。
柱上雕虫对书字，槽中瘦马仰听琴。
求之流辈岂易得，行矣关山方独吟。
赊取松醪一斗酒，与君相伴洒烦襟。','',''),('quantangshi-29695','览古','李商隱','quantangshi','','卷30','莫恃金汤忽太平，草间霜露古今情。
空糊頳坏真何益，欲举黄旗竟未成。
长乐瓦飞随水逝，景阳钟堕失天明。
回头一吊箕山客，始信逃尧不为名。','',''),('quantangshi-29696','子初郊墅','李商隱','quantangshi','','卷30','看山对酒君思我，听鼓离城我访君。
腊雪已添墙下水，斋钟不散槛前云。
阴移竹柏浓还淡，歌杂渔樵断更闻。
亦拟村南买烟舍，子孙相约事耕耘。','',''),('quantangshi-29697','汉南书事','李商隱','quantangshi','','卷30','西师万众几时回，哀痛天书近已裁。
文吏何曾重刀笔，将军犹自舞轮台。
几时拓土成王道，从古穷兵是祸胎。
陛下好生千万寿，玉楼长御白云杯。','',''),('quantangshi-29698','当句有对','李商隱','quantangshi','','卷30','密迩平阳接上兰，秦楼鸳瓦汉宫盘。
池光不定花光乱，日气初涵露气干。
但觉游蜂饶舞蝶，岂知孤凤忆离鸾。
三星自转三山远，紫府程遥碧落宽。','',''),('quantangshi-29699','井络','李商隱','quantangshi','','卷30','井络天彭一掌中，漫夸天设劒为峰。
阵图东聚燕江石，边柝西悬雪岭松。
堪叹故君成杜宇，可能先主是真龙。
将来为报奸雄辈，莫向金牛访旧踪。','',''),('quantangshi-29700','写意','李商隱','quantangshi','','卷30','燕雁迢迢隔上林，高秋望断正长吟。
人间路有潼江险，天外山惟玉垒深。
日向花间留返照，云从城上结层阴。
三年已制思乡泪，更入新年恐不禁。','',''),('quantangshi-29701','随师东','李商隱','quantangshi','','卷30','东征日调万黄金，几竭中原买鬬心。
军令未闻诛马谡，捷书惟是报孙歆。
但须鸑鷟巢阿阁，岂假鸱鸮在泮林。
可惜前朝玄菟郡，积骸成莽阵云深。','',''),('quantangshi-29702','宋玉','李商隱','quantangshi','','卷30','何事荆台百万家，惟教宋玉擅才华。
楚辞已不饶唐勒，风赋何曾让景差。
落日渚宫供观阁，开年云梦送烟花。
可怜庾信寻荒径，犹得三朝托后车。','',''),('quantangshi-29703','韩同年新居饯韩西迎家室戏赠','李商隱','quantangshi','','卷30','籍籍征西万户侯，新缘贵婿起朱楼。
一名我漫居先甲，千骑君翻在上头。
云路招邀回彩凤，天河迢遰笑牵牛。
南朝禁脔无人近，瘦尽琼枝咏四愁。','',''),('quantangshi-29704','奉和太原公送前杨秀才戴兼招杨正字戎','李商隱','quantangshi','','卷30','潼关地接古弘农，万里高飞雁与鸿。
桂树一枝当白日，芸香三代继清风。
仙舟尚惜乖双美，彩服何由得尽同。
谁惮士龙多笑疾，美髭终类晋司空。','',''),('quantangshi-29705','池边','李商隱','quantangshi','','卷30','玉管葭灰细细吹，流鸎上下燕参差。
日西千遶池边树，忆把枯条撼雪时。','',''),('quantangshi-29706','贾生','李商隱','quantangshi','','卷30','宣室求贤访逐臣，贾生才调更无伦。
可怜夜半虚前席，不问苍生问鬼神。','',''),('quantangshi-29707','送王十三校书分司','李商隱','quantangshi','','卷30','多少分曹掌秘文，洛阳花雪梦随君。
定知何逊缘联句，每到城东忆范云。','',''),('quantangshi-29708','寄恼韩同年二首 一','李商隱','quantangshi','','卷30','帘外辛夷定已开，开时莫放艳阳回。
年华若到经风雨，便是胡僧话劫灰。','',''),('quantangshi-29709','寄恼韩同年二首 二','李商隱','quantangshi','','卷30','龙山晴雪凤楼霞，洞里迷人有几家。
我为伤春心自醉，不劳君劝石榴花。','',''),('quantangshi-29710','谒山','李商隱','quantangshi','','卷30','从来系日乏长绳，水去云回恨不胜。
欲就麻姑买沧海，一杯春露冷如冰。','',''),('quantangshi-29711','钧天','李商隱','quantangshi','','卷30','上帝钧天会众灵，昔人因梦到青冥。
伶伦吹裂孤生竹，却为知音不得听。','',''),('quantangshi-29712','失猿','李商隱','quantangshi','','卷30','祝融南去万重云，清啸无因更一闻。
莫遣碧江通箭道，不教肠断忆同羣。','',''),('quantangshi-29713','戏题友人壁','李商隱','quantangshi','','卷30','花迳逶迤柳巷深，小阑亭舞啭春禽。
相如解作长门赋，却用文君取酒金。','',''),('quantangshi-29714','假日','李商隱','quantangshi','','卷30','素琴弦断酒瓶空，倚坐欹眠日已中。
谁向刘灵天幕内，更当陶令北窻风。','',''),('quantangshi-29715','寄远','李商隱','quantangshi','','卷30','姮娥捣药无时已，玉女投壶未肯休。
何日桑田俱变了，不教伊水向东流。','',''),('quantangshi-29716','王昭君','李商隱','quantangshi','','卷30','毛延寿画欲通神，忍为黄金不顾人。
马上琵琶行万里，汉宫长有隔生春。','',''),('quantangshi-29717','旧将军','李商隱','quantangshi','','卷30','云台高议正纷纷，谁定当时荡寇勋。
日暮灞陵原上猎，李将军是故将军。','',''),('quantangshi-29718','曼倩辞','李商隱','quantangshi','','卷30','十八年来堕世间，瑶池归梦碧桃闲。
如何汉殿穿针夜，又向窻中觑阿环。','',''),('quantangshi-29719','所居','李商隱','quantangshi','','卷30','窻下寻书细，溪边坐石平。
水风醒酒病，霜日曝衣轻。
鸡黍随人设，蒲渔得地生。
前贤无不谓，容易即遗名。','',''),('quantangshi-29720','高松','李商隱','quantangshi','','卷30','高松出众木，伴我向天涯。
客散初晴候，僧来不语时。
有风传雅韵，无雪试幽姿。
上药终相待，他年访伏龟。','',''),('quantangshi-29721','访秋','李商隱','quantangshi','','卷30','酒薄吹还醒，楼危望已穷。
江臯当落日，帆席见归风。
烟带龙潭白，霞分鸟道红。
殷勤报秋意，只是有丹枫。','',''),('quantangshi-29722','昭州','李商隱','quantangshi','','卷30','桂水春犹早，昭川日正西。
虎当官道鬬，猿上驿楼啼。
绳烂金沙井，松干乳洞梯。
乡音殊可骇，仍有醉如泥。','',''),('quantangshi-29723','哭刘司户蕡','李商隱','quantangshi','','卷30','路有论冤谪，言皆在中兴。
空闻迁贾谊，不待相孙弘。
江阔惟回首，天高但抚膺。
去年相送地，春雪满黄陵。','',''),('quantangshi-29724','裴明府居止','李商隱','quantangshi','','卷30','爱君茅屋下，向晚水溶溶。
试墨书新竹，张琴和古松。
坐来闻好鸟，归去度疎钟。
明日还相见，桥南贳酒醲。','',''),('quantangshi-29725','陆发荆南始至商洛','李商隱','quantangshi','','卷30','昔去真无奈，今还岂自知。
青辞木奴橘，紫见地仙芝。
四海秋风阔，千嵓暮景迟。
向来忧际会，犹有五湖期。','',''),('quantangshi-29726','陈后宫','李商隱','quantangshi','','卷30','玄武开新苑，龙舟宴幸频。
渚莲参法驾，沙鸟犯句陈。
寿献金茎露，歌翻玉树尘。
夜来江令醉，别诏宿临春。','',''),('quantangshi-29727','乐游原','李商隱','quantangshi','','卷30','春梦乱不记，春原登已重。
青门弄烟柳，紫阁舞云松。
拂砚轻冰散，开尊绿酎浓。
无悰托诗遣，吟罢更无悰。','',''),('quantangshi-29728','赠子直花下','李商隱','quantangshi','','卷30','池光忽隐墙，花气乱侵房。
屏缘蝶留粉，窗油蜂印黄。
官书推小吏，侍史从清郎。
竝马更吟去，寻思有底忙。','',''),('quantangshi-29729','小园独酌','李商隱','quantangshi','','卷30','柳带谁能结，花房未肯开。
空余双蝶舞，竟绝一人来。
半展龙须席，轻斟玛瑙杯。
年年春不定，虚信岁前梅。','',''),('quantangshi-29730','思归','李商隱','quantangshi','','卷30','固有楼堪依，能无酒可倾。
岭云春沮洳，江月夜晴明。
鱼乱书何托，猿哀梦易惊。
旧居连上苑，时节正迁鸎。','',''),('quantangshi-29731','献寄旧府开封公','李商隱','quantangshi','','卷30','幕府三年远，春秋一字襃。
书论秦逐客，赋续楚离骚。
地理南溟阔，天文北极高。
酬恩抚身世，未觉胜鸿毛。','',''),('quantangshi-29732','向晚','李商隱','quantangshi','','卷30','当风横去幰，临水卷空帷。
北土秋千罢，南朝祓禊归。
花情羞脉脉，柳意怅微微。
莫叹佳期晚，佳期自古稀。','',''),('quantangshi-29733','春游','李商隱','quantangshi','','卷30','桥峻斑骓疾，川长白鸟高。
烟轻惟润柳，风滥欲吹桃。
徙倚三层阁，摩挲七宝刀。
庾郎年最少，青草妬春袍。','',''),('quantangshi-29734','离席','李商隱','quantangshi','','卷30','出宿金尊掩，从公玉帐新。
依依向余照，远远隔芳尘。
细草翻惊雁，残花伴醉人。
杨朱不用劝，只是更霑巾。','',''),('quantangshi-29735','俳谐','李商隱','quantangshi','','卷30','短顾何由遂，迟光且莫惊。
鸎能歌子夜，蝶解舞宫城。
柳讶眉双浅，桃猜粉太轻。
年华有情状，吾岂怯平生。','',''),('quantangshi-29736','细雨','李商隱','quantangshi','','卷30','萧洒傍回汀，依微过短亭。
气凉先动竹，点细未开萍。
稍促高高燕，微疎的的萤。
故园烟草色，仍近五门青。','',''),('quantangshi-29737','商于新开路','李商隱','quantangshi','','卷30','六百商于路，崎岖古共闻。
蜂房春欲暮，虎穽日初曛。
路向泉间辨，人从树杪分。
更谁开捷径，速拟上青云。','',''),('quantangshi-29738','题郑大有隐居','李商隱','quantangshi','','卷30','结构何峰是，喧闲此地分。
石梁高泻月，樵路细侵云。
堰卧蛟螭室，希夷鸟兽羣。
近知西岭上，玉管有时闻。','',''),('quantangshi-29739','夜饮','李商隱','quantangshi','','卷30','卜夜容衰鬓，开筵属异方。
烛分歌扇泪，雨送酒船香。
江海三年客，干坤百战场。
谁能辞酩酊，淹卧剧清漳。','',''),('quantangshi-29740','江上','李商隱','quantangshi','','卷30','万里风来地，清江北望楼。
云通梁苑路，月带楚城秋。
刺字从漫灭，归途尚阻修。
前程更烟水，吾道岂淹留。','',''),('quantangshi-29741','凉思','李商隱','quantangshi','','卷30','客去波平槛，蝉休露满枝。
永怀当此节，倚立自移时。
北斗兼春远，南陵寓使迟。
天涯占梦数，疑误有新知。','',''),('quantangshi-29742','鸶凤','李商隱','quantangshi','','卷30','旧镜鸾何处，衰桐凤不栖。
金钱饶孔雀，锦段落山鸡。
王子调清管，天人降紫泥。
岂无云路分，相望不应迷。','',''),('quantangshi-29743','李卫公','李商隱','quantangshi','','卷30','绛纱弟子音尘绝，鸾镜佳人旧会稀。
今日致身歌舞地，木棉花暖鹧鸪飞。','',''),('quantangshi-29744','韦蟾','李商隱','quantangshi','','卷30','谢家离别正凄凉，少傅临岐赌佩囊。
却忆短亭回首处，夜来烟雨满池塘。','',''),('quantangshi-29745','自贶','李商隱','quantangshi','','卷30','陶令弃官后，仰眠书屋中。
谁将五斗米，拟换北窗风。','',''),('quantangshi-29746','蝶','李商隱','quantangshi','','卷30','孤蝶小徘徊，翩翾粉翅开。
并应伤皎洁，频近雪中来。','',''),('quantangshi-29747','夜意','李商隱','quantangshi','','卷30','帘垂幕半卷，枕冷被仍香。
如何为相忆，魂梦过潇湘。','',''),('quantangshi-29748','因书','李商隱','quantangshi','','卷30','绝徼南通栈，孤城北枕江。
猿声连月槛，鸟影落天窗。
海石分碁子，郫筒当酒缸。
生归话辛苦，别夜对凝釭。','',''),('quantangshi-29749','奉寄安国大师兼简子蒙','李商隱','quantangshi','','卷30','忆奉莲花座，兼闻贝叶经。
岩光分蜡屐，涧响入铜瓶。
日下徒推鹤，天涯正对萤。
鱼山羡曹植，眷属有文星。','',''),('quantangshi-29750','闲游','李商隱','quantangshi','','卷30','危亭题竹粉，曲沼嗅荷花。
数日同携酒，平明不在家。
寻幽殊未极，得句总堪夸。
强下西楼去，西楼倚暮霞。','',''),('quantangshi-29751','县中恼饮席','李商隱','quantangshi','','卷30','晚醉题诗赠物华，罢吟还醉忘归家。
若无江氏五色笔，争奈河阳一县花。','',''),('quantangshi-29752','题李上謩壁','李商隱','quantangshi','','卷30','旧着思玄赋，新编杂拟诗。
江庭犹近别，山舍得幽期。
嫩割周颙韭，肥烹鲍照葵。
饱闻南烛酒，仍及拨醅时。','',''),('quantangshi-29753','江村题壁','李商隱','quantangshi','','卷30','沙岸竹森森，维艄听越禽。
数家同老寿，一径自阴深。
喜客尝留橘，应官说采金。
倾壶真得地，爱日静霜砧。','',''),('quantangshi-29754','即日','李商隱','quantangshi','','卷30','桂林闻旧说，曾不异炎方。
山响匡牀语，花飘度腊香。
几时逢雁足，着处断猿肠。
独抚青青桂，临城忆雪霜。','',''),('quantangshi-29755','漫成五章 一','李商隱','quantangshi','','卷30','沈宋裁辞矜变律，王杨落笔得良朋。
当时自谓宗师妙，今日惟观对属能。','',''),('quantangshi-29756','漫成五章 二','李商隱','quantangshi','','卷30','李杜操持事略齐，三才万象共端倪。
集仙殿与金銮殿，可是苍蝇惑曙鸡。','',''),('quantangshi-29757','漫成五章 三','李商隱','quantangshi','','卷30','生儿古有孙征虏，嫁女今无王右军。
借问琴书终一世，何如旗盖仰三分。','',''),('quantangshi-29758','漫成五章 四','李商隱','quantangshi','','卷30','代北偏师衔使节，关中裨将建行台。
不妨常日饶轻薄，且喜临戎用草莱。','',''),('quantangshi-29759','漫成五章 五','李商隱','quantangshi','','卷30','郭令素心非黩武，韩公本意在和戎。
两都耆旧偏垂泪，临老中原见朔风。','',''),('quantangshi-29760','射鱼曲','李商隱','quantangshi','','卷30','思牢弩箭磨青石，绣额蛮渠三虎力。
寻潮背日伺泅鳞，贝阙夜移鲸失色。
纤纤粉簳馨香饵，绿鸭回塘养龙水。
含冰汉语远于天，何由回作金盘死。','',''),('quantangshi-29761','日高','李商隱','quantangshi','','卷30','镀镮故锦縻轻拖，玉𥫽不动便门锁。
水精眠梦是何人，栏药日高红髲𩭝。
飞香上云春诉天，云梯十二门九关。
轻身灭影何可望，粉蛾帖死屏风上。','',''),('quantangshi-29762','宫中曲','李商隱','quantangshi','','卷30','云母滤宫月，夜夜白于水。
赚得羊车来，低扇遮黄子。
水精不觉冷，自刻鸳鸯翅。
蚕缕茜香浓，正朝缠左臂。
巴牋两三幅，满写承恩字。
欲得识青天，昨夜苍龙是。','',''),('quantangshi-29763','海上谣','李商隱','quantangshi','','卷30','桂水寒于江，玉兔秋冷咽。
海底觅仙人，香桃如瘦骨。
紫鸾不肯舞，满翅蓬山雪。
借得龙堂宽，晓出揲云髪。
刘郎旧香炷，立见茂陵树。
云孙帖帖卧秋烟，上元细字如蚕眠。','',''),('quantangshi-29764','李夫人三首 一','李商隱','quantangshi','','卷30','一带不结心，两股方安髻。
慙愧白茅人，月没教星替。','',''),('quantangshi-29765','李夫人三首 二','李商隱','quantangshi','','卷30','剩结茱萸枝，多擘秋莲的。
独自有波光，彩囊盛不得。','',''),('quantangshi-29766','李夫人三首 三','李商隱','quantangshi','','卷30','蛮丝系条脱，妍眼和香屑。
寿宫不惜铸南人，柔肠早被秋眸割。
清澄有余幽素香，鳏鱼渴凤真珠房。
不知瘦骨类冰井，更许夜帘通晓霜。
土花漠漠云茫茫，黄河欲尽天苍苍。','',''),('quantangshi-29767','景阳宫井双桐','李商隱','quantangshi','','卷30','秋港菱花干，玉盘明月蚀。
血渗两枯心，情多去未得。
徒经白门伴，不见丹山客。
未待刻作人，愁多有魂魄。
谁将玉盘与，不死翻相误。
天更阔于江，孙枝觅郎主。
昔妬隣宫槐，道类双眉歛。
今日繁红樱，抛人占长簟。
翠襦不禁绽，留泪啼天眼。
寒灰劫尽问方知，石羊不去谁相绊。','',''),('quantangshi-29768','秋日晚思','李商隱','quantangshi','','卷30','桐槿日零落，雨余方寂寥。
枕寒庄蝶去，窻冷胤萤销。
取适琴将酒，忘名牧与樵。
平生有游旧，一一在烟霄。','',''),('quantangshi-29769','春宵自遣','李商隱','quantangshi','','卷30','地胜遗尘事，身闲念岁华。
晚晴风过竹，深夜月当花。
石乱知泉咽，苔荒任迳斜。
陶然恃琴酒，忘却在山家。','',''),('quantangshi-29770','七夕偶题','李商隱','quantangshi','','卷30','宝婺摇珠佩，常娥照玉轮。
灵归天上匹，巧遗世间人。
花果香千户，笙竽滥四隣。
明朝晒犊鼻，方信阮家贫。','',''),('quantangshi-29771','灵仙阁晚眺寄郓州韦评事','李商隱','quantangshi','','卷30','愚公方住谷，仁者本依山。
共誓林泉志，胡为尊俎间。
华莲开菡萏，荆玉刻孱颜。
爽气临周道，岚光入汉关。
满壶徒蚁泛，高阁已苔斑。
想就安车召，宁期负矢还。
潘游全璧散，郭去半舟闲。
定笑幽人迹，鸿轩不可攀。','',''),('quantangshi-29772','幽居冬暮','李商隱','quantangshi','','卷30','羽翼摧残日，郊园寂寞时。
晓鸡惊树雪，寒骛守冰池。
急景忽云暮，颓年浸已衰。
如何匡国分，不与夙心期。','',''),('quantangshi-29773','过姚孝子庐偶书','李商隱','quantangshi','','卷30','拱木临周道，荒庐积古苔。
鱼因感姜出，鹤为吊陶来。
两鬓蓬常乱，双眸血不开。
圣朝敦尔类，非独路人哀。','',''),('quantangshi-29774','赋得月照冰池','李商隱','quantangshi','','卷30','皓月方离海，坚冰正满池。
金波双激射，璧彩两参差。
影占徘徊处，光含的皪时。
高低连素色，上下接清规。
顾兔飞难定，潜鱼跃未期。
鹊惊俱欲遶，狐听始无疑。
似镜将盈手，如霜恐透肌。
独怜游翫意，达晓不知疲。','',''),('quantangshi-29775','永乐县所居一草一木无非自栽今春悉已芳茂因书即事一章','李商隱','quantangshi','','卷30','手种悲陈事，心期玩物华。
柳飞彭泽雪，桃散武陵霞。
枳嫩栖鸾叶，桐香待凤花。
绶藤萦弱蔓，袍草展新芽。
学植功虽倍，成蹊迹尚赊。
芳年谁共玩，终老邵平瓜。','',''),('quantangshi-29776','南潭上亭宴集以疾后至因而抒情','李商隱','quantangshi','','卷30','马卿聊应召，谢傅已登山。
歌发百花外，乐调深竹间。
鷁舟萦远岸，鱼钥启重关。
鸎蝶如相引，烟萝不暇攀。
佳人启玉齿，上客颔朱颜。
肯念沈疴士，俱期倒载还。','',''),('quantangshi-29777','寒食行次冷泉驿','李商隱','quantangshi','','卷30','驿途仍近节，旅宿倍思家。
独夜三更月，空庭一树花。
介山当驿秀，汾水遶关斜。
自怯春寒苦，那堪禁火赊。','',''),('quantangshi-29778','寄华岳孙逸人','李商隱','quantangshi','','卷30','灵岳几千仞，老松逾百寻。
攀崖仍蹑壁，噉叶复眠阴。
海上呼三岛，斋中戏五禽。
唯应逢阮籍，长啸作鸾音。','',''),('quantangshi-29779','戏题赠稷山驿吏王全','李商隱','quantangshi','','卷30','绛台驿吏老风尘，耽酒成仙几十春。
过客不劳询甲子，惟书亥字与时人。','',''),('quantangshi-29780','和韦潘前辈七月十二日夜泊池州城下先寄上李使君','李商隱','quantangshi','','卷30','桂含爽气三秋首，蓂吐中旬二叶新。
正是澄江如练处，玄晖应喜见诗人。','',''),('quantangshi-29781','花下醉','李商隱','quantangshi','','卷30','寻芳不觉醉流霞，倚树沈眠日已斜。
客散酒醒深夜后，更持红烛赏残花。','',''),('quantangshi-29782','所居永乐县久旱县宰祈祷得雨因赋诗','李商隱','quantangshi','','卷30','甘膏滴滴是精诚，昼夜如丝一尺盈。
祗怪闾阎喧鼓吹，邑人同报束长生。','',''),('quantangshi-29783','正月十五夜闻京有灯恨不得观','李商隱','quantangshi','','卷30','月色灯光满帝都，香车宝辇隘通衢。
身闲不睹中兴盛，羞逐乡人赛紫姑。','',''),('quantangshi-29784','赠赵协律晰','李商隱','quantangshi','','卷30','俱识孙公与谢公，二年歌哭处还同。
已叨邹马声华末，更共刘卢族望通南省恩深宾馆在，东山事往妓楼空。
不堪岁暮相逢地，我欲西征君又东。','',''),('quantangshi-29785','摇落','李商隱','quantangshi','','卷30','摇落伤年日，羁留念远心。
水亭吟断续，月幌梦飞沈。
古木含风久，疎萤怯露深。
人闲始遥夜，地迥更清砧。
结爱曾伤晚，端忧复至今。
未谙沧海路，何处玉山岑？
滩激黄牛暮，云屯白帝阴。
遥知霑洒意，不减欲分襟。','',''),('quantangshi-29786','滞雨','李商隱','quantangshi','','卷30','滞雨长安夜，残灯独客愁。
故乡云水地，归梦不宜秋。','',''),('quantangshi-29787','偶题二首 一','李商隱','quantangshi','','卷30','小亭闲眠微醉消，山榴海栢枝相交。
水文簟上琥珀枕，傍有堕钗双翠翘。','',''),('quantangshi-29788','偶题二首 二','李商隱','quantangshi','','卷30','清月依微香露轻，曲房小院多逢迎。
春丛定见饶栖鸟，饮罢莫持红烛行。','',''),('quantangshi-29789','月','李商隱','quantangshi','','卷30','过水穿楼触处明，藏人带树远含清。
初生欲缺虚惆怅，未必圆时即有情。','',''),('quantangshi-29790','夜冷','李商隱','quantangshi','','卷30','树遶池宽月影多，村砧坞笛隔风萝。
西亭翠被余香薄，一夜将愁向败荷。','',''),('quantangshi-29791','正月崇让宅','李商隱','quantangshi','','卷30','密锁重关掩绿苔，廊深阁迥此徘徊。
先知风起月含晕，尚自露寒花未开。
蝙拂帘旌终展转，鼠翻牕网小惊猜。
背灯独共余香语，不觉犹歌起夜来。','',''),('quantangshi-29792','城外','李商隱','quantangshi','','卷30','露寒风定不无情，临水当山又隔城。
未必明时胜蜯蛤，一生长共月亏盈。','',''),('quantangshi-29793','撰彭阳公志文毕有感','李商隱','quantangshi','','卷30','延陵留表墓，岘首送沈碑。
敢伐不加点，犹当无愧辞。
百生终莫报，九死谅难追。
待得生金后，川原亦几移。','',''),('quantangshi-29794','北青萝','李商隱','quantangshi','','卷30','残阳西入崦，茅屋访孤僧。
落叶人何在，寒云路几层。
独敲初夜磬，闲倚一枝藤。
世界微尘里，吾宁爱与憎。','',''),('quantangshi-29795','戏赠张书记','李商隱','quantangshi','','卷30','别馆君孤枕，空庭我闭关。
池光不受月，野气欲沈山。
星汉秋方会，关河梦几还。
危弦伤远道，明镜惜红颜。
古木含风久，平芜尽日闲。
心知两愁绝，不段若寻环。','',''),('quantangshi-29796','幽人','李商隱','quantangshi','','卷30','丹竈三年火，苍崖万岁藤。
樵归说逢虎，碁罢正留僧。
星斗同秦分，人烟接汉陵。
东流清渭苦，不尽照衰兴。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-29797','念远','李商隱','quantangshi','','卷30','日月淹秦甸，江湖动越吟。
苍桐应露下，白阁自云深。
皎皎非鸾扇，翘翘失凤簪。
牀空鄂君被，杵冷女媭砧。
北思惊沙雁，南情属海禽。
关山已摇落，天地共登临。','',''),('quantangshi-29798','过故崔兖海宅与崔明秀才话旧因寄僚杜赵李三掾','李商隱','quantangshi','','卷30','绛帐恩如昨，乌衣事莫寻。
诸生空会葬，旧掾已华簪。
共入留宾驿，俱分市骏金。
莫凭无鬼论，终负托孤心。','',''),('quantangshi-29799','微雨','李商隱','quantangshi','','卷30','初随林霭动，稍共夜凉分。
窗迥侵灯冷，庭虚近水闻。','',''),('quantangshi-29800','南山赵行军新诗盛称游宴之洽因寄一絶','李商隱','quantangshi','','卷30','莲幕遥临黑水津，橐鞬无事但寻春。
梁王司马非孙武，且免宫中斩美人。','',''),('quantangshi-29801','曲江','李商隱','quantangshi','','卷30','望断平时翠辇过，空闻子夜鬼悲歌。
金舆不返倾城色，玉殿犹分下苑波。
死忆华亭闻唳鹤，老忧王室泣铜驼。
天荒地变心难折，若比阳春意未多。','',''),('quantangshi-29802','景阳井','李商隱','quantangshi','','卷30','景阳宫井剩堪悲，不尽龙鸾誓死期。
肠断吴王宫外水，浊泥犹得葬西施。','',''),('quantangshi-29803','故番禺侯以赃罪致不辜事觉母者他日过其门','李商隱','quantangshi','','卷30','饮鸩非君命，兹身亦厚亡。
江陵从种橘，交广合投香。
不见千金子，空馀数仞墙。
杀人须显戮，谁举汉三章。','',''),('quantangshi-29804','咏云','李商隱','quantangshi','','卷30','捧月三更断，藏星七夕明。
才闻飘迥路，旋见隔重城。
潭暮随龙起，河秋压雁声。
只应惟宋玉，知是楚神名。','',''),('quantangshi-29805','夜出西溪','李商隱','quantangshi','','卷30','东府忧春尽，西溪许日曛。
月澄新涨水，星见欲销云。
柳好休伤别，松高莫出羣。
军书虽倚马，犹未当能文。','',''),('quantangshi-29806','效长吉','李商隱','quantangshi','','卷30','长长汉殿眉，窄窄楚宫衣。
镜好鸾空舞，帘疎燕误飞。
君王不可问，昨夜约黄归。','',''),('quantangshi-29807','柳','李商隱','quantangshi','','卷30','江南江北雪初消，漠漠轻黄惹嫩条。
灞岸已攀行客手，楚宫先骋舞姬腰。
清明带雨临官道，晚日含风拂野桥。
如线如丝正牵恨，王孙归路一何遥。','',''),('quantangshi-29808','九月于东逢雪','李商隱','quantangshi','','卷30','举家忻共报，秋雪堕前峰。
岭外他年忆，于东此日逢。
粒轻还自乱，花薄未成重。
岂是惊离鬓，应来洗病容。','',''),('quantangshi-29809','四皓庙','李商隱','quantangshi','','卷30','本为留侯慕赤松，汉庭方识紫芝翁。
萧何只解追韩信，岂得虚当第一功。','',''),('quantangshi-29810','送阿龟归华','李商隱','quantangshi','','卷30','草堂归意背烟萝，黄绶垂腰不奈何。
因汝华阳求药物，碧松根下茯苓多。','',''),('quantangshi-29811','九日','李商隱','quantangshi','','卷30','曾共山翁把酒时，霜天白菊绕堦墀。
十年泉下无人问，九日樽前有所思。
不学汉臣栽苜蓿，空教楚客咏江篱。
郎君官贵施行马，东阁无因再得窥。','',''),('quantangshi-29812','僧院牡丹','李商隱','quantangshi','','卷30','薄叶风才倚，枝轻雾不胜。
开先如避客，色浅为依僧。
粉壁正荡水，缃帏初卷灯。
倾城惟待笑，要裂几多缯。','',''),('quantangshi-29813','赠司勋杜十三员外','李商隱','quantangshi','','卷30','杜牧司勋字牧之，清秋一首杜秋诗。
前身应是梁江总，名总还曾字总持。
心铁已从干镆利，鬓丝休叹雪霜垂。
汉江远吊西江水，羊[祜]韦丹尽有碑。','',''),('quantangshi-29814','高花','李商隱','quantangshi','','卷30','花将人共笑，篱外露繁枝。
宋玉临江宅，墙低不碍窥。','',''),('quantangshi-29815','嘲桃','李商隱','quantangshi','','卷30','无赖夭桃面，平明露井东。
春风为开了，却拟笑春风。','',''),('quantangshi-29816','送丰都李尉','李商隱','quantangshi','','卷30','万古商于地，凭君泣路岐。
固难寻绮季，可得信张仪。
雨气燕先觉，叶阴蝉遽知。
望乡尤忌晚，山晚更参差。','',''),('quantangshi-29817','天平公座中呈令狐令公时蔡京在坐京曾为僧徒故有第五句','李商隱','quantangshi','','卷30','罢执霓旌上醮坛，慢妆娇树水晶盘。
更深欲诉蛾眉歛，衣薄临醒玉艳寒。
白足禅僧思败道，青袍御史拟休官。
虽然同是将军客，不敢公然子细看。','',''),('quantangshi-29818','江上忆严五广休','李商隱','quantangshi','','卷30','征南幕下带长刀，梦笔深藏五色毫。
逢着澄江不敢咏，镇西留与谢功曹。','',''),('quantangshi-29819','饯席重送从叔余之梓州','李商隱','quantangshi','','卷30','莫叹万重山，君还我未还。
武关犹怅望，何况百牢关。','',''),('quantangshi-29820','访隐','李商隱','quantangshi','','卷30','路到层峰断，门依老树开。
月从平楚转，泉自上方来。
薤白罗朝馔，松黄暖夜杯。
相留笑孙绰，空解赋天台。','',''),('quantangshi-29821','寓兴','李商隱','quantangshi','','卷30','薄宦仍多病，从知竟远游。
谈谐叨客礼，休澣接冥搜。
树好频移榻，云奇不下楼。
岂关无景物，自是有乡愁。','',''),('quantangshi-29822','东南','李商隱','quantangshi','','卷30','东南一望日中乌，欲遂羲和去得无。
且向秦楼棠树下，每朝先觅照罗敷。','',''),('quantangshi-29823','归来','李商隱','quantangshi','','卷30','旧隐无何别，归来始更悲。
难寻白道士，不见惠禅师。
草径虫鸣急，沙渠水下迟。
却将波浪眼，清晓对红梨。','',''),('quantangshi-29824','子直晋昌李花','李商隱','quantangshi','','卷30','吴馆何时熨，秦台几夜熏。
绡轻谁解卷，香异自先闻。
月里谁无姊，云中亦有君。
罇前见飘荡，愁极客襟分。','',''),('quantangshi-29825','河清与赵氏昆季宴集得拟杜工部','李商隱','quantangshi','','卷30','胜概殊江右，佳名逼渭川。
虹收青嶂雨，鸟没夕阳天。
客鬓行如此，沧波坐渺然。
此中真得地，漂荡钓鱼船。','',''),('quantangshi-29826','寓目','李商隱','quantangshi','','卷30','园桂悬心碧，池莲饫眼红。
此生真远客，几别即衰翁。
小幌风烟入，高窻雾雨通。
新知他日好，锦瑟傍朱栊。','',''),('quantangshi-29827','题道静院院在中条山故王颜中丞所置虢州刺史舍官居此今写真存焉','李商隱','quantangshi','','卷30','紫府丹成化鹤羣，青松手植变龙文。
壶中别有仙家日，岭上犹多隐士云。
独坐遗芳成故事，褰帷旧貌似元君。
自怜筑室灵山下，徒望朝岚与夕曛。','',''),('quantangshi-29828','赋得桃李无言','李商隱','quantangshi','','卷30','夭桃花正发，穠李蘂方繁。
应候非争艳，成蹊不在言。
静中霞暗吐，香处雪潜翻。
得意摇风态，含情泣露痕。
芬芳光上苑，寂默委中园。
赤白徒自许，幽芳谁与论。','',''),('quantangshi-29829','登霍山驿楼','李商隱','quantangshi','','卷30','庙列前峰迥，楼开四望穷。
岭鼷岚色外，陂雁夕阳中。
弱柳千条露，衰荷一面风。
壶关有狂孽，速继老生功。','',''),('quantangshi-29830','寄和水部马郎中题兴德驿时昭义已平','李商隱','quantangshi','','卷30','仙郎倦去心，郑驿暂登临。
水色潇湘阔，沙程朔漠深。
鷁舟时往复，鸥鸟恣浮沈。
更想逢归马，悠悠岳树阴。','',''),('quantangshi-29831','题小松','李商隱','quantangshi','','卷30','怜君孤秀植庭中，细叶轻阴满座风。
桃李盛时虽寂寞，雪霜多后始青葱。
一年几变枯荣事，百尺方资柱石功。
为谢西园车马客，定悲摇落尽成空。','',''),('quantangshi-29832','行次昭应县道上送户部李郎中充昭义攻讨','李商隱','quantangshi','','卷30','将军大斾埽狂童，诏选名贤赞武功。
暂逐虎牙临故绛，远含鸡舌过新丰。
鱼游沸鼎知无日，鸟覆危巢岂待风。
早勒勋庸燕石上，伫光纶綍汉廷中。','',''),('quantangshi-29833','水斋','李商隱','quantangshi','','卷30','多病欣依有道邦，南塘宴起想秋江。
卷帘飞燕还拂水，开户暗虫犹打窗。
更阅前题已披卷，仍斟昨夜未开缸。
谁人为报故交道，莫惜鲤雨时一双。','',''),('quantangshi-29834','奉同诸公题河中任中丞新创河亭四韵之作','李商隱','quantangshi','','卷30','万里谁能访十洲，新亭云构压中流。
河鲛纵翫难为室，海蜃遥惊耻化楼。
左右名山穷远目，东西大道锁轻舟。
独留巧思传千古，长与蒲津作胜游。','',''),('quantangshi-29835','过故府中武威公交城旧庄感事','李商隱','quantangshi','','卷30','信陵亭馆接郊畿，幽象遥通晋水祠。
日落高门喧燕雀，风飘大树撼熊罴。
新蒲似笔思投日，芳草如茵忆吐时。
山下祗今黄绢字，泪痕犹堕六州儿。','',''),('quantangshi-29836','赠田叟','李商隱','quantangshi','','卷30','荷蓧衰翁似有情，相逢携手遶村行。
烧畲晓映远山色，伐树暝传深谷声。
鸥鸟忘机翻浃洽，交亲得路昧平生。
抚躬道直诚感激，在野无贤心自惊。','',''),('quantangshi-29837','赠别前蔚州契苾使君','李商隱','quantangshi','','卷30','何年部落到阴陵，奕世勤王国史称。
夜卷牙旗千帐雪，朝飞羽骑一河冰。
蕃儿襁负来青冢，狄女壶浆出白登。
日晚䴙鹈泉畔猎，路人遥识郅都鹰。','',''),('quantangshi-29838','和人题真娘墓','李商隱','quantangshi','','卷30','虎丘山下劒池边，长遣游人叹逝川。
罥树断丝悲舞席，出云清梵想歌筵。
柳眉空吐效颦叶，榆荚还飞买笑钱。
一自香魂招不得，祗应江上独婵娟。','',''),('quantangshi-29839','人日即事','李商隱','quantangshi','','卷30','文王喻复今朝是，子晋吹笙此日同。
舜格有苗旬太远，周称流火月难穷。
镂金作胜传荆俗，翦彩为人起晋风。
独想道衡诗思苦，离家恨得二年中。','',''),('quantangshi-29840','春日寄怀','李商隱','quantangshi','','卷30','世间荣落重逡巡，我独丘园坐四春。
纵使有花兼有月，可堪无酒又无人。
青袍似草年年定，白发如丝日日新。
欲逐风波千万里，未知何路到龙津。','',''),('quantangshi-29841','和刘评事永乐闲居见寄','李商隱','quantangshi','','卷30','白社幽闲君暂居，青云器业我全疎。
看封谏草归鸾掖，尚贲衡门待鹤书。
莲耸碧峰关路近，荷翻翠扇水堂虚。
自探典籍忘名利，欹枕时惊落蠹鱼。','',''),('quantangshi-29842','和马郎中移白菊见示','李商隱','quantangshi','','卷30','陶诗只采黄金宝，郢曲新传白雪英。
素色不同篱下发，繁花疑自月中生。
浮杯小摘开云母，带露全移缀水精。
偏称含香五字客，从兹得地始芳荣。','',''),('quantangshi-29843','喜闻太原同院崔侍御台拜兼寄在台三二同年之什','李商隱','quantangshi','','卷30','鹏鱼何事遇屯同，云水升沈一会中。
刘放未归鸡树老，邹阳新去兔园空。
寂寥我对先生柳，赫奕君乘御史骢。
若向南台见莺友，为传垂翅度春风。','',''),('quantangshi-29844','喜雪','李商隱','quantangshi','','卷30','朔雪自龙沙，呈祥势可嘉。
有田皆种玉，无树不开花。
班扇慵裁素，曹衣讵比麻。
鹅归逸少宅，鹤满令威家。
寂寞门扉掩，依稀履迹斜。
人疑游面市，马似困盐车。
洛水妃虚妬，姑山客漫夸。
联辞虽许谢，和曲本慙巴。
粉署闱全隔，霜台路正赊。
此时倾贺酒，相望在京华。','',''),('quantangshi-29845','柳枝五首 一','李商隱','quantangshi','','卷30','花房与蜜脾，蜂雄蛱蝶雌。
同时不同类，那复更相思。','',''),('quantangshi-29846','柳枝五首 二','李商隱','quantangshi','','卷30','本是丁香树，春条结始生。
玉作弹碁局，中心亦不平。','',''),('quantangshi-29847','柳枝五首 三','李商隱','quantangshi','','卷30','嘉瓜引蔓长，碧玉冰寒浆。
东陵虽五色，不忍值牙香。','',''),('quantangshi-29848','柳枝五首 四','李商隱','quantangshi','','卷30','柳枝井上蟠，莲叶浦中干。
锦鳞与绣羽，水陆有伤残。','',''),('quantangshi-29849','柳枝五首 五','李商隱','quantangshi','','卷30','画屏绣步障，物物自成双。
如何湖上望，只是见鸳鸯。','',''),('quantangshi-29850','燕台四首 春','李商隱','quantangshi','','卷30','风光冉冉东西陌，几日娇魂寻不得。
蜜房羽客类芳心，冶叶倡条徧相识。
暖蔼辉迟桃树西，高鬟立共桃鬟齐。
雄龙雌凤杳何许，絮乱丝繁天亦迷。
醉起微阳若初曙，映帘梦断闻残语。
愁将铁网罥珊瑚，海阔天翻迷处所。
衣带无情有宽窄，春烟自碧秋霜白。
研丹擘石天不知，愿得天牢锁冤魄。
夹罗委箧单绡起，香肌冷衬琤琤佩。
今日东风自不胜，化作幽光入西海。','',''),('quantangshi-29851','燕台四首 夏','李商隱','quantangshi','','卷30','前阁雨帘愁不卷，后堂芳树阴阴见。
石城景物类黄泉，夜半行郎空柘弹。
绫扇唤风阊阖天，轻帷翠幕波渊旋。
蜀魂寂寞有伴未，几夜瘴花开木棉。
桂宫留影光难取，嫣薰兰破轻轻语。
直教银汉堕怀中，未遣星妃镇来去。
浊水清波何异源，济河水清黄河浑。
安得簿雾起缃裙，手接云軿呼太君。','',''),('quantangshi-29852','燕台四首 秋','李商隱','quantangshi','','卷30','月浪冲天天宇湿，凉蟾落尽疎星入。
云屏不动掩孤嚬，西楼一夜风筝急。
欲织相思花寄远，终日相思却相怨。
但闻北斗声回环，不见长河水清浅。
金鱼锁断红桂春，古时尘满鸳鸯茵。
堪悲小苑作长道，玉树未怜亡国人。
瑶琴愔愔藏楚弄，越罗冷薄金泥重。
帘钩鹦鹉夜惊霜，唤起南云绕云梦。
双璫丁丁联尺素，内记湘川相识处。
歌唇一世衔雨看，可惜馨香手中故。','',''),('quantangshi-29853','燕台四首 冬','李商隱','quantangshi','','卷30','天东日出天西下，雌凤孤飞女龙寡。
青溪白石不相望，堂中远甚苍梧野。
冻壁霜华交隐起，芳根中断香心死。
浪乘画舸忆蟾蜍，月娥未必婵娟子。
楚管蛮弦愁一概，空城舞罢腰支在。
当时欢向掌中销，桃叶桃根双姊妹。
破鬟矮堕凌朝寒，白玉燕钗黄金蝉。
风车雨马不持去，蜡烛啼红怨天曙。','',''),('quantangshi-29854','河内诗二首 一','李商隱','quantangshi','','卷30','鼍鼓沈沈虬水咽，秦丝不上蛮弦绝。
常娥衣薄不禁寒，蟾蜍夜艳秋河月。
碧城冷落空蒙烟，帘轻幕重金钩栏。
灵香不下两皇子，孤星直上相风竿。
八桂林边九芝草，短襟小鬓相逢道。
入门暗数一千春，愿去闰年留月小。
栀子交加香蓼繁，停辛伫苦留待君。','',''),('quantangshi-29855','河内诗二首 二','李商隱','quantangshi','','卷30','阊门日下吴歌远，陂路绿菱香满满。
后溪暗起鲤鱼风，船旗闪断芙蓉干。
轻身奉君畏身轻，双桡两桨樽酒清。
莫因风雨罢团扇，此曲断肠惟北声。
低楼小径城南道，犹自金鞍对芳草。','',''),('quantangshi-29856','赠送前刘五经映三十四韵','李商隱','quantangshi','','卷30','建国宜师古，兴邦属上庠。
从来以儒戏，安得振朝纲。
叔世何多难，兹基遂已亡。
泣麟犹委吏，歌凤更佯狂。
屋壁余无几，焚坑逮可伤。
挟书秦二世，壤宅汉诸王。
草草临盟誓，区区务富强。
微茫金马署，狼籍鬬鸡场。
尽欲心无窍，皆如面正墙。
惊疑豹文鼠，贪窃虎皮羊。
南渡宜终否，西迁冀小康。
策非方正士，贡绝孝廉郎。
海鸟悲钟鼓，狙公畏服裳。
多岐空扰扰，幽室竟伥伥。
凝邈为时范，虚空作士常。
何由羞五霸，直自呰三皇。
别派驱杨墨，他镳并老庄。
诗书资破冢，法制困探囊。
周礼仍存鲁，隋师果禅唐。
鼎新麾一举，革故法三章。
星宿森文雅，风雷起退藏。
缧囚为学切，掌故受经忙。
夫子时之彦，先生迹未荒。
褐衣终不召，白首兴难忘。
感激殊非圣，栖迟到异粻。
片辞褒有德，一字贬无良。
燕地尊邹衍，西河重卜商。
式闾真道在，拥彗信谦光。
获预青衿列，叨来绛帐旁。
虽从各言志，还要大为防。
勿谓孤寒弃，深忧讦直妨。
叔孙谗易得，盗跖暴难当。
雁下秦云黑，蝉休陇叶黄。
莫逾巾屦念，容许后升堂。','',''),('quantangshi-29857','哭遂州萧侍郎二十四韵','李商隱','quantangshi','','卷30','遥作时多难，先令祸有源。
初惊逐客议，旋骇党人冤。
密侍荣方入，司刑望愈尊。
皆因优诏用，实有谏书存。
苦雾三辰没，穷阴四塞昏。
虎威狐更假，隼击鸟逾喧。
徒欲心存阙，终遭耳属垣。
遗音和蜀魄，易箦对巴猿。
有女悲初寡，无男泣过门。
朝争屈原草，庙馁莫敖魂。
迥阁伤神峻，长江极望翻。
青云宁寄意，白骨始霑恩。
早岁思东合，为邦属故园。
登舟惭郭泰，解榻愧陈蕃。
分以忘年契，情犹锡类敦。
公先真帝子，我系本王孙。
啸傲张高盖，从容接短辕。
秋吟小山桂，春醉后堂萱。
自叹离通籍，何尝忘呌阍。
不成穿圹入，终拟上书论。
多士还鱼贯，云谁正骏奔。
暂能诛儵忽，长与问干坤。
蚁漏三泉路，螿啼百草根。
始知同泰讲，徼福是虚言。','',''),('quantangshi-29858','送千牛李将军赴阙五十韵','李商隱','quantangshi','','卷30','照席琼枝秀，当年紫绶荣。
班资古直阁，勋伐旧西京。
在昔王纲紊，因谁国步清。
如无一战霸，安有大横庚。
内竖依凭切，凶门责望轻。
中台终恶直，上将更要盟。
丹陛祥烟灭，皇闱杀气横。
喧阗众狙怒，容易八蛮惊。
梼杌宽之久，防风戮不行。
素来矜异类，此去岂亲征。
舍鲁真非策，居邠未有名。
曾无力牧御，宁待雨师迎。
火箭侵乘石，云桥逼禁营。
何时绝刁斗，不夜见欃枪。
屡亦闻投鼠，谁其敢射鲸。
世情休念乱，物议笑轻生。
大卤思龙跃，苍梧失象耕。
灵衣沾愧汗，仪马困阴兵。
别馆兰薰酷，深宫蜡焰明。
黄山遮舞态，黑水断歌声。
纵未移周鼎，何辞免赵坑。
空拳转鬬地，数板不沈城。
且欲凭神算，无因计力争。
幽囚苏武节，弃市仲由缨。
下殿言终验，增埤事早萌。
蒸鸡殊减饍，屑麴异和羹。
否极时还泰，屯余运果亨。
流离几南渡，仓卒得西平。
神鬼收昏黑，奸凶首满盈。
官非督护贵，师以丈人贞。
覆载还高下，寒暄急改更。
马前烹莽卓，坛上揖韩彭。
扈跸三才正，回军六合晴。
此时惟短劒，仍世尽双旌。
顾我由羣从，逢君叹老成。
庆流归嫡长，贻厥在名卿。
隼击须当要，鹏抟莫问程。
趋朝排玉座，出位泣金茎。
幸藉梁园赋，叨蒙许氏评。
中郎推贵壻，定远重时英。
政已标三尚，人今伫一鸣。
长刀悬月魄，快马骇星精。
披豁惭深眷，暌离动素诚。
蕙留春晼晚，松待岁峥嵘。
异县期回雁，登时已饭鲭。
去程风刺刺，别夜漏丁丁。
庾信生多感，杨朱死有情。
弦危中妇瑟，甲冷想夫筝。
会与秦楼凤，俱听汉苑鸎。
洛川迷曲沼，烟月两心倾。','',''),('quantangshi-29859','咏怀寄秘阁旧僚二十六韵','李商隱','quantangshi','','卷30','年鬓日堪悲，衡茅益自嗤。
攻文枯若木，处世钝如锤。
敢忘垂堂戒，宁将暗室欺。
悬头曾苦学，折臂反成医。
仆御嫌夫懦，孩童笑叔痴。
小男方嗜栗，幼女漫忧葵。
遇炙谁先噉，逢韲即便吹。
官衔同画饼，面貎乏凝脂。
典籍将蠡测，文章若管窥。
图形翻类狗，入梦肯非罴。
自哂成书簏，终当呪酒巵。
懒霑襟上血，羞镊镜中丝。
槖龠言方喻，樗蒱齿讵知。
事神徒惕虑，佞佛愧虚辞。
曲艺垂麟角，浮名状虎皮。
乘轩宁见宠，巢幕更逢危。
礼俗拘嵇喜，侯王忻戴逵。
途穷方结舌，静胜但搘颐。
粝食空弹劒，亨衢讵置锥。
栢台成口号，芸阁暂肩随。
悔逐迁鸎伴，谁观择虱时。
瓮间眠太率，牀下隐何卑。
奋迹登弘阁，摧心对董帷。
校雠如有暇，松竹一相思。','',''),('quantangshi-29860','戊辰会静中出贻同志二十韵','李商隱','quantangshi','','卷30','大道谅无外，会越自登真。
丹元子何索，在己莫问隣。
蒨璨玉琳华，翶翔九真君。
戏掷万里火，聊召六甲旬。
瑶简被灵诰，持符开七门。
金铃摄羣魔，绛节何兟兟。
吟弄东海若，笑倚扶桑春。
三山诚迥视，九州扬一尘。
我本玄元胄，禀华由上津。
中迷鬼道乐，沈为下土民。
托质属太阴，炼形复为人。
誓将覆宫泽，安此真与神。
龟山有慰荐，南真为弥纶。
玉管会玄圃，火枣承天姻。
科车遏故气，侍香传灵氛。
飘颻被青霓，婀娜佩紫纹。
林洞何其微，下仙不与羣。
丹泥因未控，万劫犹逡巡。
荆芜既以剃，舟壑永无湮。
相期保妙命，腾景侍帝宸。','',''),('quantangshi-29861','和郑愚赠汝阳王孙家筝妓二十韵','李商隱','quantangshi','','卷30','冰雾怨何穷，秦丝娇未已。
寒空烟霞高，白日一万里。
碧嶂愁不行，浓翠遥相倚。
茜袖捧琼姿，皎日丹霞起。
孤猿耿幽寂，西风吹白芷。
回首苍梧深，女萝闭山鬼。
荒郊白鳞断，别浦晴霞委。
长彴压河心，白道连地尾。
秦人昔富家，绿窗闻妙旨。
鸿惊雁背飞，象牀殊故里。
因令五十丝，中道分宫征。
斗粟配新声，娣侄徒纤指。
风流大堤上，怅望白门里。
蠹粉实雌弦，灯光冷如水。
羌管促蛮柱，从醉吴宫耳。
满内不埽眉，君王对西子。
初花惨朝露，冷臂凄愁髓。
一曲送连钱，远别长于死。
玉砌衔红兰，妆窗结碧绮。
九门十二关，清晨禁桃李。','',''),('quantangshi-29862','四年冬以退居蒲之永乐渴然有农夫望岁之志遂作忆雪又作残雪诗各一百言以寄情于游旧 忆雪','李商隱','quantangshi','','卷30','爱景人方乐，同云候稍愆。
徒闻周雅什，愿赋朔风篇。
欲俟千箱庆，须资六出妍。
咏留飞絮后，歌唱落梅前。
庭树思琼蕊，妆楼认粉绵。
瑞邀盈尺日，丰待两岐年。
预约延枚酒，虚乘访戴船。
映书孤志业，披氅阻神仙。
几向霜阶步，频将月幌褰。
玉京应已足，白屋但颙然。','',''),('quantangshi-29863','四年冬以退居蒲之永乐渴然有农夫望岁之志遂作忆雪又作残雪诗各一百言以寄情于游旧 残雪','李商隱','quantangshi','','卷30','旭日开晴色，寒空失素尘。
遶墙全剥粉，傍井渐消银。
刻兽摧盐虎，为山倒玉人。
珠还犹照魏，璧碎尚留秦。
落日惊侵画，余光悞惜春。
檐冰滴鹅管，屋瓦镂鱼鳞。
岭霁岚光坼，松暄翠粒新。
拥林愁拂尽，着砌恐行频。
焦寝忻无患，梁园去有因。
莫能知帝力，空此荷平均。','',''),('quantangshi-29864','大卤平后移家到永乐县居书怀十韵寄刘韦二前辈二公尝于此县寄居','李商隱','quantangshi','','卷30','驱马遶河干，家山照露寒。
依然五柳在，况值百花残。
昔去惊投笔，今来分挂冠。
不忧悬磬乏，乍喜覆盂安。
甑破宁回顾，舟沈岂暇看。
脱身离虎口，移疾就猪肝。
鬓入新年白，颜无旧日丹。
自悲秋获少，谁惧夏畦难。
逸志忘鸿鹄，清香披蕙兰。
还持一杯酒，坐想二公懽。','',''),('quantangshi-29865','河阳诗','李商隱','quantangshi','','卷30','黄河摇溶天上来，玉楼影近中天台。
龙头泻酒客寿杯，主人浅笶红玫瑰。
梓泽东来七十里，长沟复堑埋云子。
可惜秋眸一脔光，汉陵走马黄尘起。
南浦老鱼腥古涎，真珠密字芙蓉篇。
湘中寄到梦不到，衰容自去抛凉天。
忆得蛟丝裁小卓，蛱蝶飞回木绵薄。
绿繍笙囊不见人，一口红霞夜深嚼。
幽兰泣露新香死，画图浅缥松溪水。
楚丝微觉竹枝高，半曲新辞写緜纸。
巴西夜市红守宫，后房点臂斑斑红。
堤南渴雁自飞久，芦花一夜吹西风。
晓帘串断蜻蜓翼，罗屏但有空青色。
玉湾不钓三千年，莲房暗被蛟龙惜。
湿银注镜井口平，鸾钗映月寒铮铮。
不知桂树在何处，仙人不下双金茎。
百尺相风插重屋，侧近嫣红伴柔绿。
百劳不识对月郎，湘竹千条为一束。','',''),('quantangshi-29866','自桂林奉使江陵途中感怀寄献尚书','李商隱','quantangshi','','卷30','下客依莲幕，明公念竹林。
纵然膺使命，何以奉徽音。
投刺虽伤晚，酬恩岂在今。
迎来新琐闼，从到碧瑶岑。
水势初知海，天文始识参。
固惭非贾谊，惟恐后陈琳。
前席惊虚辱，华樽许细斟。
尚怜秦痔苦，不遣楚醪沈。
既载从戎笔，仍披选胜襟。
泷通伏波柱，帘对有虞琴。
宅与严城接，门藏别岫深。
阁凉松冉冉，堂静桂森森。
社内容周续，乡中保展禽。
白衣居士访，乌帽逸人寻。
佞佛将成传，耽书或类淫。
长怀五羖赎，终着九州箴。
良讯封鸳绮，余光借玳簪。
张衡愁浩浩，沈约瘦愔愔。
芦白疑粘鬓，枫丹欲照心。
归期无雁报，旅抱有猿侵。
短日安能驻，低云只有阴。
乱鸦冲晒网，寒女簇遥砧。
东道违宁久，西园望不禁。
江生魂黯黯，泉客泪涔涔。
逸翰应藏法，高辞肯浪吟。
数须传庾翼，莫独与卢谌。
假寐凭书簏，哀吟叩劒镡。
未尝贪偃息，那复议登临。
彼美回清镜，其谁受曲针。
人皆向燕路，无乃费黄金。','',''),('quantangshi-29867','送从翁从东川弘农尚书幕','李商隱','quantangshi','','卷30','大镇初更帅，嘉宾素见邀。
使车无远近，归路更烟霄。
稳放骅骝步，高安翡翠巢。
御风知有在，去国肯无聊。
早忝诸孙末，俱从小隐招。
心悬紫云阁，梦断赤城标。
素女悲清瑟，秦娥弄玉箫。
山连玄圃近，水接绛河遥。
岂意闻周铎，翻然慕舜韶。
皆辞乔木去，远逐断蓬飘。
薄俗谁其激，斯民已甚恌。
鸾皇期一举，燕雀不相饶。
敢共頽波远，因之内火烧。
是非过别梦，时节惨惊飙。
未至谁能赋，中干欲病痟。
屡曾纡锦繍，勉欲报琼瑶。
我恐霜侵鬓，君先绶挂腰。
甘心与陈阮，挥手谢松乔。
锦里差隣接，云台闭寂寥。
一川虚月魄，万崦自芝苗。
瘴雨泷间急，离魂峡外销。
非关无烛夜，其奈落花朝。
几处逢鸣佩，何筵不翠翘。
蛮童骑象舞，江市卖鲛绡。
南诏知非敌，西山亦屡骄。
勿贪佳丽地，不为圣明朝。
少减东城饮，时看北斗杓。
莫因乖别久，遂逐岁寒凋。
盛幕开高宴，将军问故僚。
为言公玉季，早日弃渔樵。','',''),('quantangshi-29868','李肱所遗画松诗书两纸得四十韵','李商隱','quantangshi','','卷30','万草已凉露，开图披古松。
青山徧沧海，此树生何峰。
孤根邈无倚，直立撑鸿蒙。
端如君子身，挺若壮士胸。
樛枝势夭矫，忽欲蟠拏空。
又如惊螭走，默与奔云逢。
孙枝擢细叶，旖旎狐裘茸。
邹颠蓐髪软，丽姬眉黛浓。
视久眩目睛，倏忽变辉容。
竦削正稠直，婀娜旋敷峰。
又如洞房冷，翠被张穹笼。
亦若暨罗女，平旦妆颜容。
细疑袭气母，猛若争神功。
燕雀固寂寂，雾露常冲冲。
香兰愧伤暮，碧竹惭空中。
可集呈瑞凤，堪藏行雨龙。
淮山桂偃蹇，蜀郡桑重童。
枝条亮眇脆，灵气何由同。
昔闻咸阳帝，近说稽山侬。
或着仙人号，或以大夫封。
终南与清都，烟雨遥相通。
安知夜夜意，不起西南风。
美人昔清兴，重之犹月钟。
宝笥十八九，香缇千万重。
一旦鬼瞰室，稠叠张羉罿。
赤羽中要害，是非皆怱怱。
生如碧海月，死践霜郊蓬。
平生握中玩，散失随奴童。
我闻照妖镜，及与神劒锋。
寓身会有地，不为凡物蒙。
伊人秉蕬图，顾眄择所从。
而我何为者，开颜捧灵踪。
报以漆鸣琴，悬之真珠栊。
是时方暑夏，座内若严冬。
忆昔谢四骑，学仙玉阳东。
千株尽若此，路入琼瑶宫。
口咏玄云歌，手把金芙蓉。
浓蔼深霓袖，色映琅玕中。
悲哉堕世网，去之若遗弓。
形魄天坛上，海日高曈曈。
终骑紫鸾归，持寄扶桑翁。','',''),('quantangshi-29869','戏题枢言草阁三十二韵','李商隱','quantangshi','','卷30','君家在河北，我家在山西。
百岁本无业，阴阴仙李枝。
尚书文与武，战罢幕府开。
君从渭南至，我自仙游来。
平昔苦南北，动成云雨乖。
逮今两携手，对若牀下鞵。
夜归碣石馆，朝上黄金台。
我有苦寒调，君抱阳春才。
年颜各少壮，髪绿齿尚齐。
我虽不能饮，君时醉如泥。
政静筹画简，退食多相携。
埽掠走马路，整顿射雉翳。
春风二三月，柳密莺正啼。
清河在门外，上与浮云齐。
欹冠调玉琴，弹作松风哀。
又弹明君怨，一去怨不回。
感激坐者泣，起视雁行低。
翻忧龙山雪，却杂胡沙飞。
仲容铜琵琶，项直声凄凄。
上贴金捍拨，画为承露鸡。
君时卧掁触，劝客白玉杯。
苦云年光疾，不饮将安归。
我赏此言是，因循未能谐。
君言中圣人，坐卧莫我违。
楡荚乱不整，杨花飞相随。
上有白日照，下有东风吹。
青楼有美人，颜色如玫瑰。
歌声入青云，所痛无良媒。
少年苦不久，顾慕良难哉。
徒令真珠肶，裛入珊瑚腮。
君今且少安，听我苦吟诗。
古诗何人作，老大从伤悲。','',''),('quantangshi-29870','偶成转韵七十二句赠四同舍','李商隱','quantangshi','','卷30','沛国东风吹大泽，蒲青柳碧春一色。
我来不见隆准人，沥酒空余庙中客。
征东同舍鸳与鸾，酒酣劝我悬征鞍。
蓝山宝肆不可入，玉中仍是青琅玕。
武威将军使中侠，少年箭道惊杨叶。
战功高后数文章，怜我秋斋梦蝴蝶。
诘旦九门传奏章，高车大马来煌煌。
路逢邹枚不暇揖，腊月大雪过大梁。
忆昔公为会昌宰，我时入谒虚怀待。
众中赏我赋高唐，回看屈宋由年辈。
公事武皇为铁冠，历厅请我相所难。
我时顦顇在书阁，卧枕芸香春夜阑。
明年赴辟下昭桂，东郊恸哭辞兄弟。
韩公堆上跋马时，廻望秦川树如荠。
依稀南指阳台云，鲤鱼食鈎猿失羣。
湘妃庙下已春尽，虞帝城前初日曛。
谢游桥上澄江馆，下望山城如一弹。
鹧鸪声苦晓惊眠，朱槿花娇晚相伴。
顷之失职辞南风，破帆坏桨荆江中。
斩蛟断璧不无意，平生自许非忩忩。
归来寂寞灵台下，着破蓝衫出无马。
天官补吏府中趋，玉骨瘦来无一把。
手封狴牢屯制囚，直厅印锁黄昏愁。
平明赤帖使修表，上贺嫖姚收贼州。
旧山万仞青霞外，望见扶桑出东海。
爱君忧国去未能，白道青松了然在。
此时闻有燕昭台，挺身东望心眼开。
且吟王粲从军乐，不赋渊明归去来。
彭门十万皆雄勇，首戴公恩若山重。
廷评日下握灵蛇，书记眠时吞彩凤。
之子夫君郑与裴，何甥谢舅当世才。
青袍白简风流极，碧沼红莲倾倒开。
我生麤疎不足数，梁父哀吟鸲鹆舞。
横行阔视倚公怜，狂来笔力如牛弩。
借酒祝公千万年，吾徒礼分常周旋。
收旗卧鼓相天子，相门出相光青史。','',''),('quantangshi-29871','五言述德抒情诗一首四十韵献上杜七兄仆射相公','李商隱','quantangshi','','卷30','帝作黄金阙，仙开白玉京。
有人扶太极，惟岳降元精。
耿贾官勋大，荀陈地望清。
旗常悬祖德，甲令着嘉声。
经出宣尼壁，书留晏子楹。
武乡传陈法，践土主文盟。
自昔流王泽，由来仗国桢。
九河分合沓，一柱忽峥嵘。
得主劳三顾，惊人肯再鸣。
碧虚天共转，黄道日同行。
后饮曹参酒，先和傅说羹。
即时贤路辟，此夜泰阶平。
愿保无疆福，将图不朽名。
率身期济世，叩额虑兴兵。
感念肴尸露，咨嗟赵卒坑。
傥令安隐忍，何以赞贞明。
恶草虽当路，寒松实挺生。
人言真可畏，公意本无争。
故事留台阁，前驱且斾旌。
芙蓉王俭府，杨柳亚夫营。
清啸频疎俗，高谈屡析酲。
过庭多令子，乞墅有名甥。
南诏应闻命，西山莫敢惊。
寄辞收的博，端坐扫欃枪。
雅宴初无倦，长歌底有情。
槛危春水暖，楼迥雪峰晴。
移席牵缃蔓，回桡扑绛英。
谁知杜武库，只见谢宣城。
有客趋高义，于今滞下卿。
登门惭后至，置驿恐虚迎。
自是依刘表，安能比老彭。
雕龙心己切，画虎意何成。
岂有曾黔突，徒劳不倚衡。
乘时乖巧宦，占象合艰贞。
废忘淹中学，迟回谷口耕。
悼伤潘岳重，树立马迁轻。
陇鸟悲丹觜，湘兰怨紫茎。
归期过旧岁，旅梦遶残更。
弱植叨华族，衰门倚外兄。
欲陈劳者曲，未唱泪先横。','',''),('quantangshi-29872','今月二日不自量度辄以诗一首四十韵干凟尊严伏蒙仁恩俯赐披览奖逾其实情溢于辞顾惟疎芜曷用酬戴辄复五言四十韵诗献上亦诗人咏叹不足之义也','李商隱','quantangshi','','卷30','家擅无双誉，朝居第一功。
四时当首夏，八节应条风。
涤濯临清济，巉岩倚碧嵩。
鲍壶冰皎洁，王佩玉丁东。
处剧张京兆，通经戴侍中。
将星临迥夜，卿月丽层穹。
下令销秦盗，高谈破宋聋。
含霜太山竹，拂雾峄阳桐。
乐道干知退，当官蹇匪躬。
服箱青海马，入兆渭川熊。
固是符真宰，徒劳让化工。
凤池春潋艳，鸡树晓曈昽。
愿守三章约，还期九译通。
薰琴调大舜，宝瑟和神农。
慷慨资元老，周旋值狡童。
仲尼羞问阵，魏绛喜和戎。
欵欵将除蠧，孜孜欲达聪。
所求因渭浊，安肯与雷同。
物议将调鼎，君恩忽赐弓。
开吴相上下，全蜀占西东。
锐卒鱼悬饵，豪胥鸟在笼。
疲民呼杜母，隣国仰羊公。
置驿推东道，安禅合北宗。
嘉宾增重价，上士悟真空。
扇举遮王导，樽开见孔融。
烟飞愁舞罢，尘定惜歌终。
岸柳兼池绿，园花映烛红。
未曾周顗醉，转觉季之恭。
系滞喧人望，便蕃属圣衷。
天书何日降，庭燎几时烘。
早岁乖投刺，今晨幸发蒙。
远途哀跛鼈，薄艺奖雕虫。
故事曾尊隗，前修有荐雄。
终须烦刻画，聊拟更磨礲。
蛮岭晴留雪，巴江晚带枫。
营巢怜越燕，裂帛待燕鸿。
自苦诚先檗，长飘不后蓬。
容华虽少健，思绪即悲翁。
感激淮山馆，优游碣石宫。
待公三入相，丕祚始无穷。','',''),('quantangshi-29873','骄儿诗','李商隱','quantangshi','','卷30','衮师我骄儿，美秀乃无匹。
文葆未周晬，固已知六七。
四岁知名姓，眼不视棃栗。
交朋颇窥观，谓是丹穴物。
前朝尚器貌，流品方第一。
不然神仙姿，不尔燕鹤骨。
安得此相谓，欲慰衰朽质。
青春妍和月，朋戏浑甥侄。
绕堂复穿林，沸若金鼎溢。
门有长者来，造次请先出。
客前问所须，含意下吐实。
归来学客面，䦱败秉爷笏。
或谑张飞胡，或笑邓艾吃。
豪鹰毛崱屴，猛马气佶傈。
截得青篔簹，骑走恣唐突。
忽复学参军，按声唤苍鹘。
又复纱灯旁，稽首礼夜佛。
仰鞭罥蛛网，俯首饮花蜜。
欲争蛱蝶轻，未谢柳絮疾。
阶前逢阿姊，六甲颇输失。
凝走弄香奁，拔脱金屈[戌]。
抱持多反侧，威怒不可律。
曲躬牵牕网，衉唾拭琴漆。
有时看临书，挺立不动膝。
古锦请裁衣，玉轴亦欲乞。
请爷书春胜，春胜宜春日。
芭蕉斜卷笺，辛夷低过笔。
爷昔好读书，恳苦自着述。
顦顇欲四十，无肉畏蚤虱。
儿慎勿学爷，读书求甲乙。
穰苴司马法，张良黄石术。
便为帝王师，不假更纤悉。
况今西与北，羌戎正狂悖。
诛赦两未成，将养如痼疾。
儿当速成大，探雏入虎穴。
当为万户侯，勿守一经帙。','',''),('quantangshi-29874','行次西郊作一百韵','李商隱','quantangshi','','卷30','蛇年建午月，我自梁还秦。
南下大散关，北济渭之滨。
草木半舒坼，不类冰雪晨。
又若夏苦热，燋卷无芳津。
高田长檞枥，下田长荆榛。
农具弃道旁，饥牛死空墩。
依依过村落，十室无一存。
存者皆面啼，无衣可迎宾。
始若畏人问，及门还具陈。
右辅田畴薄，斯民常苦贫。
伊昔称乐土，所赖牧伯仁。
官清若冰玉，吏善如六亲。
生儿不远征，生女事四隣。
浊酒盈瓦缶，烂谷堆荆囷。
健儿庇旁妇，衰翁舐童孙。
况自贞观后，命官多儒臣。
例以贤牧伯，征人司陶钧。
降及开元中，奸邪挠经纶。
晋公忌此事，多録边将勋。
因令猛毅辈，杂牧升平民。
中原遂多故，除授非至尊。
或出幸臣辈，或由帝戚恩。
中原困屠解，奴隶厌肥豚。
皇子弃不乳，椒房抱羌浑。
重赐竭中国，强兵临北边。
控弦二十万，长臂皆如猿。
皇都三千里，来往同雕鸢。
五里一换马，十里一开筵。
指顾动白日，暖热回苍旻。
公卿辱嘲叱，唾弃如粪丸。
大朝会万方，天子正临轩。
彩旗转初旭，玉座当祥烟。
金障既特设，珠帘亦高褰。
捋须蹇不顾，坐在御榻前。
忤者死艰屦，附之升顶颠。
华侈矜递炫，豪俊相并吞。
因失生惠养，渐见征求频。
奚寇西北来，挥霍如天翻。
是时正忘战，重兵多在边。
列城遶长河，平明插旗幡。
但闻虏骑入，不见汉兵屯。
大妇抱儿哭，小妇攀车轓。
生小太平年，不识夜闭门。
少壮尽点行，疲老守空村。
生分作死誓，挥泪连秋云。
廷臣例麞怯，诸将如羸奔。
为贼扫上阳，捉人送潼关。
玉辇望南斗，未知何日旋。
诚知开辟久，遘此云雷屯。
送者问鼎大，存者要高官。
抢攘互间谍，孰辨枭与鸾。
千马无返辔，万车无还辕。
城空鼠雀死，人去豺狼喧。
南资竭吴越，西费失河源。
因令左藏库，摧毁惟空垣。
如人当一身，有左无右边。
筋体半痿痹，肘腋生臊膻。
列圣蒙此耻，含怀不能宣。
谋臣拱手立，相戒无敢先。
万国困杼轴，内库无金钱。
健儿立霜雪，腹歉衣裳单。
馈饷多过时，高估铜与铅。
山东望河北，爨烟犹相联。
朝廷不暇给，辛苦无半年。
行人搉行资，居者税屋椽。
中间遂作梗，狼籍用戈鋋。
临门送节制，以锡通天班。
破者以族灭，存者尚迁延。
礼数异君父，羁糜如羌零。
直求输赤诚，所望大体全。
巍巍政事堂，宰相厌八珍。
敢问下执事，今谁掌其权。
疮疽几十载，不敢扶其根。
国蹙赋更重，人稀役弥繁。
近年牛医儿，城社更扳援。
盲目把大斾，处此京西藩。
乐祸忘怨敌，树党多狂狷。
生为人所惮，死非人所怜。
快刀断其头，列若猪牛悬。
凤翔三百里，兵马如黄巾。
夜半军牒来，屯兵万五千。
乡里骇供亿，老少相扳牵。
儿孙生未孩，弃之无惨颜。
不复议所适，但欲死山间。
尔来又三岁，甘泽不及春。
盗贼亭午起，问谁多穷民。
节使杀亭吏，捕之恐无因。
咫尺不相见，旱久多黄尘。
官健腰佩弓，自言为官巡。
常恐值荒迥，此辈还射人。
愧客问本末，愿客无因循。
郿坞抵陈仓，此地忌黄昏。
我听此言罢，冤愤如相焚。
昔闻举一会，羣盗为之奔。
又闻理与乱，在人不在天。
我愿为此事，君前剖心肝。
叩头出鲜血，滂沱污紫宸。
九重黯已隔，涕泗空沾唇。
使典作尚书，厮养为将军。
慎勿道此言，此言未忍闻。','',''),('quantangshi-29875','井泥四十韵','李商隱','quantangshi','','卷30','皇都依仁里，西北有高斋。
昨日主人氏，治井堂西陲。
工人三五辈，辇出土与泥。
到水不数尺，积共庭树齐。
他日井甃毕，用土益作堤。
曲随林掩映，缭以池周回。
下去冥寞穴，上承雨露滋。
寄辞别地脉，因言谢泉扉。
升腾不自意，畴昔忽已乖。
伊余掉行鞅，行行来自西。
一日下马到，此时芳草萋。
四面多好树，旦暮云霞姿。
晚落花满地，幽鸟鸣何枝。
萝幄既已荐，山樽亦可开。
待得孤月上，如与佳人来。
因兹感物理，恻怆平生怀。
茫茫此羣品，不定轮与蹄。
喜得舜可禅，不以瞽瞍疑。
禹竟代舜立，其父吁咈哉。
嬴氏并六合，所来因不韦。
汉祖把左契，自言一布衣。
当涂佩国玺，本乃黄门携。
长戟乱中原，何妨起戎氐。
不独帝王耳，臣下亦如斯。
伊尹佐兴王，不藉汉父资。
蟠溪老钓叟，坐为周之师。
屠狗兴贩缯，突起定倾危。
长沙启封土，岂是出程姬。
帝问主人翁，有自卖珠儿。
武昌昔男子，老苦为人妻。
蜀王有遗魄，今在林中啼。
淮南鸡舐药，翻向云中飞。
大钧运羣有，难以一理推。
顾于冥冥内，为问秉者谁。
我恐更万世，此事愈云为。
猛虎与双翅，更以角副之。
凤凰不五色，联翼上鸡栖。
我欲秉钧者，朅来与我偕。
浮云不相顾，寥泬谁为梯。
悒怏夜将半，但歌井中泥。','',''),('quantangshi-29876','夜思','李商隱','quantangshi','','卷30','银箭耿寒漏，金釭凝夜光。
彩鸾空自舞，别燕不相将。
寄恨一尺素，含情双玉璫。
会前犹月在，去后始宵长。
往事经春物，前期托报章。
永令虚粲枕，长不掩兰房。
觉动迎猜影，疑来浪认香。
鹤应闻露警，蜂亦为花忙。
古有阳台梦，今多下蔡倡。
何为薄冰雪，消瘦滞非乡。','',''),('quantangshi-29877','思贤顿','李商隱','quantangshi','','卷30','内殿张弦管，中原绝鼓鼙。
舞成青海马，鬬杀汝南鸡。
不见华胥梦，空闻下蔡迷。
宸襟他日泪，薄暮望贤西。','',''),('quantangshi-29878','无题','李商隱','quantangshi','','卷30','万里风波一叶舟，忆归初罢更夷犹。
碧江地没元相引，黄鹤沙边亦少留。
益德冤魂终报主，阿童高义镇横秋。
人生岂得长无谓，怀古思乡共白头。','',''),('quantangshi-29879','有怀在蒙飞卿','李商隱','quantangshi','','卷30','薄宦频移疾，当年久索居。
哀同庚开府，瘦极沈尚书。
城绿新阴远，江清返照虚。
所思惟翰墨，从古待双鱼。','',''),('quantangshi-29880','春深脱衣','李商隱','quantangshi','','卷30','睥睨江鸦集，堂皇海燕过。
减衣怜蕙若，展帐动烟波。
日烈忧花甚，风长奈柳何。
陈遵容易学，身世醉时多。','',''),('quantangshi-29881','怀求古翁','李商隱','quantangshi','','卷30','何时粉署仙，傲兀逐戎旃。
关塞犹传箭，江湖莫系船。
欲收棊子醉，竟把钓车眠。
谢朓真堪忆，多才不忌前。','',''),('quantangshi-29882','五月六日夜忆往岁秋与彻师同宿','李商隱','quantangshi','','卷30','紫阁相逢处，丹岩议宿时。
堕蝉翻败叶，栖鸟定寒枝。
万里飘流远，三年问讯迟。
炎方忆初地，频梦碧琉璃。','',''),('quantangshi-29883','城上','李商隱','quantangshi','','卷30','有客虚投笔，无憀独上城。
沙禽失侣远，江树着阴轻。
边遽稽天讨，军须竭地征。
贾生游刃极，作赋又论兵。','',''),('quantangshi-29884','如有','李商隱','quantangshi','','卷30','如有瑶台客，相难复索归。
芭蕉开绿扇，菡萏荐红衣。
浦外传光远，烟中结响微。
良宵一寸焰，回首是重帏。','',''),('quantangshi-29885','朱槿花二首 一','李商隱','quantangshi','','卷30','莲后红何患，梅先白莫夸。
才飞建章火，又落赤城霞。
不卷锦步障，未登油壁车。
日西相对罢，休澣向天涯。','',''),('quantangshi-29886','朱槿花二首 二','李商隱','quantangshi','','卷30','勇多侵路去，恨有碍灯还。
嗅自微微白，看成沓沓殷。
坐疑忘物外，归去有帘间。
君问伤春句，千辞不可删。','',''),('quantangshi-29887','寓怀','李商隱','quantangshi','','卷30','彩鸾餐颢气，威凤入卿云。
长养三清境，追随五帝君。
烟波遗汲汲，矰缴任云云。
下界围黄道，前程合紫氛。
金书惟是见，玉管不胜闻。
草为回生种，香缘却死熏。
海明三岛见，天迥九江分。
搴树无劳援，神禾岂用耘。
鬬龙风结阵，恼鹤露成文。
汉岭霜何早，秦宫日易曛。
星机抛密绪，月杵散灵氛。
阳鸟西南下，相思不及羣。','',''),('quantangshi-29888','木兰','李商隱','quantangshi','','卷30','二月二十二，木兰开坼初。
初当新病酒，复自久离居。
愁绝更倾国，惊新闻远书。
紫丝何日障，油壁几时车。
弄粉知伤重，调红或有余。
波痕空映袜，烟态不胜裾。
桂岭含芳远，莲塘属意疎。
瑶姬与神女，长短定何如。','',''),('quantangshi-29889','细雨成咏献尚书河东公','李商隱','quantangshi','','卷30','洒砌听来响，卷帘看已迷。
江间风暂定，云外日应西。
稍稍落蝶粉，班班融燕泥。
颭萍初过沼，重柳更缘堤。
必拟和残漏，宁无晦暝鼙。
半将花漠漠，全共草萋萋。
猿别方长啸，鸟惊始独栖。
府公能八咏，聊且续新题。','',''),('quantangshi-29890','病中闻河东公乐营置酒口占寄上','李商隱','quantangshi','','卷30','闻驻行春斾，中途赏物华。
缘忧武昌柳，遂忆洛阳花。
嵇鹤元无对，荀龙不在夸。
只将沧海月，长压赤城霞。
兴欲倾燕馆，欢终到习家。
风长应侧帽，路隘岂容车。
楼迥波窥锦，窗虚日弄纱。
锁门金了鸟，展障玉鸦叉。
舞妙从兼楚，歌能莫杂巴。
必投潘岳果，谁掺禰衡挝。
刻烛当时忝，传杯此夕赊。
可怜漳浦卧，愁绪独如麻。','',''),('quantangshi-29891','回中牡丹为雨所败二首 一','李商隱','quantangshi','','卷30','下苑他年未可追，西州今日忽相期。
水亭暮雨寒犹在，罗荐春香暖不知。
舞蝶殷勤收落蘂，佳人惆怅卧遥帷。
章台街里芳菲伴，且问宫腰损几枝。','',''),('quantangshi-29892','回中牡丹为雨所败二首 二','李商隱','quantangshi','','卷30','浪笑榴花不及春，先期零落更愁人。
玉盘迸泪伤心数，锦瑟惊弦破梦频。
万里重阴非旧圃，一年生意属流尘。
前溪舞罢君回顾，并觉今朝粉态新。','',''),('quantangshi-29893','拟意','李商隱','quantangshi','','卷30','怅望逢张女，迟回送阿侯。
空看小垂手，忍问大刀头。
妙选茱萸帐，平居翡翠楼。
云屏不取暖，月扇未遮羞。
上掌真何有，倾城岂自由。
楚妃交荐枕，汉后共藏𩰘。
夫向羊车觅，男从凤穴求。
书成祓禊帖，唱杀畔牢愁。
夜杵鸣江练，春刀解若榴。
象牀穿幰网，犀帖钉窗油。
仁寿遗明镜，陈仓拂彩球。
真防舞如意，佯盖卧箜篌。
濯锦桃花水，溅裙杜若洲。
鱼儿悬宝劒，燕子合金瓯。
银箭催摇落，华筵惨去留。
几时销薄怒，从此抱离忧。
帆落啼猿峡，樽开画鷁舟。
急弦肠对断，翦蜡泪争流。
璧马谁能带，金虫不复收。
银河扑醉眼，珠串咽歌喉。
去梦随川后，来风贮石邮。
兰丛衔露重，榆荚点星稠。
解佩无遗迹，凌波有旧游。
曾来十九首，私谶咏牵牛。','',''),('quantangshi-29894','谢往桂林至彤庭窃咏','李商隱','quantangshi','','卷30','辰象森罗正，句陈翊卫宽。
鱼龙排百戏，剑佩俨千官。
城禁将开晚，宫深欲曙难。
月输移枍诣，仙路下栏干。
共贺高禖应，将陈寿酒欢。
金星压芒角，银汉转波澜。
王母来空阔，羲和上屈盘。
凤皇传诏旨，獬廌冠朝端。
造化中台座，威风上将坛。
甘泉犹望幸，早晚冠呼韩。','',''),('quantangshi-29895','烧香曲','李商隱','quantangshi','','卷30','钿云蟠蟠牙比鱼，孔雀翅尾蛟龙须。
漳宫旧样博山炉，楚娇捧笑开芙蕖。
八蚕茧緜小分炷，兽焰微红隔云母。
白天月泽寒未冰，金虎含秋向东吐。
玉佩呵光铜照昏，帘波日暮冲斜门。
西来欲上茂陵树，柏梁已失栽桃魂。
露庭月井大红气，轻衫薄细当君意。
蜀殿琼人伴夜深，金銮不问残灯事。
何当巧吹君怀度，襟灰为土填清露。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-29896','送从翁东川弘农尚书幕','李商隱','quantangshi','','卷30','昔帝回冲眷，维皇恻上仁。
三灵迷赤气，万汇呌苍旻。
刊木方隆禹，升陑始创殷。
夏台曾圮闭，汜水敢逡巡。
拯溺休规步，防虞要徙薪。
蒸黎今得请，宇宙昨还淳。
缵祖功宜急，贻孙计甚勤。
降灾虽代有，稔恶不无因。
宫掖方为蛊，边隅忽遘迍。
献书秦逐客，间谍汉名臣。
北伐将谁使，南征决此辰。
中原重板荡，玄象失钩陈。
诘旦违清道，衔枚别紫宸。
兹行殊厌胜，故老遂分新。
去异封于巩，来宁避处豳。
永嘉几失坠，宣政遽酸辛。
元子当传启，皇孙合授询。
时非三揖让，表请再陶钧。
旧好盟还在，中枢策屡遵。
苍黄传国玺，违远属车尘。
雏虎如凭怒，漦龙性漫驯。
封崇自何等，流落乃斯民。
逗挠官军乱，优容败将频。
早朝披草莽，夜缒达丝纶。
忘战追无及，长驱气益振。
妇言终未易，庙算况非神。
日驭难淹蜀，星旄要定秦。
人心诚未去，天道亦无亲。
锦水湔云浪，黄山扫地春。
斯文虚梦鸟，吾道欲悲麟。
断续殊乡泪，存亡满席珍。
魂销季羔窦，衣化子张绅。
建议庸何所，通班昔滥臻。
浮生见开泰，独得咏汀苹。','',''),('quantangshi-29897','晋昌晚归马上赠','李商隱','quantangshi','','卷30','西北朝天路，登临思上才。
城闲烟草遍，村暗雨云回。
人岂无端别，猨应有意哀。
征南予更远，吟断望乡台。','',''),('quantangshi-29898','哭虔州杨侍郎','李商隱','quantangshi','','卷30','汉网疎仍漏，齐民困未苏。
如何大丞相，翻作弛刑徒。
中宪方外易，尹京终就拘。
本矜能弭谤，先议取非辜。
巧有凝脂密，功无一柱扶。
深知狱吏贵，几迫季冬诛。
呌帝青天阔，辞家白日晡。
流亡诚不吊，神理若为诬。
在昔恩知忝，诸生礼秩殊。
入韩非劒客，过赵受钳奴。
楚水招魂远，邙山卜宅孤。
甘心亲垤蚁，旋踵戮城狐。
阴骘今如此，天灾未可无。
莫凭牲玉请，便望救焦枯。','',''),('quantangshi-29899','寄太原卢司空三十韵','李商隱','quantangshi','','卷30','隋舰临淮甸，唐旗出井陉。
断鳌搘四柱，卓马济三灵。
祖业隆盘古，孙谋复大庭。
从来师俊杰，可以焕丹青。
旧族开东岳，雄图奋北溟。
邪同獬廌触，乐伴凤凰听。
酣战仍挥日，降妖亦鬬霆。
将军功不伐，叔舅德惟馨。
鸡塞谁生事，狼烟不暂停。
拟填沧海鸟，敢竞太阳萤。
内草才传诏，前茅已勒铭。
那劳出师表，尽入大荒经。
德水萦长带，阴山绕画屏。
秖忧非綮肯，未觉有膻腥。
保佐资冲漠，扶持在杳冥。
乃心防暗室，华髪称明廷。
按甲神初静，挥戈思欲醒。
羲之当妙选，孝若近归宁。
月色来侵幌，诗成有转棂。
罗含黄菊宅，柳恽白苹汀。
神物龟酬孔，仙才鹤姓丁。
西山童子药，南极老人星。
自顷徒窥管，于今愧挈瓶。
何由叨末席，还得叩玄扃。
庄叟虚悲雁，终童漫识艇。
幕中虽策画，劒外且伶俜。
俣俣行忘止，鳏鳏卧不瞑。
身应瘠于鲁，泪欲溢为荣。
禹贡思金鼎，尧图忆土铏。
公乎来入相，王欲驾云亭。','',''),('quantangshi-29900','安平公诗','李商隱','quantangshi','','卷30','丈人博陵王名家，怜我总角称才华。
华州留语晓至暮，高声喝吏放两衙。
明朝骑马出城外，送我习业南山阿。
仲子延岳年十六，面如白玉欹乌纱。
其弟炳章犹两丱，瑶林琼树含奇花。
陈留阮家诸侄秀，逦迤出拜何骈罗。
府中从事杜与李，麟角虎翅相过摩。
清词孤韵有歌响，击触钟磬鸣环珂。
三月石堤冻销释，东风开花满阳坡。
时禽得伴戏新木，其声尖咽如鸣梭。
公时载酒领从事，踊跃鞍马来相过。
仰看楼殿撮清汉，坐视世界如恒沙。
面热脚掉互登陟，青云表柱白云崖。
一百八句在贝叶，三十三天长雨花。
长者子来辄献盖，辟支佛去空留鞾。
公时受诏镇东鲁，遣我草诏随车牙。
顾我下笔即千字，疑我读书倾五车。
呜嘑大贤苦不寿，时世方士无灵砂。
五月至止六月病，遽颓泰山惊逝波。
明年徒步吊京国，宅破子毁哀如何。
西风冲户卷素帐，隟光斜照旧燕窠。
古人常叹知己少，况我沦贱艰虞多。
如公之德世一二，岂得无泪如黄河。
沥胆咒愿天有眼，君子之泽方滂沱。','',''),('quantangshi-29901','赤壁','李商隱','quantangshi','','卷30','折戟沈沙铁未销，自将磨洗认前朝。
东风不与周郎便，铜雀春深锁二乔。','',''),('quantangshi-29902','垂柳','李商隱','quantangshi','','卷30','垂柳碧鬅茸，楼昏雨带容。
思量成夜梦，束久废春慵。
梳洗凭张敞，乘骑笑稚恭。
碧虚随转笠，红烛近高舂。
怨目明秋水，愁眉淡远峰。
小阑花尽蝶，静院醉醒蛩。
旧作琴台凤，今为药店龙。
宝匳抛掷久，一任景阳钟。','',''),('quantangshi-29903','清夜怨','李商隱','quantangshi','','卷30','含泪坐春宵，闻君欲度辽。
绿池荷叶嫩，红砌杏花娇。
曙月当窗满，征云出塞遥。
画楼终日闭，清管为谁调。','',''),('quantangshi-29904','定子','李商隱','quantangshi','','卷30','檀槽一抹广陵春，定子初开睡脸新。
却笑吃虚隋炀帝，破家亡国为何人。','',''),('quantangshi-29905','木兰花','李商隱','quantangshi','','卷30','洞庭波冷晓侵云，日日征帆送远人。
几度木兰舟上望，不知元是此花身。','',''),('quantangshi-29906','游灵伽寺','李商隱','quantangshi','','卷30','碧烟秋寺泛湖来，水打城根古堞摧。
尽日伤心人不见，石榴花满旧琴台。','',''),('quantangshi-29907','龙丘途中 一','李商隱','quantangshi','','卷30','汉苑残花别，吴江盛夏来。
惟看万树谷，不见一枝开。','',''),('quantangshi-29908','龙丘途中 二','李商隱','quantangshi','','卷30','水色饶湘浦，滩声怯建溪。
泪流回月上，可得更猨蹄。','',''),('quantangshi-29909','句','李商隱','quantangshi','','卷30','兰膏爇处心犹浅，银烛烧残焰不馨。
好向书生窗畔种，免教辛苦更囊萤。
遥想故园陌，桃李正酣酣。
头上金雀钗，腰佩翠琅玕。
芦洲客雁报春来。','',''),('quantangshi-29910','送友人归宜春','紀唐夫','quantangshi','','卷30','落花兼柳絮，无处不纷纷。
远道空归去，流莺独自闻。
墅桥喧碓水，山郭入楼云。
故里南陔曲，秋期欲送君。','',''),('quantangshi-29911','骢马曲','紀唐夫','quantangshi','','卷30','连钱出塞蹋沙蓬，岂比当时御史骢。
逐北自谙深碛路，连嘶谁念静边功。
登山每与青云合，弄影应知碧草同。
今日虏平将换妾，不如罗袖舞春风。','',''),('quantangshi-29912','送温庭筠尉方城','紀唐夫','quantangshi','','卷30','何事明时泣玉频，长安不见杏园春。
凤皇诏下虽霑命，鹦鹉才高却累身。
且尽绿醽销积恨，莫辞黄绶拂行尘。
方城若比长沙路，犹隔千山与万津。','',''),('quantangshi-29913','及第后宿平康里','裴思謙','quantangshi','','卷30','银缸斜背解鸣璫，小语偷声贺玉郎。
从此不知兰麝贵，夜来新染桂枝香。','',''),('quantangshi-29914','都堂试贡士日庆春雪','李衢','quantangshi','','卷30','锡瑞来丰岁，旌贤入贡辰。
轻摇梅共笑，飞褭柳知春。
遶砌封琼屑，依阶喷玉尘。
蜉蝣吟更古，科斗映还新。
鹤毳迷难辨，冰壶鉴易真。
因歌大君德，率舞咏陶钧。','',''),('quantangshi-29915','都堂试贡士日庆春雪','李損之','quantangshi','','卷30','春雪昼悠扬，飘飞试士场。
缀毫疑起草，霑字共成章。
匝地如铺练，凝阶似截肪。
鹅毛萦树合，柳絮带风狂。
息疫方殊庆，丰年已报祥。
应知郢上曲，高唱出东堂。','',''),('quantangshi-29916','除夜长安作','李景','quantangshi','','卷30','长安朔风起，穷巷掩双扉。
新岁明朝是，故乡何路归。
鬓丝饶镜色，隟雪夺灯辉。
却羡秦州雁，逢春尽北飞。','',''),('quantangshi-29917','都堂试贡士日庆春雪','李景','quantangshi','','卷30','密雪分天路，羣才坐粉廊。
霭空迷昼景，临宇借寒光。
似暖花消地，无声玉满堂。
洒池偏误曲，留砚忽因方。
几处曹风比，何人谢赋长。
春晖早相照，莫滞九衢芳。','',''),('quantangshi-29918','登景云寺阁','張元宗','quantangshi','','卷30','胡马饮河洛，我家从此迁。
今来独垂泪，三十六峰前。','',''),('quantangshi-29919','望终南山','張元宗','quantangshi','','卷30','红尘白日长安路，马足车轮不暂闲。
唯有茂陵多病客，每来高处望南山。','',''),('quantangshi-29920','省试霓裳羽衣曲','李肱','quantangshi','','卷30','开元太平时，万国贺丰岁。
梨园献旧曲，玉座流新制。
凤管递参差，霞衣竞摇曳。
宴罢水殿空，辇余春草细。
蓬壶事已久，仙乐功无替。
讵肯听遗音，圣明知善继。','',''),('quantangshi-29921','句','李肱','quantangshi','','卷30','水光先见月，露气早知秋。','',''),('quantangshi-29922','永州送侄归宜春','鄭史','quantangshi','','卷30','宋玉正秋悲，那堪更别离。
从来襟上泪，尽作鬓边丝。
永水清如此，袁江色可知。
到家黄菊坼，亦莫怪归迟。','',''),('quantangshi-29923','秋日零陵与幕下诸宾游河夜饮','鄭史','quantangshi','','卷30','湘月苹风乍畅襟，烛前江水练千寻。
新秋宋玉能为赋，永夕袁安好共吟。
辇下翠蛾须强展，尊中绿蚁且徐斟。
汀沙渐有珠凝露，缓棹兰桡任夜深。','',''),('quantangshi-29924','赠妓行云诗','鄭史','quantangshi','','卷30','最爱铅华薄薄妆，更兼衣着又鹅黄。
从来南国名佳丽，何事今朝在北行。','',''),('quantangshi-29925','纪梦','許瀍','quantangshi','','卷30','晓入瑶台露气清，天风飞下步虚声。
尘心未尽俗缘在，十里下山空月明。','',''),('quantangshi-29926','题朝阳岩','牛叢','quantangshi','','卷30','蹑石攀萝路不迷，晓天风好浪花低。
洞名独占朝阳号，应有梧桐待凤栖。','',''),('quantangshi-29927','咸阳有怀','陳上美','quantangshi','','卷30','山连河水碧氛氲，瑞气东移拥圣君。
秦苑有花空笑日，汉陵无主自侵云。
古槐堤上莺千啭，远渚沙中鹭一羣。
赖与渊明同把菊，烟郊西望夕阳曛。','',''),('quantangshi-29928','晴望九华山','楊鴻','quantangshi','','卷30','九华闲望簇清虚，气象羣峰尽不如。
惆怅都南挂冠吏，无人解向此山居。','',''),('quantangshi-29929','正月','趙璜','quantangshi','','卷30','正月今朝半，阳台信未回。
水芹寒不食，山杏雨应开。
世网留三宿，真源寄一杯。
因声谢猨鸟，岁[晏]会归来。','',''),('quantangshi-29930','七夕诗','趙璜','quantangshi','','卷30','乌鹊桥头双扇开，年年一度过河来。
莫嫌天上稀相见，犹胜人间去不回。
欲减烟花饶俗世，暂烦云月掩楼台。
别时旧路长清浅，岂肯离情似死灰。','',''),('quantangshi-29931','曲江上巳','趙璜','quantangshi','','卷30','长堤十里转香车，两岸烟花锦不如。
欲问神仙在何处，紫云楼阁向空虚。','',''),('quantangshi-29932','题七夕图','趙璜','quantangshi','','卷30','帝子吹箫上翠微，秋风一曲凤皇归。
明年七月重相见，依旧高悬织女机。','',''),('quantangshi-29933','登明戍堡','潘咸','quantangshi','','卷30','来经古城上，极目思无穷。
寇尽烟萝外，人归蔓草中。
峰峦当阙古，堞垒对云空。
不见昔名将，徒称有战功。','',''),('quantangshi-29934','送陈明府之任','潘咸','quantangshi','','卷30','客见天台县，闾阎树色间。
骖回几临水，带缓独开山。
吏散落花尽，人居远岛闲。
过于老莱子，端简独承颜。','',''),('quantangshi-29935','长安春暮','潘咸','quantangshi','','卷30','客在关西春暮夜，还同江外已清明。
三更独立看花月，惟欠子规啼一声。','',''),('quantangshi-29936','舟行','潘咸','quantangshi','','卷30','平沙极浦无人度，独系孤舟寒草西。
半夜起看潮上月，万山中有一猨啼。','',''),('quantangshi-29937','送僧','潘咸','quantangshi','','卷30','阙下僧归山顶寺，却看朝日下方明。
莫道野人寻不见，半天云里有钟声。','',''),('quantangshi-29938','句','潘咸','quantangshi','','卷30','栈踏猨声暮，江看剑影秋。
僧老白云上，磬寒高鸟边。
心已同猨狖，不闻人是非。
行人渡流水，白马入前山。
秋深雪满黄金塞，夜夜鸿声入汉阳。','',''),('quantangshi-29939','秋晚同友人闲步','薛瑩','quantangshi','','卷30','藉草与行莎，相看日未斜。
断崖分鸟道，疎树见人家。
望远临孤石，吟余落片霞。
野情看不足，归路思犹赊。','',''),('quantangshi-29940','宿仙都观阴王二君修道处','薛瑩','quantangshi','','卷30','十载别仙峰，峰前千古踪。
阴王修道处，云雪满高松。
洞口风雷异，池心星汉重。
明朝下山去，片月落残钟。','',''),('quantangshi-29941','宿东岩寺晓起','薛瑩','quantangshi','','卷30','野寺寒塘晓，游人一梦分。
钟残数树月，僧起半岩云。
宿鸟惊初见，幽泉落不闻。
吟余凭前槛，红叶下纷纷。','',''),('quantangshi-29942','秋日湖上','薛瑩','quantangshi','','卷30','落日五湖游，烟波处处愁。
沈浮千古事，谁与问东流。','',''),('quantangshi-29943','江山闲望','薛瑩','quantangshi','','卷30','渺渺无穷尽，风涛几日平。
年光与人事，东去一声声。','',''),('quantangshi-29944','访武陵道者不遇','薛瑩','quantangshi','','卷30','花发鸟仍啼，行行路欲迷。
二真无问处，虚度武陵溪。','',''),('quantangshi-29945','寄旧山隐侣','薛瑩','quantangshi','','卷30','旧山诸隐沦，身在苦无身。
莫锁白云路，白云多悞人。','',''),('quantangshi-29946','羡僧','薛瑩','quantangshi','','卷30','处世曾无着，生前事尽非。
一瓶兼一衲，南北去如归。','',''),('quantangshi-29947','锦','薛瑩','quantangshi','','卷30','轧轧弄寒机，功多力渐微。
惟忧机上锦，不称舞人衣。','',''),('quantangshi-29948','中秋月','薛瑩','quantangshi','','卷30','三十六旬盈复缺，百年堪喜又堪伤。
劝君莫惜登楼望，云放婵娟不久长。','',''),('quantangshi-29949','句','薛瑩','quantangshi','','卷30','单棹横疎雨，江滩秋泊时。
花留身住越，月递梦还秦。','',''),('quantangshi-29950','赠毛仙翁','崔元略','quantangshi','','卷30','莫将凡圣比云泥，椿菌之年本不齐。
度世无劳大稻米，升天只用半刀圭。
人间嗟对黄昏槿，海上闲听碧落鸡。
旌节行中令引道，便从尘外踏丹梯。','',''),('quantangshi-29951','太学创置石经','馮涯','quantangshi','','卷30','圣唐复古制，德义功无替。
奥旨悦诗书，遗文分篆隶。
银钩互交映，石壁靡尘翳。
永与干坤期，不逐日月逝。
儒林道益广，学者心弥锐。
从此理化成，恩光遍遐裔。','',''),('quantangshi-29952','赠李商隐','喻鳧','quantangshi','','卷30','羽翼恣抟扶，山河使笔驱。
月疎吟夜桂，龙失咏春珠。
草细盘金勒，花繁倒玉壶。
徒嗟好章句，无力致前途。','',''),('quantangshi-29953','元日即事','喻鳧','quantangshi','','卷30','敛板贺交亲，称觞讵有巡。
年光悲掷旧，景色喜呈新。
水柳烟中重，山梅雪后真。
不知将白发，何以度青春。','',''),('quantangshi-29954','送贾岛往金州谒姚员外','喻鳧','quantangshi','','卷30','山光与水色，独往此中深。
溪沥椒花气，岩盘漆叶阴。
潇湘终共去，巫峡羡先寻。
几夕江楼月，玄晖伴静吟。','',''),('quantangshi-29955','送友人罢举归蜀','喻鳧','quantangshi','','卷30','憔悴满衣尘，风光岂属身。
卖琴红粟贵，看镜白髭新。
栈畔谁高步，巴边自问津。
凄然莫滴血，杜宇正哀春。','',''),('quantangshi-29956','送卫尉之延陵','喻鳧','quantangshi','','卷30','草木正花时，交亲触雨辞。
一官之任远，尽室出城迟。
乳滴茅君洞，鸦鸣季子祠。
想知佐理暇，日有咏怀诗。','',''),('quantangshi-29957','送越州高录事','喻鳧','quantangshi','','卷30','官曹权纪纲，行李半舟航。
浦溆潮来广，川源鸟去长。
笋成稽岭岸，莲发镜湖香。
泽国还之任，鲈鱼浪得尝。','',''),('quantangshi-29958','送潘咸','喻鳧','quantangshi','','卷30','时时赍破囊，访我息闲坊。
煮雪问茶味，当风看雁行。
心齐山鹿逸，句敌柳花狂。
坚苦今如此，前程岂渺茫。','',''),('quantangshi-29959','送友人下第归宁','喻鳧','quantangshi','','卷30','紫阁雪未尽，杏园花亦寒。
灞西辞旧友，楚外忆新安。
细雨猨啼枿，微阳鹭起滩。
旋应赴秋贡，讵得久承欢。','',''),('quantangshi-29960','游北山寺','喻鳧','quantangshi','','卷30','烟冈影畔寺，游步此时孤。
庭静众药在，鹤闲双桧枯。
蓝峰露秋院，灞水入春厨。
便可栖心迹，如何返旧途。','',''),('quantangshi-29961','冬日题无可上人院','喻鳧','quantangshi','','卷30','入户道心生，茶间踏叶行。
泻风瓶水涩，承露鹤巢轻。
阁北长河气，窗东一桧声。
诗言与禅味，语默此皆清。','',''),('quantangshi-29962','游云际寺','喻鳧','quantangshi','','卷30','涧壑吼风雷，香门绝顶开。
阁寒僧不下，钟定虎常来。
鸟啄林稍菓，鼯跳竹里苔。
心源无一事，尘界拟休回。','',''),('quantangshi-29963','题翠微寺','喻鳧','quantangshi','','卷30','沿溪又涉巅，始喜入前轩。
钟度鸟沈壑，殿扃云湿幡。
凉泉堕众石，古木彻疎猨。
月上僧阶近，斯游岂易言。','',''),('quantangshi-29964','广德官舍二松','喻鳧','quantangshi','','卷30','杨公休簿领，二木日坚牢。
直甚彰吾节，清终庇尔曹。
幽阴月里细，冷树雪中高。
谁见干霄后，枝飘白鹤毛。','',''),('quantangshi-29965','浴马','喻鳧','quantangshi','','卷30','解控复收鞭，长津动细涟。
空蹄沈绿玉，阔臆没连钱。
沫漩桥声下，嘶盘柳影边。
常闻畯龙性，固与白波便。','',''),('quantangshi-29966','和段学士南亭春日对雨','喻鳧','quantangshi','','卷30','晨飞晚未休，兰阁客吟愁。
萧飒柳边挂，萦纡花底流。
声繁乍离籁，洒急不成沤。
经夕江湖思，烟波一钓舟。','',''),('quantangshi-29967','书怀','喻鳧','quantangshi','','卷30','秖是守琴书，僧中独寓居。
心唯务鹤静，分合与名疎。
暮雨啼螿次，凉风落木初。
家山太湖渌，归去复何如。','',''),('quantangshi-29968','一公房','喻鳧','quantangshi','','卷30','幽深谁掩关，清净自多闲。
一雨收众木，孤云生远山。
花萎绿苔上，鸽乳翠楼间。
岚霭燃香夕，容听半偈还。','',''),('quantangshi-29969','晚次临泾','喻鳧','quantangshi','','卷30','路入犬羊群，城寒雉堞曛。
居人秖尚武，过客谩投文。
马怯奔浑水，雕沈莽苍云。
沙田积蒿艾，竟夕见烧焚。','',''),('quantangshi-29970','王母祠前写望','喻鳧','quantangshi','','卷30','云霞千古事，桃李旧花颜。
芳信沈青鸟，空祠掩暮山。
香传一座暗，柳匝万家闲。
那复伤神所，河昏落日间。','',''),('quantangshi-29971','游暖泉精舍','喻鳧','quantangshi','','卷30','坞木殿前空，山河泽国同。
鸟闲沙影上，泉落树阴中。
缆舸蒲花水，萦幡柳絮风。
翛然方寸地，何事更悲蓬。','',''),('quantangshi-29972','怀乡','喻鳧','quantangshi','','卷30','秋风江上家，钓艇泊芦花。
断岸绿杨荫，疎篱红槿遮。
鼍鸣积雨窟，鹤步夕阳沙。
抱疾僧窗夜，归心过月斜。','',''),('quantangshi-29973','岫禅师南溪兰若','喻鳧','quantangshi','','卷30','锡影配瓶光，孤溪照草堂。
水悬青石磴，钟动白云牀。
树色含残雨，河流带夕阳。
唯应无月夜，瞑目见他方。','',''),('quantangshi-29974','龙翔寺寄李频','喻鳧','quantangshi','','卷30','钟声南北寺，不道往来遥。
人事因循过，时光荏苒销。
悬灯洒砌雨，上阁遶云雕。
即是洲中柳，嘶蝉急暮条。','',''),('quantangshi-29975','送武瑴之邠宁','喻鳧','quantangshi','','卷30','戍路少人踪，边烟澹复浓。
诗宁写别恨，酒不上离容。
燕拂沙河柳，鵶高石窟钟。
悠然一暌阻，山叠虏云重。','',''),('quantangshi-29976','夏日题岫禅师房','喻鳧','quantangshi','','卷30','朝朝声磬罢，童子扫藤阴。
花过少游客，日长无事心。
回山闭院直，落水下桥深。
安得开方便，容身老此林。','',''),('quantangshi-29977','夏日因怀阳羡旧游寄裴书记','喻鳧','quantangshi','','卷30','落日太湖西，波涵万象低。
藕花熏浦溆，菱蔓匿凫鹥。
树及长桥尽，滩回七里迷。
还应坐筹暇，时一梦荆溪。','',''),('quantangshi-29978','呈薛博士','喻鳧','quantangshi','','卷30','辛勤长在学，一室少曾开。
时忆暮山寺，独登衰草台。
名期五字立，迹愧九年来。
此意今聊写，还希君子哀。','',''),('quantangshi-29979','即事','喻鳧','quantangshi','','卷30','抱杖立溪口，迎秋看塞门。
连山互苍翠，二水各清浑。
笛发孤烟戍，鵶归夕照村。
萋萋芳草色，终是忆王孙。','',''),('quantangshi-29980','龙翔寺阁夜怀渭南张少府','喻鳧','quantangshi','','卷30','春城带病别，秋塞见除书。
况是神仙吏，仍非尘土居。
河风吹鸟迥，岳雨滴桐疎。
坐阁驰思夕，沙东凉月虚。','',''),('quantangshi-29981','夏日龙翔寺居即事寄崔侍御','喻鳧','quantangshi','','卷30','古刹一幡斜，吹门水过沙。
数声钟里饭，双影树间茶。
落日穷荒雨，微风古堑花。
何当戴豸客，复此问生涯。','',''),('quantangshi-29982','龙翔寺居喜胡权见访因宿','喻鳧','quantangshi','','卷30','林栖无异欢，煮茗就花栏。
雀啅北冈晓，僧开西阁寒。
冲桥二水急，扣月一钟残。
明发还分手，徒悲行路难。','',''),('quantangshi-29983','宿石窟寺','喻鳧','quantangshi','','卷30','一刹古冈南，孤钟撼夕岚。
客闲明月阁，僧闭白云庵。
野鹤立枯枿，天龙吟净潭。
因知不生理，合自此中探。','',''),('quantangshi-29984','夏日龙翔寺寄张侍御','喻鳧','quantangshi','','卷30','沙西林杪寺，殿倚石棱开。
晓月僧汲井，残阳钟殷台。
河冲绿野去，鸟背白云来。
日夕唯增思，京关未想回。','',''),('quantangshi-29985','秋日将归长安留别王尚书','喻鳧','quantangshi','','卷30','朔漠正秋霖，西风传夕砧。
沧洲未归迹，华髪受恩心。
露色冈莎冷，蝉声坞木深。
清晨鈇钺内，只献白云吟。','',''),('quantangshi-29986','龙翔寺言怀','喻鳧','quantangshi','','卷30','眠云喜道存，读易过朝昏。
乔木青连郭，长河白泻门。
钟沈残月坞，鸟去夕阳村。
搜此成闲句，期逢作者论。','',''),('quantangshi-29987','龙翔寺居夏日寄献王尚书','喻鳧','quantangshi','','卷30','那期高斾下，得遇重臣知。
泉石容居止，风沙免路岐。
河兼落下望，句入大荒思。
无复愁烦暑，回山翠阁危。','',''),('quantangshi-29988','题弘济寺不出院僧','喻鳧','quantangshi','','卷30','楚鞋应此世，只遶砌苔休。
色相栽花视，身心坐石修。
声寒通节院，城黑见烽楼。
欲取闲云并，闲云有去留。','',''),('quantangshi-29989','寄刘录事','喻鳧','quantangshi','','卷30','城西青岛寺，累夏漱寒泉。
今在提纲所，应难扫石眠。
风沙榆塞迥，波浪橘洲偏。
重整潇湘棹，心期更几年。','',''),('quantangshi-29990','酬王檀见寄','喻鳧','quantangshi','','卷30','驰心栖杳冥，何物比清冷。
夜月照巫峡，秋风吹洞庭。
酬难尘鬓皓，坐久壁灯青。
竟晚苍山咏，乔枝有鹤听。','',''),('quantangshi-29991','寺居秋日对雨有怀','喻鳧','quantangshi','','卷30','修修复雭雭，黄叶此时飞。
隐几客吟断，邻房僧话稀。
鸽寒栖树定，萤湿在窗微。
即事潇湘渚，渔翁披草衣。','',''),('quantangshi-29992','答刘录事夜月怀湘西友人见寄','喻鳧','quantangshi','','卷30','相逢仍朔漠，相问即波涛。
江思苇花折，笛声关月高。
簿书君阅倦，章句我吟劳。
竟夕空凭阁，长河漴石壕。','',''),('quantangshi-29993','上高侍御','喻鳧','quantangshi','','卷30','旧隐白云峰，生涯落叶同。
关河一栖旅，杨柳十东风。
迹处龙钟内，声居汩没中。
酬恩若有地，宁止杀微躬。','',''),('quantangshi-29994','冬日寄友人','喻鳧','quantangshi','','卷30','空为梁甫吟，谁竟是知音。
风雪坐闲夜，乡园来旧心。
沧江孤棹迥，落日一钟深。
君子久忘我，此诚甘自沈。','',''),('quantangshi-29995','冬夜宿余正字静恭里闲居','喻鳧','quantangshi','','卷30','每来多便宿，不负白云言。
古木朔风动，寒城疎雪翻。
微灯悬刻漏，旧梦返湘沅。
先是琴边起，知为阁务繁。','',''),('quantangshi-29996','得子侄书','喻鳧','quantangshi','','卷30','远书来阮巷，阙下见江东。
不得经史力，枉抛耕稼功。
雁天霞脚雨，渔夜苇条风。
无复琴杯兴，开怀向尔同。','',''),('quantangshi-29997','献知己','喻鳧','quantangshi','','卷30','亦忝受恩身，当殊投刺新。
竟蒙分玉石，终不离埃尘。
大谷非无暖，幽枝自未春。
昏昏过朝夕，应念苦吟人。','',''),('quantangshi-29998','赠张濆处士','喻鳧','quantangshi','','卷30','露白覆棋宵，林青读易朝。
道高天子问，名重四方招。
许鹤归华顶，期僧过石桥。
虽然在京国，心迹自逍遥。','',''),('quantangshi-29999','早秋寺居酬张侍御六韵见寄','喻鳧','quantangshi','','卷30','六十上清冥，晓缄东越藤。
山光紫衣陟，寺影白云凝。
湿叶起寒鸟，深林惊古僧。
微风窗静展，细雨阁吟登。
清韵岳磬远，佳音湖水澄。
却思前所献，何以豸冠称。','',''),('quantangshi-30000','和段学士对雪','喻鳧','quantangshi','','卷30','盈尺知丰稔，开窗对酒壶。
飘当大野匝，洒到急流无。
密际西风尽，凝间朔气扶。
干摧鸟栖枿，冷射夜残罏。
赞月澄斜汉，兼沙搅北湖。
慙于郢客坐，一此调巴歈。','',''),('quantangshi-30001','监试夜雨滴空堦','喻鳧','quantangshi','','卷30','霎霎复凄凄，飘松又洒槐。
气蒙蛛网槛，声叠藓花堦。
古壁青灯动，深庭湿叶埋。
徐垂旧夗瓦，竞历小茅斋。
冷与阴虫间，清将玉漏谐。
病身唯展转，谁见此时怀。','',''),('quantangshi-30002','春雨如膏','喻鳧','quantangshi','','卷30','幂幂敛轻尘，蒙蒙湿野春。
细光添柳重，幽点溅花匀。
惨淡游丝景，阴沈落絮辰。
回低飞蝶翅，寒滴语禽身。
洒岳摧余雪，吹江叠远苹。
东城与西陌，晴后趣何新。','',''),('quantangshi-30003','送友人南中访旧知','喻鳧','quantangshi','','卷30','春尽大方游，思君便白头。
地蒸川有毒，天暖树无秋。
水急三巴险，猨分五岭愁。
为缘知己分，南国必淹留。','',''),('quantangshi-30004','玄都观李尊师','喻鳧','quantangshi','','卷30','藓帻翠髯公，存思古观空。
晓坛柽叶露，晴圃柳花风。
寿已将椿并，碁难见局终。
何当与高鹤，飞去海光中。','',''),('quantangshi-30005','送石贲归吴兴','喻鳧','quantangshi','','卷30','同志幸同年，高堂君独还。
齐荣恩未报，共隐事皆闲。
访寺临河岸，开楼见海山。
洛中推二陆，莫久恋乡关。','',''),('quantangshi-30006','感遇','喻鳧','quantangshi','','卷30','江乡十年别，京国累日同。
在客几多事，俱付酒杯中。','',''),('quantangshi-30007','晚思','喻鳧','quantangshi','','卷30','鹤下紫阁云，沈沈翠微雨。
独坐正无言，孤庄一声杵。','',''),('quantangshi-30008','赠空禅师','喻鳧','quantangshi','','卷30','虎见修行久，松知夏腊高。
寒堂坐风雨，瞑目尚波涛。','',''),('quantangshi-30009','西山寒日逢韦侍御','喻鳧','quantangshi','','卷30','獬豸霜中貌，龙钟病后颜。
惨伤此身事，风雪动江山。','',''),('quantangshi-30010','题禅院','喻鳧','quantangshi','','卷30','无花地亦香，有鹤松多直。
向此奚必孤，山僧尽相识。','',''),('quantangshi-30011','惊秋','喻鳧','quantangshi','','卷30','莺啭才间关，蝉鸣旋萧屑。
如何两鬓毛，不作千枝雪。','',''),('quantangshi-30012','经刘校书墓','喻鳧','quantangshi','','卷30','远冢松回曲渚风，一官闻是校书终。
霜情月思今何在，零落人间策子中。','',''),('quantangshi-30013','蒋处士宅喜闲公至','喻鳧','quantangshi','','卷30','绝杯夏别螺江渡，单钵春过处士斋。
尝茗议空经不夜，照花明月影侵堦。','',''),('quantangshi-30014','绝句','喻鳧','quantangshi','','卷30','银地无尘金菊开，紫棃红枣堕莓苔。
一泓秋水一轮月，今夜故人来不来。','',''),('quantangshi-30015','句','喻鳧','quantangshi','','卷30','颜凋明镜觉，思苦白云知。
沧洲迷钓隐，紫阁负僧期。','',''),('quantangshi-30016','听歌','劉得仁','quantangshi','','卷31','朱槛满明月，美人歌落梅。
忽惊尘起处，疑是有风来。
一曲听初彻，几年愁暂开。
东南正云雨，不得见阳台。','',''),('quantangshi-30017','青龙寺僧院','劉得仁','quantangshi','','卷31','常多簪组客，非独看高松。
此地堪终日，开门见数峰。
苔新禽迹少，泉冷树阴重。
师意如山里，空房晓暮钟。','',''),('quantangshi-30018','夏夜会同人','劉得仁','quantangshi','','卷31','沈沈清暑夕，星斗俨虚空。
岸帻栖禽下，烹茶玉漏中。
形骸忘已久，偃仰趣无穷。
日汲泉来漱，微开密筱风。','',''),('quantangshi-30019','游崔监丞城南别业','劉得仁','quantangshi','','卷31','门与青山近，青山复几重。
雪融皇子岸，春浥翠微峰。
地有经冬草，林无未老松。
竹寒溪隔寺，晴日直闻钟。','',''),('quantangshi-30020','答韦先辈春雨后见寄','劉得仁','quantangshi','','卷31','风散五更雨，鸟啼三月春。
轩窗透初日，砚席绝纤尘。
帝里峰头出，邻家树色新。
怜君高且静，有句寄闲人。','',''),('quantangshi-30021','题吴先生山居','劉得仁','quantangshi','','卷31','先生此幽隐，便可谢人羣。
潭底见秋石，树间飞霁云。
山居心已惯，俗事耳憎闻。
念我要多疾，开炉药许分。','',''),('quantangshi-30022','晚游慈恩寺','劉得仁','quantangshi','','卷31','寺去幽居近，每来因采薇。
伴僧行不困，临水语忘归。
磬动青林晚，人惊白鹭飞。
堪嗟浮俗事，皆与道相违。','',''),('quantangshi-30023','题王处士山居','劉得仁','quantangshi','','卷31','茅堂入谷远，林暗绝其邻。
终日有流水，经年无到人。
溪云常欲雨，山洞别开春。
自得仙家术，栽松独养真。','',''),('quantangshi-30024','宿僧院','劉得仁','quantangshi','','卷31','禅地无尘夜，焚香话所归。
树摇幽鸟梦，萤入定僧衣。
破月斜天半，高河下露微。
翻令嫌白日，动即与心违。','',''),('quantangshi-30025','晓别吕山人','劉得仁','quantangshi','','卷31','疎钟兼漏尽，曙色照青氛。
栖鹤出高树，山人归白云。
月盈期重宿，丹熟约相分。
羡入秋风洞，幽泉仔细闻。','',''),('quantangshi-30026','送知全禅师南游','劉得仁','quantangshi','','卷31','师誉振京城，谈空万乘听。
北行山已雪，南去木犹青。
夜岳禅销月，秋潭汲动星。
回期不可定，孤鹤在高冥。','',''),('quantangshi-30027','上张水部','劉得仁','quantangshi','','卷31','出入门阑久，儿童亦有情。
不须将姓字，长说向公卿。
每许连牀坐，时容并马行。
恩深转无语，怀抱自分明。','',''),('quantangshi-30028','塞上行作','劉得仁','quantangshi','','卷31','乡井从离别，穷边触目愁。
生人居外地，塞雪下中秋。
雁举之衡翅，河穿入虏流。
将军心莫苦，向此取封侯。','',''),('quantangshi-30029','赠江夏卢使君','劉得仁','quantangshi','','卷31','诗人中最屈，无与使君俦。
白发虽求退，明时合见收。
登山犹自健，纵酒可多愁。
好是能骑马，相逢见鄂州。','',''),('quantangshi-30030','冬夜寄白阁僧','劉得仁','quantangshi','','卷31','营营不自息，暌阔数年情。
林下期难逐，人间事旋生。
鸟栖寒水迥，月映积冰清。
石室焚香坐，悬知不为名。','',''),('quantangshi-30031','送姚合郎中任杭州','劉得仁','quantangshi','','卷31','水陆中分程，看花一月行。
会稽山隔浪，天竺树连城。
候吏赍鱼印，迎船载斾旌。
渡江春始半，列屿草初生。','',''),('quantangshi-30032','西园','劉得仁','quantangshi','','卷31','夏圃秋凉入，树低逢帻欹。
水声翻败堰，山翠湿疎篱。
绿滑莎藏径，红连果压枝。
幽人更何事，旦夕与僧期。','',''),('quantangshi-30033','昊天观新栽竹','劉得仁','quantangshi','','卷31','清风枝叶上，山鸟已栖来。
根别古沟岸，影生秋观苔。
徧思诸草木，惟此出尘埃。
恨为移君晚，空庭更拟栽。','',''),('quantangshi-30034','晚步曲江因谒慈恩寺恭上人','劉得仁','quantangshi','','卷31','岂曰趣名者，年年待命通。
坐令青嶂上，兴起白云中。
岸浸如天水，林含似雨风。
南宗犹有碍，西寺问恭公。','',''),('quantangshi-30035','送姚处士归亳州','劉得仁','quantangshi','','卷31','白发麻衣破，还谯别弟回。
首垂听乐泪，花落待歌杯。
石路寻芝熟，柴门有鹿来。
明王下征诏，应就碧峰开。','',''),('quantangshi-30036','寄楼子山云栖上人','劉得仁','quantangshi','','卷31','一室凿崔嵬，危梯叠藓苔。
永无尘事到，时有至人来。
涧谷冬深静，烟岚日午开。
修身知得地，京寺未言回。','',''),('quantangshi-30037','秋夜喜友人宿','劉得仁','quantangshi','','卷31','莫说春闱事，清宵且共吟。
频年遗我辈，何日遇知音。
逼曙天倾斗，将寒叶坠林。
无将簪绂意，只损壮夫心。','',''),('quantangshi-30038','秋日同僧宿西池','劉得仁','quantangshi','','卷31','菡萏遍秋水，隔林香似焚。
僧同池上宿，霞向月边分。
渚鸟栖蒲立，城砧接曙闻。
来宵莫他约，重此话孤云。','',''),('quantangshi-30039','宿韦津山居','劉得仁','quantangshi','','卷31','永夕见招宿，诗书盈草堂。
静吟倾美酒，高论出名场。
窗飒松篁韵，庭兼雪月光。
心期身未老，一去泛潇湘。','',''),('quantangshi-30040','夜携酒访崔正字','劉得仁','quantangshi','','卷31','只应芸阁吏，知我僻兼愚。
吟兴忘饥冻，生涯任有无。
惨云埋远岫，阴吹吼寒株。
忽起围炉思，招携酒满壶。','',''),('quantangshi-30041','送蔡京东归迎侍','劉得仁','quantangshi','','卷31','高堂惟两别，此别是荣归。
薄俸迎亲远，平时知己稀。
郓郊秋木见，鲁寺夜钟微。
近腊西来日，多逢霰雪飞。','',''),('quantangshi-30042','中秋','劉得仁','quantangshi','','卷31','尘里兼尘外，咸期此夕明。
一年惟一度，长恐有云生。
露洗微埃尽，光濡是物清。
朗吟看正好，惆怅又西倾。','',''),('quantangshi-30043','池上宿','劉得仁','quantangshi','','卷31','事事不求奢，长吟省叹嗟。
无才堪世弃，有句向谁夸。
老树呈秋色，空池浸月华。
凉风白露夕，此境属诗家。','',''),('quantangshi-30044','秋夕即事','劉得仁','quantangshi','','卷31','永夕坐暝久，萧萧猨狖啼。
漏微砧韵隔，月落斗杓低。
危叶无风坠，幽禽并树栖。
自怜在岐路，不醉亦沈迷。','',''),('quantangshi-30045','晚夏','劉得仁','quantangshi','','卷31','日夕是西风，流光半已空。
山光渐凝碧，树叶即翻红。
学浅慙多士，秋成羡老农。
谁怜信公道，不泣路岐中。','',''),('quantangshi-30046','夏日即事','劉得仁','quantangshi','','卷31','到晓改诗句，四邻嫌苦吟。
中宵横北斗，夏木隐栖禽。
天地先秋肃，轩窗映月深。
幽庭多此景，惟恐曙光侵。','',''),('quantangshi-30047','夏日通济里居酬诸先辈见访','劉得仁','quantangshi','','卷31','君子远相寻，联镳到敝林。
有诗谁索和，无酒可赊斟。
门列晴峰色，堂开古木阴。
何因驻清听，惟恐日西沈。','',''),('quantangshi-30048','寄姚谏议','劉得仁','quantangshi','','卷31','鸣鞭静路尘，籍籍谏垣臣。
函疏封还密，炉香侍立亲。
箧多临水作，窗宿卧云人。
危坐开寒纸，灯前起草频。','',''),('quantangshi-30049','和厉玄侍御题户部相公庐山草堂','劉得仁','quantangshi','','卷31','白云居创毕，诏入凤池年。
林长双峰树，潭分并寺泉。
石溪盘鹤外，岳室闭猨前。
柱史题诗后，松前更肃然。','',''),('quantangshi-30050','题山中故静禅师','劉得仁','quantangshi','','卷31','寂灭身何在，门人隔此生。
影悬尘已厚，塔种柏初成。
溪院秋先雪，山堂古有精。
当时挂锡处，树老几枝倾。','',''),('quantangshi-30051','夏日游慈恩寺','劉得仁','quantangshi','','卷31','何处消长日，慈恩精舍频。
僧高容野客，树密绝嚣尘。
闲上凌虚塔，相逢避暑人。
却愁归去路，马迹竝车轮。','',''),('quantangshi-30052','题终南麻先生寂禅师石室','劉得仁','quantangshi','','卷31','因居石室贫，五十二回春。
拥褐冥心客，穷经暮齿人。
翠沈空水定，雨绝片云新。
危细秋峰径，相随到顶频。','',''),('quantangshi-30053','送灵武朱书记','劉得仁','quantangshi','','卷31','灵帅与谁善，得君宾幕中。
从容应尽礼，赞画致元功。
连塞云长惨，才秋树半空。
相如偏自惬，掌记复乘骢。','',''),('quantangshi-30054','吊草堂禅师','劉得仁','quantangshi','','卷31','杖履疑师在，房关四壁蛩。
贮瓶经腊水，响塔隔山钟。
乳鸽沿苔井，斋猨散雪峰。
如何不相见，倚徧寺前松。','',''),('quantangshi-30055','早春送湘潭李少府之任','劉得仁','quantangshi','','卷31','柳新春水湄，春岸草离离。
祖席觞云尽，离人泪各垂。
业文传不朽，作尉岂多时。
公退琴堂上，风吹斑竹枝。','',''),('quantangshi-30056','送越客归','劉得仁','quantangshi','','卷31','霜薄东南地，江枫落未齐。
众山离楚上，孤棹宿吴西。
渚客留僧语，笼猨失子啼。
到家冬即是，荷尽若耶溪。','',''),('quantangshi-30057','送周钺往江夏','劉得仁','quantangshi','','卷31','东西南北郡，自说徧曾游。
人世终多故，皇都不少留。
郢城帆过夜，汉水月方秋。
此谒亲知去，闻猨岂解愁。','',''),('quantangshi-30058','送河池李明府之任','劉得仁','quantangshi','','卷31','河池安所理，种柳与弹琴。
自合清时化，仍资白首吟。
程余行片月，公退入遥林。
想得询民瘼，方称单父心。','',''),('quantangshi-30059','送蔡京侍御赴大梁幕','劉得仁','quantangshi','','卷31','同城各多故，会面亦稀疎。
及道须相别，临岐恨有余。
梁园飞楚鸟，汴水走淮鱼。
众说裁军檄，陈琳远不如。','',''),('quantangshi-30060','哭鲍溶有感','劉得仁','quantangshi','','卷31','寥落故人宅，今来身已亡。
古苔封墨沼，深竹映书堂。
秋色池馆静，雨声云水凉。
无因展交道，日暮剖心肠。','',''),('quantangshi-30061','送僧归玉泉寺','劉得仁','quantangshi','','卷31','玉泉归故刹，便老是僧期。
乱木孤蝉后，寒山绝鸟时。
若寻流水去，转出白云迟。
见说千峰路，溪深复顶危。','',''),('quantangshi-30062','宣义池上','劉得仁','quantangshi','','卷31','修篁夹绿池，幽絮此中飞。
何必青山远，仍将白发归。
鸟啼亦有恨，鸥习总无机。
树起秋风细，西林磬入微。','',''),('quantangshi-30063','回中夜访独孤从事','劉得仁','quantangshi','','卷31','满庭霜月魄，风静绝纤闻。
边境时无事，州城夜访君。
拥裘听塞角，酌醴话湘云。
赞佐元戎美，恩齐十万军。','',''),('quantangshi-30064','宿宣义池亭','劉得仁','quantangshi','','卷31','暮色遶柯亭，南山幽竹青。
夜深斜舫月，风定一池星。
岛屿无人迹，菰蒲有鹤翎。
此中足吟眺，何用泛沧溟。','',''),('quantangshi-30065','送智玄首座归蜀中旧山','劉得仁','quantangshi','','卷31','像教得重兴，因师说大乘。
从来悟明主，今去证高僧。
蜀国烟霞异，灵山水月澄。
乡闾诸善友，喜似见南能。','',''),('quantangshi-30066','贺顾非熊及第其年内索文章','劉得仁','quantangshi','','卷31','愚为童稚时，已解念君诗。
及得高科晚，须逢圣主知。
花前飜有泪，鬓上却无丝。
从此东归去，休为坠叶期。','',''),('quantangshi-30067','冬日骆家亭子','劉得仁','quantangshi','','卷31','亭台腊月时，松竹见贞姿。
林积烟藏日，风吹水合池。
恨无人此住，静有鹤相窥。
是景吟诗徧，真于野客宜。','',''),('quantangshi-30068','题邵公禅院','劉得仁','quantangshi','','卷31','无事门多掩，阴阶竹扫苔。
劲风吹雪聚，渴鸟啄冰开。
树向寒山得，人从瀑布来。
终期天目老，擎锡逐云回。','',''),('quantangshi-30069','忆鹤','劉得仁','quantangshi','','卷31','自尔归仙后，经秋又过春。
白云寻不得，紫府去无因。
此地空明月，何山伴羽人。
终期华表上，重见令威身。','',''),('quantangshi-30070','听夜泉','劉得仁','quantangshi','','卷31','静里层层石，潺湲到鹤林。
流回出几洞，源远历千岑。
寒助空山月，清兼此夜心。
幽人听达曙，相和藓牀吟。','',''),('quantangshi-30071','乐游原春望','劉得仁','quantangshi','','卷31','乐游原上望，望尽帝都春。
始觉繁华地，应无不醉人。
云开双阙丽，柳映九衢新。
爱此频来往，多闲逐此身。','',''),('quantangshi-30072','赠雍陶博士','劉得仁','quantangshi','','卷31','腹是羣书笥，官为六义师。
情高少尘事，朝下足闲时。
有句同人伏，无私胄子知。
汉庭公议在，正与触邪宜。','',''),('quantangshi-30073','夏日感怀寄所知','劉得仁','quantangshi','','卷31','了了见岐路，欲行难负心。
趋时不圆转，自古易湮沈。
日正林方合，蜩鸣夏已深。
中郎今远在，谁识爨桐音。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-30074','陈情上知己','劉得仁','quantangshi','','卷31','性与才俱拙，名场迹甚微。
久居颜亦厚，独立事多非。
刻骨搜新句，无人悯白衣。
明时自堪恋，不是不知机。','',''),('quantangshi-30075','秋夜寄友人二首 一','劉得仁','quantangshi','','卷31','永夜无他虑，长吟毕二更。
暗灯摇碧影，滞雨滴堦声。
道进愁还浅，年加睡自轻。
如何得深术，相与舍浮名。','',''),('quantangshi-30076','秋夜寄友人二首 二','劉得仁','quantangshi','','卷31','所思同海岱，所梦亦烟波。
默坐看山久，闲行值寺过。
独吟黄叶乱，相去碧峰多。
我有归心在，君行竟若何。','',''),('quantangshi-30077','寄春坊顾校书','劉得仁','quantangshi','','卷31','宁因不得志，寂寞本相宜。
冥目冥心坐，花开花落时。
数畦蔬甲出，半梦鸟声移。
只恐龙楼吏，归山又见违。','',''),('quantangshi-30078','寄雍陶先辈','劉得仁','quantangshi','','卷31','久别青云士，幽人分固然。
愁心不易去，蹇步卒难前。
尽落经霜叶，频阴欲雪天。
归山自有限，岂待白头年。','',''),('quantangshi-30079','对月寄雍陶','劉得仁','quantangshi','','卷31','圆明寒魄上，天地一光中。
临水通宵坐，知君此兴同。
华凝衣有露，静极树无风。
若向湘江见，湘江彻底空。','',''),('quantangshi-30080','寄谢观','劉得仁','quantangshi','','卷31','十五年余苦，今朝始遇君。
无慙于白日，不枉别孤云。
得失天难问，称扬鬼亦闻。
此恩销镂骨，吟坐叶纷纷。','',''),('quantangshi-30081','送鄂州崔大夫赴镇','劉得仁','quantangshi','','卷31','廉问帝难人，朝庭辍重臣。
入山初有雪，登路正无尘。
去国鸣驺缓，经云住斾频。
千峰与万木，清听雨情新。','',''),('quantangshi-30082','送钱给事赴虢州','劉得仁','quantangshi','','卷31','帝心忧虢俗，暂庭辍掖垣臣。
疲瘵初承制，乡闾似得春。
化成应有瑞，位重转闻贫。
用作盐梅日，争回卧辙人。','',''),('quantangshi-30083','送雍陶侍御赴兖州裴尚书命','劉得仁','quantangshi','','卷31','纶阁知孤直，翻论北巷贤。
且縻莲幕里，会致玉堦前。
洙泗秋微动，龟蒙月正圆。
元戎军务息，清句待君联。','',''),('quantangshi-30084','送新罗人归本国','劉得仁','quantangshi','','卷31','鸡林隔巨浸，一住一年行。
日近国先曙，风吹海不平。
眼穿乡井树，头白渺弥程。
到彼星霜换，唐家语却生。','',''),('quantangshi-30085','送车涛罢举归山','劉得仁','quantangshi','','卷31','朝是暮还非，人情冷暖移。
浮生只如此，强进欲何为。
要路知无援，深山必遇师。
怜君明此理，休去不迟疑。','',''),('quantangshi-30086','送王书记归邠州','劉得仁','quantangshi','','卷31','陈琳轻一别，马上意超然。
来日行烦暑，归时听早蝉。
阴云翳城郭，细雨紊山川。
从事公刘地，元戎旧礼贤。','',''),('quantangshi-30087','送谢观之劒南从事','劉得仁','quantangshi','','卷31','迢递从知己，他人敢更言。
离京虽未腊，到府已应暄。
飞急奔行雁，啼酸忆子猨。
江山无限思，君拟共谁论。','',''),('quantangshi-30088','送顾非熊作尉盱眙','劉得仁','quantangshi','','卷31','一名兼一尉，未足是君伸。
厉数为诗者，多来作谏臣。
路翻平楚阔，草带古淮新。
天下虽云大，同声有几人。','',''),('quantangshi-30089','送高湘及第后东归觐叔','劉得仁','quantangshi','','卷31','此去几般荣，登科鼎足名。
无慙入南巷，高价耸东京。
窗对嵩山碧，庭来洛水声。
门前桃李树，一径已阴成。','',''),('quantangshi-30090','送友人下第归觐','劉得仁','quantangshi','','卷31','君此卜行日，高堂应梦归。
莫将和氏泪，滴着老莱衣。
岳雨连河细，田禽出麦飞。
到家调膳后，吟苦落蝉晖。','',''),('quantangshi-30091','送友人下第归扬州觐省','劉得仁','quantangshi','','卷31','新柳间花垂，东西京路岐。
园林知自到，寝食计相思。
雨断淮山出，帆扬楚树移。
晨昏心已泰，蝉发是回时。','',''),('quantangshi-30092','早行','劉得仁','quantangshi','','卷31','万类半已动，此心宁自安。
月沈平野尽，星隐曙空残。
马渡横流广，人行湛露寒。
还思犹梦者，不信早行难。','',''),('quantangshi-30093','通济里居酬庐肇见寻不遇','劉得仁','quantangshi','','卷31','衡门掩绿苔，树下绝尘埃。
偶赴高僧约，旋知长者来。
云山堪眺望，车马必裴回。
问以何为待，慙无酒一杯。','',''),('quantangshi-30094','赠王尊师','劉得仁','quantangshi','','卷31','为道常日损，尊师修此心。
挂肩黄布被，穿髪白蒿簪。
符札灵砂字，弦弹古素琴。
囊中曾有药，点土亦成金。','',''),('quantangshi-30095','冬夜与蔡校书宿无可上人院','劉得仁','quantangshi','','卷31','儒释偶同宿，夜窗寒更清。
忘机于世久，晤语到天明。
月倒高松影，风旋一磬声。
真门犹是幻，不用觉浮生。','',''),('quantangshi-30096','冬日喜同志宿','劉得仁','quantangshi','','卷31','相逢话清夜，言实转相知。
共道名虽切，唯论命不疑。
吟身坐霜石，眠鸟握风枝。
别忆天台客，烟霞昔有期。','',''),('quantangshi-30097','逢吕上山人','劉得仁','quantangshi','','卷31','尘里正愁老，相逢眼益明。
从前枉多病，此后鲜疎名。
古柏今收子，深山许事兄。
长生如有分，愿逐到蓬瀛。','',''),('quantangshi-30098','春暮对雨','劉得仁','quantangshi','','卷31','春暮雨微微，翻疑坠叶时。
气蒙杨柳重，寒勒牡丹迟。
未夕鸟先宿，望晴人有期。
何当廓阴闭，新暑竹风吹。','',''),('quantangshi-30099','长信宫','劉得仁','quantangshi','','卷31','簟凉秋气初，长信恨何如。
拂黛月生指，解鬟云满梳。
一从悲画扇，几度泣前鱼。
坐听南宫乐，清风摇翠裾。','',''),('quantangshi-30100','初夏题段郎中修竹里南园','劉得仁','quantangshi','','卷31','高人游息处，与此曲池连。
密树才春后，深山在目前。
远峰初绝雨，片石欲生烟。
数有僧来宿，应缘静好禅。','',''),('quantangshi-30101','题景玄禅师院','劉得仁','quantangshi','','卷31','古僧精进者，师复是谁流。
道贵行无我，禅难说到头。
汲泉羸鹤立，拥褐老猨愁。
曾住深山院，何如此院幽。','',''),('quantangshi-30102','夏日樊川别业即事','劉得仁','quantangshi','','卷31','无事称无才，柴门亦罕开。
脱巾吟永日，着屐步荒台。
风卷微尘上，霆将暴雨来。
终南云渐合，咫尺失崔嵬。','',''),('quantangshi-30103','寄无可上人','劉得仁','quantangshi','','卷31','省学为诗日，宵吟每达晨。
十年期是梦，一事未成身。
枉别山中客，殊非世上人。
今来已如此，须得桂荣新。','',''),('quantangshi-30104','和范校书赠造微上人','劉得仁','quantangshi','','卷31','得性见微公，何曾执着空。
修心将佛竝，吐论与儒通。
晓漱松杉下，宵禅雪月中。
他生有缘会，君子亦应同。','',''),('quantangshi-30105','访曲江胡处士','劉得仁','quantangshi','','卷31','何况归山后，而今已似仙。
卜居天苑畔，闲步禁楼前。
落日明沙岸，微风上纸鸢。
静还林石下，坐读养生篇。','',''),('quantangshi-30106','慈恩寺塔下避暑','劉得仁','quantangshi','','卷31','古松凌巨塔，修竹映空廊。
竟日闻虚籁，深山只此凉。
僧真生我静，水淡发茶香。
坐久东楼望，钟声振夕阳。','',''),('quantangshi-30107','秋晚与友人游青龙寺','劉得仁','quantangshi','','卷31','高视终南秀，西风度阁凉。
一生同隙影，几处好山光。
暮鸟投嬴木，寒钟送夕阳。
因居话心地，川冥宿僧房。','',''),('quantangshi-30108','春日雨后作','劉得仁','quantangshi','','卷31','朝来微有雨，天地爽无尘。
北厥明如昼，南山碧动人。
车舆终日别，草树一城新。
枉是吾君戚，何门谒紫宸。','',''),('quantangshi-30109','别王山人','劉得仁','quantangshi','','卷31','旨甘虽自足，未是禄荣亲。
尚逐趋时伴，多离有道人。
山居衣以草，生寄药随身。
不食长无疾，年知出十旬。','',''),('quantangshi-30110','赠陶山人','劉得仁','quantangshi','','卷31','处士例营营，惟君纵此生。
闲能资寿考，健不换公卿。
药圃妻同耨，山田子共耕。
定知丹熟后，无姓亦无名。','',''),('quantangshi-30111','禁署早春晴望','劉得仁','quantangshi','','卷31','御林闻有早莺声，玉槛春香九陌晴。
寒着霁云归紫阁，暖浮佳气动芳城。
宫池日到冰初解，辇路风吹草欲生。
鸳侣此时皆赋咏，商山雪在思尤清。','',''),('quantangshi-30112','山中寻道人不遇','劉得仁','quantangshi','','卷31','年过弱冠风尘里，常拟随师学炼形。
石路特来寻道者，云房空见有仙经。
碁于松底留残局，鹤向潭边退数翎。
便欲此居闲到老，先生何日下青冥。','',''),('quantangshi-30113','赠敬晊助教二首 一','劉得仁','quantangshi','','卷31','到来常听说清虚，手把玄元七字书。
仙籍不知名姓有，道情惟见往来疎。
已能绝粒无饥色，早晚休官买隐居。
便欲去随为弟子，片云孤鹤可相于。','',''),('quantangshi-30114','赠敬晊助教二首 二','劉得仁','quantangshi','','卷31','街西静观求居处，不到权门到寺频。
禁掖人知连状荐，国庠官满一家贫。
清仪称是蓬瀛客，直气堪为谏诤臣。
自顾无成年渐长，报恩惟愿杀微身。','',''),('quantangshi-30115','送祖山人归山','劉得仁','quantangshi','','卷31','独来朝市笑浮云，却忆烟霞出帝城。
不说金丹能点化，空教弟子学长生。
壶中泻酒看云影，洞里逢师下鹤迎。
料得仙家玉牌上，已镌白日上升名。','',''),('quantangshi-30116','监试莲花峰','劉得仁','quantangshi','','卷31','太华万余重，岧嶤只此峰。
当秋倚寥泬，入望似芙蓉。
翠拔千寻直，青危一朵穠。
气分毛女秀，灵有羽人踪。
倒影侵官路，流香激庙松。
尘埃终不及，车马自憧憧。','',''),('quantangshi-30117','京兆府试目极千里','劉得仁','quantangshi','','卷31','献赋多年客，低眉恨不前。
此心常郁矣，纵目忽超然。
送骥登长路，有鸿入远天。
古墟烟幂幂，穷野草绵绵。
树与金城接，山疑桂水连。
何当开霁日，无物翳平川。','',''),('quantangshi-30118','寻陈处士山堂','劉得仁','quantangshi','','卷31','步溪凡几转，始得见幽踪。
路隐千根树，门开万仞峰。
片云生石窦，浅水卧枯松。
穷谷风光冷，深山翠碧浓。
鹤看空里过，仙向坐中逢。
底露秋潭水，声微暮观钟。
他年来此定，异日愿相容。
且喜今归去，人间事更慵。','',''),('quantangshi-30119','题从伯舍人道正里南园','劉得仁','quantangshi','','卷31','帝里余新第，朱门面碧岑。
曙堂增爽气，乔木动清阴。
直去亲瑶陛，朝回在竹林。
风流才子调，好尚古人心。
薜荔遮窗暗，莓苔近井深。
礼无青草隔，诗共白衣吟。
轩静留孤鹤，庭虚到远砧。
掩关裁凤诏，开镜理琼簪。
种植今如此，尘埃永不侵。
云奔投刺者，日日待为霖。','',''),('quantangshi-30120','赋得听松声','劉得仁','quantangshi','','卷31','庭际微风动，高松韵自生。
听时无物乱，尽日觉神清。
强与幽泉竝，翻嫌细雨并。
拂空增鹤唳，过牖合琴声。
况复当秋暮，偏宜在月明。
不知深涧底，萧瑟有谁听。','',''),('quantangshi-30121','宿普济寺','劉得仁','quantangshi','','卷31','京寺数何穷，清幽此不同。
曲江临阁北，御苑自墙东。
广陌车音急，危楼夕景通。
乱峰沈暝野，毒暑过秋空。
幡扬虚无里，星生杳霭中。
月光笼月殿，莲气入莲宫。
缀草凉天露，吹人古木风。
饮茶除假寐，闻磬释尘蒙。
童子眠苔净，高僧话漏终。
待鸣晓钟后，万井复朣胧。','',''),('quantangshi-30122','和郑校书夏日游郑泉','劉得仁','quantangshi','','卷31','太虚悬畏景，古木蔽清阴。
爰有泉堪挹，闲思日可寻。
来闻鸣滴滴，照竦碧沈沈。
几脉成溪壑，何人测浅深。
澄时无一物，分处厉千林。
净溉灵根药，凉浮玉翅禽。
饮疑蠲宿疾，见自失烦襟。
僧共云前濑，龙和月下吟。
叠光轻吹动，彻底晓霞侵。
不用频游去，令君少进心。','',''),('quantangshi-30123','和段校书冬夕寄题庐山','劉得仁','quantangshi','','卷31','名高身未到，此恨蓄多时。
是夕吟因话，他年必去随。
尝闻庐岳顶，半入楚江湄。
几处悬崖上，千寻瀑布垂。
炉峰松淅沥，湓浦柳参差。
日色连湖白，钟声拂浪迟。
烟梯缘薜荔，岳寺步欹危。
地本饶灵草，林曾出祖师。
石楼霞耀壁，猨树鹤分枝。
细径萦岩末，高窗见海涯。
嵌空寒更极，寂寞夜尤思。
阴谷冰埋术，仙田雪覆芝。
乱泉禅客濑，异迹逸人知。
藓室新开竈，柽潭末了棋。
如何遂闲放，长得在希夷。
空务渔樵事，方无道路悲。
谢公台尚在，陶令柳潜衰。
尘外难相许，人间贵迹遗。
虽怀丹桂影，不忘白云期。
仁者终携手，今朝预赋诗。','',''),('quantangshi-30124','书事寄万年厉员外','劉得仁','quantangshi','','卷31','帝城皆剧县，令尹美居东。
遂拜赵张下，蹔离星象中。
拥归从北阙，送上动南宫。
紫禁黄山遶，沧溟素浐通。
封疆亲日月，邑里出王公。
赋税充天府，歌谣入圣聪。
土膏寒麦覆，人海昼尘蒙。
廨宇松连翠，朝街火散红。
文场新桂茂，粉署旧兰崇。
留客挥盈爵，抽毫咏早鸿。
前驺潘岳贵，故里邵平穷。
劝隐莲峰久，期耕树谷同。
凫飞将去叶，劒气尚埋丰。
何必华阴土，方垂拂拭功。','',''),('quantangshi-30125','上姚谏议','劉得仁','quantangshi','','卷31','高文与盛德，皆谓古无伦。
圣代生才子，明庭有谏臣。
已瞻龙衮近，渐向凤池新。
却忆波涛郡，来时岛屿春。
名因诗句大，家似布衣贫。
曾暗投新轴，频闻奖滞身。
照吟清夕月，送药紫霞人。
终计依门馆，何疑不化鳞。','',''),('quantangshi-30126','上翰林丁学士','劉得仁','quantangshi','','卷31','今代如尧代，征贤察众情。
久聆推行寔，然后佐聪明。
官自文华重，恩因顾问生。
词人求作称，天子许和羹。
御柳凋霜晚，宫泉滴月清。
直庐寒漏近，秋烛白麻成。
玉殿移时对，金舆数侍行。
赐衣香未散，借马色难名。
时辈何偏羡，儒流此最荣。
终当闻夑理，寰宇永升平。','',''),('quantangshi-30127','二','劉得仁','quantangshi','','卷31','何处访岐路，青云但忆归。
风尘数年限，门馆一生依。
外族帝王是，中朝亲旧稀。
翻令浮议者，不许九霄飞。','',''),('quantangshi-30128','山中舒怀寄上丁学士','劉得仁','quantangshi','','卷31','五字投精鉴，慙非大雅词。
本求闲赐览，岂料便蒙知。
幽拙欣殊幸，提携更不疑。
弱苗须雨长，懒翼在风吹。
砺镞端杨叶，光门待桂枝。
计闻尘里誉，因和禁中诗。','',''),('quantangshi-30129','莺出谷','劉得仁','quantangshi','','卷31','东风潜启物，动息意皆新。
此鸟从幽谷，依林报早春。
出寒虽未及，振羽渐能频。
稍类冲天鹤，多随折桂人。
尊前喧有语，花里昼藏身。
若向穠华处，余禽不见亲。','',''),('quantangshi-30130','哭翰林丁侍郎','劉得仁','quantangshi','','卷31','相知出肺腑，非旧亦非亲。
每见云霄侣，多阳鄙拙身。
即期扶泰运，岂料哭贤人。
应是随先帝，依前作近臣。
平生任公直，爱弟尚风尘。
宅闭青松古，坟临赤水新。
官清仍齿壮，儿小复家贫。
惆怅天难问，空流泪满巾。','',''),('quantangshi-30131','陈情上李景让大夫','劉得仁','quantangshi','','卷31','一被浮名误，旋遭白发侵。
裴回恋明主，梦寐在秋岑。
遇物唯多感，居常只是吟。
待时钳定口，经事压低心。
辛苦文场久，因缘戚里深。
老迷新道路，贫卖旧园林。
晴赏行闻水，宵棊坐见参。
龟留闲去问，僧约偶来寻。
望喜潜凭鹊，娱情愿有琴。
此生如遂意，誓死报知音。
上德怜孤直，唯公拔陆沈。
丘山恩忽被，蝼蚁力难任。
作鉴明同日，听言重若金。
从兹更无限，翘足俟为霖。','',''),('quantangshi-30132','和郑先辈谢秩闲居寓书所怀','劉得仁','quantangshi','','卷31','西风日夜吹，万木共离披。
近甸新晴后，高人得意时。
暂闲心亦泰，论道面难欺。
把笔还诗债，将琴当酒资。
蓝衫悬竹桁，乌帽挂松枝。
名占文章重，官归谏宪迟。
生涯贫帝里，公议到台司。
室冷沾苔藓，门清绝路岐。
莫言邻白屋，即贺立丹墀。
岂虑尘埃久，云霄故有期。','',''),('quantangshi-30133','病中晨起即事寄场中往还','劉得仁','quantangshi','','卷31','昨日离尘里，今朝懒已成。
岂能为久隐，更欲泥浮名。
虚牖晨光白，幽园晓气清。
戴沙寻水去，披雾入林行。
叠叶孤禽在，初阳半树明。
桑麻新雨润，芦荻古波声。
易向田家熟，元于世路生。
病多三径塞，吟苦四邻惊。','',''),('quantangshi-30134','悲老宫人','劉得仁','quantangshi','','卷31','白发宫娃不解悲，满头犹自插花枝。
曾缘玉貌君王宠，准拟人看似旧时。','',''),('quantangshi-30135','村中闲步','劉得仁','quantangshi','','卷31','闲共野人临野水，新秋高树挂清晖。
不知尘里无穷事，白鸟双飞入翠微。','',''),('quantangshi-30136','上巳日','劉得仁','quantangshi','','卷31','未敢分明赏物华，十年如见梦中花。
游人过尽衡门掩，独自凭栏到日斜。','',''),('quantangshi-30137','省试日上崔侍郎四首 一','劉得仁','quantangshi','','卷31','衣上年年泪血痕，只将怀抱诉干坤。
如今主圣臣贤日，岂致人间一物冤。','',''),('quantangshi-30138','省试日上崔侍郎四首 二','劉得仁','quantangshi','','卷31','如病如痴二十秋，求名难得又难休。
回看骨肉须堪耻，一着麻衣便白头。','',''),('quantangshi-30139','省试日上崔侍郎四首 三','劉得仁','quantangshi','','卷31','戚里称儒愧小才，礼闱公道此时开。
他人何事虚相指，明主无私不是媒。','',''),('quantangshi-30140','省试日上崔侍郎四首 四','劉得仁','quantangshi','','卷31','方寸终朝似火然，为求白日上青天。
自嗟辜负平生眼，不识春光二十年。','',''),('quantangshi-30141','秋夜','劉得仁','quantangshi','','卷31','秋气满堂孤烛冷，清宵无寐忆山归。
窗前月过三更后，细竹吟风似雨微。','',''),('quantangshi-30142','长门怨','劉得仁','quantangshi','','卷31','争得一人闻此怨，长门深夜有妍姝。
早知雨露翻相悞，只插荆钗嫁匹夫。','',''),('quantangshi-30143','贾妇怨','劉得仁','quantangshi','','卷31','嫁与商人头欲白，未曾一日得双行。
任君逐利轻江海，莫把风涛似妾轻。','',''),('quantangshi-30144','寄友人','劉得仁','quantangshi','','卷31','风飒沈思眼忽开，尘埃污得是庸才。
那堪更见巢松鹤，飞入青云不下来。','',''),('quantangshi-30145','晏起','劉得仁','quantangshi','','卷31','日过辰时犹在梦，客来应笑也求名。
浮生自得长高枕，不向人间与命争。','',''),('quantangshi-30146','马上别单于刘评事','劉得仁','quantangshi','','卷31','庙谋宏远人难测，公主生还帝感深。
天下底平须共喜，一时闲事莫惊心。','',''),('quantangshi-30147','赠从弟谷','劉得仁','quantangshi','','卷31','此世荣枯岂足惊，相逢惟要眼长青。
从来不爱三闾死，今日凭君莫独醒。','',''),('quantangshi-30148','别山居','劉得仁','quantangshi','','卷31','万壑千岩景象开，登临未足又须回。
凭师莫断松间路，秋月圆时弟子来。','',''),('quantangshi-30149','赠道人','劉得仁','quantangshi','','卷31','长在城中无定业，卖丹磨镜两途贫。
三山来往寻常事，不省曾惊市井人。','',''),('quantangshi-30150','对月寄同志','劉得仁','quantangshi','','卷31','霜满中庭月在林，塞鸿频过又更深。
支颐不语相思坐，料得君心似我心。','',''),('quantangshi-30151','忆鹤','劉得仁','quantangshi','','卷31','白丝翎羽丹砂顶，晓度秋烟出翠微。
来向孤松枝上立，见人吟苦却高飞。','',''),('quantangshi-30152','云门寺','劉得仁','quantangshi','','卷31','上方僧又起，清磬出林初。
吟苦晓灯暗，露零秋草疎。
旧山多梦到，流水送愁余。
寄寺欲经岁，惭无亲故书。','',''),('quantangshi-30153','中秋宿邓逸人居','劉得仁','quantangshi','','卷31','偶与山僧宿，吟诗坐到明。
夜凉耽月色，秋渴漱泉声。
磵木如竿耸，窗云作片生。
白衣闲自贵，不揖汉公卿。','',''),('quantangshi-30154','句','劉得仁','quantangshi','','卷31','外家虽是帝，当路且无亲。
白日只如哭，黄泉免恨无。
身闲甘旨下，白发太平人。
同游芳草寺，见示白云诗。
犹祈启金口，一为动文权。
深山寺路千层石，竹杖椶鞋便可登。','',''),('quantangshi-30155','题山院','權審','quantangshi','','卷31','万叶风声利，一山秋气寒。
晓霜浮碧瓦，落日度朱栏。','',''),('quantangshi-30156','绝句','權審','quantangshi','','卷31','得即高歌失即休，多悲多恨谩悠悠。
今朝有酒今朝醉，明日愁来明日愁。','',''),('quantangshi-30157','郡中有怀寄上睦州员外杜十三兄','邢羣','quantangshi','','卷31','城枕溪流更浅斜，丽谯连带邑人家。
经冬野菜青青色，未腊山梅处处花。
虽免嶂云生岭上，永无音信到天涯。
如今岁[晏]从羁滞，心喜弹冠事不赊。','',''),('quantangshi-30158','早发灵芝望九华寄杜员外使君','曹汾','quantangshi','','卷31','戴月早辞三秀馆，迟明初识久华峰。
嵯嵯玉劒寒铓利，褭褭青莲翠叶重。
奇状却疑人画出，岚光如为客添浓。
行春若到五溪上，此处褰帷正面逢。','',''),('quantangshi-30159','落花','嚴惲','quantangshi','','卷31','春光冉冉归何处，更向花前把一杯。
尽日问花花不语，为谁零落为谁开。','',''),('quantangshi-30160','题筹笔驿','殷潛之','quantangshi','','卷31','江东矜割据，邺下夺孤嫠。
霸畧非匡汉，宏图欲佐谁。
奏书辞后主，仗劒出全师。
重袭襃斜路，悬开反正旗。
欲将苞有截，必使举无遗。
沈虑经谋际，挥毫决胜时。
圜觚当分画，前箸此操持。
山秀扶英气，川流入妙思。
算成功在彀，运去事终亏。
命屈天方厌，人亡国自随。
艰难推旧姓，开创极初基。
总叹曾过地，宁探作教资。
若归新历数，谁复顾衰危。
报德兼明道，长留识者知。','',''),('quantangshi-30161','送高遂赴举','祝元膺','quantangshi','','卷31','句曲旧宅真，自产日月英。
既涵岳渎气，安无神仙名。
松桂逦迤色，与君相送情。','',''),('quantangshi-30162','寄道友','祝元膺','quantangshi','','卷31','两颔凝清霜，玉炉焚天香。
为我延岁华，得入不死乡。','',''),('quantangshi-30163','梦仙谣','祝元膺','quantangshi','','卷31','蟾蜍夜作青冥烛，螮蝀晴为碧落梯。
好个分明天上路，谁教深入武陵溪。','',''),('quantangshi-30164','句','祝元膺','quantangshi','','卷31','雾纹斑似豹，水力健如龙。','',''),('quantangshi-30165','贺邓璠使君正拜袁州','彭蟾','quantangshi','','卷31','六年惠爱及黎甿，大府论功俟陟明。
尺一诏书天上降，二千石禄世间荣。
新添画戟门增峻，旧蹑青云路转平。
更待皇恩醒善政，碧油幢到郡斋迎。','',''),('quantangshi-30166','和严恽落花诗','王樞','quantangshi','','卷31','花落花开人世梦，衰荣闲事且持杯。
春风底事轻摇落，何似从来不要开。','',''),('quantangshi-30167','咏宣律和尚袈裟','張希復','quantangshi','','卷31','共覆三衣中夜寒，披时不镇尼师坛。
无因盖得龙宫地，畦里尘飞叶相残。','',''),('quantangshi-30168','莺出谷','錢可復','quantangshi','','卷31','玉律阳和变，时禽羽翮新。
载飞初出谷，一啭已惊人。
拂柳宜烟暖，冲花觉露春。
抟风翻翰疾，向日弄吭频。
求友心何切，迁乔幸有因。
华林高玉树，栖托及芳晨。','',''),('quantangshi-30169','莺出谷','張鷺','quantangshi','','卷31','弱柳随俦匹，迁莺正及春。
乘风音响远，映日羽毛新。
已得辞幽谷，还将脱俗尘。
鸳鸾方可慕，燕雀迥无邻。
游止知难屈，飜飞在此伸。
一枝如借便，终冀托深仁。','',''),('quantangshi-30170','莺出谷','劉莊物','quantangshi','','卷31','幸因辞旧谷，从此及芳晨。
欲语如调舌，初飞似畏人。
风调归影便，日暖吐声频。
翔集知无阻，联绵贵有因。
喜迁乔木近，宁厌对花新。
堪念微禽意，关关也爱春。','',''),('quantangshi-30171','题吕食新水阁兼寄南商州郎中','朱景玄','quantangshi','','卷31','丹槛初结构，孤高冠清川。
庭临谷中树，檐落山上泉。
晓色挂残月，夜声杂繁弦。
青春去如水，康乐归何年。','',''),('quantangshi-30172','华山南望春','朱景玄','quantangshi','','卷31','灵岳多异状，巉巉出虚空。
闲云恋岩壑，起灭苍翠中。
皓气澄野水，神光秘琼宫。
鹤巢前林雪，瀑落满涧风。
春尽花未发，川回路难穷。
何因着山屐，鹿迹寻羊公。','',''),('quantangshi-30173','水阁','朱景玄','quantangshi','','卷31','楼居半池上，澄影共相空。
谢守题诗处，莲开净碧中。','',''),('quantangshi-30174','迎风亭','朱景玄','quantangshi','','卷31','山雨留清气，溪飙送早凉。
时回石门步，阶下碧云光。','',''),('quantangshi-30175','双槠亭','朱景玄','quantangshi','','卷31','连檐对双树，冬翠夏无尘。
未肯慙桃李，成阴不待春。','',''),('quantangshi-30176','莲亭','朱景玄','quantangshi','','卷31','回塘最幽处，拍水小亭开。
莫怪阑干湿，䴔䴖夜宿来。','',''),('quantangshi-30177','中峯亭','朱景玄','quantangshi','','卷31','中峯上翠微，窗晓早霞飞。
几引登山屐，春风踏雪归。','',''),('quantangshi-30178','飞云亭','朱景玄','quantangshi','','卷31','上结孤圆顶，飞轩出泰清。
有时迷处所，梁栋晓云生。','',''),('quantangshi-30179','四望亭','朱景玄','quantangshi','','卷31','高亭羣峰首，四面俯晴川。
每见晨光晓，阶前万井烟。','',''),('quantangshi-30180','望莲台','朱景玄','quantangshi','','卷31','秋台好登望，菡萏发清池。
半似红颜醉，凌波欲暮时。','',''),('quantangshi-30181','茶亭','朱景玄','quantangshi','','卷31','静得尘埃外，茶芳小华山。
此亭真寂寞，世路少人闲。','',''),('quantangshi-30182','宿新安村步','朱景玄','quantangshi','','卷31','淅淅寒流涨浅沙，月明空渚徧芦花。
离人偶宿孤村下，永夜闻砧一两家。','',''),('quantangshi-30183','远闻本郡行春到旧山二首 一','朱景玄','quantangshi','','卷31','一身从宦留京邑，五马遥闻到旧山。
已领烟霞光野径，深惭老幼候柴关。','',''),('quantangshi-30184','远闻本郡行春到旧山二首 二','朱景玄','quantangshi','','卷31','清风借响松筠外，画隼停晖水石间。
定掩溪名在图传，共知轩盖此登攀。','',''),('quantangshi-30185','和崔使君临发不得观积雪','朱景玄','quantangshi','','卷31','贫居稍与池塘近，旬日轩车不降来。
一树琼花空有待，晓风看落满青苔。','',''),('quantangshi-30186','句','朱景玄','quantangshi','','卷31','塞鸿先秋去，边草入夏生。','',''),('quantangshi-30187','别青州妓段东美 一','薛宜僚','quantangshi','','卷31','经年邮驿许安栖，一会他乡别恨迷。
今日海帆飘万里，不堪肠断对含啼。','',''),('quantangshi-30188','别青州妓段东美 二','薛宜僚','quantangshi','','卷31','阿母桃花方似锦，王孙草色正如烟。
不须更向沧溟望，惆怅欢情恰一年。','',''),('quantangshi-30189','咏韦臯','郭圓','quantangshi','','卷31','宣父从周又适秦，昔贤谁少出风尘。
当时甚讶张延赏，不识韦臯是贵人。','',''),('quantangshi-30190','进宣宗收复河湟诗','崔鉉','quantangshi','','卷31','边陲万里注恩波，宇宙羣芳洽凯歌。
右地名王争解辫，远方戎垒尽投戈。
烟尘永息三秋戍，瑞气遥清九折河。
共遇圣明千载运，更观俗阜与时和。','',''),('quantangshi-30191','咏架上鹰','崔鉉','quantangshi','','卷31','天边心胆架头身，欲拟飞腾未有因。
万里碧霄终一去，不知谁是解绦人。','',''),('quantangshi-30192','越亭二十韵','晦','quantangshi','','卷31','乏才叨八使，徇禄非三顾。
南服颁诏条，东林证迷误。
未闻述职效，偶脱嚣烦趣。
激水浚㘭塘，缘崖欹磴步。
西岩焕朝旭，深壑囊宿雾。
影气爽衣巾，凉飔轻杖履。
临高神虑寂，远眺川原布。
孤帆逗汀烟，飜鵶集江树。
独探洞府静，怳若偓佺遇。
一瞬契真宗，百年成妄故。
孱颜石户启，杳霭溪云度。
松籁韵宫商，鸳甍势翔遡。
津梁危彴架，济物虚舟渡。
环流驰羽觞，金英妬妆嫮。
笳吟寒垒迥，鸟噪空山暮。
怅望麋鹿心，低回车马路。
悬冠谢陶令，褫佩怀疏傅。
遐想蜕缨緌，徒慙恤襦袴。
福盈祸之倚，权胜道所恶。
何必栖禅关，无言自冥悟。','',''),('quantangshi-30193','除浙东留题桂郡林亭','晦','quantangshi','','卷31','紫泥远自金銮降，朱斾翻驰镜水头。
陶令风光偏畏夜，子牟衰鬓暗惊秋。
西隣月色何时见，南国春光岂再游。
莫遣艳歌催客醉，不堪回首翠蛾愁。','',''),('quantangshi-30194','句','晦','quantangshi','','卷31','石静如开镜，山高若耸莲。
笋竿抽玉管，花蔓缀金钿。','',''),('quantangshi-30195','和元常侍除浙东留题','路貫','quantangshi','','卷31','谢安致理逾三载，黄霸清声彻九重。
犹辍佩环归凤阙，且将仁政到稽峯。
林间立马罗千骑，池上开筵醉一钟。
共喜甘棠有新咏，独惭霜鬓又攀龙。','',''),('quantangshi-30196','赠巩畴','鄭薰','quantangshi','','卷31','密雪松桂寒，书窗导余清。
风憾冰玉碎，阶前琴磬声。
榻静几砚洁，帙散缣缃明。
高论展僧肇，精言资巩生。
立意加玄虚，析理分纵横。
万化悉在我，一物安能惊。
江海何所动，丘山常自平。
迟速不相阂，后先徒起争。
镜照分妍丑，秤称分重轻。
颜容宁入鉴，铢两岂关衡。
蕴微道超忽，剖镫音泠泠。
纸上掣牢键，舌端摇利兵。
圆澈保直性，客尘排妄情。
有住即非住，无行即是行。
疏越舍朱弦，哇淫鄙秦筝。
淡薄贵无味，羊斟慙大羹。
洪远包干坤，幽窅潜沈冥。
罔烦跬步举，顿达万里程。
庐远尚莫晓，隐留曾误听。
直须持妙说，共诣毗耶城。','',''),('quantangshi-30197','句','鄭薰','quantangshi','','卷31','项斯逢水部，谁道不关情。','',''),('quantangshi-30198','镊白曲','薛逢','quantangshi','','卷31','去年镊白鬓，境里犹堪认年少。
今年镊白发，两眼昏昏手战跳。
满酌浓酹假颜色，颜色不扬翻自笑。
少年曾读古人书，本期独善安有余。
虽盖长安一片瓦，未遑卒岁容宁居。
前年依亚成都府，月请俸緍六十五。
妻儿骨肉愁欲来，偏梁阁道归得否。
长安六月尘亘天，池塘鼎沸林欲燃。
合家恸哭出门送，独驱匹马陵山巅。
到官只是推诚信，终日兢兢幸无恡。
丞相知怜为小心，忽然奏佩专城印。
专城俸入一倍多，况兼职禄霜峨峨。
山妻稚女悉迎到，时列绿罇酣酒歌。
醉来便向罇前倒，风月满头丝皓皓。
虽然减得阖门忧，又加去国五年老。
五年老，知奈何，来日少，去日多。
金锤锤碎黄金镊，更唱罇前老去歌。','',''),('quantangshi-30199','君不见','薛逢','quantangshi','','卷31','君不见，马侍中，气吞河朔称英雄。
君不见，韦太尉，二十年前镇蜀地。
一朝冥漠归下泉，功业胜名两憔悴。
奉诚园里篙棘生，长兴街南沙路平。
当时带砺在何处，今日子孙无地耕。
或闻羁旅甘常调，簿尉文参各天表。
清明纵便天使来，一把纸钱风树杪。
碑文半缺碑堂摧，祁连冢象狐兔开。
野花似雪落何处，棠棃树下香风来。
马侍中，韦太尉，盛去衰来片时事。
人生倏忽一梦中，何必深深固权位。','',''),('quantangshi-30200','老去也','薛逢','quantangshi','','卷31','惆怅人生不满百，一事无成头雪白。
回看幼累与老妻，俱是途中远行客。
匣中旧镜照胆明，昔曾见我髭未生。
朝巾暮栉不自省，老皮皴皱文纵横。
合掌髻子蒜许大，此日方知非是我。
暗数七旬能几何，不觉中肠热如火。
老去也，争奈何，敲酒盏，唱短歌。
短歌未竟日已没，月映西南庭树柯。','',''),('quantangshi-30201','追昔行','薛逢','quantangshi','','卷31','朝光如飞犹尚可，暮更如箭不容卧。
犍为穿城更漏频，一一皆从枕边过。
一夕凡几更，一更凡几声。
青春枉向镜中老，白发虚从愁里生。
曾窥帝里东邻女，自比桃花镜中许。
一朝嫁得征戌儿，荷戈千里防秋去。
去时只作旦暮期，别后生死俱不知。
风惊粉色入蝉鬓，愁送镜花潜堕枝。
前年因出长安陌，见一女人头雪白。
日中扶杖憇树阴，仿髴形容认相识。
向予吁嗟还独语，曾与君家邻舍住。
当时妾嫁与征人，几向墙头诮夫主。
花开叶洛何推迁，屈指数当三十年。
眉头薤叶同枯叶，琴上朱弦成断弦。
嫁时宝镜依然在，鹊影菱花满光彩。
梦里长嗟离别多，愁中不觉颜容改。
叹息人生能几何，喜君颜貌未蹉跎。
因君下马重相顾，请奏青门肠断歌。','',''),('quantangshi-30202','醉春风','薛逢','quantangshi','','卷31','去年春似今年春，依旧野花愁杀人。
犍为县里古城上，开是好花飞是尘。
戏蝶狂蜂相往返，一枝花上声千万。
时节先从暖处开，北枝未发南枝晚。
江城太守须髯苍，忽然置酒开华堂。
歌儿舞女亦随后，暂醉始知天地长。
顷年曾作东周掾，同舍寻春屡开宴。
斗门亭上柳如丝，洛水桥边月如练。
洛阳风俗不禁街，骑马夜归香满怀。
坐客争吟云碧句，美人醉赠珊瑚钗。
日往月来何草草，今年又校三年老。
槽中骏马不能骑，惆怅落花开满道。
为报时人知不知，看花对酒定无疑。
君看野外孤坟下，石羊石马是谁家。','',''),('quantangshi-30203','邻相反行','薛逢','quantangshi','','卷31','东家有儿年十五，只向田园独辛苦。
夜开沟水遶稻田，晓叱耕牛垦塉土。
西家有儿才弱龄，仪容清峭云鹤形。
涉书猎史无早暮，坐期朱紫如拾青。
东家西家两相诮，西儿笑东东又笑。
西云养志与荣名，彼此相非不同调。
东家自云虽辛苦，躬耕早暮及所亲。
男舂女爨二十载，堂上未为衰老人。
朝机暮织还充体，余者到兄还及弟。
春秋伏腊长在家，不许妻奴暂违礼。
尔今二十方读书，十年取第三十余。
往来途路长离别，几人便得升公车。
纵令得官身须老，衔恤终天向谁道。
百年骨肉归下泉，万里枌榆长秋草。
我今躬耕奉所天，耘锄刈获当少年。
面上笑添今日喜，肩头薪续厨中烟。
纵使此身头雪白，又有儿孙还稼穑。
家藏一卷古孝经，世世相传皆得力。
为报西家知不知，何须谩笑东家儿。
生前不得供甘滑，殁后扬名徒尔为。','',''),('quantangshi-30204','灵台家兄古镜歌','薛逢','quantangshi','','卷31','一尺圆潭深黑色，篆文如丝人不识。
耕夫云住赫连城，赫连城下亲耕得。
镜上磨莹一月余，日中渐见菱花舒。
金膏洗拭鉎涩尽，黑云吐出新蟾蜍。
人言此是千年物，百鬼闻之形暗栗。
玉匣曾经龙照来，岂宜更鉴农夫质。
有时霹雳半夜惊，窗中飞电如晦明。
盘龙鳞胀玉匣溢，牙爪触风时有声。
耕夫不解珍灵异，翻惧赫连神作祟。
十千卖与灵台兄，百丈灵湫坐中至。
溢匣水色如玉倾，儿童不敢窥泓澄。
寒光照人近不得，坐愁雷电湫中生。
吾兄吾兄须爱惜，将来慎勿虚抛掷。
兴云致雨会有时，莫谴红牀秽灵迹。','',''),('quantangshi-30205','观竞渡','薛逢','quantangshi','','卷31','三月三日天清明，杨花绕江啼晓莺。
使君未出郡斋内，江上已闻齐和声。
使君出时皆有引，马前已被红旗阵。
两岸罗衣破鼻香，银钗照日如霜刃。
鼓声三下红旗开，两龙跃出浮水来。
擢影斡波飞万劒，鼓声劈浪鸣千雷。
雷声冲急波相近，两龙望标目如瞬。
江上人呼霹雳声，竿头彩挂虹霓晕。
前船抢水已得标，后船失势空挥桡。
疮眉血首争不定，输岸一朋心似烧。
只将标示输赢赏，两岸十舟五来往。
须臾戏罢各东西，竞脱文身请书上。
吾今细观竞渡儿，何殊当路权相持。
不思得所各休去，会到摧舟折楫时。','',''),('quantangshi-30206','酬牛秀才登楼见示','薛逢','quantangshi','','卷31','旅馆再经秋，心烦嬾上楼。
年光同过隙，人事且随流。
骨肉凭书问，乡关托梦游。
所嗟山郡酒，倾尽只添忧。','',''),('quantangshi-30207','夏夜宴明月湖','薛逢','quantangshi','','卷31','夏夜宴南湖，琴觞兴不孤。
月摇天上桂，星泛浦中珠。
助照萤随舫，添盘笋迸厨。
圣朝思静默，堪守谷中愚。','',''),('quantangshi-30208','大水','薛逢','quantangshi','','卷31','暴雨逐惊雷，从风忽骤来。
浪驱三岛至，江拆二仪开。
势恐圆枢折，声疑厚轴摧。
冥心问元化，天眼几时回。','',''),('quantangshi-30209','席上酬东川严中丞叙旧见赠','薛逢','quantangshi','','卷31','昔记披云日，今逾二十年。
声名俱是梦，恩旧半归泉。
朱绂慙衰齿，红妆惨别筵。
离歌正凄切，休更促危弦。','',''),('quantangshi-30210','禁火','薛逢','quantangshi','','卷31','日日冒烟尘，忽忽禁火辰。
塞榆关水湿，边草贼回春。
岁月伤风迈，疮痍念苦辛。
沙中看白骨，肠断故乡人。','',''),('quantangshi-30211','咏柳','薛逢','quantangshi','','卷31','弱植惊风急自伤，暮来翻遣思悠扬。
曾飘紫陌随高下，敢拂朱阑竞短长。
萦砌乍飞还乍舞，扑池如雪又如霜。
莫令歧路频攀折，渐拟垂阴到画堂。','',''),('quantangshi-30212','宫词','薛逢','quantangshi','','卷31','十二楼中尽晓妆，望仙楼上望君王。
锁衔金兽连环冷，水滴铜龙昼漏长。
云髻罢梳还对镜，罗衣欲换更添香。
遥窥正殿帘开处，袍袴宫人扫御牀。','',''),('quantangshi-30213','长安春日','薛逢','quantangshi','','卷31','穷途日日困泥沙，上苑年年好物华。
荆棘不当车马道，管弦长奏绮罗家。
王孙草上悠扬蝶，少女风前烂熳花。
嬾出任从游子笑，入门还是旧生涯。','',''),('quantangshi-30214','韦寿博书斋','薛逢','quantangshi','','卷31','玄晏先生已白头，不随鵷鹭狎羣鸥。
元卿谢免开三迳，平仲朝归卧一裘。
醉后独知殷甲子，病来犹作晋春秋。
尘缨未濯今如此，野水无情处处流。','',''),('quantangshi-30215','潼关河亭','薛逢','quantangshi','','卷31','重冈如抱岳如蹲，屈曲秦川势自尊。
天地并功开帝宅，山河相凑束龙门。
橹声呕轧中流渡，柳色微茫远岸村。
满眼波涛终古事，年来惆怅与谁论。','',''),('quantangshi-30216','送衢州崔员外','薛逢','quantangshi','','卷31','笑分铜虎别京师，岭下山川想到时。
红树暗藏殷浩宅，绿萝深覆偃王祠。
风茅向暖抽书带，露竹迎风舞钓丝。
休指岩西数归日，知君已负白云期。','',''),('quantangshi-30217','开元后乐','薛逢','quantangshi','','卷31','莫奏开元旧乐章，乐中歌曲断人肠。
郐王玉笛三更咽，虢国金车十里香。
一自犬戎生苏北，便从征战老汾阳。
中原骏马搜求尽，沙苑年来草又芳。','',''),('quantangshi-30218','汉武宫辞','薛逢','quantangshi','','卷31','汉武清斋夜筑坛，自斟明水醮仙官。
殿前玉女移香案，云际金人捧露盘。
绛节几时还入梦，碧桃何处更骖鸾？
茂陵烟雨埋弓劒，石马无声蔓草寒。','',''),('quantangshi-30219','潼关驿亭','薛逢','quantangshi','','卷31','河上关门日日开，古今名利旋堪哀。
终军壮节埋黄土，杨震丰碑翳绿苔。
寸禄应知霑有分，一官常惧处非才。
犹惊往岁同袍者，尚逐江东计吏来。','',''),('quantangshi-30220','五峯隠者','薛逢','quantangshi','','卷31','烟霞壁立水溶溶，路转崖回旦暮中。
鸂鶒畏人沈涧月，山羊投石挂岩松。
高斋既许陪云宿，晚稻何妨为客舂。
今日见君嘉遯处，悔将名利役疎慵。','',''),('quantangshi-30221','上吏部崔相公','薛逢','quantangshi','','卷31','龙门曾共战惊澜，雷电浮云出浚湍。
紫府有名同羽化，碧霄无路却泥蟠。
公车未结王生袜，客路虚弹贡禹冠。
今日罏锤任真宰，暂回风水不应难。','',''),('quantangshi-30222','送刘郎中牧杭州','薛逢','quantangshi','','卷31','一州横制浙江湾，台榭参差积翠间。
楼下潮回沧海浪，枕边云起剡溪山。
吴江水色连堤阔，越俗舂声隔岸还。
圣代牧人无远近，好将能事济清闲。','',''),('quantangshi-30223','贫女吟','薛逢','quantangshi','','卷31','残妆满面泪阑干，几许幽情欲话难。
云髻嬾梳愁拆凤，翠蛾羞照恐惊鸾。
南邻送女初鸣佩，北里迎妻已梦兰。
惟有深闺顦顇质，年年长凭绣牀看。','',''),('quantangshi-30224','夜宴观妓','薛逢','quantangshi','','卷31','灯火荧煌醉客豪，卷帘罗绮艳仙桃。
纤腰怕束金蝉断，鬓髪宜簪白燕高。
愁傍翠蛾深八字，笑回丹脸利双刀。
无因得荐阳台梦，愿拂余香到緼袍。','',''),('quantangshi-30225','送西川杜司空赴镇','薛逢','quantangshi','','卷31','黑眉玄髪尚依然，紫绶金章五十年。
三入凤池操国柄，八分龙节付兵权。
东周城阙中天外，西蜀楼台落日边。
莫遣洪罏旷真宰，九流人物待陶甄。','',''),('quantangshi-30226','长安夜雨','薛逢','quantangshi','','卷31','滞雨通宵又彻明，百忧如草雨中生。
心关桂玉天难晓，运落风波梦亦惊。
压树早鸦飞不散，到窗寒鼓湿无声。
当年志气俱消尽，白发新添四五茎。','',''),('quantangshi-30227','猎骑','薛逢','quantangshi','','卷31','兵印对封入卫稀，碧空云尽早霜微。
浐川桑落雕初下，渭曲禾收兔正肥。
陌上管弦清似语，草头弓马疾如飞。
岂知万里黄云戍，血迸金疮卧铁衣。','',''),('quantangshi-30228','金城宫','薛逢','quantangshi','','卷31','忆昔明皇初御天，玉舆频此驻神仙。
龙盘藻井喷红艳，兽坐金牀吐碧烟。
云外笙歌岐薛醉，月中台榭后妃眠。
自从戎马生河雒，深锁篷莱一百年。','',''),('quantangshi-30229','惊秋','薛逢','quantangshi','','卷31','露竹风蝉昨夜秋，百年心事付东流。
明霜义分成虚话，阜俗文章惜暗投。
长笑李斯称溷鼠，每多庄叟喻牺牛。
五湖烟水盈归梦，芦荻花中一钓舟。','',''),('quantangshi-30230','六街尘','薛逢','quantangshi','','卷31','六街尘起鼓冬冬，马足车输在处通。
百役并驱衣食内，四民长走路岐中。
年光与物随流水，世事如花落晓风。
名利到身无了日，不知今古旋成空。','',''),('quantangshi-30231','悼古','薛逢','quantangshi','','卷31','细推今古事堪愁，贵贱同归土一丘。
汉武玉堂人岂在，石家金谷水空流。
光阴自旦还将暮，草木从春又到秋。
闲事与时俱不了，且将身暂醉乡游。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-30232','九华观废月池','薛逢','quantangshi','','卷31','曾发箫声水槛前，夜蟾寒沼两婵娟。
微波有恨终归海，明月无情却上天。
白鸟带将林外雪，绿荷枯尽渚中莲。
荣华不肯人间住，须读庄生第一篇。','',''),('quantangshi-30233','社日游开元观','薛逢','quantangshi','','卷31','松栢当轩蔓桂篱，古坛衰草暮风吹。
荒凉院宇无人到，寂寞烟霞只自知。
浪渍法堂余像设，水存虚殿半科仪。
因求天宝年中梦，故事分明载折碑。','',''),('quantangshi-30234','九日曲池游眺','薛逢','quantangshi','','卷31','陌上秋风动酒旗，江头丝竹竞相追。
正当海晏河清日，便是修文偃武时。
绣毂尽为行乐伴，艳歌皆属太平诗。
微臣辛忝颁尧历，一望郊原惬所思。','',''),('quantangshi-30235','九日郡斋有感','薛逢','quantangshi','','卷31','白日贪长夜更长，百般无意更思量。
三冬不见秦中雪，九日惟添鬓畔霜。
霞泛水文沈暮色，树凌金气发秋光。
楼前野菊无多少，一雨重开一番黄。','',''),('quantangshi-30236','九日嘉州发军亭即事','薛逢','quantangshi','','卷31','三江分注界平沙，何处云山是我家？
无鹤洲中翻白浪，掬金滩上折黄花。
不愁故国归无日，却恨浮名苦有涯。
向暮洒酣宾客散，水天狼籍变余霞。','',''),('quantangshi-30237','九日雨中言怀','薛逢','quantangshi','','卷31','餻果盈前益自愁，那堪风雨滞刀州。
单牀冷席他乡梦，紫榝黄花故国秋。
万里音书何寂寂，百年生计甚悠悠。
潜将满眼思家泪，洒寄长江东北流。','',''),('quantangshi-30238','题劒门先寄上西蜀杜司徒','薛逢','quantangshi','','卷31','峭壁横空限一隅，划开元气建洪枢。
梯航百货通邦计，键闭诸蛮屏帝都。
西蹙犬戎威北狄，南吞荆郢制东吴。
千年管钥谁熔范，只自先天造化炉。','',''),('quantangshi-30239','八月初一驾幸延喜楼看冠带降戎','薛逢','quantangshi','','卷31','城头旭日照阑干，城下降戎彩仗攒。
九陌尘埃千骑合，万方臣妾一声欢。
楼台乍仰中天易，衣服初回左袵难。
清水莫教波浪浊，从今赤岭属长安。','',''),('quantangshi-30240','送司徒相公赴阙','薛逢','quantangshi','','卷31','丞相衔恩赴阙时，锦城寒菊始离披。
龙媒旧识朝天路，鸡树长虚入梦枝。
十载殿廷连步武，雨来庸蜀抚疲羸。
莫愁中土无人识，自有明明圣主知。','',''),('quantangshi-30241','送灵州田尚书','薛逢','quantangshi','','卷31','阴风猎猎满旗竿，白草飕飕劒气攒。
九姓羌浑随汉节，六州蕃落从戎鞍。
霜中入塞雕弓硬，月下翻营玉帐寒。
今曰路傍谁不指，穰苴门户惯登坛。','',''),('quantangshi-30242','座中走笔送前萧使君','薛逢','quantangshi','','卷31','笙歌惨惨咽离筵，槐柳阴阴五月天。
未学苏秦荣佩印，却思平子赋归田。
芙蓉欲绽溪边蘂，杨柳初迷渡口烟。
自笑无成今老大，送君垂泪郭门前。','',''),('quantangshi-30243','重送徐州李从事商隠','薛逢','quantangshi','','卷31','晓乘征骑带犀渠，醉别都门惨袂初。
莲府望高秦御史，柳营官重汉尚书。
斩蛇泽畔人烟晓，戏马台前树影疎。
尺组挂身何用处，古来名利尽丘墟。','',''),('quantangshi-30244','醉中闻甘州','薛逢','quantangshi','','卷31','老听笙歌亦解愁，醉中因遣合甘州。
行追赤岭千山外，坐想黄河一曲流。
日暮岂堪征妇怨，路傍能结旅人愁。
左绵刺史心先死，泪满朱弦催白头。','',''),('quantangshi-30245','北亭醉后叙旧赠东川陈书记','薛逢','quantangshi','','卷31','二十年前事尽空，半随波浪半随风。
谋身喜断韩鸡尾，辱命羞携楚鹊笼。
符竹谬分锦水外，妻孥犹隔散关东。
临岐莫怪朱弦绝，曾是君家入爨桐。','',''),('quantangshi-30246','宣政殿前陪位观册顺宗宪宗皇帝尊号','薛逢','quantangshi','','卷31','楼头钟鼓遰相催，曙色当衙晓仗开。
孔雀扇分香案出，兖龙衣动册函来。
金泥照耀传中旨，玉节从容引上台。
盛礼永尊徽号毕，圣慈南面不胜哀。','',''),('quantangshi-30247','元日楼前观仗 一','薛逢','quantangshi','','卷31','千门曙色鏁寒梅，五夜疎钟晓箭催。
宝马占堤朝阙去，香车争路进名来。
天临玉几班初合，日照金鸡仗欲回。
更傍紫微瞻北斗，上林佳气满楼台。','',''),('quantangshi-30248','元日楼前观仗 二','薛逢','quantangshi','','卷31','曈曈初日照楼台，漠漠祥云雉扇开。
星驻冕旒三殿晓，云翻珠翠六宫来。
山呼圣寿烟霞动，风转金章鸟兽回。
欲识普恩无远近，万方欢忭一声雷。','',''),('quantangshi-30249','醉中看花因思去岁之任','薛逢','quantangshi','','卷31','去岁乘轺出上京，军机旦暮促前程。
狂花野草途中恨，春月秋风劒外情。
愁见瘴烟遮路色，厌闻溪水下滩声。
不辞醉伴诸年少，羞对红妆白发生。','',''),('quantangshi-30250','题白马驿','薛逢','quantangshi','','卷31','晚麦芒干风似秋，旅人方作蜀门游。
家林渐隔梁山远，客路长依汉水流。
满壁存亡俱是梦，百年荣辱尽堪愁。
胸中愤气文难遣，强指丰碑哭武侯。','',''),('quantangshi-30251','题筹笔驿','薛逢','quantangshi','','卷31','天地三分魏蜀吴，武侯倔起赞讦谟。
身依豪杰倾心术，目对云山演阵图。
赤伏运衰功莫就，皇纲力振命先徂。
出师表上留遗恳，犹自千年激壮夫。','',''),('quantangshi-30252','贺杨收作相','薛逢','quantangshi','','卷31','阙下憧憧车马尘，沈浮相次宦游身。
须知金印朝天客，同是沙堤避路人。
威凤偶时因瑞圣，应龙无水谩通神。
立门不是趋时客，始向穷途学问津。','',''),('quantangshi-30253','元日田家','薛逢','quantangshi','','卷31','南村晴雪北村梅，树里茅檐晓尽开。
蛮榼出门儿妇去，乌龙迎路女郎来。
相逢但祝新正寿，对举那愁暮景催。
长笑士林因宦别，一官轻是十年回。','',''),('quantangshi-30254','送庆上人归湖州因寄道儒座主','薛逢','quantangshi','','卷31','上人今去白苹洲，霅水苕溪我旧游。
夜雨暗江渔火出，夕阳沈浦雁花收。
闲听别鸟啼红树，醉看归僧棹碧流。
若见儒公凭寄语，数茎霜鬓已惊秋。','',''),('quantangshi-30255','早发剡山','薛逢','quantangshi','','卷31','正怀何谢俯长流，更览余封识嵊州。
树色老依官舍晚，溪声凉傍客衣秋。
南岩气爽横郛郭，天姥云晴拂寺楼。
日暮不堪还上马，蓼花风起路悠悠。','',''),('quantangshi-30256','题春台观','薛逢','quantangshi','','卷31','殿前松柏晦苍苍，杏遶仙坛水遶廊。
垂露额题精思院，博山炉褭降真香。
苔侵古碣迷陈事，云到中峯失上方。
便拟寻溪弄花去，洞天谁更待刘郎。','',''),('quantangshi-30257','春晚东园晓思','薛逢','quantangshi','','卷31','劒外春余日更长，东园留醉乐高张。
松杉露滴无情泪，桃杏风飘不语香。
莺恋叶深啼绿树，燕窥巢稳坐雕梁。
也知留滞年华晚，争那罇前乐未央。','',''),('quantangshi-30258','芙蓉溪送前资州裴使君归京宁拜户部裴侍郎','薛逢','quantangshi','','卷31','桑柘林枯𪍷麦干，欲分离袂百忧攒。
临溪莫话前途远，举酒须歌后会难。
薄宦未甘霜髪改，夹衣犹耐水风寒。
遥知阮巷归宁日，几院儿童候马看。','',''),('quantangshi-30259','伏闻令公疾愈对见延英因有贺诗远封投献','薛逢','quantangshi','','卷31','吉语云云海外传，令公疾愈起朝天。
皇风再扇寰区内，人镜重开日月边。
光启四门通寿域，深疏万顷溉情田。
陪臣自讶迷津久，愿识方舟济巨川。','',''),('quantangshi-30260','题独孤处士村居','薛逢','quantangshi','','卷31','江上园卢荆作扉，男驱耕犊妇鸣机。
林峦当户茑萝暗，桑柘绕村姜芋肥。
几亩稻田还谓业，两间茆舍亦言归。
何如一被风尘染，到老云云相是非。','',''),('quantangshi-30261','题上皇观','薛逢','quantangshi','','卷31','狂寇穷兵犯帝畿，上皇曾此振戎衣。
门前卫士传清警，砌下奚官扫翠微。
云驻寿宫三洞启，日回仙仗六龙归。
当时丹凤衔书处，老柏苍苍已合围。','',''),('quantangshi-30262','奉和仆射相公送东川李支使归使府夏侯相公','薛逢','quantangshi','','卷31','两地交通布政和，上台深喜使星过。
欢留白日千钟酒，调入青云一曲歌。
寒柳翠添微雨重，腊梅香绽细枝多。
平津万一言卑散，莫忘高松寄女萝。','',''),('quantangshi-30263','送封尚书节制兴元','薛逢','quantangshi','','卷31','大封茅土镇襃中，醉出都门杀气雄。
陌上晚花迎虎节，马前新月学弯弓。
珂临响涧声先合，斾到春山色更红。
欲识真心报天子，满旗全是发生风。','',''),('quantangshi-30264','送西川梁常侍之新筑龙山城并锡赉两州刺史及部落酋长等','薛逢','quantangshi','','卷31','圣主忧夷貊，屯师翦束钦。
皇家思眷佑，星使忽登临。
用命期开国，违天必衅砧。
化须均草树，恩不间飞沈。
束马凌苍壁，扪萝上碧岑。
瘴川风自热，劒阁气长阴。
迅濑从天急，乔松入地深。
仰观唯一迳，俯瞰即千寻。
水作新城带，山为故垒襟。
东开洞君听，南辟纳蛮心。
渥泽濡三部，衣冠化雨林。
带文雕白玉，符理篆黄金。
鸟道经邛𤏡，星缠过觜参。
回轩如睿奖，休作苦辛吟。','',''),('quantangshi-30265','河满子','薛逢','quantangshi','','卷31','系马宫槐老，持杯店菊黄。
故交今不见，流恨满川光。','',''),('quantangshi-30266','题黄花驿','薛逢','quantangshi','','卷31','孤戍迢迢蜀路长，鸟鸣山馆客思乡。
更看绝顶烟霞外，数树岩花照夕阳。','',''),('quantangshi-30267','凉州词','薛逢','quantangshi','','卷31','昨夜蕃兵报国讐，沙州都护破凉州。
黄河九曲今归汉，塞外纵横战血流。','',''),('quantangshi-30268','嘉陵江','薛逢','quantangshi','','卷31','备问嘉陵江水湄，百川东去尔西之。
但教清浅源流在，天路朝宗会有期。','',''),('quantangshi-30269','观猎','薛逢','quantangshi','','卷31','马缩寒毛鹰落膘，角弓初暖箭新调。
平原踏尽无禽出，竟日翻身望碧霄。','',''),('quantangshi-30270','狼烟','薛逢','quantangshi','','卷31','三道狼烟过碛来，受降城上探旗开。
传声却报边无事，自是官军入抄回。','',''),('quantangshi-30271','侠少年','薛逢','quantangshi','','卷31','绿眼胡鹰踏锦韝，五花騘马白貂裘。
往来三市无人识，倒把金鞭上酒楼。','',''),('quantangshi-30272','感塞','薛逢','quantangshi','','卷31','满塞旌旗镇上游，各分天子一方忧。
无因得见哥舒翰，可惜西山十八州。','',''),('quantangshi-30273','听曹刚弹琵琶','薛逢','quantangshi','','卷31','禁曲新翻下玉都，四弦掁触五音殊。
不知天上弹多少，金凤衔花尾半无。','',''),('quantangshi-30274','定山寺','薛逢','quantangshi','','卷31','十里松萝映碧苔，一川晴色镜中开。
遥闻上界翻经处，片片香云出院来。','',''),('quantangshi-30275','越王楼送高梓州入朝','薛逢','quantangshi','','卷31','乘递初登建外州，倾心喜事富人侯。
方当游艺依仁日，便到攀辕卧辙秋。
容听巴歌消子夜，许陪仙躅上危楼。
欲知恨恋情深处，听取长江旦暮流。','',''),('quantangshi-30276','送李蕴赴郑州因献卢郎中','薛逢','quantangshi','','卷31','仆射陂西想到时，满川晴色见旌旗。
马融闲卧笛声远，王粲醉吟楼影移。
几日赋诗秋水寺，经年草诏白云司。
唯君此去人多羡，却是恩深自不知。','',''),('quantangshi-30277','送裴评事','薛逢','quantangshi','','卷31','塞垣从事识兵机，只拟平戎不拟归。
入夜茄声含白髪，报秋榆叶落征衣。
城临战垒黄云晚，马渡寒沙夕照微。
此别不应书断绝，满天霜雪有鸿飞。','',''),('quantangshi-30278','送沈单作尉江都','薛逢','quantangshi','','卷31','炀帝都城春水边，笙歌夜上木兰船。
三千宫女自涂地，十万人家如洞天。
焰焰花枝官舍晚，重重云影寺墙连。
少年作尉须矜慎，莫向楼前坠马鞭。','',''),('quantangshi-30279','送薛耽先辈归谒汉南','薛逢','quantangshi','','卷31','云绕千峰驿路长，谢家联句待檀郎。
手持碧落新攀桂，月在东轩旧选牀。
几日旌幢延骏马，到时冰玉动华堂。
孔门多少风流处，不遣颜回识醉乡。','',''),('quantangshi-30280','送同年郑祥先辈归汉南','薛逢','quantangshi','','卷31','年来惊喜两心知，高处同攀次第枝。
人倚绣屏闲赏夜，马嘶花径醉归时。
声名本自文章得，藩溷曾劳笔砚随。
家去恩门四千里，只应从此梦旌旗。','',''),('quantangshi-30281','李先辈擢第东归有赠送','薛逢','quantangshi','','卷31','金榜前头无是非，平人分得一枝归。
正怜日暖云飘路，何处宴回风满衣？
门掩长淮心更远，渡连芳草马如飞。
茂陵自笑犹多病，空有书斋在翠微。','',''),('quantangshi-30282','送韩绛归淮南寄韩绰先辈','薛逢','quantangshi','','卷31','岛上花枝系钓船，隋家宫畔水连天。
江帆自落鸟飞外，月观静依春色边。
门巷草生车辙在，朝廷恩及雁行联。
相逢且问昭州事，曾鼓庄盆对逝川。','',''),('quantangshi-30283','送卢缄归扬州','薛逢','quantangshi','','卷31','曾向雷塘寄掩扉，荀家灯火有余辉。
关河日暮望空极，杨柳渡头人独归。
隋苑荒台风褭褭，灞陵残雨梦依依。
今年春色还相悞，为我江边谢钓矶。','',''),('quantangshi-30284','送剡客','薛逢','quantangshi','','卷31','两重江外片帆斜，数里林塘遶一家。
门掩右军余水石，路横诸谢旧烟霞。
扁舟几处逢溪雪，长笛何人怨柳花。
若到天台洞阳观，葛洪丹井在云涯。','',''),('quantangshi-30285','凉州词 一','薛逢','quantangshi','','卷31','千里东归客，无心忆旧游。
挂帆游□水，高枕到青州。','',''),('quantangshi-30286','凉州词 二','薛逢','quantangshi','','卷31','君住孤山下，烟深夜径长。
辕门渡绿水，游苑遶垂杨。','',''),('quantangshi-30287','凉州词 三','薛逢','quantangshi','','卷31','树发花如锦，莺啼柳若丝。
更游懽宴地，愁见别离时。','',''),('quantangshi-30288','送萧俛相公归山','薛逢','quantangshi','','卷31','眼前轩冕是鸿毛，天上人情谩自劳。
脱却朝衣便东去，青云不及白云高。','',''),('quantangshi-30289','石膏枕','薛逢','quantangshi','','卷31','表里通明不假雕，冷于春雪白于瑶。
朝来送在凉牀上，只怕风吹日炙销。','',''),('quantangshi-30290','句','薛逢','quantangshi','','卷31','草荒留客院，泥卧喂生台。
碧碎鸳鸯瓦，香埋菡萏罏。
初日晖晖上彩旄。
金鞍俯鞚尘开处，银镝离弦中处声。
昨日鸿毛万钧重，今朝山岳一朝轻。','',''),('quantangshi-30291','汾上宴别','趙嘏','quantangshi','','卷31','云物如故乡，山川知异路。
年来未归客，马上春色暮。
一尊花下酒，残日水西树。
不待管弦终，摇鞭背花去。','',''),('quantangshi-30292','书斋雪后','趙嘏','quantangshi','','卷31','拥褐坐茅檐，春晴喜初日。
微风入桃径，爽气归缥帙。
频时苦风雪，就景理巾栉。
树暖高鸟来，窗闲曙云出。
乡遥路难越，道蹇时易失。
欲静又不能，东山负芝术。','',''),('quantangshi-30293','寄道者','趙嘏','quantangshi','','卷31','洞庭先生归路长，海云望极春茫茫。
别来几度向蓬岛，自傍瑶台折灵草。','',''),('quantangshi-30294','虎丘寺赠渔处士','趙嘏','quantangshi','','卷31','兰若云深处，前年客重过。
岩空秋色动，水阔夕阳多。
早负江湖志，今如鬓发何。
唯思闲胜我，钓艇在烟波。','',''),('quantangshi-30295','陪崔璞侍御和崔㻂春日有怀','趙嘏','quantangshi','','卷31','诗家本多感，况值广陵春。
暖驻含窗日，香余醉袖尘。
浮名皆有分，一笑最关身。
自此容依托，清才两故人。','',''),('quantangshi-30296','昔昔盐二十首 垂柳覆金堤','趙嘏','quantangshi','','卷31','新年垂柳色，袅袅对空闺。
不畏芳菲好，自缘离别啼。
因风飘玉户，向日映金堤。
驿使何时度，还将赠陇西。','',''),('quantangshi-30297','昔昔盐二十首 蘼芜叶复齐','趙嘏','quantangshi','','卷31','提筐红叶下，度日采蘼芜。
掬翠香盈袖，看花忆故夫。
叶齐谁复见，风暖恨偏孤。
一被春光累，容颜与昔殊。','',''),('quantangshi-30298','昔昔盐二十首 水溢芙蓉沼','趙嘏','quantangshi','','卷31','渌沼春光后，青青草色浓。
绮罗惊翡翠，暗粉妬芙蓉。
云遍窗前见，荷翻镜里逢。
将心托流水，终日渺无从。','',''),('quantangshi-30299','昔昔盐二十首 花飞桃李蹊','趙嘏','quantangshi','','卷31','远期难可托，桃李自依依。
花径无容迹，戎裘未下机。
随风开又落，度日扫还飞。
欲折枝枝赠，那知归不归。','',''),('quantangshi-30300','昔昔盐二十首 采桑秦氏女','趙嘏','quantangshi','','卷31','南陌采桑出，谁知妾姓秦。
独怜倾国貌，不负早莺春。
珠履荡花湿，龙钩折桂新。
使君那驻马，自有侍中人。','',''),('quantangshi-30301','昔昔盐二十首 织锦窦家妻','趙嘏','quantangshi','','卷31','当年谁不羡，分作窦家妻。
锦字行行苦，罗帏日日啼。
岂知登陇远，秪恨下机迷。
直候阳关使，殷勤寄海西。','',''),('quantangshi-30302','昔昔盐二十首 关山别荡子','趙嘏','quantangshi','','卷31','那堪闻荡子，迢递涉关山。
肠为马嘶断，衣从泪滴斑。
愁看塞上路，讵惜镜中颜。
傥见征西雁，应传一字还。','',''),('quantangshi-30303','昔昔盐二十首 风月守空闺','趙嘏','quantangshi','','卷31','良人犹远戍，耿耿夜闺空。
绣户流宵月，罗帏坐晚风。
魂飞沙帐北，肠断玉关中。
尚自无消息，锦衾那得同。','',''),('quantangshi-30304','昔昔盐二十首 恒歛千金笑','趙嘏','quantangshi','','卷31','玉颜恒自歛，羞出镜台前。
早惑阳城客，今悲华锦筵。
从军人更远，投喜鹊空传。
夫壻交河北，迢迢路几千。','',''),('quantangshi-30305','昔昔盐二十首 长垂双玉啼','趙嘏','quantangshi','','卷31','双双红泪堕，度日暗中啼。
雁出居延北，人犹辽海西。
向灯垂玉枕，对月洒金闺。
不惜罗衣湿，惟愁归意迷。','',''),('quantangshi-30306','昔昔盐二十首 蟠龙随镜隐','趙嘏','quantangshi','','卷31','鸾镜无由照，蛾眉岂忍看。
不知愁发换，空见隐龙蟠。
那惬红颜改，偏伤白日残。
今朝窥玉匣，双泪落阑干。','',''),('quantangshi-30307','昔昔盐二十首 彩凤逐帷低','趙嘏','quantangshi','','卷31','巧绣双飞凤，朝朝伴下帷。
春花那见照，暮色已频欺。
欲卷思君处，将啼裛泪时。
何年征戍客，传语报佳期。','',''),('quantangshi-30308','昔昔盐二十首 惊魂同夜鹊','趙嘏','quantangshi','','卷31','万里无人见，众情难与论。
思君常入梦，同鹊屡惊魂。
孤寝红罗帐，双啼玉筯痕。
妾心甘自保，岂复暂忘恩。','',''),('quantangshi-30309','昔昔盐二十首 倦寝听晨鸡','趙嘏','quantangshi','','卷31','去去边城骑，愁眠掩夜闺。
披衣窥落月，拭泪待鸣鸡。
不愤连年别，那看长夜啼。
功成应自恨，早晚发辽西。','',''),('quantangshi-30310','昔昔盐二十首 暗牑悬蛛网','趙嘏','quantangshi','','卷31','暗中蛛网织，历乱绮窗前。
万里终无信，一条徒自悬。
分从珠露滴，愁见隟风牵。
妾意何聊赖，看看剧断弦。','',''),('quantangshi-30311','昔昔盐二十首 空梁落燕泥','趙嘏','quantangshi','','卷31','春至今朝燕，花时伴独啼。
飞斜珠箔隔，语近画梁低。
帷卷闲窥户，牀空暗落泥。
谁能长对此，双去复双栖。','',''),('quantangshi-30312','昔昔盐二十首 前年过代北','趙嘏','quantangshi','','卷31','代北几千里，前年又复经。
燕山云自合，胡塞草应青。
铁马喧鼙鼓，蛾眉怨锦屏。
不知羌笛曲，掩泪若为听。','',''),('quantangshi-30313','昔昔盐二十首 今岁往辽西','趙嘏','quantangshi','','卷31','万里飞书至，闻君已渡辽。
秪谙新别苦，忘却旧时娇。
烽戍年将老，红颜日向雕。
胡沙兼汉苑，相望几迢迢。','',''),('quantangshi-30314','昔昔盐二十首 一去无还意','趙嘏','quantangshi','','卷31','良人征绝域，一去不言还。
百战攻胡虏，三冬阻玉关。
萧萧边马思，猎猎戍旗闲。
独抱千重恨，连年未解颜。','',''),('quantangshi-30315','昔昔盐二十首 那能惜马蹄','趙嘏','quantangshi','','卷31','云中路杳杳，江畔草凄凄。
妾久垂珠泪，君何惜马蹄。
边风悲晓角，营月怨春鼙。
未道休征战，愁眉又复低。','',''),('quantangshi-30316','送韦处士归省朔方','趙嘏','quantangshi','','卷31','映柳见行色，故山当落晖。
青云知已殁，白首一身归。
满袖萧关雨，连沙塞雁飞。
到家翻有喜，借取老莱衣。','',''),('quantangshi-30317','送权先辈归觐信安','趙嘏','quantangshi','','卷31','衣彩独归去，一枝兰更香。
马嘶芳草渡，门掩百花塘。
野色亭台晚，滩声枕簟凉。
小斋松岛上，重叶覆书堂。','',''),('quantangshi-30318','风蝉','趙嘏','quantangshi','','卷31','风蝉旦夕鸣，伴夜送秋声。
故里客归尽，水边身独行。
噪轩高树合，惊枕暮山横。
听处无人见，尘埃满甑生。','',''),('quantangshi-30319','重寄卢中丞','趙嘏','quantangshi','','卷31','贱子来还去，何人伴使君。
放歌迎晚醉，指路上高云。
此夜雁初至，空山雨独闻。
别多头欲白，惆怅惜余醺。','',''),('quantangshi-30320','晓发','趙嘏','quantangshi','','卷31','旅行宜蚤发，况复是南归。
月影缘山尽，钟声隔浦微。
星残萤共映，叶落鸟惊飞。
去去渡南渚，树深人出稀。','',''),('quantangshi-30321','送友人郑州归觐','趙嘏','quantangshi','','卷31','为有趋庭恋，应忘道路赊。
风消荥泽冻，雨静圃田沙。
古陌人来远，遥天雁势斜。
园林新到日，春酒酌梨花。','',''),('quantangshi-30322','洛中逢卢郢石归觐','趙嘏','quantangshi','','卷31','不堪俱失意，相送出东周。
缘切倚门恋，倍添为客愁。
春山和雪静，寒水带冰流。
别后期君处，灵源紫阁秋。','',''),('quantangshi-30323','赠越客','趙嘏','quantangshi','','卷31','故国波涛隔，明时心久留。
献书双阙晚，看月五陵秋。
南棹何当返，长江忆共游。
定知钓鱼伴，相望在汀州。','',''),('quantangshi-30324','经无锡县醉后吟','趙嘏','quantangshi','','卷31','客过无名姓，扁舟系柳阴。
穷秋南国泪，残日故乡心。
京洛衣尘在，江湖酒病深。
何须觅陶令，乘醉自横琴。','',''),('quantangshi-30325','东归道中二首 一','趙嘏','quantangshi','','卷31','平生事行役，今日始知非。
岁月老将至，江湖春未归。
传家有天爵，主祭用儒衣。
何必劳知己，无名亦息机。','',''),('quantangshi-30326','东归道中二首 二','趙嘏','quantangshi','','卷31','未明唤僮仆，江上忆残春。
风雨落花夜，山川驱马人。
星星一镜发，草草百年身。
此日念前事，沧洲情更亲。','',''),('quantangshi-30327','旅次商山','趙嘏','quantangshi','','卷31','役役依山水，何曾似问津。
断崖如避马，芳树欲留人。
日夕猿鸟伴，古今京洛尘。
一枝甘已失，辜负故园春。','',''),('quantangshi-30328','长洲','趙嘏','quantangshi','','卷31','扁舟殊不系，浩荡路才分。
范蠡湖中树，吴王苑外云。
悲心人望月，独夜雁离羣。
明发还驱马，关城见日曛。','',''),('quantangshi-30329','江边','趙嘏','quantangshi','','卷31','终日劳车马，江边款竹扉。
残花春浪阔，小酒故人稀。
戍鼓客帆远，津云夕照微。
何由兄与弟，俱及暮春归。','',''),('quantangshi-30330','宿灵岩寺','趙嘏','quantangshi','','卷31','明月溪头寺，虫声满橘洲。
倚栏香径晚，移石太湖秋。
古树云归尽，荒台水更流。
无人见惆怅，独上最高楼。','',''),('quantangshi-30331','越中寺居','趙嘏','quantangshi','','卷31','迟客疎林下，斜溪小艇通。
野桥连寺月，高竹半楼风。
水静鱼吹浪，枝闲鸟下空。
数峰相向绿，日夕郡城东。','',''),('quantangshi-30332','赠金刚三藏','趙嘏','quantangshi','','卷31','心法云无住，流沙归复来。
锡随山鸟动，经附海船回。
洗足柳遮寺，坐禅花委苔。
惟将一童子，又欲过天台。','',''),('quantangshi-30333','长安晚秋','趙嘏','quantangshi','','卷31','云物凄凉拂曙流，汉家宫阙动高秋。
残星几点雁横塞，长笛一声人倚楼。
紫艳半开篱菊静，红衣落尽渚莲愁。
鲈鱼正美不归去，空戴南冠学楚囚。','',''),('quantangshi-30334','齐安早秋','趙嘏','quantangshi','','卷31','流年堪惜又堪惊，砧杵风来满郡城。
高鸟过时秋色动，征帆落处暮云平。
思家正叹江南景，听角仍含塞北情。','',''),('quantangshi-30335','东望','趙嘏','quantangshi','','卷31','楚江横在草堂前，杨柳洲西载酒船。
两见梨花归不得，每逢寒食一潸然。
斜阳映阁山当寺，微绿含风月满川。
同郡故人攀桂尽，把诗吟向泬寥天。','',''),('quantangshi-30336','长安月夜与友人话故山','趙嘏','quantangshi','','卷31','宅边秋水浸苔矶，日日持竿去不归。
杨柳风多潮未落，蒹葭霜冷雁初飞。
重嘶匹马吟红叶，却听疎钟忆翠微。
今夜秦城满楼月，故人相见一沾衣。','',''),('quantangshi-30337','题横水驿双峰院松','趙嘏','quantangshi','','卷31','故园溪上雪中别，野馆门前云外逢。
白发渐多何事苦，清阴长在好相容。
迎风几拂朝天骑，带月犹含度岭钟。
更忆葛洪丹井畔，数株临水欲成龙。','',''),('quantangshi-30338','发剡中','趙嘏','quantangshi','','卷31','正怀何谢俯长流，更览余封识嵊州。
树色老依官舍晚，溪声凉傍客衣秋。
南岩气爽横郛郭，天姥云晴拂寺楼。
日暮不堪还上马，蓼花风起路悠悠。','',''),('quantangshi-30339','登安陆西楼','趙嘏','quantangshi','','卷31','楼上华筵日日开，眼前人事祗堪哀。
征车自入红尘去，远水长穿绿树来。
云雨暗更歌舞伴，山川不尽别离杯。
无由并写春风恨，欲下郧城首重回。','',''),('quantangshi-30340','九日陪越州元相燕龟山寺','趙嘏','quantangshi','','卷31','佳晨何处泛花游，丞相筵开水上头。
双影斾摇山雨霁，一声歌动寺云秋。
林光静带高城晚，湖色寒分半槛流。
共贺万家逢此节，可怜风物似荆州。','',''),('quantangshi-30341','经汉武泉','趙嘏','quantangshi','','卷31','芙蓉苑里起清秋，汉武泉声落御沟。
他日江山映蓬鬓，二年杨柳别渔舟。
竹间驻马题诗去，物外何人识醉游。
尽把归心付红叶，晚来随水向东流。','',''),('quantangshi-30342','曲江春望怀江南故人','趙嘏','quantangshi','','卷31','杜若洲边人未归，水寒烟暖想柴扉。
故园何处风吹柳，新雁南来雪满衣。
目极思随原草遍，浪高书到海门稀。
此时愁望情多少，万里春流遶钓矶。','',''),('quantangshi-30343','上令狐相公','趙嘏','quantangshi','','卷31','鹗在卿云冰在壶，代天才业奉訏谟。
荣同伊陟传朱户，秀比王商入画图。
昨夜星辰回剑履，前年风月满江湖。
不知机务时多暇，犹许诗家属和无。','',''),('quantangshi-30344','忆山阳','趙嘏','quantangshi','','卷31','家在枚臯旧宅边，竹轩晴与楚坡连。
芰荷香遶垂鞭袖，杨柳风横弄笛船。
城碍十洲烟岛路，寺临千顷夕阳川。
可怜时节堪归去，花落猿啼又一年。','',''),('quantangshi-30345','二','趙嘏','quantangshi','','卷31','折柳城边起暮愁，可怜春色独怀忧。
伤心正叹人间事，回首更惭江上鸥。
鶗鴂声中寒食雨，芙蓉花外夕阳楼。
凭高满眼送清渭，去傍故山山下流。','',''),('quantangshi-30346','送僧归庐山','趙嘏','quantangshi','','卷31','禅栖忽忆五峰游，去着方袍谢列侯。
经启楼台千叶曙，锡含风雨一枝秋。
题诗片石侵云在，洗钵香泉覆菊流。
却忆前年别师处，马嘶残月虎溪头。','',''),('quantangshi-30347','赠天卿寺神亮上人','趙嘏','quantangshi','','卷31','五看春尽此江濆，花自飘零日自曛。
空有慈悲随物念，已无踪迹在人羣。
迎秋日色檐前见，入夜钟声竹外闻。
笑指白莲心自得，世间烦恼是浮云。','',''),('quantangshi-30348','降虏','趙嘏','quantangshi','','卷31','广武溪头降虏稀，一声寒角怨金微。
河湟不在春风地，歌舞空裁雪夜衣。
铁马半嘶边草去，狼烟高映塞鸿飞。
扬雄尚白相如吃，今日何人从猎归。','',''),('quantangshi-30349','平戎','趙嘏','quantangshi','','卷31','边声一夜殷秋鼙，牙帐连烽拥万蹄。
武帝未能忘塞北，董生才足使胶西。
冰横晓渡胡兵合，雪满穷沙汉骑迷。
自古平戎有良策，将军不用倚云梯。','',''),('quantangshi-30350','宿楚国寺有怀','趙嘏','quantangshi','','卷31','风动衰荷寂寞香，断烟残月共苍苍。
寒生晚寺波摇壁，红堕疎林叶满牀。
起雁似惊南浦棹，阴云欲护北楼霜。
江边松菊荒应尽，八月长安夜正长。','',''),('quantangshi-30351','早发剡中石城寺','趙嘏','quantangshi','','卷31','暂息劳生树色间，平明机虑又相关。
吟辞宿处烟霞去，心负秋来水石闲。
竹户半开钟未绝，松枝静霁鹤初还。
明朝一倍堪惆怅，回首尘中见此山。','',''),('quantangshi-30352','寄归','趙嘏','quantangshi','','卷31','三年踏尽化衣尘，只见长安不见春。
马过雪街天未曙，客迷关路泪空频。
桃花坞接啼猿寺，野竹庭通画鷁津。
早晚相酬身事了，水边归去一闲人。','',''),('quantangshi-30353','献淮南李相公','趙嘏','quantangshi','','卷31','傅岩高静见台星，庙畧当时讨不庭。
万里有云归碧落，百川无浪到沧溟。
军中老将传兵术，江上诸侯受政经。
闻道国人思再入，镕金新铸鹤仪形。','',''),('quantangshi-30354','宛陵寓居上沈大夫二首 一','趙嘏','quantangshi','','卷31','满耳歌谣满眼山，宛陵城郭翠微间。
人情已觉春长在，溪户仍将水共闲。
晓色入楼红蔼蔼，夜声寻砌碧潺潺。
幽云高鸟俱无事，晚伴西风醉客还。','',''),('quantangshi-30355','宛陵寓居上沈大夫二首 二','趙嘏','quantangshi','','卷31','溪树参差绿可攀，谢家云水满东山。
能忘天上他年贵，来结林中一日闲。
醉叩玉盘歌褭褭，暖鸣幽涧鸟关关。
觥筹不尽须归去，路在春风缥缈间。','',''),('quantangshi-30356','淮信贺滕迈台州','趙嘏','quantangshi','','卷31','凋瘵民思太古风，上贤绥辑副宸衷。
舟移清镜禹祠北，路转翠屏天姥东。
旌斾影前横竹马，咏歌声里乐樵童。
遥知到郡沧波晏，三岛离离一望中。','',''),('quantangshi-30357','下第寄宣城幕中诸公','趙嘏','quantangshi','','卷31','一醉曾将万事齐，暂陪欢去便如泥。
黄花李白墓前路，碧浪桓彝宅后溪。
九月霜中随计吏，十年江上灌春畦。
莫言春尽不惆怅，自有闲眠到日西。','',''),('quantangshi-30358','送令狐郎中赴郢州','趙嘏','quantangshi','','卷31','佐幕才多始拜侯，一门清贵动神州。
霜蹄晓驻秦云断，野斾晴翻郢树秋。
几处尘生随候骑，半江帆尽见分流。
大冯罢相吟诗地，莫惜频登白雪楼。','',''),('quantangshi-30359','送卢缄归扬州','趙嘏','quantangshi','','卷31','曾向雷塘寄掩扉，荀家灯火有余辉。
关河日暮望空极，杨柳渡头人独归。
隋苑荒台风褭褭，灞陵残雨梦依依。
今年春色还相悞，为我江边谢钓矶。','',''),('quantangshi-30360','送李裴评事','趙嘏','quantangshi','','卷31','塞垣从事识兵机，只拟平戎不拟归。
入夜笳声含白发，报秋榆叶落征衣。
城临战垒黄云晚，马渡寒沙夕照微。
此别不应书断绝，满天霜雪有鸿飞。','',''),('quantangshi-30361','别麻氏','趙嘏','quantangshi','','卷31','晓哭呱呱动四隣，于君我作负心人。
出门便涉东西路，回首初惊枕席尘。
满眼泪珠和语咽，旧窗风月更谁亲。
分离况值花时节，从此东风不似春。','',''),('quantangshi-30362','代人赠别','趙嘏','quantangshi','','卷31','月自斜窗梦自惊，衷肠中有万愁生。
清猿处处三声尽，碧落悠悠一水横。
平子定情词丽绝，诗人匪石誓分明。
会须携手乘鸾去，箫史楼台在玉京。','',''),('quantangshi-30363','寒食新丰别友人','趙嘏','quantangshi','','卷31','一百五日家未归，新丰鸡犬独依依。
满楼春色傍人醉，半夜雨声前计非。
缭绕沟塍含绿晚，荒凉树石向川微。
东风吹泪对花落，憔悴故交相见稀。','',''),('quantangshi-30364','李侍御归山同宿华严寺','趙嘏','quantangshi','','卷31','家有青山近玉京，风流柱史早知名。
园林手植自含绿，霄汉眼看当去程。
处处白云迷驻马，家家红树近流莺。
相逢一宿最高寺，夜夜翠微泉落声。','',''),('quantangshi-30365','今年新先辈以遏密之际每有宴集必资清谈书此奉贺','趙嘏','quantangshi','','卷31','天上高高月桂丛，分明三十一枝风。
满怀春色向人动，遮路乱花迎马红。
鹤驭回飘云雨外，兰亭不在管弦中。
居然自是前贤事，何必青楼倚翠空。','',''),('quantangshi-30366','自遣','趙嘏','quantangshi','','卷31','晚树疎蝉起别愁，远人回首忆沧洲。
江连故国无穷恨，日带残云一片秋。
久客转谙时态薄，多情只共酒淹留。
到头生长烟霞者，须向烟霞老始休。','',''),('quantangshi-30367','浙东陪元相公游云门寺','趙嘏','quantangshi','','卷31','松下山前一径通，烛迎千骑满山红。
溪云乍歛幽岩雨，晓气初高大斾风。
小槛宴花容客醉，上方看竹与僧同。
归来吹尽严城角，路转横塘乱水东。','',''),('quantangshi-30368','陪韦中丞宴扈都头花园','趙嘏','quantangshi','','卷31','门下烟横载酒船，谢家携客醉华筵。
寻花偶坐将军树，饮水方重刺史天。
几曲艳歌春色里，断行高鸟暮云边。
分明听得舆人语，愿及行春更一年。','',''),('quantangshi-30369','花园即事呈常中丞','趙嘏','quantangshi','','卷31','烟暖池塘柳覆台，百花园里看花来。
烧衣焰席三千树，破鼻醒愁一万杯。
不肯为歌随拍落，却因令舞带香回。
山公仰尔延宾客，好傍春风次第开。','',''),('quantangshi-30370','宿何书记先辈延福新居','趙嘏','quantangshi','','卷31','松下有琴闲未收，一灯高为石丛留。
诗情似到山家夜，树色轻含御水秋。
小榼提携终永日，半斑容鬓漫生愁。
因君抚掌问时俗，紫阁堆檐不举头。','',''),('quantangshi-30371','秦中逢王处士','趙嘏','quantangshi','','卷31','万水东流去不回，先生独自负仙才。
蘂宫横浪海边别，鹤翅驻云天上来。
几处吹箫森羽卫，谁家残月下楼台。
春风正好分琼液，乞取当时白玉杯。','',''),('quantangshi-30372','江上逢许逸人','趙嘏','quantangshi','','卷31','是非处处生尘埃，唯君襟抱无嫌猜。
收帆依雁湓浦宿，带雨别僧衡岳回。
芳罇稍驻落日唱，醉袖更拂长云开。
清秋华发好相似，却把钓竿归去来。','',''),('quantangshi-30373','和令狐补阙春日独游西街','趙嘏','quantangshi','','卷31','左掖初辞近侍班，马嘶寻得过街闲。
映鞭柳色微遮水，随步花枝欲碍山。
暖泛鸟声来席上，醉从诗句落人间。
此时失意哀吟客，更觉风流不可攀。','',''),('quantangshi-30374','广陵答崔琛','趙嘏','quantangshi','','卷31','棹倚隋家旧院墙，柳金梅雪扑檐香。
朱楼映日重重晚，碧水含光滟滟长。
八斗已闻传姓字，一枝何足计行藏。
声名官职应前定，且把旌麾入醉乡。','',''),('quantangshi-30375','答友人','趙嘏','quantangshi','','卷31','诗家才子酒家仙，游宦曾依积水边。
窗户动摇三岛树，琴尊安稳五湖船。
罗浮道士分琼液，锦席佳人艳楚莲。
今日相逢朗吟罢，满城砧杵一灯前。','',''),('quantangshi-30376','送张又新除温州','趙嘏','quantangshi','','卷31','东晋江山称永嘉，莫辞红斾向天涯。
凝弦夜醉松亭月，歇马晓寻溪寺花。
地与剡川分水石，境将蓬岛共烟霞。
却愁明诏征非晚，不得秋来见海槎。','',''),('quantangshi-30377','送滕迈郎中赴睦州','趙嘏','quantangshi','','卷31','郡斋秋尽一江横，频命郎官地更清。
星月去随新诏动，旌旗遥映故山明。
诗寻片石依依晚，帆挂孤云杳杳轻。
想到钓台逢竹马，只应歌咏伴猿声。','',''),('quantangshi-30378','送剡客','趙嘏','quantangshi','','卷31','两重江外片帆斜，数里林塘遶一家。
门掩右军余水石，路横诸谢旧烟霞。
扁舟几处逢溪雪，长笛何人怨柳花。
若到天台洞阳观，葛洪丹井在云涯。','',''),('quantangshi-30379','李先辈擢第东归有赠送','趙嘏','quantangshi','','卷31','金榜前头无是非，平人分得一枝归。
正怜日暖云飘路，何处宴回风满衣？
门掩长淮心更远，渡连芳草马如飞。
茂陵自笑犹多病，空有书斋在翠微。','',''),('quantangshi-30380','送同年郑祥先辈归汉南','趙嘏','quantangshi','','卷31','年来惊喜两心知，高处同攀次第枝。
人倚绣屏闲赏夜，马嘶花径醉归时。
声名本是文章得，藩阃曾劳笔砚随。
家去恩门四千里，只应从此梦旌旗。','',''),('quantangshi-30381','送沈单作尉江都','趙嘏','quantangshi','','卷31','炀帝都城春水边，笙歌夜上木兰船。
三千宫女自涂地，十万人家如洞天。
焰焰花枝官舍晚，重重云影寺墙连。
少年作尉须矜慎，莫向楼前坠马鞭。','',''),('quantangshi-30382','送李蕴赴郑州因献卢郎中俶','趙嘏','quantangshi','','卷31','仆射陂西想到时，满川晴色见旌旗。
马融闲卧笛声远，王粲醉吟楼影移。
几日赋诗秋水寺，经年草诏白云司。
唯君此去人多羡，却是恩深自不知。','',''),('quantangshi-30383','送韩绛归淮南寄韩绰先辈','趙嘏','quantangshi','','卷31','岛上花枝系钓船，隋家宫畔水连天。
江帆自落鸟飞外，月观静依春色边。
门巷草生车辙在，朝廷恩及雁行联。
相逢且问昭州事，曾鼓庄盆对逝川。','',''),('quantangshi-30384','送薛耽先辈归谒汉南','趙嘏','quantangshi','','卷31','云绕千峰驿路长，谢家联句待檀郎。
手持碧落新攀桂，月在东轩旧选牀。
几日旌幢延骏马，到时冰玉动华堂。
孔门多少风流处，不遣颜回识醉乡。','',''),('quantangshi-30385','送陈嘏登第作尉归觐','趙嘏','quantangshi','','卷31','千峰归去旧林塘，溪县门前即故乡。
曾把桂夸春里巷，重怜身称锦衣裳。
洲迷翠羽云遮槛，露湿红蕉月满廊。
就养举朝人共羡，清资让却校书郎。','',''),('quantangshi-30386','送裴延翰下第归觐滁州','趙嘏','quantangshi','','卷31','失意何曾恨解携，问安归去秣陵西。
郡斜杨柳春风岸，山映楼台明月溪。
江上诗书悬素业，日边门户倚丹梯。
一枝攀折回头是，莫向清秋惜马蹄。','',''),('quantangshi-30387','题崇圣寺简云端僧录','趙嘏','quantangshi','','卷31','暮尘飘尽客愁长，来扣禅关月满廊。
宋玉逢秋空雪涕，净名无地可容牀。
高云覆槛千岩树，疎磬含风一夜霜。
回首故园红叶外，只将多病告医王。','',''),('quantangshi-30388','越中寺居寄上主人','趙嘏','quantangshi','','卷31','野寺初容访静来，晚晴江上见楼台。
中林有路到花尽，一日无人看竹回。
自晒诗书经雨后，别留门户为僧开。
苦心若是酬恩事，不敢吟春忆酒杯。','',''),('quantangshi-30389','早出洞仙观','趙嘏','quantangshi','','卷31','露浓如水洒苍苔，洞口烟萝密不开。
残月色低当户后，晓钟声逈隔山来。
春生药圃芝犹短，夜醮斋坛鹤未回。
愁是独寻归路去，人间步步是尘埃。','',''),('quantangshi-30390','题昭应王明府溪亭','趙嘏','quantangshi','','卷31','靖节何须彭泽逢，菊洲松岛水悠溶。
行人自折门前柳，高鸟不离溪畔峰。
晓渭度檐帆的的，晚原含雨树重重。
轩车过尽无公事，枕上一声长乐钟。','',''),('quantangshi-30391','赠王先生','趙嘏','quantangshi','','卷31','太一真人隐翠霞，早年曾降蔡经家。
羽衣使者峭于鹤，鸟爪侍娘飘若花。
九鼎栏干归马齿，三山窕窈步云涯。
时因弟子偷灵药，散落人间驻物华。','',''),('quantangshi-30392','赠道者','趙嘏','quantangshi','','卷31','华盖飘飘绿鬓翁，往来朝谒蘂珠宫。
几年山下阴阳鼎，尽日涧边桃李风。
野迹似云无处着，仙容如水与谁同。
应怜有客外妻子，思在长生一顾中。','',''),('quantangshi-30393','王先生不别而去','趙嘏','quantangshi','','卷31','仙翁归袖拂烟霓，一卷素书还独携。
劚药满囊身不病，抱琴何处鹤同栖？
霑衣尽日看山坐，搔首残春向路迷。
树树白云幽径绝，短船空倚武陵溪。','',''),('quantangshi-30394','山阳卢明府以双鹤寄遗白氏以诗回答因寄和','趙嘏','quantangshi','','卷31','缑山双去羽翰轻，应为仙家好弟兄。
茅固枕前秋对舞，陆云溪上夜同鸣。
紫泥封处曾回首，碧落归时莫问程。
自笑沧江一渔叟，何由似尔到层城。','',''),('quantangshi-30395','赠李秘书','趙嘏','quantangshi','','卷31','束带临风气调新，孔门才业独谁伦。
杉松韵冷雪溪暗，鸾鹤势高天路春。
美玉韫来休问价，芳枝攀去正无尘。
莫将芸阁轻科第，须作人间第一人。','',''),('quantangshi-30396','回于道中寄舒州李珏相公','趙嘏','quantangshi','','卷31','都无鄙吝隔尘埃，昨日丘门避席来。
静语乍临清庙瑟，披风如在九层台。
几烦命妓浮溪棹，再许论诗注酒杯。
从此微尘知感恋，七真台上望三台。','',''),('quantangshi-30397','舒州献李相公','趙嘏','quantangshi','','卷31','野人留得五湖船，丞相兴歌郡国年。
醉笔倚风飘涧雪，静襟披月坐楼天。
鹤归华表山河在，气返青云雨露全。
闻说万方思旧德，一时倾望重陶甄。','',''),('quantangshi-30398','成名年献座主仆射兼呈同年','趙嘏','quantangshi','','卷31','拂烟披月羽毛新，千里初辞九陌尘。
曾失玄珠求[象罔]，不将双耳负伶伦。
贾嵩词赋相如手，杨乘歌篇李白身。
除却今年仙侣外，堂堂又见两三春。','',''),('quantangshi-30399','抒怀上歙州卢中丞宣州杜侍郎','趙嘏','quantangshi','','卷31','东来珠履与旌旗，前者登朝亦一时。
竹马迎呼逢稚子，柏台长告见男儿。
花飘舞袖楼相倚，角送归轩客尽随。
独有贱夫怀感激，十年两地负恩知。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-30400','山阳韦中丞罢郡因献','趙嘏','quantangshi','','卷31','笙歌只是旧笙歌，肠断风流奈别何。
照物二年春色在，感恩千室泪痕多。
尽将魂梦随西去，犹望旌旗暂一过。
今日尊前无限思，万重云月隔烟波。','',''),('quantangshi-30401','山阳即席献裴中丞','趙嘏','quantangshi','','卷31','早年天上见清尘，今日楼中醉一春。
暂肯剖符临水石，几曾焚笔动星辰。
琼台雪映迢迢鹤，蓬岛波横浩浩津。
好是仙家羽衣使，欲敎垂涕问何人。','',''),('quantangshi-30402','西峰即事献沈大夫','趙嘏','quantangshi','','卷31','松竹闲游道路身，衣襟落尽往来尘。
山连谢宅余霞在，水映琴溪旧浪春。
拂榻从容今有地，酬恩寂寞久无人。
安知不及屠沽者，曾对青萍泪满巾。','',''),('quantangshi-30403','杜陵贻杜牧侍御','趙嘏','quantangshi','','卷31','紫陌尘多不可寻，南溪酒熟一披襟。
山高昼枕石牀隐，泉落夜窗烟树深。
白首寻人嗟问计，青云无路觅知音。
唯君怀抱安如水，他日门墙许醉吟。','',''),('quantangshi-30404','下第后上李中丞','趙嘏','quantangshi','','卷31','落第逢人恸哭初，平生志业欲何如。
鬓毛洒尽一枝桂，泪血滴来千里书。
谷外风高摧羽翮，江边春在忆樵渔。
唯应感激知恩地，不待功成死有余。','',''),('quantangshi-30405','淛东赠李副使员外','趙嘏','quantangshi','','卷31','妙尽戎机佐上台，少年清苦自霜台。
马嘶深竹闲宜贵，花拂朱衣美称才。
早入半缘分务重，晚吟多是看山回。
名高渐少翻飞伴，几度烟霄独去来。','',''),('quantangshi-30406','寄淮南幕中刘员外','趙嘏','quantangshi','','卷31','郎官何逊最风流，爱月怜山不下楼。
三佐戎旃换朱绂，一辞兰省见清秋。
桂生岩石本潇洒，鹤到烟空更自由。
休向西斋久闲卧，满朝倾盖是依刘。','',''),('quantangshi-30407','薛廷范从事自宣城至因赠','趙嘏','quantangshi','','卷31','少年从事霍嫖姚，来自枫林度柳桥。
金管别筵楼灼灼，玉溪回首马萧萧。
清风气调真君辈，知己风流满圣朝。
独有故人愁欲死，晚檐疎雨动空瓢。','',''),('quantangshi-30408','寄浔阳赵校书','趙嘏','quantangshi','','卷31','帘下秋江夜影空，倚楼人在月明中。
不将行止问朝列，唯脱衣裳与钓翁。
几处别巢悲去燕，十年回首送归鸿。
那应更结庐山社，见说心闲胜远公。','',''),('quantangshi-30409','赠李从贵','趙嘏','quantangshi','','卷31','白马嘶风何处还，鞭梢拂地看南山。
珠帘卷尽不回首，春色欲阑休闭关。
花外鸟归残雨暮，竹边人语夕阳闲。
知君旧隐嵩云下，岩桂从今几更攀。','',''),('quantangshi-30410','赠陈正字','趙嘏','quantangshi','','卷31','鲁儒今日意何如，名挂春官选籍初。
野艇几曾寻水去，故山从此与云疎。
吟怜受露花阴足，行觉嘶风马力余。
闻说晚心心更静，竹间依旧卧看书。','',''),('quantangshi-30411','洞庭寄所思','趙嘏','quantangshi','','卷31','目断兰台空望归，锦衾香冷梦来稀。
书中自报刀头约，天上三看破镜飞。
孤浪谩疑红脸笑，轻云忽似舞罗衣。
遥知不语坐相忆，寂寞洞房寒烛微。','',''),('quantangshi-30412','代人赠杜牧侍御','趙嘏','quantangshi','','卷31','郎作东台御史时，妾长西望歛双眉。
一从诏下人皆羡，岂料恩衰不自知。
高阙如天萦晓梦，华筵似水隔秋期。
坐来情态犹无限，更向楼前舞柘枝。','',''),('quantangshi-30413','旅馆闻雁别友人','趙嘏','quantangshi','','卷31','路遶秋塘首独搔，背羣燕雁正呼号。
故关何处重相失，碧落有云终自高。
旅宿去缄他日恨，单飞谁见此生劳。
行衣湿尽千山雪，肠断金笼好羽毛。','',''),('quantangshi-30414','泊凫矶江馆','趙嘏','quantangshi','','卷31','风雪晴来岁欲除，孤舟晚下意何如。
月当轩色湖平后，雁断云声夜起初。
傍晓管弦何处静，犯寒杨柳遶津疎。
三间茅屋东溪上，归去生涯竹与书。','',''),('quantangshi-30415','春尽独游慈恩寺南池','趙嘏','quantangshi','','卷31','竹外池塘烟雨收，送春无伴亦迟留。
秦城马上半年客，潘鬓水边今日愁。
气变晚云红映阙，风含高树碧遮楼。
杏园花落游人尽，独为圭峰一举头。','',''),('quantangshi-30416','重游楚国寺','趙嘏','quantangshi','','卷31','往事飘然去不回。
空余山色在楼台，池塘风暖雁寻去。
松桂寺高人独来，庄叟着书真达者。
贾生挥涕信悠哉，老僧心地闲于水。
犹被流年日日催。','',''),('quantangshi-30417','三像寺酬元秘书','趙嘏','quantangshi','','卷31','官总芸香阁署崇，可怜诗句落春风。
偶然侍坐水声里，还许醉吟松影中。
车马照来红树合，烟霞咏尽翠微空。
不因高寺闲回首，谁识飘飘一塞翁。','',''),('quantangshi-30418','献淮南李仆射','趙嘏','quantangshi','','卷31','早年曾谒富民侯，今日难甘失鹄羞。
新诺似山无力负，旧恩如水满身流。
马嘶红叶萧萧晚，日照长江滟滟秋。
功德万重知不惜，一言抛得百生愁。','',''),('quantangshi-30419','江亭晚望','趙嘏','quantangshi','','卷31','碧江凉冷雁来疎，闲望江云思有余。
秋馆池亭荷叶歇，野人篱落豆花初。
无愁自得仙翁术，多病能忘太史书。
闻说故园香稻熟，片帆归去就鲈鱼。','',''),('quantangshi-30420','赠曹处士幽居','趙嘏','quantangshi','','卷31','勾漏先生冰玉然，曾将八石问羣仙。
中山暂醉一千日，南苑往来三百年。
碁局不收花满洞，霓旌欲别浪翻天。
何须更学鸱夷子，头白江湖一短船。','',''),('quantangshi-30421','重阳日示舍弟','趙嘏','quantangshi','','卷31','多少乡心入酒杯，野塘今日菊花开。
新霜何处雁初下，故国穷秋首正回。
渐老向人空感激，一生驱马傍尘埃。
侯门无路提携尔，虚共扁舟万里来。','',''),('quantangshi-30422','客至','趙嘏','quantangshi','','卷31','得路逢津更俊才，可怜鞍马照春来。
残花几日小斋闭，大笑一声幽抱开。
袖拂碧溪寒缭绕，冠欹红树晚裴回。
相逢少别更堪恨，何必秋风江上台。','',''),('quantangshi-30423','岁暮江轩寄卢端公','趙嘏','quantangshi','','卷31','积水生高浪，长风自北时。
万艘俱拥棹，上客独吟诗。
路以重湖阻，心将小谢期。
渚云愁正断，江雁重惊悲。
笑忆游星子，歌寻罢贵池。
梦来孤岛在，醉醒百忧随。
戍逈烟生晚，江寒鸟过迟。
问山樵者对，经雨钓船移。
敢叹今留滞，犹胜曩别离。
醉从陶令得，善必丈人知。
道蹇才何取，恩深剑不疑。
此身同岸柳，只待变寒枝。','',''),('quantangshi-30424','秋日吴中观贡藕','趙嘏','quantangshi','','卷31','野艇几西东，清泠映碧空。
褰衣来水上，捧玉出泥中。
叶乱田田绿，莲余片片红。
激波才入选，就日已生风。
御洁玲珑膳，人怀拔擢功。
梯山谩多品，不与世流同。','',''),('quantangshi-30425','华清宫和杜舍人','趙嘏','quantangshi','','卷31','五十年天子，离宫仰峻墙。
登封时正泰，御宇日何长。
上位先名实，中兴事宪章。
起戎轻甲胄，余地复河湟。
道帝玄元祖，儒封孔子王。
因缘百司署，藂会一人汤。
渭水波摇绿，秦郊草半黄。
马驯金勒细，鹰健玉铃锵。
下箭朱弓满，鸣鞭皓腕攘。
畋思获吕望，谏只避周昌。
兔迹贪前逐，枭心不早防。
几添鹦鹉劝，先赐荔枝尝。
月锁千门静，天吹一笛凉。
细音摇羽佩，轻步宛霓裳。
祸乱基潜结，升平意遽忘。
衣冠逃犬虏，鼙鼓动渔阳。
外戚心殊迫，中途事可量。
血埋妃子艳，刅断禄儿肠。
近侍烟尘隔，前踪辇路荒。
益知迷宠佞，遗恨丧贤良。
北阙尊明主，南宫逊上皇。
禁清余凤吹，池冷睡龙光。
祝寿山犹在，流年水共伤。
杜鹃魂厌蜀，蝴蝶梦悲庄。
雀卵遗雕栱，虫丝罥画粱。
紫苔侵壁润，红树闭门芳。
守吏齐鸳瓦，耕民得翠璫。
登年齐酺乐，讲武旧兵场。
暮草深岩翠，幽花坠径香。
不堪垂白叟，行折御沟杨。','',''),('quantangshi-30426','下第','趙嘏','quantangshi','','卷31','南溪抱瓮客，失意自怀羞。
晚路谁携手，残春自白头。','',''),('quantangshi-30427','到家','趙嘏','quantangshi','','卷31','童稚苦相问，归来何太迟。
共谁争岁月，赢得鬓边丝。','',''),('quantangshi-30428','春酿','趙嘏','quantangshi','','卷31','春酿正风流，梨花莫问愁。
马卿思一醉，不惜鷫鸘裘。','',''),('quantangshi-30429','寒塘','趙嘏','quantangshi','','卷31','晓发梳临水，寒塘坐见秋。
乡心正无限，一雁度南楼。','',''),('quantangshi-30430','寄前黄州窦使君','趙嘏','quantangshi','','卷31','池上笙歌寂不闻，楼中愁杀碧虚云。
玉壶凝尽重重泪，寄与风流旧使君。','',''),('quantangshi-30431','八月二十九日宿怀','趙嘏','quantangshi','','卷31','秋天晴日菊还香，独坐书斋思已长。
无奈风光易流转，强须倾酒一杯觞。','',''),('quantangshi-30432','泗上奉送相公','趙嘏','quantangshi','','卷31','语堪铭座默含春，西汉公卿绝比伦。
今日抱辕留不得，欲挥双涕学舒人。','',''),('quantangshi-30433','赠桐乡丞','趙嘏','quantangshi','','卷31','舟触长松岸势回，潺湲一夜绕亭台。
若敎靖节先生见，不肯更吟归去来。','',''),('quantangshi-30434','哭李进士','趙嘏','quantangshi','','卷31','牵马街中哭送君，灵车辗雪隔城闻。
唯有山僧与樵客，共舁孤榇入幽坟。','',''),('quantangshi-30435','重阳','趙嘏','quantangshi','','卷31','节逢重九海门外，家在五湖烟水东。
还向秋山觅诗句，伴僧吟对菊花风。','',''),('quantangshi-30436','重阳日即事','趙嘏','quantangshi','','卷31','病酒坚辞绮席春，菊花空伴水边身。
由来举止非闲雅，不是龙山落帽人。','',''),('quantangshi-30437','十无诗寄桂府杨中丞 一','趙嘏','quantangshi','','卷31','琴酒曾将风月须，谢公名迹满江湖。
不知贵拥旌旗后，犹暇怜诗爱酒无。','',''),('quantangshi-30438','十无诗寄桂府杨中丞 二','趙嘏','quantangshi','','卷31','东省南宫兴不孤，几因诗酒谬招呼。
一从开署芙蓉幕，曾向风前记得无。','',''),('quantangshi-30439','十无诗寄桂府杨中丞 三','趙嘏','quantangshi','','卷31','遥闻桂水遶城隅，城上江山满画图。
为问訾家洲畔月，清秋拟许醉狂无。','',''),('quantangshi-30440','十无诗寄桂府杨中丞 四','趙嘏','quantangshi','','卷31','日暮江边一小儒，空怜未有白髭须。
马融已贵诸生老，犹自容窥绛帐无。','',''),('quantangshi-30441','十无诗寄桂府杨中丞 五','趙嘏','quantangshi','','卷31','一种吟诗号孔徒，沧江有客独疎愚。
初筵尽辟知名士，许到风前月下无。','',''),('quantangshi-30442','十无诗寄桂府杨中丞 六','趙嘏','quantangshi','','卷31','望断南云日已晡，便应凭梦过重湖。
不知自古登龙者，曾有因诗泥得无。','',''),('quantangshi-30443','十无诗寄桂府杨中丞 七','趙嘏','quantangshi','','卷31','早游门馆一樵夫，祗爱吟诗傍药炉。
旌斾满江身不见，思言记得颖川无。','',''),('quantangshi-30444','十无诗寄桂府杨中丞 八','趙嘏','quantangshi','','卷31','孔融襟抱称名儒，爱物怜才与世殊。
今日宾堦忘姓字，当时省记荐雄无。','',''),('quantangshi-30445','十无诗寄桂府杨中丞 九','趙嘏','quantangshi','','卷31','僻爱江山俯坐隅，人间不是便为图。
尊前为问神仙伴，肯向三清慰荐无。','',''),('quantangshi-30446','十无诗寄桂府杨中丞 十','趙嘏','quantangshi','','卷31','膺门不避额逢珠，绝境由来卷轴须。
早忝阿戎诗友契，趋庭曾荐禰生无。','',''),('quantangshi-30447','寄山僧','趙嘏','quantangshi','','卷31','云里幽僧不置房，橡花藤叶盖禅牀。
朝来逢着山中伴，闻说新移最上方。','',''),('quantangshi-30448','喜张濆及第','趙嘏','quantangshi','','卷31','九转丹成最上仙，青天暖日踏云轩。
春风贺喜无言语，排比花枝满杏园。','',''),('quantangshi-30449','赠张濆榜头被驳落','趙嘏','quantangshi','','卷31','莫向花前泣酒杯，谪仙依旧是仙才。
犹堪与世为祥瑞，曾到蓬山顶上来。','',''),('quantangshi-30450','悼亡二首 一','趙嘏','quantangshi','','卷31','一烛从风到奈何，二年衾枕逐流波。
虽知不得公然泪，时泣阑干恨更多。','',''),('quantangshi-30451','悼亡二首 二','趙嘏','quantangshi','','卷31','明月萧萧海上风，君归泉路我飘蓬。
门前虽有如花貌，争奈如花心不同。','',''),('quantangshi-30452','宫乌栖','趙嘏','quantangshi','','卷31','宫乌栖处玉楼深，微月生檐夜夜心。
香辇不回花自落，春来空佩辟寒金。','',''),('quantangshi-30453','长信宫','趙嘏','quantangshi','','卷31','君恩已尽欲何归，犹有残香在舞衣。
自恨身轻不如燕，春来长遶御帘飞。','',''),('quantangshi-30454','广陵城','趙嘏','quantangshi','','卷31','红映高台绿绕城，城边春草傍墙生。
隋家不向此中尽，汴水应无东去声。','',''),('quantangshi-30455','冷日过骊山','趙嘏','quantangshi','','卷31','冷日微烟渭水愁，翠华宫树不胜秋。
