尊前尽日谁相对，唯有南山似故人。','',''),('quantangshi-30457','下第后归永乐里自题二首 二','趙嘏','quantangshi','','卷31','玄发侵愁忽似翁，暖尘寒袖共东风。
公卿门户不知处，立马九衢春影中。','',''),('quantangshi-30458','出试日独游曲江','趙嘏','quantangshi','','卷31','江莎渐映花边绿，楼日自开池上春。
双鹤遶空来又去，不知临水有愁人。','',''),('quantangshi-30459','题曹娥庙','趙嘏','quantangshi','','卷31','青娥埋没此江滨，江树飕飗惨暮云。
文字在碑碑已堕，波涛辜负色丝文。','',''),('quantangshi-30460','题段氏中台','趙嘏','quantangshi','','卷31','看山台下水无尘，碧筱前头曲水春。
独对一尊风雨夜，不知家有早朝人。','',''),('quantangshi-30461','华州座中献卢给事','趙嘏','quantangshi','','卷31','送迎皆到三峰下，满面烟霜满马尘。
自是追攀认知己，青云不假送迎人。','',''),('quantangshi-30462','商山道中','趙嘏','quantangshi','','卷31','和如春色净如秋，五月商山是胜游。
当昼火云生不得，一溪萦作万重愁。','',''),('quantangshi-30463','赠歙州妓','趙嘏','quantangshi','','卷31','滟滟横波思有余，庾楼明月堕云初。
扬州寒食春风寺，看遍花枝尽不如。','',''),('quantangshi-30464','赠王明府','趙嘏','quantangshi','','卷31','五柳逢秋影渐微，陶潜恋酒不知归。
但存物外醉乡在，谁向人间问是非。','',''),('quantangshi-30465','吕校书雨中见访','趙嘏','quantangshi','','卷31','竹阁斜溪小槛明，惟君来赏见山情。
马嘶风雨又归去，独听子规千万声。','',''),('quantangshi-30466','千秋岭下','趙嘏','quantangshi','','卷31','知有岩前万树桃，未逢摇落思空劳。
年年盛发无人见，三十六溪春水高。','',''),('quantangshi-30467','歙州道中仆逃','趙嘏','quantangshi','','卷31','去跳风雨几奔波，曾共辛勤奈若何。
莫遣穷归不知处，秋山重叠戍旗多。','',''),('quantangshi-30468','重阳日寄韦舍人','趙嘏','quantangshi','','卷31','节过重阳菊委尘，江边病起杖扶身。
