徒知六国随斤斧，莫有羣儒定是非。
一千里色中秋月，十万军声半夜潮。
梁王旧馆已秋色，珠履少年轻绣衣。','',''),('quantangshi-30554','汉堤诗','盧肇','quantangshi','','卷31','阴沴奸阳，来暴于襄。
洎入大郛，波端若铓。
触厚摧高，不知其防。
骇溃颠委，万室皆毁。
竈登蛟鼍，堂集鳣鲔。
惟恩若雠，母不能子。
洪溃既涸，閈闳其虚。
以隳我堵，以剥我庐。
酸伤顾望，若践丘墟。
帝曰念嗟，朕日南顾。
流灾降慝，天曷台怒。
滔滔襄郊，捽我婴孺。
于惟余甿，饥伤喘呼。
斯为淫痍，孰往膏傅。
惟汝元寮，佥举明哲。
我公用谐，苴茅杖节。
来视襄人，噢咻提挈。
不日不月，咍乎拚悦。
乃泳故堤，陷于沙泥。
缺落坳圯，由东讫西。
公曰呜呼，汉之有堤。
实命襄人，不力乃力，则及乃身。
具锸与畚，汉堤其新。
帝廪有粟，帝府有缗。
尔成尔堤，必锡尔勤。
襄人怡怡，听命襄浒。
背襄肩杵，奔走蹈舞。
分之卒伍，令以麾鼓。
寻尺既度，日月可数。
登登嶪嶪，周旋上下。
披岘斲楚，飞石挽土。
举筑殷雷，骇汗霏雨。
疲癃鳏独，奋有筋膂。
呀吁来助，提筐负筥。
不劳其劳，杂沓笑语。
咸曰卢公，来赐我生。
斯堤既成，蜿蜿而平。
确尔山固，屹如云横。
汉流虽狂，坚不可蚀。
代千年亿，与天无极。
惟公之堤，昔在人心。
既筑既城，横之于南。
萌渚不峻，此门不深。
今复在兹，于汉之阴。
斯堤已崇，兹民获佑。
齯童相庆，室以完富。
贻于襄人，愿保厥寿。
繄公之功，赫焉如昼。
捍此巨灾，崒若京阜。
天子赐之，百姓载之。
族孙作诗，昭示厥后。','',''),('quantangshi-30555','题甘露寺','盧肇','quantangshi','','卷31','北固岩端寺，佳名自上台。
地从京口断，山到海门回。
曙色烟中灭，潮声日下来。
一隅通雉堞，千仞耸楼台。
林暗疑降虎，江空想度杯。
福庭增气象，仙磬落昭回。
觉路花非染，流年景谩催。
隋宫凋绿草，晋室散黄埃。
西蜀波湍尽，东溟日月开。
如登最高处，应得见蓬莱。','',''),('quantangshi-30556','江陵府初试澄心如水','盧肇','quantangshi','','卷31','丹心何所喻，唯水并清虚。
莫测千寻底，难知一勺初。
内明非有物，上善本无鱼。
澹泊随高下，波澜逐卷舒。
养蒙方浩浩，出险每徐徐。
若灌情田里，常流尽不如。','',''),('quantangshi-30557','风不鸣条','盧肇','quantangshi','','卷31','习习和风至，过条不自鸣。
暗通青律起，远傍白苹生。
拂树花仍落，经林鸟自惊。
几牵萝蔓动，潜惹柳丝轻。
入谷迷松响，开窗失竹声。
薰弦方在御，万国仰皇情。','',''),('quantangshi-30558','别宜春赴举','盧肇','quantangshi','','卷31','秋天草木正萧疎，西望秦关别旧居。
筵上芳樽今日酒，箧中黄卷古人书。
辞乡且伴衔芦雁，入海终为戴角鱼。
长短九霄飞直上，不敎毛羽落空虚。','',''),('quantangshi-30559','射策后作','盧肇','quantangshi','','卷31','射策明时愧不才，敢期青律变寒灰。
晴怜断雁侵云去，暖见醯鸡傍酒来。
箭发尚忧杨叶远，愁生只恐杏花开。
曲江春浅人游少，尽日看山醉独回。','',''),('quantangshi-30560','和主司王起','盧肇','quantangshi','','卷31','嵩高降德为时生，洪笔三题造化名。
凤诏伫归专北极，骊珠搜得尽东瀛。
褒衣已换金章贵，禁掖曾随玉树荣。
明日定知同相印，青衿新列柳间营。','',''),('quantangshi-30561','及第送潘图归宜春','盧肇','quantangshi','','卷31','三载皇都恨食贫，北溟今日化穷鳞。
青云乍喜逢知己，白社犹悲送故人。
对酒共惊千里别，看花自感一枝春。
君归为说龙门寺，雷雨初生电遶身。','',''),('quantangshi-30562','将归宜春留题新安馆','盧肇','quantangshi','','卷31','东里如今号郑乡，西家昔日近丘墙。
芸台四部添新学，秘殿三年学老郎。
天外鸳鸾愁不见，山中云鹤喜相忘。
犹张皂盖归蓬荜，直谓时无许子将。','',''),('quantangshi-30563','竞渡诗','盧肇','quantangshi','','卷31','石溪久住思端午，馆驿楼前看发机。
鼙鼓动时雷隐隐，兽头凌处雪微微。
冲波突出入齐[譀]，跃浪争先鸟退飞。
向道是龙刚不信，果然夺得锦标归。','',''),('quantangshi-30564','除歙州途中寄座主王侍郎','盧肇','quantangshi','','卷31','忽忝专城奉六条，自怜出谷屡迁乔。
驱车虽道还家近，捧日惟愁去国遥。
朱户昨经新棨戟，风帆常觉恋箪瓢。
江天夜夜知消息，长见台星在碧霄。','',''),('quantangshi-30565','御沟水','盧肇','quantangshi','','卷31','万壑朝溟海，萦回岁月多。
无如此沟水，咫尺奉天波。','',''),('quantangshi-30566','杨柳枝','盧肇','quantangshi','','卷31','青鸟泉边草木春，黄云塞上是征人。
归来若得长条赠，不惮风霜与苦辛。','',''),('quantangshi-30567','新植红茶花偶出被人移去以诗索之','盧肇','quantangshi','','卷31','严恨柴门一树花，便随香远逐香车。
花如解语还应道，欺我郎君不在家。','',''),('quantangshi-30568','戏题','盧肇','quantangshi','','卷31','神女初离碧玉堦，彤云犹拥牡丹鞋。
知道相公怜玉腕，强将纤手整金钗。','',''),('quantangshi-30569','成名后作','盧肇','quantangshi','','卷31','桂在蟾宫不可攀，功成业熟也何难。
今朝折得东归去，共与乡闾年少看。','',''),('quantangshi-30570','登祝融寺兰若','盧肇','quantangshi','','卷31','祝融绝顶万余层，策杖攀萝步步登。
行到月宫霞外寺，白云相伴两三僧。','',''),('quantangshi-30571','被谪连州','盧肇','quantangshi','','卷31','黄绢外孙翻得罪，华颠故老莫相嗤。
连州万里无亲戚，旧识唯应有荔枝。','',''),('quantangshi-30572','谪后再书一绝','盧肇','quantangshi','','卷31','崆峒道士悞烧丹，赤鼠黄牙几许难。
坠堕阎浮南斗下，不知何事犯星官。','',''),('quantangshi-30573','题清远峡观音院二首 一','盧肇','quantangshi','','卷31','清潭洞澈深千丈，危岫攀萝上几层。
秋尽更无黄叶树，夜阑唯对白头僧。','',''),('quantangshi-30574','题清远峡观音院二首 二','盧肇','quantangshi','','卷31','风入古松添急雨，月临虚槛背残灯。
老猨啸狖还欺客，来撼窗前百尺藤。','',''),('quantangshi-30575','喜杨舍人入翰林','盧肇','quantangshi','','卷31','御笔亲批翰长衔，夜开金殿送瑶缄。
平明玉案临宣室，已见龙光出傅岩。','',''),('quantangshi-30576','谪连州书春牛榜子','盧肇','quantangshi','','卷31','阳和未解逐民忧，雪满羣山对白头。
不得职田饥欲死，儿侬何事打春牛。','',''),('quantangshi-30577','送弟','盧肇','quantangshi','','卷31','去日家无担石储，汝须勤苦事樵渔。
古人尽向尘中远，白日耕田夜读书。','',''),('quantangshi-30578','牧童','盧肇','quantangshi','','卷31','谁人得似牧童心，牛上横眠秋听深。
时复往来吹一曲，何愁南北不知音。','',''),('quantangshi-30579','嘲小儿','盧肇','quantangshi','','卷31','贪生只爱眼前珍，不觉风光度岁频。
昨日见来骑竹马，今朝早是有年人。','',''),('quantangshi-30580','金钱花','盧肇','quantangshi','','卷31','轮郭休夸四字书，红窠写出对庭除。
时时买得佳人笑，本色金钱却不如。','',''),('quantangshi-30581','木笔花','盧肇','quantangshi','','卷31','媆如新竹管初齐，粉腻红轻样可携。
谁与诗人偎槛看，好于牋墨并分题。','',''),('quantangshi-30582','句','盧肇','quantangshi','','卷31','君梦涔阳月，中秋忆棹歌。
妙吹应谐凤，工书定得鹅。
亭边古木昼阴阴，亭下寒潭百丈深。
黄菊旧连陶令宅，青山遥负向平心。','',''),('quantangshi-30583','塞下曲','丁稜','quantangshi','','卷31','北风鸣晚角，雨雪塞云低。
烽举战军动，天寒征马嘶。
出营红斾展，过碛暗沙迷。','',''),('quantangshi-30584','和主司王起','丁稜','quantangshi','','卷31','公心独立副天心，三辖春闱冠古今。
兰署门生皆入室，莲峰太守别知音。
同升翰苑时名重，遍历朝端主意深。
新有受恩江海客，坐听朝夕继为霖。','',''),('quantangshi-30585','和主司王起','高退之','quantangshi','','卷31','昔年桃李已滋荣，今日兰荪又发生。
葑菲采时皆有道，权衡分处且无情。
叨陪鸳鹭朝天客，共作门阑出谷鸎。
何事感恩偏觉重，忽闻金榜扣柴荆。','',''),('quantangshi-30586','和主司王起','孟球','quantangshi','','卷31','当年门下化龙成，今日余波进后生。
仙籍共知推丽藻，禁垣同得荐嘉名。
桃蹊早茂夸新萼，菊圃初开耀晚英。
谁料羽毛方出谷，许敎齐和九臯鸣。','',''),('quantangshi-30587','和主司王起','劉耕','quantangshi','','卷31','孔门频建铸颜功，紫绶青衿感激同。
一篑勤劳成太华，三年恩德仰维嵩。
杨随前辈穿皆中，桂许平人折欲空。
惭和周郎应见顾，感知大造竟无穷。','',''),('quantangshi-30588','和主司王起','裴翻','quantangshi','','卷31','常将公道选羣生，犹被春闱屈重名。
文柄久持殊岁纪，恩门三启动寰瀛。
云霄幸接鸳鸾盛，变化欣同草木荣。
乍得阳和如细柳，参差长近亚夫营。','',''),('quantangshi-30589','和主司王起','樊驤','quantangshi','','卷31','满朝簪发半门生，又见新书甲乙名。
孤进自今开道路，至公依旧振寰瀛。
云飞太华清词着，花发长安白屋荣。
忝受恩光同上客，惟将报德是经营。','',''),('quantangshi-30590','和主司王起','崔軒','quantangshi','','卷31','满朝朱紫半门生，新榜劳人又得名。
国器旧知收片玉，朝宗转觉集登瀛。
同升翰苑三年美，继入花源九族荣。
共仰莲峰听雪唱，欲赓仙曲意怔营。','',''),('quantangshi-30591','和主司王起','蒯希逸','quantangshi','','卷31','一振声华入紫薇，三开秦镜照春闱。
龙门旧列金章贵，莺谷新迁碧落飞。
恩感风雷宜变化，诗裁锦绣借光辉。
谁知散质多荣忝，鸳鹭清尘接布衣。','',''),('quantangshi-30592','句','蒯希逸','quantangshi','','卷31','蟾蜍醉里破，蛱蝶梦中残。
山险不曾离马后，酒醒长见在牀前。','',''),('quantangshi-30593','望九华山','林滋','quantangshi','','卷31','兹山突出何怪奇，上有万状无凡姿。
大者嶙峋若奔兕，小者㠥嵬如婴儿。
玉柱金茎相拄枝，干空逾碧势参差。
虚中始讶巨灵擘，阧处乍惊愚叟移。
萝烟石月相蔽亏，天风褭褭猨咿咿。
龙潭万古喷飞溜，虎穴几人能得窥。
吁予比年爱灵境，到此始觉魂神驰。
如何独得百丈索，直上高峰抛俗羁。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-30594','春望','林滋','quantangshi','','卷31','春海镜长天，青郊丽上年。
林光虚霁晓，山翠薄晴烟。
气暖禽声变，风恬草色鲜。
散襟披石磴，韶景自深怜。','',''),('quantangshi-30595','蠡泽旅怀','林滋','quantangshi','','卷31','谁言行旅日，况复桃花时。
水即沧溟远，星从天汉垂。
川光独鸟暮，林色落英迟。
岂是王程急，偏多游子悲。','',''),('quantangshi-30596','宴韦侍御新亭','林滋','quantangshi','','卷31','烟磴披青霭，风筵藉紫苔。
花香凌桂醑，竹影落藤杯。
鸣籁将歌远，飞枝拂舞开。
未愁留兴晚，明月度云来。','',''),('quantangshi-30597','人日','林滋','quantangshi','','卷31','春辉新入碧烟开，芳院初将穆景来。
共向花前图瑞胜，试看池上动轻苔。
林香半落沾罗幌，蕙色微含近酒杯。
闻道宸游方命赏，应随恩赉喜昭回。','',''),('quantangshi-30598','和主司王起','林滋','quantangshi','','卷31','龙门一变荷生成，况是三传不朽名。
美誉早闻喧北阙，颓波今见走东瀛。
鸳行既接参差影，鸡树仍同次第荣。
从此青衿与朱紫，升堂侍宴更何营。','',''),('quantangshi-30599','听蜀道士琴歌','李宣古','quantangshi','','卷31','至道不可见，正声难得闻。
忽逢羽客抱绿绮，西别峨嵋峰顶云。
初排□面蹑轻响，似掷细珠鸣玉上。
忽挥素爪画七弦，苍崖劈裂迸碎泉。
愤声高，怨声咽，屈原呌天两妃绝。
朝雉飞，双鹤离，属玉夜啼独鹜悲。
吹我神飞碧霄里，牵我心灵入秋水。
有如驱逐太古来，邪淫辟荡贞心开。
孝为子，忠为臣，不独语言能敎人。
前弄啸，后弄嚬，一舒一惨非冬春。
从朝至暮听不足，相将直说瀛洲宿。
更深弹罢背孤灯，窗雪萧萧打寒竹。
人间岂合值仙踪，此别多应不再逢。
抱琴却上瀛洲去，一片白云千万峰。','',''),('quantangshi-30600','和主司王起','李宣古','quantangshi','','卷31','恩光忽逐晓春生，金榜前头忝姓名。
三感至公裨造化，重扬文德振寰瀛。
伫为霖雨曾相贺，半在云霄觉更荣。
何处新诗添照灼，碧莲峰下柳间营。','',''),('quantangshi-30601','杜司空席上赋','李宣古','quantangshi','','卷31','红灯初上月轮高，照见堂前万朵桃。
觱栗调清银象管，琵琶声亮紫檀槽。
能歌姹女颜如玉，解引萧郎眼似刀。
争奈夜深抛耍令，舞来挼去使人劳。','',''),('quantangshi-30602','赋寒食日亥时','李宣古','quantangshi','','卷31','人定朱门尚未开，初星粲粲照人回。
此时寒食无烟火，花柳苍苍月欲来。','',''),('quantangshi-30603','句','李宣古','quantangshi','','卷31','翠盖不西来，池上天池歇。
冉冉池上烟，盈盈池上柳。
生贵非道傍，不断行人手。','',''),('quantangshi-30604','风不鸣条','黃頗','quantangshi','','卷31','五纬起祥飙，无声瑞圣朝。
稍开含露蘂，才转惹烟条。
密叶应潜变，低枝几暗摇。
林间莺欲啭，花下蝶微飘。
初满沿堤草，因生逐水苗。
太平无一事，天外奏虞韶。','',''),('quantangshi-30605','和主司王起','黃頗','quantangshi','','卷31','二十二年文敎主，三千上士满皇州。
独陪宣父蓬瀛奏，方接颜生鲁卫游。
多羡龙门齐变化，屡看鸡树第名流。
升堂何处最荣美，朱紫环[尊]几处酬。','',''),('quantangshi-30606','闻宜春诸举子陪郡主登河梁翫月','黃頗','quantangshi','','卷31','一年秋半月当空，遥羡飞觞接庾公。
虹影迥分银汉上，兔辉全写玉筵中。
笙歌送尽迎寒漏，冰雪吟消永夜风。
虽向东堂先折桂，不如宾席此时同。','',''),('quantangshi-30607','和主司王起','張道符','quantangshi','','卷31','三开文镜继芳声，暗暗云霄接去程。
会压洪波先得路，早升清禁共垂名。
莲峰对处朱轮贵，金榜传时玉韵成。
更许下才听白雪，一枝今过郄诜荣。','',''),('quantangshi-30608','和主司王起','丘上卿','quantangshi','','卷31','常将公道选诸生，不是鸳鸿不得名。
天上宴回联步武，禁中麻出满寰瀛。
簪裾尽过前贤贵，门馆仍叨旧学荣。
看着凤池相继入，都堂那肯滞关营。','',''),('quantangshi-30609','和主司王起','石貫','quantangshi','','卷31','重德由来为国生，五朝清显冠公卿。
风波久伫济川檝，羽翼三迁出谷莺。
绛帐青衿同日贵，春兰秋菊异时荣。
孔门弟子皆贤哲，谁料穷儒忝一名。','',''),('quantangshi-30610','和主司王起','李潛','quantangshi','','卷31','文学宗师心秤平，无私三用佐贞明。
恩波旧是仙舟客，德宇新添月桂名。
兰署崇资金色重，莲峰高唱玉音清。
羽毛方荷生成力，难继鸾皇上汉声。','',''),('quantangshi-30611','和主司王起','孟守','quantangshi','','卷31','科文又主守初时，光显门生济会期。
美擅东堂登甲乙，荣同内署侍恩私。
羣莺共喜新迁木，双凤皆当即入池。
别有倍深知感士，曾经两度得芳枝。','',''),('quantangshi-30612','和主司王起','思言','quantangshi','','卷31','儒雅皆传德敎行，几崇浮俗赞文明。
龙门昔上波涛远，禁署同登渥泽荣。
虚散谬当陪杞梓，后先宁异感生成。
时方侧席征贤急，况说謌谣近帝京。','',''),('quantangshi-30613','风不鸣条','戈牢','quantangshi','','卷31','旭日悬清景，微风在绿条。
入松声不发，度柳影空摇。
长养应潜变，扶疎每暗飘。
有林时袅袅，无树渐萧萧。
慢逐青烟散，轻和瑞气饶。
丰年知有待，歌咏美唐尧。','',''),('quantangshi-30614','和主司王起','戈牢','quantangshi','','卷31','圣干文德最称贤，自古儒生少比肩。
再启龙门将二纪，两司莺谷已三年。
蓬山皆美成荣贵，金榜谁知忝后先。
正是感恩流涕日，但思旌斾碧峰前。','',''),('quantangshi-30615','风不鸣条','厚載','quantangshi','','卷31','寂寂曙风生，迟迟散野轻。
露华摇有滴，林叶褭无声。
暗翦藂芳发，空传谷鸟鸣。
悠扬韶景静，澹荡霁烟横。
远水波澜息，荒郊草树荣。
吾君垂至化，万类共澄清。','',''),('quantangshi-30616','和主司王起','厚載','quantangshi','','卷31','长庆曾收间世英，果居台阁冠公卿。
天书再受恩波远，金榜三开日月明。
已见差肩趍翰苑，更期连步掌台衡。
小儒谬迹云霄路，心仰莲峰望太清。','',''),('quantangshi-30617','风不鸣条','王甚夷','quantangshi','','卷31','圣日祥风起，韶晖助发生。
蒙蒙遥野色，褭褭细条轻。
荏弱看渐动，怡和吹不鸣。
枝含余露湿，林霁晓烟平。
缥缈春光媚，悠扬景气晴。
康哉帝尧代，寰宇共澄清。','',''),('quantangshi-30618','和主司王起','王甚夷','quantangshi','','卷31','春闱帝念主生成，长庆公闻两岁名。
有蕴赤心分雨露，无私和气浃寰瀛。
龙门乍出难胜幸，鸳侣先行是最荣。
遥仰高峰看白雪，多惭属和意屏营。','',''),('quantangshi-30619','送李潜归绵州觐省','姚鵠','quantangshi','','卷31','朱楼对翠微，红斾出重扉。
此地千人望，寥天一鹤归。
雪封山崦白，鸟拂栈梁飞。
谁比趋庭恋，骊珠耀彩衣。','',''),('quantangshi-30620','塞外寄张侍御','姚鵠','quantangshi','','卷31','千里入黄云，羁愁日日新。
疎钟关路晓，远雨塞山春。
南眺有归雁，北来无故人。
却思陪宴处，回望与天隣。','',''),('quantangshi-30621','晓发','姚鵠','quantangshi','','卷31','旅行宜早发，况复是南归。
月影缘山尽，钟声隔浦微。
残星萤共失，落叶鸟和飞。
去去渡南浦，村中人出稀。','',''),('quantangshi-30622','题终南山隐者居','姚鵠','quantangshi','','卷31','开门绝壑旁，蹑藓过花梁。
路入峰峦影，风来芝术香。
夜吟明雪牖，春梦闭云房。
尽室更何有，一琴兼一觞。','',''),('quantangshi-30623','嘉川驿楼晚望','姚鵠','quantangshi','','卷31','楼压寒江上，开帘对翠微。
斜阳诸岭暮，古渡一僧归。
窗逈云冲起，汀遥鸟背飞。
谁言坐多倦，目极自忘机。','',''),('quantangshi-30624','送人归吴','姚鵠','quantangshi','','卷31','东吴与上国，万里路迢迢。
为别晨昏久，全轻水陆遥。
湘阴岛上寺，楚色月中潮。
到此一长望，知君积恨销。','',''),('quantangshi-30625','送石贯归湖州','姚鵠','quantangshi','','卷31','同志幸同年，高堂君独还。
齐荣恩未报，共隐事应闲。
访寺临湖岸，开楼见海山。
洛中推二陆，莫久恋乡关。','',''),('quantangshi-30626','送刘耕归舒州','姚鵠','quantangshi','','卷31','四座莫纷纷，须臾岐路分。
自从同得意，谁不惜离羣。
旧国连青海，归程在白云。
弃繻当日路，应竞看终军。','',''),('quantangshi-30627','寄赠许璋少府','姚鵠','quantangshi','','卷31','若说君高道，何人更得如。
公庭唯树石，生计是琴书。
诗句峭无敌，文才清有余。
不知尺水内，争滞北溟鱼。','',''),('quantangshi-30628','寄雍陶先辈','姚鵠','quantangshi','','卷31','知音杳何处，书札寄无由。
独宿月中寺，相思天畔楼。
露凝衰草白，萤度远烟秋。
怅望难归枕，吟劳生夜愁。','',''),('quantangshi-30629','寄友人','姚鵠','quantangshi','','卷31','西风又开菊，久客意如何。
旧国天涯远，清砧月夜多。
明时难际会，急景易蹉跎。
抱玉终须献，谁言恋薜萝。','',''),('quantangshi-30630','感怀陈情','姚鵠','quantangshi','','卷31','恩重空感激，何门誓杀身。
谬曾分玉石，竟自困风尘。
阴谷非因暖，幽丛岂望春。
升沈在言下，应念异他人。','',''),('quantangshi-30631','送程秀才下第归蜀','姚鵠','quantangshi','','卷31','莺迁与鶂退，十载泣岐分。
蜀道重来老，巴猨此去闻。
晓程侵岭雪，远栈入溪云。
莫滞趋庭恋，荣亲祗待君。','',''),('quantangshi-30632','旱鱼词上苗相公','姚鵠','quantangshi','','卷31','似龙鳞已足，唯是欠登门。
日里腮犹湿，泥中目未昏。
乞锄防蚁穴，望水泻金盆。
他日能为雨，公田报此恩。','',''),('quantangshi-30633','野寺寓居即事二首 一','姚鵠','quantangshi','','卷31','南山色当户，初日半檐时。
鹤去卧看远，僧来嫌起迟。
窗明云影断，庭晓树阴移。
何处题新句，连溪密叶垂。','',''),('quantangshi-30634','野寺寓居即事二首 二','姚鵠','quantangshi','','卷31','古寺更何有，当庭唯折幢。
伴僧青藓榻，对雨白云窗。
暝色生前岭，离魂隔远江。
沙洲半藜草，飞鹭白双双。','',''),('quantangshi-30635','襄州献卢尚书','姚鵠','quantangshi','','卷31','立事成功尽远图，一方独与万方殊。
藩臣皆竞师兵畧，相国今多揖庙谟。
礼乐政行凋弊俗，歌谣声彻帝王都。
即随凤诏归何处，祗是操持造化炉。','',''),('quantangshi-30636','将归蜀留献恩地仆射二首 一','姚鵠','quantangshi','','卷31','自持衡镜采幽沈，此事常闻旷古今。
危叶只将终委地，焦桐谁料却为琴。
蒿莱讵报生成德，犬马空怀感恋心。
明日还家盈眼血，定应回首即霑襟。','',''),('quantangshi-30637','将归蜀留献恩地仆射二首 二','姚鵠','quantangshi','','卷31','江上长思狎钓翁，此心难与昨心同。
自承丘壑新恩重，已分烟霞旧隐空。
龙变偶因资巨浪，鸟飞谁肯借高风。
应怜死节无门効，永叹潜怀似转蓬。','',''),('quantangshi-30638','随州献李侍御二首 一','姚鵠','quantangshi','','卷31','彩笔曾专造化权，道尊翻向宦途闲。
端居有地唯栽药，静坐无时不忆山。
德望旧悬霄汉外，政声新溢路歧间。
众知圣主搜贤相，朝夕欲徴黄霸还。','',''),('quantangshi-30639','随州献李侍御二首 二','姚鵠','quantangshi','','卷31','再刖未甘何处说，但垂双泪出咸秦。
风尘匹马来千里，蓬梗全家望一身。
旧隐每怀空竟夕，愁眉不展几经春。
今朝傥降非常顾，倒屐宁惟有古人。','',''),('quantangshi-30640','虢州献杨抑卿二首 一','姚鵠','quantangshi','','卷31','盖世英华更有谁，赋成传写遍坤维。
名科累中求贤日，苦节高标守郡时。
楼上呌云秋鼓角，林间宿鹤夜旌旗。
征归诏下应非久，德望人情在凤池。','',''),('quantangshi-30641','虢州献杨抑卿二首 二','姚鵠','quantangshi','','卷31','碧山曾共惜分阴，暗学相如赋上林。
到此敢逾千里恨，归家且遂十年心。
疎愚祗怯膺门险，浅薄争窥孔室深。','',''),('quantangshi-30642','赠边将','姚鵠','quantangshi','','卷31','三边近日往来通，尽是将军镇抚功。
兵统万人为上将，威加千里慑西戎。
清笳遶塞吹寒月，红斾当山肃晓风。
却恨北荒霑雨露，无因扫尽虏庭空。','',''),('quantangshi-30643','送费[炼]师供奉赴上都','姚鵠','quantangshi','','卷31','缩地周游不计程，古今应只有先生。
已同化鹤临华表，又见骖龙向玉清。
萝磴静攀云共过，雪坛当醮月孤明。
无因相逐朝天帝，空羡烟霞得送迎。','',''),('quantangshi-30644','和徐先辈秋日游泾州南亭呈三二同年','姚鵠','quantangshi','','卷31','多此欢情泛鷁舟，桂枝同折塞同游。
声喧岛上巢松鹤，影落杯中过水鸥。
送日暮钟交戍岭，呌云寒角动城楼。
酒酣笑语秋风里，谁道槐花更起愁。','',''),('quantangshi-30645','送黄颇归袁','姚鵠','quantangshi','','卷31','莫倦连期在醉乡，孔门多恋惜分行。
文章声价从来重，霄汉途程此去长。
何处听猨临万壑，几宿因月滞三湘。
炉峰若上应相忆，不得同过惠远房。','',''),('quantangshi-30646','和陕州参军李通微首夏书怀呈同寮张裳段羣二先辈','姚鵠','quantangshi','','卷31','公门何事更相牵，邵伯优贤任养闲。
满院落花从覆地，半檐初日未开关。
寻仙郑谷烟霞里，避暑柯亭树石间。
独为高怀谁和继，掾曹同处桂同攀。','',''),('quantangshi-30647','玉真观寻赵尊师不遇','姚鵠','quantangshi','','卷31','羽客朝元昼掩扉，林中一径雪中微。
松阴遶院鹤相对，山色满楼人未归。
尽日独思风驭返，寥天几望野云飞。
凭高目断无消息，自醉自吟愁落晖。','',''),('quantangshi-30648','及第后上主司王起','姚鵠','quantangshi','','卷31','三年竭力向春闱，塞断浮华众路岐。
盛选栋梁非昔日，平均雨露及明时。
登龙旧美无邪径，折桂新荣尽直枝。
莫道只陪金马贵，相期更在凤皇池。','',''),('quantangshi-30649','送贺知章入道','姚鵠','quantangshi','','卷31','若非尧运及垂衣，肯许巢由脱俗机。
太液始同黄鹤下，仙乡已驾白云归。
还披旧褐辞金殿，却捧玄珠向翠微。
羁束慙无仙药分，随车空有梦魂飞。','',''),('quantangshi-30650','送友人出塞','姚鵠','quantangshi','','卷31','帝城春色着寒梅，去恨离怀醉不开。
作别欲将何计免，此行应又隔年回。
入河残日雕西尽，卷雪惊蓬马上来。
有思莫忘清塞学，众传君负佐王才。','',''),('quantangshi-30651','送僧归新罗','姚鵠','quantangshi','','卷31','淼淼万余里，扁舟发落晖。
沧溟何岁别，白首此时归。
寒暑途中变，人烟岭外稀。
惊天巨鳌鬬，蔽日大鹏飞。
雪入行砂屦，云生坐石衣。
汉风深习得，休恨本心违。','',''),('quantangshi-30652','奉和秘监从翁夏日陕州河亭晚望','姚鵠','quantangshi','','卷31','洪河何处望，一境在孤烟。
极野如蓝日，长波似镜年。
卷帘花影里，倚槛鹤巢边。
霞焰侵旌斾，滩声杂管弦。
钟微来叠岫，帆远落遥天。
过客多相指，应疑会水仙。','',''),('quantangshi-30653','风不鸣条','姚鵠','quantangshi','','卷31','吾君理化清，上瑞报时平。
晓吹何曾歇，柔条自不鸣。
花香知暗度，柳动觉潜生。
只见低垂影，那闻击触声。
大王初溥畅，少女正轻盈。
幸遇无私力，幽芳愿发荣。','',''),('quantangshi-30654','书情献知己','姚鵠','quantangshi','','卷31','日日恨何穷，巴云旧隐空。
一为栖寓客，二见北归鸿。
有道期攀桂，无门息转蓬。
赁居将罄比，乞食与僧同。
花月登临处，江山怅望中。
众皆轻病骥，谁肯救焦桐。
坐惜春还至，愁吟夜每终。
谷寒思变律，叶晚怯回风。
谒蔡慙王粲，怜衡冀孔融。','',''),('quantangshi-30655','和工部杨尚书重送绝句','姚鵠','quantangshi','','卷31','桂枝攀得献庭闱，何似空怀楚橘归。
好控扶摇早回首，人人思看大鹏飞。','',''),('quantangshi-30656','寄石桥僧','項斯','quantangshi','','卷31','逢师入山日，道在石桥边。
别后何人见，秋来几处禅。
溪中云隔寺，夜半雪添泉。
生有天台约，知无却出缘。','',''),('quantangshi-30657','送欧阳衮归闽中','項斯','quantangshi','','卷31','秦城几年住，犹着故乡衣。
失意时相识，成名后独归。
海秋蛮树黑，岭夜瘴禽飞。
为学心难满，知君更掩扉。','',''),('quantangshi-30658','古观','項斯','quantangshi','','卷31','置观碑已折，看松年不分。
洞中谁识药，门外日添坟。
放去龟随水，呼来鹿怕薰。
坛边见灰火，几烧祭星文。','',''),('quantangshi-30659','题令狐处士溪居','項斯','quantangshi','','卷31','白发已过半，无心离此溪。
病尝山药徧，贫起草堂低。
为月窗从破，因诗壁重泥。
近来常夜坐，寂莫与僧齐。','',''),('quantangshi-30660','送僧归南岳','項斯','quantangshi','','卷31','心知衡岳路，不怕去人稀。
船里谁鸣磬，沙头自曝衣。
有家从小别，是寺即言归。
料得逢春住，当禅云满扉。','',''),('quantangshi-30661','宁州春思','項斯','quantangshi','','卷31','失意离城早，边城任见花。
初为断酒客，旧识卖书家。
寒寺稀无雪，春风亦有沙。
思归频入梦，即路不言赊。','',''),('quantangshi-30662','山友赠藓花冠','項斯','quantangshi','','卷31','尘污出华发，慙君青藓冠。
此身闲未得，终日戴应难。
好就松阴挂，宜当枕石看。
会须寻道士，簪去绕霜坛。','',''),('quantangshi-30663','蛮家','項斯','quantangshi','','卷31','领得卖珠钱，还归铜柱边。
看儿调小象，打鼓试新船。
醉后眠神树，耕时语瘴烟。
不逢寒便老，相问莫知年。','',''),('quantangshi-30664','早春题湖上顾氏新居二首 一','項斯','quantangshi','','卷31','近得水云看，门长侵早开。
到时微有雪，行处又无苔。
劝酒客初醉，留茶僧未来。
每逢晴暖日，唯见乞花栽。','',''),('quantangshi-30665','早春题湖上顾氏新居二首 二','項斯','quantangshi','','卷31','门不当官道，行人到亦稀。
故从餐后出，方至夜深归。
开箧拣书卷，扫牀移褐衣。
几时同买宅，相近有柴扉。','',''),('quantangshi-30666','苍梧云气','項斯','quantangshi','','卷31','何年化作愁，漠漠便难收。
数点山能远，平铺水不流。
湿连湘竹暮，浓盖舜坟秋。
亦有思归客，看来尽白头。','',''),('quantangshi-30667','晚春花','項斯','quantangshi','','卷31','阴洞日光薄，花开不及时。
当春无半树，经烧足空枝。
疎与香风会，细将泉影移。
此中人到少，开尽几人知。','',''),('quantangshi-30668','宿胡氏溪亭','項斯','quantangshi','','卷31','独住水声里，有亭无热时。
客来因月宿，牀势向山移。
鹤睡松枝定，萤归葛叶垂。
寂寥犹欠伴，谁为报僧知。','',''),('quantangshi-30669','送华阴隐者','項斯','quantangshi','','卷31','往往到城市，得非征药钱。
世人空识面，弟子莫知年。
自说能医死，相期更学仙。
近来移住处，毛女旧峰前。','',''),('quantangshi-30670','落第后寄江南亲友','項斯','quantangshi','','卷31','古巷槐阴合，愁多昼掩扉。
独存过江马，强拂看花衣。
送客心先醉，寻僧夜不归。
龙钟易惆怅，莫遣寄书稀。','',''),('quantangshi-30671','欲别','項斯','quantangshi','','卷31','花时人欲别，每日醉樱桃。
买酒金钱尽，弹筝玉指劳。
归期无岁月，客路有风涛。
锦缎裁衣赠，麒麟落剪刀。','',''),('quantangshi-30672','留别张水部籍','項斯','quantangshi','','卷31','省中重拜别，兼领寄人书。
已念此行远，不应相问疎。
子城西并宅，御水北同渠。
要取春前到，乘闲候起居。','',''),('quantangshi-30673','小古镜','項斯','quantangshi','','卷31','字已无人识，唯应记铸年。
见来深似水，携去重于钱。
鸾翅巢空月，菱花徧小天。
宫中照黄帝，曾得化为仙。','',''),('quantangshi-30674','题太白山隐者','項斯','quantangshi','','卷31','高居在幽岭，人得见时稀。
写箓扃虚白，寻僧到翠微。
扫坛星下宿，收药雨中归。
从服小还后，自疑身解飞。','',''),('quantangshi-30675','病中怀王展先辈在天台','項斯','quantangshi','','卷31','枕上用心静，唯应改旧诗。
强行休去早，暂卧起还迟。
因说来归处，却愁初病时。
赤城山下寺，无计得相随。','',''),('quantangshi-30676','鲤鱼','項斯','quantangshi','','卷31','似龙鳞又足，只是欠登门。
月里腮犹湿，泥中目未昏。
乞锄防蚁穴，望水写金盆。
他日能为雨，公田报此恩。','',''),('quantangshi-30677','子规','項斯','quantangshi','','卷31','游魂自相叫，宁复记前身。
飞过人家月，声连客路春。
梦边催晓急，愁外送风频。
自有霑花血，相和泪滴新。','',''),('quantangshi-30678','边州客舍','項斯','quantangshi','','卷31','开门不成出，麦色徧前坡。
自小诗名在，如今白发多。
经年无越信，终日厌蕃歌。
近寺居僧少，春来亦嬾过。','',''),('quantangshi-30679','赠道者','項斯','quantangshi','','卷31','晏来知养气，度日语时稀。
到处留丹井，终寒不絮衣。
病乡多惠药，鬼俗有符威。
自说身轻健，今年数梦飞。','',''),('quantangshi-30680','边游','項斯','quantangshi','','卷31','古镇门前去，长安路在东。
天寒明堠火，日晚裂旗风。
塞馆皆无事，儒装亦有弓。
防秋故乡卒，暂喜语音同。','',''),('quantangshi-30681','夜泊淮阴','項斯','quantangshi','','卷31','夜入楚家烟，烟中人未眠。
望来淮岸尽，坐到酒楼前。
灯影半临水，筝声多在船。
乘流向东去，别此易经年。','',''),('quantangshi-30682','远水','項斯','quantangshi','','卷31','渺渺浸天色，一边生晚光。
阔浮萍思远，寒入雁愁长。
北极连平地，东流即故乡。
扁舟来宿处，仿髴似潇湘。','',''),('quantangshi-30683','黄州暮愁','項斯','quantangshi','','卷31','凌澌冲泪眼，重叠自西来。
即夜寒应合，非春暖不开。
岂无登陆计，宜弃济川材。
愿寄浮天外，高风万里回。','',''),('quantangshi-30684','晓发昭应','項斯','quantangshi','','卷31','行人见雪愁，初作帝乡游。
旅店开偏早，乡帆去未收。
灯残催卷席，手冷怕梳头。
是物寒无色，汤泉正自流。','',''),('quantangshi-30685','赠金州姚合使君','項斯','quantangshi','','卷31','为郎名更重，领郡是蹉跎。
官壁题诗尽，衙庭看鹤多。
城池连草堑，篱落带椒坡。
未觉旗幡贵，闲行触处过。','',''),('quantangshi-30686','送殷中丞游边','項斯','quantangshi','','卷31','话别无长夜，灯前闻曙鵶。
已行难避雪，何处合逢花？
野寺门多闭，羌楼酒不赊。
还须见边将，谁拟静尘沙。','',''),('quantangshi-30687','寄坐夏僧','項斯','quantangshi','','卷31','坐夏日偏长，知师在律堂。
多因束带热，更忆剃头凉。
苔色侵经架，松阴到簟牀。
还应炼诗句，借卧石池傍。','',''),('quantangshi-30688','寄卢式','項斯','quantangshi','','卷31','到处久南望，未知何日回。
寄书频到海，得梦忽闻雷。
岭日当秋暗，蛮花近腊开。
白身居瘴疠，谁不惜君才。','',''),('quantangshi-30689','日东病僧','項斯','quantangshi','','卷31','云水绝归路，来时风送船。
不言身后事，犹坐病中禅。
深壁藏灯影，空窗出艾烟。
已无乡土信，起塔寺门前。','',''),('quantangshi-30690','泛溪','項斯','quantangshi','','卷31','溪船泛渺弥，渐觉灭炎辉。
动水花连影，逢人鸟背飞。
深犹见白石，凉好换生衣。
未得多诗句，终须隔宿归。','',''),('quantangshi-30691','送顾少府','項斯','quantangshi','','卷31','作尉年犹少，无辞去路赊。
渔舟县前泊，山吏日高衙。
幽景临溪寺，秋蝉织杼家。
行程须过越，先醉镜湖花。','',''),('quantangshi-30692','咸阳别李处士','項斯','quantangshi','','卷31','古道自迢迢，咸阳离别桥。
越人闻水处，秦树带霜朝。
驻马言难尽，分程望易遥。
秋前未相见，此意转萧条。','',''),('quantangshi-30693','寄流人','項斯','quantangshi','','卷31','毒草不曾枯，长添客健无。
雾开蛮市合，船散海城孤。
象迹频藏齿，龙涎远蔽珠。
家人秦地老，泣对日南图。','',''),('quantangshi-30694','华顶道者','項斯','quantangshi','','卷31','仙人掌中住，生有上天期。
已废烧丹处，犹多种杏时。
养龙于浅水，寄鹤在高枝。
得道复无事，相逢尽日棊。','',''),('quantangshi-30695','酬从叔听夜泉见寄','項斯','quantangshi','','卷31','梦罢更开户，寒泉声隔云。
共谁寻最远，独自坐偏闻。
岩际和风滴，溪中泛月分。
岂知当此夜，流念到江濆。','',''),('quantangshi-30696','和李用夫栽小松','項斯','quantangshi','','卷31','移来未换叶，已胜在空山。
静对心标直，遥吟境助闲。
影侵残雪际，声透小窗间。
即耸凌空干，翛翛岂易攀。','',''),('quantangshi-30697','哭南流人','項斯','quantangshi','','卷31','遥见南来使，江头哭问君。
临终时有雪，旅葬处无云。
官库空收劒，蛮僧共起坟。
知名人尚少，谁为录遗文。','',''),('quantangshi-30698','经李白墓','項斯','quantangshi','','卷31','夜郎归未老，醉死此江边。
葬阙官家礼，诗残乐府篇。
游魂应到蜀，小碣岂旌贤。
身没犹何罪，遗坟野火燃。','',''),('quantangshi-30699','春夜樊川竹亭陪诸同年宴','項斯','quantangshi','','卷31','相知皆是旧，每恨独游频。
幸此同芳夕，宁辞倒醉身。
灯光遥映烛，萼粉暗飘茵。
明月分归骑，重来更几春。','',''),('quantangshi-30700','送僧','項斯','quantangshi','','卷31','灵山巡未徧，不作住持心。
逢寺暂投宿，是山皆独寻。
有时过静界，在处想空林。
从小即行脚，出家来至今。','',''),('quantangshi-30701','送苏处士归西山','項斯','quantangshi','','卷31','南游何所为，一箧又空归。
守道安清世，无心换白衣。
深林蝉噪暮，绝顶客来稀。
早晚重相见，论持更及微。','',''),('quantangshi-30702','游烂柯山','項斯','quantangshi','','卷31','步步出尘氛，溪山别是春。
坛边时过鹤，碁处寂无人。
访古碑多缺，探幽路不真。
翻疑归去晚，清世累移晨。','',''),('quantangshi-30703','送友人之永嘉','項斯','quantangshi','','卷31','长贫知不易，去计拟何逃。
相对人愁别，经过几处劳。
城连沙岫远，山断夏云高。
犹想成诗处，秋灯半照涛。','',''),('quantangshi-30704','巴中逢故人','項斯','quantangshi','','卷31','劳思空积岁，偶会更无由。
以分难相舍，将行且暂留。
路歧何处极，江峡半猨愁。
到此分南北，离怀岂易收。','',''),('quantangshi-30705','送归江州友人初下第','項斯','quantangshi','','卷31','名高不俟召，收采献君门。
偶屈应缘数，他人尽为冤。
新春城外路，旧隐水边村。
归去无劳久，知君更待论。','',''),('quantangshi-30706','舜城怀古','項斯','quantangshi','','卷31','禅禹逊尧聪，巍巍盛此中。
四隅咸启圣，万古赖成功。
道德去弥远，山河势不穷。
停车一再拜，帝业即今同。','',''),('quantangshi-30707','送刘道士之成都严真观','項斯','quantangshi','','卷31','严君名不朽，道出二经中。
归去精诚恳，还应梦寐通。
池台镜定月，松桧雨余风。
想对灵玄忆，人间恋若空。','',''),('quantangshi-30708','汉南遇友人','項斯','quantangshi','','卷31','此身西复东，何计此相逢。
梦尽吴越水，恨深襄汉钟。
积云开去路，曙雪叠前峰。
谁即知非旧，怜君忽见容。','',''),('quantangshi-30709','游头陀寺上方','項斯','quantangshi','','卷31','高步陟崔嵬，吟闲路惜回。
寺知何代有，僧见梵天来。
暮霭连沙积，余霞徧槛开。
更期招静者，长啸上南台。','',''),('quantangshi-30710','送友人游河东','項斯','quantangshi','','卷31','停车晓烛前，一语几潸然。
路去干戈日，乡遥饥馑年。
湖波晴见雁，槐驿晚无蝉。
莫纵经时住，东南书信偏。','',''),('quantangshi-30711','中秋夜怀','項斯','quantangshi','','卷31','趋驰早晚休，一岁又残秋。
若只如今日，何难至白头。
沧波归处远，旅食尚边愁。
赖见前贤说，穷通不自由。','',''),('quantangshi-30712','寄富春孙路处士','項斯','quantangshi','','卷31','平生醉与吟，谁是见君心。
上国一归去，沧江闲至今。
钟繁秋寺近，峰阔晚涛深。
疎放长如此，何人长得寻。','',''),('quantangshi-30713','送客归新罗','項斯','quantangshi','','卷31','君家沧海外，一别见何因。
风土虽知敎，程途自致贫。
浸天波色晚，横笛鸟行春。
明发千樯下，应无更远人。','',''),('quantangshi-30714','杭州江亭留题登眺','項斯','quantangshi','','卷31','处处日驰销，凭轩夕似朝。
渔翁闲鼓棹，沙鸟戏迎潮。
树间津亭密，城连坞寺遥。
因谁报隐者，向此得耕樵。','',''),('quantangshi-30715','荆州夜与友亲相遇','項斯','quantangshi','','卷31','山海两分歧，停舟偶似期。
别来何限意，相见却无辞。
坐永神凝梦，愁繁鬓欲丝。
趋名易迟晚，此去莫经时。','',''),('quantangshi-30716','送友人游边','項斯','quantangshi','','卷31','方春到帝京，有恋有愁并。
万里江海思，半年沙塞程。
绿阴斜向驿，残照远侵城。
自可资新课，还期振盛名。','',''),('quantangshi-30717','题赠宣州亢拾遗','項斯','quantangshi','','卷31','传骑一何催，山门昼未开。
高人终避世，圣主不遗才。
坐次欹临水，门中独举杯。
谁为旦夕侣，深寺数僧来。','',''),('quantangshi-30718','姚氏池亭','項斯','quantangshi','','卷31','池馆饶嘉致，幽人惬所闲。
筱风能动浪，岸树不遮山。
啸槛鱼惊后，眠窗鹤语间。
何须说庐阜，深处更跻攀。','',''),('quantangshi-30719','送友人之江南','項斯','quantangshi','','卷31','东南路苦辛，去路见无因。
万里此相送，故交谁更亲。
日浮汀草绿，烟霁海山春。
握手无别赠，为予书札频。','',''),('quantangshi-30720','彭蠡湖春望','項斯','quantangshi','','卷31','湖亭东极望，远棹不须回。
遍草新湖落，连天众雁来。
芦洲残照尽，云障积烟开。
更想鸱夷子，扁舟安在哉。','',''),('quantangshi-30721','闻友人会裴明府县楼','項斯','quantangshi','','卷31','闲阁雨吹尘，陶家揖上宾。
湖山万叠翠，门树一行春。
景遍归檐燕，歌喧已醉身。
登临兴不足，喜有数来因。','',''),('quantangshi-30722','归家山行','項斯','quantangshi','','卷31','献赋才何拙，经时不耻归。
能知此意是，甘取众人非。
遍陇耕无圃，缘溪钓有矶。
此怀难自遣，期在振儒衣。','',''),('quantangshi-30723','长安书怀呈知己','項斯','quantangshi','','卷31','江湖归不易，京邑计长贫。
独夜有知己，论心无故人。
一灯愁里梦，九陌病中春。
为问清平日，无门致出身。','',''),('quantangshi-30724','闻蝉','項斯','quantangshi','','卷31','动叶复惊神，声声断续匀。
坐来同听者，俱是未归人。
一棹三湘浪，单车二蜀尘。
伤秋各有日，千可念因循。','',''),('quantangshi-30725','李处土道院南楼','項斯','quantangshi','','卷31','霜晚复秋残，楼明近远山。
满壶邀我醉，一榻为僧闲。
树簇孤汀眇，帆欹积浪间。
从容更南望，殊欲外人寰。','',''),('quantangshi-30726','送顾非熊及第归茅山','項斯','quantangshi','','卷31','吟诗三十载，成此一名难。
自有恩门入，全无帝里欢。
湖光愁里碧，岩景梦中寒。
到后松杉月，何人共晓看。','',''),('quantangshi-30727','春日题李中丞樊川别墅','項斯','quantangshi','','卷31','心知受恩地，到此亦裴回。
上路移时立，中轩隔宿来。
川光通沼沚，寺影带楼台。
无限成蹊树，花多向客开。','',''),('quantangshi-30728','龙州与韩将军夜会','項斯','quantangshi','','卷31','庭绿草纤纤，边州白露沾。
别歌缘劒起，客泪是愁添。
见月鹊啼树，避风云满帘。
将军尽尊酒，楼上赋星占。','',''),('quantangshi-30729','途中逢友人','項斯','quantangshi','','卷31','长大有南北，山川各所之。
相逢孤馆夜，共忆少年时。
烂醉百花酒，狂题几首诗。
来朝又分袂，后会鬓应丝。','',''),('quantangshi-30730','送友人下第归襄阳','項斯','quantangshi','','卷31','失意已春残，归愁与别难。
山分关路细，江遶夜城寒。
草色连晴坂，鼍声离晓滩。
差池是秋赋，何以暂怀安。','',''),('quantangshi-30731','宿山寺','項斯','quantangshi','','卷31','栗叶重重覆翠微，黄昏溪上语人稀。
月明古寺客初到，风度闲门僧未归。
山果经霜多自落，水萤穿竹不停飞。
中宵能得几时睡，又被钟声催着衣。','',''),('quantangshi-30732','病鹤','項斯','quantangshi','','卷31','青云有意力犹微，岂料低回得所依。
幸念翅因风雨困，岂敎身陷稻粱肥。
曾游碧落宁无侣，见有清池不忍飞。
纵使他年引仙驾，主人恩在亦应归。','',''),('quantangshi-30733','梦仙','項斯','quantangshi','','卷31','昨宵魂梦到仙津，得见蓬山不死人。
云叶许裁成野服，玉浆敎吃润愁身。
红楼近月宜寒水，绿杏摇风占古春。
次第引看行未徧，浮光牵入世间尘。','',''),('quantangshi-30734','古扇','項斯','quantangshi','','卷31','昨日裁成夺夏威，忽逢秋节便相违。
寒尘妬尽秦王女，凉殿恩随汉主妃。
似月旧临红粉面，有风休动麝香衣。
千年萧瑟关人事，莫语当时掩泪归。','',''),('quantangshi-30735','泾州听张处士弹琴','項斯','quantangshi','','卷31','边州独夜正思乡，君又弹琴在客堂。
仿髴不离灯影外，似闻流水到潇湘。','',''),('quantangshi-30736','赠别','項斯','quantangshi','','卷31','鱼在深泉鸟在云，从来只得影相亲。
他时纵有逢君处，应作人间白发身。','',''),('quantangshi-30737','对鲙','項斯','quantangshi','','卷31','行到鲈鱼乡里时，鲙盘如雪怕风吹。
犹怜醉里江南路，马上垂鞭学钓时。','',''),('quantangshi-30738','忆朝阳峰前居','項斯','quantangshi','','卷31','每忆闲眠处，朝阳最上峰。
溪僧来自远，林路出无踪。
败褐黏苔徧，新题出石重。
霞光侵曙发，岚翠近秋浓。
健羡机能破，安危道不逢。
雪残猨到阁，庭午鹤离松。
此地虚为别，人间久未容。
何时无一事，却去养疎慵。','',''),('quantangshi-30739','暮上瞿唐峡','項斯','quantangshi','','卷31','自古艰难地，孤舟旦暮程。
独愁空托命，省已是轻生。
有树皆相倚，无岩不倒倾。
蛟螭波数怒，鬼怪火潜明。
履道知无负，离心自要惊。
何年面骨肉，细话苦辛行。','',''),('quantangshi-30740','和李中丞醉中期王征君月夜同游浐水旧居','項斯','quantangshi','','卷31','醉后情俱远，难忘素浐间。
照花深处月，当户旧时山。
事想同清话，欢期一破颜。
风流还爱竹，此夜尚思闲。','',''),('quantangshi-30741','浊水求珠','項斯','quantangshi','','卷31','灵魄自沉浮，从来任浊流。
愿从深处得，不向暗中投。
圆月时堪惜，沧波路可求。
沙寻龙窟远，泥访蚌津幽。
是宝终知贵，唯恩且用酬。
如能在公掌，的不负明眸。','',''),('quantangshi-30742','江村夜泊','項斯','quantangshi','','卷31','日落江路黑，前村人语稀。
几家深树里，一火夜渔归。','',''),('quantangshi-30743','落第后归觐喜逢僧再阳','項斯','quantangshi','','卷31','相逢须强笑，人世别离频。
去晓长侵月，归乡动隔春。
见僧心暂静，从俗事多屯。
宇宙诗名小，山河客路新。
翠桐犹入爨，青镜未辞尘。
逸足常思骥，随羣且退鳞。
宴乖红杏寺，愁在绿杨津。
羞病难为药，开眉嬾顾人。','',''),('quantangshi-30744','送越僧元瑞','項斯','quantangshi','','卷31','静中无伴侣，今亦独随缘。
昨夜离空室，焚香净去船。','',''),('quantangshi-30745','旧宫人','項斯','quantangshi','','卷31','自出先皇玉殿中，衣裳不更染深红。
宫钗折尽垂空鬓，内扇穿多减半风。
桃熟亦曾君手赐，酒阑犹候妾歌终。
如今还向城边住，御水东流意不通。','',''),('quantangshi-30746','梦游仙','項斯','quantangshi','','卷31','梦游飞上天家楼，珠箔当风挂玉钩。
鹦鹉隔帘呼再拜，水仙移镜嬾梳头。
丹霞不是人间晓，碧树仍逢岫外秋。
将谓便长于此地，鸡声入耳所堪愁。','',''),('quantangshi-30747','送宫人入道','項斯','quantangshi','','卷31','愿随仙女董双成，王母前头作伴行。
初戴玉冠多悞拜，欲辞金殿别称名。
将敲碧落新斋磬，却进昭阳旧赐筝。
旦暮焚香绕坛上，步虚犹作按歌声。','',''),('quantangshi-30748','长安退将','項斯','quantangshi','','卷31','塞外冲沙损眼明，归来养病住秦京。
上高楼阁看星坐，着白衣裳把劒行。
常说老身思鬬将，最悲无力制蕃营。
翠眉红脸和回鹘，惆怅中原不用兵。','',''),('quantangshi-30749','遥装夜','項斯','quantangshi','','卷31','卷席贫抛壁下牀，且铺他处对灯光。
欲行千里从今夜，犹惜残春发故乡。
蚊蚋已生团扇急，衣裳未了剪刀忙。
谁知更有芙蓉浦，南去令人愁思长。','',''),('quantangshi-30750','送苗七求职','項斯','quantangshi','','卷31','相逢未得三回笑，风送离情入剪刀。
客路最能销日月，梦魂空自畏波涛。
独眠秋夜琴声急，未拜军城劒色高。
去去缘多山与海，鹤身宁肯为飞劳。','',''),('quantangshi-30751','山行','項斯','quantangshi','','卷31','青枥林深亦有人，一渠流水数家分。
山当日午回峰影，草带泥痕过鹿羣。
蒸茗气从茅舍出，缲丝声隔竹篱闻。
行逢卖药归来客，不惜相随入岛云。','',''),('quantangshi-30752','题永忻寺影堂','項斯','quantangshi','','卷31','不遇修寺日，无钱入影堂。
故来空礼拜，临去重添香。
僧得名难近，灯传火已长。
发心依止后，借住有邻房。','',''),('quantangshi-30753','献令狐相公时相公郊坛行事回','項斯','quantangshi','','卷31','鹗在卿云冰在壶，代天才业本訏谟。
荣同伊陟传朱户，秀比王商入画图。
昨夜星辰回劒履，前年风月满江湖。
不知机务时多暇，还许诗家属和无。','',''),('quantangshi-30754','句','項斯','quantangshi','','卷31','佳人背江坐，眉际列烟树。
马蹄没青莎，船迹成空波。
春风吹两意，何意更相值。
更望会稽何处是，沙连竹箭白鹇羣。','',''),('quantangshi-30755','校猎曲','馬戴','quantangshi','','卷31','楚子畋郊野，布罟笼天涯。
浮云张作罗，万草结成罝。
意在绝飞鸟，臂弓腰镆鎁。
远将射句践，次欲诛夫差。
壮志一朝尽，他□□繁华。
当时能猎贤，保国兼保家。','',''),('quantangshi-30756','蛮家','馬戴','quantangshi','','卷31','领得卖珠钱，还归铜柱边。
看儿调小象，打鼓放新船。
醉后眠神树，耕时语瘴烟。
又逢衰蹇老，相问莫知年。','',''),('quantangshi-30757','春思','馬戴','quantangshi','','卷31','初日照杨柳，玉楼含翠阴。
啼春独鸟思，望远佳人心。
幽怨贮瑶瑟，韶光凝碧林。
所思曾不见，芳草意空深。','',''),('quantangshi-30758','送从叔赴南海幕','馬戴','quantangshi','','卷31','洞庭秋色起，哀狖更难闻。
身往海边郡，帆悬天际云。
炎州罗翠鸟，瘴岭控蛮军。
信息来非易，堪悲此路分。','',''),('quantangshi-30759','江行留别','馬戴','quantangshi','','卷31','吴楚半秋色，渡江逢苇花。
云侵帆影尽，风逼雁行斜。
返照开岚翠，寒潮荡浦沙。
余将何所往，海峤拟营家。','',''),('quantangshi-30760','将别寄友人','馬戴','quantangshi','','卷31','帝乡归未得，辛苦事羇游。
别馆一尊酒，客程千里秋。
霜风红叶寺，夜雨白苹洲。
长恐此时泪，不禁和恨流。','',''),('quantangshi-30761','客行','馬戴','quantangshi','','卷31','路岐长不尽，客恨杳难通。
芦荻晚汀雨，柳花南浦风。
乱钟嘶马急，残日半帆红。
却羡渔樵侣，闲歌落照中。','',''),('quantangshi-30762','过野叟居','馬戴','quantangshi','','卷31','野人闲种树，树老野人前。
居止白云内，渔樵沧海边。
呼儿采山药，放犊饮溪泉。
自着养生论，无烦忧暮年。','',''),('quantangshi-30763','答光州王使君','馬戴','quantangshi','','卷31','信来淮上郡，楚岫入秦云。
自顾为儒者，何由答使君。
蜕风蝉半失，阻雨雁频闻。
欲识平生分，他时别纪勋。','',''),('quantangshi-30764','下第再过崔邵池阳居','馬戴','quantangshi','','卷31','岂无故乡路，路远未成归。
关内相知少，海边来信稀。
离云空石穴，芳草偃郊扉。
谢子一留宿，此心聊息机。','',''),('quantangshi-30765','夕次淮口','馬戴','quantangshi','','卷31','天涯秋光尽，木末羣鸟还。
夜久游子息，月明岐路闲。
风生淮水上，帆落楚云间。
此意竟谁见，行行非故关。','',''),('quantangshi-30766','落日怅望','馬戴','quantangshi','','卷31','孤云与归鸟，千里片时间。
念我一何滞，辞家久未还。
微阳下乔木，远色隐秋山。
临水不敢照，恐惊平昔颜。','',''),('quantangshi-30767','早发故山作','馬戴','quantangshi','','卷31','云门夹峭石，石路荫长松。
谷响猨相应，山深水复重。
餐霞人不见，采药客犹逢。
独宿灵潭侧，时闻岳顶钟。','',''),('quantangshi-30768','下第别郜扶','馬戴','quantangshi','','卷31','穷途别故人，京洛泣风尘。
在世即应老，他乡又欲春。
平生空志学，晚岁拙谋身。
静话归休计，唯将海上亲。','',''),('quantangshi-30769','寄终南真空禅师','馬戴','quantangshi','','卷31','闲想白云外，了然清净僧。
松门山半寺，夜雨佛前灯。
此境可长住，浮生自不能。
一从林下别，瀑布几成冰。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-30770','长安寓居寄赠贾岛','馬戴','quantangshi','','卷31','岁暮见华发，平生志半空。
孤云不我弃，归隐与谁同。
枉道紫宸谒，妨栽丹桂丛。
何如随野鹿，栖止石岩中。','',''),('quantangshi-30771','秋郊夕望','馬戴','quantangshi','','卷31','度鸟向栖急，阴虫逢夜多。
余霞媚秋汉，迥月濯沧波。
蔓草将萎绝，流年其奈何。
耿然摇落思，独酌不成歌。','',''),('quantangshi-30772','赠越客','馬戴','quantangshi','','卷31','故国波涛隔，明时已久留。
献书双阙晚，看月五陵秋。
南棹何时返，长江忆共游。
遥知钓船畔，相望在汀洲。','',''),('quantangshi-30773','送顾非熊下第归江南','馬戴','quantangshi','','卷31','无成西别秦，返驾江南春。
草际楚田雁，舟中吴苑人。
残云挂绝岛，迥树入通津。
想到长洲日，门前多白苹。','',''),('quantangshi-30774','汧上劝旧友','馬戴','quantangshi','','卷31','斗酒故人同，长歌起北风。
斜阳高垒闭，秋角暮山空。
雁叫寒流上，萤飞薄雾中。
坐来生白发，况复久从戎。','',''),('quantangshi-30775','送狄参军赴杭州','馬戴','quantangshi','','卷31','新官非次受，圣主宠前勋。
关雪发车晚，风涛挂席闻。
海门山叠翠，湖岸郡藏云。
执简从公后，髯参岂胜君。','',''),('quantangshi-30776','过故人所迁新居','馬戴','quantangshi','','卷31','金马诏何晚，茂陵居近修。
客来云雨散，鸟下梧桐秋。
迥汉衔天阙，遥泉响御沟。
坐看凉月上，为子一淹留。','',''),('quantangshi-30777','落照','馬戴','quantangshi','','卷31','照曜天山外，飞鸦几共过。
微红拂秋汉，片白透长波。
影促寒汀薄，光残古木多。
金霞与云气，散漫复相和。','',''),('quantangshi-30778','宿崔邵池阳别墅','馬戴','quantangshi','','卷31','杨柳色已改，郊原日复低。
烟生寒渚上，霞散乱山西。
待月人相对，惊风雁不齐。
此心君莫问，旧国去将迷。','',''),('quantangshi-30779','楚江怀古三首 一','馬戴','quantangshi','','卷31','露气寒光集，微阳下楚丘。
猨啼洞庭树，人在木兰舟。
广泽生明月，苍山夹乱流。
云中君不降，竟夕自悲秋。','',''),('quantangshi-30780','楚江怀古三首 二','馬戴','quantangshi','','卷31','惊鸟去无际，寒蛩鸣我傍。
芦洲生早雾，兰隰下微霜。
列宿分穷野，空流注大荒。
看山候明月，聊自整云装。','',''),('quantangshi-30781','楚江怀古三首 三','馬戴','quantangshi','','卷31','野风吹蕙带，骤雨滴兰桡。
屈宋魂冥寞，江山思寂寥。
阴霓侵晚景，海树入回潮。
欲折寒芳荐，明神讵可招。','',''),('quantangshi-30782','远水','馬戴','quantangshi','','卷31','荡漾空沙际，虚明入远天。
秋光照不极，鸟影去无边。
势引长云断，波轻片雪连。
汀洲杳难到，万古覆苍烟。','',''),('quantangshi-30783','夕发邠宁寄从弟','馬戴','quantangshi','','卷31','半酣走马别，别后锁边城。
日落月未上，鸟栖人独行。
方驰故国恋，复怆长年情。
入夜不能息，何当闲此生。','',''),('quantangshi-30784','赠别北客','馬戴','quantangshi','','卷31','君生游侠地，感激气何高。
饮尽玉壶酒，赠留金错刀。
雁关飞霰雪，鲸海落云涛。
决去如征鸟，离心空自劳。','',''),('quantangshi-30785','夜下湘中','馬戴','quantangshi','','卷31','洞庭人夜别，孤棹下湘中。
露洗寒山遍，波摇楚月空。
密林飞暗狖，广泽发鸣鸿。
行值扬帆者，江分又不同。','',''),('quantangshi-30786','送吕郎中牧东海郡','馬戴','quantangshi','','卷31','假道经淮泗，樯乌集隼旟。
芜城沙菼接，波岛石林疎。
海鹤空庭下，夷人远岸居。
山乡足遗老，伫听荐贤书。','',''),('quantangshi-30787','山行偶作','馬戴','quantangshi','','卷31','缘危路忽穷，投宿值樵翁。
鸟下山含暝，蝉鸣露滴空。
石门斜月入，云窦暗泉通。
寂寞生幽思，心疑旧隐同。','',''),('quantangshi-30788','巴江夜猨','馬戴','quantangshi','','卷31','日饮巴江水，还啼巴岸边。
秋声巫峡断，夜影楚云连。
露滴青枫树，山空明月天。
谁知泊船者，听此不能眠。','',''),('quantangshi-30789','送田使君牧蔡州','馬戴','quantangshi','','卷31','主意思政理，牧人官不轻。
树多淮右地，山远汝南城。
望稼周田隔，登楼楚月生。
悬知蒋亭下，渚鹤伴闲行。','',''),('quantangshi-30790','雀台怨','馬戴','quantangshi','','卷31','魏宫歌舞地，蝶戏鸟还鸣。
玉座人难到，铜台雨滴平。
西陵树不见，漳浦草空生。
万恨尽埋此，徒悬千载名。','',''),('quantangshi-30791','早发故园','馬戴','quantangshi','','卷31','语别在中夜，登车离故乡。
曙钟寒出岳，残月迥凝霜。
风柳条多折，沙云气尽黄。
行逢海西雁，零落不成行。','',''),('quantangshi-30792','赠别江客','馬戴','quantangshi','','卷31','湘中有岑穴，君去挂帆过。
露细蒹葭广，潮回岛屿多。
汀洲延夕照，枫叶坠寒波。
应使同渔者，生涯许钓歌。','',''),('quantangshi-30793','宿翠微寺','馬戴','quantangshi','','卷31','处处松阴满，樵开一迳通。
鸟归云壑静，僧语石楼空。
积翠含微月，遥泉韵细风。
经行心不厌，忆在故山中。','',''),('quantangshi-30794','霁后寄白阁僧','馬戴','quantangshi','','卷31','苍翠霾高雪，西峯鸟外看。
久披山衲坏，孤坐石牀寒。
盥手水泉滴，燃灯夜烧残。
终期老云峤，煮药伴中餐。','',''),('quantangshi-30795','送僧归金山寺','馬戴','quantangshi','','卷31','金陵山色里，蝉急向秋分。
迥寺横洲岛，归僧渡水云。
夕阳依岸尽，清磬隔潮闻。
遥想禅林下，炉香带月焚。','',''),('quantangshi-30796','新秋雨霁宿王处士东郊','馬戴','quantangshi','','卷31','夕阳逢一雨，夜木洗清阴。
露气竹窗静，秋光云月深。
煎尝灵药味，话及故山心。
得意两不寐，微风生玉琴。','',''),('quantangshi-30797','关山曲二首 一','馬戴','quantangshi','','卷31','金甲耀兜鍪，黄金拂紫骝。
叛羌旗下戮，陷壁夜中收。
霜霰戎衣月，关河碛气秋。
箭疮殊未合，更遣击兰州。','',''),('quantangshi-30798','关山曲二首 二','馬戴','quantangshi','','卷31','火发龙山北，中宵易左贤。
勒兵临汉水，惊雁散胡天。
木落防河急，军孤受敌偏。
犹闻汉皇怒，按劒待开边。','',''),('quantangshi-30799','塞下曲二首 一','馬戴','quantangshi','','卷31','旌旗倒北风，霜霰逐南鸿。
夜救龙城急，朝焚虏帐空。
骨销金镞在，鬓改玉关中。
却想羲轩氏，无人尚战功。','',''),('quantangshi-30800','塞下曲二首 二','馬戴','quantangshi','','卷31','广漠云凝惨，日斜飞霰生。
烧山搜猛兽，伏道击回兵。
风折旗竿曲，沙埋树杪平。
黄云飞旦夕，偏奏苦寒声。','',''),('quantangshi-30801','广陵曲','馬戴','quantangshi','','卷31','葱茏桂树枝，高系黄金羁。
叶隐青蛾翠，花飘白玉墀。
上鸣间关鸟，下醉游侠儿。
炀帝国已破，此中都不知。','',''),('quantangshi-30802','送人游蜀','馬戴','quantangshi','','卷31','别离杨柳陌，迢遰蜀门行。
若听清猨后，应多白发生。
虹霓侵栈道，风雨杂江声。
过尽愁人处，烟花是锦城。','',''),('quantangshi-30803','宿无可上人房','馬戴','quantangshi','','卷31','稀逢息心侣，细话远山期。
河汉秋深夜，杉梧露滴时。
风传林磬响，月掩草堂迟。
坐卧禅心在，浮生皆不知。','',''),('quantangshi-30804','旅次夏州','馬戴','quantangshi','','卷31','嘶马发相续，行次夏王台。
锁郡云阴暮，鸣笳烧色来。
霜繁边上宿，鬓改碛中回。
怅望胡沙晓，惊蓬朔吹催。','',''),('quantangshi-30805','同庄秀才宿镇星观','馬戴','quantangshi','','卷31','的的星河落，霑苔复洒松。
湿光微泛草，石翠澹摇峰。
野观云和月，秋城漏间钟。
知君亲此境，九陌少相逢。','',''),('quantangshi-30806','鹳雀楼晴望','馬戴','quantangshi','','卷31','尧女楼西望，人怀太古时。
海波通禹凿，山木闭虞祠。
鸟道残虹挂，龙潭返照移。
行云如可驭，万里赴心期。','',''),('quantangshi-30807','赠淮南将','馬戴','quantangshi','','卷31','何事淮南将，功高业未成。
风涛辞海郡，雷雨镇山营。
度碛黄云起，防秋白发生。
密机曾制敌，忧国更论兵。
塞色侵旗动，寒光锁甲明。
自怜心有作，独立望专征。','',''),('quantangshi-30808','寄贾岛','馬戴','quantangshi','','卷31','海上不同来，关中俱久住。
寻思别山日，老尽经行树。
志业人未闻，时光鸟空度。
风悲汉苑秋，雨滴秦城暮。
佩玉与锵金，非亲亦非故。
朱颜枉自毁，明代空相遇。
岁晏各能归，心知旧歧路。','',''),('quantangshi-30809','湘川吊舜','馬戴','quantangshi','','卷31','伊予生好古，吊舜苍梧间。
白日坐将没，游波凝不还。
九疑云动影，旷野竹成班。
雁集蒹葭渚，猨啼雾露山。
南风吹早恨，瑶瑟怨长闲。
元化谁能问，天门恨久关。','',''),('quantangshi-30810','送僧归闽中旧寺','馬戴','quantangshi','','卷31','寺隔海山遥，帆前落叶飘。
断猨通楚塞，惊鹭出兰桡。
星月浮波岛，烟萝渡石桥。
钟声催野饭，秋色落寒潮。
旧社人多老，闲房树半凋。
空林容病士，岁晚待相招。','',''),('quantangshi-30811','寄远','馬戴','quantangshi','','卷31','坐想亲爱远，行嗟天地阔。
积疹甘毁颜，沈忧更销骨。
迢迢游子心，望望归云没。
乔木非故里，高楼共明月。
夜深秋风多，闻雁来天末。','',''),('quantangshi-30812','经咸阳北原','馬戴','quantangshi','','卷31','秦山曾共转，秦云自舒卷。
古来争雄图，到此多不返。
野狖穴孤坟，农人耕废苑。
川长波又逝，日与岁俱晚。
夜入咸阳中，悲吞不能饭。','',''),('quantangshi-30813','冬日寄洛中杨少尹','馬戴','quantangshi','','卷31','黄河岸柳衰，城下渡流澌。
年长从公懒，天寒入府迟。
家山望几遍，魏阙赴何时。
怀古心谁识，应多谒舜祠。','',''),('quantangshi-30814','浙江夜宿','馬戴','quantangshi','','卷31','落帆人更起，露草满汀洲。
远狖啼荒峤，孤萤溺漫流。
积阴开片月，爽气集高秋。
去去胡为恋，搴芳时一游。','',''),('quantangshi-30815','寄西岳白石僧','馬戴','quantangshi','','卷31','挂锡中峯上，经行踏石梯。
云房出定后，岳月在池西。
峭壁残霞照，欹松积雪齐。
年年着山屐，曾得到招提。','',''),('quantangshi-30816','同州冬日陪吴常侍闲宴','馬戴','quantangshi','','卷31','中天白云散，集客郡斋时。
陶性聊飞爵，看山忽罢碁。
雪花凝始散，木叶脱无遗。
静理良多暇，招邀惬所思。','',''),('quantangshi-30817','答鄜畤友人同宿见示','馬戴','quantangshi','','卷31','为客自堪悲，风尘日满衣。
承明无计入，旧隐但怀归。
雪积孤城暗，灯残晓角微。
相逢喜同宿，此地故人稀。','',''),('quantangshi-30818','题僧禅院','馬戴','quantangshi','','卷31','虚室焚香久，禅心悟几生。
滤泉侵月起，扫径避虫行。
树隔前朝在，苔滋废渚平。
我来风雨夜，像设一灯明。','',''),('quantangshi-30819','怀故山寄贾岛','馬戴','quantangshi','','卷31','心偶羡明代，学诗观国风。
自从来阙下，未胜在山中。
丹桂日应老，白云居久空。
谁能谢诗去，聊与此生同。','',''),('quantangshi-30820','灞上秋居','馬戴','quantangshi','','卷31','灞原风雨定，晚见雁行频。
落叶他乡树，寒灯独夜人。
空园白露滴，孤壁野僧隣。
寄卧郊扉久，何门致此身。','',''),('quantangshi-30821','寄崇德里居作','馬戴','quantangshi','','卷31','扫君园林地，泽我清凉襟。
高鸟云路晚，孤蝉杨柳深。
风微汉宫漏，月迥秦城砧。
光景坐如此，徒怀经济心。','',''),('quantangshi-30822','河梁别','馬戴','quantangshi','','卷31','河梁送别者，行哭半非亲。
此路足征客，胡天多杀人。
金罍照离思，宝瑟凝残春。
早晚期相见，垂杨凋复新。','',''),('quantangshi-30823','留别定襄卢军事','馬戴','quantangshi','','卷31','行行与君别，路在雁门西。
秋色见边草，军声闻戍鼙。
酣歌击宝劒，跃马上金堤。
归去咸阳里，平生志不迷。','',''),('quantangshi-30824','送杜秀才东游','馬戴','quantangshi','','卷31','羇游年复长，去日值秋残。
草出函关白，云藏野渡寒。
鸿多霜雪重，山广道途难。
心事何人识，斗牛应数看。','',''),('quantangshi-30825','怀黄颇','馬戴','quantangshi','','卷31','有客南浮去，平生与我同。
炎州结遥思，芳杜采应空。
秦雁归侵月，湘猿戏褭枫。
期君翼明代，未可恋山中。','',''),('quantangshi-30826','陇上独望','馬戴','quantangshi','','卷31','斜日挂边树，萧萧独望间。
阴云藏汉垒，飞火照胡山。
陇首行人绝，河源夕鸟还。
谁为立勋者，可惜宝刀闲。','',''),('quantangshi-30827','长安书怀','馬戴','quantangshi','','卷31','岐路今如此，还堪恸哭频。
关中成久客，海上老诸亲。
谷口田应废，乡山草又春。
年年销壮志，空作献书人。','',''),('quantangshi-30828','邯郸驿楼作','馬戴','quantangshi','','卷31','芜没丛台久，清漳废御沟。
蝉鸣河外树，人在驿西楼。
云烧天中赤，山当日落秋。
近郊经战后，处处骨成丘。','',''),('quantangshi-30829','别家后次飞狐西即事','馬戴','quantangshi','','卷31','远归从此别，亲爱失天涯。
去国频回首，方秋不在家。
鸣蛩闻塞路，冷雁背龙沙。
西次桑干曲，洲中见荻花。','',''),('quantangshi-30830','题青龙寺镜公房','馬戴','quantangshi','','卷31','一室意何有，闲门为我开。
炉香寒自灭，履雪饭初回。
窗迥孤山入，灯残片月来。
禅心方此地，不必访天台。','',''),('quantangshi-30831','边城独望','馬戴','quantangshi','','卷31','聊凭危堞望，倍起异乡情。
霜落蒹葭白，山昏雾露生。
河滩胡雁下，戎垒汉鼙惊。
独树残秋色，狂歌泪满缨。','',''),('quantangshi-30832','江亭赠别','馬戴','quantangshi','','卷31','长亭晚送君，秋色渡江濆。
衰柳风难定，寒涛雪不分。
猨声离楚峡，帆影入湘云。
独泛扁舟夜，山钟可卧闻。','',''),('quantangshi-30833','旅次寄贾岛兼简无可上人','馬戴','quantangshi','','卷31','相思边草长，回望水连空。
雁过当行次，蝉鸣复客中。
壮年看即改，羸病计多同。
傥宿林中寺，深凭问远公。','',''),('quantangshi-30834','寄剡中友人','馬戴','quantangshi','','卷31','故人今在剡，秋草意如何。
岭暮云霞杂，潮回岛屿多。
沃洲僧几访，天姥客谁过。
岁晚偏相忆，风生隔楚波。','',''),('quantangshi-30835','送国子韦丞','馬戴','quantangshi','','卷31','临水独相送，归期千里间。
云回逢过雨，路转入连山。
一骑行芳草，新蝉发故关。
遥聆茂陵下，夜启竹扉闲。','',''),('quantangshi-30836','题吴发原南居','馬戴','quantangshi','','卷31','闲居谁厌僻，门掩汉祠前。
山色夏云映，树阴幽草连。
晴光分渚曲，绿气冒原田。
何日远游罢，高枝已噪蝉。','',''),('quantangshi-30837','雒中寒夜姚侍御宅怀贾岛','馬戴','quantangshi','','卷31','夜木动寒色，雒阳城阙深。
如何异乡思，更抱故人心。
微月关山远，闲堦霜霰侵。
谁知石门路，待与子同寻。','',''),('quantangshi-30838','征妇叹','馬戴','quantangshi','','卷31','稚子在我抱，送君登远道。
稚子今已行，念君上边城。
蓬根既无定，蓬子焉用生。
但见请防胡，不闻言罢兵。
及老能得归，少者还长征。','',''),('quantangshi-30839','山中寄姚合员外','馬戴','quantangshi','','卷31','朝与城阙别，暮同麋鹿归。
鸟鸣松观静，人过石桥稀。
木叶摇山翠，泉痕入涧扉。
敢招仙署客，暂此拂朝衣。','',''),('quantangshi-30840','中秋月','馬戴','quantangshi','','卷31','阴魄出海上，望之增苦吟。
冷搜骊颔重，寒彻蚌胎深。
皓气笼诸夏，清光射万岑。
悠然天地内，皎洁一般心。','',''),('quantangshi-30841','下第寄友人','馬戴','quantangshi','','卷31','金门君待问，石室我思归。
圣主尊黄屋，何人荐白衣。
年来御沟柳，赠别雨霏霏。','',''),('quantangshi-30842','寄广州杨参军','馬戴','quantangshi','','卷31','南方春景好，念子缓归心。
身方脱野服，冠未系朝簪。
足恣平生赏，无虞外役侵。
汀洲观鸟戏，向月和猨吟。
税驾楚山广，扬帆湘水深。
采奇搜石穴，怀胜即枫林。
怅望极霞际，流情堕海阴。
前朝杳难问，叹息洒鸣琴。','',''),('quantangshi-30843','离夜二首 一','馬戴','quantangshi','','卷31','东征辽水迥，北近单于台。
戎衣挂宝剑，玉筯衔金杯。
红烛暗将灭，翠蛾终不开。','',''),('quantangshi-30844','离夜二首 二','馬戴','quantangshi','','卷31','凝夜照离色，恐闻啼晚鸦。
前年营雁塞，明月戍龙沙。
曾与五陵子，休装孤剑花。','',''),('quantangshi-30845','答太原从军杨员外送别','馬戴','quantangshi','','卷31','君将海月佩，赠之光我行。
见知言不浅，怀报意非轻。
反照临歧思，中年未达情。
河梁人送别，秋汉雁相鸣。
衰柳摇边吹，寒云冒古城。
西游还献赋，应许托平生。','',''),('quantangshi-30846','送从叔重赴海南从事','馬戴','quantangshi','','卷31','又从连帅请，还作岭南行。
穷海何时到，孤帆累月程。
乱蝉吟暮色，哀狖落秋声。
晚路潮波起，寒葭雾雨生。
沙埋铜柱没，山簇瘴云平。
念此别离苦，其如宗从情。','',''),('quantangshi-30847','送韩校书江西从事','馬戴','quantangshi','','卷31','出关寒色尽，云梦草生新。
雁背岳阳雨，客行江上春。
遥程随水阔，枉路倒帆频。
夕照临孤馆，朝霞发广津。
湖山潮半隔，郡壁岸斜邻。
自此钟陵道，裁书有故人。','',''),('quantangshi-30848','送顾少府之永康','馬戴','quantangshi','','卷31','婺女星边去，春生即有花。
寒关云复雪，古渡草连沙。
宿次吴江晚，行侵日徼斜。
官传梅福政，县顾赤松家。
烧起明山翠，潮回动海霞。
清高宜阅此，莫叹近天涯。','',''),('quantangshi-30849','幽上留别令狐侍郎','馬戴','quantangshi','','卷31','自别丘中隐，频年哭路岐。
辛勤今若是，少壮岂多时。
露滴阴虫苦，秋声远客悲。
晚营严鼓角，红叶拂旌旗。
北阙虚延望，西林久见思。
川流寒水急，云返故山迟。
落照游人去，长空独鸟随。
不堪风景隔，忠信寡相知。','',''),('quantangshi-30850','襄阳席上呈于司空','馬戴','quantangshi','','卷31','花枝临水复临堤，也照清江也照泥。
寄语东君好抬举，夜来曾伴凤皇栖。','',''),('quantangshi-30851','宿裴氏溪居怀厉玄先辈','馬戴','quantangshi','','卷31','树下孤石坐，草间微有霜。
同人不同北，云鸟自南翔。
迢遰夜山色，清泠泉月光。
西风耿离抱，江海遥相望。','',''),('quantangshi-30852','集宿姚殿中宅期僧无可不至','馬戴','quantangshi','','卷31','殿中日相命，开尊话旧时。
余钟催鸟绝，积雪阻僧期。
林静寒光远，天阴曙色迟。
今夕复何夕，人谒去难追。','',''),('quantangshi-30853','宿贾岛原居','馬戴','quantangshi','','卷31','寒雁过原急，渚边秋色深。
烟霞向海岛，风雨宿园林。
俱住明时愿，同怀故国心。
未能先隐迹，聊此一相寻。','',''),('quantangshi-30854','赠别空公','馬戴','quantangshi','','卷31','云门秋却入，微径久无人。
后夜中峰月，空林百衲身。
寂寥寒磬尽，盥漱瀑泉新。
履迹谁相见，松风扫石尘。','',''),('quantangshi-30855','府试观开元皇帝东封图','馬戴','quantangshi','','卷31','俨若翠华举，登封图乍开。
冕旒明主立，冠剑侍臣陪。
迹类飞仙去，光同拜日来。
粉痕疑检玉，黛色讶生苔。
挂壁云将起，陵风仗若回。
何年复东幸，鲁叟望悠哉。','',''),('quantangshi-30856','府试水始冰','馬戴','quantangshi','','卷31','南池寒色动，北陆岁阴生。
薄薄流澌聚，漓漓翠潋平。
暗霑霜稍厚，回照日还轻。
乳窦悬残滴，湘流减恨声。
即堪金井贮，会映玉壶清。
洁白心虽识，空期饮此明。','',''),('quantangshi-30857','边馆逢贺秀才','馬戴','quantangshi','','卷31','贫病无疎我与君，不知何事久离羣。
鹿裘共弊同为客，龙阙将移拟献文。
空馆夕阳鸦绕树，荒城寒色雁和云。
不堪吟断边笳晓，叶落东西客又分。','',''),('quantangshi-30858','宿王屋天坛','馬戴','quantangshi','','卷31','星斗半沈苍翠色，红霞远照海涛分。
折松晓拂天坛雪，投简寒窥玉洞云。
绝顶醮回人不见，深林磬度鸟应闻。
未知谁与传金箓，独向仙祠拜老君。','',''),('quantangshi-30859','岐阳逢曲阳故人话旧','馬戴','quantangshi','','卷31','异地还相见，平生问可知。
壮年俱欲暮，往事尽堪悲。
道路频艰阻，亲朋久别离。
解兵逃白刃，谒帝值明时。
淹疾生涯故，因官事业移。
鸡鸣关月落，雁度朔风吹。
客泪翻岐下，乡心落海湄。
积愁何计遣，满酌浣相思。','',''),('quantangshi-30860','赠禅僧','馬戴','quantangshi','','卷31','弟子人天遍，童年在沃洲。
开禅山木长，浣衲海沙秋。
振锡摇汀月，持瓶接瀑流。
赤城何日上，鄙愿从师游。','',''),('quantangshi-30861','题庐山寺','馬戴','quantangshi','','卷31','白茅为屋宇编荆，数处堦墀石叠成。
东谷笑言西谷响，下方云雨上方晴。
鼠惊樵客缘苍壁，猨戏山头撼紫柽。
别有一条投涧水，竹筒斜引入茶铛。','',''),('quantangshi-30862','题石瓮寺','馬戴','quantangshi','','卷31','僧室并皇宫，云门辇路同。
渭分双阙北，山迥五陵东。
修绠悬林表，深泉汲洞中。
人烟窥垤蚁，鸳瓦拂冥鸿。
藓壁松生峭，龛灯月照空。
稀逢息心侣，独礼竺干公。','',''),('quantangshi-30863','谒仙观二首 一','馬戴','quantangshi','','卷31','我生求羽化，斋沐造仙居。
葛蔓没丹井，石函盛道书。
寒松多偃侧，灵洞遍清虚。
一就泉西饮，云中采药蔬。','',''),('quantangshi-30864','谒仙观二首 二','馬戴','quantangshi','','卷31','山空蕙气香，乳管折云房。
愿值壶中客，亲传肘后方。
三更礼星斗，寸匕服丹霜。
默坐树阴下，仙经横石牀。','',''),('quantangshi-30865','送朴山人归新罗','馬戴','quantangshi','','卷31','浩渺行无极，扬帆但信风。
云山过海半，乡树入舟中。
波定遥天出，沙平远岸穷。
离心寄何处，目断曙霞东。','',''),('quantangshi-30866','题静住寺钦用上人房','馬戴','quantangshi','','卷31','寺近朝天路，多闻玉佩音。
鉴人开慧眼，归鸟息禅心。
磬接星河曙，窗连夏木深。
此中能宴坐，何必在云林。','',''),('quantangshi-30867','赠杨先辈','馬戴','quantangshi','','卷31','平生闲放久，野鹿许为羣。
居止邻西岳，轩窗度白云。
斋心饭松子，话道接茅君。
汉主思清净，休书谏猎文。','',''),('quantangshi-30868','酬李景章先辈','馬戴','quantangshi','','卷31','平生诗句忝多同，不得陪君奉至公。
金镝自宜先中鹄，铅刀甘且学雕虫。
莺啼细柳临关路，燕接飞花遶汉宫。
九陌芳菲人竞赏，此时心在别离中。','',''),('quantangshi-30869','赠祠部令狐郎中','馬戴','quantangshi','','卷31','官初执宪称雄才，省转为郎雅望催。
待制松阴移玉殿，分宵露气静天台。
算棋默向孤云坐，随鹤闲穷片水回。
忽忆十年相识日，小儒新自海边来。','',''),('quantangshi-30870','送册东夷王使','馬戴','quantangshi','','卷31','越海传金册，华夷礼命行。
片帆秋色动，万里信潮生。
日映孤舟出，沙连绝岛明。
翳空翻大鸟，飞雪洒长鲸。
旧鬓回应改，遐荒梦易惊。
何当理风檝，天外问来程。','',''),('quantangshi-30871','送武陵王将军','馬戴','quantangshi','','卷31','河外今无事，将军有战名。
艰难长剑缺，功业少年成。
晓仗亲云陛，寒宵突禁营。
朱旗身外色，玉漏耳边声。
开合谈宾至，调弓过雁惊。
为儒多不达，见学请长缨。','',''),('quantangshi-30872','赠鄠县尉李先辈二首 一','馬戴','quantangshi','','卷31','同人家鄠杜，相见罢官时。
野坐苔生石，荒居菊入篱。
听蝉临水久，送鹤背山迟。
未拟还城阙，溪僧别有期。','',''),('quantangshi-30873','赠鄠县尉李先辈二首 二','馬戴','quantangshi','','卷31','休官不到阙，求静匪营他。
种药唯愁晚，看云肯厌多。
渚边逢鹭下，林表伴僧过。
闲检仙方试，松花酒自和。','',''),('quantangshi-30874','边将','馬戴','quantangshi','','卷31','玉榼酒频倾，论功笑李陵。
红缰跑骏马，金镞掣秋鹰。
塞迥连天雪，河深彻底冰。
谁言提一剑，勤苦事中兴。','',''),('quantangshi-30875','下第别令狐员外','馬戴','quantangshi','','卷31','论文期雨夜，饮酒及芳晨。
坐叹百花发，潜惊双鬓新。
旧交多得路，别业远仍贫。
便欲辞知己，归耕海上春。','',''),('quantangshi-30876','送春坊董正字浙右归觐','馬戴','quantangshi','','卷31','去觐毗陵日，秋残建业中。
莎垂石城古，山阔海门空。
灌木寒樯远，层波皓月同。
何当复雠校，春集少阳宫。','',''),('quantangshi-30877','送和北虏使','馬戴','quantangshi','','卷31','路始阴山北，迢迢雨雪天。
长城人过少，沙碛马难前。
日入流沙际，阴生瀚海边。
刀镮向月动，旌纛冒霜悬。
逐兽孤围合，交兵一箭传。
穹庐移斥候，烽火绝祁连。
汉将行持节，胡儿坐控弦。
明妃的回面，南送使君旋。','',''),('quantangshi-30878','摅情留别并州从事','馬戴','quantangshi','','卷31','浅学长自鄙，谬承贤达知。
才希汉主召，玉任楚人疑。
年长慙漂泊，恩深惜别离。
秋光独鸟过，暝色一蝉悲。
鹤发生何速，龙门上苦迟。
雕虫羞朗鉴，干禄贵明时。
故国诚难返，青云致未期。
空将感激泪，一自洒临岐。','',''),('quantangshi-30879','酬田卿送西游','馬戴','quantangshi','','卷31','华堂开翠簟，惜别玉壶深。
客去当烦暑，蝉鸣复此心。
废城乔木在，古道浊河侵。
莫虑西游远，西关绝陇阴。','',''),('quantangshi-30880','雪中送青州薛评事','馬戴','quantangshi','','卷31','腊景不可犯，从戎难自由。
怜君急王事，走马赴边州。
岳雪明日观，海云冒营丘。
慙无斗酒泻，敢望御重裘。','',''),('quantangshi-30881','哭京兆庞尹','馬戴','quantangshi','','卷31','神州丧贤尹，父老泣关中。
未尽羣生愿，才留及物功。
清光沈皎月，素业振遗风。
履迹莓苔掩，珂声紫陌空。
从来受知者，会葬汉陵东。','',''),('quantangshi-30882','路傍树','馬戴','quantangshi','','卷31','古树何人种，清阴减昔时。
莓苔根半露，风雨节偏危。
虫蠹心将穴，蝉催叶向衰。
樵童不须翦，聊起邵公思。','',''),('quantangshi-30883','送客南游','馬戴','quantangshi','','卷31','拟卜何山隐，高秋指岳阳。
苇干云梦色，橘熟洞庭香。
疎雨残虹影，[囘]云背鸟行。
灵均如可问，一为哭清湘。','',''),('quantangshi-30884','寄襄阳王公子','馬戴','quantangshi','','卷31','君马勒金羁，君家贮玉笄。
白云登岘首，碧树醉铜鞮。
泽广荆州北，山多汉水西。
鹿门知不隐，芳草自萋萋。','',''),('quantangshi-30885','集宿姚侍御宅怀永乐宰殷侍御','馬戴','quantangshi','','卷31','石田虞芮接，种树白云阴。
穴闭神踪古，河流禹凿深。
樵人应满郭，仙鸟几巢林。
此会偏相语，曾供雪夜吟。','',''),('quantangshi-30886','易水怀古','馬戴','quantangshi','','卷31','荆卿西去不复返，易水东流无尽期。
落日萧条蓟城北，黄沙白草任风吹。','',''),('quantangshi-30887','送僧二首 一','馬戴','quantangshi','','卷31','亲在平阳忆久归，洪河雨涨出关迟。
独过旧寺人稀识，一一杉松老别时。','',''),('quantangshi-30888','送僧二首 二','馬戴','quantangshi','','卷31','龛中破衲自持行，树下禅牀坐一生。
来往白云知岁久，满山猨鸟会经声。','',''),('quantangshi-30889','赠友人边游回','馬戴','quantangshi','','卷31','游子新从绝塞回，自言曾上李陵台。
尊前语尽北风起，秋色萧条胡雁来。','',''),('quantangshi-30890','山中作','馬戴','quantangshi','','卷31','屐齿无泥竹策轻，莓苔梯滑夜难行。
独开石室松门里，月照前山空水声。','',''),('quantangshi-30891','出塞词','馬戴','quantangshi','','卷31','金带连环束战袍，马头冲雪度临洮。
卷旗夜劫单于帐，乱斫胡儿缺宝刀。','',''),('quantangshi-30892','寄云台观田秀才','馬戴','quantangshi','','卷31','云压松枝拂石窗，幽人独坐鹤成双。
晚来漱齿敲冰渚，闲读仙书倚翠幢。','',''),('quantangshi-30893','边上送杨侍御鞫狱回','馬戴','quantangshi','','卷31','狱成冤雪晚云开，豸角威清塞雁回。
飞将送迎遥避马，离亭不敢劝金杯。','',''),('quantangshi-30894','射雕骑','馬戴','quantangshi','','卷31','蕃面将军着鼠裘，酣歌冲雪在边州。
猎过黑山犹走马，寒雕射落不回头。','',''),('quantangshi-30895','高司马移竹','馬戴','quantangshi','','卷31','丛居堂下幸君移，翠掩灯窗露叶垂。
莫羡孤生在山者，无人看着拂云枝。','',''),('quantangshi-30896','赠前蔚州崔使君','馬戴','quantangshi','','卷31','战回脱剑绾铜鱼，塞雁迎风避隼旟。
欲识前时为郡政，校成上下考新书。','',''),('quantangshi-30897','秋思二首 一','馬戴','quantangshi','','卷31','万木秋霖后，孤山夕照余。
田园无岁计，寒近忆樵渔。','',''),('quantangshi-30898','秋思二首 二','馬戴','quantangshi','','卷31','亭树霜霰满，野塘凫鸟多。
蕙兰不可折，楚老徒悲歌。','',''),('quantangshi-30899','黄神谷纪事','馬戴','quantangshi','','卷31','霹雳振秋岳，折松横洞门。
云龙忽变化，但觉玉潭昏。','',''),('quantangshi-30900','过亡友墓','馬戴','quantangshi','','卷31','忆昨送君葬，今看坟树高。
寻思后期者，只是益生劳。','',''),('quantangshi-30901','闻瀑布冰折','馬戴','quantangshi','','卷31','万仞冰峭折，寒声投白云。
光摇山月堕，我向石牀闻。','',''),('quantangshi-30902','赠道者','馬戴','quantangshi','','卷31','深居白云穴，静注赤松经。
往往龙潭上，焚香礼斗星。','',''),('quantangshi-30903','华下逢杨侍御','馬戴','quantangshi','','卷31','巨灵掌上月，玉女盆中泉。
柱史息车看，孤云心浩然。','',''),('quantangshi-30904','新春闻赦','馬戴','quantangshi','','卷31','道在猜谗息，仁深疾苦除。
尧聪能下听，汤网本来疎。','',''),('quantangshi-30905','送李侍御福建从事','馬戴','quantangshi','','卷31','晋安来越国，蔓草故宫迷。
钓渚龙应在，琴台鹤乱栖。
泛涛明月广，边海众山齐。
宾府通兰棹，蛮僧接石梯。
片云和瘴湿，孤屿映帆低。
上客多诗兴，秋猨足夜啼。','',''),('quantangshi-30906','酬刑部姚郎中','馬戴','quantangshi','','卷31','路岐人不见，尚得记心中。
月忆潇湘渚，春生兰杜丛。
鸟啼花半落，人散爵方空。
所赠诚难答，泠然一雅风。','',''),('quantangshi-30907','送柳秀才往连州看弟','馬戴','quantangshi','','卷31','离人非逆旅，有弟谪连州。
楚雨霑猨暮，湘云拂雁秋。
蒹葭行广泽，星月棹寒流。
何处江关鏁，风涛阻客愁。','',''),('quantangshi-30908','晚眺有怀','馬戴','quantangshi','','卷31','点点抱离念，旷怀成怨歌。
高台试延望，落照在寒波。
此地芳草歇，旧山乔木多。
悠然暮天际，但见鸟相过。','',''),('quantangshi-30909','山中兴作','馬戴','quantangshi','','卷31','高高丹桂枝，袅袅女萝衣。
密叶浮云过，幽阴暮鸟归。
月和风翠动，花落瀑泉飞。
欲翦兰为佩，中林露未曦。','',''),('quantangshi-30910','送皇甫协律淮南从事','馬戴','quantangshi','','卷31','辟书丞相草，招作广陵行。
隋柳疎淮岸，汀洲接海城。
楚樯经雨泊，烟月隔潮生。
谁与同尊俎，鸡鸾集虎营。','',''),('quantangshi-30911','别灵武令狐校书','馬戴','quantangshi','','卷31','北风吹别思，落月度关河。
树隐流沙短，山平近塞多。
雁池戎马饮，雕帐戍人过。
莫虑行军苦，华夷道正和。','',''),('quantangshi-30912','田氏南楼对月','馬戴','quantangshi','','卷31','主人同露坐，明月在高台。
咽咽阴虫叫，萧萧寒雁来。
影摇疎木落，魄转曙钟开。
幸免丹霞映，清光溢酒杯。','',''),('quantangshi-30913','送宗密上人','馬戴','quantangshi','','卷31','门前九陌尘，石上定中身。
近放辽天鹤，曾为南岳人。
腊高松叶换，雪尽茗芽新。
一自传香后，名山愿卜邻。','',''),('quantangshi-30914','白鹿原晚望','馬戴','quantangshi','','卷31','浐曲雁飞下，秦原人葬回。
丘坟与城阙，草树共尘埃。','',''),('quantangshi-30915','失意书怀呈知己','馬戴','quantangshi','','卷31','直道何由启圣君，非才谁敢议论文。
心存黄箓兼丹诀，家忆青山与白云。
麋鹿幽栖闲可近，鸳鸾高举势宜分。
微生不学刘琨辈，剑刃相交拟立勋。','',''),('quantangshi-30916','春日寻浐川王处士','馬戴','quantangshi','','卷31','碧草径微断，白云扉晚开。
罢琴松韵发，鉴水月光来。
宿鸟排花动，樵童浇竹回。
与君同露坐，涧石拂青苔。','',''),('quantangshi-30917','宿阳台观','馬戴','quantangshi','','卷31','玉洞仙何在，炉香客自焚。
醮坛围古木，石磬响寒云。
曙月孤霞映，悬流峭壁分。
心知人世隔，坐与鹤为羣。','',''),('quantangshi-30918','寄金州姚使君员外','馬戴','quantangshi','','卷31','老怀清净化，乞去守洵阳。
废井人应满，空林虎自藏。
迸泉疎石窦，残雨发椒香。
山缺通巴峡，江流带楚樯。
忧农生野思，祷庙结云装。
覆局松移影，听琴月堕光。
鸟鸣开郡印，僧去置禅牀。
罢贡金休凿，凌寒笋更长。
退公披鹤氅，高步隔鵷行。
相见朱门内，麾幢拂曙霜。','',''),('quantangshi-30919','中秋夜坐有怀','馬戴','quantangshi','','卷31','秋光动河汉，耿耿曙难分。
堕露垂丛药，残星间薄云。
心悬赤城峤，志向紫阳君。
雁过海风起，萧萧时独闻。','',''),('quantangshi-30920','题镜湖野老所居','馬戴','quantangshi','','卷31','湖里寻君去，樵风往返吹。
树喧巢鸟出，路细葑田移。
沤苎成鱼网，枯根是酒巵。
老年唯自适，生事任羣儿。','',''),('quantangshi-30921','题女道士居','馬戴','quantangshi','','卷31','不饵住云溪，休丹罢药畦。
杏花虚结子，石髓任成泥。
扫地青牛卧，栽松白鹤栖。
共知仙女丽，莫是阮郎妻。','',''),('quantangshi-30922','送王道士','馬戴','quantangshi','','卷31','真人俄整舃，双鹤屡飞翔。
恐入壶中住，须传肘后方。
霓裳云气润，石径术苗香。
一去何时见，仙家日月长。','',''),('quantangshi-30923','送道友入天台山作','馬戴','quantangshi','','卷31','却忆天台去，移居海岛空。
观寒琪树碧，雪浅石桥通。
漱齿飞泉外，餐霞早境中。
终期赤城里，披氅与君同。','',''),('quantangshi-30924','题章野人山居','馬戴','quantangshi','','卷31','带郭茅亭诗兴饶，回看一曲倚危桥。
门前山色能深浅，壁上湖光自动摇。
闲花散落填书帙，戏鸟低飞碍柳条。
向此隐来经几载，如今已是汉家朝。','',''),('quantangshi-30925','江中遇客','馬戴','quantangshi','','卷31','危石江中起，孤云岭上还。
相逢皆得意，何处是乡关。','',''),('quantangshi-30926','期王炼师不至','馬戴','quantangshi','','卷31','黄精蒸罢洗琼杯，林下从留石上苔。
昨日围棋未终局，多乘白鹤下山来。','',''),('quantangshi-30927','秋日送僧志幽归山寺','馬戴','quantangshi','','卷31','禅室绳牀在翠微，松间荷笠一僧归。
磬声寂历宜秋夜，手冷灯前自衲衣。','',''),('quantangshi-30928','句','馬戴','quantangshi','','卷31','申胥任向秦庭哭，靳尚终贻楚国忧。','',''),('quantangshi-30929','寄宜阳兄弟','易重','quantangshi','','卷31','六年雁序恨分离，诏下今朝遇已知。
上国皇风初喜日，御堦恩渥属身时。
内庭再考称文异，圣主宣名奖艺奇。
故里仙才若相问，一春攀得两重枝。','',''),('quantangshi-30930','发蕙风馆遇阴不见九华山有作','孟遲','quantangshi','','卷31','我来淮阴城，千江万山无不经。
山青水碧千万丈，奇峯急派何纵横。
又闻九华山，山顶连青冥。
太白有逸韵，使我西南行。
一步一攀策，前行正鸡鸣。
阴云冉冉忽飞起，千里万里危峥嵘。
譬如天之有日蚀，使我昏沈犹不明。
人家敲镜救不得，光阴却属贪狼星。
恨亦不能通，言亦不足听。
长鞭挥马出门去，是以九华为不平。','',''),('quantangshi-30931','寄浙右旧幕僚','孟遲','quantangshi','','卷31','由来恶舌驷难追，自古无媒谤所归。
勾践岂能容范蠡，李斯何暇救韩非。
巨拳岂为鸡挥肋，强弩那因鼠发机。
惭愧故人同鲍叔，此心江柳尚依依。','',''),('quantangshi-30932','壮士吟','孟遲','quantangshi','','卷31','壮士何曾悲，悲即无回期。
如何易水上，未歌泪先垂。','',''),('quantangshi-30933','徐波渡','孟遲','quantangshi','','卷31','晓月千重树，春烟十里溪。
过来还过去，此路不知迷。','',''),('quantangshi-30934','题嘉祥驿','孟遲','quantangshi','','卷31','树顶烟微绿，山根菊暗香。
何人独鞭马，落日上嘉祥。','',''),('quantangshi-30935','怀郑洎','孟遲','quantangshi','','卷31','风兰舞幽香，雨叶堕寒滴。
美人来不来，前山看向夕。','',''),('quantangshi-30936','长信宫','孟遲','quantangshi','','卷31','君恩已尽欲何归，犹有残香在舞衣。
自恨身轻不如燕，春来还遶御帘飞。','',''),('quantangshi-30937','闺情','孟遲','quantangshi','','卷31','山上有山归不得，湘江暮雨鹧鸪飞。
蘼芜亦是王孙草，莫送春香入客衣。','',''),('quantangshi-30938','莲塘','孟遲','quantangshi','','卷31','脉脉低回殷袖遮，脸横秋水髻盘鸦。
莲茎有刺不成折，尽日岸傍空看花。','',''),('quantangshi-30939','还淮却寄睢阳','孟遲','quantangshi','','卷31','梁王池苑已苍然，满树斜阳极浦烟。
尽日回头看不见，两行愁泪上南船。','',''),('quantangshi-30940','乌江','孟遲','quantangshi','','卷31','中分岂是无遗策，百战空劳不逝骓。
大叶固非人事及，乌江亭长又何知。','',''),('quantangshi-30941','新安故关','孟遲','quantangshi','','卷31','汉帝英雄重武材，崇山险处凿门开。
如今更有将军否，移取潼关向北来。','',''),('quantangshi-30942','广陵城','孟遲','quantangshi','','卷31','红遶高台绿遶城，城边春草傍墙生。
隋家不向此中尽，汴水应无东去声。','',''),('quantangshi-30943','过骊山','孟遲','quantangshi','','卷31','冷日微烟渭水愁，华清宫树不胜秋。
霓裳一曲千门锁，白尽梨园弟子头。','',''),('quantangshi-30944','吴故宫','孟遲','quantangshi','','卷31','越女歌长君且听，芙蓉香满水边城。
岂知一日终非主，犹自如今有怨声。','',''),('quantangshi-30945','兰昌宫','孟遲','quantangshi','','卷31','宫门两片掩埃尘，墙上无花草不春。
谁见当时禁中事，阿娇解佩与何人。','',''),('quantangshi-30946','宫人斜','孟遲','quantangshi','','卷31','云惨烟愁苑路斜，路傍丘冢尽宫娃。
茂陵不是同归处，空寄香魂着野花。','',''),('quantangshi-30947','句','孟遲','quantangshi','','卷31','天地有时饶一掷，江山无主任平分。','',''),('quantangshi-30948','和于兴宗登越王楼诗','王鐸','quantangshi','','卷31','谢眺题诗处，危楼压郡城。
雨余江水碧，云断雪山明。
锦绣来仙境，风光入帝京。
恨无青玉案，何以报高情。','',''),('quantangshi-30949','谒梓潼张恶子庙','王鐸','quantangshi','','卷31','盛唐圣主解青萍，欲振新封济顺名。
夜雨龙抛三尺匣，春云凤入九重城。
劒门喜气随雷动，玉垒韶光待贼平。
惟报关东诸将相，柱天功业赖阴兵。','',''),('quantangshi-30950','罢都统守镇滑州作','王鐸','quantangshi','','卷31','用军何事敢迁延，恩重才轻分使然。
黜诏已闻来阙下，檄书犹未遍军前。
腰间尽解苏秦印，波上虚迎范蠡船。
正会星辰扶北极，却驱戈甲镇南燕。
三尘上相逢明主，九合诸侯愧昔贤。
看却中兴扶大业，杀身无路好归田。','',''),('quantangshi-30951','句','王鐸','quantangshi','','卷31','华表尚迷丁令鹤，竹坡犹认葛溪龙。','',''),('quantangshi-30952','中秋月直禁苑','鄭畋','quantangshi','','卷31','禁署方怀忝，纶闱已再加。
暂来西掖路，还整上清槎。
恍惚归丹地，深严宿绛霞。
幽襟聊自适，闲弄紫薇花。','',''),('quantangshi-30953','麦穗两岐','鄭畋','quantangshi','','卷31','圣虑忧千亩，嘉苗荐两岐。
如云方表盛，成穗忽标奇。
瑞露纵横滴，祥风左右吹。
讴歌连上苑，化日遍平陂。
史册书堪重，丹青画更宜。
愿依连理树，俱作万年枝。','',''),('quantangshi-30954','五月一日紫宸候对时属禁直穿内而行因书六韵','鄭畋','quantangshi','','卷31','朱夏五更后，步廊三里余。
有人从翰苑，穿入内中书。
漏响飘银箭，灯光照玉除。
禁扉犹鏁钥，宫妓已妆梳。
紫府游应似，钧天梦不如。
尘埃九重外，谁信在清虚。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-30955','题缑山王子晋庙','鄭畋','quantangshi','','卷31','有昔灵王子，吹笙遡泬㵳。
六宫攀不住，三岛去相招。
亡国原陵古，宾天岁月遥。
无蹊窥海曲，有庙访山椒。
石帐龙蛇拱，云栊彩翠销。
露坛装琬琰，真像写松乔。
珠馆青童宴，琳宫阿母朝。
气舆仙女侍，天马吏兵调。
湘妓红丝瑟，秦郎白管箫。
西城要绰约，南岳命娇娆。
句曲觞金洞，天台啸石桥。
晚花珠弄蘂，春茹玉生苗。
二景神光秘，三元宝箓饶。
雾垂鸦翅发，冰束虎章腰。
鹤驭争衔箭，龙妃合献绡。
衣从星渚浣，丹就日宫烧。
物外花尝满，人间叶自凋。
望台悲汉戾，阅水笑梁昭。
古殿香残炧，荒堦柳长条。
几曾期七日，无复降重霄。
嵩岭连天汉，伊澜入海潮。
何由得真诀，使我佩环飘。','',''),('quantangshi-30956','初秋寓直三首 一','鄭畋','quantangshi','','卷31','晓星独挂结麟楼，三殿风高药树秋。
玉笛数声飘不住，问人依约在东头。','',''),('quantangshi-30957','初秋寓直三首 二','鄭畋','quantangshi','','卷31','宿鸟翩翩落照微，石台楼阁锁重扉。
步廊无限金羁响，应是诸司扈从归。','',''),('quantangshi-30958','初秋寓直三首 三','鄭畋','quantangshi','','卷31','幽阁焚香万虑凝，下帘胎息过禅僧。
玉堂分照无人后，消尽金盆一碗冰。','',''),('quantangshi-30959','夜景又作','鄭畋','quantangshi','','卷31','铃绦无响闭珠宫，小阁凉添玉蘂风。
枕簟满牀明月到，自疑身在五云中。','',''),('quantangshi-30960','杪秋夜直','鄭畋','quantangshi','','卷31','蘂宫裁诏与宵分，虽在青云忆白云。
待报君恩了归去，山翁何急草移文。','',''),('quantangshi-30961','禁直寄崔员外','鄭畋','quantangshi','','卷31','银台楼北蘂珠宫，敻与人间路不同。
在省五更春睡侣，早来分梦玉堂中。','',''),('quantangshi-30962','闻号','鄭畋','quantangshi','','卷31','陛兵偏近羽林营，夜静仍传禁号声。
应笑执金双阙下，近南犹隔两重城。','',''),('quantangshi-30963','禁直和人饮酒','鄭畋','quantangshi','','卷31','卉醴陀花物外香，清浓标格胜椒浆。
我来尚有钧天会，犹得金尊半日尝。','',''),('quantangshi-30964','下直早出','鄭畋','quantangshi','','卷31','诸司人尽马蹄稀，紫帕云竿九钉归。
偏觉石台清贵处，牓悬金字射晴晖。','',''),('quantangshi-30965','金銮坡上南望','鄭畋','quantangshi','','卷31','玉晨钟韵上清虚，画戟祥烟拱帝居。
极眼向南无限地，绿烟深处认中书。','',''),('quantangshi-30966','酬隐圭舍人寄红烛','鄭畋','quantangshi','','卷31','蜜炬殷红画不如，且将归去照吾庐。
今来并得三般事，灵运诗篇逸少书。','',''),('quantangshi-30967','马嵬坡','鄭畋','quantangshi','','卷31','[玄]宗回马杨妃死，云雨虽亡日月新。
终是圣明天子事，景阳宫井又何人。','',''),('quantangshi-30968','句','鄭畋','quantangshi','','卷31','圆明青[䭀]饭，光润碧霞浆。
浴殿晴秋倘中谢，残英犹可醉琼杯。','',''),('quantangshi-30969','题九华山','譚銖','quantangshi','','卷31','忆闻九华山，尚在童稚年。
浮沈任名路，窥仰会无缘。
罢职池阳时，复遭迎送牵。
因兹契诚愿，瞩望枕席前。
况值春正浓，气色无不全。
或如碧玉静，或似青霭鲜。
或接白云堆，或暎红霞天。
呈姿既不一，变态何啻千。
巍峩本无动，崇峻性岂偏。
外景自隐隐，潜虚固幽玄。
我来暗凝情，务道志更坚。
色与山异性，性并山亦然。
境变山不动，性存形自迁。
自迁不阻俗，自定不失贤。
浮华与朱紫，安可迷心田。','',''),('quantangshi-30970','真娘墓','譚銖','quantangshi','','卷31','武丘山下冢累累，松柏萧条尽可悲。
何事世人偏重色，真娘墓上独题诗。','',''),('quantangshi-30971','望九华山','盧嗣立','quantangshi','','卷31','九华深翠落轩楹，迥眺澄江气象明。
不遇阴霾孤岫隐，正当寒日众峯呈。
坐观风雪销烦思，惜别烟岚驻晓行。
得路归山期早诀，夜来潜已告精诚。','',''),('quantangshi-30972','应举日寄兄弟','朱可名','quantangshi','','卷31','废刈镜湖田，上书紫阁前。
愁人久委地，诗道未闻天。
不是烧金手，徒抛钓月船。
多惭兄弟意，不敢问林泉。','',''),('quantangshi-30973','河出荣光','張良器','quantangshi','','卷31','引派昆山峻，朝宗海路长。
千龄逢圣主，五色瑞荣光。
隐暎浮中国，晶明助太阳。
坤维连浩漫，天汉接微茫。
丹阙清氛里，函关紫气旁。
位尊常守伯，道泰每呈祥。
习坎灵逾久，居卑德有常。
龙门如可涉，忠信是舟梁。','',''),('quantangshi-30974','新雪八韵','薛能','quantangshi','','卷31','大雪满初晨，开门万象新。
龙钟鸡未起，萧索我何贫。
耀若花前境，清如物外身。
细飞斑户牖，干洒乱松筠。
正色凝高岭，随流助要津。
鼎消微是滓，车碾半和尘。
茶兴留诗客，瓜情想戍人。
终篇本无字，谁别胜阳春。','',''),('quantangshi-30975','国学试风化下','薛能','quantangshi','','卷31','霁阙露穹崇，含生仰圣聪。
英明高比日，声敎下如风。
静发宸居内，低来品物中。
南薰歌自溥，北极响皆通。
苹末看无状，人间觉有功。
因今委泥者，覩此忘途穷。','',''),('quantangshi-30976','升平词十首 一','薛能','quantangshi','','卷31','瑞气遶宫楼，皇居信上游。
远冈连圣祚，平地载神州。
会合皆重译，潺湲近八流。
中兴岂假问，据此自千秋。','',''),('quantangshi-30977','升平词十首 二','薛能','quantangshi','','卷31','寥泬敞延英，朝班立位横。
宣传无草动，拜舞有衣声。
鸳瓦霜消湿，虫丝日照明。
辛勤自不到，遥见似前程。','',''),('quantangshi-30978','升平词十首 三','薛能','quantangshi','','卷31','处处是欢心，时康岁已深。
不同三尺劒，应似五弦琴。
寿笑山犹尽，明嫌日有阴。
何当怜一物，亦遣断愁吟。','',''),('quantangshi-30979','升平词十首 四','薛能','quantangshi','','卷31','曙质绝埃氛，彤庭列禁军。
圣颜初对日，龙尾竞缘云。
佩响交成韵，帘阴暖带纹。
逍遥岂有事，于此咏南薰。','',''),('quantangshi-30980','升平词十首 五','薛能','quantangshi','','卷31','一物至周天，洪纤尽晏然。
车书无异俗，甲子并丰年。
奇技皆归朴，征夫亦服田。
君王故不有，台鼎合韦弦。','',''),('quantangshi-30981','升平词十首 六','薛能','quantangshi','','卷31','日日听歌谣，区中尽祝尧。
虫蝗初不害，夷狄近全销。
史笔惟书瑞，天台绝见妖。
因令匹夫志，转欲事清朝。','',''),('quantangshi-30982','升平词十首 七','薛能','quantangshi','','卷31','品物尽昭苏，神功复帝谟。
他时应有寿，当代且无虞。
赐历通遐俗，移关入半胡。
鹪鹩一何幸，于此寄微躯。','',''),('quantangshi-30983','升平词十首 八','薛能','quantangshi','','卷31','无战复无私，尧时即此时。
焚香临极早，待月卷帘迟。
端拱干坤内，何言黈纩垂。
君看圣明验，只此是神龟。','',''),('quantangshi-30984','升平词十首 九','薛能','quantangshi','','卷31','旭日上清穹，明堂坐圣聪。
衣裳承瑞气，冠冕盖重瞳。
花木经宵露，旌旗入仗风。
何期于此地，见说是神工。','',''),('quantangshi-30985','升平词十首 十','薛能','quantangshi','','卷31','五帝三皇主，萧曹魏邴臣。
文章惟返朴，戈甲尽生尘。
谏纸应无用，朝纲自有伦。
升平不可记，所见是闲人。','',''),('quantangshi-30986','送冯温往河外','薛能','quantangshi','','卷31','琴劒事行装，河关出北方。
秦音尽河内，魏画自黎阳。
野日村苗熟，秋霜馆叶黄。
风沙问船处，应得立清漳。','',''),('quantangshi-30987','送从兄之太原副使','薛能','quantangshi','','卷31','少载琴书去，须知暂佐军。
初程见西岳，尽室渡横汾。
元日何州在，枯风宿馆闻。
都门送行处，青紫骑纷纷。','',''),('quantangshi-30988','送马戴书记之太原','薛能','quantangshi','','卷31','一曲大河声，全家几日行。
从容长约夜，差互忽离城。
镇北胡沙浅，途中霍岳横。
相逢莫已讯，诗雅负雄名。','',''),('quantangshi-30989','送友人出塞','薛能','quantangshi','','卷31','榆关到不可，何况出榆关。
春草临岐断，边楼带日闲。
人归穹帐外，鸟乱废营间。
此地堪愁想，霜前作意还。','',''),('quantangshi-30990','送李溟出塞','薛能','quantangshi','','卷31','边城官尚恶，况乃是羁游。
别路应相忆，离亭更少留。
黄沙人外阔，飞雪马前稠。
甚险穹庐宿，无为过代州。','',''),('quantangshi-30991','寄终南隐者','薛能','quantangshi','','卷31','海日东南出，应开岭上扉。
扫坛花入彗，科竹露霑衣。
饭后嫌身重，茶中见鸟归。
相思爱民者，难说与亲违。','',''),('quantangshi-30992','赠隐者','薛能','quantangshi','','卷31','自得高闲性，平生向北栖。
月潭云影断，山叶雨声齐。
庭树人书匝，栏花鸟坐低。
相留永不忘，经宿话丹梯。','',''),('quantangshi-30993','惜春','薛能','quantangshi','','卷31','花开亦花落，时节暗中迁。
无计延春日，可能留少年。
小丛初散蝶，高柳即闻蝉。
繁艳归何处，满山啼杜鹃。','',''),('quantangshi-30994','送人自苏州之长沙县官','薛能','quantangshi','','卷31','驱马复乘流，何时发虎丘？
全家上南岳，一尉事诸侯。
茶煮朝宗水，船停调角州。
炎方好将息，卑湿旧堪忧。','',''),('quantangshi-30995','早春归山中旧居','薛能','quantangshi','','卷31','茫茫驱匹马，归处是荒榛。
猨迹破庭雪，鼠踪生甑尘。
开门冲网断，扫叶放苔匀。
为惜诗情错，应难致此身。','',''),('quantangshi-30996','麟中寓居寄蒲中友人','薛能','quantangshi','','卷31','萧条秋雨地，独院阻同羣。
一夜惊为客，多年不见君。
边心生落日，乡思羡归云。
更在相思处，子规灯下闻。','',''),('quantangshi-30997','关中送别','薛能','quantangshi','','卷31','一行千里外，几事寸心间。
才子贫堪叹，男儿别是闲。
黄河淹华岳，白日照潼关。
若值乡人问，终军贱不还。','',''),('quantangshi-30998','中秋夜寄李溟','薛能','quantangshi','','卷31','满魄断埃氛，牵吟并舍闻。
一年唯此夜，到晚愿无云。
待赏从初出，看行过二分。
严城亦已闭，悔不预期君。','',''),('quantangshi-30999','赠禅师','薛能','quantangshi','','卷31','梦想青山寺，前年住此中。
夜堂吹竹雨，春地落花风。
旧句师曾见，清斋我亦同。
浮生蹇莫问，辛苦未成功。','',''),('quantangshi-31000','送禅僧','薛能','quantangshi','','卷31','寒空孤鸟度，落日一僧归。
近寺路闻梵，出郊风满衣。
步摇瓶浪起，盂戛磬声微。
还坐栖禅所，荒山月照扉。','',''),('quantangshi-31001','赠隐者','薛能','quantangshi','','卷31','门前虽有径，绝向世间行。
剃草因逢药，移花便得莺。
甘贫原是道，苦学不为名。
莫怪苍髭晚，无机任世情。','',''),('quantangshi-31002','冬日送僧归吴中旧居','薛能','quantangshi','','卷31','去扫冬林下，闲持未徧经。
为山低凿牖，容月广开庭。
旧叶云千里，生涯水一瓶。
还应觅新句，看雪倚禅扃。','',''),('quantangshi-31003','恭禧皇太后挽歌词三首 一','薛能','quantangshi','','卷31','八月曾殊选，三星固异仪。
祔陵经灞浐，归赗杂华夷。
旌去题新諡，宫存鏁素帏。
重泉应不恨，生见太平时。','',''),('quantangshi-31004','恭禧皇太后挽歌词三首 二','薛能','quantangshi','','卷31','月落娥兼隐，宫空后岂还。
衔哀穷地界，亲莅泣天颜。
旧住留丹药，新陵在碧山。
国人伤莫及，应只咏关关。','',''),('quantangshi-31005','恭禧皇太后挽歌词三首 三','薛能','quantangshi','','卷31','配圣三朝隔，灵仪万姓哀。
多年好黄老，旧日荐贤才。
道着标彤管，宫闲闭绿苔。
平生六衣在，曾着祀高禖。','',''),('quantangshi-31006','送胡澳下第归蒲津','薛能','quantangshi','','卷31','无媒甘下飞，君子尚麻衣。
岁月终荣在，家园近且归。
山光临舜庙，河气隔王畿。
甚积汤原思，青青宿麦肥。','',''),('quantangshi-31007','春日闲居','薛能','quantangshi','','卷31','权门多见薄，吾道岂终行。
散地徒忧国，良时不在城。
花繁春正王，茶美梦初惊。
赖有兹文在，犹堪畅此生。','',''),('quantangshi-31008','题逃户','薛能','quantangshi','','卷31','几世瞢农桑，凶年竟失乡。
朽关生湿菌，倾屋照斜阳。
雨水淹残臼，葵花压倒墙。
明时岂致此，应自负苍苍。','',''),('quantangshi-31009','郊居答客','薛能','quantangshi','','卷31','傍舍虫声满，残秋宿雨村。
远劳才子骑，光顾野人门。
败叶盘空蔓，雕丛露暗根。
相携未尽语，川月照黄昏。','',''),('quantangshi-31010','早春归山中旧居','薛能','quantangshi','','卷31','绿草闭闲院，悄然花正开。
新年人未去，戊日燕还来。
雨地残枯沫，灯窗积旧煤。
归田语不忘，樗散料非才。','',''),('quantangshi-31011','下第后春日长安寓居三首 一','薛能','quantangshi','','卷31','一榜尽精选，此身犹陆沈。
自无功谠分，敢抱怨尤心。
暖陌开花气，春居闭日阴。
相知岂不有，知浅未知深。','',''),('quantangshi-31012','下第后春日长安寓居三首 二','薛能','quantangshi','','卷31','暂屈固何恨，所忧无此时。
隔年空仰望，临日又参差。
劳力且成病，壮心能不衰。
犹将琢磨意，更欲候宗师。','',''),('quantangshi-31013','下第后春日长安寓居三首 三','薛能','quantangshi','','卷31','关东归不得，岂是爱他乡。
草碧余花落，春闲白日长。
全家期圣泽，半路敢农桑。
独立应无侣，浮生欲自伤。','',''),('quantangshi-31014','春早选寓长安二首 一','薛能','quantangshi','','卷31','疎拙自沈昏，长安岂是村。
春非闲客事，花在五侯门。
道僻惟忧祸，诗深不敢论。
扬雄若有荐，君圣合承恩。','',''),('quantangshi-31015','春早选寓长安二首 二','薛能','quantangshi','','卷31','旧论已浮海，此心犹滞秦。
上僚如报国，公道岂无人。
岩隐悬溪瀑，城居入榻尘。
渔舟即拟去，不待晚年身。','',''),('quantangshi-31016','送进士许棠下第东归','薛能','quantangshi','','卷32','长安那不住，西笑又东行。
若以贫无计，何因事有成。
云峰天外出，江色草中明。
谩忝相于分，吾言世甚轻。','',''),('quantangshi-31017','咏岛','薛能','quantangshi','','卷32','孤岛如江上，诗家犹闭门。
一池分倒影，空舸系荒根。
烟湿高吟石，云生偶坐痕。
登临有新句，公退与谁论。','',''),('quantangshi-31018','冬日写怀','薛能','quantangshi','','卷32','幕府尽平蛮，客留戎阃间。
急流霜夹水，轻霭日连山。
设醴徒慙楚，为郎未姓颜。
斯文苦不胜，会拟老民间。','',''),('quantangshi-31019','和杨中丞早春即事','薛能','quantangshi','','卷32','贵宅登临地，春来见物华。
远江桥外色，繁杏竹边花。
戍客烽楼迥，文君酒幔斜。
新题好不极，珠府未穷奢。','',''),('quantangshi-31020','闻官军破吉浪戎小而固虑史氏遗忽因记为二章 一','薛能','quantangshi','','卷32','一战便抽兵，蛮孤吉浪平。
通连无旧穴，要害有新城。
昼卒烽前寝，春农界上耕。
高楼一拟望，新雨劒南清。','',''),('quantangshi-31021','闻官军破吉浪戎小而固虑史氏遗忽因记为二章 二','薛能','quantangshi','','卷32','泸水断嚣氛，妖巢已自焚。
汉江无敌国，蛮物在回军。
越雟通游国，苴哶闭聚蚊。
空余罗凤曲，哀思满边云。','',''),('quantangshi-31022','寒食有怀','薛能','quantangshi','','卷32','流落伤寒食，登临望岁华。
村球高过索，坟树绿和花。
晋聚应搜火，秦喧定走车。
谁知恨榆柳，风景似吾家。','',''),('quantangshi-31023','绵楼','薛能','quantangshi','','卷32','溪边人浣纱，楼下海棠花。
极望虽怀土，多情拟置家。
前山应象外，此地已天涯。
未有销忧赋，梁王礼欲奢。','',''),('quantangshi-31024','雕堂','薛能','quantangshi','','卷32','丈室久多病，小园晴独游。
鸣蛩孤烛雨，啅雀一篱秋。
圣主恩难谢，生灵志亦忧。
他年谁识我，心迹在徐州。','',''),('quantangshi-31025','赠歌人','薛能','quantangshi','','卷32','温燠坐相侵，罗襦一水沈。
拜深知有意，令背不无心。
近住应名玉，前生约姓阴。
东山期已定，相许便抽簪。','',''),('quantangshi-31026','柘枝词三首 一','薛能','quantangshi','','卷32','同营三十万，震鼓伐西羌。
战血黏秋草，征尘搅夕阳。
归来人不识，帝里独戎装。','',''),('quantangshi-31027','柘枝词三首 二','薛能','quantangshi','','卷32','悬军征拓羯，内地隔萧关。
日色昆仑上，风声朔漠间。
何当千万骑，飒飒贰师还。','',''),('quantangshi-31028','柘枝词三首 三','薛能','quantangshi','','卷32','意气成功日，春风起絮天。
楼台新邸第，歌舞小婵娟。
急破[催]摇曳，罗衫半脱肩。','',''),('quantangshi-31029','咏柳花','薛能','quantangshi','','卷32','浮生失意频，起絮又飘沦。
发自谁家树，飞来独院春。
朝容萦断砌，晴影过诸邻。
乱掩宫中蝶，繁冲陌上人。
随波应到海，霑雨或依尘。
会向慈恩日，轻轻对此身。','',''),('quantangshi-31030','一叶落','薛能','quantangshi','','卷32','轻叶独悠悠，天高片影流。
随风来此地，何树落先秋。
变色黄应近，辞林绿尚稠。
无双浮水面，孤绝落关头。
乍减诚难觉，将凋势未休。
客心空自比，谁肯问新愁。','',''),('quantangshi-31031','行路难','薛能','quantangshi','','卷32','何处力堪殚，人心险万端。
藏山难测度，暗水自波澜。
对面如千里，回肠似七盘。
已经吴坂困，欲向雁门难。
南北诚须泣，高深不可干。
无因善行止，车辙得平安。','',''),('quantangshi-31032','蔡州蒋亭','薛能','quantangshi','','卷32','草径彻林间，过桥如入山。
蔡侯添水榭，蒋氏本柴关。
静泛穷幽趣，惊飞湿醉颜。
恨无优俸买，来得暂时闲。
步与招提接，舟临夕照还。
春风应不到，前想负花湾。','',''),('quantangshi-31033','戏题','薛能','quantangshi','','卷32','闪闪动鸣璫，初来烛影傍。
拥头珠翠重，萦步绮罗长。
静发歌如磬，连飘气觉香。
不言微有笑，多媚总无妆。
坐缺初离席，帘垂却入房。
思惟不是梦，此会胜高唐。','',''),('quantangshi-31034','酬曹侍御见寄','薛能','quantangshi','','卷32','儒道苦不胜，迩来惟慕禅。
触途非巧者，于世分沈然。
要地羞难入，闲居钝更便。
清和挑菜食，闷寂闭花眠。
累遣期抛俸，机忘怕与权。
妨春愁筦榷，响夜忆林泉。
匪石从遭刖，殊膏枉被煎。
讨论唯子厚，藏退合吾先。
旧制羣英伏，来章六义全。
休旬一拟和，乡思乱情田。','',''),('quantangshi-31035','送赵道士归天目旧山','薛能','quantangshi','','卷32','愚朴尚公平，此心邻道情。
有缘终自鄙，何计逐师行。
日者闻高躅，时人盖强名。
口无滋味入，身有羽仪生。
奏乞还乡远，诗曾对御成。
土毛珍到越，尘发倦离京。
符叱风雷恶，朝修月露清。
观临天目顶，家住海潮声。
道引图看足，参同注解精。
休粮一拟问，窗草俟回程。','',''),('quantangshi-31036','除夜作','薛能','quantangshi','','卷32','和吹度穹旻，虚徐接建寅。
不辞加一岁，唯喜到三春。
燎照云烟好，幡悬井邑新。
祯祥应北极，调燮验平津。
树欲含迟日，山将退旧尘。
兰萎残此夜，竹爆和诸邻。
祝寿思明圣，驱傩看鬼神。
团圆多少辈，眠寝独劳筋。
茜斾犹双节，雕盘又五辛。
何当平贼后，归作自由身。','',''),('quantangshi-31037','桃花','薛能','quantangshi','','卷32','香色自天种，千年岂易逢。
开齐全未落，繁极欲相重。
泠湿朝如淡，晴干午更浓。
风光新社燕，时节旧春农。
篱落欹临竹，亭台盛间松。
乱缘堪羡蚁，深入不如蜂。
有影宜暄煦，无言自冶容。
洞连非俗世，溪静接仙踪。
子熟河应变，根盘土已封。
西王潜爱惜，东朔盗过从。
醉席眠英好，题诗恋景慵。
芳菲聊一望，何必在临邛。','',''),('quantangshi-31038','黄河','薛能','quantangshi','','卷32','何处发昆仑，连干复浸坤。
波浑经雁塞，声振自龙门。
岸裂新冲势，滩余旧落痕。
横沟通海上，远色尽山根。
勇逗三峰坼，雄标四渎尊。
湾中秋景树，阔外夕阳村。
沫乱知鱼呴，槎来见鸟蹲。
飞沙当白日，凝雾接黄昏。
润可资农亩，清能表帝恩。
雨吟堪极目，风度想惊魂。
显瑞龟曾出，阴灵伯固存。
盘涡寒渐急，浅濑暑微温。
九曲终柔胜，常流可暗吞。
人间无博望，谁复到穷源。','',''),('quantangshi-31039','华岳','薛能','quantangshi','','卷32','簇簇复亭亭，三峰卓杳冥。
每思穷本末，应合记图经。
发地连宫观，冲天接井星。
河微临巨势，秦重载奇形。
太古朝羣后，中央擘巨灵。
邻州犹映槛，几县恰当庭。
鹤毳坛风乱，龙漦洞水腥。
望遥通北极，上彻见东溟。
客翫晴难偶，农祈雨必零。
度关无暑气，过路得愁醒。
羽客时应见，霜猨夜可听。
顶悬飞瀑峻，崦合白云青。
混石猜良玉，寻苗得茯苓。
从官知侧近，悉俸致岩扃。','',''),('quantangshi-31040','秋雨','薛能','quantangshi','','卷32','宿雨觉才初，亭林忽复徐。
簇声诸树密，悬滴四檐疎。
省漏疑方丈，愁炊问斗储。
步难多入屐，窗浅欲飘书。
动蠖苍苔静，藏蚕落叶虚。
吹交来翕习，雷慢歇踌躇。
滞已妨行路，晴应好荷锄。
醉楼思蜀客，鯹市想淮鱼。
径草因缘合，栏花自此除。
有形皆霢霂，无地不污潴。
境晦宜甘寝，风清□退居。
我魂惊晓簟，邻话喜秋蔬。
既用功成岁，旋应惨变舒。
仓箱足可恃，归去傲吾庐。','',''),('quantangshi-31041','春色满皇州','薛能','quantangshi','','卷32','蔼蔼复悠悠，春归十二楼。
最明云里阙，先满日边州。
色媚青门外，光摇紫陌头。
上林荣旧树，太液镜新流。
暖带祥烟起，清添瑞景浮。
阳和如启蛰，从此事芳游。','',''),('quantangshi-31042','寄唁张乔喻坦之','薛能','quantangshi','','卷32','何事尽参差，惜哉吾子诗。
日令销此道，天亦负明时。
有路当重振，无门即不知。
何当见尧日，相与啜浇漓。','',''),('quantangshi-31043','赠僧','薛能','quantangshi','','卷32','尽日行方到，何年独此林。
客归惟鹤伴，人少似师心。
坐石落松子，禅牀摇竹阴。
山灵怕惊定，不遣夜猨吟。','',''),('quantangshi-31044','春日旅舍书怀','薛能','quantangshi','','卷32','出去归来旅食人，麻衣长带几坊尘。
开门草色朝无客，落案灯花夜一身。
贫舍卧多消永日，故园莺老忆残春。
蹉跎冠盖谁相念，二十年中尽苦辛。','',''),('quantangshi-31045','秋日将离滑台酬所知二首 一','薛能','quantangshi','','卷32','身起中宵骨亦惊，一分年少已无成。
松吹竹簟朝眠冷，雨湿蔬飡宿疾生。
僮汲野泉兼土味，马磨霜树作秋声。
相知莫话诗心苦，未似前贤取得名。','',''),('quantangshi-31046','秋日将离滑台酬所知二首 二','薛能','quantangshi','','卷32','灯涩秋光静不眠，叶声身影客窗前。
闲园露湿鸣蛩夜，急雨风吹落木天。
城见远山应北岳，野多空地本南燕。
明朝欲别忘形处，愁把离杯听管弦。','',''),('quantangshi-31047','下第后夷门乘舟至永城驿题','薛能','quantangshi','','卷32','秋赋春还计尽违，自知身是拙求知。
唯思旷海为休处，忽喜孤舟似去时。
连浦一城兼汴宋，夹堤千柳杂唐隋。
从来此恨皆前达，敢负吾君作楚辞。','',''),('quantangshi-31048','秋夜旅舍寓怀','薛能','quantangshi','','卷32','庭锁荒芜独夜吟，西风吹动故山心。
三秋木落半年客，满地月明何处砧？
渔唱乱沿汀鹭合，雁声寒咽陇云深。
平生只有松堪对，露浥霜欺不受侵。','',''),('quantangshi-31049','洛下寓怀','薛能','quantangshi','','卷32','胡为遭遇孰为官，朝野君亲各自欢。
敢向官途争虎首，尚嫌身累爱猪肝。
冰霜谷口晨樵远，星火炉边夜坐寒。
唯有报恩心未剖，退居犹欲佩芄兰。','',''),('quantangshi-31050','题平湖','薛能','quantangshi','','卷32','平湖湖畔雨晴新，南北东西不隔尘。
映野烟波浮动日，损花风雨寂寥春。
山无俗路藏高士，岸泊仙舟忆主人。
那得载来都未保，此心离此甚情亲。','',''),('quantangshi-31051','平阳寓怀','薛能','quantangshi','','卷32','晋国风流阻洳川，家家弦管路岐边。
曾为郡职随分竹，亦作歌词乞采莲。
北榭远峰闲即望，西湖残景醉常眠。
墙花此日休回避，不是当时恶少年。','',''),('quantangshi-31052','留题汾上旧居','薛能','quantangshi','','卷32','乡园一别五年归，回首人间总祸机。
尚胜邻翁常寂寞，敢嫌裘马未轻肥。
尘颜不见应消落，庭树曾栽已合围。
难说累牵还却去，可怜榆柳尚依依。','',''),('quantangshi-31053','怀汾上旧居','薛能','quantangshi','','卷32','素汾千载傍吾家，常忆衡门对浣纱。
好事喜逢投宿客，刈田因得自生瓜。
山头鼓笛阴沈庙，陌上薪蒸突兀车。
投暗作珠何所用，被人专拟害灵蛇。','',''),('quantangshi-31054','送同儒大德归柏梯寺','薛能','quantangshi','','卷32','柏梯还拟谢微官，遥拟千峰送法兰。
行径未曾青石断，拂牀终有白云残。
京尘濯后三衣洁，山舍禅初万象安。
薇蕨纵多师莫踏，我心犹欲尽图看。','',''),('quantangshi-31055','春日使府寓怀二首 一','薛能','quantangshi','','卷32','一想流年百事惊，已抛渔父戴尘缨。
青春背我堂堂去，白发欺人故故生。
道困古来应有分，诗传身后亦何荣。
谁怜合负清朝力，独把风骚破郑声。','',''),('quantangshi-31056','春日使府寓怀二首 二','薛能','quantangshi','','卷32','平生无解亦无操，永日书生坐独劳。
唯觉宦情如水薄，不知人事有山高。
孤心好直迍犹强，病发慵梳痒更搔。
何事故溪归未得，几抛清浅泛红桃。','',''),('quantangshi-31057','许州题德星亭','薛能','quantangshi','','卷32','瀵水南流东有堤，堤边亭是武陵溪。
槎松配石堪僧坐，蘂杏含春欲鸟啼。
高树月生沧海外，远郊山在夕阳西。
频来不似军从事，只戴纱巾曳杖藜。','',''),('quantangshi-31058','送人归上党','薛能','quantangshi','','卷32','燕台基壤穴狐蛇，计拙因循岁月赊。
兵革未销王在镐，桑蚕临熟客还家。
霏微对岸漳边雨，堆阜邻疆蓟北沙。
若到长平战场地，为求遗镞辟魔邪。','',''),('quantangshi-31059','春日重游平湖','薛能','quantangshi','','卷32','湖上春风发管弦，须临三十此离筵。
离人忽有重来日，游女初非旧少年。
官职已辜疲瘵望，诗名空被后生传。
啼莺莫惜蹉跎恨，闲事听吟一两篇。','',''),('quantangshi-31060','并州','薛能','quantangshi','','卷32','少年流落在并州，裘脱文君取次游。
携挈共过芳草渡，登临齐凭绿杨楼。
庭前蛱蝶春方好，牀上樗蒲宿未收。
坊号偃松人在否，饼炉南畔曲西头。','',''),('quantangshi-31061','相国陇西公南征能以留务独宿府城作','薛能','quantangshi','','卷32','吾君贤相事南征，独宿军厨负请缨。
灯室卧孤如怨别，月阶簪草似临行。
高墉撼铎思巴栈，老木嘷风念野营。
殊忆好僧招不及，夜来仓卒鏁严城。','',''),('quantangshi-31062','早春书事','薛能','quantangshi','','卷32','百蛮降伏委三秦，锦里风回岁已新。
渠滥水泉花巷湿，日销冰雪柳营春。
何年道胜苏羣物，尽室天涯是旅人。
焚却蜀书宜不读，武侯无可律余身。','',''),('quantangshi-31063','春日书怀','薛能','quantangshi','','卷32','伯牙琴绝岂求知，往往情牵自有诗。
壠月正当寒食夜，春阴初过海棠时。
耽书未必酬良相，断酒唯堪作老师。
多病不任衣更薄，东风台上莫相吹。','',''),('quantangshi-31064','投杜舍人','薛能','quantangshi','','卷32','牀上新诗诏草和，栏边清酒落花多。
闲消白日舍人宿，梦觉紫薇山鸟过。
春刻几分添禁漏，夏桐初叶满庭柯。
风骚委地苦无主，此事圣君终若何。','',''),('quantangshi-31065','献仆射相公','薛能','quantangshi','','卷32','清如冰雪重如山，百辟严趋礼绝攀。
强虏外闻应丧胆，平人相见尽开颜。
朝廷有道青春好，门馆无私白日闲。
致却垂衣更何事，几多诗句咏关关。','',''),('quantangshi-31066','上盐铁尚书','薛能','quantangshi','','卷32','南宫环雉隔嚣尘，况值清斋宿大臣。
城绝鼓钟更点后，雨凉烟树月华新。
檐前漱晓穹苍碧，庭下眠秋沆瀣津。
闻说务闲心更静，此时忧国合求人。','',''),('quantangshi-31067','汉南春望','薛能','quantangshi','','卷32','独寻春色上高台，三月皇州驾未回。
几处松筠烧后死，谁家桃李乱中开。
奸邪用法原非法，唱和求才不是才。
自古浮云蔽白日，洗天风雨几时来。','',''),('quantangshi-31068','晚春','薛能','quantangshi','','卷32','恶怜风景极交亲，每恨年年作瘦人。
卧晚不曾抛好夜，情多唯欲哭残春。
阴成杏叶才通日，雨着杨花已污尘。
无限后期知有在，只愁烦作总戎身。','',''),('quantangshi-31069','将赴镇过太康县有题','薛能','quantangshi','','卷32','才入东郊便太康，自听何暮岂龚黄。
晴村透日桑榆影，晓露湿秋禾黍香。
十万旌旗移巨镇，几多輗軏负孤庄。
时人欲识征东将，看取欃枪落太荒。','',''),('quantangshi-31070','彭门解嘲二首 一','薛能','quantangshi','','卷32','呜呜吹角贰师营，落日身闲笑傲行。
尽觉文章尊万事，却嫌官职剩双旌。
终休未拟降低屈，忽遇还须致太平。
频上水楼谁会我，泗滨浮磬是同声。','',''),('quantangshi-31071','彭门解嘲二首 二','薛能','quantangshi','','卷32','伤禽栖后意犹惊，偶向黐竿脱此生。
身外不思簪组事，耳中唯要管弦声。
耽吟乍可妨时务，浅饮无因致宿酲。
秦客莫嘲瓜戍远，水风潇洒是彭城。','',''),('quantangshi-31072','清河泛舟','薛能','quantangshi','','卷32','都人层立似山丘，坐啸将军拥棹游。
遶郭烟波浮泗水，一船丝竹载凉州。
城中覩望皆丹雘，旗里惊飞尽白鸥。
儒将不须夸郄縠，未闻诗句解风流。','',''),('quantangshi-31073','新竹','薛能','quantangshi','','卷32','柳营茅土倦麤材，因向山家乞翠栽。
清露便敎终夜滴，好风疑是故园来。
栏边匠去朱犹湿，溉后虫浮穴暗开。
他日会应威凤至，莫辞公府受尘埃。','',''),('quantangshi-31074','晚春','薛能','quantangshi','','卷32','征东留滞一年年，又向军前遇火前。
画出鷁舟宜祓禊，镂成鸡卵有秋千。
澄明烟水孤城立，狼藉风花落日眠。
赖指清和樱笋熟，不然愁杀暮春天。','',''),('quantangshi-31075','题彭祖楼','薛能','quantangshi','','卷32','新晴天状湿融融，徐国滩声上下洪。
极目澄鲜无限景，入怀轻好可怜风。
身防潦倒师彭祖，妓拥登临愧谢公。
谁致此楼潜惠我，万家残照在河东。','',''),('quantangshi-31076','汉庙祈雨回阳春亭有怀','薛能','quantangshi','','卷32','南荣轩槛接城闉，适罢祈农此访春。
九九已从南至尽，芊芊初傍北篱新。
池中水是前秋雨，陌上风惊自古尘。
欲召罗敷倾一盏，乘闲言语不容人。','',''),('quantangshi-31077','送李倍秀才','薛能','quantangshi','','卷32','南朝才子尚途穷，毕竟应须问叶公。
书劒伴身离泗上，雪风吹面立船中。
家园枣熟归圭窦，会府槐疎试射弓。
相顾日偏留不得，夜深聊欲一杯同。','',''),('quantangshi-31078','重游德星亭感事','薛能','quantangshi','','卷32','颖水川中枕水台，当时难别此重来。
舟沈土岸生新草，诗映纱笼有薄埃。
事系兴亡人少到，地当今古我迟回。
残阳照树明于旭，犹向池边把酒杯。','',''),('quantangshi-31079','许州题观察判官厅','薛能','quantangshi','','卷32','三载从戎类系匏，重游全许尚分茅。
刘郎别后无遗履，丁令归来有旧巢。
冬暖井梧多未落，夜寒窗竹自相敲。
纤腰弟子知千恨，笑与扬雄作解嘲。','',''),('quantangshi-31080','闲题','薛能','quantangshi','','卷32','八年藩翰似侨居，只此谁知报玉除。
旧将已成三仆射，老身犹是六尚书。
时丁厚讟终无咎，道致中兴尚有余。
为问春风谁是主，空催弱柳拟何如。','',''),('quantangshi-31081','送福建李大夫','薛能','quantangshi','','卷32','洛州良牧帅瓯闽，曾是西垣作谏臣。
红斾已胜前尹正，尺书犹带旧丝纶。
秋来海有幽都雁，船到城添外国人。
行过小藩应大笑，只知夸近不知贫。','',''),('quantangshi-31082','送李倍巡官归永乐旧居','薛能','quantangshi','','卷32','羡君归去五峰前，往往星河实见仙。
麦壠夏枯成废地，枣枝秋赤近高天。
山泉饮犊流多变，村酒经蚕味可怜。
曾约道门终老住，步虚声里寄闲眠。','',''),('quantangshi-31083','赠歌者','薛能','quantangshi','','卷32','一字新声一颗珠，转喉疑是击珊瑚。
听时坐部音中有，唱后樱花叶里无。
汉浦蔑闻虚解佩，临邛焉用枉当垆。
谁人得向青楼宿，便是仙郎不是夫。','',''),('quantangshi-31084','舞者','薛能','quantangshi','','卷32','绿毛钗动小相思，一唱南轩日午时。
慢靸轻裾行欲近，待调诸曲起来迟。
筵停匕筯无非听，吻带宫商尽是词。
为问倾城年几许，更胜琼树是琼枝。','',''),('quantangshi-31085','天际识归舟','薛能','quantangshi','','卷32','斜日满江楼，天涯照背流。
同人在何处，远目认孤舟。
帆省当时席，歌声旧日讴。
人浮津济晚，棹倚泬寥秋。
晴阔忻全见，归迟怪久游。
离居意无限，贪此望难休。','',''),('quantangshi-31086','和曹侍御除夜有怀','薛能','quantangshi','','卷32','有病无媒客，多慵亦太疎。
自怜成叔夜，谁与荐相如。
嗜退思年老，谙空笑岁除。
迹闲过寺宿，头暖近阶梳。
春立穷冬后，阳生旧物初。
叶多庭不扫，根在迳新锄。
田事终归彼，心情倦老于。
斵材须见像，藏劒岂为鱼。
效浅慙尹禄，恩多负辟书。
醻知必拟共，勿使浪踌躇。','',''),('quantangshi-31087','华清宫和杜舍人','薛能','quantangshi','','卷32','五十年天子，离宫仰峻墙。
登封时正泰，御宇日何长。
上位先名实，中兴事宪章。
起戎轻甲胄，余地复河湟。
道降玄元祖，儒封孔子王。
因缘百司署，聚会一人汤。
渭水波摇绿，秦山草半黄。
马驯金勒细，鹰健玉铃锵。
下箭朱方满，鸣鞭皓腕攘。
畋思获吕望，谏祗避周昌。
兔迹贪前逐，枭心不早防。
几添鹦鹉劝，先赐荔枝尝。
月锁千门静，天吹一笛凉。
细音摇羽佩，轻步宛霓裳。
祸乱基潜结，升平意遽忘。
衣冠逃犬虏，鼙鼓动渔阳。
外戚心殊迫，中原事可量。
血埋妃子艳，刃断禄儿肠。
近侍烟尘隔，前踪辇路荒。
益知迷宠佞，遗恨丧贤良。
北阙尊明主，南宫逊上皇。
禁清余凤吹，池冷睡龙光。
祝寿山犹在，流年水共伤。
杜鹃魂厌蜀，蝴蝶梦悲壮。
雀卵遗雕栱，虫丝罥画梁。
紫苔侵壁润，红树闭门芳。
守吏齐鸳瓦，耕民得翠璫。
登年昔酺乐，讲武旧兵场。
暮草深岩翠，幽花坠迳香。
不堪垂白叟，行折御沟杨。','',''),('quantangshi-31088','送浙东王大夫','薛能','quantangshi','','卷32','天爵擅忠贞，皇恩复宠荣。
远源过晋史，甲族本缑笙。
亚相兼尤美，周行历尽清。
制除天近晓，衙谢草初生。
宾客招闲地，戎装拥上京。
九街鸣玉勒，一宅照红旌。
细雨当离席，遥花显去程。
佩刀畿甸色，歌吹馆桥声。
騕褭从秦赐，艅艎到汴迎。
步沙逢霁月，宿岸致严更。
渤澥流东鄙，天台压属城。
众谈称重镇，公意念疲甿。
井邑曾多难，疮痍此未平。
察应均赋歛，逃必复桑耕。
隼重权兼帅，鼍雄设有兵。
越台随厚俸，剡硾得尤名。
夜蜡州中宴，春风部外行。
香匳扃凤诏，朱篆动龙坑。
报后功何患，投虚论素精。
征还真指掌，感激自关情。
旧业怀昏作，微班负旦评。
空余骚雅事，千古傲刘桢。','',''),('quantangshi-31089','送李殷游京西','薛能','quantangshi','','卷32','立马送君地，黯然愁到身。
万途皆有匠，六义独无人。
莫怪敢言此，已能甘世贫。
时来贵亦在，事是掩何因。
投刺皆羁旅，游边更苦辛。
岐山终蜀境，泾水复蛮尘。
埋没飡须强，炎蒸醉莫频。
俗徒欺合得，吾道死终新。
展分先难许，论诗永共亲。
归京稍作意，充斥犯西邻。','',''),('quantangshi-31090','长安送友人之黔南','薛能','quantangshi','','卷32','衡岳犹云过，君家独几千。
心从贱游话，分向禁城偏。
陆路终何处，三湘在素船。
琴书去迢递，星路照潺湲。
台镜簪秋晚，盘蔬饭雨天。
同文到乡尽，殊国共行连。
后会应多日，归程自一年。
贫交永无忘，孤进合相怜。','',''),('quantangshi-31091','寄李频','薛能','quantangshi','','卷32','长安千万蹊，迷者自多迷。
直性身难达，良时日易低。
环檐消旧雪，晴气满春泥。
那得同君去，逢峰苦爱齐。','',''),('quantangshi-31092','赠苗端公二首 一','薛能','quantangshi','','卷32','繁总近何如，君才必有余。
身欢步兵酒，吏写鲁连书。
坐默闻鼙吹，庭班见雪初。
沈碑若果去，一为访邻居。','',''),('quantangshi-31093','赠苗端公二首 二','薛能','quantangshi','','卷32','至老不相疎，斯言不是虚。
两心宜一体，同舍又邻居。
晓角秋砧外，清云白月初。
从军何有用，未造鲁连书。','',''),('quantangshi-31094','寄河南郑侍郎','薛能','quantangshi','','卷32','三峡与三壕，门阑梦去劳。
细冰和洛水，初雪洒嵩高。
大雅何由接，微荣亦已逃。
寒窗不可寐，风地叶萧骚。','',''),('quantangshi-31095','蒙恩除侍御史行次华州寄蒋相','薛能','quantangshi','','卷32','林下天书起遁逃，不堪移疾入尘劳。
黄河近岸阴风急，仙掌临关旭日高。
行野众喧闻雁发，宿亭孤寂有狼嗥。
荀家位极兼禅理，应笑埋轮着所操。','',''),('quantangshi-31096','寄唐州杨郎中','薛能','quantangshi','','卷32','关雎憔悴一儒生，忽把鱼须事圣明。
贫得俸钱还乍喜，晚登朝序却无荣。
前年坐蜀同樽俎，此日边淮独斾旌。
班列道孤君不见，曲江春暖共僧行。','',''),('quantangshi-31097','塞上蒙汝州任中丞寄书','薛能','quantangshi','','卷32','三省推贤两掖才，关东深许稍迟回。
舟浮汝水通淮去，雨出嵩峰到郡来。
投札转京忧不远，枉缄经虏喜初开。
西楼一望知无极，更与何人把酒杯。','',''),('quantangshi-31098','题盐铁李尚书浐州别业','薛能','quantangshi','','卷32','鹿原阴面浐州湄，坐觉林泉逼梦思。
闲景院开花落后，湿香风好雨来时。
邻惊麦野闻雏雉，别创茅亭住老师。
备足好中还有阙，许昌军里李陵诗。','',''),('quantangshi-31099','送刘驾归京','薛能','quantangshi','','卷32','相逢听一吟，惟我不降心。
在世忧何事，前生得至音。
蒲多南去远，汾尽北游深。
为宿关亭日，苍苍晓欲临。','',''),('quantangshi-31100','夏日寺中有怀','薛能','quantangshi','','卷32','亭午四邻睡，院中唯鸟鸣。
当门塞鸿去，欹枕世人情。
地燥苍苔裂，天凉晚月生。
归家岂不愿，辛苦未知名。','',''),('quantangshi-31101','夏日蒲津寺居二首 一','薛能','quantangshi','','卷32','日日闲车马，谁来访此身。
一门兼鹤静，四院与僧邻。
雨室墙穿溜，风窗笔染尘。
空余气长在，天子用平人。','',''),('quantangshi-31102','夏日蒲津寺居二首 二','薛能','quantangshi','','卷32','故国有如梦，省来长远游。
清晨起闲院，疎雨似深秋。
宿寝书棱叠，行吟杖迹稠。
天晴岂能出，春暖未更裘。','',''),('quantangshi-31103','北都题崇福寺','薛能','quantangshi','','卷32','此地潜龙寺，何基即帝台。
细花庭树荫，清气殿门开。
长老多相识，旬休暂一来。
空空亦拟解，干进幸无媒。','',''),('quantangshi-31104','题龙兴寺','薛能','quantangshi','','卷32','高户列禅房，松门到上方。
像开只树岭，人施蜀城香。
地遍磷磷石，江移孑孑樯。
林僧语不尽，身役事梁王。','',''),('quantangshi-31105','题大云寺西阁','薛能','quantangshi','','卷32','阁临偏险寺当山，独坐西城笑满颜。
四野有歌行路乐，五营无战射堂闲。
鼙和调角秋空外，砧办征衣落照间。
方拟杀身酬圣主，敢于高处恋乡关。','',''),('quantangshi-31106','舟行至平羌','薛能','quantangshi','','卷32','貔虎直沙壖，严更护早眠。
簇霜孤驿树，落日下江船。
暂去非吴起，终休爱鲁连。
平羌无一术，候吏莫加笾。','',''),('quantangshi-31107','题开元寺阁','薛能','quantangshi','','卷32','一阁见一郡，乱流仍乱山。
未能终日住，尤爱暂时闲。
唱棹吴门去，啼林杜宇还。
高僧不可羡，西景掩禅关。','',''),('quantangshi-31108','凌云寺','薛能','quantangshi','','卷32','像阁与山齐，何人致石梯。
万烟生聚落，一崦露招提。
斋月人来上，残阳鸽去栖。
从边亦已极，烽火是沈黎。','',''),('quantangshi-31109','石堂溪','薛能','quantangshi','','卷32','三面接渔樵，前门向郡桥。
岸沙崩橘树，山径入茶苗。
夜拥军烟合，春浮妓舸邀。
此心无与醉，花影莫相烧。','',''),('quantangshi-31110','荔枝楼','薛能','quantangshi','','卷32','高槛起边愁，荔枝谁致楼。
会须敎匠坼，不欲见蛮陬。
树痹无春影，天连觉汉流。
仲宣如可拟，即此是荆州。','',''),('quantangshi-31111','圣冈','薛能','quantangshi','','卷32','古迹是何王，平身入石房。
远村通后径，一郡隔前冈。
昼静唯禅客，春来有女郎。
独醒回不得，无事可焚香。','',''),('quantangshi-31112','蜀州郑史君寄鸟觜茶因以赠答八韵','薛能','quantangshi','','卷32','鸟觜撷浑牙，精灵胜镆铘。
烹尝方带酒，滋味更无茶。
拒碾干声细，撑封利颖斜。
衔芦齐劲实，啄木聚菁华。
盐损添常诫，姜宜着更夸。
得来抛道药，携去就僧家。
旋觉前瓯浅，还愁后信赊。
千慙故人意，此惠敌丹砂。','',''),('quantangshi-31113','暇日寓怀寄朝中亲友','薛能','quantangshi','','卷32','命与才违岂自由，我身何负我身愁。
临生白发方监郡，遥耻青衣懒上楼。
过客闷嫌疎妓乐，小儿憨爱□貔貅。
闲吟一寄清朝侣，未必淮阴不拜侯。','',''),('quantangshi-31114','春日寓怀','薛能','quantangshi','','卷32','幽拙未谋身，无端患不均。
盗憎犹念物，花尽不知春。
井邑常多弊，江山岂有神。
犍为何处在，一拟吊埋轮。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-31115','监郡犍为舟中寓题寄同舍','薛能','quantangshi','','卷32','一寝闲身万事空，任天敎作假文翁。
旗穿岛树孤舟上，家在山亭每日中。
叠果盘飱丹橘地，若花牀席早梅风。
佳期说尽君应笑，刘表尊前且不同。','',''),('quantangshi-31116','江柳','薛能','quantangshi','','卷32','条绿似垂缨，离筵日照轻。
向人虽有态，伤我为无情。
桥远孤临水，墙低半出营。
天津曾此见，亦是怆行行。','',''),('quantangshi-31117','寄吉谏议','薛能','quantangshi','','卷32','将迎须学返抽身，合致蹉跎敢效颦。
性静拟归无上士，迹疎常负有情人。
终凭二顷谋婚嫁，谬着千篇断斧斤。
闻说旧交贤且达，欲弹章甫自羞贫。','',''),('quantangshi-31118','江上寄情','薛能','quantangshi','','卷32','天际归舟浩荡中，我关王泽道何穷。
未为时彦徒经国，尚有边兵耻佐戎。
酿黍气香村欲社，斫桑春尽野无风。
年来断定知休处，一树繁花一亩宫。','',''),('quantangshi-31119','平盖观','薛能','quantangshi','','卷32','巨柏与山高，玄门静有猱。
春风开野杏，落日照江涛。
白璧心难说，青云世未遭。
天涯望不极，谁识咏离骚。','',''),('quantangshi-31120','春霁','薛能','quantangshi','','卷32','久客孤舟上，天涯漱晓津。
野芳桤似柳，江霁雪和春。
吏叫能惊鹭，官麤实害身。
何当穷蜀境，却忆滞游人。','',''),('quantangshi-31121','春居即事','薛能','quantangshi','','卷32','云密露晨晖，西园独掩扉。
雨新临断火，春冷着单衣。
榆荚奔风健，兰芽负土肥。
交亲不是变，自作寄书稀。','',''),('quantangshi-31122','边城寓题','薛能','quantangshi','','卷32','孤蹇复飘零，天涯若堕萤。
东风吹痼疾，暖日极青冥。
蚕市归农醉，渔舟钓客醒。
论邦苦不早，祗此负王庭。','',''),('quantangshi-31123','春日江居寓怀','薛能','quantangshi','','卷32','归兴乍离边，兰桡复锦川。
斫春槎枿树，消雪土膏田。
岸暖寻新菜，舟寒着旧绵。
临邛若个是，欲向酒家眠。','',''),('quantangshi-31124','边城作','薛能','quantangshi','','卷32','行止象分符，监州是戏儒。
管排蛮户远，出箐鸟巢孤。
北向秦何在，南来蜀已无。
怀沙悔不及，只有便乘桴。','',''),('quantangshi-31125','闻李夷遇下第东归因以寄赠','薛能','quantangshi','','卷32','囊中书是居山写，海畔家贫乞食还。
吾子莫愁登第晚，古人惟爱贱游闲。
舟行散适江亭上，郡宴歌吟蜡烛间。
从此乐章休叙战，汉兵无阵亦无蛮。','',''),('quantangshi-31126','留题','薛能','quantangshi','','卷32','茶兴复诗心，一瓯还一吟。
压春甘蔗冷，喧雨荔枝深。
骤去无遗恨，幽栖已徧寻。
峨眉不可到，高处望千岑。','',''),('quantangshi-31127','春日北归舟中有怀','薛能','quantangshi','','卷32','尽日遶盘飧，归舟向蜀门。
雨干杨柳渡，山热杏花村。
净镜空山晓，孤灯极浦昏。
边城不是意，回首未终恩。','',''),('quantangshi-31128','初发嘉州寓题','薛能','quantangshi','','卷32','劳我是犍为，南征又北移。
唯闻杜鹃夜，不见海棠时。
在暗曾无负，含灵合有知。
州人若爱树，莫损召南诗。','',''),('quantangshi-31129','题汉州西湖','薛能','quantangshi','','卷32','西湖天下名，可以濯吾缨。
况是携家赏，从妨半驿程。
尝茶春味渴，断酒晚怀清。
尽得幽人趣，犹嫌守吏迎。
重湌逢角暮，百事喜诗成。
坐阻湘江谪，谁为话政声。','',''),('quantangshi-31130','自广汉游三学山','薛能','quantangshi','','卷32','残阳终日望栖贤，归路携家得访禅。
世缺一来应薄命，雨留三宿是前缘。
诗题不忍离岩下，屐齿难忘在水边。
猨鸟可知僧可会，此心常似有香烟。','',''),('quantangshi-31131','三学山开照寺','薛能','quantangshi','','卷32','尽室徧相将，中方上下方。
夜深楠树远，春气陌林香。
圣迹留岩险，灵灯出混茫。
何因将慧劒，割爱事空王。','',''),('quantangshi-31132','雨霁北归留题三学山','薛能','quantangshi','','卷32','远树平川半夕阳，锦城遥辨立危墙。
闲思胜事多遗恨，却悔公心是谩忙。
灌口阙寻慙远客，峨嵋乖约负支郎。
灵龛一望终何得，谬有人情满蜀乡。','',''),('quantangshi-31133','行次灵龛驿寄西蜀尚书','薛能','quantangshi','','卷32','北客推车指蜀门，干阳知已近临坤。
从辞府郭常回首，欲别封疆更感恩。
援寡圣朝难望阙，暑催蚕麦得归村。
雷公解斸冲天气，白日何辜遣戴盆。','',''),('quantangshi-31134','雨霁宿望喜驿','薛能','quantangshi','','卷32','风雷一罢思何清，江水依然浩浩声。
飞鸟旋生啼鸟在，后人常似古人情。
将来道路终须达，过去山川实不平。
闲想更逢知旧否，馆前杨柳种初成。','',''),('quantangshi-31135','筹笔驿','薛能','quantangshi','','卷32','葛相终宜马革还，未开天意便开山。
生欺仲达徒增气，死见王阳合厚颜。
流运有功终是扰，阴符多术得非奸。','',''),('quantangshi-31136','通仙洞','薛能','quantangshi','','卷32','高龛险欲催，百尺洞门开。
白日仙何在，清风客暂来。
临崖松直上，避石水低回。
贾掾曾空去，题诗岂易哉。','',''),('quantangshi-31137','嘉陵驿见贾岛旧题','薛能','quantangshi','','卷32','贾子命堪悲，唐人独解诗。
左迁今已矣，清绝更无之。
毕竟吾犹许，商量众莫疑。
嘉陵四十字，一一是天资。','',''),('quantangshi-31138','嘉陵驿','薛能','quantangshi','','卷32','江涛千叠阁千层，衔尾相随尽室登。
稠树蔽山闻杜宇，午烟薰日食嘉陵。
频题石上程多破，暂歇泉边起不能。
如此幸非名利切，益州来日合携僧。','',''),('quantangshi-31139','嘉陵驿','薛能','quantangshi','','卷32','尽室可招魂，蛮余出蜀门。
雹凉随雨气，江热傍山根。
蚕月缲丝路，农时碌碡村。
干将磨欲尽，无位可酬恩。','',''),('quantangshi-31140','西县途中二十韵','薛能','quantangshi','','卷32','野客误桑麻，从军带镆铘。
岂论之白帝，未合过黄花。
落日投江县，征尘漱齿牙。
蜀音连井络，秦分隔褒斜。
硖路商逢使，山邮雀啅蛇。
忆归临角黍，良遇得新瓜。
食久庭阴转，行多屐齿洼。
气清岩下瀑，烟漫雨余畲。
黄鸟当蚕候，稀蒿杂麦查。
汗凉风似雪，浆度蜜如沙。
野色生肥芋，乡仪捣散茶。
梯航经杜宇，烽候彻苴咩。
逗石流何险，通关运固赊。
葛侯真竭泽，刘主合亡家。
陷彼贪功吠，贻为黩武夸。
阵图谁许可，庙貌我揄揶。
闲事休征汉，斯行且咏巴。
音繁来有铎，軏尽去无车。
溢目看风景，清怀啸月华。
焰樵烹紫笋，腰簟憩乌纱。
杞国忧寻悟，临邛渴自加。
移文莫有诮，必不滞天涯。','',''),('quantangshi-31141','西县作','薛能','quantangshi','','卷32','三年西蜀去如沈，西县西来出万岑。
树石向闻清汉浪，水风初见绿萍阴。
平郊不爱行增气，好井无疑漱入心。
从此渐知光景异，锦都廻首尽愁吟。','',''),('quantangshi-31142','分水岭望灵宝峰','薛能','quantangshi','','卷32','千寻万仞峰，灵宝号何从。
盛立同吾道，贪程阻圣踪。
岭奇应有药，壁峭尽无松。
那得休于是，蹉跎亦卧龙。','',''),('quantangshi-31143','水帘吟','薛能','quantangshi','','卷32','万滴相随万响兼，路尘天产尽旁霑。
源从颢气何因绝，派助前溪岂觉添。
豪客每来清夏葛，愁人才见认愁檐。
嘉名已极终难称，别是风流不是帘。','',''),('quantangshi-31144','褒斜道中','薛能','quantangshi','','卷32','十驿褒斜到处慵，眼前常似接灵踪。
江遥旋入旁来水，山豁犹藏向后峰。
鸟径恶时应立虎，畲田闲日自烧松。
行吟却笑公车役，夜发星驰半不逢。','',''),('quantangshi-31145','褒城驿有故元相公旧题诗因仰叹而作','薛能','quantangshi','','卷32','鄂相顷题应好池，题云万竹与千棃。
我来已变当初地，前过应无继此诗。
敢叹临行殊旧境，惟愁后事劣今时。
闲吟四壁堪搔首，频见青苹白鹭鸶。','',''),('quantangshi-31146','题褒城驿池','薛能','quantangshi','','卷32','池馆通秦槛向衢，旧闻佳赏此踟蹰。
清凉不散亭犹在，事力何销舫已无。
钓客坐风临岛屿，牧牛当雨食菰蒲。
西川吟吏偏思葺，只恐归寻水亦枯。','',''),('quantangshi-31147','送崔学士赴东川','薛能','quantangshi','','卷32','羽人仙籍冠浮丘，欲作酇侯且蜀侯。
导骑已多行劒阁，亲军全到近绵州。
文翁劝学人应恋，魏绛和戎戍自休。
唯有夜罇懽莫厌，庙堂他日少闲游。','',''),('quantangshi-31148','海棠','薛能','quantangshi','','卷32','酷烈复离披，玄功莫我知。
青苔浮落处，暮柳间开时。
带醉游人插，连阴被叟移。
晨前清露湿，晏后恶风吹。
香少传何许，妍多画半遗。
岛苏涟水脉，庭绽粒松枝。
偶泛因沈砚，闲飘欲乱碁。
遶山生玉垒，和郡徧坤维。
负赏慙休饮，牵吟分失饥。
明年应不见，留此赠巴儿。','',''),('quantangshi-31149','咏夹迳菊','薛能','quantangshi','','卷32','夹迳尽黄英，不通人竝行。
几曾相对绽，元自两行生。
丛比高低等，香连左右并。
畔摇风势断，中夹日华明。
间隔蛩吟隔，交横蝶乱横。
频应泛桑落，摘处近前楹。','',''),('quantangshi-31150','碧鲜亭春题竹','薛能','quantangshi','','卷32','竹少竹更重，碧鲜疆更名。
有栏常凭立，无径独穿行。
夕月阴何乱，春风叶尽轻。
已闻图画客，兼写薛先生。','',''),('quantangshi-31151','竹迳','薛能','quantangshi','','卷32','盘迳入依依，旋惊幽鸟飞。
寻多苔色古，踏碎箨声微。
鞭节横妨户，枝梢动拂衣。
前溪闻到处，应接钓鱼矶。','',''),('quantangshi-31152','新柳','薛能','quantangshi','','卷32','轻轻须重不须轻，众木难成独早成。
柔性定胜刚性立，一枝还引万枝生。
天钟和气元无力，时遇风光别有情。
谁道少逢知己用，将军因此建雄名。','',''),('quantangshi-31153','牡丹四首 一','薛能','quantangshi','','卷32','异色禀陶甄，常疑主者偏。
众芳殊不类，一笑独奢妍。
颗折羞含嬾，藂虚隐陷圆。
亚心堆胜被，美色艳于莲。
品格如寒食，精光似少年。
种堪收子子，价合易贤贤。
迥秀应无妬，奇香称有仙。
深阴宜映幕，富贵助开筵。
蜀水争能染，巫山未可怜。
数难忘次第，立困恋傍边。
逐日愁风雨，和星祝夜天。
且从留尽赏，离此便归田。','',''),('quantangshi-31154','牡丹四首 二','薛能','quantangshi','','卷32','万朵照初筵，狂游忆少年。
晓光如曲水，颜色似西川。
白向庚辛受，朱从造化研。
众开成伴侣，相笑极神仙。
见焰宁劳火，闻香不带烟。
自高轻月桂，非偶贱池莲。
影接雕盘动，藂遭恶草偏。
招欢忧事阻，就卧觉情牵。
四面宜绨锦，当头称管弦。
泊来莺定忆，粉扰蝶何颠。
苏息承朝露，滋荣仰霁天。
压栏多尽好，敌国贵宜然。
未落须迷醉，因兹任病缠。
人谁知极物，空负感麟篇。','',''),('quantangshi-31155','牡丹四首 三','薛能','quantangshi','','卷32','去年零落暮春时，泪湿红牋怨别离。
常恐便随巫峡散，何因重有武陵期。
传情每向馨香得，不语还应彼此知。
欲就栏边安枕席，夜深闲共说相思。','',''),('quantangshi-31156','牡丹四首 四','薛能','quantangshi','','卷32','牡丹愁为牡丹饥，自惜多情欲瘦羸。
浓艳冷香初盖后，好风干雨正开时。
吟蜂遍坐无闲蘂，醉客曾偷有折枝。
京国别来谁占翫，此花光景属吾诗。','',''),('quantangshi-31157','使院栽苇','薛能','quantangshi','','卷32','戛戛复差差，一丛千万枝。
格如僧住处，栽得吏闲时。
笋自厅中出，根从府外移。
从军无宿例，空想夜风吹。','',''),('quantangshi-31158','失鹤二首 一','薛能','quantangshi','','卷32','偶背雕笼与我违，四方端伫竟忘归。
谁家白日云间见，何处沧洲雨里飞。
曾啄稻粱残粒在，旧翘泥潦半踪稀。
凭人转觉多相误，尽道皤然作令威。','',''),('quantangshi-31159','失鹤二首 二','薛能','quantangshi','','卷32','华表翘风未可期，变丁投卫两堪疑。
应缘失路防人损，空有归心最我知。
但见空笼抛夕月，若何无树宿荒陂。
不然直道高空外，白水青山属腊师。','',''),('quantangshi-31160','答贾支使寄鹤','薛能','quantangshi','','卷32','瑞羽奇姿踉跄形，称为仙驭过清冥。
何年厚禄曾居卫，几世前身本姓丁。
幸有远云兼远水，莫临华表望华亭。
劳君赠我清歌侣，将去田园夜坐听。','',''),('quantangshi-31161','陈州刺史寄鹤','薛能','quantangshi','','卷32','临风高视耸奇形，渡海冲天想尽经。
因得羽仪来合浦，便无魂梦去华亭。
春飞见境乘桴切，夜唳闻时醉枕醒。
南守欲知多少重，抚毛千万唤丁丁。','',''),('quantangshi-31162','孔雀','薛能','quantangshi','','卷32','偶有功名正俗才，灵禽何事降瑶台。
天仙黼黻毛应是，宫后屏帏尾忽开。
曾处嶂中真雾隐，每过庭下似春来。
佳人为我和衫拍，遣作傞傞送一杯。','',''),('quantangshi-31163','鄜州进白野鹊','薛能','quantangshi','','卷32','轻毛叠雪翅开霜，红觜能深练尾长。
名应玉符朝北阙，色柔金性瑞西方。
不忧云路填河远，为对天颜送喜忙。
从此定知栖息处，月宫琼树是仙乡。','',''),('quantangshi-31164','早蝉','薛能','quantangshi','','卷32','不见上庭树，日高声忽吟。
他人岂无耳，远客自关心。
暂落还因雨，横飞亦向林。
分明去年意，从此渐闻砧。','',''),('quantangshi-31165','申湖','薛能','quantangshi','','卷32','昔年依峡寺，每日见申湖。
下泪重来此，知心一已无。
雨霖舟色暗，岸拔木形枯。
旧境深相恼，新春宛不殊。
方来寻熟侣，起去恨惊凫。
忍事花何笑，喧吟瀑正麤。
堪忧从宦到，倍遣曩怀孤。
上马终回首，傍人怪感吁。','',''),('quantangshi-31166','谢刘相寄天柱茶','薛能','quantangshi','','卷32','两串春团敌夜光，名题天柱印维扬。
偷嫌曼倩桃无味，捣觉嫦娥药不香。
惜恐被分缘利市，尽应难觅为供堂。
麤官寄与真抛却，赖有诗情合得尝。','',''),('quantangshi-31167','题后集','薛能','quantangshi','','卷32','诗源何代失澄清，处处狂波污后生。
常感道孤吟有泪，却缘风坏语无情。
难甘恶少欺韩信，枉被诸侯杀禰衡。
纵到缑山也无益，四方联络尽蛙声。','',''),('quantangshi-31168','秋晚送无可上人','薛能','quantangshi','','卷32','半夜觉松雨，照书灯悄然。
河声才淅沥，旧业近潺湲。
坐滴寒更尽，吟惊宿鹤迁。
相思不相见，日短复愁牵。','',''),('quantangshi-31169','赠源寂禅师','薛能','quantangshi','','卷32','瓶钵镇随腰，怡然处寂寥。
门禅从北祖，僧格似南朝。
性近徒相许，缘多愧未销。
何传能法慧，此岸要津桥。','',''),('quantangshi-31170','赠禅师','薛能','quantangshi','','卷32','嗜欲本无性，此生长在禅。
九州空有路，一室独多年。
鸣磬微尘落，移瓶湿地圆。
相寻偶同宿，星月坐忘眠。','',''),('quantangshi-31171','夏日青龙寺寻僧二首 一','薛能','quantangshi','','卷32','帝里欲何待，人间无阙遗。
不能安旧隐，都属扰明时。
违理须齐辱，雄图岂藉知。
纵横悉已悞，斯语是吾师。','',''),('quantangshi-31172','夏日青龙寺寻僧二首 二','薛能','quantangshi','','卷32','得官殊未喜，失计是忘愁。
不是无心速，焉能有自由。
凉风盈夏扇，蜀茗半形瓯。
笑向权门客，应难见道流。','',''),('quantangshi-31173','寄题巨源禅师','薛能','quantangshi','','卷32','风雨禅思外，应残木槿花。
何年别乡土，一衲代袈裟。
日气侵瓶暖，雷声动枕斜。
还当扫楼影，天晚自煎茶。','',''),('quantangshi-31174','题河中亭子','薛能','quantangshi','','卷32','河擘双流岛在中，岛中亭上正南空。
蒲根旧浸临关道，沙色遥飞傍苑风。
晴见树卑知岳大，晚闻车乱觉桥通。
无穷胜事应须宿，霜白蒹葭月在东。','',''),('quantangshi-31175','逢友人边游回','薛能','quantangshi','','卷32','游子新从绝塞回，自言曾上李陵台。
尊前语尽北风起，秋色萧条胡雁来。','',''),('quantangshi-31176','春雨','薛能','quantangshi','','卷32','电阔照潺潺，惊流往复还。
远声如有洞，迷色似无山。
利物干坤内，并风竹树间。
静思来朔漠，愁望满柴关。
迸湿消尘虑，吹风触疾颜。
谁知草茅迳，霑此尚虚闲。','',''),('quantangshi-31177','夏雨','薛能','quantangshi','','卷32','何处发天涯，风雷一道赊。
去声随地急，残势傍楼斜。
透树垂红叶，霑尘带落花。
潇湘无限思，闲看下蒹葭。','',''),('quantangshi-31178','秋夜山中述事','薛能','quantangshi','','卷32','初宵门未掩，独坐对霜空。
极目故乡月，满溪寒草风。
樵声当岭上，僧语在云中。
正恨归期晚，萧萧闻塞鸿。','',''),('quantangshi-31179','长安道','薛能','quantangshi','','卷32','汲汲复营营，东西连两京。
关繻古若在，山岳累应成。
各自有身事，不相知姓名。
交驰兼众类，分散入重城。
此去应无尽，万方人旋生。
空余片言苦，来往觅刘桢。','',''),('quantangshi-31180','酬泗州韦中丞埇上日寄赠兼次本韵','薛能','quantangshi','','卷32','鲁儒相悟欲成空，学尽文章不见功。
官自掖垣飘海上，镇从随岸入山中。
尝遭火发瞿云宅，争得天如老氏弓。
何意杜陵怀宝客，也随迷路出关东。','',''),('quantangshi-31181','泛觞池','薛能','quantangshi','','卷32','通咽远华罇，泛觞名自君。
净看筹见影，轻动酒生纹。
细滴随杯落，来声就浦分。
便应半酣后，清冷漱兼云。','',''),('quantangshi-31182','荔枝','薛能','quantangshi','','卷32','颗如松子色如樱，未识蹉跎欲半生。
岁杪监州曾见树，时新入座久闻名。','',''),('quantangshi-31183','丁巳上元日放三雉','薛能','quantangshi','','卷32','婴网虽皆困，褰笼喜共归。
无心期尔报，相见莫惊飞。','',''),('quantangshi-31184','寓题','薛能','quantangshi','','卷32','王泽犹来雅在新，尚词微事可愁人。
淫哇满眼关雎弱，犹贺清朝有此身。','',''),('quantangshi-31185','望蜀亭','薛能','quantangshi','','卷32','树簇烟迷蜀国深，岭头分界恋登临。
前轩一望无他处，从此西川只在心。','',''),('quantangshi-31186','游嘉州后溪','薛能','quantangshi','','卷32','山屐经过满迳踪，隔溪遥见夕阳舂。
当时诸葛成何事，只合终身作卧龙。','',''),('quantangshi-31187','自讽','薛能','quantangshi','','卷32','千题万咏过三旬，忘食贪魔作瘦人。
行处便吟君莫笑，就中诗病不任春。','',''),('quantangshi-31188','乞假归题候馆','薛能','quantangshi','','卷32','仆带雕弓马似飞，老莱衣上着戎衣。
邮亭不暇吟山水，塞外经年皆未归。','',''),('quantangshi-31189','监郡犍为将归使府登楼寓题','薛能','quantangshi','','卷32','几日监临向蜀春，错抛歌酒强忧人。
江楼一望西归去，不负嘉州只负身。','',''),('quantangshi-31190','过象耳山二首 一','薛能','quantangshi','','卷32','一色青松几万栽，异香薰路带花开。
山门欲别心潜愿，更到蜀中还到来。','',''),('quantangshi-31191','过象耳山二首 二','薛能','quantangshi','','卷32','到处逢山便欲登，自疑身作往来僧。
徒行至此三千里，不是有缘应不能。','',''),('quantangshi-31192','圣灯','薛能','quantangshi','','卷32','莽莽空中稍稍灯，坐看迷浊变[清澄]。
须知火尽烟无益，一夜栏边说向僧。','',''),('quantangshi-31193','过昌利观有怀','薛能','quantangshi','','卷32','万仞云峯八石泉，李君仙后更谁仙。
我来驻马人何问，老柏无多不种田。','',''),('quantangshi-31194','蜀路','薛能','quantangshi','','卷32','劒阁缘云拂斗魁，疾风生树过龙媒。
前程憩罢知无益，但是驽蹄亦到来。','',''),('quantangshi-31195','山下偶作','薛能','quantangshi','','卷32','零雨霑山百草香，树梢高顶尽斜阳。
横流巨石皆堪住，何事无僧有石房。','',''),('quantangshi-31196','伏牛山','薛能','quantangshi','','卷32','虎蹲峰状屈名牛，落日连村好望秋。
不为时危耕不得，一犁风雨便归休。','',''),('quantangshi-31197','老圃堂','薛能','quantangshi','','卷32','邵平瓜地接吾庐，谷雨干时偶自锄。
昨日春风欺不在，就牀吹落读残书。','',''),('quantangshi-31198','春题','薛能','quantangshi','','卷32','柳莫摇摇花莫开，此心因病亦成灰。
人生只有家园乐，及取春农归去来。','',''),('quantangshi-31199','并州寓怀','薛能','quantangshi','','卷32','人多知遇独难求，人负知音独爱酬。
常恐此心无乐处，枉称年少在并州。','',''),('quantangshi-31200','中秋旅舍','薛能','quantangshi','','卷32','云卷庭虚月逗空，一方秋草尽鸣虫。
