南檐十月绳牀暖，背卷真经向日看。','',''),('quantangshi-31286','赠无表禅师','薛能','quantangshi','','卷32','笠戴圆阴楚地椶，磬敲清响蜀山铜。
秋来说偈寅朝殿，爽爽杨枝满手风。','',''),('quantangshi-31287','彭门偶题','薛能','quantangshi','','卷32','淮王西舍固非夫，柳恽偏州未是都。
直到春秋诸列国，拥旄才子也应无。','',''),('quantangshi-31288','嘲赵璘','薛能','quantangshi','','卷32','巡关每傍摴蒲局，望月还登乞巧楼。
第一莫敎娇太过，缘人衣带上人头。','',''),('quantangshi-31289','句','薛能','quantangshi','','卷32','百首如一首，卷初如卷终。
坐久仆头出，语多僧齿寒。
西塞长云尽，南湖片月斜。
李白终无取，陶潜固不刊。
我身若在开元日，争遣名为李翰林。','',''),('quantangshi-31290','早春','劉威','quantangshi','','卷32','晓来庭户外，草树似依依。
一夜东风起，万山春色归。
冰消泉派动，日暖露珠曦。
已酝看花酒，娇莺莫预飞。','',''),('quantangshi-31291','伤春感怀','劉威','quantangshi','','卷32','花飞惜不得，年长更堪悲。
春尽有归日，老来无去时。
风前千片雪，镜里数茎丝。
肠断青山暮，独攀杨柳枝。','',''),('quantangshi-31292','闰三月','劉威','quantangshi','','卷32','三年皆一闰，此闰胜常时。
莫怪花开晚，都缘春尽迟。
节分炎气近，律应蕙风移。
梦得成胡蝶，芳菲幸不遗。','',''),('quantangshi-31293','早秋游湖上亭','劉威','quantangshi','','卷32','危亭秋尚早，野思已无穷。
竹叶一尊酒，荷香四座风。
晓烟孤屿外，归鸟夕阳中。
渐爱湖光冷，移舟月满空。','',''),('quantangshi-31294','宿渔家','劉威','quantangshi','','卷32','竹屋清江上，风烟四五家。
水园分芰叶，邻界认芦花。
雨到鱼翻浪，洲回鸟傍沙。
月明何处去，片片席帆斜。','',''),('quantangshi-31295','旅中早秋','劉威','quantangshi','','卷32','金威生止水，爽气遍遥空。
草色萧条路，槐花零落风。
夜来万里月，觉后一声鸿。
莫问前程事，飒然沙上蓬。','',''),('quantangshi-31296','早秋西归有怀','劉威','quantangshi','','卷32','求归方有计，惜别更堪愁。
上马江城暮，出郊山戍秋。
暗销何限事，白尽去年头。
莫怪频惆怅，异乡难再游。','',''),('quantangshi-31297','冬夜旅怀','劉威','quantangshi','','卷32','寒窗危竹枕，月过半牀阴。
嫩叶不归梦，晴虫成苦吟。
酒无通夜力，事满五更心。
寂寞谁相似，残灯与素琴。','',''),('quantangshi-31298','塞上作','劉威','quantangshi','','卷32','萧萧陇水侧，落日客愁中。
古塞一声笛，长沙千里风。
鸟无栖息处，人爱战争功。
数夜城头月，弯弯如引弓。','',''),('quantangshi-31299','秋日寄陈景孚秀才','劉威','quantangshi','','卷32','征车日已远，物候尚凄凄。
风叶青桐落，露花红槿低。
心随秦国远，梦到楚山迷。
却恨衔芦雁，秋飞不向西。','',''),('quantangshi-31300','冬日送友人西归','劉威','quantangshi','','卷32','北风吹别思，杳杳度云山。
满望是归处，一生犹未闲。
知音方见誉，浮宦久相关。
空有心如月，同居千里还。','',''),('quantangshi-31301','感寓','劉威','quantangshi','','卷32','海竭山移岁月深，分明齐得世人心。
颜回徒恨少成古，彭祖何曾老至今。
须向道中平贵贱，还从限内任浮沈。
他年免似骊山鬼，信有蓬莱不可寻。','',''),('quantangshi-31302','七夕','劉威','quantangshi','','卷32','乌鹊桥成上界通，千秋灵会此宵同。
云收喜气星楼晓，香拂轻尘玉殿空。
翠辇不行青草路，金銮徒候白榆风。
彩盘花阁无穷意，只在游丝一缕中。','',''),('quantangshi-31303','晚春陪王员外东塘游宴','劉威','quantangshi','','卷32','水绿山青春日长，政成因暇泛回塘。
初移柳岸笙歌合，欲过苹洲罗绮香。
共济已惊依玉树，随流还许醉金觞。
一声画角严城暮，云雨分时满路光。','',''),('quantangshi-31304','游东湖黄处士园林','劉威','quantangshi','','卷32','偶向东湖更向东，数声鸡犬翠微中。
遥知杨柳是门处，似隔芙蓉无路通。
樵客出来山带雨，渔舟过去水生风。
物情多与闲相称，所恨求安计不同。','',''),('quantangshi-31305','题许子正处士新池','劉威','quantangshi','','卷32','坐爱风尘日已西，功成得与化工齐。
巧分孤岛思何远，欲似五湖心易迷。
渐有野禽来试水，又怜春草自侵堤。
那堪更到芙蓉拆，晚夕香联桃李蹊。','',''),('quantangshi-31306','旅怀','劉威','quantangshi','','卷32','物态人心渐渺茫，十年徒学钓沧浪。
老将何面还吾土，梦有惊魂在楚乡。
自是一身嫌苟合，谁怜今日欲佯狂。
无名无位却无事，醉落乌纱卧夕阳。','',''),('quantangshi-31307','早秋归','劉威','quantangshi','','卷32','数口飘零身未回，梦魂遥断越王台。
家书欲寄雁飞远，客恨正深秋又来。
风解绿杨三署冷，月当银汉四山开。
茫茫归路在何处，砧杵一声心已摧。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-31308','欧阳示新诗因贻四韵','劉威','quantangshi','','卷32','冲戛瑶琼得至音，数篇清越应南金。
都由苦思无休日，已证前贤不到心。
风入寒松声自古，水归沧海意皆深。
欲知字字惊神鬼，一气秋时试夜吟。','',''),('quantangshi-31309','尉迟将军','劉威','quantangshi','','卷32','天仗拥门希授钺，重臣入梦岂安金。
江河定后威风在，社稷危来寄托深。
扶病暂将弓试力，感恩重与剑论心。
明妃若遇英雄世，青冢何由怨陆沈。','',''),('quantangshi-31310','赠欧阳秀才','劉威','quantangshi','','卷32','桐上知音日下身，道光谁不仰清尘。
偶来水馆逢为客，旧熟诗名似故人。
永日空惊沧海阔，何年重见白头新。
权门要路应行遍，闲伴山夫一夜贫。','',''),('quantangshi-31311','赠道者','劉威','quantangshi','','卷32','五云深处有真仙，岁月催多却少年。
入郭不知今世事，卖丹犹觅古时钱。
闲寻白鹿眠瑶草，暗摘红桃去洞天。
时向人间深夜坐，鬼神长在药囊边。','',''),('quantangshi-31312','赠道者','劉威','quantangshi','','卷32','道帔轻裾三岛云，绿髯长占镜中春。
高风已驾祥鸾驭，浮世休惊野马尘。
过海独辞王母面，度关谁识老聃身。
儒生也爱长生术，不见人间大笑人。','',''),('quantangshi-31313','遣怀寄欧阳秀才','劉威','quantangshi','','卷32','地上江河天上乌，百年流转只须臾。
平生闲过日将日，欲老始知吾负吾。
似豹一班时或有，如龟三顾岂全无。
古来晚达人何限，莫笑空枝犹望苏。','',''),('quantangshi-31314','送元秀才入道','劉威','quantangshi','','卷32','不教荣乐损天机，愿逐鸾皇次第飞。
明月满时开道帔，俗尘飘处脱儒衣。
只携仙籍还金洞，便与时流隔翠微。
空有缄题报亲爱，一千年后始西归。','',''),('quantangshi-31315','三闾大夫','劉威','quantangshi','','卷32','三闾一去湘山老，烟水悠悠痛古今。
青史已书殷鉴在，词人劳咏楚江深。
竹移低影潜贞节，月入中流洗恨心。
再引离骚见微旨，肯敎渔父会升沈。','',''),('quantangshi-31316','伤曾秀才马','劉威','quantangshi','','卷32','买得龙媒越水濆，轻桃细杏色初分。
秋归未过阳关日，夜魄忽销阴塞云。
吴练已知随影没，朔风犹想带嘶闻。
临轩振策休惆怅，坐致烟霄只在君。','',''),('quantangshi-31317','喷玉泉冥会诗八首 白衣叟途中吟二首 一','李玖','quantangshi','','卷32','春草萋萋春水绿，野棠开尽飘香玉。
绣岭宫前鹤发人，犹唱开元太平曲。','',''),('quantangshi-31318','喷玉泉冥会诗八首 白衣叟途中吟二首 二','李玖','quantangshi','','卷32','厌世逃名者，谁能答姓名。
曾闻王乐否，眷取路傍情。','',''),('quantangshi-31319','喷玉泉冥会诗八首 白衣叟述甘棠馆西楹诗','李玖','quantangshi','','卷32','浮云凄惨日微明，沈痛将军负罪名。
白昼叫阍无近戚，缟衣饮气只门生。
佳人暗泣填宫泪，廐马连嘶换主声。
六合茫茫皆汉土，此身无处哭田横。','',''),('quantangshi-31320','喷玉泉冥会诗八首 白衣叟喷玉泉感旧游书怀','李玖','quantangshi','','卷32','树色川光向晚晴，旧曾游处事分明。
鼠穿月榭荆榛合，草掩花园畦壠平。
迹陷黄沙仍未寤，罪标青简竟何名。
伤心谷口东流水，犹喷当时寒玉声。','',''),('quantangshi-31321','喷玉泉冥会诗八首 四丈夫同赋 一','李玖','quantangshi','','卷32','鸟啼莺语思何穷，一世荣华一梦中。
李固有冤藏蠹简，邓攸无子续清风。
文章高韵传流水，丝管遗音托草虫。
春月不知人事改，闲垂光影照洿宫。','',''),('quantangshi-31322','喷玉泉冥会诗八首 四丈夫同赋 二','李玖','quantangshi','','卷32','桃蹊李径尽荒凉，访旧寻新益自伤。
虽有衣衾藏李固，终无表疏雪王章。
羁魂尚觉霜风冷，朽骨徒惊月桂香。
天爵竟为人爵悞，谁能高叫问苍苍。','',''),('quantangshi-31323','喷玉泉冥会诗八首 四丈夫同赋 三','李玖','quantangshi','','卷32','落花寂寂草绵绵，云影山光尽宛然。
坏室基摧新石鼠，潴宫水引故山泉。
青云自致惭天爵，白首同[归]感昔贤。
惆怅林间中夜月，孤光曾照读书筵。','',''),('quantangshi-31324','喷玉泉冥会诗八首 四丈夫同赋 四','李玖','quantangshi','','卷32','新荆棘路旧衡门，又驻高车会一尊。
寒骨未沾新雨露，春风不长败兰荪。
丹诚岂分埋幽壤，白日终希照覆盆。
珍重昔年金谷友，共来泉际话幽魂。','',''),('quantangshi-31325','下第归宜春酬黄颇饯别','潘唐','quantangshi','','卷32','圣代澄清雨露均，独怀惆怅出咸秦。
承明未荐相如赋，故国犹惭季子贫。
御苑钟声临远水，都门树色背行尘。
一从此地曾携手，益羡江头桃李春。','',''),('quantangshi-31326','题泐潭','裴休','quantangshi','','卷32','泐潭形胜地，祖塔在云湄。
浩劫有穷日，真风无坠时。
岁华空自老，消息竟谁知。
到此轻尘虑，功名自可遗。','',''),('quantangshi-31327','赠黄蘖山僧希运','裴休','quantangshi','','卷32','曾传达士心中印，额有圆珠七尺身。
挂锡十年栖蜀水，浮杯今日渡漳滨。
一千龙象随高步，万里香华结胜因。
拟欲事师为弟子，不知将法付何人。','',''),('quantangshi-31328','登望京楼赋','令狐綯','quantangshi','','卷32','夷门一镇五经秋，未得朝天不免愁。
因上此楼望京国，便名楼作望京楼。','',''),('quantangshi-31329','享太庙乐章','夏侯孜','quantangshi','','卷32','于铄令主，圣祚重昌。
兴起敎义，申明典章。
俗尚素朴，人皆乐康。
积德可报，流庆无疆。','',''),('quantangshi-31330','和重阳锡宴御制诗','魏謩','quantangshi','','卷32','四方无事去，宸豫杪秋来。
八水寒光起，千山霁色开。','',''),('quantangshi-31331','贺王仆射放榜','周墀','quantangshi','','卷32','文场三化鲁儒生，三十余年振重名。
曾忝木鸡夸羽翼，又陪金马入蓬瀛。
虽欣月桂居先折，更羡春兰最后荣。
欲到龙门看风雨，关防不许暂离营。','',''),('quantangshi-31332','酬李常侍立秋日奉诏祭岳见寄','周墀','quantangshi','','卷32','秋祠灵岳奉尊罍，风过深林古柏开。
莲掌月高圭币列，金天雨露鬼神陪。
质明三献虽终礼，祈寿千年别上杯。
岂是琐才能祀事，洪农太守主张来。','',''),('quantangshi-31333','寄华州周侍郎立秋日奉诏祭岳诗','李景讓','quantangshi','','卷32','关河豁静晓云开，承诏秋祠太守来。
山霁莲花添翠黛，路阴桐叶少尘埃。
朱轓入庙威仪肃，玉佩升坛步武回。
往岁今朝几时事，谢君非重我非才。','',''),('quantangshi-31334','句','李景讓','quantangshi','','卷32','成都十万户，抛若一鸿毛。','',''),('quantangshi-31335','续梦中十韵','鄭顥','quantangshi','','卷32','间岁流虹节，归轩出禁扃。
奔波陶畏景，萧洒梦殊庭。
境象非曾到，崇严昔未经。
日斜乌敛翼，风动鹤飘翎。
异苑人争集，凉台笔不停。
石门雾露白，玉殿莓苔青。
若匪灾先兆，何缘思入冥。
御炉虚仗马，华盖负云亭。
白日成千古，金縢閟九龄。
小臣哀绝笔，湖上泣青萍。','',''),('quantangshi-31336','扬州送人','鄭顥','quantangshi','','卷32','桂檝木兰舟，枫江竹箭流。
故人从此去，望远不胜愁。
落日低帆影，归风引棹讴。
思君折杨柳，泪尽武昌楼。','',''),('quantangshi-31337','置酒','鄭顥','quantangshi','','卷32','酒熟人须饮，春还鬓已秋。
愿逢千日醉，得逭百年愁。
卒卒周姬旦，栖栖鲁孔丘。
平生能几日，不及且遨游。','',''),('quantangshi-31338','重阳宴东观山亭和从事卢顺之','張固','quantangshi','','卷32','乱山青翠郡城东，爽节凭高一望通。
交友会时丝管合，羽觞飞处笑言同。
金英耀彩晴云外，玉树凝霜暮雨中。
高咏已劳潘岳思，醉欢慙道自车公。','',''),('quantangshi-31339','独秀山','張固','quantangshi','','卷32','孤峰不与众山俦，直入青云势未休。
会得干坤融结意，擎天一柱在南州。','',''),('quantangshi-31340','长门怨','劉臯','quantangshi','','卷32','营营孤思通，寂寂长门夜。
妾妬亦知非，君恩那不借。
携琴就玉阶，调悲声未谐。
将心寄明月，流影入君怀。','',''),('quantangshi-31341','宿日观东房诗','李質','quantangshi','','卷32','曾入桃溪路，仙源信少双。
洞霞飘素练，藓壁画阴窗。
古木愁撑月，危峰欲堕江。
自吟空向寂，谁共倒秋缸。','',''),('quantangshi-31342','赠副戎','南卓','quantangshi','','卷32','翱翔曾在玉京天，堕落江南路几千。
从事不须轻县宰，满身犹带御炉烟。','',''),('quantangshi-31343','命妓盛小丛歌饯崔侍御还阙','李訥','quantangshi','','卷32','绣衣奔命去情多，南国佳人敛翠娥。
曾向敎坊听国乐，为君重唱盛丛歌。','',''),('quantangshi-31344','李尚书命妓歌饯有作奉酬','崔元範','quantangshi','','卷32','羊公留宴岘山亭，洛浦高歌五夜情。
独向柏台为老吏，可怜林木响余声。','',''),('quantangshi-31345','和李尚书命妓歌饯崔侍御','楊知至','quantangshi','','卷32','燕赵能歌有几人，为花回雪似含颦。
声随御史西归去，谁伴文翁怨九春。','',''),('quantangshi-31346','覆落后呈同年','楊知至','quantangshi','','卷32','由来梁雁与冥鸿，不合翩翩向碧空。
寒谷谩劳邹氏律，长天独遇宋都风。
此时泣玉情虽异，他日衔环事亦同。
二月春光正摇荡，无因得醉杏园中。','',''),('quantangshi-31347','送韦觐谪潘州','李明遠','quantangshi','','卷32','北鸟飞不到，南人谁去游。
天涯浮瘴水，岭外向潘州。
草木春秋暮，猨猱日夜愁。
定知迁客泪，应只对君流。','',''),('quantangshi-31348','前望江麴令颂德','蕭縝','quantangshi','','卷32','政绩虽殊道且同，无辞买石纪前功。
谁论重德光青史，过里犹歌卧辙风。','',''),('quantangshi-31349','重阳东观席上赠侍郎张固','盧順之','quantangshi','','卷32','渡江旌斾动鱼龙，令节开筵上碧峰。
翡翠巢低岩桂小，茱萸房湿露香浓。
白云郊外无尘事，黄菊筵中尽醉容。
好是谢公高兴处，夕阳归骑出疎松。','',''),('quantangshi-31350','责汉水辞','李善夷','quantangshi','','卷32','汉之广兮，风波四起。
虽有风波，不如蹄涔之水。
蹄涔之水，不为下国而倾天子。
汉之深兮，其堤莫量。
虽云莫量，不如行潦之汪。
行潦之汪，不为下国而溺天王。
汉之美者曰鲂，吾虽饥不食其鲂，恐污吾之饥肠。','',''),('quantangshi-31351','大堤曲','李善夷','quantangshi','','卷32','酒旗相望大堤头，堤下连墙堤上楼。
日暮行人争渡急，桨声幽轧满中流。','',''),('quantangshi-31352','金灯','盧溵','quantangshi','','卷32','疎茎秋拥翠，幽艳夕添红。
有月长灯在，无烟烬火同。
香浓初受露，势庳不知风。
应笑金台上，先随晓漏终。','',''),('quantangshi-31353','和李尚书命妓饯崔侍御','盧溵','quantangshi','','卷32','乌台上客紫髯公，共捧天书静境中。
桃朵不辞歌白苎，耶溪暮雨起樵风。','',''),('quantangshi-31354','对酒','趙牧','quantangshi','','卷32','云翁耕扶桑，种黍养日乌。
手挼六十花甲子，循环落落如弄珠。
长绳系日未是愚，有翁临镜捋白须。
饥魂吊骨吟古书，冯唐八十无高车。
人生如云在须臾，何乃自苦八尺躯。
裂衣换酒且为娱，劝君朝饮一瓢。
夜饮一壶，杞天崩。
雷腾腾，桀非尧是何足凭。
桐君桂父岂胜我，醉里白龙多上升。
菖蒲花开鱼尾定，金丹始可延君命。','',''),('quantangshi-31355','南歌子词三首 一','裴諴','quantangshi','','卷32','不是厨中丳，争知{炙火=肉}里心。
井边银钏落，展转恨还深。','',''),('quantangshi-31356','南歌子词三首 二','裴諴','quantangshi','','卷32','不信长相忆，抬头问取天。
风吹荷叶动，无夜不摇莲。','',''),('quantangshi-31357','南歌子词三首 三','裴諴','quantangshi','','卷32','簳蜡为红烛，情知不自由。
细丝斜结网，争奈眼相钩。','',''),('quantangshi-31358','新添声杨柳枝词 一','裴諴','quantangshi','','卷32','思量大是恶姻缘，只得相看不得怜。
愿作琵琶槽那畔，得他长抱在胷前。','',''),('quantangshi-31359','新添声杨柳枝词 二','裴諴','quantangshi','','卷32','独房莲子没人看，偷折莲时命也𢬵。
若有所由来借问，但道偷莲是下官。','',''),('quantangshi-31360','夏杪登越王楼临涪江望雪山寄朝中知友','于興宗','quantangshi','','卷32','巴西西北楼，堪望亦堪愁。
山乱江回远，川清树欲秋。
晴明中雪岭，烟霭下渔舟。
写寄朝天客，知余恨独游。','',''),('quantangshi-31361','东阳涵碧亭','于興宗','quantangshi','','卷32','高低竹杂松，积翠复留风。
路剧阴溪里，寒生暑气中。','',''),('quantangshi-31362','奉酬绵州中丞以江山小图远垂赐及兼寄诗','李朋','quantangshi','','卷32','巴江与雪山，井邑共回环。
图写丹青内，分明烟霭间。
移君名郡兴，助我小斋闲。
日想登临处，高踪不可攀。','',''),('quantangshi-31363','奉酬于中丞登越王楼见寄之什','楊牢','quantangshi','','卷32','劒外书来日，惊忙自折封。
丹青得山水，强健慰心胸。
事少胜诸郡，江回见几重。
宁悲久作别，且似一相逢。
诗合焚香咏，愁应赖酒浓。
庾楼寒更忆，肠断雪千峰。','',''),('quantangshi-31364','赠舍弟','楊牢','quantangshi','','卷32','秦云蜀浪两堪愁，尔养晨昏我远游。
千里客心难寄梦，两行乡泪为君流。
早驱风雨知龙圣，饿食鱼鰕觉虎羞。
袖里镆铘光似水，丈夫不合等闲休。','',''),('quantangshi-31365','句','楊牢','quantangshi','','卷32','虾𢋙欲吃月，保让常敎圆。
心明外不察，月向怀中圆。
罗帏若不卷，谁道中无人。
魁形下方天顶亚，二十四寸窗中月。','',''),('quantangshi-31366','和绵州于中丞登越王楼见寄','李續','quantangshi','','卷32','早年登此楼，退想不胜愁。
地远二千里，时将四十秋。
邅迍多失路，华皓任虚舟。
诗酒虽堪使，何因得共游。','',''),('quantangshi-31367','和绵州于中丞登越王楼作','李汶濡','quantangshi','','卷32','珍重巴西守，殷勤寄远情。
劒峰当户碧，诗韵满楼清。
日照涪川阔，烟笼雪峤明。
征黄看即及，莫叹滞江城。','',''),('quantangshi-31368','和于中丞夏杪登越王楼望雪山见寄','田章','quantangshi','','卷32','志乖多感物，临眺更增愁。
暑候虽云夏，江声已似秋。
雪遥难辨木，村近好维舟。
莫恨归朝晚，朝簪拟胜游。','',''),('quantangshi-31369','和绵州于中丞登越王楼作','薛蒙','quantangshi','','卷32','左绵江上楼，五马此销愁。
暑退千山雪，风来万木秋。
邅回犹刺郡，系滞似维舟。
即有征黄日，名川莫厌游。','',''),('quantangshi-31370','和绵州于中丞登越王楼作','李鄴','quantangshi','','卷32','长听巴西事，看图胜所闻。
江楼明返照，雪岭乱晴云。
景象诗情在，幽奇笔迹分。
使君徒说好，不祗怨离羣。','',''),('quantangshi-31371','和绵州于中丞登越王楼作二首 一','于瓌','quantangshi','','卷32','楼因藩邸号，川势似依楼。
显敞含清暑，岚光入素秋。
山宜姑射貌，江泛李膺舟。
郢曲思朋执，轻纱画胜游。','',''),('quantangshi-31372','和绵州于中丞登越王楼作二首 二','于瓌','quantangshi','','卷32','极目郡城楼，浮云拂槛愁。
政成多暇日，诗思动先秋。
远霁千岩雪，随波一叶舟。
昔曾窥粉绘，今愿许陪游。','',''),('quantangshi-31373','和于中丞登越王楼','王嚴','quantangshi','','卷32','雉堞临朱槛，登兹便散愁。
蝉声怨炎夏，山色报新秋。
江转穿云树，心闲随叶舟。
仲[宣]徒有叹，谢守几追游。','',''),('quantangshi-31374','题越王楼寄献中丞使君','劉暌','quantangshi','','卷32','朱轩迥压碧烟州，昔岁贤王是胜游。
山簇劒峰朝阙远，水如巴字遶城流。
人间物象分千里，天上笙歌醉五侯。
今日登临无限意，同霑惠化自销愁。','',''),('quantangshi-31375','秋日登越王楼献于中丞','李渥','quantangshi','','卷32','越王曾牧劒南州，因向城隅建此楼。
横玉远开千峤雪，暗雷下听一江流。
画檐先弄朝阳色，朱槛低临众木秋。
徒学仲宣聊四望，且将词赋好依刘。','',''),('quantangshi-31376','洋州于中丞顷牧左绵题诗越王楼上朝贤继和輙课四韵','劉璐','quantangshi','','卷32','隔政代君侯，多惭迹令猷。
山光来户牖，江鸟满汀洲。
雅韵征朝客，清词写郡楼。
至今谣未已，注意在洋州。','',''),('quantangshi-31377','和于中丞登越王楼作','盧栯','quantangshi','','卷32','图[画]越王楼，开缄慰别愁。
山光涵雪冷，水色带江秋。
云岛孤征雁，烟帆一叶舟。
向风舒霁景，如伴谢公游。','',''),('quantangshi-31378','飞鸿响远音','李體仁','quantangshi','','卷32','漠漠微霜夕，翩翩出渚鸿。
清声流逈野，高韵入寥空。
旧质经寒塞，残音响远风。
萦云犹类网，避月尚疑弓。
弱羽虽能振，丹霄竟未通。
欲知多怨思，听取暮烟中。','',''),('quantangshi-31379','春愁','韓琮','quantangshi','','卷32','金乌长飞玉兔走，青鬓长青古无有。
秦娥十六语如弦，未解贪花惜杨柳。
吴鱼岭雁无消息，水誓兰情别来久。
劝君年少莫游春，暖风迟日浓于酒。','',''),('quantangshi-31380','牡丹','韓琮','quantangshi','','卷32','残花何处藏，尽在牡丹房。
嫩蘂包金粉，重葩结绣囊。
云凝巫峡梦，帘闭景阳妆。
应恨年华促，迟迟待日长。','',''),('quantangshi-31381','兴平县野中得落星石移置县斋','韓琮','quantangshi','','卷32','的的堕芊苍，茫茫不记年。
几逢疑虎将，应逐犯牛仙。
择地依兰畹，题诗间锦钱。
何时成五色，却上女娲天。','',''),('quantangshi-31382','题商山店','韓琮','quantangshi','','卷32','商山驿路几经过，未到仙娥见谢娥。
红锦机头抛皓腕，绿云鬟下送横波。
佯嗔阿母留宾客，暗为王孙换绮罗。
碧涧门前一条水，岂知平地有天河。','',''),('quantangshi-31383','风','韓琮','quantangshi','','卷32','竞持飘忽意何穷，为盛为衰半不同。
偃草喜逢新雨后，鸣条愁听晓霜中。
凉飞玉管来秦甸，暗褭花枝入楚宫。
莫见东风便无定，满帆还有济川功。','',''),('quantangshi-31384','云','韓琮','quantangshi','','卷32','深惹离情霭落晖，如车如盖早依依。
山头触石应常在，天际从龙自不归。
莫向隙窗笼夜月，好来仙洞湿行衣。
春风淡荡无心后，见说襄王梦亦稀。','',''),('quantangshi-31385','露','韓琮','quantangshi','','卷32','长随圣泽堕尧天，濯遍幽兰叶叶鲜。
才喜轻尘销陌上，已愁新月到堦前。
文腾要地成非久，珠缀秋荷偶得圆。
几处花枝抱离恨，晓风残月正澘然。','',''),('quantangshi-31386','霞','韓琮','quantangshi','','卷32','应是行云未拟归，变成春态媚晴晖。
深如绮色斜分阁，碎似花光散满衣。
天际欲销重惨淡，镜中闲照正依稀。
晓来何处低临水，无限鸳鸯妬不飞。','',''),('quantangshi-31387','颍亭','韓琮','quantangshi','','卷32','颍上新亭瞰一川，几重旧址敞幽关。
寒声北下当轩水，翠影西来扑槛山。
远目静随孤鹤去，高情常共白云闲。
知君久负巢由志，早晚相忘寂寞间。','',''),('quantangshi-31388','咏马','韓琮','quantangshi','','卷32','曾经伯乐识长鸣，不似龙行不敢行。
金埒未登嘶若是，盐车犹驾瘦何惊。
难逢王济知音癖，欲就燕昭买骏名。
早晚飞黄引同皂，碧云天上作鸾鸣。','',''),('quantangshi-31389','题圭峰下长孙家林亭','韓琮','quantangshi','','卷32','赵国林亭二百年，绿苔如毯葛如烟。
闲期竹色摇霜看，醉惜松声枕月眠。
出树圭峰寒压坐，入篱沙濑碧流天。
明知富贵非身物，莫为金章堕地仙。','',''),('quantangshi-31390','牡丹','韓琮','quantangshi','','卷32','桃时杏日不争浓，叶帐阴成始放红。
晓艳远分金掌露，暮香深惹玉堂风。
名移兰杜千年后，贵擅笙歌百醉中。
如梦如仙忽零落，暮霞何处绿屏空。','',''),('quantangshi-31391','雨','韓琮','quantangshi','','卷32','阴云拂地散丝轻，长得为霖济物名。
夜浦涨归天堑阔，春风洒入御沟平。
轩车几处归频湿，罗绮何人去欲生。
不及流他荷叶上，似珠无数转分明。','',''),('quantangshi-31392','京西即事','韓琮','quantangshi','','卷32','秋草河兰起阵云，凉州唯向管弦闻。
豺狼毳幕三千帐，貔虎金戈十万军。
候骑北来惊有说，戍楼西望悔为文。
昭阳亦待平安火，谁握旌旗不见勋。','',''),('quantangshi-31393','公子行','韓琮','quantangshi','','卷32','紫袖长衫色，银蝉半臂花。
带装盘水玉，鞍绣坐云霞。
别殿承恩泽，飞龙赐渥洼。
控罗青褭辔，镂象碧熏葩。
意气倾歌舞，阑珊走钿车。
袖障云缥缈，钗转凤欹斜。
珠卷迎归箔，雕笼晃醉纱。
唯无难夜日，不得似仙家。','',''),('quantangshi-31394','秋晚信州推院亲友或责无书即事寄答','韓琮','quantangshi','','卷32','官信安仁拙，书非叔夜慵。
谬驰骢马传，难附鲤鱼封。
万里劳何补，千年运忝逢。
不量横草力，虚慕入云踪。
洁水空澄鉴，持铅亦砺锋。
月寒深夜桂，霜凛近秋松。
宪摘无逃魏，冤申得梦冯。
问狸将挟虎，歼虿敢虞蜂。
商吹移砧调，春华改镜容。
归期方畹积，愁思暮山重。
仙鼠犹惊燕，莎鸡欲变蛩。
唯应碧湘浦，云落及芙蓉。','',''),('quantangshi-31395','晚春江晴寄友人','韓琮','quantangshi','','卷32','晚日低霞绮，晴山远画眉。
春青河畔草，不是望乡时。','',''),('quantangshi-31396','凉州词','韓琮','quantangshi','','卷32','树发花如锦，莺啼柳若丝。
更游欢宴地，悲见别离时。','',''),('quantangshi-31397','莫春浐水送别','韓琮','quantangshi','','卷32','绿暗红稀出凤城，暮云楼阁古今情。
行人莫听宫前水，流尽年光是此声。','',''),('quantangshi-31398','骆谷晚望','韓琮','quantangshi','','卷32','秦川如画渭如丝，去国还家一望时。
公子王孙莫来好，岭花多是断肠枝。','',''),('quantangshi-31399','二月二日游洛源','韓琮','quantangshi','','卷32','旧苑新晴草似苔，人还香在踏青回。
今朝此地成惆怅，已后逢春更莫来。','',''),('quantangshi-31400','柳','韓琮','quantangshi','','卷32','折柳歌中得翠条，远移金殿种青霄。
上阳宫女含声送，不忿先归舞细腰。','',''),('quantangshi-31401','杨柳枝','韓琮','quantangshi','','卷32','梁苑隋堤事已空，万条犹舞旧春风。
那堪更想千年后，谁见杨花入汉宫。','',''),('quantangshi-31402','杨柳枝词','韓琮','quantangshi','','卷32','枝鬬纤腰叶鬬眉，春来无处不如丝。
霸陵原上多离别，少有长条拂地垂。','',''),('quantangshi-31403','和襄阳徐相公商贺徐副使加章绶','王傳','quantangshi','','卷32','朱紫联辉照日新，芳菲全属断金人。
华筵重处宗盟地，白雪飞时郢曲春。
仙府色饶攀桂侣，莲花光让握兰身。
自怜亦是膺门客，吟想恩荣气益振。','',''),('quantangshi-31404','和李尚书命妓饯崔侍御','盧鄴','quantangshi','','卷32','何郎载酒别贤侯，更吐歌珠宴庾楼。
莫道江南不同醉，即陪舟檝上京游。','',''),('quantangshi-31405','松','陸肱','quantangshi','','卷32','雪霜知劲质，今古占嘉名。
断砌盘根远，疎林偃盖清。
鹤栖何代色，僧老四时声。
郁郁心弥久，烟高万井生。','',''),('quantangshi-31406','赠王福娘','崔澹','quantangshi','','卷32','怪得清风送异香，娉婷仙子曳霓裳。
惟应错认偷桃客，曼倩曾为汉侍郎。','',''),('quantangshi-31407','答问读书居','莫宣卿','quantangshi','','卷32','书屋倚麒麟，不同牛马路。
牀头万卷书，溪上五龙渡。
井汲冽寒泉，桂花香玉露。
茅檐无外物，只见青云护。','',''),('quantangshi-31408','百官乘月早朝听残漏','莫宣卿','quantangshi','','卷32','建礼俨朝冠，重门耿夜阑。
碧空蟾魄度，清禁漏声残。
候晓车舆合，凌霜剑佩寒。
星河犹皎皎，银箭尚珊珊。
杳霭祥光起，霏微瑞气攒。
忻逢圣明代，长愿接鵷鸾。','',''),('quantangshi-31409','赋得水怀珠','莫宣卿','quantangshi','','卷32','长川含媚色，波底孕灵珠。
素魄生苹末，圆规照水隅。
沦涟冰彩动，荡漾瑞光铺。
迥夜星同贯，清秋岸不枯。
江妃思在掌，海客亦忘躯。
合浦当还日，恩威信已敷。','',''),('quantangshi-31410','句','莫宣卿','quantangshi','','卷32','我本南山凤，岂同凡鸟羣。','',''),('quantangshi-31411','和李尚书命妓饯崔侍御','封彥卿','quantangshi','','卷32','莲府才为绿水宾，忽乘骢马入咸秦。
为君唱作西[河]调，日暮偏伤去住人。','',''),('quantangshi-31412','一','封彥卿','quantangshi','','卷32','湘川狺狺兮俗犷且佷，利杀业偷兮吏莫之驯。
繄释氏兮易暴使仁，释何在兮释在斯文。','',''),('quantangshi-31413','二','封彥卿','quantangshi','','卷32','湘水滔滔兮四望何依，猨狖腾拏兮云树飞飞。
月沈浦兮烟暝山，樯席卷兮橹牀闲。','',''),('quantangshi-31414','三','封彥卿','quantangshi','','卷32','湘川超忽兮落日晼晼，松覆秋亭兮兰被春苑。
上人去兮几千里，何日同游兮湘川水。','',''),('quantangshi-31415','和柯古穷居苦日喜雨','韋蟾','quantangshi','','卷32','贞机澹少思，雅尚防多僻。
揽葛犹不畏，劳形同处瘠。
头焦讵是焚，背汗宁关炙。
方欣见润础，那虞悲铄石。
道与古人期，情难物外适。
几怀朱邸绶，颇旷金门籍。
清奥已萧萧，陈柯将槭槭。
玉律诗调正，琼巵酒肠窄。
衣桁袭中单，浴牀抛下綌。
黎侯寓于卫，六义非凡格。','',''),('quantangshi-31416','岳麓道林寺','韋蟾','quantangshi','','卷32','石门逈接苍梧野，愁色阴深二妃寡。
广殿崔嵬万壑间，长廊诘曲千岩下。
静听林飞念佛鸟，细看壁画驮经马。
暖日斜明螮蝀梁，湿烟散幂鸳鸯瓦。
北方部落檀香塑，西国文书贝叶写。
坏栏迸竹醉好题，窄路垂藤困堪把。
沈裴笔力鬬雄壮，宋杜词源两风雅。
他方居士来施斋，彼岸上人投结夏。
悲我未离扰扰徒，劝我休学悠悠者。
何时得与刘遗民，同入东林远公社。','',''),('quantangshi-31417','上元三首 一','韋蟾','quantangshi','','卷32','新正圆月夜，尤重看灯时。
累塔嫌沙细，成文讶笔迟。
归牛疑燧落，过雁悞书迟。
生惜兰膏烬，还为隔岁期。','',''),('quantangshi-31418','上元三首 二','韋蟾','quantangshi','','卷32','举烛光才起，挥毫势竞分。
点时惊坠石，挑处接崩云。
辞异秦丞相，铭非窦冠军。
唯愁残焰落，逢玉亦俱焚。','',''),('quantangshi-31419','上元三首 三','韋蟾','quantangshi','','卷32','多宝神光动，生金瑞色浮。
照人低入郭，伴月夜当楼。
熏穴应无取，焚林固有求。
夜阑陪玉帐，不见九枝留。','',''),('quantangshi-31420','梅','韋蟾','quantangshi','','卷32','高树临溪艳，低枝隔竹繁。
何须是桃李，然后欲忘言。
拟折魂先断，须看眼更昏。
谁知南陌草，却解望王孙。','',''),('quantangshi-31421','送卢潘尚书之灵武','韋蟾','quantangshi','','卷32','贺兰山下果园成，塞北江南旧有名。
水木万家朱户暗，弓刀千队铁衣鸣。
心源落落堪为将，胆气堂堂合用兵。
却使六番诸子弟，马前不信是书生。','',''),('quantangshi-31422','题僧壁','韋蟾','quantangshi','','卷32','一竹横檐挂净巾，竈无烟火地无尘。
剃头未必知心法，要且闲于名利人。','',''),('quantangshi-31423','赠商山僧','韋蟾','quantangshi','','卷32','商岭东西路欲分，两间茅屋一溪云。
师言耳重知师意，人是人非不欲闻。','',''),('quantangshi-31424','长乐驿谑李汤给事题名','韋蟾','quantangshi','','卷32','渭水秦川拂眼明，希仁何事寡诗情。
只应学得虞姬壻，书字才能记姓名。','',''),('quantangshi-31425','句','韋蟾','quantangshi','','卷32','争挥钩弋手，竞耸踏摇身。
伤颊讵关舞，捧心非効嚬。','',''),('quantangshi-31426','赋得寿星见','盧渥','quantangshi','','卷32','玄象今何应，时和政亦平。
祥为一人寿，色映九霄明。
皎洁垂银汉，光芒近斗城。
含规同月满，表瑞得天清。
甘露盈条降，非烟向日生。
无如此嘉祉，率土荷秋成。','',''),('quantangshi-31427','题嘉祥驿','盧渥','quantangshi','','卷32','交亲荣饯洛城空，秉钺戎装上将同。
星使自天丹诏下，雕鞍照地数程中。
马嘶静谷声偏响，斾映晴山色更红。
到后定知人易化，满街棠树有遗风。','',''),('quantangshi-31428','九华山','郭夔','quantangshi','','卷32','岩翠凌云出迥然，岧嶤万丈倚秋天。
暮风飘送当轩色，晓雾斜飞入槛烟。
帘卷倚屏双影聚，镜开朱户九条悬。
画图何必家家有，自有画图来目前。','',''),('quantangshi-31429','送莫仲节状元归省','柳珪','quantangshi','','卷32','青骢聚送谪仙人，南国荣亲不及君。
椰子味从今日近，鹧鸪声向旧山闻。
孤猨夜呌三湘月，匹马时侵五岭云。
想到故乡应腊过，药栏犹有异花薰。','',''),('quantangshi-31430','津阳门诗','鄭嵎','quantangshi','','卷32','津阳门北临通逵，雪风猎猎飘酒旗。
泥寒欵段蹶不进，疲童退问前何为。
酒家顾客催解装，案前罗列樽与巵。
青钱琐屑安足数，白醪软美甘如饴。
开垆引满相献酬，枯肠渴肺忘朝饥。
愁忧似见出门去，渐觉春色入四肢。
主翁移客挑华灯，双肩隐膝乌帽欹。
笑云鲐老不为礼，飘萧雪鬓双垂颐。
问余何往凌寒曦，顾翁枯朽郎岂知。
翁曾豪盛客不见，我自为君陈昔时。
时平亲卫号羽林，我才十五为孤儿。
射熊搏虎众莫敌，弯弧出入随佽飞。
此时初创观风楼，檐高百尺堆华榱。
楼南更起鬬鸡殿，晨光出影相参差。
其年十月移禁仗，山下栉比罗百司。
朝元阁成老君见，会昌县以新丰移。
幽州晓进供奉马，玉珂宝勒黄金羁。
五王扈驾夹城路，传声校猎渭水湄。
羽林六军各出射，笼山络野张罝维。
雕弓绣韣不知数，翻身灭没皆蛾眉。
赤鹰黄鹘云中来，妖狐狡兔无所依。
人烦马殆禽兽尽，百里腥膻禾黍稀。
暖山度腊东风微，宫娃赐浴长汤池。
刻成玉莲喷香液，漱回烟浪深逶迤。
犀屏象荐杂罗列，锦凫绣雁相追随。
破簪碎钿不足拾，金沟残溜和缨緌。
上皇宽容易承事，十家三国争光辉。
绕牀呼卢恣樗博，张灯达昼相谩欺。
相君侈拟纵骄横，日从秦虢多游嬉。
朱衫马前未满足，更驱武卒罗旌旗。
画轮宝轴从天来，云中笑语声融怡。
鸣鞭后骑何躞蹀，宫妆襟袖皆仙姿。
青门紫陌多春风，风中数日残春遗。
骊驹吐沬一奋迅，路人拥彗争珠玑。
八姨新起合欢堂，翔鵾贺燕无由窥。
万金酬工不肯去，矜能恃巧犹嗟咨。
四方节制倾附媚，穷奢极侈沽恩私。
堂中特设夜明枕，银烛不张光鉴帷。
瑶光楼南皆紫禁，梨园仙宴临花枝。
迎娘歌喉玉𥦖窱，蛮儿舞带金葳蕤。
三郎紫笛弄烟月，怨如别鹤呼羁雌。
玉奴琵琶龙香拨，倚歌促酒声娇悲。
饮鹿泉边春露曦，粉梅檀杏飘朱墀。
金沙洞口长生殿，玉蘂峰头王母祠。
禁庭术士多幻化，上前较胜纷相持。
罗公如意夺颜色，三藏袈裟成散丝。
蓬莱池上望秋月，无云万里悬清辉。
上皇夜半月中去，三十六宫愁不归。
月中秘乐天半间，丁璫玉石和埙篪。
宸聪听览未终曲，却到人间迷是非。
千秋御节在八月，会同万国朝华夷。
花萼楼南大合乐，八音九奏鸾来仪。
都卢寻幢诚龌龊，公孙劒伎方神奇。
马知舞彻下牀榻，人惜曲终更羽衣。
禄山此时侍御侧，金鸡画障当罘罳。
绣{衤羽}衣褓日屓贔，甘言狡计愈娇痴。
诏令上路建甲第，楼通走马如飞翚。
大开内府恣供给，玉缶金筐银簸箕。
异谋潜炽促归去，临轩赐带盈十围。
忠臣张公识逆状，日日切谏上弗疑。
汤成召浴果不至，潼关已溢渔阳师。
御街一夕无禁鼓，玉辂顺动西南驰。
九门回望尘坌多，六龙夜驭兵卫疲。
县官无人具军顿，行宫彻屋屠云螭。
马嵬驿前驾不发，宰相射杀冤者谁。
长眉鬒发作凝血，空有君王潜涕涕。
青泥坂上到三蜀，金堤城边止九旗。
移文泣祭昔臣墓，度曲悲歌秋雁辞。
明年尚父上捷书，洗清观阙收封畿。
两君相见望贤顿，君臣鼓舞皆歔欷。
宫中亲呼高骠骑，潜令改葬杨真妃。
花肤雪艳不复见，空有香囊和泪滋。
鉴舆却入华清宫，满山红实垂相思。
飞霜殿前月悄悄，迎春亭下风飔飔。
雪衣女失玉笼在，长生鹿瘦铜牌垂。
象牀尘凝罨飒被，画檐虫网颇梨碑。
碧菱花覆云母陵，风篁雨菊低离披。
真人影帐偏生草，果老药堂空掩扉。
鼎湖一日失弓劒，桥山烟草俄霏霏。
空闻玉椀入金市，但见铜壶飘翠帷。
开元到今逾十纪，当初事迹皆残隳。
竹花唯养栖梧凤，水藻周游巢叶龟。
会昌御宇斥内典，去留二敎分黄缁。
庆山污潴石瓮毁，红楼绿阁皆支离。
奇松怪柏为樵苏，童山眢谷亡嶮巇。
烟中壁碎摩诘画，云间字失玄宗诗。
石鱼岩底百寻井，银牀下卷红绠迟。
当时清影荫红叶，一旦飞埃埋素规。
韩家烛台倚林杪，千枝灿若山霞摛。
昔年光彩夺天月，昨日销镕当路岐。
龙宫御榜高可惜，火焚牛挽临崎峗。
孔雀松残赤琥珀，鸳鸯瓦碎青琉璃。
今我前程能几许，徒有余息筋力羸。
逢君话此空洒涕，却忆欢娱无见期。
主翁莫泣听我语，宁劳感旧休吁嘻。
河清海宴不难覩，我皇已上升平基。
湟中土地昔湮没，昨夜收复无疮痍。
戎王北走弃青冢，虏马西奔空月支。
两逢尧年岂易偶，愿翁颐养丰肤肌。
平明酒醒便分首，今夕一樽翁莫违。','',''),('quantangshi-31431','春日即事','崔櫓','quantangshi','','卷32','一百五日又欲来，梨花梅花参差开。
行人自笑不归去，瘦马独吟真可哀。
杏酪渐香邻舍粥，榆烟将变旧炉灰。
画桥春暖清歌夜，肯信愁肠日九回。','',''),('quantangshi-31432','春晚岳阳言怀二首 一','崔櫓','quantangshi','','卷32','烟花零落过清明，异国光阴老客情。
云梦夕阳愁里色，洞庭春浪坐来声。
天边一与旧山别，江上几看芳草生。
独倚阑干意难写，暮笳呜咽调孤城。','',''),('quantangshi-31433','春晚岳阳言怀二首 二','崔櫓','quantangshi','','卷32','翠烟如钿柳如环，晴倚南楼独看山。
江国草花三月暮，帝城尘梦一年间。
虚舟尚叹萦难解，飞鸟空惭倦未还。
何似不羁詹父伴，睡烟歌月老潺潺。','',''),('quantangshi-31434','过蛮溪渡','崔櫓','quantangshi','','卷32','绿杨如发雨如烟，立马危桥独唤船。
山口断云迷旧路，渡头芳草忆前年。
身随远道徒悲梗，诗卖明时不直钱。
归去楚台还有计，钓船春雨日高眠。','',''),('quantangshi-31435','岸梅','崔櫓','quantangshi','','卷32','含情含怨一枝枝，斜压渔家短短篱。
惹袖尚余香半日，向人如诉雨多时。
初开偏称雕梁画，未落先愁玉笛吹。
行客见来无去意，解帆烟浦为题诗。','',''),('quantangshi-31436','重阳日次荆南路经武宁驿','崔櫓','quantangshi','','卷32','茱萸冷吹溪口香，菊花倒遶山脚黄。
家山去此强百里，弟妹待我醉重阳。
风健旱鸿高晓景，露清圆碧照秋光。
莫看时节年年好，暗送搔头逐手霜。','',''),('quantangshi-31437','述怀','崔櫓','quantangshi','','卷32','白首成何事，无欢可替悲。
空余酒中兴，犹似少年时。','',''),('quantangshi-31438','三月晦日送客','崔櫓','quantangshi','','卷32','野酌乱无巡，送君兼送春。
明年春色至，莫作未归人。','',''),('quantangshi-31439','华清宫三首 一','崔櫓','quantangshi','','卷32','草遮回蹬绝鸣銮，云树深深碧殿寒。
明月自来还自去，更无人倚玉栏干。','',''),('quantangshi-31440','华清宫三首 二','崔櫓','quantangshi','','卷32','障掩金鸡蓄祸机，翠华西拂蜀云飞。
珠帘一闭朝元阁，不见人归见燕归。','',''),('quantangshi-31441','华清宫三首 三','崔櫓','quantangshi','','卷32','门横金锁悄无人，落日秋声渭水滨。
红叶下山寒寂寂，湿云如梦雨如尘。','',''),('quantangshi-31442','题云梦亭','崔櫓','quantangshi','','卷32','薄烟如梦雨如尘，霜景晴来却胜春。
好住池西红叶树，何年今日伴何人。','',''),('quantangshi-31443','有酒失于虔州陆郎中肱以诗谢之','崔櫓','quantangshi','','卷32','醉时颠蹶醒时羞，麴糵推人不自由。
叵耐一双穷相眼，不堪花卉在前头。','',''),('quantangshi-31444','闻笛','崔櫓','quantangshi','','卷32','银河漾漾月晖晖，楼碍星边织女机。
横玉叫云天似水，满空霜逐一声飞。','',''),('quantangshi-31445','山路见花','崔櫓','quantangshi','','卷32','晓红初拆露香新，独立空山冷笑人。
春意自知无主惜，恣风吹逐马蹄尘。','',''),('quantangshi-31446','暮春对花','崔櫓','quantangshi','','卷32','病香无力被风欺，多在青苔少在枝。
马上行人莫回首，断君肠是欲残时。','',''),('quantangshi-31447','句','崔櫓','quantangshi','','卷32','强半瘦因前夜雪，数枝愁向晚天来。
无人解把无尘袖，盛取残香尽日怜。
一番春雨吹巢冷，半朵山花咽觜香。
云生柱础降龙地，露洗林峦放鹤天。
菱叶乍翻人采后，荇花初没舸行时。','',''),('quantangshi-31448','乌夜号','李羣玉','quantangshi','','卷32','层波隔梦渚，一望青枫林。
有鸟在其间，达晓自悲吟。
是时月黑天，四野烟雨深。
如闻生离哭，其声痛人心。
悄悄夜正长，空山响哀音。
远客不可听，坐愁华发侵。
既非蜀帝魂，恐是桓山禽。
四子各分散，母声犹至今。','',''),('quantangshi-31449','升仙操','李羣玉','quantangshi','','卷32','嬴女去秦宫，琼笙飞碧空。
凤台闭烟雾，鸾吹飘天风。
复闻周太子，亦遇浮丘公。
丛簧发天弄，轻举紫霞中。
浊世不久驻，清都路何穷。
一去霄汉上，世人那得逢。','',''),('quantangshi-31450','雨夜呈长官','李羣玉','quantangshi','','卷32','远客坐长夜，雨声孤寺秋。
请量东海水，看取浅深愁。
愁穷重于山，终年压人头。
朱颜与芳景，暗赴东波流。
鳞翼思风水，青云方阻修。
孤灯冷素艳，虫响寒房幽。
借问陶渊明，何物号忘忧。
无因一酩酊，高枕万情休。','',''),('quantangshi-31451','小弟艎南游近书来','李羣玉','quantangshi','','卷32','湘南客帆稀，游子寡消息。
经时停尺素，望尽云边翼。
笑言频梦寐，独立想容色。
落景无来人，修江入天白。
停停倚门念，瑟瑟风雨夕。
何处泊扁舟，迢遰湍波侧。
秋归旧窗竹，永夜一凄寂。
吟尔鹡鸰篇，中宵慰相忆。','',''),('quantangshi-31452','赠方处士','李羣玉','quantangshi','','卷32','白衣方外人，高闲溪中鹤。
无心恋稻粱，但以林泉乐。
赤霄终得意，天池俟飞跃。
岁晏入帝乡，期君在寥廓。','',''),('quantangshi-31453','秋怨','李羣玉','quantangshi','','卷32','瑟瑟凉海气，西来送愁容。
金风死绿蕙，玉露生寒松。
所思在溟碧，无因一相逢。
登楼睇去翼，目尽沧波重。
虚窗度流萤，斜月啼幽蛩。
疎红落残艳，冷水凋芙蓉。
岁暮空太息，年华逐遗踪。
凝情耿不寐，揽涕起疎慵。','',''),('quantangshi-31454','感春','李羣玉','quantangshi','','卷32','春情不可状，艳艳令人醉。
暮水绿杨愁，深窗落花思。
吴宫新暖日，海燕双飞至。
秋思逐烟光，空蒙满天地。','',''),('quantangshi-31455','山中秋夕','李羣玉','quantangshi','','卷32','抱琴出南楼，气爽浮云灭。
松风吹天箫，竹路踏碎月。
后山鹤唳定，前浦荷香发。
境寂良夜深，了与人间别。','',''),('quantangshi-31456','将游罗浮登广陵楞伽台别羽客','李羣玉','quantangshi','','卷32','清远登高台，晃朗纵览历。
濯泉唤仙风，于此荡灵魄。
冷光邀远目，百里见海色。
送云归蓬壶，望鹤灭秋碧。
波澜收日气，天自回澄寂。
百越落掌中，十洲点空白。
身居飞鸟上，口咏玄元籍。
飘如出尘笼，想望吹箫客。
冥冥人间世，歌笑不足惜。
朅来罗浮巅，披云炼琼液。
谢公云岑兴，可以蹑高迹。
吾将抱瑶琴，绝境纵所适。','',''),('quantangshi-31457','卢溪道中','李羣玉','quantangshi','','卷32','晓发潺湲亭，夜宿潺湲水。
风篁扫石濑，琴声九十里。
光奔觉来眼，寒落梦中耳。
曾向三峡行，巴江亦如此。','',''),('quantangshi-31458','湖中古愁三首 一','李羣玉','quantangshi','','卷32','凉风西海来，直渡洞庭水。
翛翛木叶下，白浪连天起。
蘅兰委皓雪，百草一时死。
摧残负志人，感叹何穷已。','',''),('quantangshi-31459','湖中古愁三首 二','李羣玉','quantangshi','','卷32','昔我覩云梦，穷秋经汨罗。
灵均竟不返，怨气成微波。
奠桂开古祠，朦胧入幽萝。
落日潇湘上，凄凉吟九歌。','',''),('quantangshi-31460','湖中古愁三首 三','李羣玉','quantangshi','','卷32','南云哭重华，水死悲二女。
天边九点黛，白骨迷处所。
朦胧波上瑟，清夜降北渚。
万古一双魂，飘飘在烟雨。','',''),('quantangshi-31461','别狄佩','李羣玉','quantangshi','','卷32','翠竹不着花，凤雏长忍饥。
未开丹霄翮，空把碧梧枝。
圣人奏云韶，祥凤一来仪。
文章耀白日，众鸟莫敢窥。
郁抑不自言，凡鸟何由知。
当看九千仞，飞出太平时。','',''),('quantangshi-31462','古镜','李羣玉','quantangshi','','卷32','明月何处来，朦胧在人境。
得非轩辕作，妙绝世莫竝。
瑶匣开旭日，白电走孤影。
泓澄一尺天，彻底寒霜景。
冰辉凛毛发，使我肝胆冷。
忽惊行深幽，面落九秋井。
云天入掌握，爽朗神魂净。
不必负局仙，金沙发光炯。
阴沈蓄灵怪，可与天地永。
恐为悲龙吟，飞去在俄顷。','',''),('quantangshi-31463','我思何所在','李羣玉','quantangshi','','卷32','我思何所在，乃在阳台侧。
良宵相望时，空此明月色。
归魂泊湘云，飘荡去不得。
觉来理舟檝，波浪春湖白。
烟光浩楚秋，瑶草不忍摘。
因书天末心，系此双飞翼。','',''),('quantangshi-31464','送萧绾之桂林','李羣玉','quantangshi','','卷32','兰香佩兰人，弄兰兰江春。
尔为兰林秀，芳藻惊常伦。
灿灿凤池裔，一毛今再新。
竹花不给口，憔悴清湘滨。
一朝南溟飞，彩翮不可亲。
苍梧云水晚，离思空凝颦。
我亦纵烟棹，西浮彭蠡津。
丈夫未虎变，落魄甘风尘。
大禹惜寸阴，况我无才身。
流光销道路，以此生嗟辛。
万里阔分袂，相思杳难申。
桂水秋更碧，寄书西上鳞。','',''),('quantangshi-31465','感兴四首 一','李羣玉','quantangshi','','卷32','子云吞白凤，遂吐太玄书。
幽微十万字，枝叶何扶疎。
婉娈猛虎口，甘言累其初。
一覩美新作，斯瑕安可除。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-31466','感兴四首 二','李羣玉','quantangshi','','卷32','昔窃不死药，奔空有嫦娥。
盈盈天上艳，孤洁栖金波。
织女了无语，长宵隔银河。
轧轧挥素手，几时停玉梭。','',''),('quantangshi-31467','感兴四首 三','李羣玉','quantangshi','','卷32','洞房三五夕，金釭凝焰灭。
美人抱云和，斜倚纱窗月。
沈吟想幽梦，闺思深不说。
弦冷玉指寒，含颦待明发。','',''),('quantangshi-31468','感兴四首 四','李羣玉','quantangshi','','卷32','朔雁衔边秋，寒声落燕代。
先惊愁人耳，颜发潜消改。
凝云蔽洛浦，梦寐劳光彩。
天边无书来，相思泪成海。','',''),('quantangshi-31469','将之吴越留别坐中文酒诸侣','李羣玉','quantangshi','','卷32','秋色满水国，江湖兴萧然。
氛埃敛八极，万里净澄鲜。
涔浦纵孤棹，吴门渺三千。
回随衡阳雁，南入洞庭天。
早闻陆士龙，矫掌跨山川。
非思鲈鱼脍，且弄五湖船。
暝泊远浦霞，晓饭芦洲烟。
风流访王谢，佳境恣洄沿。
霜剪别岸柳，香枯北池莲。
岁华坐摇落，寂寂感流年。
明朝即漂萍，离憾无由宣。','',''),('quantangshi-31470','大云池泛舟','李羣玉','quantangshi','','卷32','九月莲花死，萍枯霜水清。
船浮天光远，棹拂翠澜轻。
古木□□□，了无烟霭生。
游鳞泳皎洁，洞见逍遥情。
渔父一曲歌，沧浪遂知名。
未知斯水上，可以濯吾缨。','',''),('quantangshi-31471','送友人之峡','李羣玉','quantangshi','','卷32','东吴有赋客，愿识阳台仙。
彩毫飞白云，不减郢中篇。
楚水五月浪，轻舟入暮烟。
巫云多感梦，桂檝早回旋。','',''),('quantangshi-31472','登宜春醉宿景星寺寄郑判官兼简空上人','李羣玉','quantangshi','','卷32','晓发碧水阳，暝宿金山寺。
松风洒寒雨，淅沥醒余醉。
夜中香积饭，蔬粒俱精异。
境寂灭尘愁，神高得诗思。
皎皎荥阳子，芳春富才义。
涨海豁心源，冰壶见门地。
碧霄有鸠序，未展联行翅。
俱笑一尺绳，三年绊骐骥。
摧藏担簦客，郁抑胸襟事。
名业尔未从，临风嘿舒志。
一身渺云岭，中夜空涕泗。
侧枕对孤灯，衾寒不成寐。
粮薪极桂玉，大道生榛刺。
耻息恶木阴，难书劒歌意。
扬鞭入莽苍，山驿凌烟翠。
越鸟日南飞，芳音愿相次。','',''),('quantangshi-31473','江楼独酌怀从叔','李羣玉','quantangshi','','卷32','水国发爽气，川光静高秋。
酣歌金尊醁，送此清风愁。
楚色忽满目，滩声落西楼。
云翻天边叶，月弄波上钩。
芳意长摇落，蘅兰谢汀洲。
长吟碧云合，怅望江之幽。','',''),('quantangshi-31474','登章华楼','李羣玉','quantangshi','','卷32','楚子故宫地，苍然云水秋。
我来览从事，落景空生愁。
伯业没荆棘，雄图成古丘。
沈吟问鼎语，但见东波流。
征鸿引乡心，一去何悠悠。
晴湖碧云晚，暝色空高楼。
迢遰趋远峤，微茫入孤舟。
空路不堪望，西风白浪稠。','',''),('quantangshi-31475','骢马','李羣玉','quantangshi','','卷32','浮云何权奇，绝足世未知。
长嘶清海风，蹀躞振云丝。
由来渥洼种，本是苍龙儿。
穆满不再活，无人昆阆骑。
若识跃峤怯，宁劳耀金羁。
青刍与白水，空笑驽骀肥。
伯乐傥一见，应惊耳长垂。
当思八荒外，逐日向瑶池。','',''),('quantangshi-31476','赠方处士兼以写别','李羣玉','quantangshi','','卷32','天与云鹤情，人间恣诗酒。
龙宫奉采觅，澒洞一千首。
清如南薰丝，韵若黄钟吼。
喜于风骚地，忽见陶谢手。
籍籍九江西，篇篇在人口。
芙蓉为芳菲，未落诸花后。
所知心眼大，别自开户牖。
才力似风鹏，谁能算升斗。
无营傲云竹，琴帙静为友。
鸾凤戢羽仪，骐骥在郊薮。
镜湖春水绿，越客忆归否。
白衣四十秋，逍遥一何久。
此身无定迹，又逐浮云走。
离思书不穷，残阳落江柳。','',''),('quantangshi-31477','湘西寺霁夜','李羣玉','quantangshi','','卷32','雨过琉璃宫，佳兴浩清绝。
松风冷晴滩，竹路踏碎月。
月波荡如水，气爽星朗灭。
皓夜千树寒，峥嵘万岩雪。
后山鹤唳断，前池荷香发。
境寂凉夜深，神思空飞越。','',''),('quantangshi-31478','伤思','李羣玉','quantangshi','','卷32','八月白露浓，芙蓉抱香死。
红枯金粉堕，寥落寒塘水。
西风团叶下，叠縠参差起。
不见棹歌人，空垂绿房子。','',''),('quantangshi-31479','送郑京昭之云安','李羣玉','quantangshi','','卷32','君吟高唐赋，路过巫山渚。
莫令巫山下，幽梦惹云雨。
往事几千年，芬菲今尚传。
空留荆王馆，岩嶂深苍然。
楚水五月浪，轻舟入苹烟。
送君扬檝去，愁绝郢城篇。','',''),('quantangshi-31480','送处士自番禺东游便归苏台别业','李羣玉','quantangshi','','卷32','哑轧暮江上，橹声摇落心。
宛陵三千里，路指吴云深。
莼菜动归兴，忽然闻会吟。
南浮龙川月，东下敬亭岑。
多君咏逍遥，结萝碧溪阴。
高笼华表鹤，静对幽兰琴。
汗漫江海思，傲然抽冠簪。
归屿未云寂，还家应追寻。
二陆文苑秀，岧嶤怀所钦。
惜我入洛晚，不睹双南金。
江左风流尽，名贤成古今。
送君无限意，别酒但加斟。','',''),('quantangshi-31481','法华微上人盛话金山境胜旧游在目吟成此篇','李羣玉','quantangshi','','卷32','江上青莲宫，人间蓬莱岛。
烟霞与波浪，隐暎楼台好。
潮门梵音静，海日天光早。
愿与灵鹫人，吟经此终老。','',''),('quantangshi-31482','洞庭入澧江寄巴丘故人','李羣玉','quantangshi','','卷32','四月桑半枝，吴蚕初弄丝。
江行好风日，燕舞轻波时。
去事旋成梦，来欢难预期。
唯凭东流水，日夜寄相思。','',''),('quantangshi-31483','自澧浦东游江表途出巴丘投员外从公虞','李羣玉','quantangshi','','卷32','短翮后飞者，前攀鸾鹤翔。
力微应万里，矫首空苍苍。
谁昔探花源，考盘西岳阳。
高风动商洛，绮皓无馨香。
一朝下蒲轮，清辉照岩廊。
孤醒立众醉，古道何由昌。
经术震浮荡，国风扫齐梁。
文襟即玄圃，笔下成琳琅。
霞水散吟啸，松筠奉琴觞。
冰壶避皎洁，武库羞锋铓。
小子书代耕，束发颇自强。
艰哉水投石，壮志空摧藏。
十年侣龟鱼，垂头在沅湘。
巴歌揜白雪，鲍肆埋兰芳。
骚雅道未丧，何忧名不彰。
饥寒束困厄，默塞飞星霜。
百志不成一，东波掷年光。
尘生脱粟甑，万里违高堂。
中夜恨火来，焚烧九回肠。
平明梁山泪，缘枕霑匡牀。
依泊洞庭波，木叶忽已黄。
哀砧捣秋色，晓月啼寒螿。
复此棹孤舟，云涛浩茫茫。
朱门待媒势，短褐谁揄扬。
仰羡野陂凫，无心忧稻粱。
不如天边雁，南北皆成行。
男儿白日间，变化未可量。
所希困辱地，剪拂成腾骧。
咋笔话肝肺，咏兹枯鱼章。
何由首西路，目断白云乡。','',''),('quantangshi-31484','洞庭驿楼雪夜宴集奉赠前湘州张员外','李羣玉','quantangshi','','卷32','昔与张湘州，闲登岳阳楼。
目穷衡巫表，兴尽荆吴秋。
掷笔落郢曲，巴人不能酬。
是时簪裾会，景物穷冥搜。
误忝玳筵秀，得陪文苑游。
几篇云楣上，风雨沈银钩。
□□□□□，□□□沧洲。
童儿待郭伋，竹马空迟留。
路指云汉津，谁能吟四愁。
银壶傲海雪，青管罗名讴。
贱子迹未安，谋身拙如鸠。
分随烟霞老，岂有风云求。
不逐万物化，但贻知己羞。
方穷立命说，战胜心悠悠。
不然蹲会稽，钩下三五牛。
所期波涛助，燀赫呈吞舟。','',''),('quantangshi-31485','送郑子宽弃官东游便归女几','李羣玉','quantangshi','','卷32','八月湖浸天，扬帆入秋色。
岷峨雪气来，寒涨潇湘碧。
子真冥鸿志，不逐笼下翼。
九女叠云屏，于焉恣栖息。
新诗山水思，静入陶谢格。
困醉松花春，追攀紫烟客。
相逢十年旧，嚬笑等欢慽。
一饭玉露蔬，中肠展堆积。
停食不尽意，倾意怅可惜。
云水一分飞，离忧洞庭侧。
回车三乡路，仙菊正堪摘。
寄谢杜兰香，何年别张硕。','',''),('quantangshi-31486','长沙九日登东楼观舞 一','李羣玉','quantangshi','','卷32','南国有佳人，轻盈绿腰舞。
华筵九秋暮，飞袂拂云雨。
翩如兰苕翠，婉如游龙举。
越艳罢前溪，吴姬停白紵。','',''),('quantangshi-31487','长沙九日登东楼观舞 二','李羣玉','quantangshi','','卷32','慢态不能穷，繁姿曲向终。
低回莲破浪，凌乱雪萦风。
坠珥时流盻，修裾欲遡空。
唯愁捉不住，飞去逐惊鸿。','',''),('quantangshi-31488','龙山人惠石廪方及团茶','李羣玉','quantangshi','','卷32','客有衡岳隐，遗余石廪茶。
自云凌烟露，采掇春山芽。
圭璧相压叠，积芳莫能加。
碾成黄金粉，轻嫩如松花。
红炉爨霜枝，越儿斟井华。
滩声起鱼眼，满鼎漂清霞。
凝澄坐晓灯，病眼如蒙纱。
一瓯拂昏寐，襟鬲开烦拏。
顾渚与方山，谁人留品差。
持瓯默吟味，摇膝空咨嗟。','',''),('quantangshi-31489','宿鸟远峡化台遇风雨','李羣玉','quantangshi','','卷32','孤鹤长松颠，独宿万岩雨。
龙湫在石脚，引袂时一取。
惊风折乔木，飞焰猎窗户。
半夜霹雳声，高斋有人语。','',''),('quantangshi-31490','岳阳春晚','李羣玉','quantangshi','','卷32','不觉春物老，块然湖上楼。
云沙鹧鸪思，风日沅湘愁。
去翼灭云梦，来帆指昭丘。
所嗟芳桂晚，寂寞对汀洲。','',''),('quantangshi-31491','汉阳春晚','李羣玉','quantangshi','','卷32','汉阳抱青山，飞楼暎湘渚。
白云蔽黄鹤，绿树藏鹦鹉。
凭高送春目，流恨伤千古。
遐思禰衡才，令人怨黄祖。','',''),('quantangshi-31492','将离澧浦置酒野屿奉怀沈正字昆弟三人联登高第','李羣玉','quantangshi','','卷32','春月三改兔，花枝成绿阴。
年光东流水，浩叹伤羁心。
酌桂烟屿晚，鴂鸣江草深。
良图一超忽，万恨空相寻。
上国刈翘楚，才微甘陆沈。
无灯假贫女，有泪沾牛衾。
衡岳三麒麟，各振黄钟音。
卿云被文彩，芳价摇词林。
夫子芸阁英，养鳞湘水浔。
晴沙踏兰菊，隐几当青岑。
明月洞庭上，悠扬挂离襟。
停觞一摇笔，聊寄生刍吟。','',''),('quantangshi-31493','湘中别成威闍黎','李羣玉','quantangshi','','卷32','至哉彼上人，冰霜凛规则。
游心杳何境，宴坐入冥默。
解空与密行，名腊信崇德。
吐论驾秋涛，龙宫发胸臆。
羣迷行大夜，浩浩一昏黑。
赤水千丈深，玄珠几人得。
持杯挹溟涨，至理安可测。
宁假喻芭蕉，真成嗅薝卜。
松声扫白月，霁夜来静域。
清梵罢法筵，天香满衣襋。
何方济了岸，秪仗慈航力。
愿与十八贤，同栖翠莲国。','',''),('quantangshi-31494','别尹炼师','李羣玉','quantangshi','','卷32','吾家五千言，至道悬日月。
若非函谷令，谁注流沙说。
多君飞升志，机悟独超拔。
学道玉笥山，烧丹白云穴。
南穷衡疑秀，采药历幽绝。
夜卧瀑布风，朝行碧岩雪。
洞宫四百日，玉籍恣探阅。
徒以菌蟪姿，缅攀修真诀。
尘笼罩浮世，遐思空飞越。
一罢棋酒欢，离情满寥泬。
愿骑紫盖鹤，早向黄金阙。
城市不可留，尘埃秽仙骨。','',''),('quantangshi-31495','饭僧','李羣玉','quantangshi','','卷32','好读天竺书，为寻无生理。
焚香面金偈，一室唯巾水。
交信方外言，二三空门子。
峻范照秋霜，高标揜僧史。
清晨洁蔬茗，延请良有以。
一落喧哗竞，栖心愿依止。
奔曦入半百，冉冉颓蒙汜。
云泛名利心，风轻是非齿。
向为情爱缚，未尽金仙旨。
以静制猨心，将虞瞥然起。
纶巾与藜杖，此意真已矣。
他日云壑间，来寻幽居士。','',''),('quantangshi-31496','赠回雪','李羣玉','quantangshi','','卷32','回雪舞萦盈，萦盈若回雪。
腰支一把玉，秪恐风吹折。
如能买一笑，满斗量明月。
安得金莲花，步步承罗袜。','',''),('quantangshi-31497','将之京国赠薛员外','李羣玉','quantangshi','','卷32','黄叶下空馆，寂寥寒雨愁。
平居岁华晏，络纬啼林幽。
节物凋壮志，咄嗟不能休。
空怀赵鞅叹，变化良无由。
所思杳何如，侧身仰皇州。
苍烟晦楚野，寒浪埋昭丘。
赵壹赋命薄，陈思多世忧。
翻然羡鱼鸟，畅矣山川游。
薛公龙泉姿，其气在斗牛。
南冠束秀发，白石劳悲讴。
圭衮照崇阅，文儒嗣箕裘。
旷然方寸地，霁海浮云舟。
澧浦一遗佩，郢南再悲秋。
叫阍路既阻，浩荡怀灵修。
莫奏武溪笛，且登仲宣楼。
亨通与否闭，物理相沈浮。
天子坐宣室，夔龙奉谟猷。
行当赐环去，岂作遗贤羞。','',''),('quantangshi-31498','送魏圭觐省','李羣玉','quantangshi','','卷32','木落楚色深，风高浪花白。
送君飞一叶，鸟逝入空碧。
猗欤白华秀，伤心倚门夕。
不知云涨遥，万里看咫尺。
萧萧青枫岸，去掩江山宅。
离觞有黄花，节物助凄戚。
潇湘入𤃩桂，一路萦水石。
烟萝拂行舟，玉濑锵枕席。
多君林泉趣，耽翫日成癖。
长啸凌清晖，襟情当雪涤。
登龙屈指内，飞誉甚籍籍。
未折月中枝，宁随宋都鶂。
曰余吞声地，举足伤瓦砾。
见尔一开颜，温明乃珠璧。
春风到云峤，把酒时相忆。
豆蔻花入船，鹧鸪啼送客。
扬天与瘴海，此去备沿历。
珍重春官英，加餐数刀帛。','',''),('quantangshi-31499','始忝四座奏状闻荐蒙恩授官旋进歌诗延英宣赐言怀纪事呈同馆诸公二十四韵','李羣玉','quantangshi','','卷32','两鬓有二毛，光阴流浪中。
形骸日土木，志气随云风。
冥默楚江畔，萧条林巷空。
幽鸟事翔翥，敛翼依蒿蓬。
一饭五放箸，愀然念途穷。
孟门在步武，所向何由通。
秖征大易言，物否不可终。
庶期白雪调，一奏惊凡聋。
昨忝丞相召，扬鞭指冥鸿。
姓名挂丹诏，文句飞天聪。
解薜龙凤署，怀铅兰桂丛。
声名仰闻见，烟汉陪高踪。
峨峨羣玉山，肃肃紫殿东。
神飙泛钟漏，佳气浮筠松。
自顾珉玞璞，何缘侣圭琮。
羣贤垂重价，省已增磨砻。
天子栖穆清，三台付夔龙。
九霄降雨露，万国望时雍。
巍巍致君期，勋华将比崇。
承天四柱石，嶷若窥衡嵩。
日见帝道升，谋猷垂景钟。
寰瀛纳寿域，翔泳皆冲融。
百神俨云亭，伫将告成功。
吾徒事文藻，骧首歌登封。','',''),('quantangshi-31500','穆天子','李羣玉','quantangshi','','卷32','穆满恣逸志，而轻天下君。
一朝得八骏，逐日西溟濆。
寂漠崦嵫幽，绝迹留空文。
三千閟宫艳，怨绝宁胜云。
或言帝轩辕，乘龙凌紫氛。
桥山葬弓劒，暧昧竟难分。
不思五弦琴，作歌咏南薰。
但听西王母，瑶池吟白云。','',''),('quantangshi-31501','广州重别方处士之封川 一','李羣玉','quantangshi','','卷32','楚国傲名客，九州徧芳声。
白衣谢簪绂，云卧重岩扃。
长波飞素舸，五月下南溟。
大笑相逢日，天边作酒星。','',''),('quantangshi-31502','广州重别方处士之封川 二','李羣玉','quantangshi','','卷32','七年一云雨，常恨辉容隔。
天末又分襟，离忧鬓堪白。
顾回凌潮檝，且着登山屐。
共期罗浮秋，与子醉海色。','',''),('quantangshi-31503','洞庭遇秋','李羣玉','quantangshi','','卷32','尘愁老来颜，久与江山隔。
逍遥澄湖上，洗眼见秋色。
凉波弄轻棹，湖月生远碧。
未减遥客情，西望杳何极。','',''),('quantangshi-31504','寄短书歌','李羣玉','quantangshi','','卷32','骨肉萍蓬各天末，十度附书九不达。
孤台冷眼无来人，楚水秦天莽空阔。
翔雁横秋过洞庭，西风落日浪峥嵘。
三年音信凝颦外，一曲哀歌白发生。','',''),('quantangshi-31505','王内人琵琶引','李羣玉','quantangshi','','卷32','檀槽一曲黄钟羽，细拨紫云金凤语。
万里胡天海塞秋，分明弹出风沙愁。
三千宫嫔推第一，敛黛倾鬟艳兰室。
嬴女停吹降浦箫，嫦娥净揜空波瑟。
翠幕横云蜡焰光，银龙吐酒菊花香。
皓魄翻。','',''),('quantangshi-31506','醒起独酌怀友','李羣玉','quantangshi','','卷32','西风静夜吹莲塘，芙蓉破红金粉香。
摘花把酒弄秋芳，吴云楚水愁茫茫。
美人此夕不入梦，独宿高楼明月凉。','',''),('quantangshi-31507','竞渡时在湖外偶为成章','李羣玉','quantangshi','','卷32','雷奔电逝三千儿，彩舟画檝射初晖。
喧江雷鼓鳞甲动，三十六龙衔浪飞。
灵均昔日投湘死，千古沈魂在湘水。
绿草斜烟日暮时，笛声幽远愁江鬼。','',''),('quantangshi-31508','新荷','李羣玉','quantangshi','','卷32','田田八九叶，散点绿池初。
嫩碧才平水，圆阴已蔽鱼。
浮萍遮不合，弱荇绕犹疎。
半在春波底，芳心卷未舒。','',''),('quantangshi-31509','初月二首 一','李羣玉','quantangshi','','卷32','滟滟流光浅，娟娟泛露轻。
云间龙爪落，帘上玉钩明。
桂树枝犹小，仙人影未成。
欲为千里别，倚幌独含情。','',''),('quantangshi-31510','初月二首 二','李羣玉','quantangshi','','卷32','凝颦立户前，细魄向娟娟。
破镜徒相问，刀头恐隔年。
轻轻摇远水，脉脉下春烟。','',''),('quantangshi-31511','石潴','李羣玉','quantangshi','','卷32','古岸陶为器，高林尽一焚。
焰红湘浦口，烟浊洞庭云。
迥野煤飞乱，遥空爆响闻。
地形穿凿势，恐到祝融坟。','',''),('quantangshi-31512','云安','李羣玉','quantangshi','','卷32','滩恶黄牛吼，城孤白帝秋。
水寒巴字急，歌迥竹枝愁。
树暗荆王馆，云昏蜀客舟。
瑶姬不可见，行雨在高丘。','',''),('quantangshi-31513','石头城','李羣玉','quantangshi','','卷32','伯业随流水，寒芜上古城。
长空横海色，断岸落潮声。
八极悲扶拄，五湖来止倾。
东南天子气，扫地入函京。','',''),('quantangshi-31514','湖阔','李羣玉','quantangshi','','卷32','楚色笼青草，秋风洗洞庭。
夕霏生水寺，初月尽云汀。
棹响来空阔，渔歌发杳冥。
欲浮阑下艇，一到斗牛星。','',''),('quantangshi-31515','失鹤','李羣玉','quantangshi','','卷32','瑶台烟雾外，一去不回心。
清海蓬壶远，秋风碧落深。
堕翎留片雪，雅操入孤琴。
岂是笼中物，云萝莫更寻。','',''),('quantangshi-31516','腊夜雪霁月彩交光开阁临轩竟睡不得命家仆吹笙数曲独引一壶奉寄江陵副使杜中丞','李羣玉','quantangshi','','卷32','月华临霁雪，皓彩射貂裘。
桂酒寒无醉，银笙冻不流。
怀哉梁苑客，思作剡溪游。
竟夕吟琼树，川途恨阻修。','',''),('quantangshi-31517','长沙陪裴大夫登北楼','李羣玉','quantangshi','','卷32','岩嶂随高步，琴尊奉胜游。
金风吹绿簟，湘水入朱楼。
朗抱云开月，高情鹤见秋。
登临多暇日，非为赋消忧。','',''),('quantangshi-31518','登蒲涧寺后二岩三首 一','李羣玉','quantangshi','','卷32','五仙骑五羊，何代降兹乡。
涧有尧年韭，山余禹日粮。
楼台笼海色，草树发天香。
浩啸波光里，浮溟兴甚长。','',''),('quantangshi-31519','登蒲涧寺后二岩三首 二','李羣玉','quantangshi','','卷32','行尽崎岖路，惊从汗漫游。
青天豁眼快，碧海醒心秋。
便欲寻河汉，因之犯斗牛。
九霄身自致，何必遇浮丘。','',''),('quantangshi-31520','登蒲涧寺后二岩三首 三','李羣玉','quantangshi','','卷32','南溟吞越绝，极望碧鸿蒙。
龙渡潮声里，雷喧雨气中。
赵佗丘壠灭，马援鼓鼙空。
遐想鱼鹏化，开襟九万风。','',''),('quantangshi-31521','早鸿','李羣玉','quantangshi','','卷32','木落波浪动，南飞闻夜鸿。
参差天汉雾，嘹唳月明风。
野水莲茎折，寒泥稻穗空。
无令一行侣，相失五湖中。','',''),('quantangshi-31522','旅泊','李羣玉','quantangshi','','卷32','摇落江天里，飘零倚客舟。
短篇才遣闷，小酿不供愁。
沙雨潮痕细，林风月影稠。
书空闲度日，深拥破貂裘。','',''),('quantangshi-31523','半醉','李羣玉','quantangshi','','卷32','处俗常如病，看花亦似秋。
若无时复酒，宁遣镇长愁。
渐觉身非我，都迷蝶与周。
何烦五色药，尊下即丹丘。','',''),('quantangshi-31524','昼寐','李羣玉','quantangshi','','卷32','筠桂晚萧疎，任人嘲宰予。
鸟惊林下梦，风展枕前书。
正作庄生蝶，谁知惠子鱼。
人间无乐事，直拟到华胥。','',''),('quantangshi-31525','晚莲','李羣玉','quantangshi','','卷32','露冷芳意尽，稀疎空碧荷。
残香随暮雨，枯蘂堕寒波。
楚客罢奇服，吴姬停棹歌。
涉江无可寄，幽恨竟如何。','',''),('quantangshi-31526','将之番禺留别湖南府幕','李羣玉','quantangshi','','卷32','本乏烟霞志，那随鸳鹭游。
一枝仍未定，数粒欲何求。
溟涨道途远，荆吴云雪愁。
会登梅岭翠，南翥入炎洲。','',''),('quantangshi-31527','宵民','李羣玉','quantangshi','','卷32','大雅无忧怨，宵民有爱憎。
鲁侯天不遇，臧氏尔何能。
惨惨心如虺，营营舌似蝇。
谁于销骨地，一鉴玉壶冰。','',''),('quantangshi-31528','吾道','李羣玉','quantangshi','','卷32','吾道成微哂，时情付绝言。
凤兮衰已尽，犬也吠何繁。
轻重忧衡曲，妍媸虑镜昏。
方忻耳目净，谁到翟公门。','',''),('quantangshi-31529','与三山人夜话','李羣玉','quantangshi','','卷32','静谈云鹤趣，高会两三贤。
酒思弹琴夜，茶芳向火天。
兔裘堆膝暖，鸠杖倚牀偏。
各厌池笼窄，相看意浩然。','',''),('quantangshi-31530','春寒','李羣玉','quantangshi','','卷32','拨火垂帘夕，将暄向冷天。
闷斟壶酒暖，愁听雨声眠。
处世心悠尔，干时思索然。
春光看已半，明日又藏烟。','',''),('quantangshi-31531','广江驿饯筵留别','李羣玉','quantangshi','','卷32','别筵欲尽秋，一醉海西楼。
夜雨寒潮水，孤灯万里舟。
酒飞鹦鹉重，歌送鹧鸪愁。
惆怅三年客，难期此处游。','',''),('quantangshi-31532','桑落洲','李羣玉','quantangshi','','卷32','九江寒露夕，微浪北风生。
浦屿渔人火，蒹葭凫雁声。
颓云晦庐岳，微鼓辨湓城。
远忆天边弟，曾从此路行。','',''),('quantangshi-31533','杜门','李羣玉','quantangshi','','卷32','且咏闲居赋，飞翔去未能。
春风花屿酒，秋雨竹溪灯。
世路变陵谷，时情验友朋。
达生书一卷，名利付春冰。','',''),('quantangshi-31534','池州封员外郡斋双鹤丹顶霜翎仙态浮旷罢政之日因呈此章','李羣玉','quantangshi','','卷32','潇洒二白鹤，对之高兴清。
寒溪侣云水，朱阁伴琴笙。
顾慕稻粱惠，超遥江海情。
应携帝乡去，仙阙看飞鸣。','',''),('quantangshi-31535','经费拾遗所居呈封员外','李羣玉','quantangshi','','卷32','云卧竟不起，少微空陨光。
唯应孔北海，为立郑公乡。
旧馆苔藓合，幽斋松菊荒。
空余书带草，日日上阶长。','',''),('quantangshi-31536','送秦炼师','李羣玉','quantangshi','','卷32','紫府静沈沈，松轩思别琴。
水流宁有意，云泛本无心。
锦洞桃花远，青山竹叶深。
不因时卖药，何路更相寻。','',''),('quantangshi-31537','湘阴县送迁客北归','李羣玉','quantangshi','','卷32','不须留薏苡，重遣世人疑。
瘴染面如蘖，愁熏头似丝。
黄梅住雨外，青草过湖时。
今日开汤网，冥飞亦未迟。','',''),('quantangshi-31538','九日陪崔大夫宴清河亭','李羣玉','quantangshi','','卷32','玉醴浮金菊，云亭敞玳筵。
晴山低画浦，斜雁远书天。
谢朓离都日，殷公出守年。
不知瑶水宴，谁和白云篇。','',''),('quantangshi-31539','送房处士闲游','李羣玉','quantangshi','','卷32','采药陶贞白，寻山许远游。
刀圭藏妙用，岩洞契冥搜。
花月三江水，琴尊一叶舟。
羡君随野鹤，长揖稻粱愁。','',''),('quantangshi-31540','赠花','李羣玉','quantangshi','','卷32','酒为看花酝，花须趁酒红。
莫令芳树晚，使我绿尊空。
金谷园无主，桃源路不通。
纵非乘露折，长短尽随风。','',''),('quantangshi-31541','洞庭风雨二首 一','李羣玉','quantangshi','','卷32','面南一片黑，俄起北风颠。
浪泼巴陵树，雷烧鹿角田。
鱼龙方簸荡，云雨正喧阗。
想赭君山日，秦皇怒赫然。','',''),('quantangshi-31542','洞庭风雨二首 二','李羣玉','quantangshi','','卷32','巨浸吞湘澧，西风忽怒号。
水将天共黑，云与浪争高。
羽化思乘鲤，山漂欲拚鳌。
阳乌犹曝翅，真恐湿蟠桃。','',''),('quantangshi-31543','临水蔷薇','李羣玉','quantangshi','','卷32','堪爱复堪伤，无情不久长。
浪摇千脸笑，风舞一丛芳。
似濯文君锦，如窥汉女妆。','',''),('quantangshi-31544','中秋维舟君山看月二首 一','李羣玉','quantangshi','','卷32','汗漫铺澄碧，朦胧吐玉盘。
雨师清滓秽，川后扫波澜。
气射繁星灭，光笼八表寒。
来从云涨迥，路上碧霄宽。','',''),('quantangshi-31545','中秋维舟君山看月二首 二','李羣玉','quantangshi','','卷32','熠耀游何处，蟾蜍食渐残。
棹翻银浪急，林映白虹攒。
练彩连河晓，冰晖压树干。
夜深高不动，天下仰头看。','',''),('quantangshi-31546','桂州经佳人故居琪树','李羣玉','quantangshi','','卷32','种树人何在，攀枝空叹嗟。
人无重见日，树有每年花。
满院雀声莫，半庭春景斜。
东风不知恨，徧地落余霞。','',''),('quantangshi-31547','赠元绂','李羣玉','quantangshi','','卷32','相逢在总角，与子即同心。
隐石那知玉，披沙始遇金。
兰秋香不死，松晚翠方深。
各保芳坚性，宁忧霜霰侵。','',''),('quantangshi-31548','中秋广江驿示韦益','李羣玉','quantangshi','','卷32','莫惜三更坐，难消万里情。
同看一片月，俱在广州城。
泪逐金波满，魂随夜鹊惊。
支颐乡思断，无语到鸡鸣。','',''),('quantangshi-31549','九日越台','李羣玉','quantangshi','','卷32','旭日高山上，秋天大海隅。
黄花罗粔籹，绛实簇茱萸。
病久欢情薄，乡遥客思孤。
无心同落帽，天际望归途。','',''),('quantangshi-31550','中秋越台看月','李羣玉','quantangshi','','卷32','海雨洗尘埃，月从空碧来。
水光笼草树，练影挂楼台。
皓曜迷鲸目，晶荧失蚌胎。
宵分凭槛望，应合见蓬莱。','',''),('quantangshi-31551','长沙开元寺昔与故长林许侍御题松竹联句','李羣玉','quantangshi','','卷32','墙阴数行字，怀旧惨伤情。
薜荔侵年月，莓苔压姓名。
逝川前后水，浮世短长生。
独立秋风暮，凝颦隔郢城。','',''),('quantangshi-31552','伤友','李羣玉','quantangshi','','卷32','玉棺来九天，凫舃掩穷泉。
芜没池塘屿，凄凉翰墨筵。
短期存大梦，旧好委浮烟。
我有幽兰曲，因君遂绝弦。','',''),('quantangshi-31553','法性寺六祖戒坛','李羣玉','quantangshi','','卷32','初地无阶级，余基数尺低。
天香开茉莉，梵树落菩提。
惊俗生真性，青莲出淤泥。
何人得心法，衣钵在曹溪。','',''),('quantangshi-31554','东湖二首 一','李羣玉','quantangshi','','卷32','晚景微雨歇，逍遥湖上亭。
波闲鱼弄饵，树静鸟遗翎。
性野难依俗，诗玄自入冥。
何繇遂潇洒，高枕对云汀。','',''),('quantangshi-31555','东湖二首 二','李羣玉','quantangshi','','卷32','雨气消残暑，苍苍月欲升。
林间风卷簟，栏下水摇灯。
迥野垂银镜，层峦挂玉绳。
重期浮小檝，来摘半湖菱。','',''),('quantangshi-31556','湖阁晓晴寄呈从翁二首 一','李羣玉','quantangshi','','卷32','岭日开寒雾，湖光荡霁华。
风乌摇迳柳，水蝶恋幽花。
蜀国地西极，吴门天一涯。
轻舟栏下去，点点入湘霞。','',''),('quantangshi-31557','湖阁晓晴寄呈从翁二首 二','李羣玉','quantangshi','','卷32','高秋凭远槛，万里看新晴。
重雾披天急，千云触石轻。
湖山四五点，湘雁两三声。
遥想潘园里，琴尊兴转清。','',''),('quantangshi-31558','同张明府游溇水亭','李羣玉','quantangshi','','卷32','草色绿溪晚，梅香生縠文。
云天敛余霁，水木笼微曛。
垂钓坐方屿，幽禽时一闻。
何当五柳下，酌醴吟庭筠。','',''),('quantangshi-31559','七月十五夜看月','李羣玉','quantangshi','','卷32','朦胧南溟月，汹涌出云涛。
下射长鲸眼，遥分玉兔毫。
势来星斗动，路越青冥高。
竟夕瞻光彩，昂头把白醪。','',''),('quantangshi-31560','北风','李羣玉','quantangshi','','卷32','病发干垂枕，临风强起梳。
蝶飞魂尚弱，蚁鬬体犹虚。
瘦骨呻吟后，羸容几杖初。
庭幽行药静，凉暑翠筠疎。','',''),('quantangshi-31561','游玉芝观','李羣玉','quantangshi','','卷32','寻仙向玉清，独倚雪初晴。
木落寒郊迥，烟开叠嶂明。
片云盘鹤影，孤磬杂松声。
且共探玄理，归途月未生。','',''),('quantangshi-31562','中秋夜南楼寄友人','李羣玉','quantangshi','','卷32','海月出银浪，湖光射高楼。
朗吟无渌酒，贱价买清秋。
气冷鱼龙寂，轮高星汉幽。
他乡此夜客，对景饯多愁。','',''),('quantangshi-31563','三月五日陪裴大夫泛长沙东湖','李羣玉','quantangshi','','卷32','上巳余风景，芳辰集远坰。
彩舟浮滉荡，绣毂下娉婷。
林榭回葱蒨，笙歌转杳冥。
湖光迷翡翠，草色醉蜻蜓。
鸟弄桐花日，鱼翻谷雨萍。
从今留胜会，谁肯画兰亭。','',''),('quantangshi-31564','龟','李羣玉','quantangshi','','卷32','静养千年寿，重泉自隐居。
不应随跛鼈，宁肯滞凡鱼。
灵腹唯玄露，芳巢必翠蕖。
扬花输蚌蛤，犇月恨蟾蜍。
曳尾辞泥后，支牀得水初。
冠山期不小，铸印事宁虚。
有志酬毛宝，无心畏豫且。
他时清洛汭，会荐帝尧书。','',''),('quantangshi-31565','长沙春望寄涔阳故人','李羣玉','quantangshi','','卷32','清明别后雨晴时，极浦空颦一望眉。
湖畔春山烟黯黯，云中远树黑离离。
依微水戍闻疎鼓，掩映河桥见酒旗。
风暖草长愁自醉，行吟无处寄相思。','',''),('quantangshi-31566','金塘路中','李羣玉','quantangshi','','卷32','山连楚越复吴秦，蓬梗何年是住身。
黄叶黄花古城路，秋风秋雨别家人。
冰霜想度商于冻，桂玉愁居帝里贫。
十口系心抛不得，每回回首即长颦。','',''),('quantangshi-31567','自遣','李羣玉','quantangshi','','卷32','翻覆升沈百岁中，前途一半已成空。
浮生暂寄梦中梦，世事如闻风里风。
修竹万竿资阒寂，古书千卷要穷通。
一壶浊酒暄和景，谁会陶然失马翁。','',''),('quantangshi-31568','送于少监自广州还紫逻','李羣玉','quantangshi','','卷32','鸣臯山水似麻源，谢监东还忆故园。
海峤烟霞轻逸翰，洛川花木待回轩。
宦情薄去诗千首，世事闲来酒一尊。
明日中书见颜范，始应通籍入金门。','',''),('quantangshi-31569','石门韦明府为致东阳潭石鲫鲙','李羣玉','quantangshi','','卷32','锦鳞衔饵出清涟，暖日江亭动鲙筵。
叠雪乱飞消箸底，散丝繁洒拂刀前。
太湖浪说朱衣鲋，汉浦休夸缩项鳊。
隽味品流知第一，更劳霜橘助芳鲜。','',''),('quantangshi-31570','规公业在净名得甚深义仆近获顾长康月宫真影对戴安道所画文殊走笔此篇以屈瞻礼','李羣玉','quantangshi','','卷32','五浊之世尘冥冥，达观栖心于此经。
但用须弥藏芥子，安知牛迹笑东溟。
生公吐辩真无敌，顾氏传神实有灵。
今日净开方丈室，一飞白足到茅亭。','',''),('quantangshi-31571','玉真观','李羣玉','quantangshi','','卷32','高情帝女慕乘鸾，绀发初簪玉叶冠。
秋月无云生碧落，素蕖寒露出清澜。
层城烟雾将归远，浮世尘埃久住难。
一自箫声飞去后，洞宫深掩碧瑶坛。','',''),('quantangshi-31572','辱绵州于中丞书信','李羣玉','quantangshi','','卷32','一缄垂露到云林，中有孙阳念骥心。
万木自凋山不动，百川皆旱海长深。
风标想见瑶台鹤，诗韵如闻渌水琴。
他日纵陪池上酌，已应难到暝猨吟。','',''),('quantangshi-31573','送崔使君萧山祷雨甘泽遽降','李羣玉','quantangshi','','卷32','谢公一拜敬亭祠，五马旋归下散丝。
不假土龙呈夭矫，自然石燕起参差。
预听禾稼如云语，应有空蒙似雾时。
已向为霖报消息，颍川征诏是前期。','',''),('quantangshi-31574','重经巴丘追感','李羣玉','quantangshi','','卷32','昔年高接李膺欢，日泛仙舟醉碧澜。
诗句乱随青草发，酒肠俱逐洞庭宽。
浮生聚散云相似，往事微茫梦一般。
今日片帆城下去，秋风回首泪阑干。','',''),('quantangshi-31575','湘阴江亭却寄友人','李羣玉','quantangshi','','卷32','湘岸初晴淑景迟，风光正是客愁时。
幽花暮落骚人浦，芳草春深帝子祠。
往事隔年如过梦，旧游回首谩劳思。
烟波自此扁舟去，小酌文园杳未期。','',''),('quantangshi-31576','哭郴州王使君','李羣玉','quantangshi','','卷32','银章朱绂照云骢，六换鱼书惠化崇。
瑶树忽倾沧海里，醉乡翻在夜台中。
东山妓逐飞花散，北海尊随逝水空。
曾是绮罗筵上客，一来长恸向春风。','',''),('quantangshi-31577','九日巴丘杨公台上宴集','李羣玉','quantangshi','','卷32','凄凄霜日上高台，水国秋深客思哀。
万叠银山寒浪起，一行斜字早鸿来。
谁家捣练孤城暮，何处题衣远信回？
江汉路长身不定，菊花三笑旅萍开。','',''),('quantangshi-31578','奉和张舍人送秦炼师归岑公山','李羣玉','quantangshi','','卷32','仙翁归卧翠微岑，一夜西风月峡深。
松迳定知芳草合，玉书应念素尘侵。
闲云不系东西影，野鹤宁知去住心。
兰浦苍苍春欲暮，落花流水怨离琴。','',''),('quantangshi-31579','送陶少府赴选','李羣玉','quantangshi','','卷32','陶君官兴本萧疎，长傍青山碧水居。
久向三茅穷艺术，仍传五柳旧琴书。
迹同飞鸟栖高树，心似闲云在太虚。
自是葛洪求药价，不关梅福恋簪裾。','',''),('quantangshi-31580','寄张祜','李羣玉','quantangshi','','卷32','越水吴山任兴行，五湖云月挂高情。
不游都邑称平子，只向江东作步兵。
昔岁芳声到童稚，老来佳句徧公卿。
如君气力波澜地，留取阴何沈范名。','',''),('quantangshi-31581','寄长沙许侍御','李羣玉','quantangshi','','卷32','三年文会许追随，和徧南朝杂体诗。
未把彩毫还郭璞，乞留残锦与丘迟。
竹斋琴酒欢成梦，水寺烟霞赏对谁。
今日秋风满湘浦，秪应搔首咏琼枝。','',''),('quantangshi-31582','望月怀友','李羣玉','quantangshi','','卷32','浮云卷尽看朣胧，直出沧溟上碧空。
盈手水光寒不湿，流天素彩静无风。
酒花荡漾金尊里，棹影飘颻玉浪中。
川路正长难可越，美人千里思何穷。','',''),('quantangshi-31583','和吴中丞悼笙妓','李羣玉','quantangshi','','卷32','丽质仙姿烟逐风，凤皇声断吹台空。
多情草色怨还绿，无主杏花春自红。
堕珥尚存芳树下，余香渐减玉堂中。
唯应去抱云和管，从此长归阿母宫。','',''),('quantangshi-31584','薛侍御处乞鞾','李羣玉','quantangshi','','卷32','越客南来夸桂麖，良工用意巧缝成。
看时共说茱萸皱，着处嫌无鸜鹆鸣。
百里奚身悲甚似，五羊皮价敢全轻。
日于文苑陪高步，赢得芳尘接武名。','',''),('quantangshi-31585','九子坡闻鹧鸪','李羣玉','quantangshi','','卷32','落照苍茫秋草明，鹧鸪啼处远人行。
正穿诘曲崎岖路，更听钩輈格磔声。
曾泊桂江深岸雨，亦于梅岭阻归程。
此时为尔肠千断，乞放今宵白发生。','',''),('quantangshi-31586','凉公从叔春祭广利王庙','李羣玉','quantangshi','','卷32','龙骧伐鼓下长川，直济云涛古庙前。
海客敛威惊火斾，天吴收浪避楼船。
阴灵向作南溟主，祀典高齐五岳肩。
从此华夷封域静，潜熏玉烛奉尧年。','',''),('quantangshi-31587','长沙紫极宫雨夜愁坐','李羣玉','quantangshi','','卷32','独坐高斋寒拥衾，洞宫台殿窅沈沈。
春灯含思静相伴，夜雨滴愁更向深。
穷达未知他日事，是非皆到此时心。
羁栖摧剪平生志，抱膝时为梁甫吟。','',''),('quantangshi-31588','送人隐居','李羣玉','quantangshi','','卷32','碁局茅亭幽涧滨，竹寒江静远无人。
邨梅尚敛风前笑，沙草初偷雪后春。
鹏鷃喻中消日月，沧浪歌里放心神。
平生自有烟霞志，久欲抛身狎隐沦。','',''),('quantangshi-31589','江楼闲望怀关中亲故','李羣玉','quantangshi','','卷32','摇落江天欲尽秋，远鸿高送一行愁。
音书寂绝秦云外，身世蹉跎楚水头。
年貌暗随黄叶去，时情深付碧波流。
风凄日冷江湖晚，驻目寒空独倚楼。','',''),('quantangshi-31590','请告南归留别同馆','李羣玉','quantangshi','','卷32','一点灯前独坐身，西风初动帝城砧。
不胜庾信乡关思，遂作陶潜归去吟。
书合乍离情黯黯，彤庭回望肃沈沈。
应怜一别瀛洲侣，万里单飞云外深。','',''),('quantangshi-31591','仙明洲口号','李羣玉','quantangshi','','卷32','长爱沙洲水竹居，暮江春树绿阴初。
浪翻新月金波浅，风损轻云玉叶疎。
半浦夜歌闻荡桨，一星幽火照叉鱼。
二年此处寻佳句，景物常输楚客书。','',''),('quantangshi-31592','送萧十二校书赴郢州婚姻','李羣玉','quantangshi','','卷32','蓬莱才子即萧郎，彩服青书卜凤皇。
玉佩定催红粉色，锦衾应惹翠云香。
马穿暮雨荆山远，人宿寒灯郢梦长。
领取和鸣好风景，石城花月送归乡。','',''),('quantangshi-31593','送隐者归罗浮','李羣玉','quantangshi','','卷32','春山杳杳日迟迟，路入云峰白犬随。
两卷素书留贳酒，一柯樵斧坐看棋。
蓬莱道士飞霞履，清远仙人寄好诗。
自此尘寰音信断，山川风月永相思。','',''),('quantangshi-31594','献王中丞','李羣玉','quantangshi','','卷32','登仙望绝李膺舟，从此青蝇点遂稠。
半夜劒吹牛斗动，二年门掩雀罗愁。
张仪会展平生舌，韩信那慙跨下羞。
他日图勋画麟阁，定呈肝胆始应休。','',''),('quantangshi-31595','哭小女痴儿','李羣玉','quantangshi','','卷32','平生未省梦熊罴，稚女如花坠晓枝。
条蔓纵横输葛藟，子孙蕃育羡螽斯。
方同王衍钟情切，犹念商瞿有庆迟。
负尔五年恩爱泪，眼中惟有涸泉知。','',''),('quantangshi-31596','醉后赠冯姬','李羣玉','quantangshi','','卷32','黄昏歌舞促琼筵，银烛台西见小莲。
二寸横波回慢水，一双纤手语香弦。
桂形浅拂梁家黛，瓜字初分碧玉年。
愿托襄王云雨梦，阳台今夜降神仙。','',''),('quantangshi-31597','广州陪凉公从叔越台宴集','李羣玉','quantangshi','','卷32','一迳松梢踏石梯，步穷身在白云西。
日衔赤浪金车没，天拂沧波翠幕低。
高鸟散飞惊大斾，长风万里卷秋鼙。
玉钩挂海笙歌合，珠履三千半似泥。','',''),('quantangshi-31598','留别马使君','李羣玉','quantangshi','','卷32','俱来海上叹烟波，君佩银鱼我触罗。
蜀国才微甘放荡，专城年少岂蹉跎。
应怜旅梦千重思，共怆离心一曲歌。
唯有管弦知客意，分明吹出感恩多。','',''),('quantangshi-31599','将欲南行陪崔八宴海榴亭','李羣玉','quantangshi','','卷32','朝宴华堂暮未休，几人偏得谢公留。
风传鼓角霜侵戟，云卷笙歌月上楼。
宾馆尽开徐孺榻，客帆空恋李膺舟。
谩夸书劒无归处，水远山长步步愁。','',''),('quantangshi-31600','湖寺清明夜遣怀','李羣玉','quantangshi','','卷32','柳暗花香愁不眠，独凭危槛思凄然。
野云将雨渡微月，沙鸟带声飞远天。
久向饥寒抛弟妹，每因时节忆团圆。','',''),('quantangshi-31601','九日','李羣玉','quantangshi','','卷32','年年羞见菊花开，十度悲秋上楚台。
半岭残阳衔树落，一行斜雁向人来。
行云永绝襄王梦，野水偏伤宋玉怀。
丝管阑珊归客尽，黄昏独自咏诗回。','',''),('quantangshi-31602','同郑相并歌姬小饮戏赠','李羣玉','quantangshi','','卷32','裙拖六幅湘江水，鬓耸巫山一段云。
风格只应天上有，歌声岂合世间闻。
胸前瑞雪灯斜照，眼底桃花酒半醺。
不是相如怜赋客，争敎容易见文君。','',''),('quantangshi-31603','秣陵怀古','李羣玉','quantangshi','','卷32','野花黄叶旧吴宫，六代豪华烛散风。
龙虎势衰佳气歇，凤皇名在故台空。
市朝迁变秋芜绿，坟冢高低落照红。
霸业鼎图人去尽，独来惆怅水云中。','',''),('quantangshi-31604','黄陵庙','李羣玉','quantangshi','','卷32','小姑洲北浦云边，二女容华自俨然。
野庙向江春寂寂，古碑无字草芊芊。
风回日暮吹芳芷，月落山深哭杜鹃。
犹似含颦望巡狩，九疑愁断隔湘川。','',''),('quantangshi-31605','送唐侍御福建省兄','李羣玉','quantangshi','','卷32','桂枝攀尽贾家才，霄汉春风棣萼开。
世掌纶言传大笔，官分鸿序压霜台。
闽山翠卉迎飞斾，越水清纹散落梅。
到日池塘春草绿，谢公应梦惠连来。','',''),('quantangshi-31606','送秦炼师归岑公山','李羣玉','quantangshi','','卷32','紫泥飞诏下金銮，列象分明世仰观。
北省谏书藏旧草，南宫郎署握新兰。
春归凤沼恩波暖，晓入鸳行瑞气寒。
偏是此生栖息者，满衣零泪一时干。','',''),('quantangshi-31607','浔阳观水','李羣玉','quantangshi','','卷32','朝宗汉水接阳台，唅呀填坑吼作雷。
莫见九江平稳去，还从三峡嶮巇来。
南经梦泽宽浮日，西出岷山劣泛杯。
直至沧溟涵贮尽，深沈不动浸昭回。','',''),('quantangshi-31608','谪仙吟赠赵道士','李羣玉','quantangshi','','卷32','汗漫东游黄鹤雏，缙云仙子住清都。
三元麟凤推高座，六甲风雷閟小壶。
日月暗资灵寿药，山河直拟化生符。
若为失意居蓬岛，鳌足尘飞桑树枯。','',''),('quantangshi-31609','长沙陪裴大夫夜宴','李羣玉','quantangshi','','卷32','东山夜宴酒成河，银烛荧煌照绮罗。
四面雨声笼笑语，满堂香气泛笙歌。
泠泠玉漏初三滴，滟滟金觞已半酡。
共向柏台窥雅量，澄陂万顷见天和。','',''),('quantangshi-31610','宝剑','李羣玉','quantangshi','','卷32','雷焕丰城掘剑池，年深事远迹依稀。
泥沙难掩冲天气，风雨终思发匣时。
夜电尚摇池底影，秋莲空吐锷边辉。
自从星坼中台后，化作双龙去不归。','',''),('quantangshi-31611','人日梅花病中作','李羣玉','quantangshi','','卷32','去年今日湘南寺，独把寒梅愁断肠。
今年此日江边宅，卧见琼枝低压墙。
半落半开临野岸，团情团思醉韶光。
玉鳞寂寂飞斜月，素艳亭亭对夕阳。
已被儿童苦攀折，更遭风雨损馨香。
洛阳桃李渐撩乱，回首行宫春景长。','',''),('quantangshi-31612','静夜相思','李羣玉','quantangshi','','卷32','山空天籁寂，水榭延轻凉。
浪定一浦月，藕花闲自香。','',''),('quantangshi-31613','桂州经佳人故居','李羣玉','quantangshi','','卷32','桂水依旧绿，佳人本不还。
秖应随暮雨，飞入九疑山。','',''),('quantangshi-31614','放鱼','李羣玉','quantangshi','','卷32','早觅为龙去，江湖莫漫游。
须知香饵下，触口是銛钩。','',''),('quantangshi-31615','莲叶','李羣玉','quantangshi','','卷32','根是泥中玉，心承露下珠。
在君塘下种，埋没任春蒲。','',''),('quantangshi-31616','客愁二首 一','李羣玉','quantangshi','','卷32','客愁看柳色，日日逐春深。
荡漾春风起，谁知历乱心。','',''),('quantangshi-31617','客愁二首 二','李羣玉','quantangshi','','卷32','客愁看柳色，日日逐春长。
凭送湘流水，绵绵入帝乡。','',''),('quantangshi-31618','洞庭干二首 一','李羣玉','quantangshi','','卷32','借问蓬莱水，谁逢清浅年。
伤心云梦泽，岁岁作桑田。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-31619','洞庭干二首 二','李羣玉','quantangshi','','卷32','朱宫紫贝阙，一旦作沙洲。
八月还平在，鱼虾不用愁。','',''),('quantangshi-31620','病起别主人','李羣玉','quantangshi','','卷32','益愧千金少，情将一饭殊。
恨无泉客泪，尽泣感恩珠。','',''),('quantangshi-31621','火炉前坐','李羣玉','quantangshi','','卷32','孤灯照不寐，风雨满西林。
多少关心事，书灰到夜深。','',''),('quantangshi-31622','古词','李羣玉','quantangshi','','卷32','一合相思泪，临江洒素秋。
碧波如会意，却与向西流。','',''),('quantangshi-31623','嘲卖药翁','李羣玉','quantangshi','','卷32','斸尽春山土，辛勤卖药翁。
莫抛破笠子，留作败天公。','',''),('quantangshi-31624','伤小女痴儿','李羣玉','quantangshi','','卷32','哭尔春日短，支颐长叹嗟。
不如半死树，犹吐一枝花。','',''),('quantangshi-31625','青鷁','李羣玉','quantangshi','','卷32','独立蒹葭雨，低飞浦屿风。
须知毛色下，莫入鹭鸶丛。','',''),('quantangshi-31626','池塘晚景','李羣玉','quantangshi','','卷32','风荷珠露倾，惊起睡䴔䴖。
月落池塘静，金刀剪一声。','',''),('quantangshi-31627','投从叔','李羣玉','quantangshi','','卷32','可惜出羣蹄，毛焦久卧泥。
孙阳如不顾，骐骥向谁嘶。','',''),('quantangshi-31628','恼自澄','李羣玉','quantangshi','','卷32','常闻天女会，玉指散天花。
莫遣春风里，红芳点袈裟。','',''),('quantangshi-31629','读贾谊传','李羣玉','quantangshi','','卷32','卑湿长沙地，空抛出世才。
已齐生死理，服鸟莫为灾。','',''),('quantangshi-31630','寄人','李羣玉','quantangshi','','卷32','寄语双莲子，须知用意深。
莫嫌一点苦，便拟弃莲心。','',''),('quantangshi-31631','寄韦秀才','李羣玉','quantangshi','','卷32','荆台兰渚客，寥落共含情。
空馆相思夜，孤灯照雨声。','',''),('quantangshi-31632','春日寄友','李羣玉','quantangshi','','卷32','晴气熏樱蘂，丰蒙雪满林。
请君三斗酒，醉卧白罗岑。','',''),('quantangshi-31633','题竹','李羣玉','quantangshi','','卷32','一顷含秋绿，森风十万竿。
气吹朱夏转，声扫碧霄寒。','',''),('quantangshi-31634','怀初公','李羣玉','quantangshi','','卷32','不见休上人，空伤碧云思。
何处开宝书，秋风海光寺。','',''),('quantangshi-31635','龙安寺佳人阿最歌八首 一','李羣玉','quantangshi','','卷32','团团明月面，冉冉柳枝腰。
未入鸳鸯被，心长似火烧。','',''),('quantangshi-31636','龙安寺佳人阿最歌八首 二','李羣玉','quantangshi','','卷32','见面知何益，闻名忆转深。
拳挛荷叶子，未得展莲心。','',''),('quantangshi-31637','龙安寺佳人阿最歌八首 三','李羣玉','quantangshi','','卷32','欲摘不得摘，如看波上花。
若敎亲玉树，情愿作蒹葭。','',''),('quantangshi-31638','龙安寺佳人阿最歌八首 四','李羣玉','quantangshi','','卷32','门路穿茶焙，房门映竹烟。
会须随鹿女，乞火到窗前。','',''),('quantangshi-31639','龙安寺佳人阿最歌八首 五','李羣玉','quantangshi','','卷32','不是求心印，都缘爱绿珠。
何须同泰寺，然后始为奴。','',''),('quantangshi-31640','龙安寺佳人阿最歌八首 六','李羣玉','quantangshi','','卷32','既为金界客，任改净人名。
愿扫琉璃地，烧香过一生。','',''),('quantangshi-31641','龙安寺佳人阿最歌八首 七','李羣玉','quantangshi','','卷32','素腕撩金索，轻红约翠纱。
不如栏下水，终日见桃花。','',''),('quantangshi-31642','龙安寺佳人阿最歌八首 八','李羣玉','quantangshi','','卷32','第一龙宫女，相怜是阿谁。
好鱼输獭尽，白鹭镇长饥。','',''),('quantangshi-31643','野鸭','李羣玉','quantangshi','','卷32','鸂鶒借毛衣，喧呼鹰隼稀。
云披菱藻地，任汝作羣飞。','',''),('quantangshi-31644','题二妃庙','李羣玉','quantangshi','','卷32','黄陵庙前春已空，子规啼血滴松风。
不知精爽归何处，疑是行云秋色中。','',''),('quantangshi-31645','寄友二首 一','李羣玉','quantangshi','','卷32','野水晴山雪后时，独行邨落更相思。
无因一向溪头醉，处处寒梅映酒旗。','',''),('quantangshi-31646','寄友二首 二','李羣玉','quantangshi','','卷32','花落轻寒酒熟迟，醉眠不及落花期。
愁人相忆春山暮，烟树苍苍播谷时。','',''),('quantangshi-31647','桃源','李羣玉','quantangshi','','卷32','我到瞿真上升处，山川四望使人愁。
紫云白鹤去不返，唯有桃花溪水流。','',''),('quantangshi-31648','题王侍御宅','李羣玉','quantangshi','','卷32','门向沧江碧岫开，地多鸥鹭少尘埃。
绿阴十里滩声里，闲自王家看竹来。','',''),('quantangshi-31649','闻湘南从叔朝觐','李羣玉','quantangshi','','卷32','长沙地窄却回时，舟檝骎骎向凤池。
为报湘川神女道，莫敎云雨湿旌旗。','',''),('quantangshi-31650','汉阳太白楼','李羣玉','quantangshi','','卷32','江上层楼翠霭间，满帘春水满窗山。
青枫绿草将愁去，远入吴云暝不还。','',''),('quantangshi-31651','送客','李羣玉','quantangshi','','卷32','沅水罗文海燕回，柳条牵恨到荆台。
