相约杏花坛上去，画栏红紫鬬樗蒲。','',''),('quantangshi-31711','古意','賈島','quantangshi','','卷32','碌碌复碌碌，百年双转毂。
志士终夜心，良马白日足。
俱为不等闲，谁是知音目。
眼中两行泪，曾吊三献玉。','',''),('quantangshi-31712','望山','賈島','quantangshi','','卷32','南山三十里，不见逾一旬。
冒雨时立望，望之如朋亲。
虬龙一掬波，洗荡千万春。
日日雨不断，愁杀望山人。
天事不可长，劲风来如奔。
阴霪一以扫，浩翠写国门。
长安百万家，家家张屏新。
谁家最好山，我愿为其邻。','',''),('quantangshi-31713','北岳庙','賈島','quantangshi','','卷32','天地有五岳，恒岳居其北。
岩峦叠万重，诡怪浩难测。
人来不敢入，祠宇白日黑。
有时起霖雨，一洒天地德。
神兮安在哉，永康我王国。','',''),('quantangshi-31714','朝饥','賈島','quantangshi','','卷32','市中有樵山，此舍朝无烟。
井底有甘泉，釜中乃空然。
我要见白日，雪来塞青天。
坐闻西牀琴，冻折两三弦。
饥莫诣他门，古人有拙言。','',''),('quantangshi-31715','哭卢仝','賈島','quantangshi','','卷32','贤人无官死，不亲者亦悲。
空令古鬼哭，更得新邻比。
平生四十年，惟着白布衣。
天子未辟召，地府谁来追。
长安有交友，托孤遽弃移。
冢侧志石短，文字行参差。
无钱买松栽，自生蒿草枝。
在日赠我文，泪流把读时。
从兹加敬重，深藏恐失遗。','',''),('quantangshi-31716','剑客','賈島','quantangshi','','卷32','十年磨一剑，霜刃未曾试。
今日把似君，谁为不平事。','',''),('quantangshi-31717','口号','賈島','quantangshi','','卷32','中夜忽自起，汲此百尺泉。
林木含白露，星斗在青天。','',''),('quantangshi-31718','寄远','賈島','quantangshi','','卷32','别肠多郁纡，岂能肥肌肤。
始知相结密，不及相结疎。
疎别恨应少，密离恨难祛。
门前南流水，中有北飞鱼。
鱼飞向北海，可以寄远书。
不惜寄远书，故人今在无。
况此数尺身，阻彼万里途。
自非日月光，难以知子躯。','',''),('quantangshi-31719','斋中','賈島','quantangshi','','卷32','眈静非谬为，本性实疎索。
斋中一就枕，不觉白日落。
低扉碍轩辔，寡德谢接诺。
丛菊在墙阴，秋穷未开萼。
所餐类病马，动影似移岳。
欲驻迫逃衰，岂殊乱绠缚。
已见饱时雨，应丰蔬与药。','',''),('quantangshi-31720','感秋','賈島','quantangshi','','卷32','商气飒已来，岁华又虚掷。
朝云藏奇峰，暮雨洒疎滴。
几蜩嘿凉叶，数蛩思阴壁。
落日空馆中，归心远山碧。
昔人多秋感，今人何异昔。
四序驰百年，玄发坐成白。
喧喧徇声利，扰扰同辙迹。
傥无世上怀，去偃松下石。','',''),('quantangshi-31721','翫月','賈島','quantangshi','','卷32','寒月破东北，贾生立西南。
西南立倚何，立倚青青杉。
近月有数星，星名未详谙。
但爱杉倚月，我倚杉为三。
月乃不上杉，上杉难相参。
眙𥈭子细视，睛瞳桂枝劖。
目常有热疾，久视无烦炎。
以手扪衣裳，零露已濡霑。
久立双足冻，时向股䏶淹。
立久病足折，兀然黐胶黏。
他人应已睡，转喜此景恬。
此景亦胡及，而我苦淫耽。
无异市井人，见金不知廉。
不知此夜中，几人同无厌。
待得上顶看，未拟归枕函。
强步望寝斋，步步情不堪。
步到竹丛西，东望如隔帘。
却坐竹丛外，清思刮幽潜。
量知爱月人，身愿化为蟾。','',''),('quantangshi-31722','辞二知己','賈島','quantangshi','','卷32','一双千岁鹤，立别孤翔鸿。
波岛忽已暮，海雨寒蒙蒙。
离人闻美弹，亦与哀弹同。
况兹切切弄，绕彼行行躬。
云飞北岳碧，火息西山红。
何以代远诚，折芳腊雪中。','',''),('quantangshi-31723','义雀行和朱评事','賈島','quantangshi','','卷32','玄鸟雄雌俱，春雷惊蛰余。
口衔黄河泥，空即翔天隅。
一夕皆莫归，哓哓遗众雏。
双雀抱仁义，哺食劳劬劬。
雏既逦迤飞，云间声相呼。
燕雀虽微类，感愧诚不殊。
禽贤难自彰，幸得主人书。','',''),('quantangshi-31724','宿悬泉驿','賈島','quantangshi','','卷32','晓行沥水楼，暮到悬泉驿。
林月值云遮，山灯照愁寂。','',''),('quantangshi-31725','辩士','賈島','quantangshi','','卷32','辩士多毁訾，不闻谈己非。
猛虎恣杀暴，未尝啮妻儿。
此理天所感，所感当问谁。
求食饲雏禽，吐出美言词。
善哉君子人，扬光掩瑕玼。','',''),('quantangshi-31726','不欺','賈島','quantangshi','','卷32','上不欺星辰，下不欺鬼神。
知心两如此，然后何所陈。
食鱼味在鲜，食蓼味在辛。
掘井须到流，结交须到头。
此语诚不谬，敌君三万秋。','',''),('quantangshi-31727','绝句','賈島','quantangshi','','卷32','海底有明月，圆于天上轮。
得之一寸光，可买千里春。','',''),('quantangshi-31728','寓兴','賈島','quantangshi','','卷32','莫居暗室中，开目闭目同。
莫趋碧霄路，容飞不容步。
暗室未可居，碧霄未可趋。
劝君跨仙鹤，日下云为衢。','',''),('quantangshi-31729','游仙','賈島','quantangshi','','卷32','借得孤鹤骑，高近金乌飞。
掬河洗老貌，照月生光辉。
天中鹤路直，天尽鹤一息。
归来不骑鹤，身自有羽翼。
若人无仙骨，芝术徒烦食。','',''),('quantangshi-31730','枕上吟','賈島','quantangshi','','卷32','夜长忆白日，枕上吟千诗。
何当苦寒气，忽被东风吹。
冰开鱼龙别，天波殊路岐。','',''),('quantangshi-31731','双鱼谣','賈島','quantangshi','','卷32','天河堕双鲂，飞我庭中央。
掌握尺余雪，劈开肠有璜。
见令馋舌短，烹遶邻舍香。
一得古诗字，与玉含异藏。','',''),('quantangshi-31732','易水怀古','賈島','quantangshi','','卷32','荆卿重虚死，节烈书前史。
我叹方寸心，谁论一时事。
至今易水桥，寒风兮萧萧。
易水流得尽，荆卿名不消。','',''),('quantangshi-31733','早起','賈島','quantangshi','','卷32','北客入西京，北雁再离北。
秋寝独前兴，天梭星落织。
耽翫余恬爽，顾盼轻疴力。
旅途少颜尽，明镜劝仙食。
出门路纵横，张家路最直。
昨夜梦见书，张家厅上壁。','',''),('quantangshi-31734','客喜','賈島','quantangshi','','卷32','客喜非实喜，客悲非实悲。
百回信到家，未当身一归。
未归长嗟愁，嗟愁填中怀。
开口吐愁声，还却入耳来。
常恐泪滴多，自损两目辉。
鬓边虽有丝，不堪织寒衣。','',''),('quantangshi-31735','延寿里精舍寓居','賈島','quantangshi','','卷32','旅托避华馆，荒楼遂愚慵。
短庭无繁植，珍果春亦浓。
侧庐废扃枢，纤魄时卧逢。
耳目乃鄽井，肺肝即岩峰。
汲泉饮酌余，见我闲静容。
霜蹊犹舒英，寒蝶断来踪。
双履与谁逐，一寻青瘦筇。','',''),('quantangshi-31736','赠智朗禅师','賈島','quantangshi','','卷32','上人分明见，玉兔潭底没。
上人光惨貌，古来恨峭发。
涕辞孔颜庙，笑访禅寂室。
步随青山影，坐学白塔骨。
解听无弄琴，不礼有身佛。
欲问师何之，忽与我相别。
率赋赠远言，言慙非子曰。','',''),('quantangshi-31737','送沈秀才下第东归','賈島','quantangshi','','卷32','曲言恶者谁，悦耳如弹丝。
直言好者谁，刺耳如长锥。
沈生才俊秀，心肠无邪欺。
君子忌苟合，择交如求师。
毁出疾夫口，腾入礼部闱。
下第子不耻，遗才人耻之。
东归家室远，掉辔时参差。
浙云近吴见，汴柳接楚垂。
明年春光别，回首不复疑。','',''),('quantangshi-31738','酬栖上人','賈島','quantangshi','','卷32','夜久城馆闲，情幽出在山。
新月有微辉，朗朗空庭间。
处世虽识机，伊余多掩关。
松姿度腊见，篱药知春还。
静览冰雪词，厚为酬赠颜。
东林有踯躅，脱屣期共攀。','',''),('quantangshi-31739','冬月长安雨中见终南雪','賈島','quantangshi','','卷32','秋节新已尽，雨疎露山雪。
西峰稍觉明，残滴犹未绝。
气侵瀑布水，冻着白云穴。
今朝灞浐雁，何夕潇湘月。
想彼石房人，对雪扉不闭。','',''),('quantangshi-31740','寄孟协律','賈島','quantangshi','','卷32','我有吊古泣，不泣向路岐。
挥泪洒暮天，滴着桂树枝。
别后冬节至，离心北风吹。
坐孤雪扉夕，泉落石桥时。
不惊猛虎啸，难辱君子词。
欲酬空觉老，无以堪远持。
岧嶤倚角窗，王屋悬清思。','',''),('quantangshi-31741','和刘涵','賈島','quantangshi','','卷32','京官始云满，野人依旧闲。
闭扉一亩居，中有古风还。
市井日已午，幽窗梦南山。
乔木覆北斋，有鸟鸣其间。
前日远岳僧，来时与开关。
新题惊我瘦，窥镜见丑颜。
陶情惜清澹，此意复谁攀。','',''),('quantangshi-31742','明月山怀独孤崇鱼琢','賈島','quantangshi','','卷32','明月长在目，明月长在心。
在心复在目，何得稀去寻。
试望明月人，孟夏树蔽岑。
想彼叹此怀，乐喧忘幽林。
乡本北岳外，悔恨东夷深。
愿缩地脉还，岂待天恩临。
非不渴隐秀，却嫌他事侵。
或云岳楼钟，来绕草堂吟。
当从令伊后，再往步柏林。','',''),('quantangshi-31743','投张太祝','賈島','quantangshi','','卷32','风骨高更老，向春初阳葩。
[泠泠]月下韵，一一落海涯。
有子不敢和，一听千叹嗟。
身卧东北泥，魂挂西南霞。
手把一枝栗，往轻觉程赊。
水天朔方色，暖日嵩根花。
达闲幽栖山，遣寻种药家。
欲买双琼瑶，慙无一木瓜。','',''),('quantangshi-31744','咏韩氏二子','賈島','quantangshi','','卷32','千岩一尺璧，八月十五夕。
清露堕桂花，白鸟舞虚碧。','',''),('quantangshi-31745','送别','賈島','quantangshi','','卷32','丈夫未得意，行行且低眉。
素琴弹复弹，会有知音知。','',''),('quantangshi-31746','携新文诣张籍韩愈途中成','賈島','quantangshi','','卷32','袖有新成诗，欲见张韩老。
青竹未生翼，一步万里道。
仰望青冥天，云雪压我脑。
失却终南山，惆怅满怀抱。
安得西北风，身愿变蓬草。
地只闻此语，突出惊我倒。','',''),('quantangshi-31747','上谷送客游江湖','賈島','quantangshi','','卷32','莫叹迢遰分，何殊咫尺别。
江楼到夜登，还见南台月。','',''),('quantangshi-31748','重酬姚少府','賈島','quantangshi','','卷32','隙月斜枕旁，讽咏夏贻什。
如今何时节，虫虺亦已蛰。
答迟礼涉傲，抱疾思加涩。
仆本胡为者，衔肩贡客集。
茫然九州内，譬如一锥立。
欺暗少此怀，自明曾沥泣。
量无趫勇士，诚欲戈矛戢。
原阁期跻攀，潭舫偶俱入。
深斋竹木合，毕夕风雨急。
俸利沐均分，价称烦嘘噏。
百篇见删罢，一命嗟未及。
沧浪愚将还，知音激所习。','',''),('quantangshi-31749','投孟郊','賈島','quantangshi','','卷32','月中有孤芳，天下聆薰风。
江南有高唱，海北初来通。
容飘清冷余，自蕴襟抱中。
止息乃流溢，推寻却冥蒙。
我知雪山子，谒彼偈句空。
必竟获所实，尔焉遂深衷。
录之孤灯前，犹恨百首终。
一吟动狂机，万疾辞顽躬。
生平面未交，永夕梦辄同。
叙诘谁君师，讵言无吾宗。
余求履其迹，君曰可但攻。
啜波肠易饱，揖险神难从。
前岁曾入洛，差池阻从龙。
萍家复从赵，云思长萦萦。
嵩海每可诣，长途追再穷。
愿倾肺肠事，尽入焦梧桐。','',''),('quantangshi-31750','代边将','賈島','quantangshi','','卷32','持戈簇边日，战罢浮云收。
露草泣寒霁，夜泉鸣陇头。
三尺握中铁，气冲星斗牛。
报国不拘贵，愤将平虏雠。','',''),('quantangshi-31751','寄刘栖楚','賈島','quantangshi','','卷32','趋走与偃卧，去就自殊分。
当窗一重树，上有万里云。
离披不相顾，仿髴类人羣。
友生去更远，来书绝如焚。
蝉吟我为听，我歌蝉岂闻。
岁暮傥旋归，晤言桂氛氲。','',''),('quantangshi-31752','寄丘儒','賈島','quantangshi','','卷32','地近轻数见，地远重一面。
一面如何重，重甚珍宝片。
自经失欢笑，几度腾霜霰。
此心镇悬悬，天象固回转。
长安秋风高，子在东甸县。
仪形信寂蔑，风雨岂乖间。
凭人报消息，何易凭笔砚。
俱不尽我心，终须对君宴。','',''),('quantangshi-31753','送陈商','賈島','quantangshi','','卷32','古道长荆棘，新岐路交横。
君于荒榛中，寻得古辙行。
足踏圣人路，貌端禅士形。
我曾接夜谈，似听讲一经。
联翩曾数举，昨登高第名。
釜底绝烟火，晓行皇帝京。
上客远府游，主人须目明。
青云别青山，何日复可升。','',''),('quantangshi-31754','送张校书季霞','賈島','quantangshi','','卷32','从京去容州，马在船上多。
容州几千里，直傍青天涯。
掌记试校书，未称高词华。
义往不可屈，出家如入家。
城市七月初，热与夏未差。
饯君到野地，秋凉满山坡。
南境异北候，风起无尘沙。
秦吟宿楚泽，海酒落桂花。
暂醉即还醒，彼土生桂茶。','',''),('quantangshi-31755','寄友人','賈島','quantangshi','','卷32','同人半年别，一别寂来音。
赖有别时文，相思时一吟。
我常倦投迹，君亦知此衿。
笔砚且勿弃，苏张曾陆沈。
但存舌在口，当冀身遂心。
君看明月夜，松桂寒森森。','',''),('quantangshi-31756','答王参','賈島','quantangshi','','卷32','寸晷不相待，四时互如竞。
客思先觉秋，虫声苦知暝。
霜松积旧翠，露月团如镜。
诗负属景同，琴孤坐堂听。
相期黄菊节，别约红桃径。
每把式微篇，临风一长咏。','',''),('quantangshi-31757','延康吟','賈島','quantangshi','','卷32','寄居延寿里，为与延康邻。
不爱延康里，爱此里中人。
人非十年故，人非九族亲。
人有不朽语，得之烟山春。','',''),('quantangshi-31758','戏赠友人','賈島','quantangshi','','卷32','一日不作诗，心源如废井。
笔砚为辘轳，吟咏作縻绠。
朝来重汲引，依旧得清[冷]。
书赠同怀人，词中多苦辛。','',''),('quantangshi-31759','寓兴','賈島','quantangshi','','卷32','真集道方至，貌殊妬还多。
山泉入城池，自然生浑波。
今时出古言，在众翻为讹。
有琴含正韵，知音者如何。
一生足感激，世言忽嵯峨。
不得市井味，思响吾岩阿。
浮华岂我事，日月徒蹉跎。
旷哉颍阳风，千载无其他。','',''),('quantangshi-31760','怀郑从志','賈島','quantangshi','','卷32','西风吹阴云，雨雪半夜收。
忽忆天涯人，起看斗与牛。
故人别二年，我意如百秋。
音信两杳杳，谁云昔绸缪。
平明一封书，寄向东北舟。
翩翩春归鸟，会自为匹俦。','',''),('quantangshi-31761','易州登龙兴寺楼望郡北高峰','賈島','quantangshi','','卷32','郡北最高峰，巉岩绝云路。
朝来上楼望，稍觉得幽趣。
朦胧碧烟里，羣岭若相附。
何时一登陟，万物皆下顾。','',''),('quantangshi-31762','送郑山人游江湖','賈島','quantangshi','','卷32','南游衡岳上，东往天台里。
足蹑华顶峰，目观沧海水。','',''),('quantangshi-31763','就峰公宿','賈島','quantangshi','','卷32','河出鸟宿后，萤火白露中。
上人坐不倚，共我论量空。
残月华暗暧，远水响玲珑。
尔时无了梦，兹宵方未穷。','',''),('quantangshi-31764','刘景阳东斋','賈島','quantangshi','','卷32','松阴连竹影，中有芜苔井。
清风此地多，白日空自永。
景阳公干孙，诗句得真景。
劝我不须归，月出东斋静。','',''),('quantangshi-31765','对菊','賈島','quantangshi','','卷32','九日不出门，十日见黄菊。
灼灼尚繁英，美人无消息。','',''),('quantangshi-31766','送集文上人游方','賈島','quantangshi','','卷32','来从道陵井，双木溪边会。
分首芳草时，远意青天外。
此游诣几岳，嵩华衡恒泰。','',''),('quantangshi-31767','题岸上人郡内闲居','賈島','quantangshi','','卷32','静向方寸求，不居山嶂幽。
池开菡萏香，门闭莓苔秋。
金玉重四句，粃糠轻九流。
炉烟上乔木，钟磬下危楼。
手种一株松，贞心与师俦。','',''),('quantangshi-31768','游子','賈島','quantangshi','','卷32','游子喜乡远，非吾忆归庐。
谁知奔他山，自欲早旋车。
朝赏暮已足，图归愿无余。
当期附鹏翼，未偶方踌躇。','',''),('quantangshi-31769','寄山中王参','賈島','quantangshi','','卷32','我看岳西云，君看岳北月。
长怀燕城南，相送十里别。
别来千余日，日日忆不歇。
远寄一纸书，数字论白发。','',''),('quantangshi-31770','送汲鹏','賈島','quantangshi','','卷32','淮南卧理后，复逢君姓汲。
文采非寻常，志愿期卓立。
深江东泛舟，夕阳眺原隰。
夏夜言诗会，往往追不及。','',''),('quantangshi-31771','寄令狐相公','賈島','quantangshi','','卷32','策杖驰山驿，逢人问梓州。
长江那可到，行客替生愁。','',''),('quantangshi-31772','哭柏岩和尚','賈島','quantangshi','','卷32','苔覆石床新，师曾占几春。
写留行道影，焚却坐禅身。
塔院关松雪，经房锁隙尘。
自嫌双泪下，不是解空人。','',''),('quantangshi-31773','山中道士','賈島','quantangshi','','卷32','头发梳千下，休粮带瘦容。
养雏成大鹤，种子作高松。
白石通宵煮，寒泉尽日舂。
不曾离隐处，那得世人逢。','',''),('quantangshi-31774','就可公宿','賈島','quantangshi','','卷32','十里寻幽寺，寒流数派分。
僧同雪夜坐，雁向草堂闻。
静语终灯焰，余生许峤云。
由来多抱疾，声不达明君。','',''),('quantangshi-31775','旅游','賈島','quantangshi','','卷32','此心非一事，书札若为传。
旧国别多日，故人无少年。
空巢霜叶落，疎牖水萤穿。
留得林僧宿，中宵坐默然。','',''),('quantangshi-31776','送邹明府游灵武','賈島','quantangshi','','卷32','曾宰西畿县，三年马不肥。
债多平剑与，官满载书归。
边雪藏行径，林风透卧衣。
灵州听晓角，客馆未开扉。','',''),('quantangshi-31777','题皇甫荀蓝田厅','賈島','quantangshi','','卷32','任官经一年，县与玉峰连。
竹笼拾山果，瓦瓶担石泉。
客归秋雨后，印锁暮钟前。
久别丹阳浦，时时梦钓船。','',''),('quantangshi-31778','赠王将军','賈島','quantangshi','','卷32','宿卫炉烟近，除书墨未干。
马曾金镞中，身有宝刀瘢。
父子同时捷，君王画阵看。
何当为外帅，白日出长安。','',''),('quantangshi-31779','下第','賈島','quantangshi','','卷32','下第只空囊，如何住帝乡。
杏园啼百舌，谁醉在花傍。
泪落故山远，病来春草长。
知音逢岂易，孤棹负三湘。','',''),('quantangshi-31780','寄贺兰朋吉','賈島','quantangshi','','卷32','往往东林下，花香似火焚。
故园从小别，夜雨近秋闻。
野菜连寒水，枯株簇古坟。
泛舟同远客，寻寺入幽云。
斜日扉多掩，荒田径细分。
相思蝉几处，偶坐蝶成羣。
会宿曾论道，登高省议文。
苦吟遥可想，边叶向纷纷。','',''),('quantangshi-31781','忆吴处士','賈島','quantangshi','','卷32','半夜长安雨，灯前越客吟。
孤舟行一月，万水与千岑。
岛屿夏云起，汀洲芳草深。
何当折松叶，拂石剡溪阴。','',''),('quantangshi-31782','哭孟郊','賈島','quantangshi','','卷32','身死声名在，多应万古传。
寡妻无子息，破宅带林泉。
冢近登山道，诗随过海船。
故人相吊后，斜日下寒天。','',''),('quantangshi-31783','送崔定','賈島','quantangshi','','卷32','未知游子意，何不避炎蒸？
几日到汉水，新蝉鸣杜陵。
秋江待得月，夜语恨无僧。
巴峡吟过否，连天十二层。','',''),('quantangshi-31784','寄白阁默公','賈島','quantangshi','','卷32','已知归白阁，山远晚晴看。
石室人心静，冰潭月影残。
微云分片灭，古木落薪干。
后夜谁闻磬，西峰绝顶寒。','',''),('quantangshi-31785','雨后宿刘司马池上','賈島','quantangshi','','卷32','蓝溪秋漱玉，此地涨清澄。
芦苇声兼雨，芰荷香遶灯。
岸头秦古道，亭面汉荒陵。
静想泉根本，幽崖落几层。','',''),('quantangshi-31786','送朱可久归越中','賈島','quantangshi','','卷32','石头城下泊，北固暝钟初。
汀鹭潮冲起，船窗月过虚。
吴山侵越众，隋柳入唐疎。
日欲躬调膳，辟来何府书。','',''),('quantangshi-31787','送田卓入华山','賈島','quantangshi','','卷32','幽深足暮蝉，惊觉石床眠。
瀑布五千仞，草堂瀑布边。
坛松涓滴露，岳月泬寥天。
鹤过君须看，上头应有仙。','',''),('quantangshi-31788','送董正字常州觐省','賈島','quantangshi','','卷32','相逐一行鸿，何时出碛中？
江流翻白浪，木叶落青枫。
轻檝浮吴国，繁霜下楚空。
春来懽侍阻，正字在东宫。','',''),('quantangshi-31789','酬姚少府','賈島','quantangshi','','卷32','梅树与山木，俱应摇落初。
柴门掩寒雨，虫响出秋蔬。
枯槁彰清镜，孱愚友道书。
刊文非不朽，君子自相于。','',''),('quantangshi-31790','送无可上人','賈島','quantangshi','','卷32','圭峰霁色新，送此草堂人。
麈尾同离寺，蛩鸣暂别亲。
独行潭底影，数息树边身。
终有烟霞约，天台作近邻。','',''),('quantangshi-31791','送李骑曹','賈島','quantangshi','','卷32','归骑双旌远，懽生此别中。
萧关分碛路，嘶马背寒鸿。
朔色晴天北，河源落日东。
贺兰山顶草，时动卷帆风。','',''),('quantangshi-31792','送乌行中石淙别业','賈島','quantangshi','','卷32','寒水长绳汲，丁泠数滴翻。
草通石淙脉，砚带海潮痕。
岳色何曾远，蝉声尚未繁。
劳思当此夕，苗稼在西原。','',''),('quantangshi-31793','送觉兴上人归中条山兼谒河中李司空','賈島','quantangshi','','卷32','又忆西岩寺，秦原草白时。
山寻樵径上，人到雪房迟。
暮磬潭泉冻，荒林野烧移。
闻师新译偈，说拟对旌麾。','',''),('quantangshi-31794','寄无可上人','賈島','quantangshi','','卷32','僻寺多高树，凉天忆重游。
磬过沟水尽，月入草堂秋。
穴蚁苔痕静，藏蝉柏叶稠。
名山思徧往，早晚到嵩丘。','',''),('quantangshi-31795','南池','賈島','quantangshi','','卷32','萧条微雨绝，荒岸抱清源。
入舫山侵塞，分泉稻接村。
秋声依树色，月影在蒲根。
淹泊方难遂，他宵关梦魂。','',''),('quantangshi-31796','寄龙池寺贞空二上人','賈島','quantangshi','','卷32','受请终南住，俱妨去石桥。
林中秋信绝，峰顶夜禅遥。
寒草烟藏虎，高松月照雕。
霜天期到寺，寺置即前朝。','',''),('quantangshi-31797','送贞空二上人','賈島','quantangshi','','卷32','林下中餐后，天涯欲去时。
衡阳过有伴，梦泽出应迟。
石磬疎寒韵，铜瓶结夜澌。
殷勤讶此别，且未定归期。','',''),('quantangshi-31798','送裴校书','賈島','quantangshi','','卷32','拜官从祕省，署职在藩维。
多故长疎索，高秋远别离。
天寒泗上醉，夜静岳阳碁。
使府临南海，帆飞到不迟。','',''),('quantangshi-31799','升道精舍南台对月寄姚合','賈島','quantangshi','','卷32','月向南台见，秋霖洗涤余。
出逢危叶落，静看众峰疎。
[冷]露常时有，禅窗此夜虚。
相思聊怅望，润气徧衣初。','',''),('quantangshi-31800','即事','賈島','quantangshi','','卷32','索莫对孤灯，阴云积几层。
自嗟怜十上，谁肯待三征。
心被通人见，文叨大匠称。
悲秋秦塞草，怀古汉家陵。
城静高崖树，漏多幽沼冰。
过声沙岛鹭，绝行石庵僧。
岂谓旧庐在，谁言归未曾。','',''),('quantangshi-31801','黄子陂上韩吏部','賈島','quantangshi','','卷32','石楼云一别，二十二三春。
相逐升堂者，几为埋骨人。
涕流闻度瘴，病起喜还秦。
曾是令勤道，非惟恤在迍。
疎衣蕉缕细，爽味茗芽新。
钟绝滴残雨，萤多无近邻。
溪潭承到数，位秩见辞频。
若个山招隐，机忘任此身。','',''),('quantangshi-31802','投李益','賈島','quantangshi','','卷32','四十归燕字，千年外始吟。
已将书北岳，不用比南金。','',''),('quantangshi-31803','吊孟协律','賈島','quantangshi','','卷32','才行古人齐，生前品位低。
葬时贫卖马，远日哭惟妻。
孤冢北邙外，空斋中岳西。
集诗应万首，物象徧曾题。','',''),('quantangshi-31804','送人适越','賈島','quantangshi','','卷32','高城满夕阳，何事欲霑裳。
迁客蓬蒿暮，游人道路长。
晴湖胜镜碧，寒柳似金黄。
若有相思梦，殷勤载八行。','',''),('quantangshi-31805','送僧游衡岳','賈島','quantangshi','','卷32','心知衡岳路，不怕去人稀。
船里犹鸣磬，溪头自曝衣。
有家从小别，无寺不言归。
料得逢寒住，当禅雪满扉。','',''),('quantangshi-31806','送路','賈島','quantangshi','','卷32','别我就蓬蒿，日斜飞伯劳。
龙门流水急，嵩岳片云高。
叹命无知己，梳头落白毛。
从军当此去，风起广陵涛。','',''),('quantangshi-31807','洛阳道中寄弟','賈島','quantangshi','','卷32','趋走迫流年，慙经此路偏。
密云埋二室，积雪度三川。
生类梗萍泛，悲无金石坚。
翻鸿有归翼，极目仰联翩。','',''),('quantangshi-31808','登江亭晚望','賈島','quantangshi','','卷32','浩渺浸云根，烟岚没远村。
鸟归沙有迹，帆过浪无痕。
望水知柔性，看山欲倦魂。
纵情犹未已，回马欲黄昏。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-31809','送耿处士','賈島','quantangshi','','卷32','一瓶离别酒，未尽即言行。
万水千山路，孤舟几月程。
川原秋色静，芦苇晚风鸣。
迢遰不归客，人传虚隐名。','',''),('quantangshi-31810','过唐校书书斋','賈島','quantangshi','','卷32','池满风吹竹，时时得爽神。
声齐雏鸟语，画卷老僧真。
月出行几步，花开到四邻。
江湖心自切，未可挂头巾。','',''),('quantangshi-31811','送杜秀才东游','賈島','quantangshi','','卷32','东游谁见待，尽室寄长安。
别后叶频落，去程山已寒。
大河风色度，旷野烧烟残。
匣有青铜镜，时将照鬓看。','',''),('quantangshi-31812','送天台僧','賈島','quantangshi','','卷32','远梦归华顶，扁舟背岳阳。
寒蔬修净食，夜浪动禅床。
雁过孤峰晓，猨啼一树霜。
身心无别念，余习在诗章。','',''),('quantangshi-31813','怀紫阁隐者','賈島','quantangshi','','卷32','寂寥思隐者，孤烛坐秋霖。
梨栗猨喜熟，云山僧说深。
寄书应不到，结伴拟同寻。
废寝方终夕，迢迢紫阁心。','',''),('quantangshi-31814','雨夜同厉玄怀皇甫荀','賈島','quantangshi','','卷32','桐竹遶庭匝，雨多风更吹。
还如旧山夜，卧听瀑泉时。
碛雁来期近，秋钟到梦迟。
沟西吟苦客，中夕话兼思。','',''),('quantangshi-31815','秋暮','賈島','quantangshi','','卷32','北门杨柳叶，不觉已缤纷。
值鹤因临水，迎僧忽背云。
白须相并出，清泪两行分。
默默空朝夕，苦吟谁喜闻。','',''),('quantangshi-31816','哭胡遇','賈島','quantangshi','','卷32','夭寿知齐理，何曾免叹嗟。
祭回收朔雪，吊后折寒花。
野水秋吟断，空山暮影斜。
弟兄相识徧，犹得到君家。','',''),('quantangshi-31817','送丹师归闽中','賈島','quantangshi','','卷32','波涛路杳然，衰柳落阳蝉。
行李经雷电，禅前漱岛泉。
归林久别寺，过越未离船。
自说从今去，身应老海边。','',''),('quantangshi-31818','送安南惟鉴法师','賈島','quantangshi','','卷32','讲经春殿里，花遶御牀飞。
南海几回渡，旧山临老归。
潮摇蛮草落，月湿岛松微。
空水既如彼，往来消息稀。','',''),('quantangshi-31819','题李凝幽居','賈島','quantangshi','','卷32','闲居少邻并，草径入荒园。
鸟宿池边树，僧敲月下门。
过桥分野色，移石动云根。
暂去还来此，幽期不负言。','',''),('quantangshi-31820','送韩湘','賈島','quantangshi','','卷32','挂席从古路，长风起广津。
楚城花未发，上苑蝶来新。
半没湖波月，初生岛草春。
孤霞临石镜，极浦映村神。
细响吟干苇，余馨动远苹。
欲凭将一札，寄与沃洲人。','',''),('quantangshi-31821','寄董武','賈島','quantangshi','','卷32','虽同一城里，少省得从容。
门掩园林僻，日高巾帻慵。
孤鸿来半夜，积雪在诸峰。
正忆毗陵客，声声隔水钟。','',''),('quantangshi-31822','宿贇上人房','賈島','quantangshi','','卷32','堦前多是竹，闲地拟栽松。
朱点草书疏，雪平麻履踪。
御沟寒夜雨，宫寺静时钟。
此时无他事，来寻不厌重。','',''),('quantangshi-31823','访李甘原居','賈島','quantangshi','','卷32','原西居处静，门对曲江开。
石缝衔枯草，查根上净苔。
翠微泉夜落，紫阁鸟时来。
仍忆寻淇岸，同行采蕨回。','',''),('quantangshi-31824','题山寺井','賈島','quantangshi','','卷32','沈沈百尺余，功就岂斯须。
汲早僧出定，凿新虫自无。
藏源重嶂底，澄翳大空隅。
此地如经劫，凉潭会共枯。','',''),('quantangshi-31825','僻居无可上人相访','賈島','quantangshi','','卷32','自从居此地，少有事相关。
积雨荒邻圃，秋池照远山。
砚中枯叶落，枕上断云闲。
野客将禅子，依依偏往还。','',''),('quantangshi-31826','送李余及第归蜀','賈島','quantangshi','','卷32','知音伸久屈，觐省去光辉。
津渡逢清夜，途程尽翠微。
云当绵竹叠，鸟离锦江飞。
肯寄书来否，原居出亦稀。','',''),('quantangshi-31827','荒斋','賈島','quantangshi','','卷32','草合径微微，终南对掩扉。
晚凉疎雨绝，初晓远山稀。
落叶无青地，闲身着白衣。
朴愚犹本性，不是学忘机。','',''),('quantangshi-31828','夜喜贺兰三见访','賈島','quantangshi','','卷32','漏钟仍夜浅，时节欲秋分。
泉聒栖松鹤，风除翳月云。
踏苔行引兴，枕石卧论文。
即此寻常静，来多秖是君。','',''),('quantangshi-31829','题青龙寺镜公房','賈島','quantangshi','','卷32','一夕曾留宿，终南摇落时。
孤灯冈舍掩，残磬雪风吹。
树老因寒折，泉深出井迟。
疎慵岂有事，多失上方期。','',''),('quantangshi-31830','送陈判官赴绥德','賈島','quantangshi','','卷32','将军邀入幕，束带便离家。
身暖蕉衣窄，天寒碛日斜。
火烧冈断苇，风卷雪平沙。
丝竹丰州有，春来秖欠花。','',''),('quantangshi-31831','送唐环归敷水庄','賈島','quantangshi','','卷32','毛女峰当户，日高头未梳。
地侵山影扫，叶带露痕书。
松径僧寻药，沙泉鹤见鱼。
一川风景好，恨不有吾庐。','',''),('quantangshi-31832','原东居喜唐温琪频至','賈島','quantangshi','','卷32','曲江春草生，紫阁雪分明。
汲井尝泉味，听钟问寺名。
墨研秋日雨，茶试老僧铛。
地近劳频访，乌纱出送迎。','',''),('quantangshi-31833','送敭法师','賈島','quantangshi','','卷32','度岁不相见，严冬始出关。
孤烟寒色树，高雪夕阳山。
瀑布寺应到，牡丹房甚闲。
南朝遗迹在，此去几时还。','',''),('quantangshi-31834','寄钱庶子','賈島','quantangshi','','卷32','曲江春水满，北岸掩柴关。
秖有僧邻舍，全无物映山。
树阴终日扫，药债隔年还。
犹记听琴夜，寒灯竹屋间。','',''),('quantangshi-31835','原上秋居','賈島','quantangshi','','卷32','关西又落木，心事复如何。
岁月辞山久，秋霖入夜多。
鸟从井口出，人自洛阳过。
倚杖聊闲望，田家未翦禾。','',''),('quantangshi-31836','夏夜','賈島','quantangshi','','卷32','原寺偏邻近，开门物景澄。
磬通多叶罅，月离片云棱。
寄宿山中鸟，相寻海畔僧。
唯愁秋色至，乍可在炎蒸。','',''),('quantangshi-31837','冬夜','賈島','quantangshi','','卷32','羁旅复经冬，瓢空盎亦空。
泪流寒枕上，迹绝旧山中。
淩结浮萍水，雪和衰柳风。
曙光鸡未报，嘹唳两三鸿。','',''),('quantangshi-31838','送厉宗上人','賈島','quantangshi','','卷32','拥策背岷峨，终南雨雪和。
漱泉秋鹤至，禅树夜猨过。
高顶白云尽，前山黄叶多。
曾吟庐岳上，月动九江波。','',''),('quantangshi-31839','寄李存穆','賈島','quantangshi','','卷32','闻道船中病，似忧亲弟兄。
信来从水路，身去到柴城。
久别长须鬓，相思书姓名。
忽然消息绝，频梦却还京。','',''),('quantangshi-31840','赠无怀禅师','賈島','quantangshi','','卷32','身从劫劫修，果以此生周。
禅定石床暖，月移山树秋。
捧盂观宿饭，敲磬过清流。
不掩玄关路，敎人问白头。','',''),('quantangshi-31841','寄武功姚主簿','賈島','quantangshi','','卷32','居枕江沱北，情悬渭曲西。
数宵曾梦见，几处得书披。
驿路穿荒坂，公田带淤泥。
静棊功奥妙，闲作韵清凄。
锄草留丛药，寻山上石梯。
客回河水涨，风起夕阳低。
空地苔连井，孤村火隔溪。
卷帘黄叶落，锁印子规啼。
陇色澄秋月，边声入战鼙。
会须过县去，况是屡招携。','',''),('quantangshi-31842','题刘华书斋','賈島','quantangshi','','卷32','白石床无尘，青松树有鳞。
一莺啼带雨，两树合从春。
荒榭苔胶砌，幽丛果堕榛。
偶来疎或数，当暑夕胜晨。
露滴星河水，巢重草木薪。
终南同往意，赵北独游身。
渡叶司天漏，惊蛩远地人。
机清公干族，也莫卧漳滨。','',''),('quantangshi-31843','送卢秀才游潞府','賈島','quantangshi','','卷32','雨余滋润在，风不起尘沙。
边日寡文思，送君吟月华。
过山干相府，临水宿僧家。
能赋焉长屈，芳春宴杏花。','',''),('quantangshi-31844','送南康姚明府','賈島','quantangshi','','卷32','铜章美少年，小邑在南天。
版籍多迁客，封疆接洞田。
静江鸣野鼓，发缆带村烟。
却笑陶元亮，何须忆醉眠。','',''),('quantangshi-31845','送友人弃官游江左','賈島','quantangshi','','卷32','羡君休作尉，万事且全身。
寰海多虞日，江湖独往人。
姓名何处变，鸥鸟几时亲。
别后吴中使，应须访子真。','',''),('quantangshi-31846','雨中怀友人','賈島','quantangshi','','卷32','对雨思君子，尝茶近竹幽。
儒家邻古寺，不到又逢秋。','',''),('quantangshi-31847','寄远','賈島','quantangshi','','卷32','家住锦水上，身征辽海边。
十书九不到，一到忽经年。','',''),('quantangshi-31848','南斋','賈島','quantangshi','','卷32','独自南斋卧，神闲景亦空。
有山来枕上，无事到心中。
帘卷侵牀月，屏遮入座风。
望春春未至，应在海门东。','',''),('quantangshi-31849','早春题友人湖上新居二首 一','賈島','quantangshi','','卷32','近得云中路，门长侵早开。
到时犹有雪，行处已无苔。
劝酒客初醉，留茶僧未来。
每逢晴暖日，惟见乞花栽。','',''),('quantangshi-31850','早春题友人湖上新居二首 二','賈島','quantangshi','','卷32','门不当官道，行人到亦稀。
故从餐后出，多是夜深归。
开箧收诗卷，扫牀移卧衣。
几时同买宅，相送有柴扉。','',''),('quantangshi-31851','送雍陶入蜀','賈島','quantangshi','','卷32','江山事若谙，那肯滞云南。
草色分危磴，杉阴近古潭。
日斜襃谷鸟，夏浅巂州蚕。
吾自疑双鬓，相逢更不堪。','',''),('quantangshi-31852','张郎中过原东居','賈島','quantangshi','','卷32','年长惟添嬾，经旬止掩关。
高人餐药后，下马此林间。
对坐天将暮，同来客亦闲。
几时能重至，水味似深山。','',''),('quantangshi-31853','答王建祕书','賈島','quantangshi','','卷32','人皆闻蟋蟀，我独恨蹉跎。
白发无心镊，青山去意多。
信来漳浦岸，期负洞庭波。
时扫高槐影，朝回或恐过。','',''),('quantangshi-31854','送李余往湖南','賈島','quantangshi','','卷32','昔去候温凉，秋山满楚乡。
今来从辟命，春物徧涔阳。
岳石挂海雪，野枫堆渚樯。
若寻吾祖宅，寂寞在潇湘。','',''),('quantangshi-31855','偶作','賈島','quantangshi','','卷32','野步随吾意，那知是与非。
稔年时雨足，闰月暮蝉稀。
独树依冈老，遥峰出草微。
园林自有主，宿鸟且同归。','',''),('quantangshi-31856','过雍秀才居','賈島','quantangshi','','卷32','夏木鸟巢边，终南岭色鲜。
就凉安坐石，煮茗汲邻泉。
钟远清霄半，蜩稀暑雨前。
幽斋如葺罢，约我一来眠。','',''),('quantangshi-31857','寄顾非熊','賈島','quantangshi','','卷32','知君归有处，山水亦难齐。
犹去潇湘远，不闻猨狖啼。
穴通茆岭下，潮满石头西。
独立生遥思，秋原日渐低。','',''),('quantangshi-31858','送神邈法师','賈島','quantangshi','','卷32','柳絮落蒙蒙，西州道路中。
相逢春忽尽，独去讲初终。
行疾遥山雨，眠迟后夜风。
绕房三两树，回日叶应红。','',''),('quantangshi-31859','送慈恩寺霄韵法师谒太原李司空','賈島','quantangshi','','卷32','何故谒司空，云山知几重。
碛遥来雁尽，雪急去僧逢。
清磬先寒角，禅灯彻晓烽。
旧房闲片石，倚着最高松。','',''),('quantangshi-31860','送知兴上人','賈島','quantangshi','','卷32','久住巴兴寺，如今始拂衣。
欲临秋水别，不向故园归。
锡挂天涯树，房开岳顶扉。
下看千里晓，霜海日生微。','',''),('quantangshi-31861','送惠雅法师归玉泉','賈島','quantangshi','','卷32','秖到潇湘水，洞庭湖未游。
饮泉看月别，下峡听猨愁。
讲不停雷雨，吟当近海流。
降霜归楚夕，星冷玉泉秋。','',''),('quantangshi-31862','忆江上吴处士','賈島','quantangshi','','卷32','闽国扬帆去，蟾蜍亏复团。
秋风生渭水，落叶满长安。
此地聚会夕，当时雷雨寒。
兰桡殊未返，消息海云端。','',''),('quantangshi-31863','题张博士新居','賈島','quantangshi','','卷32','青枫何不种，林在洞庭村。
应为三湘远，难移万里根。
斗牛初过伏，菡萏欲香门。
旧即湖山隐，新庐葺此原。','',''),('quantangshi-31864','石门陂留辞从叔謩','賈島','quantangshi','','卷32','幽鸟飞不远，此行千里间。
寒冲陂水雾，醉下菊花山。
有耻长为客，无成又入关。
何时临涧柳，吾党共来攀。','',''),('quantangshi-31865','送朱兵曹回越','賈島','quantangshi','','卷32','星彩练中见，澄江岂有泥。
潮生垂钓罢，楚尽去樯西。
碛鸟辞沙至，山鼯隔水啼。
会稽半侵海，涛白禹祠溪。','',''),('quantangshi-31866','怀博陵故人','賈島','quantangshi','','卷32','孤城易水头，不忘旧交游。
雪压围碁石，风吹饮酒楼。
路遥千万里，人别十三秋。
吟苦相思处，天寒水急流。','',''),('quantangshi-31867','夕思','賈島','quantangshi','','卷32','秋宵已难曙，漏向二更分。
我忆山水坐，虫当寂寞闻。
洞庭风落木，天姥月离云。
会自东浮去，将何欲致君。','',''),('quantangshi-31868','寄河中杨少尹','賈島','quantangshi','','卷32','非惟咎曩时，投刺诣门迟。
怅望三秋后，参差万里期。
禹留疏凿迹，舜在寂寥祠。
此到杳难共，回风逐所思。','',''),('quantangshi-31869','孟融逸人','賈島','quantangshi','','卷32','孟君临水居，不食水中鱼。
衣褐唯麤帛，筐箱秖素书。
树林幽鸟恋，世界此心疎。
拟棹孤舟去，何峰又结庐。','',''),('quantangshi-31870','晚晴见终南诸峰','賈島','quantangshi','','卷32','秦分积多峰，连巴势不穷。
半旬藏雨里，此日到窗中。
圆魄将升兔，高空欲呌鸿。
故山思不见，碣石泬寥东。','',''),('quantangshi-31871','宿池上','賈島','quantangshi','','卷32','泉来从绝壑，亭敞在中流。
竹密无空岸，松长可绊舟。
蟪蛄潭上夜，河汉岛前秋。
异夕期深涨，携琴却此游。','',''),('quantangshi-31872','喜姚郎中自杭州回','賈島','quantangshi','','卷32','路多枫树林，累日泊清阴。
来去泛流水，翛然适此心。
一披江上作，三起月中吟。
东省期司谏，云门悔不寻。','',''),('quantangshi-31873','送郑长史之岭南','賈島','quantangshi','','卷32','云林颇重叠，岑渚复幽奇。
汨水斜阳岸，骚人正则祠。
苍梧多蟋蟀，白露湿江蓠。
擢第荣南去，晨昏近九疑。','',''),('quantangshi-31874','送李溟谒宥州李权使君','賈島','quantangshi','','卷32','英雄典宥州，迢遰苦吟游。
风宿骊山下，月斜灞水流。
去时初落叶，回日定非秋。
太守携才子，看鹏百尺楼。','',''),('quantangshi-31875','永福湖和杨郑州','賈島','quantangshi','','卷32','积水还平岸，春来引郑溪。
旧渠通郭下，新堰绝湖西。
嵩少分明对，潇湘阔狭齐。
客游随庶子，孤屿草萋萋。','',''),('quantangshi-31876','题长江','賈島','quantangshi','','卷32','言心俱好静，廨署落晖空。
归吏封宵钥，行蛇入古桐。
长江频雨后，明月众星中。
若任迁人去，西溪与剡通。','',''),('quantangshi-31877','泥阳馆','賈島','quantangshi','','卷32','客愁何并起，暮送故人回。
废馆秋萤出，空城寒雨来。
夕阳飘白露，树影扫青苔。
独坐离容惨，孤灯照不开。','',''),('quantangshi-31878','送徐员外赴河中','賈島','quantangshi','','卷32','原野正萧瑟，中间分散情。
吏从甘扈罢，诏许朔方行。
边日沈残角，河关截夜城。
云居闲独往，长老出房迎。','',''),('quantangshi-31879','送贺兰上人','賈島','quantangshi','','卷32','野僧来别我，略坐傍泉沙。
远道擎空钵，深山蹋落花。
无师禅自解，有格句堪夸。
此去非缘事，孤云不定家。','',''),('quantangshi-31880','送令狐綯相公','賈島','quantangshi','','卷32','梁园趋戟节，海草几枯春。
风水难遭便，差池未振鳞。
姓名犹语及，门馆阻何因。
苦拟修文卷，重擎献匠人。
吟看青岛处，朝退赤墀晨。
根爱杉栽活，枝怜雪霰新。
缀篇嗟调逸，不知揣才贫。
早晚还霖雨，滂沱洗月轮。
揠苗方灭裂，成器待陶钧。
困坂思回顾，迷邦輙问津。
数行望外札，绝句握中珍。
是日荣游汴，当时怯往陈。
鸿舂乖汉爵，[桢]病卧漳滨。
岳整五千仞，云惟一片身。
故山离未死，秋水宿经旬。
下第能无恧，高科恐有神。
罢耕田料废，省钓岸应榛。
慷慨知音在，谁能泪堕巾。','',''),('quantangshi-31881','寄沧州李尚书','賈島','quantangshi','','卷32','沧溟深绝阔，西岸郭东门。
弋者罗夷鸟，桴人思峤猨。
威棱高腊冽，煦育极春温。
陂淀封疆内，蒹葭壁垒根。
摇鞞边地脉，愁箭虎狼魂。
水县卖纱市，盐田煮海村。
枝条分御叶，家世食唐恩。
武可纵横讲，功从战伐论。
天涯生月片，屿顶涌泉源。
非是泥池物，方因雷雨尊。
沈谋藏未露，隣境帖无喧。
青冢骄回鹘，萧关陷吐蕃。
何时霖岁旱，早晚雪邦冤。
迢遰瞻旌纛，浮阳寄咏言。','',''),('quantangshi-31882','逢旧识','賈島','quantangshi','','卷32','几岁阻干戈，今朝劝酒歌。
羡君无白发，走马过黄河。
旧宅兵烧尽，新宫日奏多。
妖星还有角，数尺铁重磨。','',''),('quantangshi-31883','崇圣寺斌公房','賈島','quantangshi','','卷32','近来惟一食，树下掩禅扉。
落日寒山磬，多年坏衲衣。
白须长更剃，青霭远还归。
仍说游南岳，经行是息机。','',''),('quantangshi-31884','送李傅侍郎劒南行营','賈島','quantangshi','','卷32','走马从边事，新恩受外台。
勇看双节出，期破八蛮回。
许国家无恋，盘江栈不摧。
移军刁斗逐，报捷劒门开。
角咽狝猴呌，鼙干霹雳来。
去年新甸邑，犹滞佐时才。','',''),('quantangshi-31885','别徐明府','賈島','quantangshi','','卷32','抱琴非本意，生事偶相萦。
口尚袁安节，身无子贱名。
地寒春雪盛，山浅夕风轻。
百战余荒野，千夫渐耦耕。
一杯宜独夜，孤客恋交情。
明日疲骖去，萧条过古城。','',''),('quantangshi-31886','岐下送友人归襄阳','賈島','quantangshi','','卷32','蹉跎随泛梗，羁旅到西州。
举翮笼中鸟，知心海上鸥。
山光分首暮，草色向家秋。
若更登高岘，看碑定泪流。','',''),('quantangshi-31887','送友人游蜀','賈島','quantangshi','','卷32','万岑深积翠，路向此中难。
欲暮多羁思，因高莫远看。
卓家人寂寞，扬子业凋残。
唯有岷江水，悠悠带月寒。','',''),('quantangshi-31888','送郑少府','賈島','quantangshi','','卷32','江岸一相见，空令惜此分。
夕阳行带月，酌水少留君。
野地初烧草，荒山过雪云。
明年还调集，蝉可在家闻。','',''),('quantangshi-31889','子规','賈島','quantangshi','','卷32','游魂自相呌，宁复记前身。
飞过隣家月，声连野路春。
梦边催晓急，愁处送风频。
自有霑花血，相和雨滴新。','',''),('quantangshi-31890','送僧归天台','賈島','quantangshi','','卷32','辞秦经越过，归寺海西峯。
石磵双流水，山门九里松。
曾闻清禁漏，却听赤城钟。
妙宇研磨讲，应齐智者踪。','',''),('quantangshi-31891','让糺曹上乐使君','賈島','quantangshi','','卷32','战战复兢兢，犹如履薄冰。
虽然叨一掾，还似说三乘。
瓶汲南溪水，书来北岳僧。
戆愚兼抱疾，权纪不相应。','',''),('quantangshi-31892','赠友人','賈島','quantangshi','','卷32','五字诗成卷，清新韵具偕。
不同狂客醉，自伴律僧斋。
春别和花树，秋辞带月淮。
却归登第日，名近榜头排。','',''),('quantangshi-31893','送雍陶及第归成都宁亲','賈島','quantangshi','','卷32','不唯诗着籍，兼又赋知名。
议论于题称，春秋对问精。
半应阴隲与，全赖有司平。
归去峯峦众，别来松桂生。
涨江流水品，当道白云坑。
勿以攻文捷，而将学劒轻。
制衣新濯锦，开酝旧烧罂。
同日升科士，谁同膝下荣。','',''),('quantangshi-31894','谢令狐綯相公赐衣九事','賈島','quantangshi','','卷32','长江飞鸟外，主簿跨驴归。
逐客寒前夜，元戎予厚衣。
雪来松更绿，霜降月弥辉。
即日调殷鼎，朝分是与非。','',''),('quantangshi-31895','送金州鉴周上人','賈島','quantangshi','','卷32','地必寻天目，溪仍住若耶。
帆随风便发，月不要云遮。
极浦浮霜雁，回潮落海查。
峨嵋省春上，立雪指流沙。','',''),('quantangshi-31896','送谭远上人','賈島','quantangshi','','卷32','下视白云时，山房盖树皮。
垂枝松落子，侧顶鹤听棋。
清净从沙劫，中终未日欹。
金光明本行，同侍出峨嵋。','',''),('quantangshi-31897','新年','賈島','quantangshi','','卷32','嗟以龙钟身，如何岁复新。
石门思隐久，铜镜强窥频。
花发新移树，心知故国春。
谁能平此恨，岂是北宗人。','',''),('quantangshi-31898','送僧','賈島','quantangshi','','卷32','出家从丱岁，解论造玄门。
不惜挥谈柄，谁能听至言。
中时山果熟，后夏竹阴繁。
此去逢何日，峨嵋晓复昏。','',''),('quantangshi-31899','送姚杭州','賈島','quantangshi','','卷32','白云峯下城，日夕白云生。
人老江波钓，田侵海树耕。
吴山钟入越，莲叶吹摇旌。
诗异石门思，涛来向越迎。','',''),('quantangshi-31900','夜集田卿宅','賈島','quantangshi','','卷32','朗咏高斋下，如将古调弹。
翻鸿向桂水，来雪渡桑干。
滴滴玉漏曙，翛翛竹籁残。
曩年曾宿此，亦值五陵寒。','',''),('quantangshi-31901','寄山友长孙栖峤','賈島','quantangshi','','卷32','此时气萧飒，琴院可应关。
鹤似君无事，风吹雨遍山。
松生青石上，泉落白云间。
有径连高顶，心期相与还。','',''),('quantangshi-31902','酬厉玄','賈島','quantangshi','','卷32','我来从北鄙，子省涉西陵。
白发初相识，秋山拟共登。
邻居帝城雨，会宿御沟冰。
未报见贻作，耿然中夜兴。','',''),('quantangshi-31903','送刘式洛中觐省','賈島','quantangshi','','卷32','晴峯三十六，侍立上春台。
同宿别离恨，共看星月回。
野莺临苑语，河棹历江来。
便寄相思札，缄封花下开。','',''),('quantangshi-31904','送空公往金州','賈島','quantangshi','','卷32','七百里山水，手中楖栗麤。
松生师坐石，潭涤祖传盂。
长拟老岳峤，又闻思海湖。
惠能同俗姓，不是岭南卢。','',''),('quantangshi-31905','赠绍明上人','賈島','quantangshi','','卷32','未住青云室，中秋独往年。
上方嵩若寺，下视雨和烟。
祖岂无言去，心因断臂传。
不知能已后，更有几灯然。','',''),('quantangshi-31906','赠弘泉上人','賈島','quantangshi','','卷32','洗足下蓝岭，古师精进同。
心知溪卉长，居此玉林空。
西殿宵灯磬，东林曙雨风。
旧峯邻太白，石座雨苔蒙。','',''),('quantangshi-31907','送宣皎上人游太白','賈島','quantangshi','','卷32','剃发鬓无雪，去年三十三。
山过春草寺，磬度落花潭。
得句才邻约，论宗意在南。
峯灵疑懒下，苍翠太虚参。','',''),('quantangshi-31908','病起','賈島','quantangshi','','卷32','高丘归未得，空自责迟回。
身事岂能遂，兰花又已开。
病令新作少，雨阻故人来。
灯下南华卷，祛愁当酒杯。','',''),('quantangshi-31909','送殷侍御赴同州','賈島','quantangshi','','卷32','冯翊蒲西郡，沙冈拥地形。
中条全离岳，清渭半和泾。
夜暮眠明月，秋深至洞庭。
犹来交辟士，事别偃林扃。','',''),('quantangshi-31910','送沈鹤','賈島','quantangshi','','卷32','家楚壻于秦，携妻去养亲。
陆行千里外，风卷一帆新。
夜泊疏山雨，秋吟捣药轮。
芜城登眺作，才动广陵人。','',''),('quantangshi-31911','秋夜仰怀钱孟二公琴客会','賈島','quantangshi','','卷32','月色四时好，秋光君子知。
南山昨夜雨，为我写清规。
独鹤耸寒骨，高杉韵细飔。
仙家缥缈弄，仿髴此中期。','',''),('quantangshi-31912','赠李金州','賈島','quantangshi','','卷32','绮里祠前后，山程践白云。
溯流随大斾，登岸见全军。
晓角吹人梦，秋风卷雁羣。
雾开方露日，汉水底沙分。','',''),('quantangshi-31913','酬姚合校书','賈島','quantangshi','','卷32','因贫行远道，得见旧交游。
美酒易倾尽，好诗难卒酬。
公堂朝共到，私第夜相留。
不觉入关晚，别来林木秋。','',''),('quantangshi-31914','送独孤马二秀才居明月山读书','賈島','quantangshi','','卷32','濯志俱高洁，儒科慕冉颜。
家辞临水郡，雨到读书山。
栖鸟椶花上，声钟砾阁间。
寂寥窗户外，时见一舟还。','',''),('quantangshi-31915','病蝉','賈島','quantangshi','','卷32','病蝉飞不得，向我掌中行。
拆翼犹能薄，酸吟尚极清。
露华凝在腹，尘点误侵睛。
黄雀并鸢鸟，俱怀害尔情。','',''),('quantangshi-31916','青门里作','賈島','quantangshi','','卷32','燕存鸿已过，海内几人愁。
欲问南宗理，将归北岳修。
若无攀桂分，秖是卧云休。
泉树一为别，依稀三十秋。','',''),('quantangshi-31917','卢秀才南台','賈島','quantangshi','','卷32','居在青门里，台当千万岑。
下因冈助势，上有树交阴。
陵远根才近，空长畔可寻。
新晴登啸处，惊起宿枝禽。','',''),('quantangshi-31918','寄李輈侍郎','賈島','quantangshi','','卷32','终过盟津书，分明梦不虚。
人从清渭别，地隔太行余。
宾幕谁嫌静，公门但晏如。
櫑鞞干霹雳，斜汉湿蟾蜍。
追琢垂今后，敦庞得古初。
井台怜操筑，漳岸想丕疏。
亦冀铿珉佩，终当直石渠。
此身多抱疾，幽里近营居。
忆漱苏门涧，经浮楚泽潴。
松栽侵古影，荤断尚芹葅。
语嘿曾延接，心源离滓淤。
谁言姓琴氏，独跨角生鱼。','',''),('quantangshi-31919','寄令狐綯相公','賈島','quantangshi','','卷32','驴骏胜羸马，东川路匪赊。
一缄论贾谊，三蜀寄严家。
澄彻霜江水，分明露石沙。
话言声及政，栈阁谷离斜。
自着衣偏暖，谁忧雪六花。
裹裳留阔襆，防患与通茶。
山馆中宵起，星河残月华。
双僮前日雇，数口向天涯。
良乐知骐骥，张雷验镆铘。
谦光贤将相，别纸圣龙蛇。
岂有斯言玷，应无白璧瑕。
不妨圆魄里，人亦指虾蟇。','',''),('quantangshi-31920','再投李益常侍','賈島','quantangshi','','卷32','何处初投刺，当时赴尹京。
淹留花柳变，然诺肺肠倾。
避暑蝉移树，高眠雁过城。
人家嵩岳色，公府洛河声。
联句逢秋尽，尝茶见月生。
新衣裁白苎，思从曲江行。','',''),('quantangshi-31921','积雪','賈島','quantangshi','','卷32','昔属时霖滞，今逢腊雪多。
南猜飘桂渚，北讶雨交河。
尽灭平芜色，弥重古木柯。
空中离白气，岛外下沧波。
隐者迷樵道，朝人冷玉珂。
夕繁仍昼密，漏间复钟和。
想积高嵩顶，新秋皎月过。','',''),('quantangshi-31922','过杨道士居','賈島','quantangshi','','卷32','先生修道处，茆屋远嚣氛。
叩齿坐明月，搘颐望白云。
精神含药色，衣服带霞纹。
无话瀛洲路，多年别少君。','',''),('quantangshi-31923','赠僧','賈島','quantangshi','','卷32','乱山秋木穴，里有灵蛇藏。
铁锡挂临海，石楼闻异香。
出尘头未白，入定衲凝霜。
莫话五湖事，令人心欲狂。','',''),('quantangshi-31924','送友人游塞','賈島','quantangshi','','卷32','飘蓬多塞下，君见益潸然。
逈碛沙衔日，长河水接天。
夜泉行客火，晓戍向京烟。
少结相思恨，佳期芳草前。','',''),('quantangshi-31925','思游边友人','賈島','quantangshi','','卷32','凝愁对孤烛，昨日饮离杯。
叶下故人去，天中新雁来。
连沙秋草薄，带雪暮山开。
苑北红尘道，何时见远回。','',''),('quantangshi-31926','秋暮寄友人','賈島','quantangshi','','卷32','寥落关河暮，霜风树叶低。
远天垂地外，寒日下峯西。
有志烟霞切，无家岁月迷。
清宵话白阁，已负十年栖。','',''),('quantangshi-31927','寄令狐綯相公','賈島','quantangshi','','卷32','官高频敕授，老免把犁锄。
一主长江印，三封东省书。
不无濠上思，唯食圃中蔬。
梦幻将泡影，浮生事只如。','',''),('quantangshi-31928','和孟逸人林下道情','賈島','quantangshi','','卷32','四气相陶铸，中庸道岂销。
夏云生此日，春色尽今朝。
陋巷贫无闷，毗耶疾未调。
已栽天末柏，合抱岂非遥。','',''),('quantangshi-31929','宿姚少府北斋','賈島','quantangshi','','卷32','石溪同夜泛，复此北斋期。
鸟绝吏归后，蛩鸣客卧时。
鏁城凉雨细，开印曙钟迟。
忆此漳川岸，如今是别离。','',''),('quantangshi-31930','雪晴晚望','賈島','quantangshi','','卷32','倚杖望晴雪，溪云几万重。
樵人归白屋，寒日下危峯。
野火烧冈草，断烟生石松。
却回山寺路，闻打暮天钟。','',''),('quantangshi-31931','送崔峤游潇湘','賈島','quantangshi','','卷32','功烈尚书孙，琢磨风雅言。
渡河山凿处，陟岘汉滩喧。
梦想吟天目，宵同话石门。
枫林叶欲下，极浦月清暾。','',''),('quantangshi-31932','寄朱锡圭','賈島','quantangshi','','卷32','远泊与谁同，来从古木中。
长江人钓月，旷野火烧风。
梦泽吞楚大，闽山厄海丛。
此时樯底水，涛起屈原通。','',''),('quantangshi-31933','马戴居华山因寄','賈島','quantangshi','','卷32','玉女洗头盆，孤高不可言。
瀑流莲岳顶，河注华山根。
绝雀林藏鹘，无人境有猨。
秋蟾才过雨，石上古松门。','',''),('quantangshi-31934','寄胡遇','賈島','quantangshi','','卷32','一自残春别，经炎复到凉。
萤从枯树出，蛩入破堦藏。
落叶书胜纸，闲砧坐当林。
东门因送客，相访也何妨。','',''),('quantangshi-31935','送李戎扶侍往寿安','賈島','quantangshi','','卷32','二千余里路，一半是波涛。
未晓着衣起，出城逢日高。
关山多寇盗，扶侍带弓刀。
临别不挥泪，谁知心郁陶。','',''),('quantangshi-31936','送孙逸人','賈島','quantangshi','','卷32','衣屦犹同俗，妻儿亦宛然。
不餐能累月，无病已多年。
是药皆谙性，令人渐信仙。
杖头书数卷，荷入翠微烟。','',''),('quantangshi-31937','寄华山僧','賈島','quantangshi','','卷32','遥知白石室，松柏隐朦胧。
月落看心次，云生闭目中。
五更钟隔岳，万尺水悬空。
苔藓嵌岩所，依稀有径通。','',''),('quantangshi-31938','送李登少府','賈島','quantangshi','','卷32','伊阳耽酒尉，朗咏醉醒新。
应见嵩山里，明年踯躅春。
一千寻树直，三十六峯邻。
流水潺潺处，坚贞玉涧珉。','',''),('quantangshi-31939','易州过郝逸人居','賈島','quantangshi','','卷32','每逢词翰客，邀我共寻君。
果见闲居赋，未曾流俗闻。
也知邻市井，宛似出嚣氛。
却笑巢由辈，何须隐白云。','',''),('quantangshi-31940','酬鄠县李廓少府见寄','賈島','quantangshi','','卷32','稍怜公事退，复遇夕阳时。
北朔霜凝竹，南山水入篱。
吟怀沧海侣，空问白云师。
恨不相从去，心惟野鹤知。','',''),('quantangshi-31941','净业寺与前鄠县李廓少府同宿','賈島','quantangshi','','卷32','来从城上峯，京寺暮相逢。
往往语复默，微微雨洒松。
家贫初罢吏，年长畏闻蛩。
前日独拘束，披衣起晓钟。','',''),('quantangshi-31942','送南卓归京','賈島','quantangshi','','卷32','残春别镜陂，罢郡未霜髭。
行李逢炎暑，山泉满路岐。
云藏巢鹤树，风触啭莺枝。
三省同虚位，双旌带去思。
入城宵梦后，待漏月沈时。
长策并忠告，从容写玉墀。','',''),('quantangshi-31943','卧疾走笔酬韩愈书问','賈島','quantangshi','','卷32','一卧三四旬，数书惟独君。
愿为出海月，不作归山云。
身上衣频寄，瓯中物亦分。
欲知强健否，病鹤未离羣。','',''),('quantangshi-31944','长孙霞李溟自紫阁白阁二峯见访','賈島','quantangshi','','卷32','寂寞吾庐贫，同来二阁人。
所论唯野事，招作住云邻。
古寺期秋宿，平林散早春。
漱流今已矣，巢许岂尧臣。','',''),('quantangshi-31945','送惟一游清凉寺','賈島','quantangshi','','卷32','去有巡台侣，荒溪众树分。
瓶残秦地水，锡入晋山云。
秋月离喧见，寒泉出定闻。
人间临欲别，旬日雨纷纷。','',''),('quantangshi-31946','郑尚书新开涪江二首 一','賈島','quantangshi','','卷32','岸凿青山破，江开白浪寒。
日沈源出海，春至草生滩。
梓匠防波溢，蓬仙畏水干。
从今疏决后，任雨滞峯峦。','',''),('quantangshi-31947','郑尚书新开涪江二首 二','賈島','quantangshi','','卷32','不侵南亩务，已拔北江流。
涪水方移岸，浔阳有到舟。
潭澄初捣药，波动乍垂钩。
山可疏三里，从知历亿秋。','',''),('quantangshi-31948','寄乔侍郎','賈島','quantangshi','','卷32','大宁犹未到，曾渡北浮桥。
晓出爬船寺，手擎紫栗条。
差池不相见，怅望至今朝。
近日营家计，绳悬一小瓢。','',''),('quantangshi-31949','送去华法师','賈島','quantangshi','','卷32','在越居何寺，东南水路归。
秋江洗一钵，寒日晒三衣。
默听鸿声尽，行看叶影飞。
囊中无宝货，船户夜扃稀。','',''),('quantangshi-31950','送蔡京','賈島','quantangshi','','卷32','跃蹄归鲁日，带漏别秦星。
易折芳条桂，难穷邃义经。
登封多泰岳，巡狩徧沧溟。
家在何林下，梁山翠满庭。','',''),('quantangshi-31951','慈恩寺上座院','賈島','quantangshi','','卷32','未委衡山色，何如对塔峯。
曩宵曾宿此，今夕值秋浓。
羽族栖烟竹，寒流带月钟。
井甘源起异，泉涌渍苔封。','',''),('quantangshi-31952','题朱庆余所居','賈島','quantangshi','','卷32','天寒吟竟晓，古屋瓦生松。
寄信船一只，隔乡山万重。
树来沙岸鸟，窗度雪楼钟。
每忆江中屿，更看城上峯。','',''),('quantangshi-31953','送黄知新归安南','賈島','quantangshi','','卷32','池亭沈饮徧，非独曲江花。
地远路穿海，春归冬到家。
火山难下雪，瘴土不生茶。
知决移来计，相逢期尚赊。','',''),('quantangshi-31954','赠胡禅归','賈島','quantangshi','','卷32','自是根机钝，非关夏腊深。
秋来江上寺，夜坐岭南心。
井凿山含月，风吹磬出林。
祖师携只履，去路杳难寻。','',''),('quantangshi-31955','元日女道士受箓','賈島','quantangshi','','卷32','元日更新夜，斋身称净衣。
数星连斗出，万里断云飞。
霜下磬声在，月高坛影微。
立听师语了，左肘系符归。','',''),('quantangshi-31956','重与彭兵曹','賈島','quantangshi','','卷32','故人在城里，休寄海边书。
渐去老不远，别来情岂疎。
砚冰催腊日，山雀到贫居。
每有平戎计，官家别敕除。','',''),('quantangshi-31957','赠庄上人','賈島','quantangshi','','卷32','不语焚香坐，心知道已成。
流年衰此世，定力见他生。
暮雪余春冷，寒灯续昼明。
寻常五侯至，敢望下堦迎。','',''),('quantangshi-31958','落第东归逢僧伯阳','賈島','quantangshi','','卷32','相逢须语笑，人世别离频。
晓至长侵月，思乡动隔春。
见僧心暂静，从俗事多迍。
宇宙诗名小，山河客路新。
翠桐犹入爨，清镜未辞尘。
逸足思奔骥，随羣且退鳞。
宴乖红杏寺，愁在绿杨津。
老病难为乐，开眉赖故人。','',''),('quantangshi-31959','皇甫主簿期游山不及赴','賈島','quantangshi','','卷32','休官匹马在，新意入山中。
更住应难遂，前期恨不同。
集蝉苔树僻，留客雨堂空。
深夜谁相访，惟当清净翁。','',''),('quantangshi-31960','宿成湘林下','賈島','quantangshi','','卷32','相访夕阳时，千株木未衰。
石泉流出谷，山雨滴栖鸱。
漏向灯听数，酒因客寝迟。
今宵不尽兴，更有月明期。','',''),('quantangshi-31961','喜雍陶至','賈島','quantangshi','','卷32','今朝笑语同，几日百忧中。
鸟度劒门静，蛮归泸水空。
步霜吟菊畔，待月坐林东。
且莫孤此兴，勿论穷与通。','',''),('quantangshi-31962','酬胡遇','賈島','quantangshi','','卷32','丽句传人口，科名立可图。
移居见山烧，买树带巢乌。
游远风涛急，吟清雪月孤。
却思初识面，仍未有多须。','',''),('quantangshi-31963','宿慈恩寺郁公房','賈島','quantangshi','','卷32','病身来寄宿，自扫一牀闲。
反照临江磬，新秋过雨山。
竹阴移冷月，荷气带禅关。
独住天台意，方从内请还。','',''),('quantangshi-31964','送褚山人归日本','賈島','quantangshi','','卷32','悬帆待秋水，去入杳冥间。
东海几年别，中华此日还。
岸遥生白发，波尽露青山。
隔水相思在，无书也是闲。','',''),('quantangshi-31965','寄韩湘','賈島','quantangshi','','卷32','过岭行多少，潮州涨满川。
花开南去后，水冻北归前。
望鹭吟登阁，听猨泪滴船。
相思堪面话，不着尺书传。','',''),('quantangshi-31966','雨夜寄马戴','賈島','quantangshi','','卷32','芳林杏花树，花落子西东。
今夕曲江雨，寒催朔北风。
乡书沧海绝，隐路翠微通。
寂寂相思际，孤釭残漏中。','',''),('quantangshi-31967','喜无可上人游山回','賈島','quantangshi','','卷32','一食复何如，寻山无定居。
相逢新夏满，不见半年余。
听话龙潭雪，休传鸟道书。
别来还似旧，白发日高梳。','',''),('quantangshi-31968','寄毗陵彻公','賈島','quantangshi','','卷32','身依吴寺老，黄叶几回看。
早讲林霜在，孤禅隙月残。
井通潮浪远，钟与角声寒。
已有南游约，谁言礼谒难。','',''),('quantangshi-31969','送韦琼校书','賈島','quantangshi','','卷32','宾佐兼归觐，此行江汉心。
别离从阙下，道路向山阴。
孤屿消寒沫，空城滴夜霖。
若邪溪畔寺，秋色共谁寻。','',''),('quantangshi-31970','寄刘侍御','賈島','quantangshi','','卷32','衣多苔藓痕，犹拟更趋门。
自夏虽无病，经秋不过原。
积泉留岱鸟，叠岫隔巴猨。
琴月西斋集，如今岂复言。','',''),('quantangshi-31971','送穆少府知眉州','賈島','quantangshi','','卷32','劒门倚青汉，君昔未曾过。
日暮行人少，山深异鸟多。
猨啼和峡雨，栈尽到江波。
一路白云里，飞泉洒薜萝。','',''),('quantangshi-31972','二月晦日留别鄠中友人','賈島','quantangshi','','卷32','立马柳花里，别君当酒酣。
春风渐向北，云雁不飞南。
明晓日初一，今年月又三。
鞭羸去暮色，远岳起烟岚。','',''),('quantangshi-31973','送李校书赴吉期','賈島','quantangshi','','卷32','筮算重重吉，良期讵可迁。
不同牛女夜，是配凤凰年。
佩玉春风里，题章蜡烛前。
诗书与箴训，夫哲又妻贤。','',''),('quantangshi-31974','宿孤馆','賈島','quantangshi','','卷32','落日投村戍，愁生为客途。
寒山晴后绿，秋月夜来孤。
橘树千株在，渔家一半无。
自知风水静，舟系岸边芦。','',''),('quantangshi-31975','哭宗密禅师','賈島','quantangshi','','卷32','鸟道雪岑巅，师亡谁去禅。
几尘增灭后，树色改生前。
层塔当松吹，残踪傍野泉。
唯嗟听经虎，时到坏庵边。','',''),('quantangshi-31976','宿山寺','賈島','quantangshi','','卷32','众岫耸寒色，精庐向此分。
流星透疎木，走月逆行云。
绝顶人来少，高松鹤不羣。
一僧年八十，世事未曾闻。','',''),('quantangshi-31977','送友人如边','賈島','quantangshi','','卷32','去日重阳后，前程菊正芳。
行车辗秋岳，落叶坠寒霜。
云入汉天白，风高碛色黄。
蒲轮待恐晚，求荐向诸方。','',''),('quantangshi-31978','题竹谷上人院','賈島','quantangshi','','卷32','禅庭高鸟道，回望极川原。
樵径连峯顶，石泉通竹根。
木深犹积雪，山浅未闻猨。
欲别尘中苦，愿师贻一言。','',''),('quantangshi-31979','京北原作','賈島','quantangshi','','卷32','登原见城阙，策蹇思炎天。
日午路中客，槐花风处蝉。
远山秦木上，清渭汉陵前。
何事居人世，皆从名利牵。','',''),('quantangshi-31980','寄江上人','賈島','quantangshi','','卷32','紫阁旧房在，新家中岳东。
烟波千里隔，消息一朝通。
寒日汀洲路，秋晴岛屿风。
分明杜陵叶，别后两经红。','',''),('quantangshi-31981','送僧归太白山','賈島','quantangshi','','卷32','坚冰连夏处，太白接青天。
云塞石房路，峯明雨外巅。
夜禅临虎穴，寒漱撇龙泉。
后会不期日，相逢应信缘。','',''),('quantangshi-31982','暮过山村','賈島','quantangshi','','卷32','数里闻寒水，山家少四邻。
怪禽啼旷野，落日恐行人。
初月未终夕，边烽不过秦。
萧条桑柘外，烟火渐相亲。','',''),('quantangshi-31983','鹭鸶','賈島','quantangshi','','卷32','求鱼未得食，沙岸往来行。
岛月独栖影，暮天寒过声。
堕巢因木折，失侣遇弦惊。
频向烟霄望，吾知尔去程。','',''),('quantangshi-31984','内道场僧弘绍','賈島','quantangshi','','卷32','麟德燃香请，长安春几回。
夜闲同像寂，昼定为吾开。
讲罢松根老，经浮海水来。
六年双足履，只步院中苔。','',''),('quantangshi-31985','蒋亭和蔡湘州','賈島','quantangshi','','卷32','蒋宅为亭榭，蔡城东郭门。
潭连秦相井，松老汉朝根。
已积苍苔徧，何曾旧径存。
高斋无事后，时复一携尊。','',''),('quantangshi-31986','光州王建使君水亭作','賈島','quantangshi','','卷32','楚水临轩积，澄鲜一亩余。
柳根连岸尽，荷叶出萍初。
极浦清相似，幽禽到不虚。
夕阳庭际眺，槐雨滴疎疎。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-31987','留别光州王使君建','賈島','quantangshi','','卷32','杜陵千里外，期在末秋归。
既见林花落，须防木叶飞。
楚从何地尽，淮隔数峯微。
回首余霞失，斜阳照客衣。','',''),('quantangshi-31988','宿姚合宅寄张司业籍','賈島','quantangshi','','卷32','闲宵因集会，柱史话先生。
身爱无一事，心期往四明。
松枝影摇动，石磬响寒清。
谁伴南斋宿，月高霜满城。','',''),('quantangshi-31989','哭张籍','賈島','quantangshi','','卷32','精灵归恍惚，石磬韵曾闻。
即日是前古，谁人耕此坟。
旧游孤棹远，故域九江分。
本欲蓬瀛去，餐芝御白云。','',''),('quantangshi-31990','灵准上人院','賈島','quantangshi','','卷32','掩扉当太白，腊数等松椿。
禁漏来遥夜，山泉落近邻。
经声终卷晓，草色几芽春。
海内知名士，交游准上人。','',''),('quantangshi-31991','寄柳舍人宗元','賈島','quantangshi','','卷32','格与功俱造，何人意不降。
一宵三梦柳，孤泊九秋江。
擢第名重列，冲天字几双。
誓为仙者仆，侧执驭风幢。','',''),('quantangshi-31992','送玄岩上人归西蜀','賈島','quantangshi','','卷32','玉垒山中寺，幽深胜概多。
药成彭祖捣，顶受七轮摩。
去腊催今夏，流光等逝波。
会当依粪扫，五岳徧头陀。','',''),('quantangshi-31993','寄宋州田中丞','賈島','quantangshi','','卷32','古郡近南徐，关河万里余。
相思深夜后，未答去秋书。
自别知音少，难忘识面初。
旧山期已久，门掩数畦蔬。','',''),('quantangshi-31994','送朱休归劒南','賈島','quantangshi','','卷32','劒南归受贺，太学赋声雄。
山路长江岸，朝阳十月中。
芽新抽雪茗，枝重集猨枫。
卓氏琴台废，深芜想径通。','',''),('quantangshi-31995','寄长武朱尚书','賈島','quantangshi','','卷32','不日即登坛，枪旗一万竿。
角吹边月没，鼓绝爆雷残。
中国今如此，西荒可取难。
白衣思请谒，徒步在长安。','',''),('quantangshi-31996','送皇甫侍御','賈島','quantangshi','','卷32','晓钟催早朝，自是赴嘉招。
舟泊湘江阔，田收楚泽遥。
雁惊起衰草，猨渴下寒条。
来使黔南日，时应问寂寥。','',''),('quantangshi-31997','郊居即事','賈島','quantangshi','','卷32','住此园林久，其如未是家。
叶书传野意，檐溜煮胡茶。
雨后逢行鹭，更深听远蛙。
自然还往里，多是爱烟霞。','',''),('quantangshi-31998','夜集姚合宅期可公不至','賈島','quantangshi','','卷32','公堂秋雨夜，已是念园林。
何事疾病日，重论山水心。
孤灯明腊后，微雪下更深。
释子乖来约，泉西寒磬音。','',''),('quantangshi-31999','喜李余自蜀至','賈島','quantangshi','','卷32','迢遰岷峨外，西南驿路高。
几程寻嶮栈，独宿听寒涛。
白鸟飞还立，青猨断更号。
往来从此过，词体近风骚。','',''),('quantangshi-32000','王侍御南原庄','賈島','quantangshi','','卷32','买得足云地，新栽药数窠。
峰头盘一径，原下注双河。
春寺闲眠久，晴台独上多。
南斋宿雨后，仍许重来麽。','',''),('quantangshi-32001','送康秀才','賈島','quantangshi','','卷32','俱为落第年，相识落花前。
酒泻两三盏，诗吟十数篇。
行岐逢塞雨，嘶马上津船。
树影高堂下，回时应有蝉。','',''),('quantangshi-32002','送僧','賈島','quantangshi','','卷32','此生披衲过，在世得身闲。
日午游都市，天寒往华山。
言归文字外，意出有无间。
仙掌云边树，巢禽时出关。','',''),('quantangshi-32003','寄魏少府','賈島','quantangshi','','卷32','来时乖面别，终日使人慙。
易记卷中句，难忘灯下谈。
湿苔黏树瘿，瀑布溅房庵。
音信如相惠，移居古井南。','',''),('quantangshi-32004','原居即事言怀赠孙员外','賈島','quantangshi','','卷32','出入土门偏，秋深石色泉。
径通原上草，地接水中莲。
采菌依余枿，拾薪逢刈田。
镊挦白发断，兵阻尺书传。
避路来华省，抄诗上彩牋。
高斋久不到，犹喜未经年。','',''),('quantangshi-32005','登楼','賈島','quantangshi','','卷32','秋日登高望，凉风吹海初。
山川明已久，河汉没无余。
远近涯寥敻，高低中太虚。
赋因王阁笔，思比谢游疎。','',''),('quantangshi-32006','上乐使君救康成公','賈島','quantangshi','','卷32','曾梦诸侯笑，康囚议脱枷。
千根池里藕，一朵火中花。','',''),('quantangshi-32007','[昆]明池泛舟','賈島','quantangshi','','卷32','一枝青竹榜，泛泛绿萍里。
不见钓鱼人，渐入秋塘水。','',''),('quantangshi-32008','送僧','賈島','quantangshi','','卷32','大内曾持论，天南化俗行。
旧房山雪在，春草岳阳生。
晓了莲经义，堪任宝盖迎。
王侯皆护法，何寺讲钟鸣。','',''),('quantangshi-32009','送刘知新往襄阳','賈島','quantangshi','','卷32','此别诚堪恨，荆襄是旧游。
眼光悬欲落，心绪乱难收。
花木三层寺，烟波五相楼。
因君两地去，长使梦悠悠。','',''),('quantangshi-32010','寄慈恩寺郁上人','賈島','quantangshi','','卷32','中秋期夕望，虚室省相容。
北斗生清漏，南山出碧重。
露寒鸠宿竹，鸿过月圆钟。
此夜情应切，衡阳旧住峯。','',''),('quantangshi-32011','送饶州张使君','賈島','quantangshi','','卷32','终南云雨连城阙，去路西江白浪头。
滁上郡斋离昨日，鄱阳农事劝今秋。
道心生向前朝寺，文思来因静夜楼。
借问泊帆干谒者，谁人曾听峡猨愁。','',''),('quantangshi-32012','观冬设上东川杨尚书','賈島','quantangshi','','卷32','匏革奏冬非独乐，军城未晓启重门。
何时却入三台贵，此日空知八座尊。
罗绮舞中收雨点，貔貅阃外卷云根。
逐迁属吏随宾列，拨棹扁舟不忘恩。','',''),('quantangshi-32013','巴兴作','賈島','quantangshi','','卷32','三年未省闻鸿呌，九月何曾见草枯。
寒暑气均思白社，星辰位正忆皇都。
苏卿持节终还汉，葛相行师自渡泸。
乡味朔山林果别，北归期挂海帆孤。','',''),('quantangshi-32014','早蝉','賈島','quantangshi','','卷32','早蝉孤抱芳槐叶，噪向残阳意度秋。
也任一声催我老，堪听两耳畏吟休。
得非下第无高韵，须是青山隐白头。
若问此心嗟叹否，天人不可怨而尤。','',''),('quantangshi-32015','投元郎中','賈島','quantangshi','','卷32','心在潇湘归未期，卷中多是得名诗。
高台聊望清秋色，片水堪留白鹭鸶。
省宿有时闻急雨，朝回尽日伴禅师。
旧文去岁曾将献，蒙与人来说始知。','',''),('quantangshi-32016','阮籍啸台','賈島','quantangshi','','卷33','如闻长啸春风里，荆棘丛边访旧踪。
地接苏门山近远，荒台突兀抵高峰。','',''),('quantangshi-32017','滕校书使院小池','賈島','quantangshi','','卷33','小池谁见凿时初，走水南来十里余。
楼上日斜吹暮角，院中人出锁游鱼。','',''),('quantangshi-32018','送陕府王建司马','賈島','quantangshi','','卷33','司马虽然听晓钟，尚犹高枕恣疎慵。
请诗僧过三门水，卖药人归五老峰。
移舫绿阴深处息，登楼凉夜此时逢。
杜陵惆怅临相饯，未寝月前多屐踪。','',''),('quantangshi-32019','上谷旅夜','賈島','quantangshi','','卷33','世难那堪恨旅游，龙钟更是对穷秋。
故园千里数行泪，邻杵一声终夜愁。
月到寒窗空皓皛，风翻落叶更飕飗。
此心不向常人说，倚识平津万户侯。','',''),('quantangshi-32020','寄无得头陀','賈島','quantangshi','','卷33','夏腊今应三十余，不离树下冢间居。
貌堪良匠抽毫写，行称高僧续传书。
落涧水声来远远，当空月色自如如。
白衣只在青门里，心每相亲迹且疎。','',''),('quantangshi-32021','崔卿池上双白鹭','賈島','quantangshi','','卷33','鹭雏相逐出深笼，顶各有丝茎数同。
洒石多霜移足冷，隔城远树挂巢空。
其如尽在滩声外，何似双飞浦色中。
见此池潭卿自凿，清泠太液底潜通。','',''),('quantangshi-32022','送胡道士','賈島','quantangshi','','卷33','短褐身披满渍苔，灵溪深处观门开。
却从城里移琴去，许到山中寄药来。
临水古坛秋醮罢，宿杉幽鸟夜飞回。
丹梯愿逐真人上，日夕归心白发催。','',''),('quantangshi-32023','寄韩潮州愈','賈島','quantangshi','','卷33','此心曾与木兰舟，直到天南潮水头。
隔岭篇章来华岳，出关书信过泷流。
峰悬驿路残云断，海浸城根老树秋。
一夕瘴烟风卷尽，月明初上浪西楼。','',''),('quantangshi-32024','酬张籍王建','賈島','quantangshi','','卷33','疎林荒宅古坡前，久住还因太守怜。
渐老更思深处隐，多闲数得上方眠。
鼠抛贫屋收田日，雁度寒江拟雪天。
身是龙钟应是分，水曹芸阁枉来篇。','',''),('quantangshi-32025','逢博陵故人彭兵曹','賈島','quantangshi','','卷33','曲阳分散会京华，见说三年住海涯。
别后解餐蓬虆子，向前未识牡丹花。
偶逢日者敎求禄，终傍泉声拟置家。
蹋雪携琴相就宿，夜深开户斗牛斜。','',''),('quantangshi-32026','赠牛山人','賈島','quantangshi','','卷33','二十年中饵茯苓，致书半是老君经。
东都旧住商人宅，南国新修道士亭。
凿石养蜂休买蜜，坐山秤药不争星。
古来隐者多能卜，欲就先生问丙丁。','',''),('quantangshi-32027','送于中丞使回纥册立','賈島','quantangshi','','卷33','君立天骄发使车，册文字字着金书。
渐通青冢乡山尽，欲达皇情译语初。
调角寒城边色动，下霜秋碛雁行疎。
旌旗来往几多日，应向途中见岁除。','',''),('quantangshi-32028','送刘侍御重使江西','賈島','quantangshi','','卷33','时当苦热远行人，石壁飞泉溅马身。
又到钟陵知务大，还浮湓浦属秋新。
早程猨呌云深极，宿馆禽惊叶动频。
前者已闻廉使荐，兼言有画静边尘。','',''),('quantangshi-32029','赠圆上人','賈島','quantangshi','','卷33','诵经千纸得为僧，麈尾持行不拂蝇。
古塔月高闻呪水，新坛日午见烧灯。
一双童子浇红药，百八真珠贯彩绳。
且说近来心里事，仇雠相对似亲朋。','',''),('quantangshi-32030','处州李使君改任遂州因寄赠','賈島','quantangshi','','卷33','庭树几株阴入户，主人何在客闻蝉。
钥开原上高楼锁，瓶汲池东古井泉。
趂静野禽曾后到，休吟邻叟始安眠。
仙都山水谁能忆，西去风涛书满船。','',''),('quantangshi-32031','酬慈恩寺文郁上人','賈島','quantangshi','','卷33','袈裟影入禁池清，犹忆乡山近赤城。
篱落罅间寒蟹过，莓苔石上晚蛩行。
期登野阁闲应甚，阻宿山房疾未平。
闻说又寻南岳去，无端诗思忽然生。','',''),('quantangshi-32032','访鉴玄师侄','賈島','quantangshi','','卷33','维摩青石讲初休，缘访亲宗到普州。
我有军持凭弟子，岳阳溪里汲寒流。','',''),('quantangshi-32033','夜坐','賈島','quantangshi','','卷33','蟋蟀渐多秋不浅，蟾蜍已没夜应深。
三更两鬓几枝雪，一念双峰四祖心。','',''),('quantangshi-32034','送别','賈島','quantangshi','','卷33','门外便伸千里别，无车不得到河梁。
高楼直上百余尺，今日为君南望长。','',''),('quantangshi-32035','闻蝉感怀','賈島','quantangshi','','卷33','新蝉忽发最高枝，不觉立听无限时。
正遇友人来告别，一心分作两般悲。','',''),('quantangshi-32036','夏夜上谷宿开元寺','賈島','quantangshi','','卷33','诗成一夜月中题，便卧松风到曙鸡。
带月时闻山鸟语，郡城知近武陵溪。','',''),('quantangshi-32037','送于总持归京','賈島','quantangshi','','卷33','出家初隷何方寺，上国西明御水东。
却见旧房堦下树，别来二十一春风。','',''),('quantangshi-32038','崔卿池上鹤','賈島','quantangshi','','卷33','月中时呌叶纷纷，不异洞庭霜夜闻。
翎羽如今从放长，犹能飞起向孤云。','',''),('quantangshi-32039','登田中丞高亭','賈島','quantangshi','','卷33','高亭林表迥嵯峨，独坐秋宵不寝多。
玉兔玉人歌里出，白云难似莫相和。','',''),('quantangshi-32040','友人婚杨氏催妆','賈島','quantangshi','','卷33','不知今夕是何夕，催促阳台近镜台。
谁道芙蓉水中种，青铜镜里一枝开。','',''),('quantangshi-32041','酬朱侍御望月见寄','賈島','quantangshi','','卷33','他寝此时吾不寝，近秋三五日逢晴。
相思唯有霜台月，望尽孤光见却生。','',''),('quantangshi-32042','题韦云叟草堂','賈島','quantangshi','','卷33','新起此堂开北窗，当窗山隔一重江。
