老僧不出迎朝客，已住上方三十年。','',''),('quantangshi-32053','早秋寄题天竺灵隐寺','賈島','quantangshi','','卷33','峰前峰后寺新秋，绝顶高窗见沃洲。
人在定中闻蟋蟀，鹤从栖处挂猕猴。
山钟夜渡空江水，汀月寒生古石楼。
心忆悬帆身未遂，谢公此地昔年游。','',''),('quantangshi-32054','黎阳寄姚合','賈島','quantangshi','','卷33','魏都城里曾游熟，才子斋中止泊多。
去日绿杨垂紫陌，归时白草夹黄河。
新诗不觉千回咏，古镜曾经几度磨。
惆怅心思滑台北，满杯浓酒与愁和。','',''),('quantangshi-32055','送崔约秀才','賈島','quantangshi','','卷33','归宁仿髴三千里，月向船窗见几宵。
