可能在世无成事，不觉离家作老人。
中岳深林秋独往，南原多草夜无邻。
经年抱疾谁来问，野鸟相过啄木频。','',''),('quantangshi-32057','夏日寄高洗马','賈島','quantangshi','','卷33','三十年来长在客，两三行泪忽然垂。
