自夸勋业重，开府是官阶。','',''),('quantangshi-32093','春行','賈島','quantangshi','','卷33','去去行人远，尘随马不穷。
旅情斜日后，春色早烟中。
流水穿空馆，闲花发故宫。
旧乡千里思，池上绿杨风。','',''),('quantangshi-32094','题郑常侍厅前竹','賈島','quantangshi','','卷33','绿竹临诗酒，婵娟思不穷。
乱枝低积雪，繁叶亚寒风。
萧飒疑泉过，萦回有迳通。
侵庭根出土，隔壁笋成丛。
疎影纱窗外，清音宝瑟中。
卷帘终日看，欹枕几秋同。
万顷歌王子，千竿伴阮公。
露光怜片片，雨润爱蒙蒙。
嶰谷蛮湖北，湘川灀水东。
何如轩槛侧，苍翠褭长空。','',''),('quantangshi-32095','早行','賈島','quantangshi','','卷33','早起赴前程，邻鸡尚未鸣。
主人灯下别，羸马暗中行。
蹋石新霜滑，穿林宿鸟惊。
远山钟动后，曙色渐分明。','',''),('quantangshi-32096','送人南归','賈島','quantangshi','','卷33','分手向天涯，迢迢泛海波。
虽然南地远，见说北人多。
山暖花常发，秋深雁不过。
炎方饶胜事，此去莫蹉跎。','',''),('quantangshi-32097','送人南游','賈島','quantangshi','','卷33','此别天涯远，孤舟泛海中。
夜行常认火，帆去每因风。
蛮国人多富，炎方语不同。
雁飞难度岭，书信若为通。','',''),('quantangshi-32098','送道者','賈島','quantangshi','','卷33','独向山中见，今朝又别离。
一心无挂住，万里独何之。
到处绝烟火，逢人话古时。
此行无弟子，白犬自相随。','',''),('quantangshi-32099','风蝉','賈島','quantangshi','','卷33','风蝉旦夕鸣，伴叶送新声。
故里客归尽，水边身独行。
噪轩高树合，惊枕暮山横。
听处无人见，尘埃满甑生。','',''),('quantangshi-32100','清明日园林寄友人','賈島','quantangshi','','卷33','今日清明节，园林胜事偏。
晴风吹柳絮，新火起厨烟。
杜草开三迳，文章忆二贤。
几时能命驾，对酒落花前。','',''),('quantangshi-32101','上杜驸马','賈島','quantangshi','','卷33','玉山突兀压干坤，出得朱门入戟门。
妻是九重天子女，身为一品令公孙。
鸳鸯殿里参皇后，龙凤堂前贺至尊。
今日澧阳非久驻，伫为霖雨拜新恩。','',''),('quantangshi-32102','莲峰歌','賈島','quantangshi','','卷33','锦砾潺湲玉溪水，晓来微雨藤花紫。
冉冉山鸡红尾长，一声樵斧惊飞起。
松刺梳空石差齿，烟香风软人参蕊。
阳崖一梦伴云根，仙菌灵芝梦魂里。','',''),('quantangshi-32103','壮士吟','賈島','quantangshi','','卷33','壮士不曾悲，悲即无回期。
如何易水上，未歌先泪垂。','',''),('quantangshi-32104','题兴化园亭','賈島','quantangshi','','卷33','破却千家作一池，不栽桃李种蔷薇。
蔷薇花落秋风起，荆棘满庭君始知。','',''),('quantangshi-32105','竹','賈島','quantangshi','','卷33','篱外清阴接药栏，晓风交戛碧琅玕。
子猷没后知音少，粉节霜筠漫岁寒。','',''),('quantangshi-32106','李斯井','賈島','quantangshi','','卷33','井存上蔡南门外，置此井时来相秦。
断绠数寻垂古甃，取将寒水是何人。','',''),('quantangshi-32107','题诗后','賈島','quantangshi','','卷33','二句三年得，一吟双泪流。
知音如不赏，归卧故山秋。','',''),('quantangshi-32108','送友人之南陵','賈島','quantangshi','','卷33','莫叹徒劳向宦途，不羣气岸有谁如。
南陵暂掌仇香印，北阙终行贾谊书。
好趂江山寻胜境，莫辞韦杜别幽居。
少年跃马同心使，免得诗中道跨驴。','',''),('quantangshi-32109','寻人不遇','賈島','quantangshi','','卷33','闻说到扬州，吹箫有旧游。
人来多不见，莫是上迷楼。','',''),('quantangshi-32110','寻隐者不遇','賈島','quantangshi','','卷33','松下问童子，言师采药去。
只在此山中，云深不知处。','',''),('quantangshi-32111','行次汉上','賈島','quantangshi','','卷33','习家池沼草萋萋，岚树光中信马蹄。
汉主庙前湘水碧，一声风角夕阳低。','',''),('quantangshi-32112','马嵬','賈島','quantangshi','','卷33','长川几处树青青，孤驿危楼对翠屏。
一自上皇惆怅后，至今来往马蹄腥。','',''),('quantangshi-32113','冬夜送人','賈島','quantangshi','','卷33','平明走马上村桥，花落梅溪雪未消。
日短天寒愁送客，楚山无限路迢迢。','',''),('quantangshi-32114','句','賈島','quantangshi','','卷33','晴风吹柳絮，新火起厨烟。
长江风送客，孤馆雨留人。
古岸崩将尽，平沙长未休。
不如牛与羊，犹得日暮归。','',''),('quantangshi-32115','鸡鸣埭曲','溫庭筠','quantangshi','','卷33','南朝天子射雉时，银河耿耿星参差。
铜壶漏断梦初觉，宝马尘高人未知。
鱼跃莲东荡宫沼，蒙蒙御柳悬栖鸟。
红妆万户镜中春，碧树一声天下晓。
盘踞势穷三百年，朱方杀气成愁烟。
彗星拂地浪连海，战鼓渡江尘涨天。
绣龙画雉填宫井，野火风驱烧九鼎。
殿巢江燕砌生蒿，十二金人霜炯炯。
芊绵平绿台城基，暖色春容荒古陂。
宁知玉树后庭曲，留待野棠如雪枝。','',''),('quantangshi-32116','织锦词','溫庭筠','quantangshi','','卷33','丁东细漏侵琼瑟，影转高梧月初出。
簇簌金梭万缕红，鸳鸯艳锦初成匹。
锦中百结皆同心，蘂乱云盘相间深。
此意欲传传不得，玫瑰作柱朱弦琴。
为君裁破合欢被，星斗迢迢共千里。
象尺熏炉未觉秋，碧池已有新莲子。','',''),('quantangshi-32117','夜宴谣','溫庭筠','quantangshi','','卷33','长钗坠发双蜻蜓，碧尽山斜开画屏。
虬须公子五侯客，一饮千钟如建瓴。
鸾咽奼唱圆无节，眉歛湘烟袖回雪。
清夜恩情四座同，莫令沟水东西别。
亭亭蜡泪香珠残，暗露晓风罗幕寒。
飘颻戟带俨相次，二十四枝龙画竿。
裂管萦弦共繁曲，芳樽细浪倾春醁。
高楼客散杏花多，脉脉新蟾如瞪目。','',''),('quantangshi-32118','莲浦谣','溫庭筠','quantangshi','','卷33','鸣桡轧轧溪溶溶，废绿平烟吴苑东。
水清莲媚两相向，镜里见愁愁更红。
白马金鞭大堤上，西江日夕多风浪。
荷心有露似骊珠，不是真圆亦摇荡。','',''),('quantangshi-32119','郭处士击瓯歌','溫庭筠','quantangshi','','卷33','佶栗金虬石潭古，勺陂潋滟幽修语。
湘君宝马上神云，碎佩丛铃满烟雨。
吾闻三十六宫花离离，软风吹春星斗稀。
玉晨冷磬破昏梦，天露未干香着衣。
兰钗委坠垂云发，小响丁当逐回雪。
晴碧烟滋重叠山，罗屏半掩桃花月。
太平天子驻云车，龙炉勃郁双蟠拏。
宫中近臣抱扇立，侍女低鬟落翠花。
乱珠触续正跳荡，倾头不觉金乌斜。
我亦为君长叹息，缄情远寄愁无色。
莫霑香梦绿杨丝，千里春风正无力。','',''),('quantangshi-32120','遐水谣','溫庭筠','quantangshi','','卷33','天兵九月渡遐水，马踏沙鸣惊雁起。
杀气空高万里情，塞寒如箭伤眸子。
狼烟堡上霜漫漫，枯叶号风天地干。
犀带鼠裘无暖色，清光炯冷黄金鞍。
虏尘如雾昏亭障，陇首年年汉飞将。
麟阁无名期未归，楼中思妇徒相望。','',''),('quantangshi-32121','晓仙谣','溫庭筠','quantangshi','','卷33','玉妃唤月归海宫，月色澹白涵春空。
银河欲转星靥靥，碧浪叠山埋早红。
宫花有露如新泪，小苑丛丛入寒翠。
绮阁空传唱漏声，网轩未辨凌云字。
遥遥珠帐连湘烟，鹤扇如霜金骨仙。
碧箫曲尽彩霞动，下视九州皆悄然。
秦王女骑红尾凤，半空回首晨鸡弄。
雾盖狂尘亿兆家，世人犹作牵情梦。','',''),('quantangshi-32122','锦城曲','溫庭筠','quantangshi','','卷33','蜀山攒黛留晴雪，簝笋蕨芽萦九折。
江风吹巧剪霞绡，花上千枝杜鹃血。
杜鹃飞入岩下丛，夜呌思归山月中。
巴水漾情情不尽，文君织得春机红。
怨魄未归芳草死，江头学种相思子。
树成寄与望乡人，白帝荒城五千里。','',''),('quantangshi-32123','生禖屏风歌','溫庭筠','quantangshi','','卷33','玉墀暗接昆仑井，井上无人金索冷。
画壁阴森九子堂，阶前细月铺花影。
绣屏银鸭香蓊蒙，天上梦归花绕丛。
宜男漫作后庭草，不似樱桃千子红。','',''),('quantangshi-32124','嘲春风','溫庭筠','quantangshi','','卷33','春风何处好，别殿饶芳草。
苒袅转鸾旗，萎蕤吹雉葆。
扬芳历九门，澹荡入兰荪。
争奈白团扇，时时偷主恩。','',''),('quantangshi-32125','舞衣曲','溫庭筠','quantangshi','','卷33','藕肠纤缕抽轻春，烟机漠漠娇娥嚬。
金梭淅沥透空薄，剪落交刀吹断云。
张家公子夜闻雨，夜向兰堂思楚舞。
蝉衫麟带压愁香，偷得莺簧鏁金缕。
管含兰气娇语悲，胡槽雪腕鸳鸯丝。
芙蓉力弱应难定，杨柳风多不自持。
回嚬笑语西牕客，星斗寥寥波脉脉。
不逐秦王卷象牀，满楼明月梨花白。','',''),('quantangshi-32126','张静婉采莲歌','溫庭筠','quantangshi','','卷33','兰膏坠发红玉春，燕钗拖颈抛盘云。
城边杨柳向娇晚，门前沟水波粼粼。
麒麟公子朝天客，珂马璫璫度春陌。
掌中无力舞衣轻，剪断鲛绡破春碧。
抱月飘烟一尺腰，麝脐龙髓怜娇娆。
秋罗拂水碎光动，露重花多香不销。
鸂鶒交交塘水满，绿芒如粟莲茎短。
一夜西风送雨来，粉痕零落愁红浅。
船头折藕丝暗牵，藕根莲子相留连。
郎心似月月未缺，十五十六清光圆。','',''),('quantangshi-32127','湘宫人歌','溫庭筠','quantangshi','','卷33','池塘芳草湿，夜半东风起。
生绿画罗屏，金壶贮春水。
黄粉楚宫人，芳花玉刻鳞。
娟娟照棊烛，不语两含嚬。','',''),('quantangshi-32128','黄昙子歌','溫庭筠','quantangshi','','卷33','参差绿蒲短，摇艳云塘满。
红潋荡融融，莺翁鸂鶒暖。
萋芊小成路，马上修蛾嬾。
罗衫褭回风，点粉金鹂卵。','',''),('quantangshi-32129','觱篥歌','溫庭筠','quantangshi','','卷33','蜡烟如纛新蟾满，门外平沙草芽短。
黑头丞相九天归，夜听飞琼吹朔管。
情远气调兰蕙薰，天香瑞彩含絪緼。
皓然纤指都揭血，日暖碧霄无片云。
含商咀征双幽咽，软縠疎罗共萧屑。
不尽长圆叠翠愁，柳风吹破澄潭月。
鸣梭淅沥金丝蘂，恨语殷勤陇头水。
汉将营前万里沙，更深一一霜鸿起。
十二楼前花正繁，交枝簇蔕连壁门。
景阳宫女正愁绝，莫使此声催断魂。','',''),('quantangshi-32130','照影曲','溫庭筠','quantangshi','','卷33','景阳妆罢琼牕暖，欲照澄明香步嬾。
桥上衣多抱彩云，金鳞不动春塘满。
黄印额山轻为尘，翠鳞红穉俱含嚬。
桃花百媚如欲语，曾为无双今两身。','',''),('quantangshi-32131','拂舞词','溫庭筠','quantangshi','','卷33','黄河怒浪连天来，大响谹谹如殷雷。
龙伯驱风不敢上，百川喷雪高崔嵬。
二十三弦何太哀，请公勿渡立徘徊。
下有狂蛟锯为尾，裂帆截棹磨霜齿。
神椎凿石塞神潭，白马䟃𧽼赤尘起。
公乎跃马扬玉鞭，灭没高蹄日千里。','',''),('quantangshi-32132','太液池歌','溫庭筠','quantangshi','','卷33','腥鲜龙气连清防，花风漾漾吹细光。
叠澜不定照天井，倒影荡摇晴翠长。
平碧浅春生绿塘，云容雨态连青苍。
夜深银汉通柏梁，二十八宿朝玉堂。','',''),('quantangshi-32133','雉场歌','溫庭筠','quantangshi','','卷33','茭叶萋萋接烟曙，鸡鸣埭上梨花露。
彩杖锵锵已合围，绣翎白颈遥相妬。
雕尾扇张金缕高，碎铃素拂骊驹豪。
绿场红迹未相接，箭发铜牙伤彩毛。
麦陇桑阴小山晚，六虬归去凝笳远。
城头却望几含情，青亩春芜连石苑。','',''),('quantangshi-32134','雍台歌','溫庭筠','quantangshi','','卷33','太子池南楼百尺，入窓新树疎帘隔。
黄金铺首画钩陈，羽葆停幢拂交戟。
盘纡阑楯临高台，帐殿临流鸾扇开。
早雁惊鸣细波起，映花卤簿龙飞回。','',''),('quantangshi-32135','吴苑行','溫庭筠','quantangshi','','卷33','锦雉双飞梅结子，平春远绿牕中起。
吴江澹画水连空，三尺屏风隔千里。
小苑有门红扇开，天丝舞蝶共徘徊。
绮户雕楹长若此，韶光岁岁如归来。','',''),('quantangshi-32136','常林欢歌','溫庭筠','quantangshi','','卷33','宜城酒熟花覆桥，沙晴绿鸭鸣咬咬。
穠桑绕舍麦如尾，幽轧鸣机双燕巢。
马声特特荆门道，蛮水扬光色如草。
锦荐金炉梦正长，东家咿喔鸡鸣早。','',''),('quantangshi-32137','塞寒行','溫庭筠','quantangshi','','卷33','燕弓弦劲霜封瓦，朴簌寒雕睇平野。
一点黄尘起雁喧，白龙堆下千蹄马。
河源怒浊风如刀，剪断朔云天更高。
晚出榆关逐征北，惊沙飞迸冲貂袍。
心许凌烟名不灭，年年锦字伤离别。
彩毫一画竟何荣，空使青楼泪成血。','',''),('quantangshi-32138','湖阴词','溫庭筠','quantangshi','','卷33','祖龙黄须珊瑚鞭，铁骢金面青连钱。
虎髯拔劒欲成梦，日压贼营如血鲜。
海旗风急惊眠起，甲重光摇照湖水。
苍黄追骑尘外归，森索妖星阵前死。
五陵愁碧春萋萋，霸川玉马空中嘶。
羽书如电入青璅，雪腕如槌催画鞞。
白虬天子金煌铓，高临帝座回龙章。
吴波不动楚山晚，花压阑干春昼长。','',''),('quantangshi-32139','蒋侯神歌','溫庭筠','quantangshi','','卷33','楚神铁马金鸣珂，夜动蛟潭生素波。
商风刮水报西帝，庙前古树蟠白虵。
吴王赤斧斫云阵，画堂列壁丛霜刃。
巫娥传意托悲丝，铎语琅琅理双鬓。
湘烟刷翠湘山斜，东方日出飞神鸦。
青云自有黑龙子，潘妃莫结丁香花。','',''),('quantangshi-32140','汉皇迎春词','溫庭筠','quantangshi','','卷33','春草芊芊晴扫烟，宫城大锦红殷鲜。
海日初融照仙掌，淮王小队缨铃响。
猎猎东风焰赤旗，画神金甲葱茏网。
钜公步辇迎句芒，复道扫尘燕彗长。
豹尾竿前赵飞燕，柳风吹尽眉间黄。
碧草含情杏花喜，上林莺啭游丝起。
宝马摇环万骑归，恩光暗入帘栊里。','',''),('quantangshi-32141','兰塘词','溫庭筠','quantangshi','','卷33','塘水汪汪凫唼喋，忆上江南木兰檝。
绣颈金须荡倒光，团团皱绿鸡头叶。
露凝荷卷珠净圆，紫菱刺短浮根缠。
小姑归晚红妆浅，镜里芙蓉照水鲜。
东沟潏潏劳回首，欲寄一杯琼液酒。
知道无郎却有情，长敎月照相思柳。','',''),('quantangshi-32142','晚归曲','溫庭筠','quantangshi','','卷33','格格水禽飞带波，孤光斜起夕阳多。
湖西山浅似相笑，菱刺惹衣攒黛蛾。
青丝系船向江木，兰芽出土吴江曲。
水极晴摇泛滟红，草平春染烟绵绿。
玉鞭骑马杨叛儿，刻金作凤光参差。
丁丁暖漏滴花影，催入景阳人不知。
弯堤弱柳遥相瞩，雀扇团圆掩香玉。
莲塘艇子归不归，柳暗桑穠闻布谷。','',''),('quantangshi-32143','故城曲','溫庭筠','quantangshi','','卷33','漠漠沙堤烟，堤西雉子斑。
雉声何角角，麦秀桑阴闲。
游丝荡平绿，明灭时相续。
白马金络头，东风故城曲。
故城殷贵嫔，曾占未来春。
自从香骨化，飞作马蹄尘。','',''),('quantangshi-32144','昆明池水战词','溫庭筠','quantangshi','','卷33','汪汪积水光连空，重叠细纹晴漾红。
赤帝龙孙鳞甲怒，临流一盼生阴风。
鼍鼓三声报天子，雕旌兽舰凌波起。
雷吼涛惊白石山，石鲸眼裂蟠蛟死。
溟池海浦俱喧豗，青帜白旌相次来。
箭羽枪缨三百万，踏翻西海生尘埃。
茂陵仙去菱花老，唼唼游鱼近烟岛。
渺莽残阳钓艇归，绿头江鸭眠沙草。','',''),('quantangshi-32145','谢公墅歌','溫庭筠','quantangshi','','卷33','朱雀航南绕香陌，谢郎东墅连春碧。
鸠眠高柳日方融，绮榭飘颻紫庭客。
文楸方罫花参差，心阵未成星满池。
四座无喧梧竹静，金蝉玉柄俱持颐。
对局含情见千里，都城已得长虵尾。
江南王气系疎襟，未许苻坚过淮水。','',''),('quantangshi-32146','罩鱼歌','溫庭筠','quantangshi','','卷33','朝罩罩城南，暮罩罩城西。
两浆鸣幽幽，莲子相高低。
持罩入深水，金鳞大如手。
鱼尾迸圆波，千珠落湘藕。
风飔飔，雨离离，菱尖茭刺鸂鶒飞。
水连网眼白如影，淅沥篷声寒点微。
楚岸有花花盖屋，金塘柳色前溪曲。
悠溶杳若去无穷，五色澄潭鸭头绿。','',''),('quantangshi-32147','春洲曲','溫庭筠','quantangshi','','卷33','韶光染色如蛾翠，绿湿红鲜水容媚。
苏小慵多兰渚闲，融融浦日䴔䴖寐。
紫骝蹀躞金衔嘶，岸上扬鞭烟草迷。
门外平桥连柳堤，归来晚树黄莺啼。','',''),('quantangshi-32148','台城晓朝曲','溫庭筠','quantangshi','','卷33','司马门前火千炬，兰干星斗天将曙。
朱网龛鬖丞相车，晓随叠鼓朝天去。
博山镜树香䒠茸，褭褭浮航金画龙。
大江歛势避辰极，两阙深严烟翠浓。','',''),('quantangshi-32149','走马楼三更曲','溫庭筠','quantangshi','','卷33','春姿暖气昏神沼，李树拳枝紫芽小。
玉皇夜入未央宫，长火千条照栖鸟。
马过平桥通画堂，虎幡龙戟风飘扬。
帘间清唱报寒点，丙舍无人遗烬香。','',''),('quantangshi-32150','达摩支曲','溫庭筠','quantangshi','','卷33','捣麝成尘香不灭，拗莲作寸丝难绝。
红泪文姬洛水春，白头苏武天山雪。
君不见无愁高纬花漫漫，漳浦宴余清露寒。
一旦臣僚共囚虏，欲吹羌管先丸澜。
旧臣头鬓霜华早，可惜雄心醉中老。
万古春归梦不归，邺城风雨连天草。','',''),('quantangshi-32151','阳春曲','溫庭筠','quantangshi','','卷33','云母空牕晓烟薄，香昏龙气凝晖阁。
霏霏雾雨杏花天，帘外春威着罗幕。
曲阑伏槛金麒麟，沙苑芳郊连翠茵。
廐马何能啮芳草，路人不敢随流尘。','',''),('quantangshi-32152','湘东宴曲','溫庭筠','quantangshi','','卷33','湘东夜宴金貂人，楚女含情娇翠嚬。
玉管将吹插钿带，锦囊斜拂双麒麟。
重城漏断孤帆去，唯恐琼签报天曙。
万户沈沈碧树圆，云飞雨散知何处。
欲上香车俱脉脉，清歌响断银屏隔。
堤外红尘蜡炬归，楼前澹月连江白。','',''),('quantangshi-32153','东郊行','溫庭筠','quantangshi','','卷33','鬬鸡台下东西道，柳覆班骓蝶萦草。
坱霭韶容鏁澹愁，青筐叶尽蚕应老。
绿渚幽香生白苹，差差小浪吹鱼鳞。
王孙骑马有归意，林彩着空如细尘。
安得人生各相守，烧船破栈休驰走。
世上方应无别离，路傍更长千株柳。','',''),('quantangshi-32154','水仙谣','溫庭筠','quantangshi','','卷33','水客夜骑红鲤鱼，赤鸾双鹤蓬瀛书。
轻尘不起雨新霁，万里孤光含碧虚。
露魄冠轻见云发，寒丝七炷香泉咽。
夜深天碧乱山姿，光碎平波满船月。','',''),('quantangshi-32155','东峯歌','溫庭筠','quantangshi','','卷33','锦砾潺湲玉溪水，晓来微雨藤花紫。
冉冉山鸡红尾长，一声樵斧惊飞起。
松刺梳空石差齿，烟香风软人参蘂。
阳崖一梦伴云根，仙菌灵芝梦魂里。','',''),('quantangshi-32156','会昌丙寅丰岁歌','溫庭筠','quantangshi','','卷33','丙寅岁，休牛马。
风如吹烟，日如渥赭。
九重天子调天下，春绿将年到西野。
西野翁，生儿童。
门前好树青䒠茸，䒠茸单衣麦田路。
村南娶妇桃花红，新姑车右及门柱，粉项韩凭双扇中。
喜气自能成岁丰，农祥尔物来争功。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-32157','碌碌古词','溫庭筠','quantangshi','','卷33','左亦不碌碌，右亦不碌碌。
野草自根肥，羸牛生健犊。
融蜡作杏蒂，男儿不恋家。
春风破红意，女颊如桃花。
忠言未见信，巧语翻咨嗟。
一鞘无两刃，徒劳油壁车。','',''),('quantangshi-32158','春野行','溫庭筠','quantangshi','','卷33','草浅浅，春如剪。
花压李娘愁，饥蚕欲成茧。
东城年少气堂堂，金丸惊起双鸳鸯。
含羞更问卫公子，月到枕前春梦长。','',''),('quantangshi-32159','醉歌','溫庭筠','quantangshi','','卷33','檐柳初黄燕新乳，晓碧芊绵过微雨。
树色深含台榭情，莺声巧作烟花主。
锦袍公子陈杯觞，拨醅百瓮春酒香。
入门下马问谁在，降堦握手登华堂。
临邛美人连山眉，低抱琵琶含怨思。
朔风绕指我先笑，明月入怀君自知。
劝君莫惜金樽酒，年少须臾如覆手。
辛勤到老慕箪瓢，于我悠悠竟何有。
洛阳卢仝称文房，妻子脚秃舂黄粮。
阿耋光颜不识字，指麾豪儁如驱羊。
天犀压断朱鼹鼠，瑞锦惊飞金凤皇。
其余岂足霑牙齿，欲用何能报天子。
驽马垂头抢暝尘，骅骝一日行千里。
但有沈冥醉客家，支颐瞪目持流霞。
唯恐南国风雨落，碧芜狼籍棠梨花。','',''),('quantangshi-32160','江南曲','溫庭筠','quantangshi','','卷33','妾家白苹浦，日上芙蓉檝。
轧轧摇浆声，移舟入茭叶。
溪长茭叶深，作底难相寻。
避郎郎不见，鸂鶒自浮沈。
拾萍萍无根，采莲莲有子。
不作浮萍生，宁为藕花死。
岸傍骑马郎，乌帽紫游缰。
含愁复含笑，回首问横塘。
妾住金陵浦，门前朱雀航。
流苏持作帐，芙蓉持作梁。
出入金犊幰，兄弟侍中郎。
前年学歌舞，定得郎相许。
连娟眉绕山，依约腰如杵。
凤管悲若咽，鸾弦娇欲语。
扇薄露红铅，罗轻压金缕。
明月西南楼，珠帘玳瑁钩。
横波巧能笑，弯蛾不识愁。
花开子留树，草长根依土。
早闻金沟远，底事归郎许。
不学杨白花，朝朝泪如雨。','',''),('quantangshi-32161','堂堂曲','溫庭筠','quantangshi','','卷33','钱唐岸上春如织，淼淼寒潮带睛色。
淮南游客马连嘶，碧草迷人归不得。
风飘客意如吹烟，纤指殷勤伤雁弦。
一曲堂堂红烛筵，长鲸泻酒如飞泉。','',''),('quantangshi-32162','惜春词','溫庭筠','quantangshi','','卷33','百舌问花花不语，低回似恨横塘雨。
蜂争粉蘂蝶分香，不似垂杨惜金缕。
愿君留得长妖韶，莫逐东风还荡摇。
秦女含嚬向烟月，愁红带露空迢迢。','',''),('quantangshi-32163','春愁曲','溫庭筠','quantangshi','','卷33','红丝穿露珠帘冷，百尺哑哑下纤绠。
远翠愁山入卧屏，两重云母空烘影。
凉簪坠发春眠重，玉兔煴香柳如梦。
锦叠空牀委堕红，飔飔扫尾双金凤。
蜂喧蝶驻俱悠扬，柳拂赤栏纤草长。
觉后梨花委平绿，春风和雨吹池塘。','',''),('quantangshi-32164','苏小小歌','溫庭筠','quantangshi','','卷33','买莲莫破券，买酒莫解金。
酒里春容抱离恨，水中莲子怀芳心。
吴宫女儿腰似束，家在钱唐小江曲。
一自檀郎逐便风，门前春水年年绿。','',''),('quantangshi-32165','春江花月夜词','溫庭筠','quantangshi','','卷33','玉树歌阑海云黑，花庭忽作青芜国。
秦淮有水水无情，还向金陵漾春色。
杨家二世安九重，不御华芝嫌六龙。
百幅锦帆风力满，连天展尽金芙蓉。
珠翠丁星复明灭，龙头劈浪哀笳发。
千里涵空澄水魂，万枝破鼻飘香雪。
漏转霞高沧海西，颇黎枕上闻天鸡。
蛮弦代写曲如语，一醉昏昏天下迷。
四方倾动烟尘起，犹在浓香梦魂里。
后主荒宫有晓莺，飞来只隔西江水。','',''),('quantangshi-32166','懊恼曲','溫庭筠','quantangshi','','卷33','藕丝作线难胜针，蘂粉染黄那得深。
玉白兰芳不相顾，青楼一笑轻千金。
莫言自古皆如此，健劒刜钟铅绕指。
三秋庭绿尽迎霜，惟有荷花守红死。
庐江小吏朱斑轮，柳缕吐芽香玉春。
两股金钗已相许，不令独作空成尘。
悠悠楚水流如马，恨紫愁红满平野。
野土千年怨不平，至今烧作鸳鸯瓦。','',''),('quantangshi-32167','三洲词','溫庭筠','quantangshi','','卷33','团圆莫作波中月，洁白莫为枝上雪。
月随波动碎潾潾，雪似梅花不堪折。
李娘十六青丝发，画带双花为君结。
门前有路轻别离，唯恐归来旧香灭。','',''),('quantangshi-32168','春晓曲','溫庭筠','quantangshi','','卷33','家临长信往来道，乳燕双双拂烟草。
油壁车轻金犊肥，流苏帐晓春鸡早。
笼中娇鸟暖犹睡，帘外落花闲不扫。
衰桃一树近前池，似惜红颜镜中老。','',''),('quantangshi-32169','猎骑辞','溫庭筠','quantangshi','','卷33','早辞平扆殿，夕奉湘南宴。
香兔抱微烟，重鳞叠轻扇。
蚕饥使君马，雁避将军箭。
宝柱惜离弦，流黄悲赤县。
理钗低舞鬓，换袖回歌面。
晚柳未如丝，春花已如霰。
所嗟故里曲，不及青楼宴。','',''),('quantangshi-32170','西州词','溫庭筠','quantangshi','','卷33','悠悠复悠悠，昨日下西州。
西州风色好，遥见武昌楼。
武昌何郁郁，侬家定无匹。
小妇被流黄，登楼抚瑶瑟。
朱弦繁复轻，素手直凄清。
一弹三四解，掩抑似含情。
南楼登且望，西江广复平。
艇子摇两桨，催过石头城。
门前乌臼树，惨澹天将曙。
鸂鶒飞复还，郎随早帆去。
回头语同伴，定复负情侬。
去帆不安幅，作抵使西风。
他日相寻索，莫作西州客。
西州人不归，春草年年碧。','',''),('quantangshi-32171','烧歌','溫庭筠','quantangshi','','卷33','起来望南山，山火烧山田。
微红夕如灭，短焰复相连。
差差向岩石，冉冉凌青壁。
低随回风尽，远照檐茅赤。
邻翁能楚言，倚插欲澘然。
自言楚越俗，烧畲为早田。
豆苗虫促促，篱上花当屋。
废栈豕归栏，广场鸡啄粟。
新年春雨晴，处处赛神声。
持钱就人卜，敲瓦隔林鸣。
卜得山上卦，归来桑枣下。
吹火向白茅，腰镰映赬蔗。
风驱槲叶烟，槲树连平山。
迸星拂霞外，飞烬落堦前。
仰面呻复嚏，鸦娘咒丰岁。
谁知苍翠容，尽作官家税。','',''),('quantangshi-32172','长安寺','溫庭筠','quantangshi','','卷33','仁祠写露宫，长安佳气浓。
烟树含葱蒨，金刹映䒠茸。
绣户香焚象，珠网玉盘龙。
宝题斜翡翠，天井倒芙蓉。
幡长回远吹，牕虚含晓风。
游骑迷青锁，归鸟思华钟。
云栱承跗逦，羽葆背花重。
所嗟莲社客，轻荡不相从。','',''),('quantangshi-32173','和沈参军招友生观芙蓉池','溫庭筠','quantangshi','','卷33','桂栋坐清晓，瑶琴商凤丝。
况闻楚泽香，适与秋风期。
遂从棹萍客，静啸烟草湄。
倒影回澹荡，愁红媚涟漪。
湘茎久鲜涩，宿雨增离披。
而我江海意，楚游动梦思。
北渚水云叶，南塘烟雾枝。
岂亡台榭芳，独与鸥鸟知。
珠坠鱼迸浅，影多凫泛迟。
落英不可攀，返照昏澄陂。','',''),('quantangshi-32174','寓怀','溫庭筠','quantangshi','','卷33','诚足不顾得，妄矜徒有言。
语斯谅未尽，隐显何悠然。
洵彼都邑盛，眷惟车马喧。
自期尊客卿，非意干王孙。
衔知有贞爵，处实非厚颜。
苟无海岱气，奚取壶浆恩。
唯丝南山杨，适我松菊香。
鹏鵾诚未忆，谁谓凌风翔。','',''),('quantangshi-32175','余昔自西滨得兰数本移艺于庭亦既逾岁而芃然蕃殖自余游者未始以芳草为遇矣因悲夫物有厌常而反不若混然者有之焉遂寄情于此','溫庭筠','quantangshi','','卷33','寓赏本殊致，意幽非我情。
吾常有流浅，外物无重轻。
各言艺幽深，彼美香素茎。
岂为赏者设，自保孤根生。
易地无赤株，丽土亦同荣。
赏际林壑近，泛余烟露清。
余怀既郁陶，尔类徒纵横。
妍蚩苟不信，宠辱何为惊。
贞隐谅无迹，激时犹拣名。
幽丛霭绿畹，岂必怀归耕。','',''),('quantangshi-32176','秋日','溫庭筠','quantangshi','','卷33','爽气变昏旦，神臯徧原隰。
烟华久荡摇，石涧仍清急。
柳暗山犬吠，蒲荒水禽立。
菊花明欲迷，枣叶光如湿。
天籁思林岭，车尘倦都邑。
譸张夙所违，悔恡何由入。
芳草秋可藉，幽泉晓堪汲。
牧羊烧外鸣，林果雨中拾。
复此遂闲旷，翛然脱羇絷。
田收鸟雀喧，气肃龙蛇蛰。
佳节足丰穰，良朋阻游集。
沈机日寂寥，葆素常呼吸。
投迹倦攸往，放怀志所执。
良时有东菑，吾将事蓑笠。','',''),('quantangshi-32177','七夕','溫庭筠','quantangshi','','卷33','鸣机札札停金梭，芙蓉澹荡生池波。
神轩红粉陈香罗，凤低蝉薄愁双蛾。
微光奕奕凌天河，鸾咽鹤唳飘颻歌。
弯桥销尽愁奈何，天气骀荡云陂陁。
平明花木有秋意，露湿彩盘蛛网多。','',''),('quantangshi-32178','酬友人','溫庭筠','quantangshi','','卷33','辞荣亦素尚，倦游非夙心。
宁复思金籍，独此卧烟林。
闲云无定貌，佳树有余阴。
坐久芰荷发，钓阑茭苇深。
游鱼自摇漾，浴鸟故浮沈。
唯君清露夕，一为洒烦襟。','',''),('quantangshi-32179','观舞妓','溫庭筠','quantangshi','','卷33','朔音悲嘒管，瑶踏动芳尘。
总袖时增怨，听破复含嚬。
凝腰倚风软，花题照锦春。
朱弦固凄紧，琼树亦迷人。','',''),('quantangshi-32180','边笳曲','溫庭筠','quantangshi','','卷33','朔管迎秋动，雕阴雁来早。
上郡隐黄云，天山吹白草。
嘶马悲寒碛，朝阳照霜堡。
江南戍客心，门外芙蓉老。','',''),('quantangshi-32181','经西坞偶题','溫庭筠','quantangshi','','卷33','摇摇弱柳黄鹂啼，芳草无情人自迷。
日影明灭金色鲤，杏花唼喋青头鸡。
微红柰蔕惹蜂粉，洁白芹芽穿燕泥。
借问含嚬向何事，昔年曾到武陵溪。','',''),('quantangshi-32182','金虎台','溫庭筠','quantangshi','','卷33','碧草连金虎，青苔蔽石麟。
皓齿芳尘起，纤腰玉树春。
倚瑟红铅湿，分香翠黛嚬。
谁言奉陵寝，相顾复沾巾。','',''),('quantangshi-32183','侠客行','溫庭筠','quantangshi','','卷33','欲出鸿都门，阴云蔽城阙。
宝劒黯如水，微红湿余血。
白马夜频惊，三更霸陵雪。','',''),('quantangshi-32184','咏晓','溫庭筠','quantangshi','','卷33','虫歇纱牕静，鸦散碧梧寒。
稍惊朝佩动，犹传清漏残。
乱珠凝烛泪，微红上露盘。
褰衣复理鬓，余润拂芝兰。','',''),('quantangshi-32185','芙蓉','溫庭筠','quantangshi','','卷33','刺茎澹荡碧，花片参差红。
吴歌秋水冷，湘庙夜云空。
浓艳香露里，美人青镜中。
南楼未归客，一夕练塘东。','',''),('quantangshi-32186','勅勒歌塞北','溫庭筠','quantangshi','','卷33','敕勒金𭘵壁，阴山无岁华。
帐外风飘雪，营前月照沙。
羌儿吹玉管，胡姬踏锦花。
却笑江南客，梅落不归家。','',''),('quantangshi-32187','邯郸郭公词','溫庭筠','quantangshi','','卷33','金笳悲故曲，玉座积深尘。
言是邯郸伎，不见邺城人。
青苔竟埋骨，红粉自伤神。
唯有漳河柳，还向旧营春。','',''),('quantangshi-32188','古意','溫庭筠','quantangshi','','卷33','莫莫复莫莫，丝萝缘涧壑。
散木无斧斤，纤茎得依托。
枝低浴鸟歇，根静悬泉落。
不虑见春迟，空伤致身错。','',''),('quantangshi-32189','齐宫','溫庭筠','quantangshi','','卷33','白马杂金饰，言从雕辇回。
粉香随笑度，鬓态伴愁来。
远水斜如剪，青莎绿似裁。
所恨章华日，冉冉下层台。','',''),('quantangshi-32190','春日','溫庭筠','quantangshi','','卷33','柳岸杏花稀，梅梁乳燕飞。
美人鸾镜笑，嘶马雁门归。
楚宫云影薄，台城心赏违。
从来千里恨，边色满戎衣。','',''),('quantangshi-32191','咏春幡','溫庭筠','quantangshi','','卷33','闲庭见早梅，花影为谁栽。
碧烟随刃落，蝉鬓觉春来。
代郡嘶金勒，梵声悲镜台。
玉钗风不定，香步独徘徊。','',''),('quantangshi-32192','陈宫词','溫庭筠','quantangshi','','卷33','鸡鸣人草草，香辇出宫花。
妓语细腰转，马嘶金面斜。
早莺随彩仗，惊雉避凝笳。
淅沥湘风外，红轮映曙霞。','',''),('quantangshi-32193','春日野行','溫庭筠','quantangshi','','卷33','骑马踏烟莎，青春奈怨何。
蝶翎朝粉尽，鸦背夕阳多。
柳艳欺芳带，山愁萦翠蛾。
别情无处说，方寸是星河。','',''),('quantangshi-32194','咏嚬','溫庭筠','quantangshi','','卷33','毛羽歛愁翠，黛娇攒艳春。
恨容偏落泪，低态定思人。
枕上梦随月，扇边歌遶尘。
玉钩鸾不住，波浅石磷磷。','',''),('quantangshi-32195','中书令裴公挽歌词二首 一','溫庭筠','quantangshi','','卷33','王俭风华首，萧何社稷臣。
丹阳布衣客，莲渚白头人。
铭勒燕山暮，碑沈汉水春。
从今虚醉饱，无复污车茵。','',''),('quantangshi-32196','中书令裴公挽歌词二首 二','溫庭筠','quantangshi','','卷33','箭下妖星落，风前杀气廻。
国香荀令去，楼月庾公来。
玉玺终无虑，金縢意不开。
空嗟荐贤路，芳草满燕台。','',''),('quantangshi-32197','唐庄恪太子挽歌词二首 一','溫庭筠','quantangshi','','卷33','叠鼓辞宫殿，悲笳降杳冥。
影离云外日，光灭火前星。
邺客瞻秦苑，商公下汉庭。
依依陵树色，空绕古原青。','',''),('quantangshi-32198','唐庄恪太子挽歌词二首 二','溫庭筠','quantangshi','','卷33','东府虚容卫，西园寄梦思。
凤悬吹曲夜，鸡断问安时。
尘陌都人恨，霜郊赗马悲。
唯余埋璧地，烟草近丹墀。','',''),('quantangshi-32199','祕书刘尚书挽歌词二首 一','溫庭筠','quantangshi','','卷33','王笔活鸾凤，谢诗生芙蓉。
学筵开绛帐，谈柄发洪钟。
粉署见飞鵩，玉山猜卧龙。
遗风丽清韵，萧散九原松。','',''),('quantangshi-32200','祕书刘尚书挽歌词二首 二','溫庭筠','quantangshi','','卷33','麈尾近良玉，鹤裘吹素丝。
坏陵殷浩谪，春墅谢安棊。
京口贵公子，襄阳诸女儿。
折花兼踏月，多唱柳郎词。','',''),('quantangshi-32201','太子西池二首 一','溫庭筠','quantangshi','','卷33','梨花雪压枝，莺啭柳如丝。
嬾逐妆成晓，春融梦觉迟。
鬓轻全作影，嚬浅未成眉。
莫信张公子，窗间断暗期。','',''),('quantangshi-32202','太子西池二首 二','溫庭筠','quantangshi','','卷33','花红兰紫茎，愁草雨新晴。
柳占三春色，莺偷百鸟声。
日长嫌辇重，风暖觉衣轻。
薄暮香尘起，长杨落照明。','',''),('quantangshi-32203','西陵道士茶歌','溫庭筠','quantangshi','','卷33','乳窦溅溅通石脉，绿尘愁草春江色。
涧花入井水味香，山月当人松影直。
仙翁白扇霜鸟翎，拂坛夜读黄庭经。
疎香皓齿有余味，更觉鹤心通杳冥。','',''),('quantangshi-32204','过西堡塞北','溫庭筠','quantangshi','','卷33','浅草干河阔，丛棘废城高。
白马犀匕首，黑裘金佩刀。
霜清彻兔目，风急吹雕毛。
一经何用厄，日暮涕沾袍。','',''),('quantangshi-32205','送李亿东归','溫庭筠','quantangshi','','卷33','黄山远隔秦树，紫禁斜通渭城。
别路青青柳弱，前溪漠漠苔生。
和风澹荡归客，落月殷勤早莺。
灞上金樽未饮，宴歌已有余声。','',''),('quantangshi-32206','开圣寺','溫庭筠','quantangshi','','卷33','路分溪石夹烟丛，十里萧萧古树风。
出寺马嘶秋色里，向陵鸦乱夕阳中。
竹间泉落山厨静，塔下僧归影殿空。
犹有南朝旧碑在，耻将兴废问休公。','',''),('quantangshi-32207','赠蜀府将','溫庭筠','quantangshi','','卷33','十年分散劒关秋，万事皆随锦水流。
志气已曾明汉节，功名犹自滞吴钩。
雕边认箭寒云重，马上听笳塞草愁。
今日逢君倍惆怅，灌婴韩信尽封侯。','',''),('quantangshi-32208','西江贻钓叟骞生','溫庭筠','quantangshi','','卷33','晴江如镜月如钩，泛滟苍茫送客愁。
夜泪潜生竹枝曲，春潮遥上木兰舟。
事随云去身难到，梦逐烟销水自流。
昨日欢娱竟何在，一枝梅谢楚江头。','',''),('quantangshi-32209','寄清源寺僧','溫庭筠','quantangshi','','卷33','石路无尘竹径开，昔年曾伴戴颙来。
窗间半偈闻钟后，松下残棊送客回。
帘向玉峰藏夜雪，砌因蓝水长秋苔。
白莲社裹如相问，为说游人是姓雷。','',''),('quantangshi-32210','重游圭峰宗密禅师精庐','溫庭筠','quantangshi','','卷33','百尺青崖三尺坟，微言已绝杳难闻。
戴颙今日称居士，支遁他年识领军。
暂对杉松如结社，偶同麋鹿自成羣。
故山弟子空廻首，葱岭唯应见宋云。','',''),('quantangshi-32211','题李处士幽居','溫庭筠','quantangshi','','卷33','水玉簪头白角巾，瑶琴寂历拂轻尘。
浓阴似帐红薇晚，细雨如烟碧草春。
隔竹见笼疑有鹤，卷帘看画静无人。
南山自是忘年友，谷口徒称郑子真。','',''),('quantangshi-32212','利州南渡','溫庭筠','quantangshi','','卷33','澹然空水对斜晖，曲岛苍茫接翠微。
波上马嘶看棹去，柳边人歇待船归。
数丛沙草羣鸥散，万顷江田一鹭飞。
谁解乘舟寻范蠡，五湖烟水独忘机。','',''),('quantangshi-32213','赠李将军','溫庭筠','quantangshi','','卷33','谁言荀羡爱功勋，年少登坛众所闻。
曾以能书称内史，又因明易号将军。
金沟故事春长在，玉轴遗文火半焚。
不学龙骧画山水，醉乡无迹似闲云。','',''),('quantangshi-32214','寒食日作','溫庭筠','quantangshi','','卷33','红深绿暗迳相交，抱暖含芳披紫袍。
彩索平时墙婉娩，轻球落处晚寥梢。
窗中草色妬鸡卵，盘上芹泥憎燕巢。
自有玉楼春意在，不能骑马度烟郊。','',''),('quantangshi-32215','李羽处士寄新醖走笔戏酬','溫庭筠','quantangshi','','卷33','高谈有伴还成薮，沈醉无期即是乡。
已恨流莺欺谢客，更将浮蚁与刘郎。
檐前柳色分张绿，窗外花枝借助香。
所恨玳筵红烛夜，草玄寥落近廻塘。','',''),('quantangshi-32216','郊居秋日有怀一二知己','溫庭筠','quantangshi','','卷33','稻田凫雁满晴沙，钓渚归来一迳斜。
门带果林招邑吏，井分蔬圃属邻家。
臯原寂历垂禾穗，桑竹参差映豆花。
自笑谩怀经济策，不将心事许烟霞。','',''),('quantangshi-32217','题友人池亭','溫庭筠','quantangshi','','卷33','月榭风亭绕曲池，粉垣廻互瓦参差。
侵帘片白摇翻影，落镜愁红写倒枝。
鸂鶒刷毛花荡漾，鹭鸶拳足雪离披。
山翁醉后如相忆，羽扇清樽我自知。','',''),('quantangshi-32218','南湖','溫庭筠','quantangshi','','卷33','湖上微风入槛凉，翻翻菱荇满廻塘。
野船着岸偎春草，水鸟带波飞夕阳。
芦叶有声疑雾雨，浪花无际似潇湘。
飘然篷艇东归客，尽日相看忆楚乡。','',''),('quantangshi-32219','赠袁司录','溫庭筠','quantangshi','','卷33','一朝辞满有心期，花发杨园雪压枝。
刘尹故人谙往事，谢郎诸弟得新知。
金钗醉就胡姬画，玉管闲留洛客吹。
记得襄阳耆旧语，不堪风景岘山碑。','',''),('quantangshi-32220','题西明寺僧院','溫庭筠','quantangshi','','卷33','曾识匡山远法师，低松片石对前墀。
为寻名画来过院，因访闲人得看棊。
新雁参差云碧处，寒鸦辽乱叶红时。
自知终有张华识，不向沧洲州理钓丝。','',''),('quantangshi-32221','偶题','溫庭筠','quantangshi','','卷33','微风和暖日鲜明，草色迷人向渭城。
吴客卷帘闲不语，楚娥攀树独含情。
红垂果蔕樱桃重，黄染花丛蝶粉轻。
自恨青楼无近信，不将心事许卿卿。','',''),('quantangshi-32222','寄湘阴阎少府乞钓轮子','溫庭筠','quantangshi','','卷33','钓轮形与月轮同，独茧和烟影似空。
若向三湘逢雁信，莫辞千里寄渔翁。
篷声夜滴松江雨，菱叶秋传镜水风。
终日垂钩还有意，尺书多在锦鳞中。','',''),('quantangshi-32223','哭王元裕','溫庭筠','quantangshi','','卷33','闻说萧郎逐逝川，伯牙因此绝清弦。
柳边犹忆青骢影，坟上俄生碧草烟。
箧里诗书疑谢后，梦中风貌似潘前。
他时若到相寻处，碧树红楼自宛然。','',''),('quantangshi-32224','法云寺双桧','溫庭筠','quantangshi','','卷33','晋朝名辈此离羣，想对浓阴去住分。
题处尚寻王内史，画时应是顾将军。
长廊夜静声疑雨，古殿秋深影胜云。
一下南台到人世，晓泉清籁更难闻。','',''),('quantangshi-32225','送陈嘏之侯官兼简李常侍','溫庭筠','quantangshi','','卷33','纵得步兵无绿蚁，不缘句漏有丹砂。
殷勤为报同袍友，我亦无心似海槎。
春服照尘连草色，夜船闻雨滴芦花。
梅仙自是青云客，莫羡相如却到家。','',''),('quantangshi-32226','春日野行','溫庭筠','quantangshi','','卷33','雨涨西塘金堤斜，碧草芊芊晴吐芽。
野岸明媚山芍药，水田呌噪官虾蟇。
镜中有浪动菱蔓，陌上无风飘柳花。
何事轻桡句溪客，绿萍方好不归家。','',''),('quantangshi-32227','溪上行','溫庭筠','quantangshi','','卷33','绿塘漾漾烟蒙蒙，张翰此来情不穷。
雪羽䙰褷立倒影，金鳞拨剌跳晴空。
风翻荷叶一向白，雨湿蓼花千穗红。
心羡夕阳波上客，片时归梦钓船中。','',''),('quantangshi-32228','投翰林萧舍人','溫庭筠','quantangshi','','卷33','人间鵷鹭杳难从，独恨金扉直九重。
万象晚归仁寿镜，百花春隔景阳钟。
紫微芒动词初出，红烛香残诰未封。
每过朱门爱庭树，一枝何日许相容。','',''),('quantangshi-32229','春日偶作','溫庭筠','quantangshi','','卷33','西园一曲艳阳歌，扰扰车尘负薜萝。
自欲放怀犹未得，不知经世竟如何。
夜闻猛雨判花尽，寒恋重衾觉梦多。
钓渚别来应更好，春风还为起微波。','',''),('quantangshi-32230','春暮宴罢寄宋寿先辈','溫庭筠','quantangshi','','卷33','斜掩朱门花外钟，晓莺时节好相逢。
窗间桃蘂宿妆在，雨后牡丹春睡浓。
苏小风姿迷下蔡，马卿才调似临邛。
谁怜芳草生三径，参佐桥西陆士龙。','',''),('quantangshi-32231','马嵬驿','溫庭筠','quantangshi','','卷33','穆满曾为物外游，六龙经此暂淹留。
返魂无验青烟灭，埋血空生碧草愁。
香辇却归长乐殿，晓钟还下景阳楼。
甘泉不复重相见，谁道文成是故侯。','',''),('quantangshi-32232','和道溪君别业','溫庭筠','quantangshi','','卷33','积润初销碧草新，凤阳晴日带雕轮。
风飘弱柳平桥晚，雪点寒梅小苑春。
屏上楼台陈后主，镜中金翠李夫人。
花房透露红珠落，蛱蝶双飞护粉尘。','',''),('quantangshi-32233','奉天西佛寺','溫庭筠','quantangshi','','卷33','忆昔狂童犯顺年，玉虬闲暇出甘泉。
宗臣欲舞千钧劒，追骑犹观七宝鞭。
星背紫垣终埽地，日归黄道却当天。
至今南顿诸耆旧，犹指榛芜作弄田。','',''),('quantangshi-32234','题望苑驿','溫庭筠','quantangshi','','卷33','弱柳千条杏一枝，半含春雨半垂丝。
景阳寒井人难到，长乐晨钟鸟自知。
花影至今通博望，树名从此号相思。
分明十二楼前月，不向西陵照盛姬。','',''),('quantangshi-32235','寄分司元庶子兼呈元处士','溫庭筠','quantangshi','','卷33','闭门高卧莫长嗟，水木凝晖属谢家。
缑岭参差残晓雪，洛波清浅露晴沙。
刘公春尽芜菁色，华[廙]愁深苜蓿花。
月榭知君还怅望，碧霄烟阔雁行斜。','',''),('quantangshi-32236','题柳','溫庭筠','quantangshi','','卷33','杨柳千条拂面丝，绿烟金穗不胜吹。
香随静婉歌尘起，影伴娇娆舞袖垂。
羌管一声何处曲，流莺百啭最高枝。
千门九陌花如雪，飞过宫墙两自知。','',''),('quantangshi-32237','和友人悼亡','溫庭筠','quantangshi','','卷33','玉貌潘郎泪满衣，画罗轻鬓[雨]霏微。
红兰委露愁难尽，白马朝天望不归。
宝镜尘昏鸾影在，钿筝弦断雁行稀。
春来多少伤心事，碧草侵堦粉蝶飞。','',''),('quantangshi-32238','李羽处士故里','溫庭筠','quantangshi','','卷33','柳不成丝草带烟，海槎东去鹤归天。
愁肠断处春何限，病眼开时月正圆。
花若有情还怅望，水应无事莫潺湲。
终知此恨销难尽，辜负南华第一篇。','',''),('quantangshi-32239','却经商山寄昔同行人','溫庭筠','quantangshi','','卷33','曾道逍遥第一篇，尔来无处不恬然。
便同南郭能忘象，兼笑东林学坐禅。
人事转新花烂熳，客程依旧水潺湲。
若敎犹作当时意，应有垂丝在鬓边。','',''),('quantangshi-32240','池塘七夕','溫庭筠','quantangshi','','卷33','月出西南露气秋，绮罗河汉在斜沟。
杨家绣作鸳鸯幔，张氏金为翡翠钩。
香烛有花妨宿燕，画屏无睡待牵牛。
万家砧杵三篙水，一夕横塘似旧游。','',''),('quantangshi-32241','偶游','溫庭筠','quantangshi','','卷33','曲巷斜临一水间，小门终日不开关。
红珠斗帐樱桃熟，金尾屏风孔雀闲。
云髻几迷芳草蝶，额黄无限夕阳山。
与君便是鸳鸯侣，休向人间觅往还。','',''),('quantangshi-32242','寄河南杜少尹','溫庭筠','quantangshi','','卷33','十载归来鬓未凋，玳簪珠履见常僚。
岂关名利分荣路，自有才华作庆霄。
鸟影参差经上苑，骑声断续过中桥。
夕阳亭畔山如画，应念田歌正寂寥。','',''),('quantangshi-32243','赠知音','溫庭筠','quantangshi','','卷33','翠羽花冠碧树鸡，未明先向短墙啼。
窗间谢女青蛾歛，门外萧郎白马嘶。
星汉渐移庭竹影，露珠犹缀野花迷。
景阳宫里钟初动，不语垂鞭上柳堤。','',''),('quantangshi-32244','过陈琳墓','溫庭筠','quantangshi','','卷33','曾于青史见遗文，今日飘蓬过古坟。
词客有灵应识我，霸才无主始怜君。
石麟埋没藏春草，铜雀荒凉对暮云。
莫怪临风倍惆怅，欲将书劒学从军。','',''),('quantangshi-32245','题崔公池旧游','溫庭筠','quantangshi','','卷33','皎镜方塘菡萏秋，此来重见采莲舟。
谁能不逐当年乐，还恐添成异日愁。
红艳影多风袅袅，碧空云断水悠悠。
檐前依旧青山色，尽日无人独上楼。','',''),('quantangshi-32246','回中作','溫庭筠','quantangshi','','卷33','苍莽寒空远色愁，呜呜戍角上高楼。
吴姬怨思吹双管，燕客悲歌别五侯。
千里关山边草暮，一星烽火朔云秋。
夜来霜重西风起，陇水无声冻不流。','',''),('quantangshi-32247','西江上送渔父','溫庭筠','quantangshi','','卷33','却逐严光向若耶，钓轮菱棹寄年华。
三秋梅雨愁枫叶，一夜篷舟宿苇花。
不见水云应有梦，偶随鸥鹭便成家。
白苹风起楼船暮，江燕双双五两斜。','',''),('quantangshi-32248','经故秘书崔监扬州南塘旧居','溫庭筠','quantangshi','','卷33','昔年曾识范安成，松竹风姿鹤性情。
西掖曙河横漏响，北山秋月照江声。
乘舟觅吏经舆县，为酒求官得步兵。
千顷水流通故墅，至今留得谢公名。','',''),('quantangshi-32249','经故秘书崔监扬州南塘旧居','溫庭筠','quantangshi','','卷33','昔年曽识谢宣城，松竹风姿鹤性情。
唯向旧山留月色，偶逢秋涧似琴声。
乗舟覔吏经舆县，为酒求官得步兵。
玉柄寂寥谭客散，却寻池阁泪纵横。','',''),('quantangshi-32250','七夕','溫庭筠','quantangshi','','卷33','鹊归燕去两悠悠，青琐西南月似钩。
天上岁时星右转，世间离别水东流。
金风入树千门夜，银汉横空万象秋。
苏小横塘通桂檝，未应清浅隔牵牛。','',''),('quantangshi-32251','题韦筹博士草堂','溫庭筠','quantangshi','','卷33','玄晏先生已白头，不随鵷鹭狎羣鸥。
元卿谢免开三径，平仲朝归卧一裘。
醉后独知殷甲子，病来犹作晋春秋。
沧浪未濯尘缨在，野水无情处处流。','',''),('quantangshi-32252','和友人题壁','溫庭筠','quantangshi','','卷33','冲尚犹来出范围，肯将经世作风徽。
三台位缺严陵卧，百战功高范蠡归。
自欲一鸣惊鹤寝，不应孤愤学牛衣。
西州未有看棋暇，涧户何由得掩扉。','',''),('quantangshi-32253','春日将欲东归寄新及第苗绅先辈','溫庭筠','quantangshi','','卷33','几年辛苦与君同，得丧悲欢尽是空。
犹喜故人先折桂，自怜羁客尚飘蓬。
三春月照千山道，十日花开一夜风。
知有杏园无路入，马前惆怅满枝红。','',''),('quantangshi-32254','经李征君故居','溫庭筠','quantangshi','','卷33','露浓烟重草萋萋，树映阑干柳拂堤。
一院落花无客醉，五更残月有莺啼。
芳筵想像情难尽，故榭荒凉路已迷。
惆怅羸骖往来惯，每经门巷亦长嘶。','',''),('quantangshi-32255','送崔郎中赴幕','溫庭筠','quantangshi','','卷33','一别黔巫似断弦，故交东去更凄然。
心游目送三千里，雨散云飞二十年。
发迹岂劳天上桂，属词还得幕中莲。
相思休话长安远，江月随人处处圆。','',''),('quantangshi-32256','经旧游','溫庭筠','quantangshi','','卷33','珠箔金钩对彩桥，昔年于此见娇娆。
香灯怅望飞琼鬓，凉月殷勤碧玉箫。
屏倚故窗山六扇，柳垂寒砌露千条。
坏墙经雨苍苔遍，拾得当时旧翠翘。','',''),('quantangshi-32257','老君庙','溫庭筠','quantangshi','','卷33','紫气氤氲捧半岩，莲峰仙掌共巉巉。
庙前晚色连寒水，天外斜阳带远帆。
百二关山扶玉座，五千文字閟瑶缄。
自怜金骨无人识，知有飞龟在石函。','',''),('quantangshi-32258','过五丈原','溫庭筠','quantangshi','','卷33','铁马云雕久绝尘，柳阴高压汉营春。
天晴杀气屯关右，夜半妖星照渭滨。
下国卧龙空误主，中原逐鹿不因人。
象牀锦帐无言语，从此谯周是老臣。','',''),('quantangshi-32259','和友人伤歌姬','溫庭筠','quantangshi','','卷33','月缺花残莫怆然，花须终发月终圆。
更能何事销芳念，亦有浓华委逝川。
一曲艳歌留婉转，九原春草妬婵娟。
王孙莫学多情客，自古多情损少年。','',''),('quantangshi-32260','山中与诸道友夜坐闻边防不宁因示同志','溫庭筠','quantangshi','','卷33','龙砂铁马犯烟尘，迹近羣鸥意倍亲。
风卷蓬根屯戊己，月移松影守庚申。
韬钤岂足为经济，岩壑何尝是隐沦。
心许故人知此意，古来知者竟谁人。','',''),('quantangshi-32261','秘书省有贺监知章草题诗笔力遒健风尚高远拂尘寻玩因有此作','溫庭筠','quantangshi','','卷33','越溪渔客贺知章，任达怜才爱酒狂。
鸂鶒苇花随钓艇，蛤蜊菰菜梦横塘。
几年凉月拘华省，一宿秋风忆故乡。
荣路脱身终自得，福庭回首莫相忘。
出笼鸾鹤归辽海，落笔龙蛇满坏墙。
李白死来无醉客，可怜神彩吊残阳。','',''),('quantangshi-32262','题裴晋公林亭','溫庭筠','quantangshi','','卷33','谢傅林亭暑气微，山丘零落閟音徽。
东山终为苍生起，南浦虚言白首归。
池凤已传春水浴，渚禽犹带夕阳飞。
悠然到此忘情处，一日何妨有万几。','',''),('quantangshi-32263','车驾西游因而有作','溫庭筠','quantangshi','','卷33','宣曲长杨瑞气凝，上林狐兔待秋鹰。
谁将词赋陪雕辇，寂寞相如卧茂林。','',''),('quantangshi-32264','伤温德彝','溫庭筠','quantangshi','','卷33','昔年戎虏犯榆关，一败龙城匹马还。
侯印不闻封李广，他人丘垄似天山。','',''),('quantangshi-32265','赠少年','溫庭筠','quantangshi','','卷33','江海相逢客恨多，秋风叶下洞庭波。
酒酣夜别淮阴市，月照高楼一曲歌。','',''),('quantangshi-32266','赠郑征君家匡山首春与丞相赞皇公游止','溫庭筠','quantangshi','','卷33','一抛兰棹逐燕鸿，曾向江湖识谢公。
每到朱门还怅望，故山多在画屏中。','',''),('quantangshi-32267','夏中病痁作','溫庭筠','quantangshi','','卷33','山鬼扬威正气愁，便辞珍簟袭狐裘。
西窗一夕悲人事，团扇无情不待秋。','',''),('quantangshi-32268','题友人居','溫庭筠','quantangshi','','卷33','尽日松堂看画图，绮疏岑寂似清都。
若敎烟水无鸥鸟，张翰何由到五湖。','',''),('quantangshi-32269','题李相公勅赐锦屏风','溫庭筠','quantangshi','','卷33','丰沛曾为社稷臣，赐书名画墨犹新。
几人同保山河誓，犹自栖栖九陌尘。','',''),('quantangshi-32270','蔡中郎坟','溫庭筠','quantangshi','','卷33','古坟零落野花春，闻说中郎有后身。
今日爱才非昔日，莫抛心力作词人。','',''),('quantangshi-32271','元处士池上','溫庭筠','quantangshi','','卷33','蓼穗菱丛思蟪蛄，水萤江鸟满烟蒲。
愁红一片风前落，池上秋波似五湖。','',''),('quantangshi-32272','华阴韦氏林亭','溫庭筠','quantangshi','','卷33','自有林亭不得闲，陌尘宫树是非间。
终南长在茅檐外，别向人间看华山。','',''),('quantangshi-32273','寄裴生乞钓钩','溫庭筠','quantangshi','','卷33','一随菱棹谒王侯，深愧移文负钓舟。
今日太湖风色好，却将诗句乞鱼钩。','',''),('quantangshi-32274','长安春晚二首 一','溫庭筠','quantangshi','','卷33','曲江春半日迟迟，正是王孙怅望时。
杏花落尽不归去，江上东风吹柳丝。','',''),('quantangshi-32275','长安春晚二首 二','溫庭筠','quantangshi','','卷33','四方无事太平年，万象鲜明禁火前。
九重细雨惹春色，轻染龙池杨柳烟。','',''),('quantangshi-32276','三月十八日雪中作','溫庭筠','quantangshi','','卷33','芍药蔷薇语早梅，不知谁是艳阳才。
今朝领得春风意，不复饶君雪里开。','',''),('quantangshi-32277','咸阳值雨','溫庭筠','quantangshi','','卷33','咸阳桥上雨如悬，万点空蒙隔钓船。
还似洞庭春水色，晚云将入岳阳天。','',''),('quantangshi-32278','弹筝人','溫庭筠','quantangshi','','卷33','天宝年中事玉皇，曾将新曲敎宁王。
钿蝉金雁今零落，一曲伊州泪万行。','',''),('quantangshi-32279','瑶瑟怨','溫庭筠','quantangshi','','卷33','冰簟银牀梦不成，碧天如水夜云轻。
雁声远过潇湘去，十二楼中月自明。','',''),('quantangshi-32280','题端正树','溫庭筠','quantangshi','','卷33','路傍佳树碧云愁，曾侍金舆幸驿楼。
草木荣枯似人事，绿阴寂寞汉陵秋。','',''),('quantangshi-32281','渭上题三首 一','溫庭筠','quantangshi','','卷33','吕公荣达子陵归，万古烟波遶钓矶。
桥上一通名利迹，至今江鸟背人飞。','',''),('quantangshi-32282','渭上题三首 二','溫庭筠','quantangshi','','卷33','目极云霄思浩然，风帆一片水连天。
轻桡便是东归路，不肯忘机作钓船。','',''),('quantangshi-32283','渭上题三首 三','溫庭筠','quantangshi','','卷33','烟水何曾息世机，暂时相向亦依依。
所嗟白首磻溪叟，一下渔舟更不归。','',''),('quantangshi-32284','经故翰林袁学士居','溫庭筠','quantangshi','','卷33','劒逐惊波玉委尘，谢安门下更何人。
西州城外花千树，尽是羊昙醉后春。','',''),('quantangshi-32285','题城南杜邠公林亭','溫庭筠','quantangshi','','卷33','卓氏垆前金线柳，隋家堤畔锦帆风。
贪为两地分霖雨，不见池莲照水红。','',''),('quantangshi-32286','夜看牡丹','溫庭筠','quantangshi','','卷33','高低深浅一阑红，把火殷勤遶露丛。
希逸近来成嬾病，不能容易向春风。','',''),('quantangshi-32287','宿城南亡友别墅','溫庭筠','quantangshi','','卷33','水流花落叹浮生，又伴游人宿杜城。
还似昔年残梦里，透帘斜月独闻莺。','',''),('quantangshi-32288','过分水岭','溫庭筠','quantangshi','','卷33','溪水无情似有情，入山三日得同行。
岭头更是分头处，惜别潺湲一夜声。','',''),('quantangshi-32289','鄠杜郊居','溫庭筠','quantangshi','','卷33','槿篱芳援近樵家，壠麦青青一迳斜。
寂寞游人寒食后，夜来风雨送梨花。','',''),('quantangshi-32290','题河中紫极宫','溫庭筠','quantangshi','','卷33','昔年曾伴玉真游，每到仙宫即是秋。
曼倩不归花落尽，满丛烟露月当楼。','',''),('quantangshi-32291','四皓','溫庭筠','quantangshi','','卷33','商于角里便成功，一寸沈机万古同。
但得戚姬甘定分，不应真有紫芝翁。','',''),('quantangshi-32292','赠张炼师','溫庭筠','quantangshi','','卷33','丹溪药尽变金骨，清洛月寒吹玉笙。
他日隐居无访处，碧桃花发水纵横。','',''),('quantangshi-32293','病中书怀呈友人','溫庭筠','quantangshi','','卷33','逸足皆先路，穷郊独向隅。
顽童逃广柳，羸马卧平芜。
黄卷嗟谁问，朱弦偶自娱。
鹿鸣皆缀士，雌伏竟非夫。
采地荒遗野，爰田失故都。
亡羊犹博簺，牧马倦呼卢。
奕世参周禄，承家学鲁儒。
功庸留劒舃，铭戒在盘盂。
经济怀良画，行藏识远图。
未能鸣楚玉，空欲握隋珠。
定为鱼缘木，曾因兔守株。
五车堆缥帙，三迳阖绳枢。
适与羣英集，将期善价沽。
叶龙图夭矫，燕鼠笑胡卢。
赋分知前定，寒心畏厚诬。
蹑尘追庆忌，操劒学班输。
文囿陪多士，神州试大巫。
对虽希鼓瑟，名亦滥吹竽。
正使猜奔竞，何尝计有无。
镏惔虚访觅，王霸竟揶揄。
市义虚焚券，关讥谩弃繻。
至言今信矣，微尚亦悲夫。
白雪调歌响，清风乐舞雩。
胁肩难黾勉，搔首易嗟吁。
角胜非能者，推贤见射乎。
兕觥增恐竦，杯水失锱铢。
粉垛收丹采，金髇隐仆姑。
垂櫜羞尽爵，扬觯辱弯弧。
虎拙休言画，龙希莫学屠。
转蓬随欵段，耘草辟墁垆。
受业乡名郑，藏机谷号愚。
质文精等贯，琴筑韵相须。
筑室连中野，诛茅接上腴。
苇花纶虎落，松瘿鬬栾栌。
静语莺相对，闲眠鹤浪俱。
蘂多劳蝶翅，香酷坠蜂须。
芳草迷三岛，澄波似五湖。
跃鱼翻藻荇，愁鹭睡葭芦。
暝洘藏鸂鶒，幽屏卧鹧鸪。
苦辛随蓻殖，甘旨仰樵苏。
笑语空怀橘，穷愁亦据梧。
尚能甘半菽，非敢薄生刍。
钓石封苍藓，芳蹊艳绛跗。
树兰畦缭绕，穿竹路萦纡。
机杼非桑女，林园异木奴。
横竿窥赤鲤，持翳望青鸬。
泮水思芹味，琅琊得稻租。
杖轻藜拥肿，衣破芰披敷。
芳意忧鶗鴂，愁声觉蟪蛄。
短檐喧语燕，高木堕饥鼯。
事迫离幽墅，贫牵犯畏途。
爱憎防杜挚，悲叹似杨朱。
旅食常过卫，羇游欲渡泸。
塞歌伤督护，边角思单于。
堡戍标枪槊，关河鏁舳舻。
威容尊大树，邢法避秋荼。
远目穷千里，归心寄九衢。
寝甘诚系滞，浆馈贵睢盱。
怀刺名先远，干时道自孤。
齿牙频激发，簦笈尚崎岖。
莲府侯门贵，霜台帝命俞。
骥蹄初蹑景，鹏翅欲抟扶。
寓直廻骢马，分曹对暝乌。
百神歆彷佛，孤竹韵含胡。
凤阙分班立，鵷行竦劒趋。
触邪承密勿，持法奉訏谟。
鸣玉锵登降，衡牙向曳娄。
祀亲和氏璧，香近博山炉。
瑞景森琼树，轻冰莹玉壶。
豸冠簪铁柱，螭首对金铺。
内史书千卷，将军画一厨。
眼明惊气象，心死伏规模。
岂意观文物，何劳琢碔砆。
草肥牧騕褭，苔涩淬昆吾。
乡思巢枝鸟，年华过隙驹。
衔恩空抱影，酬德未捐躯。
时辈推良友，家声继令图。
致身伤短翮，骧首顾疲驽。
班马方齐骛，陈雷亦并驱。
昔皆言尔志，今亦畏吾徒。
有气干牛斗，无人辩辘轳。
客来斟绿蚁，妻试踏青蚨。
积毁方销骨，微瑕惧掩瑜。
蛇矛犹转战，鱼服自囚拘。
欲就欺人事，何能逭鬼诛。
是非迷觉梦，行役议秦吴。
凛冽风埃惨，萧条草木枯。
低徊伤志气，蒙犯变肌肤。
旅雁唯闻呌，饥鹰不待呼。
梦梭抛促织，心茧学蜘蛛。
宁复机难料，庸非信未孚。
激扬衔箭虎，疑惧听冰狐。
处己将营窟，论心若合符。
浪言辉棣萼，何所托葭莩。
乔木能求友，危巢莫吓雏。
风华飘领袖，诗礼拜衾繻。
欹枕情何苦，同舟道岂殊。
放怀亲蕙芷，收迹异桑榆。
赠远聊攀柳，栽书欲截蒲。
瞻风无限泪，廻首更踟蹰。','',''),('quantangshi-32294','感旧陈情五十韵献淮南李仆射','溫庭筠','quantangshi','','卷33','嵇绍垂髫日，山涛筮仕年。
琴樽陈席上，纨绮拜牀前。
邻里才三徙，云霄已九迁。
感深情戃怳，言发泪潺湲。
忆昔龙图盛，方今鹤羽全。
桂枝香可袭，杨叶旧频穿。
玉籍标人瑞，金丹化地仙。
赋成攒笔写，歌出满城传。
既矫排虚翅，将持造物权。
万灵思鼓铸，羣品待陶甄。
视草丝纶出，持纲雨露悬。
法行黄道内，居近翠华边。
书迹临汤鼎，吟声接舜弦。
白麻红烛夜，清漏紫微天。
雷电随神笔，鱼龙落彩牋。
闲宵陪雍畤，清暑在甘泉。
耿介非持禄，优游是养贤。
冰清临百粤，风靡化三川。
委寄崇推毂，威仪压控弦。
梁园提彀骑，淮水换戎旃。
照日青油湿，迎风锦帐鲜。
黛蛾陈二八，珠履列三千。
舞转廻红袖，歌愁歛翠钿。
满堂开照曜，分座俨婵娟。
油额芙蓉帐，香尘玳瑁筵。
绣旗随影合，金阵似波旋。
缇幕深廻互，朱门暗接连。
彩虬蟠画戟，花马立金鞭。
有客将谁托，无媒窃自怜。
抑扬中散曲，漂泊孝廉船。
未展干时策，徒抛负郭田。
转蓬犹邈尔，怀橘更澘然。
投足乖蹊迳，冥心向简编。
未知鱼跃地，空愧鹿鸣篇。
稷下期方至，漳滨病未痊。
定非笼外鸟，真是壳中蝉。
蕙迳邻幽澹，荆扉兴静便。
草堂苔点点，蔬囿水溅溅。
钓罢溪云重，樵归涧月圆。
嬾多成宿疢，愁甚似春眠。
木直终难怨，膏明只自煎。
郑乡空健羡，陈榻未招延。
旅食逢春尽，羁游为事牵。
宦无毛义檄，婚乏阮修钱。
冉弱营中柳，披敷幕下莲。
傥能容委质，非敢望差肩。
涩劒犹堪淬，余朱或可研。
从师当鼓箧，穷理久忘筌。
折简能荣瘁，遗簪莫弃捐。
韶光如见借，寒谷变风烟。','',''),('quantangshi-32295','题翠微寺二十二韵','溫庭筠','quantangshi','','卷33','邠土初成邑，虞宾竟让王。
干符初得位，天弩夜收铓。
偃息齐三代，优游念四方。
万灵扶正寝，千嶂抱重冈。
幽石归阶陛，乔柯入栋梁。
火云如沃雪，汤殿似含霜。
涧籁添仙曲，岩花借御香。
野麋陪兽舞，林鸟逐鵷行。
镜写三秦色，窗摇八水光。
问云征楚女，疑粉试何郎。
兰芷承雕辇，杉萝入画堂。
受朝松露晓，颁朔桂烟凉。
岚湿金铺外，溪鸣锦幄傍。
倚丝忧汉祖，持璧告秦皇。
短景催风驭，长星属羽觞。
储君犹问竖，元老已登牀。
鹤盖趋平乐，鸡人下建章。
龙髯悲满眼，螭首泪沾裳。
叠鼓严灵杖，吹笙送夕阳。
断泉辞劒佩，昏日伴旗常。
遗庙青莲在，颓垣碧草芳。
无因奏韶濩，流涕对幽篁。','',''),('quantangshi-32296','过孔北海墓二十韵','溫庭筠','quantangshi','','卷33','抚事如神遇，临风独涕零。
墓平春草绿，碑折古苔青。
圭玉埋英气，山河孕炳灵。
发言惊辨囿，撝翰动文星。
蕴策期干世，持权欲反经。
激扬思壮志，流落叹颓龄。
恶木人皆息，贪泉我独醒。
轮辕无匠石，刀几有庖丁。
碌碌迷藏器，规规守挈瓶。
愤容凌鼎镬，公议动朝廷。
故国将辞宠，危邦竟缓刑。
钝工磨白璧，凡石砺青萍。
揭日昭东夏，抟风滞北溟。
后尘遵轨辙，前席咏仪型。
木秀当忧悴，弦伤不底宁。
矜夸遭斥鷃，光彩困飞萤。
白羽留谈柄，清风袭德馨。
鸾凰婴雪刃，狼虎犯云屏。
兰蕙荒遗址，榛芜蔽旧坰。
轘辕近沂水，何事恋明庭。','',''),('quantangshi-32297','过华清宫二十二韵','溫庭筠','quantangshi','','卷33','忆昔开元日，承平事胜游。
贵妃专宠幸，天子富春秋。
月白霓裳殿，风干羯鼓楼。
鬬鸡花蔽膝，骑马玉搔头。
绣毂千门妓，金鞍万户侯。
薄云欹雀扇，轻雪犯貂裘。
过客闻韶濩，居人识冕旒。
气和春不觉，烟暖霁难收。
涩浪和琼甃，晴阳上彩斿。
卷衣轻鬓嬾，窥镜澹蛾羞。
屏掩芙蓉帐，帘褰玳瑁钩。
重瞳分渭曲，纤手指神州。
御案迷萱草，天袍妬石榴。
深岩藏浴凤，鲜隰媚潜虬。
不料邯郸虱，俄成即墨牛。
劒锋挥太皞，旗焰拂蚩尤。
内嬖陪行在，孤臣预坐筹。
瑶簪遗翡翠，霜仗驻骅骝。
艳笑双飞断，[香]魂一哭休。
早梅悲蜀道，高树隔昭丘。
朱阁重霄近，苍崖万古愁。
至今汤殿水，呜咽县前流。','',''),('quantangshi-32298','洞户二十二韵','溫庭筠','quantangshi','','卷33','洞户连珠网，方疏隐碧浔。
烛盘烟坠烬，帘压月通阴。
粉白仙郎署，霜清玉女砧。
醉乡高窈窈，棊阵静愔愔。
素手琉璃扇，玄髫玳瑁簪。
昔邪看寄迹，栀子咏同心。
树列千秋胜，楼悬七夕针。
旧词翻白紵，新赋换黄金。
唳鹤调蛮鼓，惊蝉应宝琴。
舞疑繁易度，歌转断难寻。
露委花相妬，风欹柳不禁。
桥弯双表逈，池涨一篙深。
清跸传恢囿，黄旗幸上林。
神鹰参翰苑，天马破蹄涔。
武库方题品，文园有好音。
朱茎殊菌蠢，丹桂欲萧森。
黼帐廻瑶席，华灯对锦衾。
画图惊走兽，书帖得来禽。
河曙秦楼映，山晴魏阙临。
绿囊逢赵后，青锁见王沈。
任达嫌孤愤，疎慵倦九箴。
若为南遁客，犹作卧龙吟。','','');
INSERT OR REPLACE INTO poems (id,title,author,collection,rhythmic,section,text,notes,tr) VALUES ('quantangshi-32299','送洛南李主簿','溫庭筠','quantangshi','','卷33','想君秦塞外，因见楚山青。
槲叶晓迷路，枳花春满庭。
禄优仍侍膳，官散得专经。
子敬怀愚谷，归心在翠屏。','',''),('quantangshi-32300','巫山神女庙','溫庭筠','quantangshi','','卷33','黯黯闭宫殿，霏霏荫薜萝。
晓峰眉上色，春水脸前波。
古树芳菲尽，扁舟离恨多。
一丛斑竹夜，环佩响如何。','',''),('quantangshi-32301','地肺山春日','溫庭筠','quantangshi','','卷33','冉冉花明岸，涓涓水绕山。
几时抛俗事，来共白云闲。','',''),('quantangshi-32302','题陈处士幽居','溫庭筠','quantangshi','','卷33','松轩尘外客，高枕自萧疎。
雨后苔侵井，霜来叶满渠。
闲看镜湖画，秋得越僧书。
若待前溪月，谁人伴钓鱼。','',''),('quantangshi-32303','握柘词','溫庭筠','quantangshi','','卷33','杨柳萦桥绿，玫瑰拂地红。
绣衫金騕褭，花髻玉珑璁。
宿雨香潜润，春流水暗通。
画楼初梦断，晓日照湘风。','',''),('quantangshi-32304','题卢处士山居','溫庭筠','quantangshi','','卷33','西溪问樵客，遥识楚人家。
古树老连石，急泉清露沙。
千峰随雨暗，一迳入云斜。
日暮飞鸦集，满山荞麦花。','',''),('quantangshi-32305','初秋寄友人','溫庭筠','quantangshi','','卷33','闲梦正悠悠，凉风生竹楼。
夜琴知欲雨，晓簟觉新秋。
独鸟楚山远，一蝉关树愁。
凭将离别恨，江外问同游。','',''),('quantangshi-32306','题丰安里王相林亭二首 一','溫庭筠','quantangshi','','卷33','花竹有薄埃，嘉游集上才。
白苹安石渚，红叶子云台。
朱户雀罗设，黄门驭骑来。
不知淮水浊，丹藕为谁开。','',''),('quantangshi-32307','题丰安里王相林亭二首 二','溫庭筠','quantangshi','','卷33','偶到乌衣巷，含情更惘然。
西州曲堤柳，东府旧池莲。
星坼悲元老，云归送墨仙。
谁知济川檝，今作野人船。','',''),('quantangshi-32308','早秋山居','溫庭筠','quantangshi','','卷33','山近觉寒早，草堂霜气晴。
树凋窗有日，池满水无声。
果落见猿过，叶干闻鹿行。
素琴机虑静，空伴夜泉清。','',''),('quantangshi-32309','和友人盘石寺逢旧友','溫庭筠','quantangshi','','卷33','楚寺上方宿，满堂皆旧游。
月溪逢远客，烟浪有归舟。
江馆白苹夜，水关红叶秋。
西风吹暮雨，汀草更堪愁。','',''),('quantangshi-32310','送人南游','溫庭筠','quantangshi','','卷33','送君游楚国，江浦树苍然。
沙净有波迹，岸平多草烟。
角悲临海郡，月到渡淮船。
唯以一杯酒，相思高楚天。','',''),('quantangshi-32311','赠郑处士','溫庭筠','quantangshi','','卷33','飘然随钓艇，云水是天涯。
红叶下荒井，碧梧侵古槎。
醉收陶令菊，贫卖邵平瓜。
更有相期处，南篱一树花。','',''),('quantangshi-32312','江岸即事','溫庭筠','quantangshi','','卷33','水容侵古岸，峰影度青苹。
庙竹唯闻鸟，江帆不见人。
雀声花外暝，客思柳边春。
别恨转难尽，行行汀草新。','',''),('quantangshi-32313','赠隐者','溫庭筠','quantangshi','','卷33','茅堂对薇蕨，炉暧一裘轻。
醉后楚山梦，觉来春鸟声。
采茶溪树绿，煮药石泉清。
不问人间事，忘机过此生。','',''),('quantangshi-32314','渚宫晚春寄秦地友人','溫庭筠','quantangshi','','卷33','风华已眇然，独立思江天。
凫雁野塘水，牛羊春草烟。
秦原晓重叠，灞浪夜潺湲。
今日思归客，愁容在镜悬。','',''),('quantangshi-32315','碧涧驿晓思','溫庭筠','quantangshi','','卷33','香灯伴残梦，楚国在天涯。
月落子规歇，满庭山杏花。','',''),('quantangshi-32316','送并州郭书记','溫庭筠','quantangshi','','卷33','宾筵得佳客，侯印有光辉。
候骑不传箭，回文空上机。
塞城收马去，烽火射雕归。
惟有严家濑，回环迳草微。','',''),('quantangshi-32317','赠越僧岳云二首 一','溫庭筠','quantangshi','','卷33','世机消已尽，巾屦亦飘然。
一室故山月，满瓶秋涧泉。
禅庵过微雪，乡寺隔寒烟。
应共白莲客，相期松桂前。','',''),('quantangshi-32318','赠越僧岳云二首 二','溫庭筠','quantangshi','','卷33','兰亭旧都讲，今日意如何。
有树关深院，无尘到浅莎。
僧居随处好，人事出门多。
不及新春雁，年年镜水波。','',''),('quantangshi-32319','咏山鸡','溫庭筠','quantangshi','','卷33','万壑动晴景，山禽凌翠微。
绣翎翻草去，红觜啄花归。
巢暖碧云色，影孤清镜辉。','',''),('quantangshi-32320','清旦题采药翁草堂','溫庭筠','quantangshi','','卷33','幽人寻药迳，来自晓云边。
衣湿术花雨，语成松岭烟。
解藤开涧户，踏石过溪泉。
林外晨光动，山昏鸟满天。','',''),('quantangshi-32321','商山早行','溫庭筠','quantangshi','','卷33','晨起动征铎，客行悲故乡。
鸡声茅店月，人迹板桥霜。
槲叶落山路，枳花明驿墙。
因思杜陵梦，凫雁满回塘。','',''),('quantangshi-32322','题竹谷神祠','溫庭筠','quantangshi','','卷33','苍苍松竹晚，一迳入荒祠。
古树风吹马，虚廊日照旗。
烟煤朝奠处，风雨夜归时。
寂寞东湖客，空看蒋帝碑。','',''),('quantangshi-32323','途中有怀','溫庭筠','quantangshi','','卷33','驱车何日闲，扰扰路岐间。
岁暮自多感，客程殊未还。
亭臯汝阳道，风雪穆陵关。
腊后寒梅发，谁人在故山。','',''),('quantangshi-32324','经李处士杜城别业','溫庭筠','quantangshi','','卷33','忆昔几游集，今来倍叹伤。
百花情易老，一笑事难忘。
白社已萧索，青楼空艳阳。
不闲云雨梦，犹欲过高唐。','',''),('quantangshi-32325','登李羽士东楼','溫庭筠','quantangshi','','卷33','经客有余音，他年终故林。
高楼本危睇，凉月更伤心。
此意竟难折，伊人成古今。
流尘其可欲，非复嬾鸣琴。','',''),('quantangshi-32326','题僧泰恭院二首 一','溫庭筠','quantangshi','','卷33','昔岁东林下，深公识姓名。
尔来辞半偈，空复叹劳生。
忧患慕禅味，寂寥遗世情。
所归心自得，何事倦尘缨。','',''),('quantangshi-32327','题僧泰恭院二首 二','溫庭筠','quantangshi','','卷33','微生竟劳止，晤言犹是非。
出门还有泪，看竹暂忘机。
爽气三秋近，浮生一笑稀。
故山松菊在，终欲掩荆扉。','',''),('quantangshi-32328','西游书怀','溫庭筠','quantangshi','','卷33','渭川通野戍，有路上桑干。
独鸟青天暮，惊麏赤烧残。
高秋辞故国，昨日梦长安。
客意自如此，非关行路难。','',''),('quantangshi-32329','送人东游','溫庭筠','quantangshi','','卷33','荒戍落黄叶，浩然离故关。
高风汉阳渡，初日郢门山。
江上几人在，天涯孤棹还。
何当重相见，尊酒慰离颜。','',''),('quantangshi-32330','寄山中友人','溫庭筠','quantangshi','','卷33','惟昔有归趣，今兹固愿言。
啸歌成往事，风雨坐凉轩。
时物信佳节，岁华非故园。
固知春草色，何意为王孙。','',''),('quantangshi-32331','偶题','溫庭筠','quantangshi','','卷33','孔雀眠高阁，樱桃拂短檐。
画明金冉冉，筝语玉纤纤。
细雨无妨烛，轻寒不隔帘。
欲将红锦段，因梦寄江淹。','',''),('quantangshi-32332','赠考功卢郎中','溫庭筠','quantangshi','','卷33','白首方辞满，荆扉对渚田。
雪中无陋巷，醉后似当年。
一笈负山药，两瓶携涧泉。','',''),('quantangshi-32333','题萧山庙','溫庭筠','quantangshi','','卷33','故道木阴浓，荒祠山影东。
杉松一庭雨，幡盖满堂风。
客奠晓莎湿，马嘶秋庙空。
夜深池上歇，龙入古潭中。','',''),('quantangshi-32334','春日寄岳州从事李员外二首 一','溫庭筠','quantangshi','','卷33','苒弱楼前柳，轻空花外窗。
蝶高飞有伴，莺早语无双。
剪胜裁春字，开屏见晓江。
从来共情战，今日欲归降。','',''),('quantangshi-32335','春日寄岳州从事李员外二首 二','溫庭筠','quantangshi','','卷33','从小识宾卿，恩深若弟兄。
相逢在何日，此别不胜情。
红粉座中客，彩斿江上城。
尚平婚嫁累，无路逐双旌。','',''),('quantangshi-32336','和段少常柯古','溫庭筠','quantangshi','','卷33','称觞慙座客，怀刺即门人。
素向宁知贵，清淡不厌贫。
野梅江上晚，堤柳雨中春。
未报淮南诏，何劳问白苹。','',''),('quantangshi-32337','海榴','溫庭筠','quantangshi','','卷33','海榴开似火，先解报春风。
叶乱裁牋绿，花宜插鬓红。
蜡珠攒作蔕，缃彩剪成丛。
郑驿多归思，相期一笑同。','',''),('quantangshi-32338','李先生别墅望僧舍宝刹因作双韵声','溫庭筠','quantangshi','','卷33','栖息消心象，檐楹溢艳阳。
帘栊兰露落，邻里柳林凉。
高阁过空谷，孤竿隔古冈。
潭庐同淡荡，仿髴复芬芳。','',''),('quantangshi-32339','敷水小桃盛开因作','溫庭筠','quantangshi','','卷33','敷水小桥东，娟娟照露丛。
所嗟非胜地，堪恨是春风。
二月艳阳节，一枝惆怅红。
定知留不住，吹落路尘中。','',''),('quantangshi-32340','寄山中人','溫庭筠','quantangshi','','卷33','月中一双鹤，石上千尺松。
素琴入爽籁，山酒和春容。
幽瀑有时断，片云无所从。
何事苏门生，携手东南峰。','',''),('quantangshi-32341','送淮阴孙令之官','溫庭筠','quantangshi','','卷33','隋堤杨柳烟，孤棹正悠然。
萧寺通淮戍，芜城枕楚壖。
鱼盐桥上市，灯火雨中船。
故老青葭岸，先知虙子贤。','',''),('quantangshi-32342','宿辉公精舍','溫庭筠','quantangshi','','卷33','禅房无外物，清话此宵同。
林彩水烟里，涧声[山]月中。
橡霜诸壑霁，杉火一炉空。
拥褐寒更彻，心知觉路通。','',''),('quantangshi-32343','旅泊新津却寄一二知己','溫庭筠','quantangshi','','卷33','维舟息行役，霁景近江村。
并起别离恨，似闻歌吹喧。
高林月初上，远水雾犹昏。
王粲平生感，登临几断魂。','',''),('quantangshi-32344','赠僧云栖','溫庭筠','quantangshi','','卷33','麈尾与筇杖，几年离石坛。
梵余林雪厚，棊罢岳钟残。
开卷喜先悟，漱瓶知早寒。
衡阳寺前雁，今日到长安。','',''),('quantangshi-32345','雪夜与友生同宿晓寄近邻','溫庭筠','quantangshi','','卷33','闭门羣动息，积雪透疎林。
有客寒方觉，无声晓已深。
正繁闻近雁，并落起栖禽。
寂寞寒塘路，怜君独阻寻。','',''),('quantangshi-32346','题造微禅师院','溫庭筠','quantangshi','','卷33','夜香闻偈后，岑寂掩双扉。
照竹灯和雪，看松月到衣。
草堂疎磬断，江寺故人稀。
唯忆湘南雨，春风独鸟归。','',''),('quantangshi-32347','正见寺晓别生公','溫庭筠','quantangshi','','卷33','清晓盥秋水，高窗留夕阴。
初阳到古寺，宿鸟起寒林。
香火有良愿，宦名非素心。
灵山缘未绝，他日重来寻。','',''),('quantangshi-32348','旅次盱眙县','溫庭筠','quantangshi','','卷33','离离麦擢芒，楚客意偏伤。
波上旅愁起，天边归路长。
孤桡投楚驿，残月在淮樯。
外杜三千里，谁人数雁行。','',''),('quantangshi-32349','鄠郊别墅寄所知','溫庭筠','quantangshi','','卷33','持颐望平绿，万景集所思。
南塘遇新雨，百草生容姿。
幽鸟不相识，美人如何期。
徒然委摇荡，惆怅春风时。','',''),('quantangshi-32350','京兆公池上作','溫庭筠','quantangshi','','卷33','稻香山色叠，平野接荒陂。
莲折舟行远，萍多钓下迟。
坏堤泉落处，凉簟雨来时。
京口兵堪用，何因入梦思。','',''),('quantangshi-32351','卢氏池上遇雨赠同游者','溫庭筠','quantangshi','','卷33','簟翻凉气集，溪上润残棊。
萍皱风来后，荷喧雨到时。
寂寥闲望久，飘洒独归迟。
无限松江恨，烦君解钓丝。','',''),('quantangshi-32352','题薛昌之所居','溫庭筠','quantangshi','','卷33','所得乃清旷，寂寥常掩关。
独来春尚在，相得暮方还。
花白风露晚，柳青街陌闲。
翠微应有雪，窗外见南山。','',''),('quantangshi-32353','东归有怀','溫庭筠','quantangshi','','卷33','晴川通野陂，此地昔伤离。
一去迹常在，独来心自知。
鹭眠茭叶折，鱼静蓼花垂。
无限高秋泪，扁舟极路岐。','',''),('quantangshi-32354','休澣日西掖谒所知','溫庭筠','quantangshi','','卷33','赤墀高阁自从容，玉女窗扉报曙钟。
日丽九门青锁闼，雨晴双阙翠微峰。
毫端蕙露滋仙草，琴上薰风入禁松。
荀令凤池春婉娩，好将余润变鱼龙。','',''),('quantangshi-32355','博山','溫庭筠','quantangshi','','卷33','博山香重欲成云，锦段机丝妬鄂君。
粉蝶团飞花转影，彩鸳双泳水生纹。
青楼二月春将半，碧瓦千家日未曛。
见说杨朱无限泪，岂能空为路岐分。','',''),('quantangshi-32356','送卢处士游吴越','溫庭筠','quantangshi','','卷33','羡君东去见残梅，唯有王孙独未廻。
吴苑夕阳明古堞，越宫春草上高台。
波生野水雁初下，风满驿楼潮欲来。
试逐渔舟看雪浪，几多江燕荇花开。','',''),('quantangshi-32357','过新丰','溫庭筠','quantangshi','','卷33','一劒乘时帝业成，沛中乡里到咸京。
寰区已作皇居贵，风月犹含白社情。
泗水旧亭春草徧，千门遗瓦古苔生。
至今留得离家恨，鸡犬相闻落照明。','',''),('quantangshi-32358','过潼关','溫庭筠','quantangshi','','卷33','地形盘屈带河流，景气澄明是胜游。
十里晓鸡关树暗，一行寒雁陇云愁。
片时无事溪泉好，尽日凝眸岳色秋。
麈尾角巾应旷望，更嗟芳霭隔秦楼。','',''),('quantangshi-32359','题西平王旧赐屏风','溫庭筠','quantangshi','','卷33','曾向金扉玉砌来，百花鲜湿隔尘埃。
披香殿下樱桃熟，结绮楼前芍药开。
朱鹭已随新卤簿，黄鹂犹湿旧池台。
世间刚有东流水，一送恩波更不廻。','',''),('quantangshi-32360','河中陪帅游亭','溫庭筠','quantangshi','','卷33','倚阑愁立独徘徊，欲赋慙非宋玉才。
满座山光摇劒戟，绕城波色动楼台。
鸟飞天外斜阳尽，人过桥心倒影来。
添得五湖多少恨，柳花飘荡似寒梅。','',''),('quantangshi-32361','和赵嘏题岳寺','溫庭筠','quantangshi','','卷33','疎钟细响乱鸣泉，客省高临似水天。
岚翠暗来空觉润，涧茶余爽不成眠。
越僧寒立孤灯外，岳月秋当万木前。
张邴宦情何太薄，远公窗外有池莲。','',''),('quantangshi-32362','苏武庙','溫庭筠','quantangshi','','卷33','苏武魂销汉使前，古祠高树两茫然。
云边雁断胡天月，陇上羊归塞草烟。
廻日楼台非甲帐，去时冠劒是丁年。
茂陵不见封侯印，空向秋波哭逝川。','',''),('quantangshi-32363','送客偶作','溫庭筠','quantangshi','','卷33','石路荒凉接野蒿，西风吹马利如刀。
小桥连驿杨柳晚，废寺入门禾黍高。
鸡犬夕阳喧县市，凫鹥秋水曝城壕。
故山有梦不归去，官树陌尘何太劳。','',''),('quantangshi-32364','寒食前有怀','溫庭筠','quantangshi','','卷33','万物鲜华雨乍晴，春寒寂历近清明。
残芳荏苒双飞蝶，晓睡朦胧百啭莺。
旧侣不归成独酌，故园虽在有谁耕。
悠然更起严滩恨，一宿东风蕙草生。','',''),('quantangshi-32365','宿云际寺','溫庭筠','quantangshi','','卷33','白盖微云一迳深，东峰弟子远相寻。
苍苔路熟僧归寺，红叶声干鹿在林。
高阁清香生静境，夜堂疎磬发禅心。
自从紫桂岩前别，不见南能直至今。','',''),('quantangshi-32366','寄岳州李外郎远','溫庭筠','quantangshi','','卷33','含嚬不语坐持颐，天远楼高宋玉悲。
湖上残棊人散后，岳阳微雨鸟来迟。
早梅犹得廻歌扇，春水还应理钓丝。
独有袁宏正憔悴，一罇惆怅落花时。','',''),('quantangshi-32367','游南塘寄知者','溫庭筠','quantangshi','','卷33','白鸟梳翎立岸莎，藻花菱刺泛微波。
烟光似带侵垂柳，露点如珠落卷荷。
楚水晓凉催客早，杜陵秋思傍蝉多。
镏公不信归心切，听取江楼一曲歌。','',''),('quantangshi-32368','寄卢生','溫庭筠','quantangshi','','卷33','遗业荒凉近故都，门前堤路枕平湖。
绿杨阴里千家月，红藕香中万点珠。
此地别来双鬓改，几时归去片帆孤。
他年犹拟金貂换，寄语黄公旧酒垆。','',''),('quantangshi-32369','春日访李十四处士','溫庭筠','quantangshi','','卷33','花深桥转水潺潺，角里先生自闭关。
看竹已知行处好，望云空得暂时闲。
谁言有策堪经世，自是无钱可买山。
一局残棊千点雨，绿萍池上暮方还。','',''),('quantangshi-32370','宿松门寺','溫庭筠','quantangshi','','卷33','白石青崖世界分，卷帘孤坐对氛氲。
林间禅室春深雪，潭上龙堂夜半云。
落月苍凉登阁在，晓钟摇荡隔江闻。
西山旧是经行地，愿漱寒瓶逐领军。','',''),('quantangshi-32371','咏寒宵','溫庭筠','quantangshi','','卷33','寒宵何耿耿，良宴有余姿。
宝靺徘徊处，熏炉怅望时。
曲琼垂翡翠，斜月到罘罳。
委坠金釭烬，阑珊玉局棊。
话穷犹注睇，歌罢尚持颐。
暗暖遥相属，氛氲积所思。
秦蛾卷衣晚，胡雁度云迟。
上郡归来梦，那知锦字诗。','',''),('quantangshi-32372','寄渚宫遗民弘里生','溫庭筠','quantangshi','','卷33','柳弱湖堤曲，篱疎水巷深。
酒阑初促席，歌罢欲分襟。
波月欺华烛，汀云润故琴。
镜清花并蔕，牀冷簟连心。
荷叠平桥暗，萍稀败舫沈。
城头五通鼓，窗外万家砧。
异县鱼投浪，当年鸟共林。
八行香未灭，千里梦难寻。
未肯暌良愿，空期嗣好音。
他时因咏作，犹得比南金。','',''),('quantangshi-32373','春尽与友人入裴氏林探渔竿','溫庭筠','quantangshi','','卷33','一迳互纡直，茅棘亦已繁。
晴阳入荒竹，暧暧如春园。
倚杖息惭倦，徘徊恋微暄。
历寻婵娟节，翦破苍筤根。
地闭修茎孤，林振余箨翻。
适心在所好，非必寻湘沅。','',''),('quantangshi-32374','春日','溫庭筠','quantangshi','','卷33','问君何所思，迢递艳阳时。
门静人归晚，墙高蝶过迟。
一双青琐燕，千万绿杨丝。
屏上吴山远，楼中朔管悲。
宝书无寄处，香毂有来期。
草色将林彩，相添入黛眉。','',''),('quantangshi-32375','洛阳','溫庭筠','quantangshi','','卷33','巩树先春雪满枝，上阳宫柳啭黄鹂。
桓谭未便忘西笑，岂为长安有凤池。','',''),('quantangshi-32376','题贺知章故居叠韵作','溫庭筠','quantangshi','','卷33','废砌翳薜荔，枯湖无菰蒲。
老媪饱藁草，愚儒输逋租。','',''),('quantangshi-32377','雨中与李先生期垂钓先后相失因作叠韵','溫庭筠','quantangshi','','卷33','隔石觅屐迹，西溪迷鸡啼。
小鸟扰晓沼，犂泥齐低畦。','',''),('quantangshi-32378','春日雨','溫庭筠','quantangshi','','卷33','细雨蒙蒙入绛纱，湖亭寒食孟珠家。
南朝漫自称流品，宫体何曾为杏花。','',''),('quantangshi-32379','细雨','溫庭筠','quantangshi','','卷33','凭轩望秋雨，凉入暑衣清。
极目鸟频没，片时云复轻。
沼萍开更歛，山叶动还鸣。
楚客秋江上，萧萧故国情。','',''),('quantangshi-32380','秋雨','溫庭筠','quantangshi','','卷33','云满鸟行灭，池凉龙气腥。
斜飘看棊簟，疎洒望山亭。
细响鸣林叶，圆文破沼萍。
秋阴杳无际，平野但冥冥。','',''),('quantangshi-32381','春初对暮雨','溫庭筠','quantangshi','','卷33','淅沥生丛筱，空蒙泫网轩。
暝姿看远树，春意入尘根。
点细飘风急，声轻入夜繁。
雀喧争槿树，人静出蔬园。
瓦湿光先起，房深影易昏。
不应江上草，相与滞王孙。','',''),('quantangshi-32382','雪二首 一','溫庭筠','quantangshi','','卷33','砚水池先冻，窗风酒易消。
鸦声出山郭，人迹过村桥。
稍急方萦转，才深未寂寥。
细光穿暗隟，轻白驻寒条。
草静封还折，松攲堕复摇。
谢庄今病眼，无意坐通宵。','',''),('quantangshi-32383','雪二首 二','溫庭筠','quantangshi','','卷33','羸骖出更慵，林寺已疎钟。
踏紧寒声涩，飞交细点重。
圃斜人过迹，皆静鸟行踪。
寂寞梁鸿病，谁人代夜舂。','',''),('quantangshi-32384','送人游淮海','溫庭筠','quantangshi','','卷33','背樯灯色暗，宿客梦初成。
半夜竹窗雨，满池荷叶声。
簟凉秋合思，木落故山情。
明发又愁起，桂花溪水清。','',''),('quantangshi-32385','原隰荑绿柳','溫庭筠','quantangshi','','卷33','逈野韶光早，晴川柳满堤。
拂尘生嫩绿，披雪见柔荑。
碧玉牙犹短，黄金缕未齐。
腰肢弄寒吹，眉意入春闺。
预恐狂夫折，迎牵逸客迷。
新莺将出谷，应借一枝栖。','',''),('quantangshi-32386','宿秦生山斋','溫庭筠','quantangshi','','卷33','衡巫路不同，结室在东峰。
岁晚得支遁，夜寒逢戴颙。
龛灯落叶寺，山雪隔林钟。
行解无由发，曹溪欲施舂。','',''),('quantangshi-32387','赠楚云上人','溫庭筠','quantangshi','','卷33','松根满苔石，尽日闭禅关。
有伴年年月，无家处处山。
烟波五湖远，瓶屦一身闲。
岳寺蕙兰晚，几时幽鸟还。','',''),('quantangshi-32388','宿白盖峰寺寄僧','溫庭筠','quantangshi','','卷33','山房霜气晴，一宿遂平生。
合上见林影，月中闻涧声。
佛灯销永夜，僧磬彻寒更。
不学何居士，焚香为宦情。','',''),('quantangshi-32389','送僧东游','溫庭筠','quantangshi','','卷33','师归旧山去，此别已凄然。
灯影秋江寺，篷声夜雨船。
鸥飞吴市外，麟卧晋陵前。
若到东林社，谁人更问禅。','',''),('quantangshi-32390','盘石寺留别成公','溫庭筠','quantangshi','','卷33','槲叶萧萧带苇风，寺前归客别支公。
三秋岸雪花初白，一夜林霜叶尽红。
山叠楚天云压塞，浪遥吴苑水连空。
悠然旅榜频回首，无复松窗半偈同。','',''),('quantangshi-32391','题中南佛塔寺','溫庭筠','quantangshi','','卷33','鸣泉隔翠微，千里到柴扉。
地胜人无欲，林昏虎有威。
涧苔侵客屦，山雪入禅衣。
桂树芳阴在，还期岁晏归。','',''),('quantangshi-32392','马嵬佛寺','溫庭筠','quantangshi','','卷33','荒鸡夜唱战尘深，五鼓雕舆过上林。
才信倾城是真语，直敎涂地始甘心。
两重秦苑成千里，一炷胡香抵万金。
曼倩死来无绝艺，后人谁肯惜青禽。','','');